@dataclass
class QwenRuntime:
    model: Any
    processor: Any
    platform: str = QWEN_PLATFORM_TRANSFORMERS
    model_id: Optional[str] = None
    config: Optional[Any] = None

    def __iter__(self):
        yield self.model
        yield self.processor


def _clear_mlx_cache() -> None:
    if MLX_CORE is None:
        return
    try:
        MLX_CORE.clear_cache()
    except Exception:
        pass


def _qwen_mlx_post_generation_cleanup() -> None:
    """Release transient MLX buffers after a Qwen generation call."""

    try:
        gc.collect()
    except Exception:
        pass
    _clear_mlx_cache()


def _reset_qwen_runtime() -> None:
    global qwen_model, qwen_processor, qwen_last_error, loaded_qwen_model_id, qwen_device
    global qwen_runtime_platform, qwen_loaded_effective_model_id, qwen_runtime_config
    state = {
        "qwen_model": qwen_model,
        "qwen_processor": qwen_processor,
        "qwen_device": qwen_device,
        "loaded_qwen_model_id": loaded_qwen_model_id,
        "qwen_last_error": qwen_last_error,
    }
    _reset_qwen_runtime_impl(state=state, torch_module=torch)
    qwen_model = state["qwen_model"]
    qwen_processor = state["qwen_processor"]
    qwen_device = state["qwen_device"]
    loaded_qwen_model_id = state["loaded_qwen_model_id"]
    qwen_last_error = state["qwen_last_error"]
    qwen_runtime_platform = None
    qwen_loaded_effective_model_id = None
    qwen_runtime_config = None
    _clear_mlx_cache()


def _unload_sam3_text_runtime() -> None:
    """Release SAM3 text prompt model to free device memory."""
    global sam3_text_model, sam3_text_processor, sam3_text_device
    state = {
        "sam3_text_model": sam3_text_model,
        "sam3_text_processor": sam3_text_processor,
        "sam3_text_device": sam3_text_device,
    }
    _unload_sam3_text_runtime_impl(state=state, lock=sam3_text_lock)
    sam3_text_model = state["sam3_text_model"]
    sam3_text_processor = state["sam3_text_processor"]
    sam3_text_device = state["sam3_text_device"]


def _unload_dinov3_backbone() -> None:
    """Release DINOv3 encoder + per-device caches."""
    global dinov3_model, dinov3_processor, dinov3_model_name, dinov3_initialized, dinov3_model_device
    state = {
        "dinov3_model": dinov3_model,
        "dinov3_processor": dinov3_processor,
        "dinov3_model_name": dinov3_model_name,
        "dinov3_model_device": dinov3_model_device,
        "dinov3_initialized": dinov3_initialized,
    }
    _unload_dinov3_backbone_impl(
        state=state,
        lock=dinov3_lock,
        agent_backbones=_agent_dinov3_backbones,
        agent_locks=_agent_dinov3_locks,
    )
    dinov3_model = state["dinov3_model"]
    dinov3_processor = state["dinov3_processor"]
    dinov3_model_name = state["dinov3_model_name"]
    dinov3_model_device = state["dinov3_model_device"]
    dinov3_initialized = state["dinov3_initialized"]
    try:
        stop_mlx_dinov3_workers()
    except Exception as exc:  # noqa: BLE001
        logger.debug("Failed to stop MLX-DINOv3 workers during unload: %s", exc)


def _unload_cradio_backbone() -> None:
    """Release C-RADIOv4 encoder."""
    global cradio_model, cradio_processor, cradio_model_name, cradio_model_device, cradio_initialized
    with cradio_lock:
        cradio_model = None
        cradio_processor = None
        cradio_model_name = None
        cradio_model_device = None
        cradio_initialized = False
    try:
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass


def _load_dinov3_backbone(
    model_name: str,
    target_device: str,
    *,
    raise_on_error: bool = False,
) -> Tuple[Optional[Any], Optional[Any]]:
    try:
        model, processor = _clip_training_load_dinov3(model_name, target_device)
        return model, processor
    except Exception as exc:  # noqa: BLE001
        if raise_on_error:
            raise RuntimeError(str(exc)) from exc
        logger.warning(
            "Failed to load DINOv3 backbone '%s' on %s: %s", model_name, target_device, exc
        )
        return None, None


def _resolve_dinov3_runtime_device(model_name: str, requested_device: Optional[str] = None) -> str:
    resolved_model = str(model_name or CLASS_ANALYSIS_DEFAULT_DINOV3_MODEL).strip() or CLASS_ANALYSIS_DEFAULT_DINOV3_MODEL
    try:
        if resolve_mlx_dinov3_backend(resolved_model) == "mlx":
            return "mlx"
    except MlxDinoV3Unavailable:
        raise
    except Exception as exc:  # noqa: BLE001
        logger.debug("MLX-DINOv3 backend check failed for %s: %s", resolved_model, exc)
    return _dinov3_resolve_device_impl(
        requested_device or device,
        cuda_disabled=dinov3_cuda_disabled,
    )


def _load_cradio_backbone_cached(
    model_name: Optional[str],
    target_device: Optional[str],
    *,
    raise_on_error: bool = False,
) -> Tuple[Optional[Any], Optional[Any], str, str]:
    global cradio_model, cradio_processor, cradio_model_name, cradio_model_device, cradio_initialized
    resolved_model = normalize_cradio_model(model_name)
    resolved_device = target_device or resolve_cradio_torch_device(model_name=resolved_model)
    try:
        if (
            cradio_model is None
            or cradio_model_name != resolved_model
            or cradio_model_device != resolved_device
        ):
            with cradio_lock:
                if (
                    cradio_model is None
                    or cradio_model_name != resolved_model
                    or cradio_model_device != resolved_device
                ):
                    model_obj, processor_obj, loaded_model, loaded_device = load_cradio_backbone(
                        resolved_model,
                        resolved_device,
                    )
                    cradio_model = model_obj
                    cradio_processor = processor_obj
                    cradio_model_name = loaded_model
                    cradio_model_device = loaded_device
                    cradio_initialized = True
        return cradio_model, cradio_processor, cradio_model_name or resolved_model, cradio_model_device or resolved_device
    except Exception as exc:  # noqa: BLE001
        cradio_initialized = False
        if raise_on_error:
            raise RuntimeError(str(exc)) from exc
        logger.warning("Failed to load C-RADIOv4 backbone '%s' on %s: %s", resolved_model, resolved_device, exc)
        return None, None, resolved_model, resolved_device


