cradio_initialized = False
cradio_lock = threading.Lock()
_agent_dinov3_backbones: Dict[Tuple[str, str], Tuple[Any, Any]] = {}
_agent_dinov3_locks: Dict[Tuple[str, str], threading.Lock] = {}
_agent_dinov3_backbones_lock = threading.Lock()


def _suspend_clip_backbone() -> None:
    global clip_model, clip_preprocess, clip_initialized, _clip_reload_needed
    state = {
        "clip_model": clip_model,
        "clip_preprocess": clip_preprocess,
        "clip_initialized": clip_initialized,
        "_clip_reload_needed": _clip_reload_needed,
        "active_encoder_type": active_encoder_type,
    }
    _suspend_clip_backbone_impl(
        state=state,
        lock=clip_lock,
        agent_backbones=_agent_clip_backbones,
        agent_locks=_agent_clip_locks,
        logger=logger,
    )
    clip_model = state["clip_model"]
    clip_preprocess = state["clip_preprocess"]
    clip_initialized = state["clip_initialized"]
    _clip_reload_needed = state["_clip_reload_needed"]


def _resume_clip_backbone(target_model_name: Optional[str] = None) -> None:
    global clip_model, clip_preprocess, clip_initialized, clip_model_name, _clip_reload_needed
    if target_model_name:
        clip_model_name = str(target_model_name).strip() or clip_model_name
    state = {
        "clip_model": clip_model,
        "clip_preprocess": clip_preprocess,
        "clip_initialized": clip_initialized,
        "_clip_reload_needed": _clip_reload_needed,
        "clip_model_name": clip_model_name,
    }
    _resume_clip_backbone_impl(
        state=state,
        lock=clip_lock,
        clip_module=clip,
        device=device,
        default_model=DEFAULT_CLIP_MODEL,
        clf=clf,
        logger=logger,
    )
    clip_model = state["clip_model"]
    clip_preprocess = state["clip_preprocess"]
    clip_initialized = state["clip_initialized"]
    clip_model_name = state["clip_model_name"]
    _clip_reload_needed = state["_clip_reload_needed"]


def _resume_classifier_backbone() -> None:
    """Reload the active encoder backbone after training, based on user-selected classifier."""
    global dinov3_model, dinov3_processor, dinov3_model_name, dinov3_initialized, dinov3_model_device
    global cradio_model, cradio_processor, cradio_model_name, cradio_model_device, cradio_initialized
    global clip_model_name, _clip_reload_needed
    if str(active_encoder_type or "").strip().lower() == "cradio":
        model_name = normalize_cradio_model(active_encoder_model or CRADIO_DEFAULT_MODEL)
        try:
            target_device = resolve_cradio_torch_device(model_name=model_name)
            model_obj, processor_obj, resolved_model, resolved_device = _load_cradio_backbone_cached(
                model_name,
                target_device,
                raise_on_error=True,
            )
            with cradio_lock:
                cradio_model = model_obj
                cradio_processor = processor_obj
                cradio_model_name = resolved_model
                cradio_model_device = resolved_device
                cradio_initialized = _cradio_runtime_ready(
                    cradio_model,
                    cradio_processor,
                    cradio_model_device,
                )
        except RuntimeError as exc:
            with cradio_lock:
                cradio_model = None
                cradio_processor = None
                cradio_model_name = None
                cradio_model_device = None
                cradio_initialized = False
            logger.warning("Failed to reload C-RADIO backbone %s after training: %s", model_name, exc)
        _clip_reload_needed = False
        return
    state = {
        "dinov3_model": dinov3_model,
        "dinov3_processor": dinov3_processor,
        "dinov3_model_name": dinov3_model_name,
        "dinov3_model_device": dinov3_model_device,
        "dinov3_initialized": dinov3_initialized,
        "clip_model_name": clip_model_name,
        "_clip_reload_needed": _clip_reload_needed,
        "active_encoder_type": active_encoder_type,
        "active_encoder_model": active_encoder_model,
    }

    def _resume_clip_from_state() -> None:
        _resume_clip_backbone(state.get("clip_model_name"))
        state["_clip_reload_needed"] = _clip_reload_needed

    def _resolve_resume_dinov3_device(requested_device: str) -> str:
        return _resolve_dinov3_runtime_device(
            str(state.get("active_encoder_model") or ""),
            requested_device,
        )

    def _load_resume_dinov3(model_name: str, target_device: str) -> Tuple[Optional[Any], Optional[Any]]:
        try:
            model_obj, processor_obj, _resolved_model, _loaded_device = _data_ingestion_get_dinov3(
                model_name,
                target_device,
            )
            return model_obj, processor_obj
        except Exception as exc:  # noqa: BLE001
            logger.warning("Failed to reload DINOv3 backbone %s after training: %s", model_name, exc)
            return None, None

    _resume_classifier_backbone_impl(
        state=state,
        device=device,
        dinov3_lock=dinov3_lock,
        dinov3_cuda_disabled=dinov3_cuda_disabled,
        dinov3_resolve_device_fn=_resolve_resume_dinov3_device,
        load_dinov3_fn=_load_resume_dinov3,
        resume_clip_fn=_resume_clip_from_state,
    )
    dinov3_model = state["dinov3_model"]
    dinov3_processor = state["dinov3_processor"]
    dinov3_model_name = state["dinov3_model_name"]
    dinov3_model_device = state["dinov3_model_device"]
    dinov3_initialized = state["dinov3_initialized"]
    clip_model_name = state["clip_model_name"]
    _clip_reload_needed = state["_clip_reload_needed"]


