def _configured_cors_origins() -> Tuple[List[str], Optional[str]]:
    """Keep the same-origin app closed by default, with explicit dev opt-ins."""

    raw = str(os.environ.get("CORS_ALLOW_ORIGINS") or "").strip()
    if raw == "*":
        logger.warning(
            "CORS_ALLOW_ORIGINS=* permits every browser origin. Do not use "
            "this setting when the backend is shared over a network."
        )
        return ["*"], None
    origins = [
        item.strip().rstrip("/")
        for item in raw.split(",")
        if item.strip()
    ]
    # The separately served development UI is documented and remains usable
    # on any local port. Tailscale Serve is same-origin and needs no CORS rule.
    loopback_regex = (
        r"^https?://(?:localhost|127\.0\.0\.1|\[::1\])(?::[0-9]{1,5})?$"
    )
    return list(dict.fromkeys(origins)), loopback_regex


_cors_origins, _cors_origin_regex = _configured_cors_origins()
app.add_middleware(
    CORSMiddleware,
    allow_origins=_cors_origins,
    allow_origin_regex=_cors_origin_regex,
    allow_methods=["*"],
    allow_headers=["*"],
)

