@dataclass
class ClassAnalysisJob:
    job_id: str
    status: str = "queued"
    progress: float = 0.0
    message: str = "Queued"
    request: Dict[str, Any] = field(default_factory=dict)
    logs: List[Dict[str, Any]] = field(default_factory=list)
    result: Optional[Dict[str, Any]] = None
    summary: Dict[str, Any] = field(default_factory=dict)
    result_path: Optional[str] = None
    thumbnail_dir: Optional[str] = None
    thumbnail_metadata_lock: threading.Lock = field(
        default_factory=threading.Lock,
        repr=False,
    )
    runtime: Dict[str, Any] = field(default_factory=dict)
    stage: str = ""
    stage_index: int = 0
    stage_count: int = 0
    stage_processed: int = 0
    stage_total: int = 0
    phase_id: str = ""
    phase_label: str = ""
    phase_detail: str = ""
    phase_completed_units: int = 0
    phase_total_units: int = 0
    active_component: str = ""
    progress_phases: List[Dict[str, Any]] = field(default_factory=list)
    cache_status: Dict[str, Any] = field(default_factory=dict)
    error: Optional[str] = None
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)
    cancel_event: threading.Event = field(default_factory=threading.Event)
    # Private ownership hook used only while Stage 2 is producing its work
    # memmaps. It is deliberately omitted from API serialization so failure or
    # cancellation can close mappings deterministically before cleanup.
    _refinement_sidecar_accumulator: Any = field(
        default=None,
        repr=False,
        compare=False,
    )
    _memory_baseline: Dict[str, int] = field(
        default_factory=dict,
        repr=False,
        compare=False,
    )
    _memory_peak_combined_rss_bytes: int = field(
        default=0,
        repr=False,
        compare=False,
    )
    # Exact terminal artifact identity retained for fail-closed reads after
    # publication/restart.  It is intentionally private and omitted from the
    # API payload; callers should never be able to supply or mutate it.
    _artifact_binding: Dict[str, Any] = field(
        default_factory=dict,
        repr=False,
        compare=False,
    )


