def _class_analysis_cache_active_users() -> List[Dict[str, str]]:
    terminal = {"completed", "failed", "cancelled"}
    active: List[Dict[str, str]] = []
    registries = (
        ("analysis", CLASS_ANALYSIS_JOBS, CLASS_ANALYSIS_JOBS_LOCK),
        (
            "cluster_search",
            CLASS_ANALYSIS_CLUSTER_JOBS,
            CLASS_ANALYSIS_CLUSTER_JOBS_LOCK,
        ),
        (
            "vlm_review",
            CLASS_ANALYSIS_QWEN_REVIEW_JOBS,
            CLASS_ANALYSIS_QWEN_REVIEW_JOBS_LOCK,
        ),
    )
    for kind, registry, lock in registries:
        with lock:
            for key, job in registry.items():
                status = str(
                    getattr(job, "status", "") or ""
                ).strip().lower()
                if status not in terminal:
                    active.append(
                        {
                            "kind": kind,
                            "job_id": str(
                                getattr(job, "job_id", key) or key
                            ),
                            "status": status or "unknown",
                        }
                    )
    with _CLASS_ANALYSIS_EVIDENCE_WORKERS_LOCK:
        for job_id, worker in _CLASS_ANALYSIS_EVIDENCE_WORKERS.items():
            if worker.is_alive():
                active.append(
                    {
                        "kind": "spatial_evidence",
                        "job_id": str(job_id),
                        "status": "running",
                    }
                )
    return sorted(active, key=lambda row: (row["kind"], row["job_id"]))


def get_class_analysis_cache_status() -> Dict[str, Any]:
    with CLASS_ANALYSIS_STORAGE_POLICY_LOCK:
        budget = int(CLASS_ANALYSIS_CACHE_MAX_BYTES)
    cache = _class_analysis_cache_inventory(
        CLASS_ANALYSIS_CACHE_ROOT,
        max_bytes=budget,
        active_users=_class_analysis_cache_active_users(),
    )
    active_job_ids = {
        str(row.get("job_id") or "")
        for row in _class_analysis_cache_active_users()
    }
    try:
        latest = _latest_class_analysis_session(CLASS_ANALYSIS_ROOT)
    except ClassAnalysisSessionManifestError:
        latest = None
    latest_job_id = str((latest or {}).get("job_id") or "")
    pinned_ids = {job_id for job_id in {*active_job_ids, latest_job_id} if job_id}
    sessions = recoverable_session_inventory(
        CLASS_ANALYSIS_ROOT,
        pinned_job_ids=pinned_ids,
    )
    generated_total = int(cache.get("total_bytes") or 0) + int(sessions["total_bytes"])
    return {
        **cache,
        "max_bytes": budget,
        "generated_total_bytes": generated_total,
        "generated_usage_fraction": generated_total / budget if budget > 0 else None,
        "over_budget_bytes": max(0, generated_total - budget),
        "cache_bytes": int(cache.get("total_bytes") or 0),
        "recoverable_session_bytes": int(sessions["total_bytes"]),
        "recoverable_session_count": int(sessions["session_count"]),
        "pinned_session_bytes": int(sessions["pinned_bytes"]),
        "evictable_session_bytes": int(sessions["evictable_bytes"]),
        "pinned_job_ids": sorted(pinned_ids),
        "budget_scope": ["regenerable_cache", "recoverable_sessions"],
    }


def set_class_analysis_cache_budget(payload: Dict[str, Any]) -> Dict[str, Any]:
    raw_gib = payload.get("max_gib") if isinstance(payload, dict) else None
    if isinstance(raw_gib, bool):
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="class_analysis_storage_budget_invalid")
    try:
        max_bytes = int(round(float(raw_gib) * 1024**3))
        write_generated_data_budget(CLASS_ANALYSIS_STORAGE_POLICY_PATH, max_bytes)
    except (TypeError, ValueError, OverflowError, ClassAnalysisStoragePolicyError) as exc:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail=str(exc)) from exc
    global CLASS_ANALYSIS_CACHE_MAX_BYTES
    with CLASS_ANALYSIS_STORAGE_POLICY_LOCK:
        CLASS_ANALYSIS_CACHE_MAX_BYTES = max_bytes
    threading.Thread(
        target=_class_analysis_enforce_cache_budget,
        name="class-analysis-storage-budget",
        daemon=True,
    ).start()
    return {
        "status": "updated",
        "max_bytes": max_bytes,
        "max_gib": max_bytes / 1024**3,
        "enforcement": "scheduled",
    }


def purge_class_analysis_cache(payload: Dict[str, Any]) -> Dict[str, Any]:
    raw_categories = (
        payload.get("categories") if isinstance(payload, dict) else None
    )
    categories = raw_categories if isinstance(raw_categories, list) else None
    try:
        return _class_analysis_purge_cache(
            CLASS_ANALYSIS_CACHE_ROOT,
            categories=categories,
            max_bytes=int(CLASS_ANALYSIS_CACHE_MAX_BYTES),
            active_users_fn=_class_analysis_cache_active_users,
        )
    except ClassAnalysisCacheBusyError as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "class_analysis_cache_busy",
                "message": (
                    "Wait for active Data Quality Explorer jobs before "
                    "clearing caches."
                ),
                "active_users": exc.active_users,
            },
        ) from exc
    except (
        ClassAnalysisCacheRootUnsafeError,
        ClassAnalysisCacheAdminError,
    ) as exc:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail={
                "code": "class_analysis_cache_request_invalid",
                "message": str(exc),
            },
        ) from exc


def get_latest_class_analysis_session() -> Dict[str, Any]:
    try:
        manifest = _latest_class_analysis_session(CLASS_ANALYSIS_ROOT)
    except ClassAnalysisSessionManifestError as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=str(exc),
        ) from exc
    return {
        "status": "available" if manifest is not None else "none",
        "session": manifest,
    }


def get_class_analysis_session_manifest(job_id: str) -> Dict[str, Any]:
    try:
        manifest = _read_class_analysis_session_manifest(
            CLASS_ANALYSIS_ROOT,
            job_id,
        )
        store_path = _class_analysis_session_store_path(job_id)
        if store_path.exists():
            progress = class_analysis_evidence_progress(store_path)
            completed = int(progress.get("completed") or 0)
            pending = int(progress.get("pending") or 0)
            processing = int(progress.get("processing") or 0)
            failed = int(progress.get("failed") or 0)
            total = int(
                progress.get("total")
                or completed + pending + processing + failed
            )
            prior = (
                dict(manifest.get("evidence") or {})
                if isinstance(manifest.get("evidence"), Mapping)
                else {}
            )
            prior.update(
                {
                    "schema": "class-analysis-evidence-progress-v1",
                    "status": (
                        "running"
                        if pending + processing
                        else "partial_failed"
                        if failed
                        else "completed"
                    ),
                    "processed": completed,
                    "total": total,
                    "pending": pending,
                    "processing": processing,
                    "failed": failed,
                }
            )
            manifest["evidence"] = prior
            if pending + processing:
                _class_analysis_start_evidence_worker(job_id)
        return manifest
    except ClassAnalysisSessionManifestError as exc:
        detail = str(exc)
        status_code = (
            HTTP_404_NOT_FOUND if detail.endswith("not_found") else HTTP_409_CONFLICT
        )
        raise HTTPException(status_code=status_code, detail=detail) from exc


def _class_analysis_session_store_path(job_id: str) -> Path:
    identifier = str(job_id or "").strip()
    if not re.fullmatch(r"ca_[A-Za-z0-9]+", identifier):
        raise HTTPException(status_code=400, detail="class_analysis_job_id_invalid")
    root = CLASS_ANALYSIS_ROOT.resolve()
    path = (root / identifier / CLASS_ANALYSIS_SESSION_STORE_FILENAME).resolve()
    if root not in path.parents:
        raise HTTPException(status_code=400, detail="class_analysis_job_id_invalid")
    return path


def _class_analysis_session_store_call(callback: Callable[..., Any], *args, **kwargs):
    try:
        return callback(*args, **kwargs)
    except SessionStoreError as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.detail) from exc


_CLASS_ANALYSIS_SESSION_REVIEW_PROJECTION_LOCK = threading.Lock()
_CLASS_ANALYSIS_SESSION_REVIEW_PROJECTION_TOKENS: Dict[str, str] = {}


def _class_analysis_review_ledger_projection_token(
    ledger_root: Optional[Path],
) -> str:
    """Cheap cross-process change token for the atomic receipt shards."""

    digest = hashlib.sha256()
    if ledger_root is None:
        digest.update(b"missing")
        return digest.hexdigest()
    for shard_path in sorted(ledger_root.glob("*.json")):
        if re.fullmatch(r"[0-9a-f]{2}", shard_path.stem) is None:
            continue
        try:
            stat = shard_path.stat()
        except FileNotFoundError:
            continue
        digest.update(shard_path.name.encode("ascii"))
        digest.update(str(int(stat.st_size)).encode("ascii"))
        digest.update(str(int(stat.st_mtime_ns)).encode("ascii"))
    return digest.hexdigest()


def _class_analysis_review_projection_entry_order(
    entry: Mapping[str, Any],
) -> Tuple[float, str, str, str]:
    """Order numeric receipt timestamps chronologically, not lexically."""

    raw_updated_at = str(entry.get("updated_at") or "").strip()
    try:
        updated_at = float(raw_updated_at)
    except (TypeError, ValueError):
        updated_at = 0.0
    if not math.isfinite(updated_at):
        updated_at = 0.0
    return (
        updated_at,
        raw_updated_at,
        str(entry.get("review_object_key") or ""),
        str(entry.get("point_id") or ""),
    )


def _class_analysis_sync_review_receipt_to_session(
    job_id: str,
    point_id: str,
    receipt: Mapping[str, Any],
) -> bool:
    """Best-effort projection; the append-only receipt remains authoritative."""

    safe_job_id = str(job_id or "").strip()
    with _CLASS_ANALYSIS_SESSION_REVIEW_PROJECTION_LOCK:
        _CLASS_ANALYSIS_SESSION_REVIEW_PROJECTION_TOKENS.pop(safe_job_id, None)
    try:
        store_path = _class_analysis_session_store_path(safe_job_id)
        if not store_path.is_file():
            return False
        disposition = str(receipt.get("disposition") or "").strip().lower()
        if disposition == "clear":
            clear_class_analysis_review_state(
                store_path,
                point_id=point_id,
                review_object_key=str(receipt.get("review_object_key") or ""),
            )
        elif disposition:
            upsert_class_analysis_review_state(
                store_path,
                point_id=point_id,
                disposition=disposition,
                revision=receipt.get("human_review_revision")
                or receipt.get("entry_revision"),
                reviewed_at=receipt.get("human_reviewed_at")
                or receipt.get("updated_at"),
                payload=receipt,
            )
        # Keep the ledger token invalid. Another process may have committed a
        # different receipt between this point projection and token sampling;
        # the next read must perform the complete authoritative reconciliation.
        return True
    except Exception:
        logger.exception(
            "Could not project review receipt into session %s/%s",
            safe_job_id,
            point_id,
        )
        return False


def _class_analysis_ensure_session_review_projection(job_id: str) -> None:
    safe_job_id = str(job_id or "").strip()
    if not safe_job_id:
        return
    ledger_root = _class_analysis_review_disposition_root(
        create=False,
        strict=True,
    )
    token = _class_analysis_review_ledger_projection_token(ledger_root)
    if _CLASS_ANALYSIS_SESSION_REVIEW_PROJECTION_TOKENS.get(safe_job_id) == token:
        return
    with _CLASS_ANALYSIS_SESSION_REVIEW_PROJECTION_LOCK:
        ledger_root = _class_analysis_review_disposition_root(
            create=False,
            strict=True,
        )
        token = _class_analysis_review_ledger_projection_token(ledger_root)
        if _CLASS_ANALYSIS_SESSION_REVIEW_PROJECTION_TOKENS.get(safe_job_id) == token:
            return
        store_path = _class_analysis_session_store_path(safe_job_id)
        if not store_path.is_file():
            return
        ensure_class_analysis_session_store_validated(store_path)
        for _attempt in range(3):
            token_before = _class_analysis_review_ledger_projection_token(
                ledger_root
            )
            entries: List[Dict[str, Any]] = []
            if ledger_root is not None:
                for shard_path in sorted(ledger_root.glob("*.json")):
                    shard_id = shard_path.stem
                    if re.fullmatch(r"[0-9a-f]{2}", shard_id) is None:
                        continue
                    lock = CLASS_ANALYSIS_REVIEW_DISPOSITION_LOCKS[
                        int(shard_id, 16)
                    ]
                    with lock:
                        payload = _class_analysis_load_review_disposition_shard(
                            ledger_root,
                            shard_id,
                            strict=True,
                        )
                    for entry in (payload.get("entries") or {}).values():
                        if not isinstance(entry, Mapping):
                            continue
                        review_key = str(
                            entry.get("review_object_key") or ""
                        ).strip()
                        point_id = str(entry.get("point_id") or "").strip()
                        if not point_id and not review_key:
                            continue
                        disposition = str(
                            entry.get("disposition") or ""
                        ).strip().lower()
                        if (
                            disposition == "reassign_class"
                            and str(entry.get("analysis_job_id") or "").strip()
                                != safe_job_id
                        ):
                            # Reassignments are deliberately scoped to the
                            # frozen analysis that proposed them. Their ledger
                            # key is job-specific, while the normalized store
                            # binds the original source-object key.
                            continue
                        if (
                            not review_key
                            and str(entry.get("analysis_job_id") or "")
                                != safe_job_id
                        ):
                            continue
                        entries.append(dict(entry))
                    tombstones = payload.get("tombstones")
                    if isinstance(tombstones, Mapping):
                        for tombstone in tombstones.values():
                            if not isinstance(tombstone, Mapping):
                                continue
                            review_key = str(
                                tombstone.get("review_object_key") or ""
                            ).strip()
                            if not review_key:
                                continue
                            # History deletion and revision-safe clear remove
                            # the live entry. Preserve that authoritative
                            # absence as an explicit projection row so the
                            # session's immutable build-time reviewed bit
                            # cannot resurrect the deleted decision.
                            entries.append(
                                {
                                    "point_id": "",
                                    "review_object_key": review_key,
                                    "disposition": "clear",
                                    "entry_revision": str(
                                        tombstone.get("entry_revision") or ""
                                    ),
                                    "updated_at": tombstone.get("deleted_at") or 0,
                                    "tombstone": dict(tombstone),
                                }
                            )
            token_after = _class_analysis_review_ledger_projection_token(
                ledger_root
            )
            if token_before != token_after:
                continue
            entries.sort(key=_class_analysis_review_projection_entry_order)
            replace_class_analysis_review_state(store_path, entries)
            _CLASS_ANALYSIS_SESSION_REVIEW_PROJECTION_TOKENS[
                safe_job_id
            ] = token_after
            return
        raise HTTPException(
            status_code=503,
            detail="class_analysis_review_projection_changed_during_reconciliation",
        )


def get_class_analysis_session_graph(job_id: str, **filters) -> Dict[str, Any]:
    _class_analysis_ensure_session_review_projection(job_id)
    return _class_analysis_session_store_call(
        get_class_analysis_graph_payload,
        _class_analysis_session_store_path(job_id),
        **filters,
    )


def get_class_analysis_session_review_queue(job_id: str, **pagination) -> Dict[str, Any]:
    _class_analysis_ensure_session_review_projection(job_id)
    try:
        requested_limit = max(1, min(100, int(pagination.get("limit") or 36)))
    except (TypeError, ValueError):
        requested_limit = 36
    job = _get_class_analysis_job(job_id)
    store_path = _class_analysis_session_store_path(job_id)
    visible: List[Dict[str, Any]] = []
    payload: Dict[str, Any] = {}
    next_cursor = pagination.get("cursor")
    for _page_index in range(8):
        page_params = dict(pagination)
        page_params["limit"] = max(1, requested_limit - len(visible))
        page_params["cursor"] = next_cursor
        page = _class_analysis_session_store_call(
            get_class_analysis_review_queue_payload,
            store_path,
            **page_params,
        )
        if not payload:
            payload = dict(page)
        items = [
            dict(item)
            for item in (page.get("items") or [])
            if isinstance(item, Mapping)
        ]
        if not items:
            next_cursor = page.get("next_cursor")
            break
        overlay = _class_analysis_apply_review_dispositions(
            {
                "summary": {"analysis_job_id": str(job.job_id or job_id)},
                "points": items,
                "wrong_class_candidates": items,
            },
            job=job,
            point_review_keys=_class_analysis_point_review_keys(items),
        )
        visible.extend(
            dict(item)
            for item in (overlay.get("wrong_class_candidates") or [])
            if isinstance(item, Mapping)
        )
        next_cursor = page.get("next_cursor")
        if len(visible) >= requested_limit or not next_cursor:
            break
    payload["items"] = visible[:requested_limit]
    payload["returned"] = len(payload["items"])
    payload["next_cursor"] = next_cursor
    return payload


def get_class_analysis_session_review_history(
    job_id: str,
    **options,
) -> Dict[str, Any]:
    _class_analysis_ensure_session_review_projection(job_id)
    return _class_analysis_session_store_call(
        get_class_analysis_review_history_payload,
        _class_analysis_session_store_path(job_id),
        **options,
    )


def get_class_analysis_session_point_detail(job_id: str, point_id: str) -> Dict[str, Any]:
    payload = _class_analysis_session_store_call(
        get_class_analysis_point_detail_payload,
        _class_analysis_session_store_path(job_id),
        point_id,
    )
    point = payload.get("point")
    if isinstance(point, dict):
        job = _get_class_analysis_job(job_id)
        review_keys = _class_analysis_disposition_keys_for_row(
            point,
            str(job.job_id or job_id),
        )
        review_entries = _class_analysis_lookup_review_dispositions(review_keys)
        receipt = next(
            (
                review_entries[key]
                for key in review_keys
                if key in review_entries
            ),
            None,
        )
        payload["review_receipt"] = (
            {
                "disposition": str(receipt.get("disposition") or ""),
                "human_reviewed_at": receipt.get("updated_at"),
                "human_review_revision": str(receipt.get("entry_revision") or ""),
                "origin": str(receipt.get("origin") or ""),
                "client_action_id": str(receipt.get("client_action_id") or ""),
            }
            if isinstance(receipt, Mapping)
            else None
        )
        overlay = _class_analysis_apply_review_dispositions(
            {
                "summary": {"analysis_job_id": str(job.job_id or job_id)},
                "points": [point],
            },
            job=job,
            point_review_keys=_class_analysis_point_review_keys([point]),
        )
        points = overlay.get("points") or []
        if points:
            payload["point"] = points[0]
    return payload


def get_class_analysis_session_point_evidence(job_id: str, point_id: str) -> Dict[str, Any]:
    return _class_analysis_session_store_call(
        get_class_analysis_point_evidence_payload,
        _class_analysis_session_store_path(job_id),
        point_id,
    )


def _class_analysis_publish_session_manifest(
    job: "ClassAnalysisJob",
    out_dir: Path,
    completion_state: Mapping[str, Any],
    result: Mapping[str, Any],
) -> None:
    summary = result.get("summary") if isinstance(result, Mapping) else {}
    summary = summary if isinstance(summary, Mapping) else {}
    manifest = _build_class_analysis_session_manifest(
        job_id=job.job_id,
        status=str(completion_state.get("status") or ""),
        summary=summary,
        request=job.request if isinstance(job.request, Mapping) else {},
        state=completion_state,
        created_at=float(job.created_at or time.time()),
        updated_at=float(completion_state.get("updated_at") or time.time()),
    )
    store_path = out_dir / CLASS_ANALYSIS_SESSION_STORE_FILENAME
    if store_path.exists():
        try:
            evidence_progress = class_analysis_evidence_progress(store_path)
            evidence_completed = int(evidence_progress.get("completed") or 0)
            evidence_pending = int(evidence_progress.get("pending") or 0)
            evidence_processing = int(evidence_progress.get("processing") or 0)
            evidence_failed = int(evidence_progress.get("failed") or 0)
            evidence_total = int(
                evidence_progress.get("total")
                or evidence_completed
                + evidence_pending
                + evidence_processing
                + evidence_failed
            )
            manifest["evidence"] = {
                "schema": "class-analysis-evidence-progress-v1",
                "status": (
                    "running"
                    if evidence_pending + evidence_processing
                    else "partial_failed"
                    if evidence_failed
                    else "completed"
                ),
                "processed": evidence_completed,
                "total": evidence_total,
                "pending": evidence_pending,
                "processing": evidence_processing,
                "failed": evidence_failed,
                "cache_hits": 0,
                "objects_per_second": 0.0,
                "eta_seconds": None,
                "backend": "DINOv3 TokenCut",
                "last_error": "",
                "updated_at": time.time(),
            }
        except Exception:
            logger.exception(
                "Failed to initialize spatial-evidence progress for %s",
                job.job_id,
            )
    _write_class_analysis_session_manifest(
        CLASS_ANALYSIS_ROOT,
        manifest,
        publish_latest=(manifest.get("status") == "completed"),
    )


