def _caption_instruction_bundle_safe_relpath(value: Any, *, detail: str) -> str:
    raw = str(value or "").strip().replace("\\", "/")
    raw = re.sub(r"/+", "/", raw)
    while raw.startswith("./"):
        raw = raw[2:]
    parts = [part for part in raw.split("/") if part and part != "."]
    if not parts or any(part == ".." for part in parts):
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail=detail)
    return "/".join(parts)


def _caption_instruction_bundle_asset_path(
    image_path: Any,
    split: Any,
    *,
    root: str,
) -> str:
    safe = _caption_instruction_bundle_safe_relpath(
        image_path,
        detail="caption_instruction_bundle_image_path_invalid",
    )
    split_norm = _annotation_normalise_split(split) if str(split or "").strip() else ""
    if split_norm and not safe.startswith(f"{split_norm}/"):
        safe = f"{split_norm}/{safe}"
    return f"{root}/{safe}"


def _caption_instruction_bundle_label_path(image_path: Any, split: Any) -> str:
    image_asset = _caption_instruction_bundle_asset_path(image_path, split, root="labels")
    label_path = Path(image_asset)
    return str(label_path.with_suffix(".txt").as_posix())


def _caption_instruction_file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _caption_instruction_bytes_sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _caption_instruction_validate_bundle_manifest(zip_path: Path) -> None:
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            name_list = zf.namelist()
            names = set(name_list)
            if len(name_list) != len(names):
                raise ValueError("manifest_zip_duplicate_member")
            manifest_bytes = zf.read(CAPTION_INSTRUCTION_BUNDLE_MANIFEST_PATH)
            manifest = json.loads(manifest_bytes.decode("utf-8"))
            if not isinstance(manifest, Mapping):
                raise ValueError("manifest_not_object")
            if str(manifest.get("format") or "").strip() != CAPTION_INSTRUCTION_BUNDLE_MANIFEST_FORMAT:
                raise ValueError("manifest_format_invalid")
            manifest_path = str(manifest.get("manifest_path") or "").strip()
            if manifest_path != CAPTION_INSTRUCTION_BUNDLE_MANIFEST_PATH:
                raise ValueError("manifest_path_invalid")
            if str(manifest.get("checksum_scope") or "").strip() != CAPTION_INSTRUCTION_BUNDLE_CHECKSUM_SCOPE:
                raise ValueError("manifest_checksum_scope_invalid")
            file_entries = manifest.get("files")
            if not isinstance(file_entries, list):
                raise ValueError("manifest_files_invalid")
            entries_by_path: Dict[str, Mapping[str, Any]] = {}
            for entry in file_entries:
                if not isinstance(entry, Mapping):
                    raise ValueError("manifest_file_entry_invalid")
                path = str(entry.get("path") or "").strip()
                if not path or path == CAPTION_INSTRUCTION_BUNDLE_MANIFEST_PATH or path in entries_by_path:
                    raise ValueError("manifest_file_path_invalid")
                entries_by_path[path] = entry
            expected_paths = names - {CAPTION_INSTRUCTION_BUNDLE_MANIFEST_PATH}
            if set(entries_by_path) != expected_paths:
                raise ValueError("manifest_file_set_mismatch")
            raw_file_count = manifest.get("file_count")
            if isinstance(raw_file_count, bool):
                raise ValueError("manifest_file_count_invalid")
            try:
                manifest_file_count = int(raw_file_count)
            except (TypeError, ValueError) as exc:
                raise ValueError("manifest_file_count_invalid") from exc
            if manifest_file_count < 0 or manifest_file_count != len(entries_by_path):
                raise ValueError("manifest_file_count_mismatch")
            member_bytes: Dict[str, bytes] = {}
            for path, entry in entries_by_path.items():
                data = zf.read(path)
                member_bytes[path] = data
                raw_entry_bytes = entry.get("bytes")
                if isinstance(raw_entry_bytes, bool):
                    raise ValueError(f"manifest_file_bytes_invalid:{path}")
                try:
                    expected_bytes = int(raw_entry_bytes)
                except (TypeError, ValueError) as exc:
                    raise ValueError(f"manifest_file_bytes_invalid:{path}") from exc
                if expected_bytes < 0:
                    raise ValueError(f"manifest_file_bytes_invalid:{path}")
                if expected_bytes != len(data):
                    raise ValueError(f"manifest_file_bytes_mismatch:{path}")
                if str(entry.get("sha256") or "").strip() != _caption_instruction_bytes_sha256(data):
                    raise ValueError(f"manifest_file_sha256_mismatch:{path}")

            def _manifest_member_path(value: Any, *, detail: str) -> str:
                path_value = str(value or "").strip().replace("\\", "/")
                parts = path_value.split("/")
                if (
                    not path_value
                    or path_value == CAPTION_INSTRUCTION_BUNDLE_MANIFEST_PATH
                    or path_value.startswith("/")
                    or any(part in ("", ".", "..") for part in parts)
                ):
                    raise ValueError(detail)
                return path_value

            def _manifest_nonnegative_int(mapping: Mapping[str, Any], key: str, *, detail: str) -> int:
                raw_value = mapping.get(key)
                if isinstance(raw_value, bool):
                    raise ValueError(f"{detail}:{key}")
                try:
                    value = int(raw_value)
                except (TypeError, ValueError) as exc:
                    raise ValueError(f"{detail}:{key}") from exc
                if value < 0:
                    raise ValueError(f"{detail}:{key}")
                return value

            def _read_jsonl_rows(path: str) -> List[Mapping[str, Any]]:
                rows: List[Mapping[str, Any]] = []
                for row_number, line in enumerate(member_bytes[path].decode("utf-8").splitlines(), start=1):
                    if not line.strip():
                        continue
                    row = json.loads(line)
                    if not isinstance(row, Mapping):
                        raise ValueError(f"manifest_jsonl_row_invalid:{path}:{row_number}")
                    rows.append(row)
                return rows

            def _read_json_object(path: str) -> Mapping[str, Any]:
                payload = json.loads(member_bytes[path].decode("utf-8"))
                if not isinstance(payload, Mapping):
                    raise ValueError(f"manifest_json_invalid:{path}")
                return payload

            def _entry_role(path: str) -> str:
                return str(entries_by_path.get(path, {}).get("role") or "").strip()

            def _require_role(path: str, role: str) -> None:
                if path not in entries_by_path:
                    raise ValueError(f"manifest_artifact_file_missing:{path}")
                if _entry_role(path) != role:
                    raise ValueError(f"manifest_file_role_mismatch:{path}")

            artifacts = manifest.get("artifacts")
            if not isinstance(artifacts, Mapping):
                raise ValueError("manifest_artifacts_invalid")
            expected_artifacts = {
                "training_jsonl": ("caption_instruction_training.jsonl", "training_rows"),
                "archive_jsonl": ("caption_instruction_archive.jsonl", "archive_rows"),
                "review_jsonl": ("caption_instruction_review.jsonl", "review_rows"),
                "report_json": ("caption_instruction_report.json", "report"),
            }
            artifact_paths: Dict[str, str] = {}
            for key, (expected_path, role) in expected_artifacts.items():
                artifact_path = _manifest_member_path(
                    artifacts.get(key),
                    detail=f"manifest_artifact_path_invalid:{key}",
                )
                if artifact_path != expected_path:
                    raise ValueError(f"manifest_artifact_path_invalid:{key}")
                _require_role(artifact_path, role)
                artifact_paths[key] = artifact_path
            if "labelmap.txt" not in entries_by_path:
                raise ValueError("manifest_labelmap_missing")
            if _entry_role("labelmap.txt") != "labelmap":
                raise ValueError("manifest_file_role_mismatch:labelmap.txt")

            training_rows = _read_jsonl_rows(artifact_paths["training_jsonl"])
            archive_rows = _read_jsonl_rows(artifact_paths["archive_jsonl"])
            review_rows = _read_jsonl_rows(artifact_paths["review_jsonl"])
            report = _read_json_object(artifact_paths["report_json"])
            training_validation = _caption_instruction_validate_training_rows(training_rows)
            if not training_validation.get("ok"):
                raise ValueError(
                    "manifest_training_rows_invalid:"
                    + str((training_validation.get("errors") or ["unknown"])[0])
                )

            row_counts = manifest.get("row_counts")
            if not isinstance(row_counts, Mapping):
                raise ValueError("manifest_row_counts_invalid")
            expected_counts = {
                "training_rows": _manifest_nonnegative_int(
                    row_counts,
                    "training_rows",
                    detail="manifest_row_count_invalid",
                ),
                "archive_rows": _manifest_nonnegative_int(
                    row_counts,
                    "archive_rows",
                    detail="manifest_row_count_invalid",
                ),
                "review_rows": _manifest_nonnegative_int(
                    row_counts,
                    "review_rows",
                    detail="manifest_row_count_invalid",
                ),
                "images": _manifest_nonnegative_int(row_counts, "images", detail="manifest_row_count_invalid"),
                "labels": _manifest_nonnegative_int(row_counts, "labels", detail="manifest_row_count_invalid"),
            }
            if expected_counts["training_rows"] != len(training_rows):
                raise ValueError("manifest_row_count_mismatch:training_rows")
            if expected_counts["archive_rows"] != len(archive_rows):
                raise ValueError("manifest_row_count_mismatch:archive_rows")
            if expected_counts["review_rows"] != len(review_rows):
                raise ValueError("manifest_row_count_mismatch:review_rows")

            role_counts = Counter(_entry_role(path) for path in entries_by_path)
            if role_counts.get("image", 0) != expected_counts["images"]:
                raise ValueError("manifest_role_count_mismatch:images")
            if role_counts.get("label", 0) != expected_counts["labels"]:
                raise ValueError("manifest_role_count_mismatch:labels")

            def _validate_assets(
                raw_assets: Any,
                *,
                count_key: str,
                path_field: str,
                expected_role: str,
                path_prefix: str,
                error_prefix: str,
            ) -> Set[str]:
                if not isinstance(raw_assets, list):
                    raise ValueError(f"{error_prefix}_entries_invalid")
                if len(raw_assets) != expected_counts[count_key]:
                    raise ValueError(f"manifest_row_count_mismatch:{count_key}")
                asset_paths: Set[str] = set()
                for asset in raw_assets:
                    if not isinstance(asset, Mapping):
                        raise ValueError(f"{error_prefix}_entry_invalid")
                    path = _manifest_member_path(
                        asset.get(path_field),
                        detail=f"{error_prefix}_path_invalid",
                    )
                    if not path.startswith(path_prefix):
                        raise ValueError(f"{error_prefix}_path_invalid:{path}")
                    if path in asset_paths:
                        raise ValueError(f"{error_prefix}_path_duplicate:{path}")
                    asset_paths.add(path)
                    if path not in entries_by_path:
                        raise ValueError(f"{error_prefix}_file_missing:{path}")
                    if _entry_role(path) != expected_role:
                        raise ValueError(f"manifest_file_role_mismatch:{path}")
                    data = member_bytes[path]
                    expected_asset_bytes = _manifest_nonnegative_int(
                        asset,
                        "bytes",
                        detail=f"{error_prefix}_bytes_invalid",
                    )
                    if expected_asset_bytes != len(data):
                        raise ValueError(f"{error_prefix}_bytes_mismatch:{path}")
                    if str(asset.get("sha256") or "").strip() != _caption_instruction_bytes_sha256(data):
                        raise ValueError(f"{error_prefix}_sha256_mismatch:{path}")
                role_paths = {path for path, entry in entries_by_path.items() if str(entry.get("role") or "") == expected_role}
                if asset_paths != role_paths:
                    raise ValueError(f"{error_prefix}_file_set_mismatch")
                return asset_paths

            _validate_assets(
                manifest.get("images"),
                count_key="images",
                path_field="bundle_image_path",
                expected_role="image",
                path_prefix="images/",
                error_prefix="manifest_image",
            )
            _validate_assets(
                manifest.get("labels"),
                count_key="labels",
                path_field="bundle_label_path",
                expected_role="label",
                path_prefix="labels/",
                error_prefix="manifest_label",
            )
            consistency_validation = _caption_instruction_artifact_consistency_validation(
                training_rows=training_rows,
                archive_rows=archive_rows,
                review_rows=review_rows,
                report=report,
                archive_image_count=len(archive_rows),
                settings=manifest.get("instruction_settings") if isinstance(manifest.get("instruction_settings"), Mapping) else {},
                settings_fingerprint=str(manifest.get("instruction_settings_fingerprint") or ""),
            )
            if not consistency_validation.get("ok"):
                raise ValueError(
                    "manifest_artifacts_inconsistent:"
                    + str((consistency_validation.get("errors") or ["unknown"])[0])
                )
    except (zipfile.BadZipFile, KeyError, json.JSONDecodeError, OSError, ValueError) as exc:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail=f"caption_instruction_bundle_manifest_invalid:{exc}",
        ) from exc


def _caption_instruction_bundle_rewrite_rows(
    rows: Sequence[Any],
    image_assets: Mapping[Tuple[str, str], Mapping[str, Any]],
    *,
    row_kind: str,
) -> List[Dict[str, Any]]:
    rewritten: List[Dict[str, Any]] = []
    row_iterable = rows if isinstance(rows, Sequence) and not isinstance(rows, (str, bytes, bytearray)) else []
    for row in row_iterable:
        if not isinstance(row, Mapping):
            continue
        row_copy: Dict[str, Any] = copy.deepcopy(dict(row))
        raw_image_path = str(
            row_copy.get("image_path") or row_copy.get("image_name") or row_copy.get("image") or ""
        ).strip()
        metadata = row_copy.get("metadata") if isinstance(row_copy.get("metadata"), Mapping) else {}
        export_metadata = (
            row_copy.get("export_metadata") if isinstance(row_copy.get("export_metadata"), Mapping) else {}
        )
        split = (
            row_copy.get("split")
            or metadata.get("split")
            or export_metadata.get("split")
            or ""
        )
        image_key = (
            _annotation_normalise_split(split) if str(split or "").strip() else "",
            _caption_instruction_normalized_image_path(raw_image_path) or raw_image_path,
        )
        asset = image_assets.get(image_key) or image_assets.get(("", image_key[1]))
        if asset:
            bundle_path = str(asset.get("bundle_image_path") or "").strip()
            original_path = str(asset.get("original_image_path") or raw_image_path).strip()
            row_copy["image_path"] = bundle_path
            if row_kind == "review":
                row_copy["image_name"] = bundle_path
                row_copy["image"] = bundle_path
                row_copy["original_image_path"] = original_path
                row_copy["bundle_image_sha256"] = str(asset.get("sha256") or "")
            elif row_kind == "archive":
                row_copy["image"] = bundle_path
                row_copy["image_name"] = bundle_path
                row_copy["original_image_path"] = original_path
                row_copy["bundle_image_sha256"] = str(asset.get("sha256") or "")
                export_copy = dict(export_metadata)
                export_copy["original_image_path"] = original_path
                export_copy["bundle_image_path"] = bundle_path
                export_copy["bundle_image_sha256"] = str(asset.get("sha256") or "")
                row_copy["export_metadata"] = export_copy
            else:
                metadata_copy = dict(metadata)
                metadata_copy["original_image_path"] = original_path
                metadata_copy["bundle_image_path"] = bundle_path
                metadata_copy["bundle_image_sha256"] = str(asset.get("sha256") or "")
                row_copy["metadata"] = metadata_copy
        rewritten.append(row_copy)
    return rewritten


def _caption_instruction_bundle_missing_rewritten_images(
    rows: Sequence[Any],
    *,
    row_kind: str,
) -> List[str]:
    missing: List[str] = []
    row_iterable = rows if isinstance(rows, Sequence) and not isinstance(rows, (str, bytes, bytearray)) else []
    for row in row_iterable:
        if not isinstance(row, Mapping):
            continue
        image_path = str(row.get("image_path") or row.get("image_name") or row.get("image") or "").strip()
        if not image_path:
            continue
        if row_kind == "training":
            metadata = row.get("metadata") if isinstance(row.get("metadata"), Mapping) else {}
            if not str(metadata.get("bundle_image_path") or "").strip():
                missing.append(image_path)
            continue
        if row_kind == "archive":
            export_metadata = row.get("export_metadata") if isinstance(row.get("export_metadata"), Mapping) else {}
            if not str(export_metadata.get("bundle_image_path") or "").strip():
                missing.append(str(row.get("original_image_path") or image_path).strip())
            continue
        if row_kind == "review" and not str(row.get("bundle_image_sha256") or "").strip():
            missing.append(str(row.get("original_image_path") or image_path).strip())
    return missing


def download_caption_instruction_bundle(
    dataset_id: str,
    options: Optional[Mapping[str, Any]] = None,
    export_payload: Optional[Mapping[str, Any]] = None,
):
    options_map = dict(options or {})
    if options_map.get("block_active_caption_jobs"):
        _raise_if_qwen_caption_export_busy(dataset_id)
    entry = _resolve_dataset_entry(dataset_id)
    dataset_root = _dataset_effective_root_from_entry(entry)
    dataset_root_resolved = dataset_root.resolve(strict=False)
    manifest = _annotation_manifest_for_entry(entry)
    export_payload = dict(export_payload or export_captions(dataset_id, options_map))
    archive_rows = list(export_payload.get("instruction_archive_rows") or [])
    training_rows = list(export_payload.get("instruction_training_rows") or [])
    review_rows = list(export_payload.get("instruction_review_rows") or [])
    report = (
        dict(export_payload.get("instruction_report"))
        if isinstance(export_payload.get("instruction_report"), Mapping)
        else {}
    )
    if not archive_rows:
        raise HTTPException(status_code=HTTP_409_CONFLICT, detail="caption_instruction_bundle_no_archive_rows")

    collect_rows: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for row in _annotation_collect_images(entry):
        if not isinstance(row, Mapping):
            continue
        split = _annotation_normalise_split(row.get("split"))
        rel = _annotation_normalise_image_relpath(row.get("image_relpath") or row.get("image_name"))
        key = (split, _caption_instruction_normalized_image_path(rel.as_posix()) or rel.as_posix())
        collect_rows[key] = dict(row)

    manifest_rows: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for row in manifest.get("images") or []:
        if not isinstance(row, Mapping):
            continue
        split = _annotation_normalise_split(row.get("split"))
        rel = _annotation_normalise_image_relpath(row.get("image_relpath") or row.get("image_name"))
        key = (split, _caption_instruction_normalized_image_path(rel.as_posix()) or rel.as_posix())
        manifest_rows[key] = dict(row)

    tmp_dir = Path(tempfile.mkdtemp(prefix="caption_instruction_bundle_"))
    try:
        safe_dataset_id = _sanitize_yolo_run_id_impl(str(dataset_id or "")) or "dataset"
        zip_path = tmp_dir / f"{safe_dataset_id}_caption_instruction_bundle.zip"
        written_arcnames: Set[str] = set()
        file_entries: List[Dict[str, Any]] = []
        image_assets: Dict[Tuple[str, str], Dict[str, Any]] = {}
        label_assets: List[Dict[str, Any]] = []

        def _record_bytes(arcname: str, data: bytes, *, role: str) -> None:
            written_arcnames.add(arcname)
            file_entries.append(
                {
                    "path": arcname,
                    "role": role,
                    "bytes": len(data),
                    "sha256": _caption_instruction_bytes_sha256(data),
                }
            )

        def _record_file(arcname: str, path: Path, *, role: str) -> None:
            stat_result = path.stat()
            written_arcnames.add(arcname)
            file_entries.append(
                {
                    "path": arcname,
                    "role": role,
                    "bytes": int(stat_result.st_size),
                    "sha256": _caption_instruction_file_sha256(path),
                }
            )

        for archive_row in archive_rows:
            if not isinstance(archive_row, Mapping):
                continue
            original_image_path = str(archive_row.get("image_path") or "").strip()
            if not original_image_path:
                continue
            split = _annotation_normalise_split(archive_row.get("split"))
            normalized = _caption_instruction_normalized_image_path(original_image_path) or original_image_path
            key = (split, normalized)
            source_row = collect_rows.get(key)
            manifest_row = manifest_rows.get(key) or {}
            if source_row is None:
                continue
            image_path = Path(str(source_row.get("image_path") or ""))
            try:
                image_resolved = image_path.resolve(strict=True)
            except Exception as exc:
                raise HTTPException(
                    status_code=HTTP_412_PRECONDITION_FAILED,
                    detail=f"caption_instruction_bundle_image_unavailable:{original_image_path}",
                ) from exc
            if not image_resolved.is_file() or not _path_is_within_root_impl(image_resolved, dataset_root_resolved):
                raise HTTPException(
                    status_code=HTTP_412_PRECONDITION_FAILED,
                    detail=f"caption_instruction_bundle_image_forbidden:{original_image_path}",
                )
            bundle_image_path = _caption_instruction_bundle_asset_path(original_image_path, split, root="images")
            image_digest = _caption_instruction_file_sha256(image_resolved)
            image_stat = image_resolved.stat()
            image_asset = {
                "original_image_path": original_image_path,
                "split": split,
                "bundle_image_path": bundle_image_path,
                "sha256": image_digest,
                "bytes": int(image_stat.st_size),
                "width": manifest_row.get("image_width"),
                "height": manifest_row.get("image_height"),
            }
            image_assets[key] = image_asset

            label_payload = _annotation_effective_label_payload(
                entry,
                split,
                _annotation_normalise_image_relpath(source_row.get("image_relpath") or original_image_path),
            )
            label_lines = [str(line).strip() for line in (label_payload.get("label_lines") or []) if str(line).strip()]
            label_text = "\n".join(label_lines) + ("\n" if label_lines else "")
            label_bytes = label_text.encode("utf-8")
            label_asset = {
                "original_image_path": original_image_path,
                "split": split,
                "bundle_label_path": _caption_instruction_bundle_label_path(original_image_path, split),
                "sha256": _caption_instruction_bytes_sha256(label_bytes),
                "bytes": len(label_bytes),
                "line_count": len(label_lines),
                "label_source": str(label_payload.get("label_source") or "").strip(),
                "label_source_present": bool(label_payload.get("label_source_present")),
            }
            label_assets.append(label_asset)

        rewritten_training_rows = _caption_instruction_bundle_rewrite_rows(
            training_rows,
            image_assets,
            row_kind="training",
        )
        missing_training_images = _caption_instruction_bundle_missing_rewritten_images(
            rewritten_training_rows,
            row_kind="training",
        )
        if missing_training_images:
            raise HTTPException(
                status_code=HTTP_412_PRECONDITION_FAILED,
                detail=f"caption_instruction_bundle_training_image_missing:{missing_training_images[0]}",
            )
        rewritten_archive_rows = _caption_instruction_bundle_rewrite_rows(
            archive_rows,
            image_assets,
            row_kind="archive",
        )
        rewritten_review_rows = _caption_instruction_bundle_rewrite_rows(
            review_rows,
            image_assets,
            row_kind="review",
        )
        missing_archive_images = _caption_instruction_bundle_missing_rewritten_images(
            rewritten_archive_rows,
            row_kind="archive",
        )
        if missing_archive_images:
            raise HTTPException(
                status_code=HTTP_412_PRECONDITION_FAILED,
                detail=f"caption_instruction_bundle_archive_image_missing:{missing_archive_images[0]}",
            )
        missing_review_images = _caption_instruction_bundle_missing_rewritten_images(
            rewritten_review_rows,
            row_kind="review",
        )
        if missing_review_images:
            raise HTTPException(
                status_code=HTTP_412_PRECONDITION_FAILED,
                detail=f"caption_instruction_bundle_review_image_missing:{missing_review_images[0]}",
            )
        training_validation = _caption_instruction_validate_training_rows(rewritten_training_rows)
        if not training_validation.get("ok"):
            raise HTTPException(
                status_code=HTTP_412_PRECONDITION_FAILED,
                detail=f"caption_instruction_bundle_training_rows_invalid:{training_validation.get('errors', ['unknown'])[0]}",
            )
        consistency_validation = _caption_instruction_artifact_consistency_validation(
            training_rows=rewritten_training_rows,
            archive_rows=rewritten_archive_rows,
            review_rows=rewritten_review_rows,
            report=report,
            archive_image_count=len(rewritten_archive_rows),
            settings=export_payload.get("instruction_settings"),
            settings_fingerprint=str(export_payload.get("instruction_settings_fingerprint") or ""),
        )
        if not consistency_validation.get("ok"):
            raise HTTPException(
                status_code=HTTP_412_PRECONDITION_FAILED,
                detail=(
                    "caption_instruction_bundle_artifacts_inconsistent:"
                    + str((consistency_validation.get("errors") or ["unknown"])[0])
                ),
            )

        def _bundle_manifest() -> Dict[str, Any]:
            files = sorted(file_entries, key=lambda item: str(item.get("path") or ""))
            return {
                "format": CAPTION_INSTRUCTION_BUNDLE_MANIFEST_FORMAT,
                "manifest_path": CAPTION_INSTRUCTION_BUNDLE_MANIFEST_PATH,
                "checksum_scope": CAPTION_INSTRUCTION_BUNDLE_CHECKSUM_SCOPE,
                "dataset_id": dataset_id,
                "exported_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                "instruction_settings": dict(export_payload.get("instruction_settings") or {}),
                "instruction_settings_fingerprint": str(export_payload.get("instruction_settings_fingerprint") or ""),
                "row_counts": {
                    "training_rows": len(rewritten_training_rows),
                    "archive_rows": len(rewritten_archive_rows),
                    "review_rows": len(rewritten_review_rows),
                    "images": len(image_assets),
                    "labels": len(label_assets),
                },
                "artifacts": {
                    "training_jsonl": "caption_instruction_training.jsonl",
                    "archive_jsonl": "caption_instruction_archive.jsonl",
                    "review_jsonl": "caption_instruction_review.jsonl",
                    "report_json": "caption_instruction_report.json",
                },
                "images": sorted(image_assets.values(), key=lambda item: str(item.get("bundle_image_path") or "")),
                "labels": sorted(label_assets, key=lambda item: str(item.get("bundle_label_path") or "")),
                "file_count": len(files),
                "files": files,
            }

        with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as zf:
            for asset in sorted(image_assets.values(), key=lambda item: str(item.get("bundle_image_path") or "")):
                source_key = (
                    _annotation_normalise_split(asset.get("split")),
                    _caption_instruction_normalized_image_path(asset.get("original_image_path"))
                    or str(asset.get("original_image_path") or ""),
                )
                source_row = collect_rows.get(source_key)
                if source_row is None:
                    continue
                image_resolved = Path(str(source_row.get("image_path") or "")).resolve(strict=True)
                arcname = str(asset.get("bundle_image_path") or "")
                zf.write(image_resolved, arcname=arcname)
                _record_file(arcname, image_resolved, role="image")
            for label_asset in sorted(label_assets, key=lambda item: str(item.get("bundle_label_path") or "")):
                source_key = (
                    _annotation_normalise_split(label_asset.get("split")),
                    _caption_instruction_normalized_image_path(label_asset.get("original_image_path"))
                    or str(label_asset.get("original_image_path") or ""),
                )
                source_row = collect_rows.get(source_key)
                if source_row is None:
                    continue
                label_payload = _annotation_effective_label_payload(
                    entry,
                    source_key[0],
                    _annotation_normalise_image_relpath(
                        source_row.get("image_relpath") or label_asset.get("original_image_path")
                    ),
                )
                label_lines = [
                    str(line).strip()
                    for line in (label_payload.get("label_lines") or [])
                    if str(line).strip()
                ]
                label_text = "\n".join(label_lines) + ("\n" if label_lines else "")
                label_bytes = label_text.encode("utf-8")
                arcname = str(label_asset.get("bundle_label_path") or "")
                zf.writestr(arcname, label_bytes)
                _record_bytes(arcname, label_bytes, role="label")
            labelmap_bytes = ("\n".join(str(item).strip() for item in manifest.get("labelmap") or [] if str(item).strip()) + "\n").encode("utf-8")
            zf.writestr("labelmap.txt", labelmap_bytes)
            _record_bytes("labelmap.txt", labelmap_bytes, role="labelmap")
            training_bytes = ("\n".join(json.dumps(row, ensure_ascii=False) for row in rewritten_training_rows) + ("\n" if rewritten_training_rows else "")).encode("utf-8")
            zf.writestr("caption_instruction_training.jsonl", training_bytes)
            _record_bytes("caption_instruction_training.jsonl", training_bytes, role="training_rows")
            archive_bytes = ("\n".join(json.dumps(row, ensure_ascii=False) for row in rewritten_archive_rows) + ("\n" if rewritten_archive_rows else "")).encode("utf-8")
            zf.writestr("caption_instruction_archive.jsonl", archive_bytes)
            _record_bytes("caption_instruction_archive.jsonl", archive_bytes, role="archive_rows")
            review_bytes = ("\n".join(json.dumps(row, ensure_ascii=False) for row in rewritten_review_rows) + ("\n" if rewritten_review_rows else "")).encode("utf-8")
            zf.writestr("caption_instruction_review.jsonl", review_bytes)
            _record_bytes("caption_instruction_review.jsonl", review_bytes, role="review_rows")
            report_bytes = (json.dumps(report, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
            zf.writestr("caption_instruction_report.json", report_bytes)
            _record_bytes("caption_instruction_report.json", report_bytes, role="report")
            manifest_bytes = (json.dumps(_bundle_manifest(), ensure_ascii=False, indent=2) + "\n").encode("utf-8")
            zf.writestr(CAPTION_INSTRUCTION_BUNDLE_MANIFEST_PATH, manifest_bytes)
            written_arcnames.add(CAPTION_INSTRUCTION_BUNDLE_MANIFEST_PATH)
        _validate_created_zip(
            zip_path,
            required_names=written_arcnames,
            detail_prefix="caption_instruction_bundle",
        )
        _caption_instruction_validate_bundle_manifest(zip_path)
        return FileResponse(
            path=str(zip_path),
            media_type="application/zip",
            filename=f"{safe_dataset_id}_caption_instruction_bundle.zip",
            background=BackgroundTask(shutil.rmtree, tmp_dir, ignore_errors=True),
        )
    except HTTPException:
        shutil.rmtree(tmp_dir, ignore_errors=True)
        raise
    except Exception as exc:  # noqa: BLE001
        shutil.rmtree(tmp_dir, ignore_errors=True)
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail=f"caption_instruction_bundle_export_failed:{exc}",
        ) from exc


def _qwen_caption_dataset_instruction_export_options(
    payload: QwenCaptionDatasetJobRequest,
) -> Dict[str, Any]:
    selected_names = [
        str(name or "").strip()
        for name in (payload.image_names or [])
        if str(name or "").strip()
    ]
    options = {
        "include_caption0_in_training": bool(payload.include_caption0_in_training),
        "include_generated_qa_in_training": bool(payload.include_generated_qa_in_training),
        "include_deterministic_metadata_qa": bool(payload.include_deterministic_metadata_qa),
        "instruction_qa_restrict_speculative_language": bool(
            payload.instruction_qa_restrict_speculative_language
        ),
        "qa_mix": str(payload.qa_mix or "balanced"),
        "answer_format": str(payload.answer_format or "natural"),
        "require_ready_instruction_export": False,
    }
    if selected_names:
        options["selected_image_names"] = selected_names
    if int(payload.max_images or 0) > 0:
        options["max_images"] = int(payload.max_images or 0)
    split = str(payload.split or "all").strip().lower()
    if split in {"train", "val"}:
        options["split"] = split
    return options


def _qwen_caption_dataset_materialize_instruction_artifacts(
    *,
    dataset_id: str,
    payload: QwenCaptionDatasetJobRequest,
    artifact_dir: Path,
) -> Dict[str, Any]:
    artifact_dir.mkdir(parents=True, exist_ok=True)
    options = _qwen_caption_dataset_instruction_export_options(payload)
    safe_dataset_id = _sanitize_yolo_run_id_impl(str(dataset_id or "")) or "dataset"
    export_payload = dict(export_captions(dataset_id, options))
    report = (
        dict(export_payload.get("instruction_report"))
        if isinstance(export_payload.get("instruction_report"), Mapping)
        else {}
    )
    report_path = artifact_dir / "caption_instruction_report.json"
    report_bytes = (json.dumps(report, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
    report_path.write_bytes(report_bytes)
    zip_response = download_caption_instruction_bundle(dataset_id, options, export_payload=export_payload)
    temp_zip_path = Path(str(getattr(zip_response, "path", "") or ""))
    if not temp_zip_path.is_file():
        raise RuntimeError("caption_instruction_bundle_response_path_missing")
    bundle_path = artifact_dir / f"{safe_dataset_id}_caption_instruction_bundle.zip"
    temp_parent = temp_zip_path.parent
    try:
        shutil.copy2(temp_zip_path, bundle_path)
    finally:
        if temp_parent.name.startswith("caption_instruction_bundle_"):
            shutil.rmtree(temp_parent, ignore_errors=True)
    summary = dict(export_payload.get("instruction_summary") or {})
    readiness = (
        report.get("training_readiness")
        if isinstance(report.get("training_readiness"), Mapping)
        else {}
    )
    return {
        "status": "ok",
        "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "artifact_dir": str(artifact_dir),
        "bundle_zip": str(bundle_path),
        "bundle_sha256": _caption_instruction_file_sha256(bundle_path),
        "bundle_bytes": int(bundle_path.stat().st_size),
        "report_json": str(report_path),
        "report_sha256": _caption_instruction_bytes_sha256(report_bytes),
        "report_bytes": len(report_bytes),
        "training_row_count": len(export_payload.get("instruction_training_rows") or []),
        "archive_row_count": len(export_payload.get("instruction_archive_rows") or []),
        "review_row_count": len(export_payload.get("instruction_review_rows") or []),
        "training_readiness_status": str(readiness.get("status") or summary.get("training_readiness_status") or ""),
        "instruction_settings": dict(export_payload.get("instruction_settings") or {}),
        "instruction_settings_fingerprint": str(export_payload.get("instruction_settings_fingerprint") or ""),
    }


def _qwen_caption_dataset_try_materialize_instruction_artifacts(
    job: QwenCaptionDatasetJob,
    payload: QwenCaptionDatasetJobRequest,
    *,
    artifact_dir: Path,
) -> None:
    if not bool(payload.instruction_dataset):
        return
    try:
        artifacts = _qwen_caption_dataset_materialize_instruction_artifacts(
            dataset_id=payload.dataset_id,
            payload=payload,
            artifact_dir=artifact_dir,
        )
    except HTTPException as exc:
        detail = str(exc.detail or exc)
        result_data = dict(job.result or {})
        result_data["instruction_artifacts"] = {
            "status": "error",
            "error": detail,
            "status_code": int(exc.status_code),
            "artifact_dir": str(artifact_dir),
        }
        job.result = result_data
        job.status = "failed"
        job.progress = 1.0
        job.error = "caption_instruction_artifact_materialization_failed"
        job.message = f"Training dataset artifact materialization failed: {detail}"
        _qwen_caption_dataset_job_log(
            job,
            "training dataset artifact materialization failed",
            error=detail,
            status_code=exc.status_code,
        )
        return
    except Exception as exc:  # noqa: BLE001
        detail = str(exc)
        result_data = dict(job.result or {})
        result_data["instruction_artifacts"] = {
            "status": "error",
            "error": detail,
            "artifact_dir": str(artifact_dir),
        }
        job.result = result_data
        job.status = "failed"
        job.progress = 1.0
        job.error = "caption_instruction_artifact_materialization_failed"
        job.message = f"Training dataset artifact materialization failed: {detail}"
        _qwen_caption_dataset_job_log(
            job,
            "training dataset artifact materialization failed",
            error=detail,
        )
        return
    result_data = dict(job.result or {})
    result_data["instruction_artifacts"] = artifacts
    job.result = result_data
    _qwen_caption_dataset_job_log(
        job,
        "training dataset artifacts materialized",
        instruction_artifacts=artifacts,
    )


def _raise_if_qwen_caption_metadata_busy(dataset_id: str) -> None:
    active = _qwen_caption_dataset_active_export_job(dataset_id)
    if not active:
        return
    job_id = str(active.get("job_id") or "").strip() or "unknown"
    status = str(active.get("status") or "").strip() or "active"
    raise HTTPException(
        status_code=HTTP_409_CONFLICT,
        detail=f"caption_metadata_busy:{job_id}:{status}",
    )


def _export_stored_caption_records_only(
    dataset_id: str,
    entry: Mapping[str, Any],
) -> Dict[str, Any]:
    records = [
        _dataset_caption_record_public(record)
        for record in _load_dataset_caption_records(entry)
    ]
    records = [
        record for _index, record in sorted(
            enumerate(records),
            key=lambda item: (
                str(item[1].get("image_key") or ""),
                0 if bool(item[1].get("is_primary")) else 1,
                item[0],
            ),
        )
    ]
    per_image_counts: Dict[str, int] = defaultdict(int)
    indexed_records: List[Dict[str, Any]] = []
    grouped_counts: Dict[str, int] = defaultdict(int)
    for record in records:
        public = _dataset_caption_record_public(record)
        image_name = str(
            public.get("image_name") or public.get("image_key") or ""
        ).strip()
        per_image_counts[image_name] += 1
        public["caption_index"] = per_image_counts[image_name]
        indexed_records.append(public)
        grouped_counts[image_name] += 1
    caption_counts = list(grouped_counts.values())
    return {
        "dataset_id": dataset_id,
        "captions": indexed_records,
        "summary": {
            "image_count": len(grouped_counts),
            "caption_count": len(indexed_records),
            "training_row_count": len(indexed_records),
            "images_with_multiple_captions": sum(
                1 for count in caption_counts if count > 1
            ),
            "max_captions_per_image": max(caption_counts) if caption_counts else 0,
        },
    }


def export_captions(dataset_id: str, options: Optional[Mapping[str, Any]] = None):
    options_map = dict(options or {})
    if options_map.get("block_active_caption_jobs"):
        _raise_if_qwen_caption_export_busy(dataset_id)
    entry = _resolve_dataset_entry(dataset_id)
    if options_map.get("records_only"):
        return _export_stored_caption_records_only(dataset_id, entry)
    caption_yolo_layout = str(entry.get("yolo_layout") or "flat").strip().lower()
    raw_selected_names = options_map.get("selected_image_names") or []
    if isinstance(raw_selected_names, str):
        raw_selected_names = [raw_selected_names]
    selected_names = {
        str(name or "").strip()
        for name in raw_selected_names
        if str(name or "").strip()
    }
    selected_names.update(Path(name).name for name in list(selected_names) if name)
    selected_names.update(Path(name).stem for name in list(selected_names) if name)
    split_filter = str(options_map.get("split") or "all").strip().lower()
    try:
        max_images = max(0, int(options_map.get("max_images") or 0))
    except (TypeError, ValueError, OverflowError):
        max_images = 0
    scoped_images: List[Dict[str, Any]] = []
    scoped_image_keys: Set[str] = set()
    scoped_export_requested = bool(selected_names) or split_filter in {"train", "val"} or max_images > 0

    def _caption_export_image_keys_for_scope(split: Optional[str], rel: Path) -> Set[str]:
        keys = {_dataset_caption_image_key(split if caption_yolo_layout == "split" else None, rel)}
        if caption_yolo_layout != "split" and split:
            keys.add(_dataset_caption_image_key(split, rel))
        return {key for key in keys if key}

    for image in _annotation_collect_images(entry):
        image_name = str(image.get("image_name") or "").strip()
        split = str(image.get("split") or "").strip() or None
        if split_filter in {"train", "val"} and split != split_filter:
            continue
        rel = Path(str(image.get("image_relpath") or image_name))
        selectors = {
            image_name,
            rel.as_posix(),
            Path(image_name).stem,
        }
        if split:
            selectors.add(f"{split}/{rel.as_posix()}")
        if selected_names and not (selectors & selected_names):
            continue
        image_key = _dataset_caption_image_key(split if caption_yolo_layout == "split" else None, rel)
        image = dict(image)
        image["_caption_export_image_key"] = image_key
        scoped_images.append(image)
        scoped_image_keys.update(_caption_export_image_keys_for_scope(split, rel))
        if max_images and len(scoped_images) >= max_images:
            break
    records = [_dataset_caption_record_public(record) for record in _load_dataset_caption_records(entry)]
    if scoped_image_keys or scoped_export_requested:
        records = [
            record
            for record in records
            if str(record.get("image_key") or "").strip() in scoped_image_keys
            or str(record.get("image_name") or "").strip() in selected_names
            or Path(str(record.get("image_name") or "")).stem in selected_names
        ]
    existing = {
        (
            str(record.get("image_key") or ""),
            str(record.get("caption") or "").strip(),
        )
        for record in records
    }
    for image in scoped_images:
        image_name = str(image.get("image_name") or "").strip()
        split = str(image.get("split") or "").strip() or None
        rel = Path(str(image.get("image_relpath") or image_name))
        image_key = str(image.get("_caption_export_image_key") or "").strip() or _dataset_caption_image_key(
            split if caption_yolo_layout == "split" else None,
            rel,
        )
        caption = _annotation_effective_text_label(entry, rel, split)
        key = (image_key, caption)
        if caption and key not in existing:
            primary = _dataset_caption_synthetic_primary(
                dataset_id=dataset_id,
                image_name=image_name,
                image_key=image_key,
                split=split,
                caption=caption,
            )
            if primary:
                records.append(primary)
                existing.add(key)
    records = [
        record for _index, record in sorted(
            enumerate(records),
            key=lambda item: (
                str(item[1].get("image_key") or ""),
                0 if bool(item[1].get("is_primary")) else 1,
                item[0],
            ),
        )
    ]
    indexed_records: List[Dict[str, Any]] = []
    grouped: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
    per_image_counts: Dict[str, int] = defaultdict(int)
    for record in records:
        public = _dataset_caption_record_public(record)
        image_name = str(public.get("image_name") or public.get("image_key") or "").strip()
        per_image_counts[image_name] += 1
        public["caption_index"] = per_image_counts[image_name]
        indexed_records.append(public)
        grouped[image_name].append(public)
    caption_counts = [len(items) for items in grouped.values()]
    summary = {
        "image_count": len(grouped),
        "caption_count": len(indexed_records),
        "training_row_count": len(indexed_records),
        "images_with_multiple_captions": sum(1 for count in caption_counts if count > 1),
        "max_captions_per_image": max(caption_counts) if caption_counts else 0,
    }
    training_rows = [
        _dataset_caption_vlm_training_row(public, dataset_id=dataset_id)
        for public in indexed_records
        if str(public.get("image_name") or public.get("image_key") or "").strip()
        and str(public.get("caption") or "").strip()
    ]
    instruction_settings = _caption_instruction_export_settings(options_map)
    instruction_records = _load_dataset_caption_instruction_records(entry)
    instruction_archive = _dataset_caption_instruction_archive(
        indexed_records,
        instruction_records,
        dataset_id=dataset_id,
        entry=entry,
        settings=instruction_settings,
        selected_image_keys=scoped_image_keys if scoped_export_requested else None,
    )
    instruction_training_rows = list(instruction_archive.get("training_rows") or [])
    instruction_archive_rows = list(instruction_archive.get("archive_rows") or [])
    instruction_review_rows = list(instruction_archive.get("review_rows") or [])
    instruction_report = (
        dict(instruction_archive.get("captioning_report"))
        if isinstance(instruction_archive.get("captioning_report"), Mapping)
        else {}
    )
    instruction_export_validation = (
        dict(instruction_archive.get("instruction_export_validation"))
        if isinstance(instruction_archive.get("instruction_export_validation"), Mapping)
        else {}
    )
    instruction_artifact_consistency = (
        dict(instruction_archive.get("instruction_artifact_consistency"))
        if isinstance(instruction_archive.get("instruction_artifact_consistency"), Mapping)
        else {}
    )
    summary["training_row_count"] = len(training_rows)
    instruction_summary = {
        "instruction_training_row_count": len(instruction_training_rows),
        "generated_qa_pair_count": int(instruction_archive.get("generated_qa_pair_count") or 0),
        "deterministic_metadata_qa_pair_count": int(
            instruction_archive.get("deterministic_metadata_qa_pair_count") or 0
        ),
        "instruction_review_row_count": len(instruction_review_rows),
        "manual_review_required_count": sum(
            1 for row in instruction_review_rows if isinstance(row, Mapping) and row.get("requires_manual_review") is True
        ),
        "training_readiness_status": str(
            (instruction_report.get("training_readiness") or {}).get("status")
            if isinstance(instruction_report.get("training_readiness"), Mapping)
            else ""
        ).strip()
        or "unknown",
        "instruction_export_validation_ok": bool(instruction_export_validation.get("ok")),
        "instruction_export_validation_error_count": int(
            instruction_export_validation.get("error_count") or 0
        ),
        "instruction_artifact_consistency_ok": bool(instruction_artifact_consistency.get("ok")),
        "instruction_artifact_consistency_error_count": int(
            instruction_artifact_consistency.get("error_count") or 0
        ),
        "rejected_training_row_count": int(instruction_archive.get("rejected_training_row_count") or 0),
    }
    instruction_archive["summary"] = dict(instruction_summary)
    return {
        "dataset_id": dataset_id,
        "captions": indexed_records,
        "grouped": dict(grouped),
        "training_rows": training_rows,
        "instruction_settings": dict(instruction_settings),
        "instruction_settings_fingerprint": str(instruction_archive.get("settings_fingerprint") or ""),
        "instruction_training_rows": instruction_training_rows,
        "instruction_archive_rows": instruction_archive_rows,
        "instruction_review_rows": instruction_review_rows,
        "instruction_report": instruction_report,
        "instruction_export_validation": instruction_export_validation,
        "instruction_artifact_consistency": instruction_artifact_consistency,
        "instruction_archive": instruction_archive,
        "archive": _dataset_caption_grouped_archive(indexed_records, dataset_id=dataset_id, summary=summary),
        "summary": summary,
        "instruction_summary": instruction_summary,
    }


def _caption_instruction_review_payload_rows(payload: Any) -> List[Any]:
    missing = object()
    if isinstance(payload, list):
        raw_rows = payload
    elif isinstance(payload, Mapping):
        raw_rows = missing
        for field in ("rows", "review_rows", "instruction_review_rows"):
            if field in payload:
                raw_rows = payload.get(field)
                break
        if raw_rows is missing and str(payload.get("format") or "").strip() == CAPTION_INSTRUCTION_REVIEW_ROWS_FORMAT:
            raw_rows = [payload]
        if raw_rows is missing:
            raw_rows = None
    else:
        raw_rows = None
    if not isinstance(raw_rows, list):
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="review_rows_list_required")
    if len(raw_rows) > CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_ROWS:
        raise HTTPException(status_code=HTTP_413_CONTENT_TOO_LARGE, detail="review_rows_too_many")
    return list(raw_rows)


def _caption_instruction_review_dataset_id_matches(row: Mapping[str, Any], dataset_id: str) -> bool:
    row_dataset_id = str(row.get("dataset_id") or "").strip()
    if not row_dataset_id:
        return True
    return row_dataset_id == str(dataset_id or "").strip()


def _caption_instruction_reject_dataset_id_mismatches(
    rows: Sequence[Any],
    *,
    dataset_id: str,
) -> None:
    expected = str(dataset_id or "").strip()
    if not expected:
        return
    for index, row in enumerate(rows, start=1):
        if not isinstance(row, Mapping):
            continue
        if str(row.get("format") or "").strip() != CAPTION_INSTRUCTION_REVIEW_ROWS_FORMAT:
            continue
        decision = _caption_instruction_review_decision(row.get("review_decision"))
        row_origin = str(row.get("row_origin") or "").strip()
        is_persisted_action = decision in {"accepted", "rejected", "needs_revision"} and row_origin in {
            "caption0",
            "generated_qa",
        }
        row_dataset_id = str(row.get("dataset_id") or "").strip()
        if not row_dataset_id:
            if is_persisted_action:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_dataset_id_missing:row_{index}",
                )
            continue
        if row_dataset_id == expected:
            continue
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail=f"review_rows_dataset_id_mismatch:row_{index}:{row_dataset_id}!={expected}",
        )


def _caption_instruction_reject_unsupported_review_decisions(rows: Sequence[Any]) -> None:
    for index, row in enumerate(rows, start=1):
        if not isinstance(row, Mapping):
            continue
        if str(row.get("format") or "").strip() != CAPTION_INSTRUCTION_REVIEW_ROWS_FORMAT:
            continue
        if _caption_instruction_review_decision_is_supported(row.get("review_decision")):
            continue
        raw_decision = str(row.get("review_decision") or "").strip()
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail=f"review_rows_unsupported_review_decision:row_{index}:{raw_decision}",
        )


def _caption_instruction_reject_malformed_review_rows(rows: Sequence[Any]) -> None:
    def _require_text_field(
        row: Mapping[str, Any],
        field: str,
        index: int,
        *,
        max_chars: int,
        detail_code: str,
        required: bool = True,
    ) -> str:
        if field not in row:
            if required:
                raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail=f"{detail_code}:row_{index}")
            return ""
        value = row.get(field)
        if not isinstance(value, str):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_{field}_invalid:row_{index}",
            )
        if len(value) > max_chars:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_field_too_long:row_{index}:{field}:{max_chars}",
            )
        text = value.strip()
        if required and not text:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail=f"{detail_code}:row_{index}")
        return text

    for index, row in enumerate(rows, start=1):
        if not isinstance(row, Mapping):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_row_not_object:row_{index}",
            )
        if str(row.get("format") or "").strip() != CAPTION_INSTRUCTION_REVIEW_ROWS_FORMAT:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_invalid_format:row_{index}",
            )
        if "dataset_id" in row:
            _require_text_field(
                row,
                "dataset_id",
                index,
                max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_ID_CHARS,
                detail_code="review_rows_dataset_id_missing",
                required=False,
            )
        image_path = ""
        for image_field in ("image_path", "image_name", "image"):
            if image_field in row:
                image_path = _require_text_field(
                    row,
                    image_field,
                    index,
                    max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_PATH_CHARS,
                    detail_code="review_rows_missing_image_path",
                    required=False,
                )
                if image_path:
                    break
        if not image_path:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_missing_image_path:row_{index}",
            )
        original_image_path = ""
        if "original_image_path" in row:
            original_image_path = _require_text_field(
                row,
                "original_image_path",
                index,
                max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_PATH_CHARS,
                detail_code="review_rows_original_image_path_invalid",
                required=False,
            )
        bundle_image_path = ""
        if "bundle_image_path" in row:
            bundle_image_path = _require_text_field(
                row,
                "bundle_image_path",
                index,
                max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_PATH_CHARS,
                detail_code="review_rows_bundle_image_path_invalid",
                required=False,
            )
        bundle_image_sha256 = ""
        if "bundle_image_sha256" in row:
            bundle_image_sha256 = _require_text_field(
                row,
                "bundle_image_sha256",
                index,
                max_chars=128,
                detail_code="review_rows_bundle_image_sha256_invalid",
                required=False,
            )
            if bundle_image_sha256 and not re.fullmatch(r"[0-9a-fA-F]{64}", bundle_image_sha256):
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_bundle_image_sha256_invalid:row_{index}",
                )
        if (bundle_image_path or bundle_image_sha256) and not original_image_path:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_original_image_path_missing_for_bundle:row_{index}",
            )
        qa_id = _require_text_field(
            row,
            "qa_id",
            index,
            max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_ID_CHARS,
            detail_code="review_rows_qa_id_missing",
        )
        row_origin = _require_text_field(
            row,
            "row_origin",
            index,
            max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_ID_CHARS,
            detail_code="review_rows_row_origin_missing",
        )
        question = _require_text_field(
            row,
            "question",
            index,
            max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_QUESTION_CHARS,
            detail_code="review_rows_question_missing",
            required=False,
        )
        candidate_answer = _require_text_field(
            row,
            "candidate_answer",
            index,
            max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_ANSWER_CHARS,
            detail_code="review_rows_candidate_answer_missing",
            required=False,
        )
        training_answer = _require_text_field(
            row,
            "training_answer",
            index,
            max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_ANSWER_CHARS,
            detail_code="review_rows_training_answer_missing",
            required=False,
        )
        if row_origin == "generated_qa" and (not question or not (candidate_answer or training_answer)):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_generated_qa_text_missing:row_{index}",
            )
        if row_origin == "caption0" and not (candidate_answer or training_answer):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_caption0_answer_missing:row_{index}",
            )
        if not question:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_question_missing:row_{index}",
            )
        if not candidate_answer:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_candidate_answer_missing:row_{index}",
            )
        _require_text_field(
            row,
            "validation_status",
            index,
            max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_ID_CHARS,
            detail_code="review_rows_validation_status_missing",
        )
        if not isinstance(row.get("selected_for_training"), bool):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_selected_for_training_invalid:row_{index}",
            )
        if not isinstance(row.get("requires_manual_review"), bool):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_requires_manual_review_invalid:row_{index}",
            )
        if row.get("selected_for_training") is True and not training_answer:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_training_answer_missing:row_{index}",
            )
        if not isinstance(row.get("source_summary"), Mapping):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_source_summary_missing:row_{index}",
            )
        if not isinstance(row.get("rejection_reasons"), list):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_rejection_reasons_invalid:row_{index}",
            )
        if "review_decision" not in row:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_review_decision_missing:row_{index}",
            )
        _require_text_field(
            row,
            "review_decision",
            index,
            max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_ID_CHARS,
            detail_code="review_rows_review_decision_missing",
            required=False,
        )
        if "review_notes" not in row:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_review_notes_missing:row_{index}",
            )
        _require_text_field(
            row,
            "review_notes",
            index,
            max_chars=CAPTION_INSTRUCTION_REVIEW_IMPORT_MAX_NOTES_CHARS,
            detail_code="review_rows_review_notes_missing",
            required=False,
        )


def _caption_instruction_has_persisted_actionable_review_decision(rows: Sequence[Any]) -> bool:
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("format") or "").strip() != CAPTION_INSTRUCTION_REVIEW_ROWS_FORMAT:
            continue
        decision = _caption_instruction_review_decision(row.get("review_decision"))
        if decision not in {"accepted", "rejected", "needs_revision"}:
            continue
        row_origin = str(row.get("row_origin") or "").strip()
        if row_origin in {"caption0", "generated_qa"}:
            return True
    return False


_CAPTION_INSTRUCTION_REVIEW_SPLITS = ("train", "val", "valid", "test")
_CAPTION_INSTRUCTION_REVIEW_SPLIT_PREFIX_RE = re.compile(r"^(train|val|valid|test)/(.+)$")


def _caption_instruction_review_path_aliases(
    image_path: Any,
    split: Any = None,
) -> Tuple[Set[str], Set[str]]:
    raw = str(image_path or "").strip()
    split_text = str(split or "").strip()
    image_names: Set[str] = set()
    image_keys: Set[str] = set()

    def _add_name(value: Any) -> None:
        candidate = str(value or "").strip()
        normalized = _caption_instruction_normalized_image_path(candidate)
        for item in {candidate, normalized}:
            if item:
                image_names.add(item)

    def _add_key(value: Any) -> None:
        candidate = str(value or "").strip()
        normalized = _caption_instruction_normalized_image_path(candidate)
        for item in {candidate, normalized}:
            if item:
                image_keys.add(item)

    if not raw:
        return image_names, image_keys

    _add_name(raw)
    _add_key(raw)
    normalized_path = _caption_instruction_normalized_image_path(raw)
    if normalized_path:
        _add_name(normalized_path)
        _add_key(normalized_path)

    relative_path = normalized_path or raw
    split_match = _CAPTION_INSTRUCTION_REVIEW_SPLIT_PREFIX_RE.match(relative_path)
    inferred_split = ""
    if split_match:
        inferred_split = split_match.group(1)
        relative_path = split_match.group(2).strip()
        _add_name(relative_path)
        _add_key(f"{inferred_split}/{relative_path}")

    if split_text and relative_path and not inferred_split:
        _add_key(f"{split_text}/{relative_path}")
    elif relative_path and not inferred_split:
        for split_candidate in _CAPTION_INSTRUCTION_REVIEW_SPLITS:
            _add_key(f"{split_candidate}/{relative_path}")

    return image_names, image_keys


def _caption_instruction_review_image_candidates(
    entry: Dict[str, Any],
    row: Mapping[str, Any],
) -> Tuple[Set[str], Set[str]]:
    image_path = str(row.get("image_path") or row.get("image_name") or row.get("image") or "").strip()
    split = str(row.get("split") or "").strip() or None
    image_names, image_keys = _caption_instruction_review_path_aliases(image_path, split)
    if not image_path:
        return image_names, image_keys

    original_image_path = str(row.get("original_image_path") or "").strip()
    if original_image_path and original_image_path != image_path:
        original_names, original_keys = _caption_instruction_review_path_aliases(original_image_path, split)
        image_names.update(original_names)
        image_keys.update(original_keys)

    normalized_path = _caption_instruction_normalized_image_path(image_path)
    names_to_try = sorted(image_names or {image_path, normalized_path})
    inferred_split = ""
    split_match = _CAPTION_INSTRUCTION_REVIEW_SPLIT_PREFIX_RE.match(normalized_path or image_path)
    if split_match:
        inferred_split = split_match.group(1)
    if inferred_split:
        split_candidates: Tuple[Optional[str], ...] = (inferred_split,)
    elif split:
        split_candidates = (split,)
    else:
        split_candidates = (None, *_CAPTION_INSTRUCTION_REVIEW_SPLITS)
    split_overrides: List[Optional[str]] = []
    for split_candidate in split_candidates:
        normalized_split = str(split_candidate or "").strip() or None
        if normalized_split not in split_overrides:
            split_overrides.append(normalized_split)
    for name in names_to_try:
        for split_override in split_overrides:
            try:
                ctx_payload = {"split": split_override} if split_override else None
                resolved_split, rel, image_key = _dataset_caption_context(entry, name, ctx_payload)
            except Exception:
                continue
            rel_name = str(rel.as_posix() if hasattr(rel, "as_posix") else rel or "").strip()
            if rel_name:
                rel_names, rel_keys = _caption_instruction_review_path_aliases(rel_name, resolved_split)
                image_names.update(rel_names)
                image_keys.update(rel_keys)
            if image_key:
                _names, key_aliases = _caption_instruction_review_path_aliases(image_key, resolved_split)
                image_keys.update(key_aliases)
    return image_names, image_keys


def _caption_instruction_review_current_image_path(
    entry: Dict[str, Any],
    row: Mapping[str, Any],
    *,
    image_names: Set[str],
    image_path: str,
) -> Optional[Path]:
    dataset_root = _dataset_effective_root_from_entry(entry)
    yolo_layout = str(entry.get("yolo_layout") or "flat").strip().lower() or "flat"
    candidates: List[str] = []
    for value in (
        row.get("original_image_path"),
        row.get("image_name"),
        row.get("image"),
        image_path,
        *sorted(image_names),
    ):
        candidate = str(value or "").strip()
        if candidate and candidate not in candidates:
            candidates.append(candidate)
    split_values: List[Optional[str]] = []
    for value in (row.get("split"), None, "train", "val"):
        split_value = str(value or "").strip() if value is not None else ""
        normalized = split_value or None
        if normalized not in split_values:
            split_values.append(normalized)
    for candidate in candidates:
        for split_override in split_values:
            try:
                split_name, rel, _image_key = _dataset_caption_context(
                    entry,
                    candidate,
                    {"split": split_override} if split_override else None,
                )
                resolved_split = str(split_name or split_override or "train")
                return _resolve_annotation_image_path(dataset_root, yolo_layout, resolved_split, rel)
            except Exception:
                continue
    return None


def _caption_instruction_reject_stale_bundle_review_image(
    entry: Dict[str, Any],
    row: Mapping[str, Any],
    *,
    row_index: int,
    image_names: Set[str],
    image_path: str,
) -> None:
    expected_sha256 = str(row.get("bundle_image_sha256") or "").strip()
    if not expected_sha256:
        return
    current_image_path = _caption_instruction_review_current_image_path(
        entry,
        row,
        image_names=image_names,
        image_path=image_path,
    )
    if current_image_path is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail=f"review_rows_bundle_image_not_found:row_{row_index}",
        )
    try:
        actual_sha256 = _caption_instruction_file_sha256(current_image_path)
    except Exception as exc:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail=f"review_rows_bundle_image_hash_failed:row_{row_index}",
        ) from exc
    if actual_sha256.lower() != expected_sha256.lower():
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail=f"review_rows_bundle_image_sha256_mismatch:row_{row_index}",
        )


def _caption_instruction_review_target_key(row: Mapping[str, Any]) -> Tuple[str, str, str, str, str]:
    row_origin = str(row.get("row_origin") or "").strip()
    qa_id = str(row.get("qa_id") or "").strip()
    image_path = str(
        row.get("original_image_path")
        or row.get("image_path")
        or row.get("image_name")
        or row.get("image")
        or ""
    ).strip()
    split = str(row.get("split") or "").strip()
    image_key = _caption_instruction_normalized_image_path(image_path)
    if split and image_key and not re.match(r"^(?:train|val|valid|test)/", image_key):
        image_key = _caption_instruction_normalized_image_path(f"{split}/{image_key}")
    if qa_id:
        return ("qa_id", row_origin, qa_id, image_key or image_path, "")
    question = _caption_instruction_normalized_question(row.get("question"))
    answer = str(row.get("candidate_answer") or row.get("training_answer") or "").strip()
    return ("question_answer", row_origin, image_key or image_path, "", f"{question}\u0000{answer}")


def _caption_instruction_review_resolved_target_key(
    row_origin: str,
    record: Mapping[str, Any],
) -> Tuple[str, str, str, str]:
    origin = str(row_origin or "").strip()
    record_id = str(record.get("id") or "").strip()
    if record_id:
        return (origin, "id", record_id, "")
    image_key = _caption_instruction_normalized_image_path(
        record.get("image_key") or record.get("image_name") or record.get("image") or ""
    )
    if origin == "generated_qa":
        question = _caption_instruction_normalized_question(record.get("question"))
        answer = str(record.get("answer") or "").strip()
        return (origin, "content", image_key, f"{question}\u0000{answer}")
    caption = str(record.get("caption") or "").strip()
    return (origin, "content", image_key, caption)


def _caption_instruction_review_has_current_text(row_origin: str, row: Mapping[str, Any]) -> bool:
    origin = str(row_origin or "").strip()
    if origin == "generated_qa":
        question = _caption_instruction_normalized_question(row.get("question"))
        answer = str(row.get("candidate_answer") or row.get("training_answer") or "").strip()
        return bool(question and answer)
    if origin == "caption0":
        caption = str(row.get("candidate_answer") or row.get("training_answer") or "").strip()
        return bool(caption)
    return True


def _caption_instruction_current_review_row_status(
    row_origin: str,
    row: Mapping[str, Any],
    *,
    image_names: Set[str],
    image_keys: Set[str],
    current_review_rows: Sequence[Mapping[str, Any]],
) -> str:
    origin = str(row_origin or "").strip()
    qa_id = str(row.get("qa_id") or "").strip()
    question = _caption_instruction_normalized_question(row.get("question"))
    candidate_answer = str(row.get("candidate_answer") or "").strip()
    training_answer = str(row.get("training_answer") or "").strip()
    selected_for_training = row.get("selected_for_training") is True
    matched_by_identity = False
    for current in current_review_rows:
        if not isinstance(current, Mapping):
            continue
        if str(current.get("row_origin") or "").strip() != origin:
            continue
        current_qa_id = str(current.get("qa_id") or "").strip()
        if qa_id and current_qa_id != qa_id:
            continue
        current_image = str(current.get("image_path") or current.get("image_name") or current.get("image") or "").strip()
        current_split = str(current.get("split") or "").strip()
        current_image_names, current_image_keys = _caption_instruction_review_path_aliases(current_image, current_split)
        if not (current_image_keys & image_keys or current_image_names & image_names):
            continue
        matched_by_identity = True
        current_question = _caption_instruction_normalized_question(current.get("question"))
        if question and current_question and current_question != question:
            return "question_stale"
        current_candidate_answer = str(current.get("candidate_answer") or "").strip()
        if candidate_answer and current_candidate_answer and current_candidate_answer != candidate_answer:
            return "candidate_answer_stale"
        current_training_answer = str(current.get("training_answer") or "").strip()
        if selected_for_training and current.get("selected_for_training") is not True:
            return "training_answer_stale"
        if training_answer and current_training_answer != training_answer:
            return "training_answer_stale"
        return "ok"
    return "not_found" if not matched_by_identity else "question_stale"


def _caption_instruction_reject_duplicate_review_targets(
    rows: Sequence[Any],
    *,
    dataset_id: str,
) -> None:
    seen: Dict[Tuple[str, str, str, str, str], Tuple[int, str]] = {}
    for index, row in enumerate(rows, start=1):
        if not isinstance(row, Mapping):
            continue
        if str(row.get("format") or "").strip() != CAPTION_INSTRUCTION_REVIEW_ROWS_FORMAT:
            continue
        if not _caption_instruction_review_dataset_id_matches(row, dataset_id):
            continue
        decision = _caption_instruction_review_decision(row.get("review_decision"))
        if decision not in {"accepted", "rejected", "needs_revision"}:
            continue
        image_path = str(row.get("image_path") or row.get("image_name") or row.get("image") or "").strip()
        row_origin = str(row.get("row_origin") or "").strip()
        if not image_path or not row_origin:
            continue
        key = _caption_instruction_review_target_key(row)
        prior = seen.get(key)
        if prior is None:
            seen[key] = (index, decision)
            continue
        prior_index, prior_decision = prior
        detail = (
            "review_rows_conflicting_duplicate_target"
            if decision != prior_decision
            else "review_rows_duplicate_target"
        )
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail=f"{detail}:row_{prior_index}:row_{index}",
        )


def _caption_instruction_apply_review_metadata(
    record: Dict[str, Any],
    row: Mapping[str, Any],
    *,
    decision: str,
    now: str,
    reviewer: str = "",
) -> None:
    metadata = dict(record.get("metadata")) if isinstance(record.get("metadata"), Mapping) else {}
    metadata.update(
        {
            "review_decision": decision,
            "review_notes": str(row.get("review_notes") or "").strip(),
            "reviewed_at": now,
            "review_imported_from": CAPTION_INSTRUCTION_REVIEW_ROWS_FORMAT,
            "review_row_origin": str(row.get("row_origin") or "").strip(),
        }
    )
    if reviewer:
        metadata["reviewer"] = reviewer
    record["metadata"] = metadata
    record["review_status"] = decision
    record["updated_at"] = now


def _caption_instruction_match_instruction_record(
    record: Mapping[str, Any],
    row: Mapping[str, Any],
    *,
    image_keys: Set[str],
) -> bool:
    record_image_key = str(record.get("image_key") or record.get("image_name") or "").strip()
    _record_image_names, record_image_keys = _caption_instruction_review_path_aliases(
        record_image_key,
        record.get("split"),
    )
    if not (record_image_keys & image_keys):
        return False
    row_question = _caption_instruction_normalized_question(row.get("question"))
    if row_question and _caption_instruction_normalized_question(record.get("question")) != row_question:
        return False
    candidate_answer = str(row.get("candidate_answer") or "").strip()
    training_answer = str(row.get("training_answer") or "").strip()
    if candidate_answer and str(record.get("answer") or "").strip() != candidate_answer:
        return False
    if not candidate_answer and training_answer and str(record.get("answer") or "").strip() != training_answer:
        return False
    qa_id = str(row.get("qa_id") or "").strip()
    record_id = str(record.get("id") or "").strip()
    if qa_id and record_id != qa_id:
        return False
    if qa_id and record_id == qa_id:
        return True
    return bool(row_question or candidate_answer or training_answer)


def _caption_instruction_match_caption_record(
    record: Mapping[str, Any],
    row: Mapping[str, Any],
    *,
    image_keys: Set[str],
) -> bool:
    record_image_key = str(record.get("image_key") or record.get("image_name") or "").strip()
    _record_image_names, record_image_keys = _caption_instruction_review_path_aliases(
        record_image_key,
        record.get("split"),
    )
    if not (record_image_keys & image_keys):
        return False
    candidate_caption = str(row.get("candidate_answer") or row.get("training_answer") or "").strip()
    if candidate_caption and str(record.get("caption") or "").strip() != candidate_caption:
        return False
    qa_id = str(row.get("qa_id") or "").strip()
    record_id = str(record.get("id") or "").strip()
    if qa_id and record_id != qa_id:
        return False
    if qa_id and record_id == qa_id:
        return True
    return bool(candidate_caption)


def _caption_instruction_review_allows_synthetic_caption0_create(
    entry: Dict[str, Any],
    row: Mapping[str, Any],
    *,
    dataset_id: str,
    image_names: Set[str],
    image_keys: Set[str],
    image_path: str,
) -> bool:
    qa_id = str(row.get("qa_id") or "").strip()
    if not re.match(r"^primary_[0-9a-f]{16}$", qa_id):
        return False
    metadata = row.get("metadata") if isinstance(row.get("metadata"), Mapping) else {}
    if metadata.get("synthetic") is not True:
        return False
    answer_source = str(row.get("answer_source") or row.get("source") or "").strip()
    if answer_source != "text_label":
        return False
    candidate_caption = str(row.get("candidate_answer") or row.get("training_answer") or "").strip()
    if not candidate_caption:
        return False
    for candidate_name in list(image_names) or [image_path]:
        split_overrides = [row.get("split"), None] if row.get("split") else [None, "train", "val"]
        for split_override in split_overrides:
            try:
                split_name, image_relpath, resolved_image_key = _dataset_caption_context(
                    entry,
                    candidate_name,
                    {"split": split_override} if split_override else None,
                )
            except Exception:
                continue
            current_caption = _annotation_effective_text_label(entry, image_relpath, split_name)
            if str(current_caption or "").strip() != candidate_caption:
                continue
            candidate_image_keys = {
                str(resolved_image_key or "").strip(),
                _dataset_caption_image_key(None, image_relpath),
            }
            if split_name:
                candidate_image_keys.add(_dataset_caption_image_key(split_name, image_relpath))
            candidate_image_keys.update(str(key or "").strip() for key in image_keys if str(key or "").strip())
            for candidate_image_key in candidate_image_keys:
                if not candidate_image_key:
                    continue
                expected_qa_id = _dataset_caption_synthetic_primary_id(
                    dataset_id=dataset_id,
                    image_key=candidate_image_key,
                    caption=candidate_caption,
                )
                if expected_qa_id == qa_id:
                    return True
    return False


def _caption_instruction_review_can_resolve_caption_context(
    entry: Dict[str, Any],
    row: Mapping[str, Any],
    *,
    image_names: Set[str],
    image_path: str,
) -> bool:
    for candidate_name in list(image_names) or [image_path]:
        split_overrides = [row.get("split"), None] if row.get("split") else [None, "train", "val"]
        for split_override in split_overrides:
            try:
                _dataset_caption_context(
                    entry,
                    candidate_name,
                    {"split": split_override} if split_override else None,
                )
                return True
            except Exception:
                continue
    return False


def _caption_instruction_reject_unmatchable_actionable_review_rows(
    entry: Dict[str, Any],
    rows: Sequence[Any],
    *,
    dataset_id: str,
    caption_records: Sequence[Mapping[str, Any]],
    instruction_records: Sequence[Mapping[str, Any]],
    current_review_rows: Sequence[Mapping[str, Any]],
) -> None:
    resolved_seen: Dict[Tuple[str, str, str, str], Tuple[int, str]] = {}
    for index, row in enumerate(rows, start=1):
        if not isinstance(row, Mapping):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_row_not_object:row_{index}",
            )
        qa_id = str(row.get("qa_id") or "").strip()
        row_origin = str(row.get("row_origin") or "").strip()
        if str(row.get("format") or "").strip() != CAPTION_INSTRUCTION_REVIEW_ROWS_FORMAT:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_invalid_format:row_{index}",
            )
        if not _caption_instruction_review_dataset_id_matches(row, dataset_id):
            continue
        decision = _caption_instruction_review_decision(row.get("review_decision"))
        if decision not in {"accepted", "rejected", "needs_revision"}:
            continue
        if row_origin == "deterministic_metadata_qa":
            continue
        image_path = str(row.get("image_path") or row.get("image_name") or row.get("image") or "").strip()
        image_names, image_keys = _caption_instruction_review_image_candidates(entry, row)
        if not image_path or not image_keys:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"review_rows_missing_image_path:row_{index}",
            )
        _caption_instruction_reject_stale_bundle_review_image(
            entry,
            row,
            row_index=index,
            image_names=image_names,
            image_path=image_path,
        )
        if row_origin == "generated_qa":
            if not qa_id:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_qa_id_missing:row_{index}",
                )
            if not _caption_instruction_review_has_current_text(row_origin, row):
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_generated_qa_text_missing:row_{index}",
                )
            matches = [
                record
                for record in instruction_records
                if _caption_instruction_match_instruction_record(record, row, image_keys=image_keys)
            ]
            if not matches:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_generated_qa_not_found:row_{index}",
                )
            if len(matches) > 1:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_generated_qa_ambiguous:row_{index}",
                )
            current_status = _caption_instruction_current_review_row_status(
                row_origin,
                row,
                image_names=image_names,
                image_keys=image_keys,
                current_review_rows=current_review_rows,
            )
            if current_status == "training_answer_stale":
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_generated_qa_training_answer_stale:row_{index}",
                )
            if current_status != "ok":
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_generated_qa_not_found:row_{index}",
                )
            resolved_key = _caption_instruction_review_resolved_target_key(row_origin, matches[0])
            prior = resolved_seen.get(resolved_key)
            if prior is not None:
                prior_index, prior_decision = prior
                detail = (
                    "review_rows_conflicting_duplicate_resolved_target"
                    if decision != prior_decision
                    else "review_rows_duplicate_resolved_target"
                )
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"{detail}:row_{prior_index}:row_{index}",
                )
            resolved_seen[resolved_key] = (index, decision)
            continue
        if row_origin == "caption0":
            if not qa_id:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_qa_id_missing:row_{index}",
                )
            if not _caption_instruction_review_has_current_text(row_origin, row):
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_caption0_answer_missing:row_{index}",
                )
            matches = [
                record
                for record in caption_records
                if _caption_instruction_match_caption_record(record, row, image_keys=image_keys)
            ]
            qa_id_known = bool(
                qa_id
                and any(str(record.get("id") or "").strip() == qa_id for record in caption_records)
            )
            if len(matches) > 1:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_caption0_ambiguous:row_{index}",
                )
            if not matches and qa_id_known:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail=f"review_rows_caption0_not_found:row_{index}",
                )
            if matches:
                current_status = _caption_instruction_current_review_row_status(
                    row_origin,
                    row,
                    image_names=image_names,
                    image_keys=image_keys,
                    current_review_rows=current_review_rows,
                )
                if current_status == "training_answer_stale":
                    raise HTTPException(
                        status_code=HTTP_400_BAD_REQUEST,
                        detail=f"review_rows_caption0_training_answer_stale:row_{index}",
                    )
                if current_status != "ok":
                    raise HTTPException(
                        status_code=HTTP_400_BAD_REQUEST,
                        detail=f"review_rows_caption0_not_found:row_{index}",
                    )
                resolved_key = _caption_instruction_review_resolved_target_key(row_origin, matches[0])
                prior = resolved_seen.get(resolved_key)
                if prior is not None:
                    prior_index, prior_decision = prior
                    detail = (
                        "review_rows_conflicting_duplicate_resolved_target"
                        if decision != prior_decision
                        else "review_rows_duplicate_resolved_target"
                    )
                    raise HTTPException(
                        status_code=HTTP_400_BAD_REQUEST,
                        detail=f"{detail}:row_{prior_index}:row_{index}",
                    )
                resolved_seen[resolved_key] = (index, decision)
                continue
            if not matches:
                caption = str(row.get("candidate_answer") or row.get("training_answer") or "").strip()
                if not caption:
                    raise HTTPException(
                        status_code=HTTP_400_BAD_REQUEST,
                        detail=f"review_rows_caption0_answer_missing:row_{index}",
                    )
                if not _caption_instruction_review_allows_synthetic_caption0_create(
                    entry,
                    row,
                    dataset_id=dataset_id,
                    image_names=image_names,
                    image_keys=image_keys,
                    image_path=image_path,
                ):
                    raise HTTPException(
                        status_code=HTTP_400_BAD_REQUEST,
                        detail=f"review_rows_caption0_creation_not_allowed:row_{index}",
                    )
                if not _caption_instruction_review_can_resolve_caption_context(
                    entry,
                    row,
                    image_names=image_names,
                    image_path=image_path,
                ):
                    raise HTTPException(
                        status_code=HTTP_400_BAD_REQUEST,
                        detail=f"review_rows_caption0_image_not_found:row_{index}",
                    )
            continue
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail=f"review_rows_unsupported_row_origin:row_{index}:{row_origin or 'missing'}",
        )


def apply_caption_instruction_review(dataset_id: str, payload: Any):
    _raise_if_qwen_caption_review_import_busy(dataset_id)
    payload = payload if payload is not None else {}
    payload_mapping = payload if isinstance(payload, Mapping) else {}
    entry = _resolve_dataset_entry(dataset_id)
    _require_dataset_annotation_lock_owner_if_active(entry, payload_mapping)
    rows = _caption_instruction_review_payload_rows(payload)
    _caption_instruction_reject_malformed_review_rows(rows)
    _caption_instruction_reject_unsupported_review_decisions(rows)
    _caption_instruction_reject_dataset_id_mismatches(rows, dataset_id=dataset_id)
    _caption_instruction_reject_duplicate_review_targets(rows, dataset_id=dataset_id)
    caption_records = _load_dataset_caption_records(entry)
    instruction_records = _load_dataset_caption_instruction_records(entry)
    current_archive = _dataset_caption_instruction_archive(
        caption_records,
        instruction_records,
        dataset_id=dataset_id,
        entry=entry,
        settings=_caption_instruction_export_settings({}),
    )
    current_review_rows = [
        row for row in (current_archive.get("instruction_review_rows") or []) if isinstance(row, Mapping)
    ]
    _caption_instruction_reject_unmatchable_actionable_review_rows(
        entry,
        rows,
        dataset_id=dataset_id,
        caption_records=caption_records,
        instruction_records=instruction_records,
        current_review_rows=current_review_rows,
    )
    if not _caption_instruction_has_persisted_actionable_review_decision(rows):
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="review_rows_no_actionable_decisions",
        )
    now = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    reviewer = str(payload_mapping.get("reviewer") or "").strip()
    used_caption_ids = {str(record.get("id") or "").strip() for record in caption_records if str(record.get("id") or "").strip()}

    caption_changed = False
    instruction_changed = False
    applied_caption_count = 0
    applied_instruction_count = 0
    created_caption_count = 0
    skipped_rows: List[Dict[str, Any]] = []

    for index, row in enumerate(rows, start=1):
        if not isinstance(row, Mapping):
            skipped_rows.append({"row_index": index, "qa_id": "", "row_origin": "", "reason": "row_not_object"})
            continue
        qa_id = str(row.get("qa_id") or "").strip()
        row_origin = str(row.get("row_origin") or "").strip()
        if str(row.get("format") or "").strip() != CAPTION_INSTRUCTION_REVIEW_ROWS_FORMAT:
            skipped_rows.append({"row_index": index, "qa_id": qa_id, "row_origin": row_origin, "reason": "invalid_format"})
            continue
        if not _caption_instruction_review_dataset_id_matches(row, dataset_id):
            skipped_rows.append({"row_index": index, "qa_id": qa_id, "row_origin": row_origin, "reason": "dataset_id_mismatch"})
            continue
        decision = _caption_instruction_review_decision(row.get("review_decision"))
        if decision not in {"accepted", "rejected", "needs_revision"}:
            skipped_rows.append({"row_index": index, "qa_id": qa_id, "row_origin": row_origin, "reason": "missing_review_decision"})
            continue
        image_path = str(row.get("image_path") or row.get("image_name") or row.get("image") or "").strip()
        image_names, image_keys = _caption_instruction_review_image_candidates(entry, row)
        if not image_path or not image_keys:
            skipped_rows.append({"row_index": index, "qa_id": qa_id, "row_origin": row_origin, "reason": "missing_image_path"})
            continue

        if row_origin == "generated_qa":
            matched = False
            for record in instruction_records:
                if not _caption_instruction_match_instruction_record(record, row, image_keys=image_keys):
                    continue
                _caption_instruction_apply_review_metadata(
                    record,
                    row,
                    decision=decision,
                    now=now,
                    reviewer=reviewer,
                )
                instruction_changed = True
                applied_instruction_count += 1
                matched = True
                break
            if not matched:
                skipped_rows.append({"row_index": index, "qa_id": qa_id, "row_origin": row_origin, "reason": "generated_qa_not_found"})
            continue

        if row_origin == "caption0":
            matched = False
            for record in caption_records:
                if not _caption_instruction_match_caption_record(record, row, image_keys=image_keys):
                    continue
                _caption_instruction_apply_review_metadata(
                    record,
                    row,
                    decision=decision,
                    now=now,
                    reviewer=reviewer,
                )
                caption_changed = True
                applied_caption_count += 1
                matched = True
                break
            if matched:
                continue
            caption = str(row.get("candidate_answer") or row.get("training_answer") or "").strip()
            if not caption:
                skipped_rows.append({"row_index": index, "qa_id": qa_id, "row_origin": row_origin, "reason": "caption0_answer_missing"})
                continue
            if not _caption_instruction_review_allows_synthetic_caption0_create(
                entry,
                row,
                dataset_id=dataset_id,
                image_names=image_names,
                image_keys=image_keys,
                image_path=image_path,
            ):
                skipped_rows.append({"row_index": index, "qa_id": qa_id, "row_origin": row_origin, "reason": "caption0_creation_not_allowed"})
                continue
            split_name: Optional[str] = None
            image_key = next(iter(sorted(image_keys)), image_path)
            image_name = image_path
            resolved_caption_context = False
            for candidate_name in list(image_names) or [image_path]:
                split_overrides = [row.get("split"), None] if row.get("split") else [None, "train", "val"]
                for split_override in split_overrides:
                    try:
                        split_name, _rel, image_key = _dataset_caption_context(
                            entry,
                            candidate_name,
                            {"split": split_override} if split_override else None,
                        )
                        image_name = candidate_name
                        resolved_caption_context = True
                        break
                    except Exception:
                        continue
                if resolved_caption_context:
                    break
            caption_id = qa_id if qa_id and qa_id not in used_caption_ids else f"cap_{uuid.uuid4().hex}"
            used_caption_ids.add(caption_id)
            record = {
                "id": caption_id,
                "image_name": image_name,
                "image": image_name,
                "image_key": image_key,
                "split": split_name or str(row.get("split") or "").strip() or None,
                "caption": caption,
                "title": "Reviewed caption0",
                "source": "text_label_review",
                "is_primary": False,
                "created_at": now,
                "updated_at": now,
                "metadata": {
                    "synthetic_source_review_qa_id": qa_id,
                    "review_decision": decision,
                    "review_notes": str(row.get("review_notes") or "").strip(),
                    "reviewed_at": now,
                    "review_imported_from": CAPTION_INSTRUCTION_REVIEW_ROWS_FORMAT,
                    "review_row_origin": row_origin,
                },
            }
            if reviewer:
                record["metadata"]["reviewer"] = reviewer
            caption_records.append(record)
            caption_changed = True
            applied_caption_count += 1
            created_caption_count += 1
            continue

        if row_origin == "deterministic_metadata_qa":
            skipped_rows.append({"row_index": index, "qa_id": qa_id, "row_origin": row_origin, "reason": "deterministic_review_not_persisted"})
            continue
        skipped_rows.append({"row_index": index, "qa_id": qa_id, "row_origin": row_origin, "reason": "unsupported_row_origin"})

    if caption_changed:
        _write_dataset_caption_records(entry, caption_records)
    if instruction_changed:
        _write_dataset_caption_instruction_records(entry, instruction_records)

    applied_count = applied_caption_count + applied_instruction_count
    return {
        "status": "applied",
        "dataset_id": dataset_id,
        "received_row_count": len(rows),
        "applied_count": applied_count,
        "caption_review_applied_count": applied_caption_count,
        "generated_qa_review_applied_count": applied_instruction_count,
        "created_caption_review_record_count": created_caption_count,
        "skipped_count": len(skipped_rows),
        "skipped_rows": skipped_rows[:50],
        "skipped_row_limit": 50,
    }


def _qwen_caption_dataset_job_log(job: QwenCaptionDatasetJob, message: str, **extra: Any) -> None:
    job.log_seq += 1
    entry = {
        "seq": job.log_seq,
        "time": time.time(),
        "message": str(message),
    }
    if extra:
        entry.update(extra)
    job.logs.append(entry)
    if len(job.logs) > 300:
        del job.logs[:-300]
    job.updated_at = time.time()


def _qwen_caption_dataset_mask_command_for_log(cmd: Sequence[Any]) -> str:
    masked: List[str] = []
    skip_next = False
    for item in cmd:
        text = str(item)
        if skip_next:
            masked.append("<configured>")
            skip_next = False
            continue
        masked.append(text)
        if text == "--openai-api-key-file":
            skip_next = True
    return " ".join(masked)


def _qwen_caption_label_counts_from_lines(
    label_lines: Sequence[str],
    labelmap: Sequence[str],
) -> Dict[str, int]:
    counts: Dict[str, int] = {}
    for line in label_lines or []:
        parts = str(line or "").split()
        if len(parts) < 5:
            continue
        try:
            class_idx = int(float(parts[0]))
        except (TypeError, ValueError):
            continue
        if 0 <= class_idx < len(labelmap):
            label = str(labelmap[class_idx] or "").strip()
        else:
            label = f"class_{class_idx}"
        if not label:
            continue
        label = {
            "LightVehicle": "Light Vehicle",
            "Solarpanels": "Solar Panels",
            "Gastank": "Gas Tank",
        }.get(label, label)
        counts[label] = counts.get(label, 0) + 1
    return counts


def _qwen_caption_dataset_cases(
    payload: QwenCaptionDatasetJobRequest,
    *,
    output_dir: Path,
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    entry = _resolve_dataset_entry(payload.dataset_id)
    manifest = _annotation_manifest_for_entry(entry)
    dataset_root = _dataset_effective_root_from_entry(entry)
    yolo_layout = str(manifest.get("yolo_layout") or entry.get("yolo_layout") or "flat")
    labelmap = [str(label or "").strip() for label in (manifest.get("labelmap") or []) if str(label or "").strip()]
    if not labelmap:
        labelmap, _glossary = _agent_load_labelmap_meta(payload.dataset_id)
    caption_request = dict(payload.caption_request or {})
    caption_mode = str(caption_request.get("caption_mode") or "full").strip().lower()
    if caption_mode not in {"full", "windowed"}:
        caption_mode = "full"
    split_filter = str(payload.split or "all").strip().lower()
    requested_names = [
        str(name or "").strip()
        for name in (payload.image_names or [])
        if str(name or "").strip()
    ]
    wanted_order: Dict[str, int] = {}
    for order_index, requested_name in enumerate(requested_names):
        wanted_order.setdefault(requested_name, order_index)
        wanted_order.setdefault(Path(requested_name).name, order_index)
        wanted_order.setdefault(Path(requested_name).stem, order_index)
    wanted_names = set(wanted_order)
    max_images = int(payload.max_images or 0)
    label_root = output_dir / "case_labels"
    cases: List[Dict[str, Any]] = []
    completion_snapshot = _qwen_caption_dataset_completion_snapshot(
        payload.dataset_id,
        payload=payload,
        entry=entry,
        manifest=manifest,
        selected_names=requested_names,
    )
    completion_by_key = {
        str(item.get("image_key") or "").strip(): item
        for item in completion_snapshot.get("images") or []
        if isinstance(item, Mapping) and str(item.get("image_key") or "").strip()
    }
    for manifest_index, row in enumerate(manifest.get("images") or [], start=1):
        split = _annotation_normalise_split(row.get("split"))
        if split_filter in {"train", "val"} and split != split_filter:
            continue
        image_relpath = _annotation_normalise_image_relpath(
            row.get("image_relpath") or row.get("image_name")
        )
        image_name = str(row.get("image_name") or image_relpath.name)
        selectors = {
            image_name,
            image_relpath.as_posix(),
            f"{split}/{image_relpath.as_posix()}",
            Path(image_name).stem,
        }
        request_order_index: Optional[int] = None
        if wanted_names:
            matching_orders = [wanted_order[selector] for selector in selectors if selector in wanted_order]
            if not matching_orders:
                continue
            request_order_index = min(matching_orders)
        _split_for_key, _rel_for_key, image_key, _image_name_for_key = _qwen_caption_dataset_manifest_image_key(
            entry,
            manifest,
            row,
        )
        if _qwen_caption_dataset_case_is_complete(
            payload,
            completion_by_key.get(image_key, {}),
        ):
            continue
        completion_counts = dict(completion_by_key.get(image_key, {}) or {})
        generated_qa_request_count = _qwen_caption_dataset_case_generated_qa_request_count(
            payload,
            completion_counts,
        )
        image_path = _resolve_annotation_image_path(
            dataset_root,
            yolo_layout,
            split,
            image_relpath,
        )
        label_lines = [str(line or "").strip() for line in (row.get("label_lines") or []) if str(line or "").strip()]
        label_path = label_root / split / image_relpath.with_suffix(".txt")
        label_path.parent.mkdir(parents=True, exist_ok=True)
        class_counts = _qwen_caption_label_counts_from_lines(label_lines, labelmap)
        case_key = f"image:{split}/{image_relpath.as_posix()}:{caption_mode}"
        cases.append(
            {
                "_label_lines": label_lines,
                "_manifest_index": manifest_index,
                "_request_order_index": request_order_index if request_order_index is not None else manifest_index,
                "case_id": case_key,
                "stem": image_path.stem,
                "image_name": image_name,
                "image_key": image_key,
                "split": split,
                "image_relpath": image_relpath.as_posix(),
                "image_path": str(image_path),
                "label_path": str(label_path),
                "label_count": int(sum(class_counts.values())),
                "class_counts": class_counts,
                "caption_mode": caption_mode,
                "completion_counts": {
                    "base_caption_count": int(completion_counts.get("base_caption_count") or 0),
                    "generated_qa_count": int(completion_counts.get("generated_qa_count") or 0),
                    "base_caption_deficit": int(completion_counts.get("base_caption_deficit") or 0),
                    "generated_qa_deficit": int(completion_counts.get("generated_qa_deficit") or 0),
                    "missing_imposed_questions": list(completion_counts.get("missing_imposed_questions") or []),
                },
                "_generated_qa_request_count": generated_qa_request_count,
                "_openai_batch_missing_required_questions": list(
                    completion_counts.get("missing_imposed_questions") or []
                ),
            }
        )
        if not wanted_names and max_images and len(cases) >= max_images:
            break
    if wanted_names:
        cases.sort(
            key=lambda case: (
                int(case.get("_request_order_index") or 0),
                int(case.get("_manifest_index") or 0),
            )
        )
        if max_images:
            cases = cases[:max_images]
    for case_index, case in enumerate(cases, start=1):
        label_lines = [
            str(line or "").strip()
            for line in case.pop("_label_lines", [])
            if str(line or "").strip()
        ]
        case.pop("_manifest_index", None)
        case.pop("_request_order_index", None)
        case["name"] = f"image_{case_index:06d}"
        label_path = Path(str(case.get("label_path") or ""))
        label_path.parent.mkdir(parents=True, exist_ok=True)
        label_path.write_text("\n".join(label_lines) + ("\n" if label_lines else ""))
    return manifest, cases


def _qwen_caption_dataset_resume_manifest_cases(output_dir: Path) -> Optional[List[Dict[str, Any]]]:
    manifest_path = output_dir / "manifest.json"
    if not manifest_path.exists():
        return None
    try:
        manifest = json.loads(manifest_path.read_text())
    except Exception:
        return None
    if not isinstance(manifest, Mapping):
        return None
    raw_cases = manifest.get("cases")
    if not isinstance(raw_cases, list):
        return None
    cases = [dict(case) for case in raw_cases if isinstance(case, Mapping)]
    return cases or None


def _qwen_caption_dataset_preview_runner_args(
    payload: QwenCaptionDatasetJobRequest,
    *,
    request_path: Path,
    caption_request_fields: Mapping[str, Any],
    caption_runner_model_fields: Mapping[str, Any],
) -> Any:
    from tools import run_qwen_caption_flow_benchmark as caption_runner

    args_data = dict(caption_runner.RUN_SETTINGS_ARG_DEFAULTS)
    args_data.update(
        {
            "request_json": request_path,
            "caption_provider": str(payload.caption_provider or "local_qwen"),
            "openai_model": str(payload.openai_model or "gpt-5.5"),
            "openai_image_detail": str(payload.openai_image_detail or "original"),
            "openai_reasoning_effort": _openai_caption_normalize_reasoning_effort(payload.openai_reasoning_effort),
            "openai_api_key_file": str(payload.openai_api_key_path or "openAI_API_KEY_DoNotCommit"),
            "openai_service_tier": str(payload.openai_service_tier or "batch"),
            "openai_timeout": float(payload.openai_timeout_seconds or 120.0),
            "model_id": caption_runner_model_fields["model_id"],
            "refinement_model_id": caption_runner_model_fields["refinement_model_id"],
            "fallback_model_id": caption_runner_model_fields["fallback_model_id"],
            "loop_recovery": caption_runner_model_fields["loop_recovery"],
            "windowed_full_image_strategy": str(
                caption_request_fields.get("caption_windowed_full_image_strategy") or "visual"
            ),
            "instruction_dataset": bool(payload.instruction_dataset),
            "subcaptions_per_image": _qwen_caption_dataset_effective_generated_qa_request_count(payload),
            "include_caption0_in_training": _qwen_caption_dataset_effective_include_caption0_in_training(payload),
            "include_generated_qa_in_training": bool(payload.include_generated_qa_in_training),
            "include_deterministic_metadata_qa": bool(payload.include_deterministic_metadata_qa),
            "instruction_qa_imposed_questions": list(payload.instruction_qa_imposed_questions or []),
            "instruction_qa_max_topup_attempts": int(payload.instruction_qa_max_topup_attempts or 0),
            "instruction_qa_restrict_speculative_language": bool(
                payload.instruction_qa_restrict_speculative_language
            ),
            "include_source_annotations_in_generator_context": bool(
                payload.include_source_annotations_in_generator_context
            ),
            "strict_grounding": bool(payload.strict_grounding),
            "qa_mix": str(payload.qa_mix or "balanced"),
            "answer_format": str(payload.answer_format or "natural"),
        }
    )
    return SimpleNamespace(**args_data)


def _qwen_caption_dataset_process_preview(
    payload: QwenCaptionDatasetJobRequest,
) -> QwenCaptionPromptPreviewResponse:
    from tools import run_qwen_caption_flow_benchmark as caption_runner

    _preflight_openai_caption_provider_request(payload)
    with tempfile.TemporaryDirectory(prefix="qwen_caption_dataset_preview_") as tmp:
        preview_root = Path(tmp)
        manifest, cases = _qwen_caption_dataset_cases(payload, output_dir=preview_root)
        if not cases:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="qwen_caption_dataset_preview_no_cases",
            )
        caption_request_fields, caption_runner_model_fields = _qwen_caption_dataset_effective_request_fields(
            payload.caption_request or {},
            set_and_forget=bool(payload.set_and_forget),
        )
        request_path = preview_root / "request_fields.json"
        request_path.write_text(json.dumps(caption_request_fields, indent=2, sort_keys=True))
        args = _qwen_caption_dataset_preview_runner_args(
            payload,
            request_path=request_path,
            caption_request_fields=caption_request_fields,
            caption_runner_model_fields=caption_runner_model_fields,
        )
        dataset_entry = _resolve_dataset_entry(payload.dataset_id)
        dataset_root = Path(_dataset_effective_root_from_entry(dataset_entry))
        first_case = dict(cases[0])
        request_data = caption_runner.case_payload(first_case, dataset_root, args)
        is_openai_batch = (
            str(payload.caption_provider or "").strip().lower() == "openai"
            and str(payload.openai_service_tier or "").strip().lower() == "batch"
        )
        caption_preview = qwen_caption_prompt_preview(QwenCaptionRequest(**request_data))
        sections = [] if is_openai_batch else list(caption_preview.sections)
        warnings = [] if is_openai_batch else list(caption_preview.warnings)
        meta = {} if is_openai_batch else dict(caption_preview.meta or {})
        total_cases = len(cases)
        first_image = str(first_case.get("image_name") or first_case.get("image_relpath") or "")
        meta["dataset_preview"] = {
            "dataset_id": payload.dataset_id,
            "dataset_label": manifest.get("dataset_label") or payload.dataset_id,
            "total_cases": total_cases,
            "first_case": first_case.get("name"),
            "first_image_name": first_image,
            "selected_image_order": list(payload.image_names or [])[:25],
            "selected_image_order_limit": 25,
            "instruction_dataset": bool(payload.instruction_dataset),
            "caption_provider": str(payload.caption_provider or "local_qwen"),
            "openai_model": str(payload.openai_model or "gpt-5.5"),
            "openai_image_detail": str(payload.openai_image_detail or "original"),
            "openai_reasoning_effort": _openai_caption_normalize_reasoning_effort(payload.openai_reasoning_effort),
            "openai_api_key_file_configured": bool(str(payload.openai_api_key_path or "").strip()),
            "openai_service_tier": str(payload.openai_service_tier or "batch"),
            "run_kind": str(payload.run_kind or "production"),
            "write_policy": str(payload.write_policy or "fill_missing"),
            "completion_mode": str(payload.completion_mode or "per_image_totals"),
            "target_base_captions_per_image": int(payload.target_base_captions_per_image or 0),
            "target_generated_qa_per_image": int(payload.target_generated_qa_per_image or 0),
            "increment_base_captions_per_image": int(payload.increment_base_captions_per_image or 0),
            "increment_generated_qa_per_image": int(payload.increment_generated_qa_per_image or 0),
            "effective_subcaptions_per_image": _qwen_caption_dataset_effective_generated_qa_request_count(payload),
            "effective_include_caption0_in_training": _qwen_caption_dataset_effective_include_caption0_in_training(payload),
            "test_outputs_count_toward_completion": bool(payload.test_outputs_count_toward_completion),
            "include_caption0_in_training": bool(payload.include_caption0_in_training),
            "include_generated_qa_in_training": bool(payload.include_generated_qa_in_training),
            "include_deterministic_metadata_qa": bool(payload.include_deterministic_metadata_qa),
            "instruction_qa_imposed_questions": list(payload.instruction_qa_imposed_questions or []),
        }

        requested_qa = caption_runner._instruction_qa_requested_count(args)
        if is_openai_batch:
            from tools import run_openai_caption_batch_smoke as batch_smoke

            batch_args = _openai_caption_batch_args(payload, request_path=request_path)
            prompt_context = batch_smoke.build_batch_prompt_context(
                case=first_case,
                dataset_root=dataset_root,
                args=batch_args,
            )
            batch_section = _qwen_caption_prompt_preview_section(
                title="OpenAI Batch combined caption+QA prompt template",
                kind="prompt",
                model_id=str(batch_args.model or payload.openai_model or "gpt-5.5"),
                system_prompt=None,
                user_prompt=str(prompt_context.get("prompt") or ""),
                note=(
                    "This is the input_text sent beside the image file in each OpenAI Batch "
                    "Responses request. Batch mode asks for caption0 and generated QA rows "
                    "together; incomplete rows are handled later by visual Catch up QA Batch jobs."
                ),
                image_region={
                    "x": 0,
                    "y": 0,
                    "width": request_data.get("image_width"),
                    "height": request_data.get("image_height"),
                    "image_width": request_data.get("image_width"),
                    "image_height": request_data.get("image_height"),
                    "image_name": first_image,
                    "kind": "full_image",
                    "openai_image_detail": str(batch_args.image_detail or payload.openai_image_detail or "original"),
                },
            )
            sections.append(batch_section)
            batch_prompt_text = _qwen_caption_preview_section_prompt_text(batch_section)
            batch_prompt_tokens = _estimate_qwen_prompt_tokens(batch_prompt_text)
            batch_prompt_chars = len(batch_prompt_text)
            try:
                batch_max_output_tokens = int(batch_args.max_output_tokens or 0)
            except (TypeError, ValueError, OverflowError):
                batch_max_output_tokens = 0
            meta["prompt_budget"] = {
                "provider": "openai",
                "service_tier": "batch",
                "sections": [
                    {
                        "title": batch_section.title,
                        "kind": batch_section.kind,
                        "model_id": batch_section.model_id or None,
                        "prompt_chars": batch_prompt_chars,
                        "estimated_prompt_tokens": batch_prompt_tokens,
                        "requested_max_output_tokens": batch_max_output_tokens,
                        "effective_max_output_tokens": batch_max_output_tokens,
                        "adapted": False,
                    }
                ],
                "total_prompt_chars": batch_prompt_chars,
                "max_prompt_tokens": batch_prompt_tokens,
                "max_prompt_section": batch_section.title,
                "includes_openai_batch_combined_prompt": True,
                "includes_generated_qa_verifier_prompt": False,
            }
            meta["instruction_qa_prompt"] = {
                "requested": int(prompt_context.get("target_qa") or requested_qa or 0),
                "batch_combined_request": True,
                "imposed_question_count": len(prompt_context.get("imposed_questions") or []),
                "qa_mix": prompt_context.get("qa_mix"),
                "answer_format": prompt_context.get("answer_format"),
                "restrict_speculative_language": bool(prompt_context.get("restrict_speculative_language")),
                "include_source_annotations_in_generator_context": bool(
                    prompt_context.get("include_source_annotations")
                ),
                "strict_grounding": bool(prompt_context.get("strict_grounding")),
                "estimated_prompt_tokens": batch_prompt_tokens,
                "max_output_tokens": batch_max_output_tokens,
                "representative_box_count": int(prompt_context.get("representative_box_count") or 0),
                "raw_label_hint_count": int(prompt_context.get("raw_label_hint_count") or 0),
                "canonical_label_hint_count": int(prompt_context.get("canonical_label_hint_count") or 0),
                "verifier": {
                    "enabled": False,
                    "reason": "openai_batch_combined_request",
                },
            }
            warnings.append(
                "OpenAI Batch preview shows the combined paid Batch prompt. It does not run the "
                "local multi-stage generated-QA verifier in the first Batch request; incomplete "
                "QA rows are handled by explicit visual Catch up QA Batch jobs."
            )
            full_text = _format_qwen_caption_prompt_preview_text(
                sections,
                warnings=warnings,
                meta=meta,
            )
            used_counts = {
                str(label): int(count)
                for label, count in dict(prompt_context.get("class_counts") or {}).items()
                if str(label).strip()
            }
            return QwenCaptionPromptPreviewResponse(
                sections=sections,
                full_text=full_text,
                used_counts=used_counts,
                used_boxes=int(prompt_context.get("representative_box_count") or 0),
                truncated=False,
                step_plan=[
                    {
                        "step": "OpenAI Batch combined visual request",
                        "detail": "One Responses Batch row per image requests caption0 and generated QA together.",
                    },
                    {
                        "step": "Collect and import",
                        "detail": "Collected complete rows are imported after target verification; incomplete rows are held for Catch up QA.",
                    },
                ],
                warnings=warnings,
                meta=meta,
            )
        if bool(payload.instruction_dataset) and requested_qa > 0:
            caption_placeholder = (
                f"<caption0 generated by the caption prompt above for {first_image or 'this image'}>"
            )
            qa_prompt_spec = caption_runner.build_instruction_qa_prompt(
                first_case,
                caption_placeholder,
                args,
            )
            qa_section = _qwen_caption_prompt_preview_section(
                title="Generated QA prompt template",
                kind="template",
                model_id=caption_runner_model_fields["model_id"],
                system_prompt=str(qa_prompt_spec.get("system_prompt") or ""),
                user_prompt=str(qa_prompt_spec.get("prompt") or ""),
                note=(
                    "Runs after caption0 is generated for each image. The preview uses a caption0 "
                    "placeholder; runtime inserts the actual generated caption."
                ),
                image_region={
                    "x": 0,
                    "y": 0,
                    "width": request_data.get("image_width"),
                    "height": request_data.get("image_height"),
                    "image_width": request_data.get("image_width"),
                    "image_height": request_data.get("image_height"),
                    "image_name": first_image,
                    "kind": "full_image",
                },
            )
            sections.append(qa_section)
            verifier_prompt = caption_runner._instruction_qa_verifier_prompt(
                candidates=[
                    {
                        "qa_id": "<generated qa id>",
                        "question": "<generated question needing verification>",
                        "answer": "<generated answer needing verification>",
                    }
                ],
                case=first_case,
                caption=caption_placeholder,
                args=args,
                source_context=qa_prompt_spec.get("source_context")
                if isinstance(qa_prompt_spec.get("source_context"), Mapping)
                else {},
                glossary_context=qa_prompt_spec.get("glossary_context")
                if isinstance(qa_prompt_spec.get("glossary_context"), Mapping)
                else {},
            )
            verifier_section = _qwen_caption_prompt_preview_section(
                title="Generated QA verifier prompt template",
                kind="template",
                model_id=caption_runner_model_fields["model_id"],
                system_prompt="You are a strict visual QA verifier. Return only valid JSON.",
                user_prompt=verifier_prompt,
                note=(
                    "Runs after generated QA. Runtime inserts candidate QA rows and the actual caption, "
                    "then accepts, rewrites, or rejects each row before training export."
                ),
                image_region={
                    "x": 0,
                    "y": 0,
                    "width": request_data.get("image_width"),
                    "height": request_data.get("image_height"),
                    "image_width": request_data.get("image_width"),
                    "image_height": request_data.get("image_height"),
                    "image_name": first_image,
                    "kind": "full_image",
                },
            )
            sections.append(verifier_section)
            qa_prompt_text = _qwen_caption_preview_section_prompt_text(qa_section)
            qa_prompt_chars = len(qa_prompt_text)
            qa_prompt_tokens = _estimate_qwen_prompt_tokens(qa_prompt_text)
            verifier_prompt_text = _qwen_caption_preview_section_prompt_text(verifier_section)
            verifier_prompt_chars = len(verifier_prompt_text)
            verifier_prompt_tokens = _estimate_qwen_prompt_tokens(verifier_prompt_text)
            try:
                qa_max_new_tokens = int(qa_prompt_spec.get("max_new_tokens") or 0)
            except (TypeError, ValueError, OverflowError):
                qa_max_new_tokens = 0
            verifier_max_new_tokens = int(getattr(caption_runner, "QA_VERIFIER_MAX_NEW_TOKENS", 2048) or 2048)
            prompt_budget = meta.get("prompt_budget")
            if isinstance(prompt_budget, Mapping):
                process_budget = dict(prompt_budget)
                raw_section_budgets = process_budget.get("sections")
                section_budgets = [
                    dict(item)
                    for item in raw_section_budgets
                    if isinstance(item, Mapping)
                ] if isinstance(raw_section_budgets, list) else []
                section_budgets.append(
                    {
                        "title": qa_section.title,
                        "kind": qa_section.kind,
                        "model_id": qa_section.model_id or None,
                        "prompt_chars": qa_prompt_chars,
                        "estimated_prompt_tokens": qa_prompt_tokens,
                        "requested_max_new_tokens": qa_max_new_tokens,
                        "effective_max_new_tokens": qa_max_new_tokens,
                        "adapted": False,
                    }
                )
                section_budgets.append(
                    {
                        "title": verifier_section.title,
                        "kind": verifier_section.kind,
                        "model_id": verifier_section.model_id or None,
                        "prompt_chars": verifier_prompt_chars,
                        "estimated_prompt_tokens": verifier_prompt_tokens,
                        "requested_max_new_tokens": verifier_max_new_tokens,
                        "effective_max_new_tokens": verifier_max_new_tokens,
                        "adapted": False,
                    }
                )
                process_budget["sections"] = section_budgets
                try:
                    existing_total_chars = int(process_budget.get("total_prompt_chars") or 0)
                except (TypeError, ValueError, OverflowError):
                    existing_total_chars = 0
                process_budget["total_prompt_chars"] = existing_total_chars + qa_prompt_chars + verifier_prompt_chars
                try:
                    existing_max_tokens = int(process_budget.get("max_prompt_tokens") or 0)
                except (TypeError, ValueError, OverflowError):
                    existing_max_tokens = 0
                if max(qa_prompt_tokens, verifier_prompt_tokens) > existing_max_tokens:
                    if verifier_prompt_tokens > qa_prompt_tokens:
                        process_budget["max_prompt_tokens"] = verifier_prompt_tokens
                        process_budget["max_prompt_section"] = verifier_section.title
                    else:
                        process_budget["max_prompt_tokens"] = qa_prompt_tokens
                        process_budget["max_prompt_section"] = qa_section.title
                elif "max_prompt_tokens" not in process_budget:
                    process_budget["max_prompt_tokens"] = existing_max_tokens
                existing_min = process_budget.get("effective_max_new_tokens_min")
                existing_max = process_budget.get("effective_max_new_tokens_max")
                try:
                    existing_min_int = int(existing_min) if existing_min is not None else qa_max_new_tokens
                except (TypeError, ValueError, OverflowError):
                    existing_min_int = qa_max_new_tokens
                try:
                    existing_max_int = int(existing_max) if existing_max is not None else qa_max_new_tokens
                except (TypeError, ValueError, OverflowError):
                    existing_max_int = qa_max_new_tokens
                if qa_max_new_tokens > 0:
                    process_budget["effective_max_new_tokens_min"] = min(existing_min_int, qa_max_new_tokens, verifier_max_new_tokens)
                    process_budget["effective_max_new_tokens_max"] = max(existing_max_int, qa_max_new_tokens, verifier_max_new_tokens)
                process_budget["includes_generated_qa_prompt"] = True
                process_budget["includes_generated_qa_verifier_prompt"] = True
                meta["prompt_budget"] = process_budget
            meta["instruction_qa_prompt"] = {
                "requested": int(qa_prompt_spec.get("requested") or 0),
                "imposed_question_count": len(qa_prompt_spec.get("imposed_questions") or []),
                "qa_mix": qa_prompt_spec.get("qa_mix"),
                "answer_format": qa_prompt_spec.get("answer_format"),
                "max_topup_attempts": int(payload.instruction_qa_max_topup_attempts or 0),
                "restrict_speculative_language": bool(
                    payload.instruction_qa_restrict_speculative_language
                ),
                "estimated_prompt_tokens": qa_prompt_tokens,
                "max_new_tokens": qa_max_new_tokens or qa_prompt_spec.get("max_new_tokens"),
                "include_source_annotations_in_generator_context": bool(
                    payload.include_source_annotations_in_generator_context
                ),
                "strict_grounding": bool(payload.strict_grounding),
                "verifier": {
                    "enabled": True,
                    "estimated_prompt_tokens": verifier_prompt_tokens,
                    "max_new_tokens": verifier_max_new_tokens,
                },
            }
            warnings.append(
                "Generated-QA prompt preview uses a caption0 placeholder because preview does not run the caption model."
            )
        elif bool(payload.instruction_dataset):
            meta["instruction_qa_prompt"] = {
                "requested": requested_qa,
                "skipped": True,
                "reason": "subcaptions_per_image is 0",
            }

        full_text = _format_qwen_caption_prompt_preview_text(
            sections,
            warnings=warnings,
            meta=meta,
        )
        return QwenCaptionPromptPreviewResponse(
            sections=sections,
            full_text=full_text,
            used_counts=caption_preview.used_counts,
            used_boxes=caption_preview.used_boxes,
            truncated=caption_preview.truncated,
            step_plan=caption_preview.step_plan,
            warnings=warnings,
            meta=meta,
        )


