def _openai_caption_normalize_reasoning_effort(value: Any) -> str:
    effort = str(value or OPENAI_CAPTION_DEFAULT_REASONING_EFFORT).strip().lower()
    return effort if effort in OPENAI_CAPTION_REASONING_EFFORTS else OPENAI_CAPTION_DEFAULT_REASONING_EFFORT


def _openai_caption_model_supports_original_detail(model: Any) -> bool:
    model_id = str(model or "gpt-5.5").strip().lower()
    if model_id in OPENAI_CAPTION_ORIGINAL_DETAIL_MODELS:
        return True
    # Future GPT-5.5 patch aliases should inherit original-detail behavior.
    return model_id.startswith("gpt-5.5-") or model_id.startswith("gpt-5.4-vision")


def _openai_caption_supported_image_details(model: Any) -> List[str]:
    details = ["auto", "high", "low"]
    if _openai_caption_model_supports_original_detail(model):
        return ["original", *details]
    return details


def _openai_caption_validate_model_detail(model: Any, detail: Any) -> str:
    model_id = str(model or "gpt-5.5").strip() or "gpt-5.5"
    requested = str(detail or "original").strip().lower()
    if requested not in OPENAI_CAPTION_IMAGE_DETAILS:
        requested = "original"
    supported = _openai_caption_supported_image_details(model_id)
    if requested not in supported:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail=(
                "openai_image_detail_unsupported:"
                f"{model_id}:{requested}:supported={','.join(supported)}"
            ),
        )
    return requested


def _openai_caption_provider_metadata() -> Dict[str, Any]:
    models = sorted(
        {
            model
            for tier in OPENAI_CAPTION_PRICING_PER_MILLION.values()
            for model in tier.keys()
        }
    )
    return {
        "default_model": "gpt-5.5",
        "default_image_detail": "original",
        "default_reasoning_effort": OPENAI_CAPTION_DEFAULT_REASONING_EFFORT,
        "reasoning_efforts": list(OPENAI_CAPTION_REASONING_EFFORTS),
        "image_detail_source": OPENAI_CAPTION_IMAGE_DETAIL_SOURCE_URL,
        "pricing_source": OPENAI_CAPTION_PRICING_SOURCE_URL,
        "pricing_last_verified": OPENAI_CAPTION_PRICING_LAST_VERIFIED,
        "pricing_per_million": OPENAI_CAPTION_PRICING_PER_MILLION,
        "cost_model": {
            "source": "static_pricing_plus_local_usage_calibration",
            "calibration_scan_limit": OPENAI_CAPTION_COST_CALIBRATION_SCAN_LIMIT,
            "calibration": _openai_caption_cost_calibration_samples(),
            "notes": [
                "Calibration is derived from locally collected OpenAI caption Batch rows with token usage.",
                "Per-caption and per-QA costs are a linear decomposition of combined caption+QA requests; run caption-only and varied-QA pilots for tighter coefficients.",
            ],
        },
        "models": [
            {
                "id": model,
                "supports_original_image_detail": _openai_caption_model_supports_original_detail(model),
                "image_details": _openai_caption_supported_image_details(model),
            }
            for model in models
        ],
    }


def _openai_caption_batch_root() -> Path:
    root = QWEN_CAPTION_DATASET_JOB_ROOT / "openai_batches"
    root.mkdir(parents=True, exist_ok=True)
    return root


def _preflight_openai_caption_provider_request(payload: QwenCaptionDatasetJobRequest) -> None:
    if str(payload.caption_provider or "local_qwen") != "openai":
        return
    _openai_caption_validate_model_detail(payload.openai_model, payload.openai_image_detail)


def _openai_caption_batch_job_dir(job_id: str) -> Path:
    safe_job_id = _sanitize_yolo_run_id_impl(job_id) or job_id
    return _openai_caption_batch_root() / safe_job_id


def _openai_caption_batch_artifact_dir(job: Mapping[str, Any]) -> Path:
    source = str(job.get("source_output_dir") or job.get("output_dir") or "").strip()
    return Path(source).expanduser().resolve(strict=False)


def _openai_caption_batch_target_manifest_path(job: Mapping[str, Any], artifact_dir: Optional[Path] = None) -> Path:
    raw = str(job.get("target_manifest") or "").strip()
    if raw:
        path = Path(raw).expanduser()
        if not path.is_absolute():
            path = (Path.cwd() / path).resolve(strict=False)
        return path.resolve(strict=False)
    base = artifact_dir if artifact_dir is not None else _openai_caption_batch_artifact_dir(job)
    return (base / "target_manifest.json").resolve(strict=False)


def _openai_caption_batch_payload_path(job_id: str) -> Path:
    return _openai_caption_batch_job_dir(job_id) / "openai_batch_job.json"


def _openai_caption_batch_now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def _openai_caption_batch_normalize_status(value: Any) -> str:
    status = str(value or "").strip().lower()
    if not status:
        return "unknown"
    return OPENAI_CAPTION_BATCH_REMOTE_STATUS_MAP.get(status, status)


def _openai_caption_batch_status_from_response(response: Mapping[str, Any]) -> str:
    return _openai_caption_batch_normalize_status(response.get("status") if isinstance(response, Mapping) else "")


def _openai_caption_batch_response_score(response: Mapping[str, Any]) -> int:
    if not isinstance(response, Mapping) or not response:
        return 0
    raw_status = str(response.get("status") or "").strip().lower()
    local_status = _openai_caption_batch_status_from_response(response)
    if local_status == "completed_remote":
        score = 900
    elif local_status in {"failed", "expired", "cancelled"}:
        score = 850
    elif raw_status in {"finalizing"}:
        score = 500
    elif local_status in OPENAI_CAPTION_BATCH_ACTIVE_STATUSES:
        score = 300
    else:
        score = 100
    if str(response.get("output_file_id") or "").strip():
        score += 80
    if str(response.get("error_file_id") or "").strip():
        score += 40
    usage = response.get("usage") if isinstance(response.get("usage"), Mapping) else {}
    usage_counts = _openai_caption_usage_counts(usage) if usage else {}
    if usage_counts.get("input_tokens") or usage_counts.get("output_tokens"):
        score += 30
    if response.get("completed_at"):
        score += 20
    if response.get("finalizing_at"):
        score += 10
    return score


def _openai_caption_batch_best_response(candidates: Sequence[Any]) -> Dict[str, Any]:
    responses = [dict(item) for item in candidates if isinstance(item, Mapping) and item]
    if not responses:
        return {}
    return max(responses, key=_openai_caption_batch_response_score)


def _openai_caption_batch_job_response_candidates(job: Mapping[str, Any]) -> List[Dict[str, Any]]:
    result = job.get("result") if isinstance(job.get("result"), Mapping) else {}
    candidates: List[Dict[str, Any]] = []
    for item in (
        result.get("batch") if isinstance(result.get("batch"), Mapping) else {},
        job.get("batch") if isinstance(job.get("batch"), Mapping) else {},
    ):
        if isinstance(item, Mapping) and item:
            candidates.append(dict(item))
    return candidates


def _openai_caption_batch_best_status_payload(job: Mapping[str, Any], artifact_dir: Path) -> Dict[str, Any]:
    candidates = _openai_caption_batch_job_response_candidates(job)
    status_payload: Dict[str, Any] = {}
    status_path = artifact_dir / "batch_status.json"
    if status_path.exists():
        try:
            loaded = json.loads(status_path.read_text(encoding="utf-8"))
            if isinstance(loaded, Mapping):
                status_payload = dict(loaded)
                response = loaded.get("response") if isinstance(loaded.get("response"), Mapping) else {}
                if response:
                    candidates.append(dict(response))
        except Exception:
            status_payload = {}
    batch_path = artifact_dir / "batch.json"
    if batch_path.exists():
        try:
            loaded = json.loads(batch_path.read_text(encoding="utf-8"))
            if isinstance(loaded, Mapping):
                response = loaded.get("response") if isinstance(loaded.get("response"), Mapping) else {}
                if response:
                    candidates.append(dict(response))
        except Exception:
            pass
    best_response = _openai_caption_batch_best_response(candidates)
    if not best_response:
        return status_payload or {"response": {}}
    current_response = status_payload.get("response") if isinstance(status_payload.get("response"), Mapping) else {}
    if _openai_caption_batch_response_score(best_response) > _openai_caption_batch_response_score(current_response):
        payload = {
            **status_payload,
            "response": best_response,
            "selected_from": "job_or_artifact_best_response",
            "selected_at": _openai_caption_batch_now(),
        }
        try:
            tmp_path = status_path.with_name(f"{status_path.name}.tmp")
            tmp_path.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
            tmp_path.replace(status_path)
        except Exception:
            logger.debug("Failed to persist best OpenAI Batch status payload", exc_info=True)
        return payload
    return status_payload or {"response": best_response}


def _qwen_caption_dataset_request_dump(payload: QwenCaptionDatasetJobRequest) -> Dict[str, Any]:
    if hasattr(payload, "model_dump"):
        return dict(payload.model_dump())
    return dict(payload.dict())


def _openai_caption_batch_write(job: Mapping[str, Any]) -> Dict[str, Any]:
    payload = dict(job)
    job_id = str(payload.get("job_id") or "").strip()
    if not job_id:
        raise ValueError("openai_caption_batch_job_id_required")
    payload["status"] = _openai_caption_batch_normalize_status(payload.get("status"))
    payload["updated_at"] = _openai_caption_batch_now()
    job_dir = _openai_caption_batch_job_dir(job_id)
    job_dir.mkdir(parents=True, exist_ok=True)
    tmp_path = job_dir / "openai_batch_job.json.tmp"
    tmp_path.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    tmp_path.replace(job_dir / "openai_batch_job.json")
    try:
        _openai_caption_batch_update_ledger_entry(payload)
    except Exception:
        logger.debug("Failed to update OpenAI caption Batch ledger", exc_info=True)
    return payload


def _openai_caption_batch_read(job_id: str) -> Dict[str, Any]:
    path = _openai_caption_batch_payload_path(job_id)
    if not path.exists():
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="openai_caption_batch_job_not_found")
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(status_code=HTTP_500_INTERNAL_SERVER_ERROR, detail="openai_caption_batch_job_corrupt") from exc
    if not isinstance(payload, Mapping):
        raise HTTPException(status_code=HTTP_500_INTERNAL_SERVER_ERROR, detail="openai_caption_batch_job_corrupt")
    out = dict(payload)
    out["status"] = _openai_caption_batch_normalize_status(out.get("status"))
    return out


def _openai_caption_batch_log(job: Mapping[str, Any], message: str, **fields: Any) -> Dict[str, Any]:
    payload = dict(job)
    entry = {
        "ts": _openai_caption_batch_now(),
        "message": str(message or "").strip(),
        **{key: value for key, value in fields.items() if value is not None},
    }
    logs = [dict(item) for item in payload.get("logs") or [] if isinstance(item, Mapping)]
    logs.append(entry)
    payload["logs"] = logs[-200:]
    artifact_dir = _openai_caption_batch_artifact_dir(payload)
    try:
        artifact_dir.mkdir(parents=True, exist_ok=True)
        with (artifact_dir / "openai_batch_events.jsonl").open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(entry, sort_keys=True) + "\n")
    except Exception:
        logger.debug("Failed to append OpenAI caption batch event", exc_info=True)
    return _openai_caption_batch_write(payload)


def _openai_caption_batch_api_key(path_value: Any) -> str:
    env_key = str(os.environ.get("OPENAI_API_KEY") or "").strip()
    if env_key:
        return env_key
    raw_path = str(path_value or "openAI_API_KEY_DoNotCommit").strip()
    if not raw_path:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_api_key_not_configured")
    key_path = Path(raw_path).expanduser()
    if not key_path.is_absolute():
        key_path = (Path.cwd() / key_path).resolve(strict=False)
    if not key_path.exists():
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_api_key_not_configured")
    key = key_path.read_text(encoding="utf-8").strip()
    if not key:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_api_key_not_configured")
    return key


def _openai_caption_admin_api_key(path_value: Any) -> Tuple[str, str]:
    env_key = str(os.environ.get("OPENAI_ADMIN_KEY") or "").strip()
    if env_key:
        return env_key, "OPENAI_ADMIN_KEY"
    raw_path = str(path_value or OPENAI_CAPTION_ADMIN_KEY_DEFAULT_FILE).strip()
    if not raw_path:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_admin_key_not_configured")
    key_path = Path(raw_path).expanduser()
    if not key_path.is_absolute():
        key_path = (Path.cwd() / key_path).resolve(strict=False)
    if not key_path.exists():
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_admin_key_not_configured")
    key = key_path.read_text(encoding="utf-8").strip()
    if not key:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_admin_key_not_configured")
    return key, str(key_path)


def _openai_caption_cost_prices(model: Any, service_tier: Any) -> Dict[str, float]:
    tier = str(service_tier or "standard").strip().lower()
    if tier != "batch":
        tier = "standard"
    model_id = str(model or "gpt-5.5").strip() or "gpt-5.5"
    prices = (OPENAI_CAPTION_PRICING_PER_MILLION.get(tier) or {}).get(model_id)
    if not prices:
        prices = (OPENAI_CAPTION_PRICING_PER_MILLION.get("standard") or {}).get(model_id)
    if not prices:
        prices = (OPENAI_CAPTION_PRICING_PER_MILLION.get("standard") or {}).get("gpt-5.5")
    return dict(prices or {"input": 0.0, "output": 0.0})


def _openai_caption_usage_number(value: Any) -> int:
    try:
        number = int(value)
    except (TypeError, ValueError, OverflowError):
        return 0
    return max(0, number)


def _openai_caption_usage_counts(usage: Any) -> Dict[str, int]:
    if not isinstance(usage, Mapping):
        return {"input_tokens": 0, "output_tokens": 0, "total_tokens": 0, "cached_input_tokens": 0, "reasoning_tokens": 0}
    input_tokens = _openai_caption_usage_number(usage.get("input_tokens") or usage.get("prompt_tokens"))
    output_tokens = _openai_caption_usage_number(usage.get("output_tokens") or usage.get("completion_tokens"))
    total_tokens = _openai_caption_usage_number(usage.get("total_tokens"))
    input_details = usage.get("input_tokens_details") if isinstance(usage.get("input_tokens_details"), Mapping) else {}
    if not input_details and isinstance(usage.get("prompt_tokens_details"), Mapping):
        input_details = usage.get("prompt_tokens_details")
    output_details = usage.get("output_tokens_details") if isinstance(usage.get("output_tokens_details"), Mapping) else {}
    if not output_details and isinstance(usage.get("completion_tokens_details"), Mapping):
        output_details = usage.get("completion_tokens_details")
    cached_input = _openai_caption_usage_number((input_details or {}).get("cached_tokens") or usage.get("cached_input_tokens"))
    reasoning = _openai_caption_usage_number((output_details or {}).get("reasoning_tokens") or usage.get("reasoning_tokens"))
    if not total_tokens:
        total_tokens = input_tokens + output_tokens
    return {
        "input_tokens": input_tokens,
        "output_tokens": output_tokens,
        "total_tokens": total_tokens,
        "cached_input_tokens": cached_input,
        "reasoning_tokens": reasoning,
    }


def _openai_caption_usage_add(lhs: Mapping[str, Any], rhs: Mapping[str, Any]) -> Dict[str, int]:
    return {
        "input_tokens": _openai_caption_usage_number(lhs.get("input_tokens")) + _openai_caption_usage_number(rhs.get("input_tokens")),
        "output_tokens": _openai_caption_usage_number(lhs.get("output_tokens")) + _openai_caption_usage_number(rhs.get("output_tokens")),
        "total_tokens": _openai_caption_usage_number(lhs.get("total_tokens")) + _openai_caption_usage_number(rhs.get("total_tokens")),
        "cached_input_tokens": _openai_caption_usage_number(lhs.get("cached_input_tokens")) + _openai_caption_usage_number(rhs.get("cached_input_tokens")),
        "reasoning_tokens": _openai_caption_usage_number(lhs.get("reasoning_tokens")) + _openai_caption_usage_number(rhs.get("reasoning_tokens")),
    }


def _openai_caption_cost_from_usage(
    *,
    usage: Mapping[str, Any],
    model: Any,
    service_tier: Any,
    source: str,
    row_count: int = 0,
) -> Dict[str, Any]:
    counts = _openai_caption_usage_counts(usage)
    prices = _openai_caption_cost_prices(model, service_tier)
    input_cost = (counts["input_tokens"] / 1_000_000.0) * float(prices.get("input") or 0.0)
    output_cost = (counts["output_tokens"] / 1_000_000.0) * float(prices.get("output") or 0.0)
    total = input_cost + output_cost
    return {
        "available": bool(counts["input_tokens"] or counts["output_tokens"]),
        "source": source,
        "model": str(model or "gpt-5.5"),
        "service_tier": "batch" if str(service_tier or "").lower() == "batch" else "standard",
        "usage": counts,
        "row_count": max(0, int(row_count or 0)),
        "pricing_per_million": prices,
        "input_cost_usd": round(input_cost, 6),
        "output_cost_usd": round(output_cost, 6),
        "cost_usd": round(total, 6),
        "pricing_note": "Usage-based estimate from token counts; invoice-level spend is available through the organization Costs API.",
    }


def _openai_caption_cost_usd_for_tokens(
    *,
    input_tokens: float,
    output_tokens: float,
    model: Any,
    service_tier: Any,
) -> float:
    prices = _openai_caption_cost_prices(model, service_tier)
    return (
        (max(0.0, float(input_tokens or 0.0)) / 1_000_000.0) * float(prices.get("input") or 0.0)
        + (max(0.0, float(output_tokens or 0.0)) / 1_000_000.0) * float(prices.get("output") or 0.0)
    )


def _openai_caption_estimate_image_tokens(detail: Any) -> int:
    detail_value = str(detail or "original").strip().lower()
    if detail_value == "low":
        return 350
    if detail_value == "auto":
        return 1200
    if detail_value == "high":
        return 1600
    return 2200


def _openai_caption_static_granular_token_model(
    *,
    detail: Any,
    max_boxes: int,
) -> Dict[str, float]:
    detail_tokens = float(_openai_caption_estimate_image_tokens(detail))
    box_tokens = float(max_boxes * 35 if max_boxes > 0 else 700)
    return {
        "caption_input_tokens": 2200.0 + detail_tokens + box_tokens,
        "caption_output_tokens": 900.0,
        "qa_input_tokens": 110.0,
        "qa_output_tokens": 180.0,
        "detail_tokens": detail_tokens,
        "box_tokens": box_tokens,
    }


def _openai_caption_row_generated_qa_count(row: Mapping[str, Any]) -> int:
    explicit = _openai_caption_usage_number(
        row.get("generated_qa_requested_pair_count")
        or row.get("generated_qa_target_pair_count")
        or row.get("generated_qa_pair_count")
    )
    if explicit:
        return explicit
    pairs = row.get("generated_qa_pairs") if isinstance(row.get("generated_qa_pairs"), list) else []
    return len([item for item in pairs if isinstance(item, Mapping)])


def _openai_caption_cost_sample_from_job(job: Mapping[str, Any]) -> Dict[str, Any]:
    request_payload = QwenCaptionDatasetJobRequest(**dict(job.get("request") or {}))
    openai_meta = job.get("openai") if isinstance(job.get("openai"), Mapping) else {}
    artifact_dir = _openai_caption_batch_artifact_dir(job)
    model = str(openai_meta.get("model") or request_payload.openai_model or "gpt-5.5")
    service_tier = "batch" if str(request_payload.openai_service_tier or "").lower() == "batch" else "standard"
    detail = str(openai_meta.get("image_detail") or request_payload.openai_image_detail or "original")
    reasoning_effort = _openai_caption_normalize_reasoning_effort(
        openai_meta.get("reasoning_effort") or request_payload.openai_reasoning_effort
    )
    max_boxes = _openai_caption_usage_number(openai_meta.get("max_boxes"))
    if not max_boxes:
        caption_request = dict(request_payload.caption_request or {})
        max_boxes = _openai_caption_usage_number(caption_request.get("caption_max_boxes") or 120)
    return {
        "job_id": str(job.get("job_id") or ""),
        "artifact_dir": artifact_dir,
        "model": model,
        "service_tier": service_tier,
        "image_detail": detail,
        "reasoning_effort": reasoning_effort,
        "max_boxes": max_boxes,
    }


def _openai_caption_iter_cost_sample_rows(limit: int = OPENAI_CAPTION_COST_CALIBRATION_SCAN_LIMIT):
    root = _openai_caption_batch_root()
    if not root.exists():
        return
    visited = 0
    for payload_path in sorted(root.glob("ocap*/openai_batch_job.json"), reverse=True):
        if visited >= limit:
            break
        try:
            job = json.loads(payload_path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(job, Mapping) or str(job.get("kind") or "") != "openai_caption_batch":
            continue
        try:
            sample_meta = _openai_caption_cost_sample_from_job(job)
        except Exception:
            continue
        artifact_dir = sample_meta.get("artifact_dir")
        if not isinstance(artifact_dir, Path):
            continue
        for row_name in ("captions.jsonl", "incomplete_captions.jsonl"):
            row_path = artifact_dir / row_name
            if not row_path.exists():
                continue
            try:
                with row_path.open("r", encoding="utf-8") as handle:
                    for line in handle:
                        if visited >= limit:
                            return
                        if not line.strip():
                            continue
                        try:
                            row = json.loads(line)
                        except Exception:
                            continue
                        if not isinstance(row, Mapping):
                            continue
                        usage = _openai_caption_usage_counts(row.get("usage"))
                        if not usage.get("input_tokens") and not usage.get("output_tokens"):
                            continue
                        visited += 1
                        yield sample_meta, row, usage, row_name
            except Exception:
                logger.debug("Failed to scan OpenAI caption cost calibration rows from %s", row_path, exc_info=True)


def _openai_caption_calibration_from_totals(
    *,
    model: Any,
    service_tier: Any,
    image_detail: Any,
    reasoning_effort: Any,
    max_boxes: int,
    row_count: int,
    qa_count_total: int,
    input_tokens: int,
    output_tokens: int,
    source: str,
    sample_job_ids: Optional[Sequence[str]] = None,
) -> Dict[str, Any]:
    rows = max(0, int(row_count or 0))
    qa_total = max(0, int(qa_count_total or 0))
    avg_qa = (float(qa_total) / float(rows)) if rows else 0.0
    avg_input = (float(input_tokens or 0) / float(rows)) if rows else 0.0
    avg_output = (float(output_tokens or 0) / float(rows)) if rows else 0.0
    static = _openai_caption_static_granular_token_model(detail=image_detail, max_boxes=max_boxes)
    static_input = static["caption_input_tokens"] + avg_qa * static["qa_input_tokens"]
    static_output = static["caption_output_tokens"] + avg_qa * static["qa_output_tokens"]
    input_scale = (avg_input / static_input) if static_input > 0 and avg_input > 0 else 1.0
    output_scale = (avg_output / static_output) if static_output > 0 and avg_output > 0 else 1.0
    caption_input = static["caption_input_tokens"] * input_scale
    caption_output = static["caption_output_tokens"] * output_scale
    qa_input = static["qa_input_tokens"] * input_scale
    qa_output = static["qa_output_tokens"] * output_scale
    caption_cost = _openai_caption_cost_usd_for_tokens(
        input_tokens=caption_input,
        output_tokens=caption_output,
        model=model,
        service_tier=service_tier,
    )
    qa_cost = _openai_caption_cost_usd_for_tokens(
        input_tokens=qa_input,
        output_tokens=qa_output,
        model=model,
        service_tier=service_tier,
    )
    observed_row_cost = _openai_caption_cost_usd_for_tokens(
        input_tokens=avg_input,
        output_tokens=avg_output,
        model=model,
        service_tier=service_tier,
    )
    return {
        "available": rows > 0 and (input_tokens > 0 or output_tokens > 0),
        "source": source,
        "model": str(model or "gpt-5.5"),
        "service_tier": "batch" if str(service_tier or "").lower() == "batch" else "standard",
        "image_detail": str(image_detail or "original"),
        "reasoning_effort": _openai_caption_normalize_reasoning_effort(reasoning_effort),
        "max_boxes": max(0, int(max_boxes or 0)),
        "row_count": rows,
        "qa_count_total": qa_total,
        "average_qa_per_row": round(avg_qa, 4),
        "average_usage_per_row": {
            "input_tokens": round(avg_input, 3),
            "output_tokens": round(avg_output, 3),
            "total_tokens": round(avg_input + avg_output, 3),
        },
        "linear_tokens": {
            "caption_input_tokens": round(caption_input, 3),
            "caption_output_tokens": round(caption_output, 3),
            "qa_input_tokens": round(qa_input, 3),
            "qa_output_tokens": round(qa_output, 3),
        },
        "cost_usd": {
            "caption": round(caption_cost, 8),
            "qa_pair": round(qa_cost, 8),
            "observed_average_row": round(observed_row_cost, 8),
            "observed_caption_plus_average_qa": round(caption_cost + avg_qa * qa_cost, 8),
        },
        "scale_factors": {
            "input": round(input_scale, 6),
            "output": round(output_scale, 6),
        },
        "static_tokens_before_calibration": {
            "caption_input_tokens": round(static["caption_input_tokens"], 3),
            "caption_output_tokens": round(static["caption_output_tokens"], 3),
            "qa_input_tokens": round(static["qa_input_tokens"], 3),
            "qa_output_tokens": round(static["qa_output_tokens"], 3),
        },
        "sample_job_ids": list(sample_job_ids or [])[:12],
        "pricing_per_million": _openai_caption_cost_prices(model, service_tier),
        "pricing_last_verified": OPENAI_CAPTION_PRICING_LAST_VERIFIED,
        "note": "Linear caption/QA decomposition calibrated from combined caption+QA response usage.",
    }


def _openai_caption_cost_calibration_samples() -> List[Dict[str, Any]]:
    root_key = str(_openai_caption_batch_root().resolve(strict=False))
    now = time.monotonic()
    cached_root = str(OPENAI_CAPTION_COST_CALIBRATION_CACHE.get("root") or "")
    cached_ts = float(OPENAI_CAPTION_COST_CALIBRATION_CACHE.get("ts") or 0.0)
    cached_samples = OPENAI_CAPTION_COST_CALIBRATION_CACHE.get("samples")
    if cached_root == root_key and isinstance(cached_samples, list) and now - cached_ts < 60.0:
        return [dict(item) for item in cached_samples if isinstance(item, Mapping)]
    grouped: Dict[Tuple[str, str, str, str, int], Dict[str, Any]] = {}
    for meta, row, usage, _row_name in _openai_caption_iter_cost_sample_rows():
        key = (
            str(meta.get("model") or "gpt-5.5"),
            str(meta.get("service_tier") or "batch"),
            str(meta.get("image_detail") or "original"),
            str(meta.get("reasoning_effort") or OPENAI_CAPTION_DEFAULT_REASONING_EFFORT),
            int(meta.get("max_boxes") or 0),
        )
        bucket = grouped.setdefault(
            key,
            {
                "model": key[0],
                "service_tier": key[1],
                "image_detail": key[2],
                "reasoning_effort": key[3],
                "max_boxes": key[4],
                "row_count": 0,
                "qa_count_total": 0,
                "input_tokens": 0,
                "output_tokens": 0,
                "sample_job_ids": [],
            },
        )
        bucket["row_count"] += 1
        bucket["qa_count_total"] += _openai_caption_row_generated_qa_count(row)
        bucket["input_tokens"] += _openai_caption_usage_number(usage.get("input_tokens"))
        bucket["output_tokens"] += _openai_caption_usage_number(usage.get("output_tokens"))
        job_id = str(meta.get("job_id") or "")
        if job_id and job_id not in bucket["sample_job_ids"]:
            bucket["sample_job_ids"].append(job_id)
    samples = [
        _openai_caption_calibration_from_totals(
            model=bucket["model"],
            service_tier=bucket["service_tier"],
            image_detail=bucket["image_detail"],
            reasoning_effort=bucket["reasoning_effort"],
            max_boxes=int(bucket["max_boxes"] or 0),
            row_count=int(bucket["row_count"] or 0),
            qa_count_total=int(bucket["qa_count_total"] or 0),
            input_tokens=int(bucket["input_tokens"] or 0),
            output_tokens=int(bucket["output_tokens"] or 0),
            source="local_collected_batch_rows",
            sample_job_ids=bucket.get("sample_job_ids") or [],
        )
        for bucket in grouped.values()
    ]
    samples = sorted(
        [sample for sample in samples if sample.get("available")],
        key=lambda item: int(item.get("row_count") or 0),
        reverse=True,
    )[:20]
    OPENAI_CAPTION_COST_CALIBRATION_CACHE.update({"root": root_key, "ts": now, "samples": samples})
    return [dict(item) for item in samples]


def _openai_caption_matching_cost_calibration(
    *,
    model: Any,
    service_tier: Any,
    image_detail: Any,
    reasoning_effort: Any,
    max_boxes: int,
) -> Dict[str, Any]:
    model_value = str(model or "gpt-5.5")
    tier_value = "batch" if str(service_tier or "").lower() == "batch" else "standard"
    detail_value = str(image_detail or "original")
    effort_value = _openai_caption_normalize_reasoning_effort(reasoning_effort)
    box_value = max(0, int(max_boxes or 0))
    samples = _openai_caption_cost_calibration_samples()
    exact = [
        sample for sample in samples
        if sample.get("model") == model_value
        and sample.get("service_tier") == tier_value
        and sample.get("image_detail") == detail_value
        and sample.get("reasoning_effort") == effort_value
        and int(sample.get("max_boxes") or 0) == box_value
    ]
    if exact:
        return dict(exact[0])
    relaxed = [
        sample for sample in samples
        if sample.get("model") == model_value
        and sample.get("service_tier") == tier_value
        and sample.get("image_detail") == detail_value
        and sample.get("reasoning_effort") == effort_value
    ]
    if relaxed:
        out = dict(relaxed[0])
        out["match"] = "model_tier_detail_effort"
        return out
    return {}


def _openai_caption_granular_cost_estimate(
    *,
    image_count: int,
    caption_count_per_image: int,
    qa_count_per_image: int,
    model: Any,
    service_tier: Any,
    image_detail: Any,
    reasoning_effort: Any,
    max_boxes: int,
    calibration: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    images = max(0, int(image_count or 0))
    captions = max(0, int(caption_count_per_image or 0))
    qa = max(0, int(qa_count_per_image or 0))
    # QA generation still needs at least one visual caption/grounding pass.
    billable_caption_units = max(captions, 1 if qa > 0 else 0)
    calibration_data = dict(calibration or {})
    if not calibration_data:
        calibration_data = _openai_caption_matching_cost_calibration(
            model=model,
            service_tier=service_tier,
            image_detail=image_detail,
            reasoning_effort=reasoning_effort,
            max_boxes=max_boxes,
        )
    if calibration_data and isinstance(calibration_data.get("linear_tokens"), Mapping):
        linear = calibration_data.get("linear_tokens") or {}
        source = "calibrated_linear_estimate"
        caption_input = float(linear.get("caption_input_tokens") or 0.0)
        caption_output = float(linear.get("caption_output_tokens") or 0.0)
        qa_input = float(linear.get("qa_input_tokens") or 0.0)
        qa_output = float(linear.get("qa_output_tokens") or 0.0)
    else:
        linear = _openai_caption_static_granular_token_model(detail=image_detail, max_boxes=max_boxes)
        source = "static_linear_estimate"
        caption_input = float(linear.get("caption_input_tokens") or 0.0)
        caption_output = float(linear.get("caption_output_tokens") or 0.0)
        qa_input = float(linear.get("qa_input_tokens") or 0.0)
        qa_output = float(linear.get("qa_output_tokens") or 0.0)
        calibration_data = {}
    total_input = images * ((billable_caption_units * caption_input) + (qa * qa_input))
    total_output = images * ((billable_caption_units * caption_output) + (qa * qa_output))
    caption_unit_cost = _openai_caption_cost_usd_for_tokens(
        input_tokens=caption_input,
        output_tokens=caption_output,
        model=model,
        service_tier=service_tier,
    )
    qa_unit_cost = _openai_caption_cost_usd_for_tokens(
        input_tokens=qa_input,
        output_tokens=qa_output,
        model=model,
        service_tier=service_tier,
    )
    total_cost = _openai_caption_cost_usd_for_tokens(
        input_tokens=total_input,
        output_tokens=total_output,
        model=model,
        service_tier=service_tier,
    )
    return {
        "available": images > 0,
        "source": source,
        "image_count": images,
        "caption_count_per_image": captions,
        "qa_count_per_image": qa,
        "billable_caption_units_per_image": billable_caption_units,
        "usage": {
            "input_tokens": int(round(total_input)),
            "output_tokens": int(round(total_output)),
            "total_tokens": int(round(total_input + total_output)),
        },
        "linear_tokens_per_unit": {
            "caption_input_tokens": round(caption_input, 3),
            "caption_output_tokens": round(caption_output, 3),
            "qa_input_tokens": round(qa_input, 3),
            "qa_output_tokens": round(qa_output, 3),
        },
        "unit_cost_usd": {
            "caption": round(caption_unit_cost, 8),
            "qa_pair": round(qa_unit_cost, 8),
            "caption_plus_qa_pair": round(caption_unit_cost + qa_unit_cost, 8),
        },
        "cost_usd": round(total_cost, 6),
        "model": str(model or "gpt-5.5"),
        "service_tier": "batch" if str(service_tier or "").lower() == "batch" else "standard",
        "image_detail": str(image_detail or "original"),
        "reasoning_effort": _openai_caption_normalize_reasoning_effort(reasoning_effort),
        "calibration": calibration_data,
        "pricing_per_million": _openai_caption_cost_prices(model, service_tier),
    }


def _openai_caption_batch_case_qa_counts(job: Mapping[str, Any], *, default_qa_count: int) -> List[int]:
    cases_path = str(job.get("cases_json") or "").strip()
    if not cases_path:
        return []
    try:
        with Path(cases_path).open("r", encoding="utf-8") as handle:
            raw_cases = json.load(handle)
    except Exception:
        return []
    if isinstance(raw_cases, Mapping):
        raw_cases = raw_cases.get("cases") or raw_cases.get("items") or []
    if not isinstance(raw_cases, list):
        return []
    counts: List[int] = []
    for case in raw_cases:
        if not isinstance(case, Mapping):
            continue
        raw_value = None
        for key in ("_generated_qa_request_count", "_openai_batch_target_qa"):
            if key in case:
                raw_value = case.get(key)
                break
        if raw_value is None:
            raw_value = default_qa_count
        try:
            count = int(raw_value)
        except (TypeError, ValueError, OverflowError):
            count = default_qa_count
        counts.append(max(0, min(count, 100)))
    return counts


def _openai_caption_batch_cost_estimate(job: Mapping[str, Any]) -> Dict[str, Any]:
    request_payload = QwenCaptionDatasetJobRequest(**dict(job.get("request") or {}))
    openai_meta = job.get("openai") if isinstance(job.get("openai"), Mapping) else {}
    model = openai_meta.get("model") or request_payload.openai_model or "gpt-5.5"
    service_tier = request_payload.openai_service_tier or "batch"
    detail = openai_meta.get("image_detail") or request_payload.openai_image_detail or "original"
    reasoning_effort = openai_meta.get("reasoning_effort") or request_payload.openai_reasoning_effort or OPENAI_CAPTION_DEFAULT_REASONING_EFFORT
    qa_count = _openai_caption_usage_number(openai_meta.get("qa_count"))
    if not qa_count:
        qa_count = _qwen_caption_dataset_effective_generated_qa_request_count(request_payload)
    max_boxes = _openai_caption_usage_number(openai_meta.get("max_boxes"))
    if not max_boxes:
        caption_request = dict(request_payload.caption_request or {})
        max_boxes = _openai_caption_usage_number(caption_request.get("caption_max_boxes") or 120)
    max_output_tokens = _openai_caption_usage_number(openai_meta.get("max_output_tokens"))
    if not max_output_tokens:
        caption_request = dict(request_payload.caption_request or {})
        max_output_tokens = _openai_caption_usage_number(
            caption_request.get("max_new_tokens") or OPENAI_CAPTION_BATCH_DEFAULT_MAX_OUTPUT_TOKENS
        )
    case_count = _openai_caption_usage_number(job.get("case_count"))
    detail_tokens = _openai_caption_estimate_image_tokens(detail)
    box_tokens = max_boxes * 35 if max_boxes > 0 else 700
    planned_case_qa_counts = _openai_caption_batch_case_qa_counts(job, default_qa_count=qa_count)
    if planned_case_qa_counts:
        case_qa_counts = planned_case_qa_counts
        case_count = len(case_qa_counts)
    else:
        case_qa_counts = [qa_count] * case_count
    if str(request_payload.completion_mode or "per_image_totals") == "incremental":
        caption_count = _qwen_caption_dataset_increment_base_caption_count(request_payload)
    else:
        caption_count = _qwen_caption_dataset_base_caption_target(request_payload)
    input_tokens = 0
    output_tokens_total = 0
    granular_rows: List[Dict[str, Any]] = []
    matching_calibration = _openai_caption_matching_cost_calibration(
        model=model,
        service_tier=service_tier,
        image_detail=detail,
        reasoning_effort=reasoning_effort,
        max_boxes=max_boxes,
    )
    for case_qa_count in case_qa_counts:
        row_estimate = _openai_caption_granular_cost_estimate(
            image_count=1,
            caption_count_per_image=caption_count,
            qa_count_per_image=case_qa_count,
            model=model,
            service_tier=service_tier,
            image_detail=detail,
            reasoning_effort=reasoning_effort,
            max_boxes=max_boxes,
            calibration=matching_calibration,
        )
        usage = row_estimate.get("usage") if isinstance(row_estimate.get("usage"), Mapping) else {}
        input_tokens += _openai_caption_usage_number(usage.get("input_tokens"))
        output_tokens_total += _openai_caption_usage_number(usage.get("output_tokens"))
        if len(granular_rows) < 5:
            granular_rows.append(row_estimate)
    usage = {
        "input_tokens": input_tokens,
        "output_tokens": output_tokens_total,
        "total_tokens": input_tokens + output_tokens_total,
    }
    estimate = _openai_caption_cost_from_usage(
        usage=usage,
        model=model,
        service_tier=service_tier,
        source=(granular_rows[0].get("source") if granular_rows else "submission_estimate"),
        row_count=case_count,
    )
    if granular_rows:
        estimate["granular"] = granular_rows[0]
    estimate["assumptions"] = {
        "case_count": case_count,
        "image_detail": str(detail or "original"),
        "caption_count_per_image": caption_count,
        "qa_count": qa_count,
        "case_qa_count_min": min(case_qa_counts) if case_qa_counts else qa_count,
        "case_qa_count_max": max(case_qa_counts) if case_qa_counts else qa_count,
        "case_qa_count_total": sum(case_qa_counts),
        "case_qa_counts_source": "cases_json" if planned_case_qa_counts else "request_default",
        "max_boxes": max_boxes,
        "max_output_tokens": max_output_tokens,
        "detail_tokens_legacy": detail_tokens,
        "box_tokens_legacy": box_tokens,
    }
    return estimate


def _openai_caption_batch_usage_from_result_rows(artifact_dir: Path) -> Dict[str, Any]:
    rows_path = artifact_dir / "results.jsonl"
    if not rows_path.exists():
        rows_path = artifact_dir / "captions.jsonl"
    usage_total = {"input_tokens": 0, "output_tokens": 0, "total_tokens": 0, "cached_input_tokens": 0, "reasoning_tokens": 0}
    row_count = 0
    try:
        with rows_path.open("r", encoding="utf-8") as handle:
            for line in handle:
                if not line.strip():
                    continue
                try:
                    row = json.loads(line)
                except Exception:
                    continue
                if not isinstance(row, Mapping):
                    continue
                counts = _openai_caption_usage_counts(row.get("usage"))
                if counts["input_tokens"] or counts["output_tokens"]:
                    row_count += 1
                    usage_total = _openai_caption_usage_add(usage_total, counts)
    except FileNotFoundError:
        pass
    except Exception:
        logger.debug("Failed to sum OpenAI caption Batch usage rows from %s", rows_path, exc_info=True)
    return {"usage": usage_total, "row_count": row_count, "path": str(rows_path)}


def _openai_caption_batch_summary_from_artifact(artifact_dir: Path) -> Dict[str, Any]:
    summary_path = artifact_dir / "summary.json"
    try:
        loaded = json.loads(summary_path.read_text(encoding="utf-8"))
    except Exception:
        loaded = {}
    if not isinstance(loaded, Mapping):
        loaded = {}
    out = dict(loaded)
    for key in (
        "total_cases",
        "output_rows",
        "error_rows",
        "failed_cases",
        "incomplete_cases",
        "missing_result_rows",
        "caption_rows",
        "incomplete_caption_rows",
        "accepted_cases",
    ):
        try:
            out[key] = max(0, int(out.get(key) or 0))
        except (TypeError, ValueError, OverflowError):
            out[key] = 0
    return out


def _openai_caption_batch_catchup_resolution(job: Mapping[str, Any]) -> Dict[str, Any]:
    catchup_id = str(job.get("last_catchup_job_id") or "").strip()
    if not catchup_id:
        return {}
    try:
        catchup = _openai_caption_batch_read(catchup_id)
    except Exception:
        return {
            "job_id": catchup_id,
            "status": "missing",
            "state": "retryable",
            "message": "A catch-up job was queued for these rows, but its local job record is missing; submit a new catch-up job or adopt the missing artifact if it exists.",
        }
    status = _openai_caption_batch_normalize_status(catchup.get("status"))
    if is_active := status in OPENAI_CAPTION_BATCH_ACTIVE_STATUSES:
        state = "active"
    elif status in {"completed_remote", "collected", "import_blocked"}:
        state = "ready"
    elif status == "imported":
        state = "resolved"
    elif status in {"failed", "partial_failed", "cancelled", "expired"}:
        state = "retryable"
    else:
        state = "unknown"
    return {
        "job_id": catchup_id,
        "status": status or "unknown",
        "state": state,
        "active": bool(is_active),
        "message": catchup.get("message"),
        "case_count": catchup.get("case_count"),
    }


def _openai_caption_batch_actual_cost(job: Mapping[str, Any]) -> Dict[str, Any]:
    request_payload = QwenCaptionDatasetJobRequest(**dict(job.get("request") or {}))
    openai_meta = job.get("openai") if isinstance(job.get("openai"), Mapping) else {}
    model = openai_meta.get("model") or request_payload.openai_model or "gpt-5.5"
    service_tier = request_payload.openai_service_tier or "batch"
    result = job.get("result") if isinstance(job.get("result"), Mapping) else {}
    batch_response = result.get("batch") if isinstance(result.get("batch"), Mapping) else {}
    if not batch_response and isinstance(job.get("batch"), Mapping):
        batch_response = job.get("batch")
    batch_usage = batch_response.get("usage") if isinstance(batch_response.get("usage"), Mapping) else {}
    batch_cost = _openai_caption_cost_from_usage(
        usage=batch_usage,
        model=model,
        service_tier=service_tier,
        source="batch_retrieve_usage",
        row_count=_openai_caption_usage_number(job.get("case_count")),
    )
    if batch_cost.get("available"):
        return batch_cost
    artifact_dir = _openai_caption_batch_artifact_dir(job)
    row_usage = _openai_caption_batch_usage_from_result_rows(artifact_dir)
    row_cost = _openai_caption_cost_from_usage(
        usage=row_usage.get("usage") or {},
        model=model,
        service_tier=service_tier,
        source="collected_response_rows",
        row_count=int(row_usage.get("row_count") or 0),
    )
    if row_usage.get("path"):
        row_cost["usage_path"] = row_usage.get("path")
    return row_cost


def _openai_caption_batch_cost_summary(job: Mapping[str, Any]) -> Dict[str, Any]:
    estimate = _openai_caption_batch_cost_estimate(job)
    actual = _openai_caption_batch_actual_cost(job)
    return {
        "estimate": estimate,
        "actual": actual,
        "updated_at": _openai_caption_batch_now(),
    }


def _openai_caption_batch_collection_cost_summary(child_jobs: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    estimate_cost = 0.0
    actual_cost = 0.0
    estimate_input = 0
    estimate_output = 0
    actual_input = 0
    actual_output = 0
    actual_available_shards = 0
    estimated_shards = 0
    for child in child_jobs:
        summary = child.get("cost_summary") if isinstance(child.get("cost_summary"), Mapping) else {}
        actual = summary.get("actual") if isinstance(summary.get("actual"), Mapping) else {}
        if not summary or not bool(actual.get("available")):
            try:
                summary = _openai_caption_batch_cost_summary(child)
            except Exception:
                summary = {}
        estimate = summary.get("estimate") if isinstance(summary.get("estimate"), Mapping) else {}
        actual = summary.get("actual") if isinstance(summary.get("actual"), Mapping) else {}
        if estimate:
            estimated_shards += 1
            estimate_cost += float(estimate.get("cost_usd") or 0.0)
            usage = estimate.get("usage") if isinstance(estimate.get("usage"), Mapping) else {}
            estimate_input += _openai_caption_usage_number(usage.get("input_tokens"))
            estimate_output += _openai_caption_usage_number(usage.get("output_tokens"))
        if actual and actual.get("available"):
            actual_available_shards += 1
            actual_cost += float(actual.get("cost_usd") or 0.0)
            usage = actual.get("usage") if isinstance(actual.get("usage"), Mapping) else {}
            actual_input += _openai_caption_usage_number(usage.get("input_tokens"))
            actual_output += _openai_caption_usage_number(usage.get("output_tokens"))
    return {
        "estimate": {
            "available": bool(estimated_shards),
            "cost_usd": round(estimate_cost, 6),
            "usage": {
                "input_tokens": estimate_input,
                "output_tokens": estimate_output,
                "total_tokens": estimate_input + estimate_output,
            },
            "shards": estimated_shards,
            "source": "child_submission_estimates",
            "pricing_note": "Sum of child Batch usage estimates.",
        },
        "actual": {
            "available": bool(actual_available_shards),
            "cost_usd": round(actual_cost, 6),
            "usage": {
                "input_tokens": actual_input,
                "output_tokens": actual_output,
                "total_tokens": actual_input + actual_output,
            },
            "shards": actual_available_shards,
            "source": "child_collected_usage",
            "pricing_note": "Sum of collected child Batch usage-based costs.",
        },
        "updated_at": _openai_caption_batch_now(),
    }


def _openai_caption_batch_job_public(
    job: Mapping[str, Any],
    *,
    dataset_id: Optional[str] = None,
    include_children: bool = False,
    include_match: bool = False,
) -> Dict[str, Any]:
    payload = dict(job)
    request = payload.get("request") if isinstance(payload.get("request"), Mapping) else {}
    # Never expose secrets; this is a backend-local path, but keep the public job payload explicit.
    if isinstance(request, Mapping):
        request_public = dict(request)
        api_key_path = ""
        for secret_key in ("openai_api_key_path", "openai_api_key_file", "openai_admin_key_path", "admin_key_path"):
            raw_secret = str(request_public.pop(secret_key, "") or "").strip()
            api_key_path = api_key_path or raw_secret
        env_key = str(os.environ.get("OPENAI_API_KEY") or "").strip()
        request_public["openai_api_key_configured"] = bool(api_key_path or env_key)
        request_public["openai_api_key_source"] = "file" if api_key_path else ("env" if env_key else "unset")
        payload["request"] = request_public
    if not isinstance(payload.get("cost_summary"), Mapping) and str(payload.get("kind") or "") == "openai_caption_batch":
        try:
            payload["cost_summary"] = _openai_caption_batch_cost_summary(payload)
        except Exception:
            logger.debug("Failed to build public OpenAI caption Batch cost summary", exc_info=True)
    if str(payload.get("kind") or "") == "openai_caption_batch":
        try:
            artifact_dir = _openai_caption_batch_artifact_dir(payload)
            summary = _openai_caption_batch_summary_from_artifact(artifact_dir)
            if summary:
                payload["output_summary"] = summary
        except Exception:
            logger.debug("Failed to attach OpenAI caption Batch output summary", exc_info=True)
        resolution = _openai_caption_batch_catchup_resolution(payload)
        if resolution:
            payload["incomplete_resolution"] = resolution
    if str(payload.get("kind") or "") == "openai_caption_batch_collection":
        try:
            payload.update(_openai_caption_batch_collection_public_fields(payload))
        except Exception:
            logger.debug("Failed to build OpenAI caption Batch collection public fields", exc_info=True)
        if include_children:
            payload["children"] = [
                _openai_caption_batch_job_public(
                    child,
                    dataset_id=dataset_id,
                    include_children=False,
                    include_match=include_match,
                )
                for child in _openai_caption_batch_collection_child_jobs(payload)
            ]
    if include_match and dataset_id and bool(payload.get("local_materialization")):
        payload["target_verification"] = {
            "reason": "local_materialization_no_remote_import",
            "match_status": "local_materialization",
            "message": "No remote Batch import is required; instruction artifacts were materialized locally.",
            "snapshot_dataset_id": payload.get("dataset_id"),
            "current_dataset_id": dataset_id,
        }
        payload["match_status"] = "local_materialization"
        payload["import_ready"] = False
    elif include_match and dataset_id:
        try:
            ok, report = _openai_caption_batch_verify_target(payload, dataset_id=dataset_id)
            payload["target_verification"] = report
            payload["match_status"] = report.get("match_status") or ("verified" if ok else "unknown")
            payload["import_ready"] = bool(ok)
        except Exception as exc:
            payload["target_verification"] = {
                "reason": "verification_error",
                "match_status": "verification_error",
                "message": str(exc),
            }
            payload["match_status"] = "verification_error"
            payload["import_ready"] = False
    return payload


def _openai_caption_batch_list_jobs(
    *,
    dataset_id: Optional[str] = None,
    include_children: bool = False,
    include_match: bool = False,
    include_archived: bool = False,
) -> List[Dict[str, Any]]:
    jobs: List[Dict[str, Any]] = []
    root = _openai_caption_batch_root()
    try:
        children = [child for child in root.iterdir() if child.is_dir()]
    except Exception:
        children = []
    for child in children:
        path = child / "openai_batch_job.json"
        if not path.exists():
            continue
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if isinstance(payload, Mapping):
            if str(payload.get("parent_job_id") or "").strip():
                continue
            if bool(payload.get("archived")) and not include_archived:
                continue
            jobs.append(
                _openai_caption_batch_job_public(
                    payload,
                    dataset_id=dataset_id,
                    include_children=include_children,
                    include_match=include_match,
                )
            )
    jobs.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    _openai_caption_batch_rebuild_ledger()
    return jobs


def _openai_caption_batch_json_sha(payload: Any) -> str:
    data = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(data.encode("utf-8")).hexdigest()


def _openai_caption_batch_label_sha(label_lines: Sequence[Any]) -> str:
    cleaned = "\n".join(str(line or "").strip() for line in label_lines if str(line or "").strip())
    if cleaned:
        cleaned += "\n"
    return hashlib.sha256(cleaned.encode("utf-8")).hexdigest()


def _openai_caption_batch_file_sha256(path: Path) -> str:
    try:
        resolved = Path(path)
        digest = hashlib.sha256()
        with resolved.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                if not chunk:
                    break
                digest.update(chunk)
        return digest.hexdigest()
    except Exception:
        return ""


def _openai_caption_batch_identity_digest(parts: Sequence[str]) -> str:
    payload = "\n".join(sorted(str(part or "") for part in parts)) + "\n"
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _openai_caption_batch_identity_from_rows(rows: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    image_parts: List[str] = []
    label_parts: List[str] = []
    image_keys: List[str] = []
    missing_image_hashes = 0
    missing_label_hashes = 0
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        image_key = str(row.get("image_key") or "").strip()
        if not image_key:
            continue
        image_sha = str(row.get("image_sha256") or "").strip()
        label_sha = str(row.get("label_sha256") or "").strip()
        image_keys.append(image_key)
        if image_sha:
            image_parts.append(f"{image_key}\0{image_sha}")
        else:
            missing_image_hashes += 1
            image_parts.append(f"{image_key}\0")
        if label_sha:
            label_parts.append(f"{image_key}\0{label_sha}")
        else:
            missing_label_hashes += 1
            label_parts.append(f"{image_key}\0")
    unique_keys = sorted(set(image_keys))
    return {
        "case_count": len(unique_keys),
        "image_fingerprint": _openai_caption_batch_identity_digest(image_parts),
        "label_fingerprint": _openai_caption_batch_identity_digest(label_parts),
        "image_hash_count": max(0, len(unique_keys) - missing_image_hashes),
        "missing_image_hash_count": missing_image_hashes,
        "label_hash_count": max(0, len(unique_keys) - missing_label_hashes),
        "missing_label_hash_count": missing_label_hashes,
        "image_keys": unique_keys[:200],
        "image_key_limit": 200,
    }


def _openai_caption_batch_current_identity_for_cases(
    cases: Sequence[Mapping[str, Any]],
    current_rows: Mapping[str, Mapping[str, Any]],
) -> Dict[str, Any]:
    rows: List[Dict[str, Any]] = []
    for case in cases:
        if not isinstance(case, Mapping):
            continue
        image_key = str(case.get("image_key") or "").strip()
        current = current_rows.get(image_key) if image_key else None
        if not isinstance(current, Mapping):
            continue
        rows.append(
            {
                "image_key": image_key,
                "image_sha256": current.get("image_sha256"),
                "label_sha256": current.get("label_sha256"),
            }
        )
    return _openai_caption_batch_identity_from_rows(rows)


def _openai_caption_batch_ledger_path() -> Path:
    return _openai_caption_batch_root() / OPENAI_CAPTION_BATCH_LEDGER_FILENAME


def _openai_caption_batch_ledger_entry(job: Mapping[str, Any]) -> Dict[str, Any]:
    request = job.get("request") if isinstance(job.get("request"), Mapping) else {}
    openai = job.get("openai") if isinstance(job.get("openai"), Mapping) else {}
    target_identity = job.get("target_identity") if isinstance(job.get("target_identity"), Mapping) else {}
    return {
        "job_id": str(job.get("job_id") or "").strip(),
        "parent_job_id": str(job.get("parent_job_id") or "").strip(),
        "kind": str(job.get("kind") or "").strip(),
        "status": str(job.get("status") or "").strip(),
        "dataset_id": str(job.get("dataset_id") or "").strip(),
        "dataset_label": str(job.get("dataset_label") or "").strip(),
        "dataset_fingerprint": str(job.get("dataset_fingerprint") or target_identity.get("image_fingerprint") or "").strip(),
        "label_fingerprint": str(job.get("label_fingerprint") or target_identity.get("label_fingerprint") or "").strip(),
        "openai_batch_id": str(job.get("openai_batch_id") or "").strip(),
        "case_count": int(job.get("case_count") or 0),
        "shard_count": int(job.get("shard_count") or 1),
        "model": str(openai.get("model") or request.get("openai_model") or "").strip(),
        "output_dir": str(job.get("output_dir") or "").strip(),
        "source_output_dir": str(job.get("source_output_dir") or "").strip(),
        "created_at": str(job.get("created_at") or "").strip(),
        "updated_at": str(job.get("updated_at") or "").strip(),
        "archived": bool(job.get("archived")),
    }


def _openai_caption_batch_update_ledger_entry(job: Mapping[str, Any]) -> None:
    job_id = str(job.get("job_id") or "").strip()
    if not job_id:
        return
    path = _openai_caption_batch_ledger_path()
    ledger: Dict[str, Any] = {"format": "tator_openai_caption_batch_ledger_v1", "jobs": {}}
    if path.exists():
        try:
            existing = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(existing, Mapping):
                ledger.update(dict(existing))
        except Exception:
            ledger = {"format": "tator_openai_caption_batch_ledger_v1", "jobs": {}}
    jobs = ledger.get("jobs") if isinstance(ledger.get("jobs"), Mapping) else {}
    jobs = dict(jobs)
    jobs[job_id] = _openai_caption_batch_ledger_entry(job)
    ledger["jobs"] = jobs
    ledger["updated_at"] = _openai_caption_batch_now()
    tmp_path = path.with_suffix(".json.tmp")
    tmp_path.write_text(json.dumps(ledger, indent=2, sort_keys=True), encoding="utf-8")
    tmp_path.replace(path)


def _openai_caption_batch_rebuild_ledger() -> Dict[str, Any]:
    jobs: Dict[str, Any] = {}
    root = _openai_caption_batch_root()
    try:
        children = [child for child in root.iterdir() if child.is_dir()]
    except Exception:
        children = []
    for child in children:
        path = child / "openai_batch_job.json"
        if not path.exists():
            continue
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if isinstance(payload, Mapping):
            entry = _openai_caption_batch_ledger_entry(payload)
            if entry.get("job_id"):
                jobs[str(entry["job_id"])] = entry
    ledger = {
        "format": "tator_openai_caption_batch_ledger_v1",
        "updated_at": _openai_caption_batch_now(),
        "jobs": jobs,
    }
    try:
        path = _openai_caption_batch_ledger_path()
        tmp_path = path.with_suffix(".json.tmp")
        tmp_path.write_text(json.dumps(ledger, indent=2, sort_keys=True), encoding="utf-8")
        tmp_path.replace(path)
    except Exception:
        logger.debug("Failed to rebuild OpenAI caption Batch ledger", exc_info=True)
    return ledger


def _openai_caption_batch_build_target_snapshot(
    *,
    dataset_id: str,
    manifest: Mapping[str, Any],
    cases: Sequence[Mapping[str, Any]],
    request_payload: Mapping[str, Any],
) -> Dict[str, Any]:
    case_items: List[Dict[str, Any]] = []
    for case in cases:
        label_path = Path(str(case.get("label_path") or ""))
        label_text = ""
        if label_path.exists():
            try:
                label_text = label_path.read_text(encoding="utf-8")
            except Exception:
                label_text = ""
        label_lines = [line.strip() for line in label_text.splitlines() if line.strip()]
        image_path = Path(str(case.get("image_path") or ""))
        image_stat: Dict[str, Any] = {}
        try:
            stat_result = image_path.stat()
            image_stat = {
                "size": int(stat_result.st_size),
                "sha256": _openai_caption_batch_file_sha256(image_path),
            }
        except Exception:
            image_stat = {"size": None, "sha256": ""}
        case_items.append(
            {
                "case_id": str(case.get("case_id") or "").strip(),
                "image_name": str(case.get("image_name") or Path(str(case.get("image_path") or "")).name).strip(),
                "image_relpath": str(case.get("image_relpath") or "").strip(),
                "split": str(case.get("split") or "").strip(),
                "image_key": str(case.get("image_key") or "").strip()
                or _dataset_caption_image_key(
                    str(case.get("split") or "").strip() or None,
                    Path(str(case.get("image_relpath") or case.get("image_name") or "")),
                ),
                "caption_mode": str(case.get("caption_mode") or "full").strip(),
                "class_counts": dict(case.get("class_counts") or {}),
                "label_count": int(case.get("label_count") or 0),
                "label_sha256": _openai_caption_batch_label_sha(label_lines),
                "image_size": image_stat.get("size"),
                "image_sha256": image_stat.get("sha256"),
            }
        )
    target_identity = _openai_caption_batch_identity_from_rows(case_items)
    snapshot = {
        "format": "tator_openai_caption_batch_target_v1",
        "created_at": _openai_caption_batch_now(),
        "dataset_id": dataset_id,
        "dataset_label": manifest.get("dataset_label"),
        "case_count": len(case_items),
        "dataset_fingerprint": target_identity.get("image_fingerprint"),
        "label_fingerprint": target_identity.get("label_fingerprint"),
        "target_identity": target_identity,
        "request": {
            "caption_provider": request_payload.get("caption_provider"),
            "openai_model": request_payload.get("openai_model"),
            "openai_image_detail": request_payload.get("openai_image_detail"),
            "openai_reasoning_effort": request_payload.get("openai_reasoning_effort"),
            "openai_service_tier": request_payload.get("openai_service_tier"),
            "write_policy": request_payload.get("write_policy"),
            "completion_mode": request_payload.get("completion_mode"),
            "run_kind": request_payload.get("run_kind"),
            "target_base_captions_per_image": request_payload.get("target_base_captions_per_image"),
            "target_generated_qa_per_image": request_payload.get("target_generated_qa_per_image"),
            "increment_base_captions_per_image": request_payload.get("increment_base_captions_per_image"),
            "increment_generated_qa_per_image": request_payload.get("increment_generated_qa_per_image"),
            "openai_batch_shard_size": request_payload.get("openai_batch_shard_size"),
            "openai_batch_require_image_hash_match": request_payload.get("openai_batch_require_image_hash_match"),
            "openai_batch_require_label_hash_match": request_payload.get("openai_batch_require_label_hash_match"),
        },
        "cases": case_items,
    }
    snapshot["target_hash"] = _openai_caption_batch_json_sha(snapshot)
    return snapshot


def _openai_caption_batch_load_json_mapping(path: Path) -> Dict[str, Any]:
    try:
        loaded = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return dict(loaded) if isinstance(loaded, Mapping) else {}


def _openai_caption_batch_load_json_list(path: Path) -> List[Dict[str, Any]]:
    try:
        loaded = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return []
    return [dict(item) for item in loaded if isinstance(item, Mapping)] if isinstance(loaded, list) else []


def _openai_caption_batch_read_jsonl(path: Path) -> List[Dict[str, Any]]:
    if not path.exists():
        return []
    rows: List[Dict[str, Any]] = []
    try:
        for line in path.read_text(encoding="utf-8").splitlines():
            if not line.strip():
                continue
            try:
                item = json.loads(line)
            except Exception:
                continue
            if isinstance(item, Mapping):
                rows.append(dict(item))
    except Exception:
        return []
    return rows


def _openai_caption_batch_text_sample(value: Any, limit: int = 1200) -> str:
    text = str(value or "")
    if len(text) <= limit:
        return text
    return text[: max(0, limit - 3)] + "..."


def _openai_caption_batch_qa_pair_sample(pair: Any) -> Dict[str, Any]:
    if not isinstance(pair, Mapping):
        return {}
    return {
        "question": _openai_caption_batch_text_sample(pair.get("question"), 500),
        "answer": _openai_caption_batch_text_sample(pair.get("answer"), 700),
    }


def _openai_caption_batch_caption_row_sample(row: Mapping[str, Any]) -> Dict[str, Any]:
    pairs = row.get("generated_qa_pairs") if isinstance(row.get("generated_qa_pairs"), list) else []
    missing_required = [
        str(question or "").strip()
        for question in (row.get("missing_required_questions") if isinstance(row.get("missing_required_questions"), list) else [])
        if str(question or "").strip()
    ]
    return {
        "case_id": row.get("case_id"),
        "image_name": row.get("image_name"),
        "final_status": row.get("final_status"),
        "failure_reason": row.get("failure_reason"),
        "caption": _openai_caption_batch_text_sample(row.get("caption"), 1600),
        "generated_qa_pair_count": row.get("generated_qa_pair_count"),
        "generated_qa_target_pair_count": row.get("generated_qa_target_pair_count"),
        "answer_format": row.get("answer_format"),
        "missing_required_questions": missing_required,
        "qa_pairs": [_openai_caption_batch_qa_pair_sample(pair) for pair in pairs[:10]],
        "qa_pair_sample_limit": 10,
    }


def _openai_caption_batch_result_row_sample(row: Mapping[str, Any]) -> Dict[str, Any]:
    return {
        "case_id": row.get("case_id"),
        "image_name": row.get("image_name"),
        "final_status": row.get("final_status"),
        "failure_reason": row.get("failure_reason"),
        "status_code": row.get("status_code"),
        "caption_chars": row.get("caption_chars"),
        "generated_qa_pair_count": row.get("generated_qa_pair_count"),
        "generated_qa_target_pair_count": row.get("generated_qa_target_pair_count"),
        "answer_format": row.get("answer_format"),
        "usage": row.get("usage") if isinstance(row.get("usage"), Mapping) else {},
        "error": row.get("error") if isinstance(row.get("error"), Mapping) else row.get("error"),
    }


def _openai_caption_batch_output_samples(artifact_dir: Path, limit: int = 5) -> Dict[str, Any]:
    accepted = _openai_caption_batch_read_jsonl(artifact_dir / "captions.jsonl")
    incomplete = _openai_caption_batch_read_jsonl(artifact_dir / "incomplete_captions.jsonl")
    results = _openai_caption_batch_read_jsonl(artifact_dir / "results.jsonl")
    return {
        "accepted_caption_rows": [_openai_caption_batch_caption_row_sample(row) for row in accepted[:limit]],
        "incomplete_caption_rows": [_openai_caption_batch_caption_row_sample(row) for row in incomplete[:limit]],
        "result_rows": [_openai_caption_batch_result_row_sample(row) for row in results[:limit]],
        "sample_limit": limit,
        "accepted_caption_row_count": len(accepted),
        "incomplete_caption_row_count": len(incomplete),
        "result_row_count": len(results),
    }


def _openai_caption_batch_instruction_artifacts_ok(job: Mapping[str, Any]) -> bool:
    result = job.get("result") if isinstance(job.get("result"), Mapping) else {}
    artifacts = result.get("instruction_artifacts") if isinstance(result.get("instruction_artifacts"), Mapping) else {}
    if str(artifacts.get("status") or "").lower() == "ok":
        return True
    report = job.get("import_report") if isinstance(job.get("import_report"), Mapping) else {}
    report_artifacts = (
        report.get("instruction_artifacts")
        if isinstance(report.get("instruction_artifacts"), Mapping)
        else {}
    )
    return str(report_artifacts.get("status") or "").lower() == "ok"


def _openai_caption_batch_materialize_instruction_artifacts(
    *,
    dataset_id: str,
    payload: QwenCaptionDatasetJobRequest,
    artifact_dir: Path,
) -> Dict[str, Any]:
    if not bool(payload.instruction_dataset):
        return {"status": "skipped", "reason": "instruction_dataset_disabled"}
    target_dir = artifact_dir / "instruction_artifacts"
    try:
        return _qwen_caption_dataset_materialize_instruction_artifacts(
            dataset_id=dataset_id,
            payload=payload,
            artifact_dir=target_dir,
        )
    except HTTPException as exc:
        return {
            "status": "error",
            "error": str(exc.detail or exc),
            "status_code": int(exc.status_code),
            "artifact_dir": str(target_dir),
        }
    except Exception as exc:  # noqa: BLE001
        return {
            "status": "error",
            "error": str(exc),
            "artifact_dir": str(target_dir),
        }


def _openai_caption_batch_attach_instruction_artifacts(
    job: Mapping[str, Any],
    *,
    dataset_id: str,
    payload: QwenCaptionDatasetJobRequest,
    import_report: Optional[Mapping[str, Any]] = None,
    force: bool = False,
) -> Dict[str, Any]:
    updated = dict(job)
    if not bool(payload.instruction_dataset):
        return updated
    if not force and _openai_caption_batch_instruction_artifacts_ok(updated):
        return updated
    artifact_dir = _openai_caption_batch_artifact_dir(updated)
    artifacts = _openai_caption_batch_materialize_instruction_artifacts(
        dataset_id=dataset_id,
        payload=payload,
        artifact_dir=artifact_dir,
    )
    result_data = dict(updated.get("result") or {}) if isinstance(updated.get("result"), Mapping) else {}
    result_data["instruction_artifacts"] = artifacts
    updated["result"] = result_data
    if import_report is not None:
        report_data = dict(import_report)
    else:
        report_data = dict(updated.get("import_report") or {}) if isinstance(updated.get("import_report"), Mapping) else {}
    if report_data:
        report_data["instruction_artifacts"] = artifacts
        updated["import_report"] = report_data
    message = (
        "OpenAI Batch training dataset artifacts materialized"
        if str(artifacts.get("status") or "").lower() == "ok"
        else "OpenAI Batch training dataset artifact materialization failed"
    )
    return _openai_caption_batch_log(updated, message, instruction_artifacts=artifacts)


def _openai_caption_batch_legacy_cases_from_artifact(source_dir: Path, manifest: Mapping[str, Any]) -> List[Dict[str, Any]]:
    direct_cases = _openai_caption_batch_load_json_list(source_dir / "cases.json")
    if direct_cases:
        return direct_cases
    manifest_cases = manifest.get("cases") if isinstance(manifest.get("cases"), list) else []
    cases = [dict(item) for item in manifest_cases if isinstance(item, Mapping)]
    if cases:
        return cases
    cases_json = str(manifest.get("cases_json") or "").strip()
    if not cases_json:
        return []
    cases_path = Path(cases_json).expanduser()
    if not cases_path.is_absolute():
        cases_path = (source_dir / cases_path).resolve(strict=False)
    return _openai_caption_batch_load_json_list(cases_path)


def _openai_caption_batch_synthesize_legacy_target_snapshot(
    *,
    source_dir: Path,
    manager_dir: Path,
    dataset_id: str,
    request_payload: Mapping[str, Any],
) -> Tuple[Dict[str, Any], str]:
    if not dataset_id:
        return {}, ""
    manifest = _openai_caption_batch_load_json_mapping(source_dir / "manifest.json")
    cases = _openai_caption_batch_legacy_cases_from_artifact(source_dir, manifest)
    if not cases:
        return {}, ""
    dataset_label = str(manifest.get("dataset_label") or "").strip()
    if not dataset_label:
        dataset_root = str(manifest.get("dataset_root") or "").strip()
        dataset_label = Path(dataset_root).name if dataset_root else dataset_id
    snapshot = _openai_caption_batch_build_target_snapshot(
        dataset_id=dataset_id,
        manifest={"dataset_label": dataset_label},
        cases=cases,
        request_payload=request_payload,
    )
    snapshot["source"] = "legacy_artifact_adoption"
    snapshot["source_artifact_dir"] = str(source_dir)
    snapshot_path = manager_dir / "target_manifest.json"
    snapshot_path.write_text(json.dumps(snapshot, indent=2, sort_keys=True), encoding="utf-8")
    return snapshot, str(snapshot_path)


def _openai_caption_batch_current_manifest_rows(
    dataset_id: str,
    selected_image_keys: Optional[Set[str]] = None,
) -> Dict[str, Dict[str, Any]]:
    entry = _resolve_dataset_entry(dataset_id)
    manifest = _annotation_manifest_for_entry(entry)
    dataset_root = _dataset_effective_root_from_entry(entry)
    yolo_layout = str(manifest.get("yolo_layout") or entry.get("yolo_layout") or "flat")
    selected = {str(key or "").strip() for key in (selected_image_keys or set()) if str(key or "").strip()}
    rows: Dict[str, Dict[str, Any]] = {}
    for row in manifest.get("images") or []:
        if not isinstance(row, Mapping):
            continue
        split, image_relpath, image_key, image_name = _qwen_caption_dataset_manifest_image_key(
            entry,
            manifest,
            row,
        )
        selectors = {image_key, image_name, image_relpath.as_posix()}
        if selected and not (selectors & selected):
            continue
        label_lines = [str(line or "").strip() for line in (row.get("label_lines") or []) if str(line or "").strip()]
        rows[image_key] = {
            "split": split,
            "image_relpath": image_relpath.as_posix(),
            "image_name": image_name,
            "label_sha256": _openai_caption_batch_label_sha(label_lines),
            "image_sha256": _openai_caption_batch_file_sha256(
                _resolve_annotation_image_path(dataset_root, yolo_layout, split, image_relpath)
            ),
        }
    return rows


def _openai_caption_batch_verify_target(
    job: Mapping[str, Any],
    dataset_id: Optional[str] = None,
    *,
    import_mode: str = "exact_only",
    selected_image_keys: Optional[Sequence[str]] = None,
) -> Tuple[bool, Dict[str, Any]]:
    artifact_dir = _openai_caption_batch_artifact_dir(job)
    target_path = _openai_caption_batch_target_manifest_path(job, artifact_dir)
    if not target_path.exists():
        return False, {
            "reason": "target_manifest_missing",
            "match_status": "unknown_missing_snapshot",
            "message": "Batch target snapshot is missing.",
        }
    try:
        snapshot = json.loads(target_path.read_text(encoding="utf-8"))
    except Exception:
        return False, {
            "reason": "target_manifest_unreadable",
            "match_status": "unknown_missing_snapshot",
            "message": "Batch target snapshot is unreadable.",
        }
    if not isinstance(snapshot, Mapping):
        return False, {
            "reason": "target_manifest_invalid",
            "match_status": "unknown_missing_snapshot",
            "message": "Batch target snapshot is invalid.",
        }
    requested_dataset = str(dataset_id or job.get("dataset_id") or "").strip()
    snapshot_dataset = str(snapshot.get("dataset_id") or "").strip()
    if not snapshot_dataset:
        return False, {
            "reason": "target_dataset_missing",
            "match_status": "unknown_missing_snapshot",
            "message": "Batch target snapshot has no dataset id.",
        }
    current_dataset_id = requested_dataset or snapshot_dataset
    selected = {str(key or "").strip() for key in (selected_image_keys or []) if str(key or "").strip()}
    snapshot_cases = [case for case in (snapshot.get("cases") or []) if isinstance(case, Mapping)]
    if not snapshot_cases:
        return False, {
            "reason": "target_cases_missing",
            "match_status": "unknown_missing_snapshot",
            "message": "Batch target snapshot has no image cases.",
            "snapshot_dataset_id": snapshot_dataset,
            "current_dataset_id": current_dataset_id,
        }
    target_lookup_keys: Set[str] = set()
    for case in snapshot_cases:
        image_key = str(case.get("image_key") or "").strip()
        selectors = {
            image_key,
            str(case.get("image_name") or "").strip(),
            str(case.get("image_relpath") or "").strip(),
        }
        selectors = {selector for selector in selectors if selector}
        if selected and not (selectors & selected):
            continue
        target_lookup_keys.update(selectors)
    try:
        current_rows = _openai_caption_batch_current_manifest_rows(
            current_dataset_id,
            selected_image_keys=target_lookup_keys or selected or set(),
        )
    except HTTPException as exc:
        return False, {
            "reason": "dataset_unavailable",
            "match_status": "current_dataset_unavailable",
            "message": str(exc.detail),
            "snapshot_dataset_id": snapshot_dataset,
            "current_dataset_id": current_dataset_id,
        }
    request_payload = QwenCaptionDatasetJobRequest(**dict(job.get("request") or {}))
    require_image_hash = bool(request_payload.openai_batch_require_image_hash_match)
    require_label_hash = bool(request_payload.openai_batch_require_label_hash_match)
    mismatches: List[Dict[str, Any]] = []
    warnings: List[Dict[str, Any]] = []
    considered_cases: List[Mapping[str, Any]] = []
    matched_cases: List[Dict[str, Any]] = []
    image_mismatch_count = 0
    label_mismatch_count = 0
    missing_count = 0

    def _current_row_for_case_selectors(selectors: Set[str]) -> Optional[Dict[str, Any]]:
        clean_selectors = {str(selector or "").strip() for selector in selectors if str(selector or "").strip()}
        for selector in clean_selectors:
            current = current_rows.get(selector)
            if isinstance(current, Mapping):
                return dict(current)
        for key, current in current_rows.items():
            if not isinstance(current, Mapping):
                continue
            current_selectors = {
                str(key or "").strip(),
                str(current.get("image_key") or "").strip(),
                str(current.get("image_name") or "").strip(),
                str(current.get("image_relpath") or "").strip(),
            }
            current_selectors = {selector for selector in current_selectors if selector}
            if clean_selectors & current_selectors:
                return dict(current)
        return None

    for case in snapshot_cases:
        image_key = str(case.get("image_key") or "").strip()
        selectors = {
            image_key,
            str(case.get("image_name") or "").strip(),
            str(case.get("image_relpath") or "").strip(),
        }
        if selected and not (selectors & selected):
            continue
        considered_cases.append(case)
        current = _current_row_for_case_selectors(selectors)
        if not current:
            missing_count += 1
            mismatches.append({"image_key": image_key, "reason": "image_missing"})
            continue
        if require_image_hash:
            submitted_image_sha = str(case.get("image_sha256") or "").strip()
            current_image_sha = str(current.get("image_sha256") or "").strip()
            if not submitted_image_sha or not current_image_sha:
                image_mismatch_count += 1
                mismatches.append(
                    {
                        "image_key": image_key,
                        "image_name": case.get("image_name"),
                        "reason": "image_sha256_missing",
                    }
                )
                continue
            if submitted_image_sha and current_image_sha and current_image_sha != submitted_image_sha:
                image_mismatch_count += 1
                mismatches.append(
                    {
                        "image_key": image_key,
                        "image_name": case.get("image_name"),
                        "reason": "image_sha256_mismatch",
                        }
                )
                continue
        matched_cases.append(
            {
                "image_key": image_key,
                "image_sha256": current.get("image_sha256"),
                "label_sha256": current.get("label_sha256"),
            }
        )
        label_mismatch = str(current.get("label_sha256") or "") != str(case.get("label_sha256") or "")
        if label_mismatch:
            label_mismatch_count += 1
            report = {
                "image_key": image_key,
                "image_name": case.get("image_name"),
                "reason": "label_sha256_mismatch",
            }
            if require_label_hash:
                mismatches.append(report)
            else:
                warnings.append(report)
    target_identity = snapshot.get("target_identity") if isinstance(snapshot.get("target_identity"), Mapping) else {}
    if selected:
        target_identity = _openai_caption_batch_identity_from_rows(
            [case for case in considered_cases if isinstance(case, Mapping)]
        )
    elif not target_identity:
        target_identity = _openai_caption_batch_identity_from_rows(
            [case for case in snapshot.get("cases") or [] if isinstance(case, Mapping)]
        )
    current_identity = _openai_caption_batch_identity_from_rows(matched_cases)
    case_count = len(considered_cases)
    matched_count = len(matched_cases)
    dataset_id_match = not requested_dataset or requested_dataset == snapshot_dataset
    same_image_fingerprint = (
        bool(target_identity.get("image_fingerprint"))
        and target_identity.get("image_fingerprint") == current_identity.get("image_fingerprint")
        and matched_count == case_count
    )
    if mismatches:
        if matched_count and (missing_count or image_mismatch_count):
            match_status = "partial_overlap"
        elif dataset_id_match and label_mismatch_count:
            match_status = "label_snapshot_mismatch"
        elif dataset_id_match:
            match_status = "same_dataset_id_image_mismatch"
        else:
            match_status = "foreign_dataset"
        return False, {
            "reason": "target_snapshot_mismatch",
            "match_status": match_status,
            "message": f"{len(mismatches)} target image or label snapshot mismatch(es).",
            "snapshot_dataset_id": snapshot_dataset,
            "current_dataset_id": current_dataset_id,
            "dataset_id_match": dataset_id_match,
            "same_image_fingerprint": same_image_fingerprint,
            "target_identity": target_identity,
            "current_identity": current_identity,
            "case_count": case_count,
            "matched_case_count": matched_count,
            "missing_case_count": missing_count,
            "image_mismatch_count": image_mismatch_count,
            "label_mismatch_count": label_mismatch_count,
            "mismatches": mismatches[:25],
            "mismatch_count": len(mismatches),
            "warnings": warnings[:25],
            "warning_count": len(warnings),
        }
    if selected and not considered_cases:
        return False, {
            "reason": "selected_images_not_in_target",
            "match_status": "partial_overlap",
            "message": "None of the selected images are present in the Batch target snapshot.",
            "snapshot_dataset_id": snapshot_dataset,
            "current_dataset_id": current_dataset_id,
            "dataset_id_match": dataset_id_match,
            "same_image_fingerprint": False,
            "target_identity": target_identity,
            "current_identity": current_identity,
            "case_count": 0,
            "matched_case_count": 0,
        }
    if not dataset_id_match:
        allowed = (
            str(import_mode or "exact_only") == "allow_same_fingerprint_dataset_id_change"
            and same_image_fingerprint
        )
        return allowed, {
            "reason": "ok" if allowed else "dataset_id_confirmation_required",
            "match_status": "same_images_different_dataset_id" if same_image_fingerprint else "foreign_dataset",
            "message": (
                "Target image identities match but the dataset id differs; explicit confirmation is required."
                if not allowed
                else "Target image identities match despite a different dataset id."
            ),
            "snapshot_dataset_id": snapshot_dataset,
            "current_dataset_id": current_dataset_id,
            "dataset_id_match": False,
            "same_image_fingerprint": same_image_fingerprint,
            "target_identity": target_identity,
            "current_identity": current_identity,
            "case_count": case_count,
            "matched_case_count": matched_count,
            "target_hash": snapshot.get("target_hash"),
            "warnings": warnings[:25],
            "warning_count": len(warnings),
        }
    result = {
        "reason": "ok",
        "match_status": "exact_dataset_match",
        "message": "Target dataset and image identities match the submitted Batch snapshot.",
        "dataset_id": snapshot_dataset,
        "snapshot_dataset_id": snapshot_dataset,
        "current_dataset_id": current_dataset_id,
        "dataset_id_match": True,
        "same_image_fingerprint": same_image_fingerprint,
        "case_count": case_count,
        "matched_case_count": matched_count,
        "target_identity": target_identity,
        "current_identity": current_identity,
        "target_hash": snapshot.get("target_hash"),
    }
    if warnings:
        result["match_status"] = "exact_dataset_match_label_warning"
        result["warnings"] = warnings[:25]
        result["warning_count"] = len(warnings)
        result["message"] = (
            "Target dataset and image identities match; "
            f"{len(warnings)} label snapshot warning(s) were recorded."
        )
    return True, result


def _openai_caption_batch_args(
    payload: QwenCaptionDatasetJobRequest,
    *,
    request_path: Path,
) -> SimpleNamespace:
    caption_request = dict(payload.caption_request or {})
    max_boxes = caption_request.get("caption_max_boxes")
    try:
        max_boxes_int = int(max_boxes if max_boxes is not None else 120)
    except (TypeError, ValueError, OverflowError):
        max_boxes_int = 120
    max_tokens = caption_request.get("max_new_tokens")
    try:
        max_tokens_int = int(max_tokens if max_tokens is not None else OPENAI_CAPTION_BATCH_DEFAULT_MAX_OUTPUT_TOKENS)
    except (TypeError, ValueError, OverflowError):
        max_tokens_int = OPENAI_CAPTION_BATCH_DEFAULT_MAX_OUTPUT_TOKENS
    max_tokens_int = max(512, min(max_tokens_int, OPENAI_CAPTION_BATCH_MAX_OUTPUT_TOKENS))
    timeout = float(payload.openai_timeout_seconds or 120.0)
    qa_count = _qwen_caption_dataset_effective_generated_qa_request_count(payload)
    imposed_questions = list(payload.instruction_qa_imposed_questions or []) if qa_count > 0 else []
    return SimpleNamespace(
        request_json=request_path,
        max_output_tokens=max_tokens_int,
        max_boxes=max(0, max_boxes_int),
        qa_count=qa_count,
        instruction_qa_imposed_questions=imposed_questions,
        instruction_qa_restrict_speculative_language=bool(payload.instruction_qa_restrict_speculative_language),
        include_source_annotations_in_generator_context=bool(payload.include_source_annotations_in_generator_context),
        strict_grounding=bool(payload.strict_grounding),
        qa_mix=str(payload.qa_mix or "balanced"),
        answer_format=str(payload.answer_format or "natural"),
        model=str(payload.openai_model or "gpt-5.5"),
        reasoning_effort=_openai_caption_normalize_reasoning_effort(payload.openai_reasoning_effort),
        image_detail=str(payload.openai_image_detail or "original"),
        timeout=max(5.0, min(timeout, 600.0)),
        upload_workers=max(1, min(int(os.environ.get("TATOR_OPENAI_BATCH_UPLOAD_WORKERS", "16") or 16), 64)),
    )


def _openai_caption_batch_refresh_from_response(job: Mapping[str, Any], batch_payload: Mapping[str, Any]) -> Dict[str, Any]:
    payload = dict(job)
    response = batch_payload.get("response") if isinstance(batch_payload.get("response"), Mapping) else batch_payload
    response = dict(response or {})
    batch_status = str(response.get("status") or "").strip().lower()
    payload["openai_status"] = batch_status
    payload["status"] = _openai_caption_batch_status_from_response(response)
    payload["openai_batch_id"] = str(response.get("id") or payload.get("openai_batch_id") or "").strip()
    payload["request_counts"] = dict(response.get("request_counts") or {})
    payload["output_file_id"] = str(response.get("output_file_id") or payload.get("output_file_id") or "").strip()
    payload["error_file_id"] = str(response.get("error_file_id") or payload.get("error_file_id") or "").strip()
    payload["result"] = {
        **(dict(payload.get("result") or {}) if isinstance(payload.get("result"), Mapping) else {}),
        "batch": response,
    }
    try:
        payload["cost_summary"] = _openai_caption_batch_cost_summary(payload)
    except Exception:
        logger.debug("Failed to update OpenAI caption Batch cost summary", exc_info=True)
    return _openai_caption_batch_write(payload)


def _openai_caption_batch_submit_worker(job_id: str) -> None:
    from tools import run_openai_caption_batch_smoke as batch_smoke

    try:
        job = _openai_caption_batch_read(job_id)
        if _openai_caption_batch_normalize_status(job.get("status")) == "cancelled":
            return
        payload = QwenCaptionDatasetJobRequest(**dict(job.get("request") or {}))
        artifact_dir = _openai_caption_batch_artifact_dir(job)
        request_path = artifact_dir / "request_fields.json"
        cases_path = artifact_dir / "cases.json"
        cases = json.loads(cases_path.read_text(encoding="utf-8"))
        if not isinstance(cases, list):
            raise RuntimeError("openai_caption_batch_cases_invalid")
        cases = [dict(case) for case in cases if isinstance(case, Mapping)]
        dataset_entry = _resolve_dataset_entry(payload.dataset_id)
        dataset_root = Path(_dataset_effective_root_from_entry(dataset_entry))
        args = _openai_caption_batch_args(payload, request_path=request_path)
        key = _openai_caption_batch_api_key(payload.openai_api_key_path)
        job = _openai_caption_batch_log(job, "uploading images", case_count=len(cases), upload_workers=args.upload_workers)
        file_rows = batch_smoke.upload_images(
            key=key,
            cases=cases,
            output_dir=artifact_dir,
            workers=args.upload_workers,
            timeout=args.timeout,
        )
        latest_job = _openai_caption_batch_read(job_id)
        if _openai_caption_batch_normalize_status(latest_job.get("status")) == "cancelled":
            _openai_caption_batch_log(latest_job, "OpenAI Batch setup stopped before submit because job was cancelled")
            return
        job = latest_job
        job = _openai_caption_batch_log(job, "writing batch input", uploaded_image_count=len(file_rows))
        batch_input = batch_smoke.write_batch_input(
            cases=cases,
            file_rows=file_rows,
            dataset_root=dataset_root,
            output_dir=artifact_dir,
            args=args,
        )
        if batch_input.stat().st_size > 200_000_000:
            raise RuntimeError(f"openai_caption_batch_input_too_large:{batch_input.stat().st_size}")
        latest_job = _openai_caption_batch_read(job_id)
        if _openai_caption_batch_normalize_status(latest_job.get("status")) == "cancelled":
            _openai_caption_batch_log(latest_job, "OpenAI Batch setup stopped before submit because job was cancelled")
            return
        job = latest_job
        job = _openai_caption_batch_log(job, "submitting OpenAI Batch", batch_input_bytes=batch_input.stat().st_size)
        batch = batch_smoke.submit_batch(
            key=key,
            batch_input=batch_input,
            output_dir=artifact_dir,
            args=args,
        )
        response = batch.get("response") if isinstance(batch.get("response"), Mapping) else {}
        job = _openai_caption_batch_refresh_from_response(job, batch)
        job = _openai_caption_batch_log(
            job,
            "OpenAI Batch submitted",
            openai_batch_id=response.get("id"),
            openai_status=response.get("status"),
        )
        batch_id = str(response.get("id") or "").strip()
        if batch_id:
            latest = batch_smoke.poll_batch(
                key=key,
                batch_id=batch_id,
                output_dir=artifact_dir,
                poll_seconds=0,
                wait_seconds=0,
                timeout=args.timeout,
            )
            _openai_caption_batch_refresh_from_response(job, latest)
    except Exception as exc:
        try:
            job = _openai_caption_batch_read(job_id)
        except Exception:
            job = {"job_id": job_id, "output_dir": str(_openai_caption_batch_job_dir(job_id))}
        error_payload = {
            "type": exc.__class__.__name__,
            "message": str(exc),
        }
        if hasattr(exc, "payload"):
            try:
                error_payload["payload"] = exc.payload()
            except Exception:
                pass
        error_blob = json.dumps(error_payload, sort_keys=True, default=str).lower()
        if (
            "billing_hard_limit_reached" in error_blob
            or "billing hard limit" in error_blob
        ) and not str(job.get("openai_batch_id") or "").strip():
            try:
                payload = QwenCaptionDatasetJobRequest(**dict(job.get("request") or {}))
                key = _openai_caption_batch_api_key(payload.openai_api_key_path)
                args = _openai_caption_batch_args(
                    payload,
                    request_path=Path(str(job.get("request_json") or _openai_caption_batch_artifact_dir(job) / "request_fields.json")),
                )
                cleanup_report = batch_smoke.cleanup_unsubmitted_uploaded_files(
                    key=key,
                    output_dir=_openai_caption_batch_artifact_dir(job),
                    timeout=args.timeout,
                    reason="billing_hard_limit_before_batch_submit",
                )
                error_payload["orphan_file_cleanup"] = cleanup_report
            except Exception as cleanup_exc:
                error_payload["orphan_file_cleanup"] = {
                    "status": "failed",
                    "type": cleanup_exc.__class__.__name__,
                    "message": str(cleanup_exc),
                }
        job = {
            **dict(job),
            "status": "failed",
            "error": error_payload,
            "message": f"OpenAI Batch setup failed: {error_payload['message']}",
        }
        _openai_caption_batch_log(job, "OpenAI Batch setup failed", error=error_payload)
        logger.exception("OpenAI caption Batch setup failed for %s", job_id)
    finally:
        with OPENAI_CAPTION_BATCH_THREADS_LOCK:
            OPENAI_CAPTION_BATCH_THREADS.pop(job_id, None)


def _openai_caption_batch_thread_alive(thread: Any) -> bool:
    is_alive = getattr(thread, "is_alive", None)
    if callable(is_alive):
        try:
            return bool(is_alive())
        except Exception:
            return False
    return bool(getattr(thread, "started", False))


def _openai_caption_batch_registered_thread_alive(job_id: str) -> bool:
    with OPENAI_CAPTION_BATCH_THREADS_LOCK:
        thread = OPENAI_CAPTION_BATCH_THREADS.get(job_id)
    return _openai_caption_batch_thread_alive(thread) if thread is not None else False


def _openai_caption_batch_submit_shard_limit() -> int:
    raw_limit = os.environ.get("TATOR_OPENAI_BATCH_SUBMIT_SHARDS", "4")
    try:
        return max(1, min(int(raw_limit or 4), 32))
    except (TypeError, ValueError, OverflowError):
        return 4


def _openai_caption_batch_submit_artifacts_present(job: Mapping[str, Any]) -> bool:
    artifact_dir = _openai_caption_batch_artifact_dir(job)
    cases_path = Path(str(job.get("cases_json") or "cases.json")).expanduser()
    request_path = Path(str(job.get("request_json") or "request_fields.json")).expanduser()
    if not cases_path.is_absolute() and not cases_path.exists():
        cases_path = artifact_dir / cases_path
    if not request_path.is_absolute() and not request_path.exists():
        request_path = artifact_dir / request_path
    return cases_path.exists() and request_path.exists()


def _openai_caption_batch_error_code(job: Mapping[str, Any]) -> str:
    error = job.get("error") if isinstance(job.get("error"), Mapping) else {}
    payload = error.get("payload") if isinstance(error.get("payload"), Mapping) else {}
    detail = payload.get("detail") if isinstance(payload.get("detail"), Mapping) else {}
    nested = detail.get("error") if isinstance(detail.get("error"), Mapping) else {}
    return str(nested.get("code") or error.get("code") or "").strip()


def _openai_caption_batch_hit_billing_hard_limit(job: Mapping[str, Any]) -> bool:
    code = _openai_caption_batch_error_code(job)
    message = str((job.get("error") if isinstance(job.get("error"), Mapping) else {}).get("message") or job.get("message") or "")
    return code == "billing_hard_limit_reached" or "billing hard limit" in message.lower()


def _openai_caption_batch_shard_size(payload: QwenCaptionDatasetJobRequest, case_count: int) -> int:
    try:
        requested = int(payload.openai_batch_shard_size or 100)
    except (TypeError, ValueError, OverflowError):
        requested = 100
    requested = max(1, min(requested, 50_000))
    if case_count <= 0:
        return requested
    return min(requested, max(1, case_count))


def _openai_caption_batch_case_chunks(
    cases: Sequence[Mapping[str, Any]],
    *,
    shard_size: int,
) -> List[List[Dict[str, Any]]]:
    safe_size = max(1, int(shard_size or 1))
    items = [dict(case) for case in cases if isinstance(case, Mapping)]
    return [items[index:index + safe_size] for index in range(0, len(items), safe_size)]


def _openai_caption_batch_start_submit_thread(job_id: str) -> bool:
    thread = threading.Thread(
        target=_openai_caption_batch_submit_worker,
        args=(job_id,),
        name=f"openai-caption-batch-{job_id}",
        daemon=True,
    )
    with OPENAI_CAPTION_BATCH_THREADS_LOCK:
        existing = OPENAI_CAPTION_BATCH_THREADS.get(job_id)
        if existing is not None and _openai_caption_batch_thread_alive(existing):
            return False
        OPENAI_CAPTION_BATCH_THREADS[job_id] = thread
    thread.start()
    return True


def _openai_caption_batch_collection_submit_worker(job_id: str) -> None:
    try:
        while True:
            try:
                parent = _openai_caption_batch_read(job_id)
            except Exception:
                return
            parent_status = _openai_caption_batch_normalize_status(parent.get("status"))
            if parent_status == "cancelled":
                return
            children = _openai_caption_batch_collection_child_jobs(parent)
            hard_limit_children = [
                child for child in children if _openai_caption_batch_hit_billing_hard_limit(child)
            ]
            if hard_limit_children:
                now = _openai_caption_batch_now()
                for child in children:
                    child_id = str(child.get("job_id") or "").strip()
                    if not child_id or str(child.get("openai_batch_id") or "").strip():
                        continue
                    child_status = _openai_caption_batch_normalize_status(child.get("status"))
                    if child_status in OPENAI_CAPTION_BATCH_FINAL_STATUSES:
                        continue
                    try:
                        payload = _openai_caption_batch_read(child_id)
                        payload["status"] = "failed"
                        payload["message"] = "OpenAI Batch setup halted before remote submission because the account billing hard limit was reached."
                        payload["updated_at"] = now
                        _openai_caption_batch_write(payload)
                    except Exception:
                        logger.debug("Failed to mark pending OpenAI caption shard failed after billing hard limit %s", child_id, exc_info=True)
                parent["status"] = "failed"
                parent["message"] = "OpenAI Batch collection halted because the account billing hard limit was reached."
                parent["updated_at"] = now
                _openai_caption_batch_log(
                    parent,
                    "OpenAI Batch collection halted by billing hard limit",
                    failed_child_count=len(hard_limit_children),
                )
                return
            child_ids = [str(child.get("job_id") or "").strip() for child in children if str(child.get("job_id") or "").strip()]
            live_child_threads = sum(1 for child_id in child_ids if _openai_caption_batch_registered_thread_alive(child_id))
            startable: List[str] = []
            for child in children:
                child_id = str(child.get("job_id") or "").strip()
                if not child_id:
                    continue
                child_status = _openai_caption_batch_normalize_status(child.get("status"))
                if child_status in OPENAI_CAPTION_BATCH_FINAL_STATUSES:
                    continue
                if str(child.get("openai_batch_id") or "").strip():
                    continue
                if not _openai_caption_batch_submit_artifacts_present(child):
                    continue
                if _openai_caption_batch_registered_thread_alive(child_id):
                    continue
                startable.append(child_id)
            slots = max(0, _openai_caption_batch_submit_shard_limit() - live_child_threads)
            started = 0
            for child_id in startable[:slots]:
                if _openai_caption_batch_start_submit_thread(child_id):
                    started += 1
            try:
                refreshed = _openai_caption_batch_refresh_collection_job(job_id)
                if started:
                    refreshed["message"] = (
                        f"Submitting OpenAI Batch shards with up to "
                        f"{_openai_caption_batch_submit_shard_limit()} concurrent shard submitter(s)."
                    )
                    _openai_caption_batch_log(
                        refreshed,
                        "OpenAI Batch collection submitter started shard workers",
                        started=started,
                        live_child_threads=live_child_threads + started,
                        pending_shards=len(startable) - started,
                    )
            except Exception:
                logger.debug("Failed to refresh OpenAI caption Batch collection submitter state", exc_info=True)
            if not startable and live_child_threads <= 0:
                try:
                    refreshed = _openai_caption_batch_refresh_collection_job(job_id)
                    _openai_caption_batch_log(refreshed, "OpenAI Batch collection submitter finished")
                except Exception:
                    logger.debug("Failed to persist OpenAI caption Batch collection submitter finish", exc_info=True)
                return
            time.sleep(2.0)
    finally:
        with OPENAI_CAPTION_BATCH_THREADS_LOCK:
            OPENAI_CAPTION_BATCH_THREADS.pop(job_id, None)


def _openai_caption_batch_start_collection_submit_thread(job_id: str) -> bool:
    thread = threading.Thread(
        target=_openai_caption_batch_collection_submit_worker,
        args=(job_id,),
        name=f"openai-caption-batch-collection-{job_id}",
        daemon=True,
    )
    with OPENAI_CAPTION_BATCH_THREADS_LOCK:
        existing = OPENAI_CAPTION_BATCH_THREADS.get(job_id)
        if existing is not None and _openai_caption_batch_thread_alive(existing):
            return False
        OPENAI_CAPTION_BATCH_THREADS[job_id] = thread
    thread.start()
    return True


def _openai_caption_batch_create_single_job(
    *,
    request_payload: QwenCaptionDatasetJobRequest,
    manifest: Mapping[str, Any],
    cases: Sequence[Mapping[str, Any]],
    caption_request_fields: Mapping[str, Any],
    job_id: str,
    parent_job_id: str = "",
    shard_index: int = 1,
    shard_count: int = 1,
    start_thread: bool = True,
) -> Dict[str, Any]:
    artifact_dir = _openai_caption_batch_job_dir(job_id)
    artifact_dir.mkdir(parents=True, exist_ok=True)
    request_path = artifact_dir / "request_fields.json"
    request_path.write_text(json.dumps(dict(caption_request_fields), indent=2, sort_keys=True), encoding="utf-8")
    clean_cases = [dict(case) for case in cases if isinstance(case, Mapping)]
    cases_path = artifact_dir / "cases.json"
    cases_path.write_text(json.dumps(clean_cases, indent=2, sort_keys=True), encoding="utf-8")
    request_snapshot = _qwen_caption_dataset_request_dump(request_payload)
    target_snapshot = _openai_caption_batch_build_target_snapshot(
        dataset_id=request_payload.dataset_id,
        manifest=manifest,
        cases=clean_cases,
        request_payload=request_snapshot,
    )
    (artifact_dir / "target_manifest.json").write_text(
        json.dumps(target_snapshot, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    args = _openai_caption_batch_args(request_payload, request_path=request_path)
    shard_label = f" shard {shard_index}/{shard_count}" if shard_count > 1 else ""
    job: Dict[str, Any] = {
        "job_id": job_id,
        "kind": "openai_caption_batch",
        "status": "preparing",
        "message": f"Preparing OpenAI Batch{shard_label} for {len(clean_cases)} image(s).",
        "dataset_id": request_payload.dataset_id,
        "dataset_label": manifest.get("dataset_label") or request_payload.dataset_id,
        "request": request_snapshot,
        "created_at": _openai_caption_batch_now(),
        "updated_at": _openai_caption_batch_now(),
        "output_dir": str(artifact_dir),
        "case_count": len(clean_cases),
        "target_hash": target_snapshot.get("target_hash"),
        "dataset_fingerprint": target_snapshot.get("dataset_fingerprint"),
        "label_fingerprint": target_snapshot.get("label_fingerprint"),
        "target_identity": target_snapshot.get("target_identity") if isinstance(target_snapshot.get("target_identity"), Mapping) else {},
        "target_manifest": str(artifact_dir / "target_manifest.json"),
        "request_json": str(request_path),
        "cases_json": str(cases_path),
        "openai": {
            "model": args.model,
            "image_detail": args.image_detail,
            "reasoning_effort": args.reasoning_effort,
            "max_output_tokens": args.max_output_tokens,
            "qa_count": args.qa_count,
            "max_boxes": args.max_boxes,
            "underlying_endpoint": "/v1/responses",
            "batch_endpoint": "/v1/batches",
        },
        "logs": [],
        "result": {},
    }
    job["cost_summary"] = _openai_caption_batch_cost_summary(job)
    if parent_job_id:
        job["parent_job_id"] = parent_job_id
        job["shard_index"] = shard_index
        job["shard_count"] = shard_count
    job = _openai_caption_batch_log(job, "OpenAI Batch job created", case_count=len(clean_cases))
    if start_thread:
        _openai_caption_batch_start_submit_thread(job_id)
    return _openai_caption_batch_job_public(_openai_caption_batch_read(job_id))


def _openai_caption_batch_create_local_materialization_job(
    *,
    request_payload: QwenCaptionDatasetJobRequest,
    manifest: Mapping[str, Any],
    job_id: str,
) -> Dict[str, Any]:
    artifact_dir = _openai_caption_batch_job_dir(job_id)
    artifact_dir.mkdir(parents=True, exist_ok=True)
    request_snapshot = _qwen_caption_dataset_request_dump(request_payload)
    target_snapshot = _openai_caption_batch_build_target_snapshot(
        dataset_id=request_payload.dataset_id,
        manifest=manifest,
        cases=[],
        request_payload=request_snapshot,
    )
    (artifact_dir / "target_manifest.json").write_text(
        json.dumps(target_snapshot, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    args = _openai_caption_batch_args(request_payload, request_path=artifact_dir / "request_fields.json")
    (artifact_dir / "request_fields.json").write_text(
        json.dumps(_qwen_caption_dataset_effective_request_fields(
            request_payload.caption_request or {},
            set_and_forget=bool(request_payload.set_and_forget),
        )[0], indent=2, sort_keys=True),
        encoding="utf-8",
    )
    (artifact_dir / "cases.json").write_text("[]\n", encoding="utf-8")
    artifacts = _openai_caption_batch_materialize_instruction_artifacts(
        dataset_id=request_payload.dataset_id,
        payload=request_payload,
        artifact_dir=artifact_dir,
    )
    artifact_ok = str(artifacts.get("status") or "").lower() == "ok"
    job: Dict[str, Any] = {
        "job_id": job_id,
        "kind": "openai_caption_batch",
        "status": "imported" if artifact_ok else "failed",
        "message": (
            "No OpenAI Batch submission was needed; deterministic training artifacts were materialized locally."
            if artifact_ok
            else "Deterministic training artifact materialization failed before OpenAI Batch submission."
        ),
        "dataset_id": request_payload.dataset_id,
        "dataset_label": manifest.get("dataset_label") or request_payload.dataset_id,
        "request": request_snapshot,
        "created_at": _openai_caption_batch_now(),
        "updated_at": _openai_caption_batch_now(),
        "output_dir": str(artifact_dir),
        "case_count": 0,
        "target_hash": target_snapshot.get("target_hash"),
        "dataset_fingerprint": target_snapshot.get("dataset_fingerprint"),
        "label_fingerprint": target_snapshot.get("label_fingerprint"),
        "target_identity": target_snapshot.get("target_identity") if isinstance(target_snapshot.get("target_identity"), Mapping) else {},
        "target_manifest": str(artifact_dir / "target_manifest.json"),
        "request_json": str(artifact_dir / "request_fields.json"),
        "cases_json": str(artifact_dir / "cases.json"),
        "local_materialization": True,
        "openai": {
            "model": args.model,
            "image_detail": args.image_detail,
            "reasoning_effort": args.reasoning_effort,
            "max_output_tokens": args.max_output_tokens,
            "qa_count": 0,
            "max_boxes": args.max_boxes,
            "remote_submission_skipped": True,
            "skip_reason": "no_visual_generation_cases",
            "underlying_endpoint": "/v1/responses",
            "batch_endpoint": "/v1/batches",
        },
        "result": {
            "instruction_artifacts": artifacts,
        },
        "import_report": {
            "status": "imported" if artifact_ok else "failed",
            "saved_captions": 0,
            "saved_generated_qa_rows": 0,
            "instruction_artifacts": artifacts,
        },
        "logs": [],
    }
    job["cost_summary"] = _openai_caption_batch_cost_summary(job)
    job = _openai_caption_batch_log(
        job,
        "OpenAI Batch remote submission skipped for local deterministic materialization",
        instruction_artifacts=artifacts,
    )
    return _openai_caption_batch_job_public(job)


def _openai_caption_batch_collection_child_ids(job: Mapping[str, Any]) -> List[str]:
    return [
        str(item or "").strip()
        for item in (job.get("child_job_ids") or [])
        if str(item or "").strip()
    ]


def _openai_caption_batch_collection_child_jobs(job: Mapping[str, Any]) -> List[Dict[str, Any]]:
    children: List[Dict[str, Any]] = []
    for child_id in _openai_caption_batch_collection_child_ids(job):
        try:
            children.append(_openai_caption_batch_read(child_id))
        except Exception:
            children.append({"job_id": child_id, "status": "missing", "case_count": 0})
    return children


def _openai_caption_batch_collection_summary(child_jobs: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    status_counts: Dict[str, int] = {}
    total_cases = 0
    request_total = 0
    request_completed = 0
    request_failed = 0
    shard_rows: List[Dict[str, Any]] = []
    collection_error_count = 0
    accepted_cases = 0
    incomplete_cases = 0
    incomplete_caption_rows = 0
    accepted_caption_rows = 0
    failed_cases = 0
    missing_result_rows = 0
    for child in child_jobs:
        status = _openai_caption_batch_normalize_status(child.get("status"))
        status_counts[status] = status_counts.get(status, 0) + 1
        collection_error = child.get("collection_error") if isinstance(child.get("collection_error"), Mapping) else {}
        if collection_error:
            collection_error_count += 1
        case_count = int(child.get("case_count") or 0)
        output_summary = _openai_caption_batch_summary_from_artifact(_openai_caption_batch_artifact_dir(child))
        accepted_cases += int(output_summary.get("accepted_cases") or 0)
        incomplete_cases += int(output_summary.get("incomplete_cases") or 0)
        incomplete_caption_rows += int(output_summary.get("incomplete_caption_rows") or 0)
        accepted_caption_rows += int(output_summary.get("caption_rows") or 0)
        failed_cases += int(output_summary.get("failed_cases") or 0)
        missing_result_rows += int(output_summary.get("missing_result_rows") or 0)
        total_cases += case_count
        counts = child.get("request_counts") if isinstance(child.get("request_counts"), Mapping) else {}
        request_total += int(counts.get("total") or case_count or 0)
        request_completed += int(counts.get("completed") or 0)
        request_failed += int(counts.get("failed") or 0)
        shard_rows.append(
            {
                "job_id": child.get("job_id"),
                "status": status,
                "case_count": case_count,
                "openai_batch_id": child.get("openai_batch_id"),
                "request_counts": dict(counts),
                "message": child.get("message"),
                "collection_error": collection_error,
                "output_summary": output_summary,
                "shard_index": child.get("shard_index"),
                "cost_summary": child.get("cost_summary") if isinstance(child.get("cost_summary"), Mapping) else {},
            }
        )
    total_shards = len(child_jobs)
    imported = status_counts.get("imported", 0)
    collected = status_counts.get("collected", 0)
    completed_remote = status_counts.get("completed_remote", 0)
    bad = sum(status_counts.get(status, 0) for status in ("failed", "expired", "cancelled", "import_blocked", "missing"))
    bad += collection_error_count
    active = sum(status_counts.get(status, 0) for status in OPENAI_CAPTION_BATCH_ACTIVE_STATUSES)
    if total_shards and imported == total_shards:
        aggregate_status = "imported"
    elif total_shards and imported + collected == total_shards:
        aggregate_status = "collected"
    elif total_shards and bad and not active:
        aggregate_status = "partial_failed" if imported + collected + completed_remote else "failed"
    elif total_shards and imported + collected + completed_remote == total_shards:
        aggregate_status = "completed_remote"
    else:
        aggregate_status = "in_progress"
    cost_summary = _openai_caption_batch_collection_cost_summary(child_jobs)
    return {
        "total_shards": total_shards,
        "status_counts": status_counts,
        "case_count": total_cases,
        "active_shards": active,
        "problem_shards": bad,
        "collection_error_shards": collection_error_count,
        "accepted_cases": accepted_cases,
        "accepted_caption_rows": accepted_caption_rows,
        "incomplete_cases": incomplete_cases,
        "incomplete_caption_rows": incomplete_caption_rows,
        "failed_cases": failed_cases,
        "missing_result_rows": missing_result_rows,
        "request_counts": {
            "total": request_total,
            "completed": request_completed,
            "failed": request_failed,
        },
        "status": aggregate_status,
        "cost_summary": cost_summary,
        "shards": sorted(shard_rows, key=lambda item: int(item.get("shard_index") or 0))[:200],
        "shard_list_limit": 200,
    }


def _openai_caption_batch_collection_public_fields(job: Mapping[str, Any]) -> Dict[str, Any]:
    child_jobs = _openai_caption_batch_collection_child_jobs(job)
    summary = _openai_caption_batch_collection_summary(child_jobs)
    return {
        "shard_summary": summary,
        "request_counts": summary.get("request_counts") or {},
        "case_count": summary.get("case_count") or job.get("case_count"),
    }


def _openai_caption_batch_refresh_collection_job(job_id: str) -> Dict[str, Any]:
    job = _openai_caption_batch_read(job_id)
    child_jobs = _openai_caption_batch_collection_child_jobs(job)
    summary = _openai_caption_batch_collection_summary(child_jobs)
    payload = dict(job)
    payload["status"] = summary.get("status") or payload.get("status") or "in_progress"
    payload["request_counts"] = summary.get("request_counts") or {}
    payload["shard_summary"] = summary
    payload["cost_summary"] = summary.get("cost_summary") or payload.get("cost_summary") or {}
    payload["message"] = (
        f"OpenAI Batch shards: {summary.get('total_shards', 0)} shard(s), "
        f"{(summary.get('request_counts') or {}).get('completed', 0)}/"
        f"{(summary.get('request_counts') or {}).get('total', 0)} request(s) complete."
    )
    return _openai_caption_batch_write(payload)


def _openai_caption_batch_start_with_cases(
    *,
    request_payload: QwenCaptionDatasetJobRequest,
    manifest: Mapping[str, Any],
    cases: Sequence[Mapping[str, Any]],
    job_id: Optional[str] = None,
    job_id_prefix: str = "ocap",
    catchup_for_job_id: str = "",
) -> Dict[str, Any]:
    clean_cases = [dict(case) for case in cases if isinstance(case, Mapping)]
    if not clean_cases:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_caption_batch_no_cases")
    job_id = str(job_id or "").strip() or f"{job_id_prefix}_{uuid.uuid4().hex[:12]}"
    artifact_dir = _openai_caption_batch_job_dir(job_id)
    artifact_dir.mkdir(parents=True, exist_ok=True)
    caption_request_fields, _model_fields = _qwen_caption_dataset_effective_request_fields(
        request_payload.caption_request or {},
        set_and_forget=bool(request_payload.set_and_forget),
    )
    shard_size = _openai_caption_batch_shard_size(request_payload, len(clean_cases))
    chunks = _openai_caption_batch_case_chunks(clean_cases, shard_size=shard_size)
    if len(chunks) <= 1:
        created = _openai_caption_batch_create_single_job(
            request_payload=request_payload,
            manifest=manifest,
            cases=clean_cases,
            caption_request_fields=caption_request_fields,
            job_id=job_id,
        )
        if catchup_for_job_id:
            job = _openai_caption_batch_read(str(created.get("job_id") or job_id))
            job["catchup_for_job_id"] = catchup_for_job_id
            job["message"] = (
                f"Preparing OpenAI Batch catch-up for {len(clean_cases)} incomplete image(s)."
            )
            job = _openai_caption_batch_log(
                job,
                "OpenAI Batch catch-up job created",
                catchup_for_job_id=catchup_for_job_id,
                case_count=len(clean_cases),
            )
            return _openai_caption_batch_job_public(job)
        return created

    request_path = artifact_dir / "request_fields.json"
    request_path.write_text(json.dumps(caption_request_fields, indent=2, sort_keys=True), encoding="utf-8")
    cases_path = artifact_dir / "cases.json"
    cases_path.write_text(json.dumps(clean_cases, indent=2, sort_keys=True), encoding="utf-8")
    request_snapshot = _qwen_caption_dataset_request_dump(request_payload)
    target_snapshot = _openai_caption_batch_build_target_snapshot(
        dataset_id=request_payload.dataset_id,
        manifest=manifest,
        cases=clean_cases,
        request_payload=request_snapshot,
    )
    (artifact_dir / "target_manifest.json").write_text(
        json.dumps(target_snapshot, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    args = _openai_caption_batch_args(request_payload, request_path=request_path)
    job = {
        "job_id": job_id,
        "kind": "openai_caption_batch_collection",
        "status": "preparing",
        "message": (
            f"Preparing {len(chunks)} OpenAI Batch shard(s) for {len(clean_cases)} image(s) "
            f"at up to {shard_size} image(s) per shard."
        ),
        "dataset_id": request_payload.dataset_id,
        "dataset_label": manifest.get("dataset_label") or request_payload.dataset_id,
        "request": request_snapshot,
        "created_at": _openai_caption_batch_now(),
        "updated_at": _openai_caption_batch_now(),
        "output_dir": str(artifact_dir),
        "case_count": len(clean_cases),
        "shard_size": shard_size,
        "shard_count": len(chunks),
        "child_job_ids": [],
        "target_hash": target_snapshot.get("target_hash"),
        "dataset_fingerprint": target_snapshot.get("dataset_fingerprint"),
        "label_fingerprint": target_snapshot.get("label_fingerprint"),
        "target_identity": target_snapshot.get("target_identity") if isinstance(target_snapshot.get("target_identity"), Mapping) else {},
        "target_manifest": str(artifact_dir / "target_manifest.json"),
        "request_json": str(request_path),
        "cases_json": str(cases_path),
        "openai": {
            "model": args.model,
            "image_detail": args.image_detail,
            "reasoning_effort": args.reasoning_effort,
            "max_output_tokens": args.max_output_tokens,
            "qa_count": args.qa_count,
            "max_boxes": args.max_boxes,
            "underlying_endpoint": "/v1/responses",
            "batch_endpoint": "/v1/batches",
        },
        "logs": [],
        "result": {},
    }
    if catchup_for_job_id:
        job["catchup_for_job_id"] = catchup_for_job_id
        job["message"] = (
            f"Preparing {len(chunks)} OpenAI Batch catch-up shard(s) for "
            f"{len(clean_cases)} incomplete image(s)."
        )
    job["cost_summary"] = _openai_caption_batch_cost_summary(job)
    job = _openai_caption_batch_log(
        job,
        "OpenAI Batch catch-up collection created" if catchup_for_job_id else "OpenAI Batch collection created",
        case_count=len(clean_cases),
        shard_count=len(chunks),
        shard_size=shard_size,
        catchup_for_job_id=catchup_for_job_id or None,
    )
    child_ids: List[str] = []
    for shard_index, chunk in enumerate(chunks, start=1):
        child_id = f"{job_id}_s{shard_index:05d}"
        _openai_caption_batch_create_single_job(
            request_payload=request_payload,
            manifest=manifest,
            cases=chunk,
            caption_request_fields=caption_request_fields,
            job_id=child_id,
            parent_job_id=job_id,
            shard_index=shard_index,
            shard_count=len(chunks),
            start_thread=False,
        )
        if catchup_for_job_id:
            child = _openai_caption_batch_read(child_id)
            child["catchup_for_job_id"] = catchup_for_job_id
            _openai_caption_batch_write(child)
        child_ids.append(child_id)
    job = _openai_caption_batch_read(job_id)
    job["child_job_ids"] = child_ids
    job["status"] = "in_progress"
    job["message"] = (
        f"Queued {len(child_ids)} OpenAI Batch shard(s) for {len(clean_cases)} image(s); "
        f"submitting up to {_openai_caption_batch_submit_shard_limit()} shard(s) concurrently."
    )
    if catchup_for_job_id:
        job["message"] = (
            f"Queued {len(child_ids)} OpenAI Batch catch-up shard(s) for "
            f"{len(clean_cases)} incomplete image(s); submitting up to "
            f"{_openai_caption_batch_submit_shard_limit()} shard(s) concurrently."
        )
    job = _openai_caption_batch_log(
        job,
        "OpenAI Batch shards queued",
        shard_count=len(child_ids),
        submit_concurrency=_openai_caption_batch_submit_shard_limit(),
        catchup_for_job_id=catchup_for_job_id or None,
    )
    _openai_caption_batch_start_collection_submit_thread(job_id)
    return _openai_caption_batch_job_public(_openai_caption_batch_refresh_collection_job(job_id))


def _start_openai_caption_batch_job(payload: QwenCaptionDatasetJobRequest) -> Dict[str, Any]:
    request_data = _qwen_caption_dataset_request_dump(payload)
    request_data["caption_provider"] = "openai"
    request_data["openai_service_tier"] = "batch"
    request_payload = QwenCaptionDatasetJobRequest(**request_data)
    _preflight_openai_caption_provider_request(request_payload)
    job_id = f"ocap_{uuid.uuid4().hex[:12]}"
    artifact_dir = _openai_caption_batch_job_dir(job_id)
    artifact_dir.mkdir(parents=True, exist_ok=True)
    manifest, cases = _qwen_caption_dataset_cases(request_payload, output_dir=artifact_dir)
    if not cases:
        return _openai_caption_batch_create_local_materialization_job(
            request_payload=request_payload,
            manifest=manifest,
            job_id=job_id,
        )
    return _openai_caption_batch_start_with_cases(
        request_payload=request_payload,
        manifest=manifest,
        cases=cases,
        job_id=job_id,
        job_id_prefix="ocap",
    )


def _openai_caption_batch_poll_job(job_id: str) -> Dict[str, Any]:
    from tools import run_openai_caption_batch_smoke as batch_smoke

    job = _openai_caption_batch_read(job_id)
    if str(job.get("kind") or "") == "openai_caption_batch_collection":
        poll_limit_raw = os.environ.get("TATOR_OPENAI_BATCH_POLL_SHARDS", "25")
        try:
            poll_limit = max(1, min(int(poll_limit_raw or 25), 500))
        except (TypeError, ValueError, OverflowError):
            poll_limit = 25
        active_children = _openai_caption_batch_collection_child_jobs(job)
        if not _openai_caption_batch_registered_thread_alive(job_id):
            has_unsubmitted_child = any(
                _openai_caption_batch_normalize_status(child.get("status")) in OPENAI_CAPTION_BATCH_ACTIVE_STATUSES
                and not str(child.get("openai_batch_id") or "").strip()
                and _openai_caption_batch_submit_artifacts_present(child)
                for child in active_children
            )
            if has_unsubmitted_child:
                _openai_caption_batch_start_collection_submit_thread(job_id)
        poll_candidates = [
            child
            for child in active_children
            if str(child.get("openai_batch_id") or "").strip()
            and _openai_caption_batch_normalize_status(child.get("status")) not in OPENAI_CAPTION_BATCH_FINAL_STATUSES
        ][:poll_limit]
        for child in poll_candidates:
            try:
                _openai_caption_batch_poll_job(str(child.get("job_id") or ""))
            except Exception:
                logger.debug("Failed to poll OpenAI caption Batch shard %s", child.get("job_id"), exc_info=True)
        refreshed = _openai_caption_batch_refresh_collection_job(job_id)
        return _openai_caption_batch_job_public(refreshed)
    if _openai_caption_batch_normalize_status(job.get("status")) in {"collected", "imported", "import_blocked"}:
        return _openai_caption_batch_job_public(job)
    batch_id = str(job.get("openai_batch_id") or "").strip()
    if not batch_id:
        status = _openai_caption_batch_normalize_status(job.get("status"))
        if (
            status in OPENAI_CAPTION_BATCH_ACTIVE_STATUSES
            and _openai_caption_batch_submit_artifacts_present(job)
            and not _openai_caption_batch_registered_thread_alive(job_id)
        ):
            if _openai_caption_batch_start_submit_thread(job_id):
                job = _openai_caption_batch_log(
                    job,
                    "OpenAI Batch submitter restarted from persisted artifacts",
                )
        return _openai_caption_batch_job_public(_openai_caption_batch_read(job_id))
    payload = QwenCaptionDatasetJobRequest(**dict(job.get("request") or {}))
    key = _openai_caption_batch_api_key(payload.openai_api_key_path)
    args = _openai_caption_batch_args(payload, request_path=Path(str(job.get("request_json") or "request_fields.json")))
    latest = batch_smoke.poll_batch(
        key=key,
        batch_id=batch_id,
        output_dir=_openai_caption_batch_artifact_dir(job),
        poll_seconds=0,
        wait_seconds=0,
        timeout=args.timeout,
    )
    refreshed = _openai_caption_batch_refresh_from_response(job, latest)
    return _openai_caption_batch_job_public(refreshed)


def _openai_caption_batch_collect_job(job_id: str) -> Dict[str, Any]:
    from tools import run_openai_caption_batch_smoke as batch_smoke

    initial_job = _openai_caption_batch_read(job_id)
    if str(initial_job.get("kind") or "") != "openai_caption_batch_collection" and _openai_caption_batch_normalize_status(initial_job.get("status")) == "imported":
        return _openai_caption_batch_job_public(initial_job)
    job = _openai_caption_batch_poll_job(job_id)
    raw_job = _openai_caption_batch_read(job_id)
    if str(raw_job.get("kind") or "") == "openai_caption_batch_collection":
        child_jobs = _openai_caption_batch_collection_child_jobs(raw_job)
        collection_errors: List[Dict[str, Any]] = []
        for child in child_jobs:
            child_status = _openai_caption_batch_normalize_status(child.get("status"))
            if child_status in {"completed_remote", "collected"}:
                child_id = str(child.get("job_id") or "").strip()
                try:
                    _openai_caption_batch_collect_job(child_id)
                except Exception as exc:
                    error = {
                        "job_id": child_id,
                        "type": exc.__class__.__name__,
                        "message": str(getattr(exc, "detail", "") or exc),
                    }
                    collection_errors.append(error)
                    try:
                        child_payload = _openai_caption_batch_read(child_id)
                        child_payload["collection_error"] = error
                        child_payload["message"] = f"Local collection failed: {error['message']}"
                        _openai_caption_batch_write(child_payload)
                    except Exception:
                        logger.debug("Failed to persist OpenAI caption Batch shard collection error %s", child_id, exc_info=True)
                    logger.debug("Failed to collect OpenAI caption Batch shard %s", child_id, exc_info=True)
        refreshed = _openai_caption_batch_refresh_collection_job(job_id)
        summary = refreshed.get("shard_summary") if isinstance(refreshed.get("shard_summary"), Mapping) else {}
        refreshed["result"] = {
            **(dict(refreshed.get("result") or {}) if isinstance(refreshed.get("result"), Mapping) else {}),
            "collection": summary,
            "collection_errors": collection_errors[:200],
        }
        if collection_errors:
            refreshed["message"] = (
                f"OpenAI Batch collection found {len(collection_errors)} shard collection error"
                f"{'' if len(collection_errors) == 1 else 's'}; inspect details before import."
            )
        refreshed = _openai_caption_batch_log(
            refreshed,
            "OpenAI Batch collection refresh",
            summary=summary,
            collection_errors=collection_errors[:200],
        )
        return _openai_caption_batch_job_public(refreshed)
    raw_status = _openai_caption_batch_normalize_status(raw_job.get("status"))
    if raw_status == "imported":
        return _openai_caption_batch_job_public(raw_job)
    if raw_status not in {"completed_remote", "collected"}:
        return job
    artifact_dir = _openai_caption_batch_artifact_dir(raw_job)
    if raw_status == "collected" and any(
        (artifact_dir / name).exists()
        for name in ("summary.json", "results.jsonl", "captions.jsonl", "incomplete_captions.jsonl")
    ):
        return _openai_caption_batch_job_public(raw_job)
    payload = QwenCaptionDatasetJobRequest(**dict(raw_job.get("request") or {}))
    key = _openai_caption_batch_api_key(payload.openai_api_key_path)
    args = _openai_caption_batch_args(
        payload,
        request_path=Path(str(raw_job.get("request_json") or _openai_caption_batch_artifact_dir(raw_job) / "request_fields.json")),
    )
    batch_status = _openai_caption_batch_best_status_payload(raw_job, artifact_dir)
    batch_smoke.download_outputs(
        key=key,
        batch=batch_status,
        output_dir=artifact_dir,
        timeout=args.timeout,
    )
    cases = json.loads((artifact_dir / "cases.json").read_text(encoding="utf-8"))
    if not isinstance(cases, list):
        raise HTTPException(status_code=HTTP_500_INTERNAL_SERVER_ERROR, detail="openai_caption_batch_cases_invalid")
    summary = batch_smoke.collect_results(
        cases=cases,
        output_dir=artifact_dir,
        target_qa=args.qa_count,
        answer_format=args.answer_format,
        imposed_questions=args.instruction_qa_imposed_questions,
        max_output_tokens=args.max_output_tokens,
    )
    raw_job.pop("collection_error", None)
    raw_job["status"] = "collected"
    incomplete_rows = int(summary.get("incomplete_caption_rows") or summary.get("incomplete_cases") or 0)
    missing_result_rows = int(summary.get("missing_result_rows") or 0)
    failed_output_rows = max(0, int(summary.get("failed_cases") or 0) - missing_result_rows)
    raw_job["message"] = (
        f"OpenAI Batch collected: {summary.get('caption_rows', 0)}/{summary.get('total_cases', 0)} accepted caption row(s)."
        + (f" {incomplete_rows} incomplete row(s) were held for catch-up." if incomplete_rows else "")
        + (f" {missing_result_rows} missing result row(s) can be retried with catch-up." if missing_result_rows else "")
        + (f" {failed_output_rows} failed output row(s) remain." if failed_output_rows else "")
    )
    raw_job["result"] = {
        **(dict(raw_job.get("result") or {}) if isinstance(raw_job.get("result"), Mapping) else {}),
        "collection": summary,
    }
    raw_job["cost_summary"] = _openai_caption_batch_cost_summary(raw_job)
    raw_job = _openai_caption_batch_log(raw_job, "OpenAI Batch outputs collected", summary=summary)
    return _openai_caption_batch_job_public(raw_job)


def _openai_caption_batch_caption_record_from_row(
    row: Mapping[str, Any],
    case: Mapping[str, Any],
) -> Dict[str, Any]:
    return {
        "case_id": str(row.get("case_id") or case.get("case_id") or "").strip(),
        "image_name": str(case.get("image_name") or row.get("image_name") or Path(str(row.get("image_path") or "")).name).strip(),
        "split": str(case.get("split") or "").strip() or None,
        "caption": str(row.get("caption") or "").strip(),
        "artifact_dir": str(row.get("artifact_dir") or ""),
        "caption_quality": {},
    }


def _openai_caption_batch_row_qa_target(row: Mapping[str, Any], payload: QwenCaptionDatasetJobRequest) -> int:
    try:
        try:
            target = max(0, int(row.get("generated_qa_target_pair_count") or 0))
        except (TypeError, ValueError, OverflowError):
            target = 0
    except (TypeError, ValueError, OverflowError):
        target = 0
    if target <= 0:
        target = _qwen_caption_dataset_generated_qa_target(payload)
    return max(0, min(target, 100))


def _openai_caption_batch_row_pairs_for_import(
    row: Mapping[str, Any],
    *,
    current_generated_qa_count: int,
) -> List[Mapping[str, Any]]:
    pairs = row.get("generated_qa_pairs") if isinstance(row.get("generated_qa_pairs"), list) else []
    catchup = row.get("openai_batch_catchup") if isinstance(row.get("openai_batch_catchup"), Mapping) else {}
    new_pairs = row.get("generated_qa_new_pairs") if isinstance(row.get("generated_qa_new_pairs"), list) else []
    if catchup and new_pairs and current_generated_qa_count > 0:
        return [pair for pair in new_pairs if isinstance(pair, Mapping)]
    return [pair for pair in pairs if isinstance(pair, Mapping)]


def _openai_caption_batch_imported_row_key(dataset_id: str, row: Mapping[str, Any]) -> str:
    case_id = str(row.get("case_id") or "").strip()
    return f"{str(dataset_id or '').strip()}::{case_id}"


def _openai_caption_batch_imported_row_keys(path: Path) -> Set[str]:
    keys: Set[str] = set()
    for row in _openai_caption_batch_read_jsonl(path):
        key = str(row.get("row_key") or "").strip()
        if key:
            keys.add(key)
    return keys


def _openai_caption_batch_mark_row_imported(
    path: Path,
    *,
    dataset_id: str,
    job_id: str,
    row: Mapping[str, Any],
    saved_caption: bool,
    saved_qa_rows: int,
) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "row_key": _openai_caption_batch_imported_row_key(dataset_id, row),
        "dataset_id": str(dataset_id or "").strip(),
        "job_id": str(job_id or "").strip(),
        "case_id": str(row.get("case_id") or "").strip(),
        "image_name": str(row.get("image_name") or "").strip(),
        "saved_caption": bool(saved_caption),
        "saved_generated_qa_rows": max(0, int(saved_qa_rows or 0)),
        "imported_at": _openai_caption_batch_now(),
    }
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(payload, sort_keys=True) + "\n")


def _openai_caption_batch_row_matches_selected(
    row: Mapping[str, Any],
    case: Mapping[str, Any],
    selected: Set[str],
) -> bool:
    if not selected:
        return True
    row_selectors = {
        str(case.get("image_key") or "").strip(),
        str(case.get("image_name") or row.get("image_name") or "").strip(),
        str(case.get("image_relpath") or "").strip(),
    }
    return bool(row_selectors & selected)


def _openai_caption_batch_should_save_caption(
    payload: QwenCaptionDatasetJobRequest,
    *,
    write_policy: str,
    current_counts: Mapping[str, Any],
) -> bool:
    if not bool(payload.save_text_labels):
        return False
    if write_policy in {"qa_only_extend", "qa_only_replace"}:
        return False
    if write_policy in {"replace_generated", "append_variants"}:
        return True
    if str(payload.completion_mode or "per_image_totals") == "incremental":
        return _qwen_caption_dataset_increment_base_caption_count(payload) > 0
    target_base = _qwen_caption_dataset_base_caption_target(payload)
    if target_base <= 0:
        return False
    try:
        current_base = int(current_counts.get("base_caption_count") or 0)
    except (TypeError, ValueError, OverflowError):
        current_base = 0
    return current_base < target_base


def _openai_caption_batch_incomplete_row_sample(row: Mapping[str, Any]) -> Dict[str, Any]:
    row_pairs = row.get("generated_qa_pairs") if isinstance(row.get("generated_qa_pairs"), list) else []
    pair_count = _openai_caption_usage_number(row.get("generated_qa_pair_count") or len(row_pairs))
    missing_required = [
        str(question or "").strip()
        for question in (row.get("missing_required_questions") if isinstance(row.get("missing_required_questions"), list) else [])
        if str(question or "").strip()
    ]
    return {
        "case_id": str(row.get("case_id") or "").strip(),
        "image_name": str(row.get("image_name") or "").strip(),
        "generated_qa_pair_count": pair_count,
        "generated_qa_target_pair_count": _openai_caption_usage_number(row.get("generated_qa_target_pair_count")),
        "failure_reason": row.get("failure_reason") or "generated_qa_incomplete",
        "missing_required_questions": missing_required,
    }


def _openai_caption_batch_target_intersects_selected(
    job: Mapping[str, Any],
    selected_image_keys: Sequence[str],
) -> Optional[bool]:
    selected = {str(key or "").strip() for key in (selected_image_keys or []) if str(key or "").strip()}
    if not selected:
        return None
    target_path = _openai_caption_batch_target_manifest_path(job, _openai_caption_batch_artifact_dir(job))
    try:
        snapshot = json.loads(target_path.read_text(encoding="utf-8"))
    except Exception:
        return None
    if not isinstance(snapshot, Mapping):
        return None
    cases = [case for case in (snapshot.get("cases") or []) if isinstance(case, Mapping)]
    if not cases:
        return None
    for case in cases:
        selectors = {
            str(case.get("image_key") or "").strip(),
            str(case.get("image_name") or "").strip(),
            str(case.get("image_relpath") or "").strip(),
        }
        if selectors & selected:
            return True
    return False


def _openai_caption_batch_import_job(
    job_id: str,
    dataset_id: Optional[str] = None,
    *,
    import_mode: str = "exact_only",
    selected_image_keys: Optional[Sequence[str]] = None,
) -> Dict[str, Any]:
    from tools import run_openai_caption_batch_smoke as batch_smoke

    target_dataset_id = str(dataset_id or "").strip()
    if not target_dataset_id:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_caption_batch_import_dataset_id_required")
    job = _openai_caption_batch_read(job_id)
    if _openai_caption_batch_normalize_status(job.get("status")) == "imported":
        request_payload = QwenCaptionDatasetJobRequest(**dict(job.get("request") or {}))
        job = _openai_caption_batch_attach_instruction_artifacts(
            job,
            dataset_id=target_dataset_id,
            payload=request_payload,
        )
        return _openai_caption_batch_job_public(job, dataset_id=target_dataset_id, include_match=True)
    if str(job.get("kind") or "") == "openai_caption_batch_collection":
        _openai_caption_batch_collect_job(job_id)
        child_jobs = _openai_caption_batch_collection_child_jobs(_openai_caption_batch_read(job_id))
        imported = 0
        partial_imported = 0
        blocked = 0
        failed = 0
        skipped = 0
        saved_captions = 0
        saved_qa = 0
        ready_shards = 0
        child_reports: List[Dict[str, Any]] = []
        for child in child_jobs:
            child_id = str(child.get("job_id") or "").strip()
            if not child_id:
                continue
            child_status = _openai_caption_batch_normalize_status(child.get("status"))
            if child_status == "imported":
                report = child.get("import_report") if isinstance(child.get("import_report"), Mapping) else {}
                imported += 1
                saved_captions += int(report.get("saved_captions") or 0)
                saved_qa += int(report.get("saved_generated_qa_rows") or 0)
                child_reports.append(
                    {
                        "job_id": child_id,
                        "status": "imported",
                        "message": child.get("message"),
                        "saved_captions": report.get("saved_captions"),
                        "saved_generated_qa_rows": report.get("saved_generated_qa_rows"),
                    }
                )
                continue
            if child_status not in {"completed_remote", "collected", "import_blocked", "imported"}:
                continue
            if child_status != "imported":
                ready_shards += 1
            if selected_image_keys and _openai_caption_batch_target_intersects_selected(child, selected_image_keys) is False:
                skipped += 1
                child_reports.append(
                    {
                        "job_id": child_id,
                        "status": "skipped",
                        "reason": "selected_images_not_in_shard",
                        "message": "No selected images are present in this shard target snapshot.",
                    }
                )
                continue
            try:
                result = _openai_caption_batch_import_job(
                    child_id,
                    dataset_id=target_dataset_id,
                    import_mode=import_mode,
                    selected_image_keys=selected_image_keys,
                )
            except Exception as exc:
                failed += 1
                child_reports.append({"job_id": child_id, "status": "failed", "message": str(exc)})
                logger.debug("Failed to import OpenAI caption Batch shard %s", child_id, exc_info=True)
                continue
            status = _openai_caption_batch_normalize_status(result.get("status"))
            report = result.get("import_report") if isinstance(result.get("import_report"), Mapping) else {}
            child_reports.append(
                {
                    "job_id": child_id,
                    "status": status,
                    "message": result.get("message"),
                    "saved_captions": report.get("saved_captions"),
                    "saved_generated_qa_rows": report.get("saved_generated_qa_rows"),
                }
            )
            if status == "imported":
                imported += 1
                saved_captions += int(report.get("saved_captions") or 0)
                saved_qa += int(report.get("saved_generated_qa_rows") or 0)
            elif status == "collected" and str(report.get("status") or "") == "partial_imported":
                partial_imported += 1
                saved_captions += int(report.get("saved_captions") or 0)
                saved_qa += int(report.get("saved_generated_qa_rows") or 0)
            elif status == "import_blocked":
                blocked += 1
            elif status in {"failed", "expired", "cancelled"}:
                failed += 1
        refreshed = _openai_caption_batch_refresh_collection_job(job_id)
        final_children = _openai_caption_batch_collection_child_jobs(refreshed)
        final_summary = _openai_caption_batch_collection_summary(final_children)
        final_status = final_summary.get("status") or "in_progress"
        import_report = {
            "status": final_status,
            "dataset_id": target_dataset_id,
            "shards": len(child_jobs),
            "imported_shards": imported,
            "partial_imported_shards": partial_imported,
            "blocked_shards": blocked,
            "failed_shards": failed,
            "skipped_shards": skipped,
            "ready_shards": ready_shards,
            "saved_captions": saved_captions,
            "saved_generated_qa_rows": saved_qa,
            "child_reports": child_reports[:200],
            "child_report_limit": 200,
            "shard_summary": final_summary,
        }
        refreshed["status"] = final_status
        request_payload = QwenCaptionDatasetJobRequest(**dict(refreshed.get("request") or {}))
        if (saved_captions or saved_qa) and bool(request_payload.instruction_dataset):
            refreshed = _openai_caption_batch_attach_instruction_artifacts(
                refreshed,
                dataset_id=target_dataset_id,
                payload=request_payload,
                import_report=import_report,
                force=True,
            )
            import_report = (
                dict(refreshed.get("import_report"))
                if isinstance(refreshed.get("import_report"), Mapping)
                else import_report
            )
        if not imported and not blocked and not failed and not skipped and not ready_shards:
            refreshed["message"] = (
                "No OpenAI Batch shard outputs are ready to import yet. "
                "Poll or collect completed shards first."
            )
        else:
            refreshed["message"] = (
                f"Imported {imported}/{len(child_jobs)} OpenAI Batch shard(s)"
                f"{f' and partially imported {partial_imported}' if partial_imported else ''}: "
                f"{saved_captions} caption(s), {saved_qa} generated QA row(s)."
            )
        refreshed["import_report"] = import_report
        refreshed["result"] = {
            **(dict(refreshed.get("result") or {}) if isinstance(refreshed.get("result"), Mapping) else {}),
            "import": import_report,
        }
        refreshed = _openai_caption_batch_log(refreshed, "OpenAI Batch collection import", report=import_report)
        return _openai_caption_batch_job_public(refreshed)
    if _openai_caption_batch_normalize_status(job.get("status")) == "completed_remote":
        job = _openai_caption_batch_collect_job(job_id)
    job = _openai_caption_batch_read(job_id)
    artifact_dir = _openai_caption_batch_artifact_dir(job)
    ok, verification = _openai_caption_batch_verify_target(
        job,
        dataset_id=target_dataset_id,
        import_mode=import_mode,
        selected_image_keys=selected_image_keys,
    )
    if not ok:
        job["status"] = "import_blocked"
        job["message"] = verification.get("message") or "OpenAI Batch import blocked."
        job["import_report"] = verification
        job = _openai_caption_batch_log(job, "OpenAI Batch import blocked", report=verification)
        return _openai_caption_batch_job_public(job)
    captions_path = artifact_dir / "captions.jsonl"
    if not captions_path.exists():
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_caption_batch_outputs_not_collected")
    output_summary = _openai_caption_batch_summary_from_artifact(artifact_dir)
    output_failed_rows = int(output_summary.get("failed_cases") or 0)
    output_missing_result_rows = int(output_summary.get("missing_result_rows") or 0)
    request_payload = QwenCaptionDatasetJobRequest(**dict(job.get("request") or {}))
    if not _qwen_caption_dataset_persists_outputs(request_payload):
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_caption_batch_test_outputs_not_persistent")
    cases = json.loads((artifact_dir / "cases.json").read_text(encoding="utf-8"))
    if not isinstance(cases, list):
        raise HTTPException(status_code=HTTP_500_INTERNAL_SERVER_ERROR, detail="openai_caption_batch_cases_invalid")
    case_by_id = {batch_smoke.case_key(case): dict(case) for case in cases if isinstance(case, Mapping)}
    selected = {str(key or "").strip() for key in (selected_image_keys or []) if str(key or "").strip()}
    rows = batch_smoke.read_jsonl(captions_path)
    target_dataset_id = str(verification.get("dataset_id") or target_dataset_id).strip()
    write_policy = str(request_payload.write_policy or "fill_missing")
    archive_seen: Set[str] = set()
    saved_captions = 0
    saved_qa = 0
    archived_generated_qa_rows = 0
    skipped_rows = 0
    incomplete_rows = 0
    already_imported_rows = 0
    incomplete_row_samples: List[Dict[str, Any]] = []
    incomplete_path = artifact_dir / "incomplete_captions.jsonl"
    held_incomplete_rows = [
        row
        for row in _openai_caption_batch_read_jsonl(incomplete_path)
        if isinstance(row, Mapping)
    ]
    held_incomplete_case_ids = {
        str(row.get("case_id") or "").strip()
        for row in held_incomplete_rows
        if str(row.get("case_id") or "").strip()
    }
    for row in held_incomplete_rows:
        case_id = str(row.get("case_id") or "").strip()
        case = case_by_id.get(case_id) or {}
        if not _openai_caption_batch_row_matches_selected(row, case, selected):
            continue
        incomplete_rows += 1
        if len(incomplete_row_samples) < 25:
            incomplete_row_samples.append(_openai_caption_batch_incomplete_row_sample(row))
    imported_images: Set[str] = set()
    imported_rows_path = artifact_dir / "imported_rows.jsonl"
    imported_row_keys = _openai_caption_batch_imported_row_keys(imported_rows_path)
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        case_id = str(row.get("case_id") or "").strip()
        case = case_by_id.get(case_id) or {}
        if not _openai_caption_batch_row_matches_selected(row, case, selected):
            skipped_rows += 1
            continue
        if case_id in held_incomplete_case_ids:
            skipped_rows += 1
            continue
        row_import_key = _openai_caption_batch_imported_row_key(target_dataset_id, row)
        if row_import_key in imported_row_keys:
            already_imported_rows += 1
            skipped_rows += 1
            continue
        caption_record = _openai_caption_batch_caption_record_from_row(row, case)
        image_name = str(caption_record.get("image_name") or "").strip()
        caption = str(caption_record.get("caption") or "").strip()
        split = str(caption_record.get("split") or "").strip() or None
        if not image_name:
            skipped_rows += 1
            continue
        current_counts = _qwen_caption_dataset_image_completion_counts(
            target_dataset_id,
            image_name,
            split=split,
        )
        target_qa = _openai_caption_batch_row_qa_target(row, request_payload)
        row_pairs = row.get("generated_qa_pairs") if isinstance(row.get("generated_qa_pairs"), list) else []
        row_pair_count = len([pair for pair in row_pairs if isinstance(pair, Mapping)])
        catchup_meta = row.get("openai_batch_catchup") if isinstance(row.get("openai_batch_catchup"), Mapping) else {}
        qa_required_for_row = (
            bool(request_payload.instruction_dataset)
            and bool(request_payload.include_generated_qa_in_training)
            and target_qa > 0
        )
        missing_required_questions = (
            batch_smoke.missing_required_questions(row_pairs, request_payload.instruction_qa_imposed_questions)
            if qa_required_for_row and request_payload.instruction_qa_imposed_questions
            else []
        )
        if qa_required_for_row and (row_pair_count < target_qa or missing_required_questions):
            held_row = dict(row)
            held_row["generated_qa_pair_count"] = row_pair_count
            held_row["generated_qa_target_pair_count"] = target_qa
            held_row["failure_reason"] = (
                "required_qa_missing" if missing_required_questions else "generated_qa_incomplete"
            )
            held_row["missing_required_questions"] = list(missing_required_questions)
            if case_id and case_id not in held_incomplete_case_ids:
                with incomplete_path.open("a", encoding="utf-8") as handle:
                    handle.write(json.dumps(held_row, ensure_ascii=False, sort_keys=True) + "\n")
                held_incomplete_case_ids.add(case_id)
            incomplete_rows += 1
            skipped_rows += 1
            if len(incomplete_row_samples) < 25:
                incomplete_row_samples.append(_openai_caption_batch_incomplete_row_sample(held_row))
            continue
        if image_name not in archive_seen and write_policy in {"replace_generated", "qa_only_replace"}:
            _qwen_caption_dataset_soft_archive_generated_outputs(
                target_dataset_id,
                image_name,
                job_id=job_id,
                split=split,
                archive_captions=write_policy == "replace_generated",
                archive_generated_qa=True,
                reason=f"{write_policy}_before_openai_batch_import",
            )
            archive_seen.add(image_name)
        row_saved_caption = False
        if caption and _openai_caption_batch_should_save_caption(
            request_payload,
            write_policy=write_policy,
            current_counts=current_counts,
        ):
            _add_caption_impl(
                target_dataset_id,
                image_name,
                {
                    "caption": caption,
                    "split": split,
                    "make_primary": bool(request_payload.generated_make_primary),
                    "source": "openai_caption_batch",
                    "session_id": request_payload.annotation_session_id,
                    "metadata": {
                        "job_id": job_id,
                        "openai_batch_id": job.get("openai_batch_id"),
                        "case_id": case_id,
                        "model": (job.get("openai") or {}).get("model") if isinstance(job.get("openai"), Mapping) else None,
                    },
                },
            )
            saved_captions += 1
            row_saved_caption = True
        pairs: Sequence[Mapping[str, Any]] = []
        current_generated_qa_count = 0
        if bool(request_payload.instruction_dataset) and bool(request_payload.include_generated_qa_in_training):
            current_generated_qa_count = int(current_counts.get("generated_qa_count") or 0)
            pairs = _openai_caption_batch_row_pairs_for_import(
                row,
                current_generated_qa_count=current_generated_qa_count,
            )
            if catchup_meta and pairs and request_payload.instruction_qa_imposed_questions:
                imposed_keys = {
                    _qwen_caption_dataset_required_question_key(question)
                    for question in request_payload.instruction_qa_imposed_questions
                    if _qwen_caption_dataset_required_question_key(question)
                }
                pairs = sorted(
                    pairs,
                    key=lambda pair: (
                        0
                        if _qwen_caption_dataset_required_question_key(pair.get("question")) in imposed_keys
                        else 1
                    ),
                )
            if catchup_meta and pairs and target_qa > 0:
                keep_questions = [
                    pair.get("question")
                    for pair in row_pairs
                    if isinstance(pair, Mapping) and str(pair.get("question") or "").strip()
                ]
                archive_needed = max(0, current_generated_qa_count + len(pairs) - target_qa)
                archived_for_row = _qwen_caption_dataset_soft_archive_generated_qa_not_in_questions(
                    target_dataset_id,
                    image_name,
                    keep_questions=keep_questions,
                    limit=archive_needed,
                    job_id=job_id,
                    split=split,
                    reason="openai_batch_catchup_replaced_unretained_qa",
                )
                if archived_for_row:
                    current_generated_qa_count = max(0, current_generated_qa_count - archived_for_row)
                    archived_generated_qa_rows += archived_for_row
        if bool(request_payload.instruction_dataset) and bool(request_payload.include_generated_qa_in_training) and pairs:
            active_limit: Optional[int] = None
            if str(request_payload.completion_mode or "per_image_totals") == "per_image_totals":
                target = _qwen_caption_dataset_generated_qa_target(request_payload)
                if write_policy in {"replace_generated", "qa_only_replace"}:
                    active_limit = target
                elif write_policy in {"fill_missing", "qa_only_extend"}:
                    active_limit = max(0, target - current_generated_qa_count)
            elif str(request_payload.completion_mode or "per_image_totals") == "incremental":
                active_limit = _qwen_caption_dataset_effective_generated_qa_request_count(request_payload)
            enriched: List[Dict[str, Any]] = []
            for pair_index, pair in enumerate(pairs):
                if not isinstance(pair, Mapping):
                    continue
                lifecycle_status = "active"
                superseded_reason = ""
                if active_limit is not None and pair_index >= active_limit:
                    lifecycle_status = "overflow"
                    superseded_reason = "openai_batch_generated_qa_target_reached"
                enriched.append(
                    {
                        "question": pair.get("question"),
                        "answer": pair.get("answer"),
                        "row_type": "generated_qa",
                        "answer_source": "vlm_generated",
                        "answer_format": str(row.get("answer_format") or request_payload.answer_format or "natural").strip()
                        or "natural",
                        "validation_status": "machine_validated",
                        "review_status": "unreviewed",
                        "caption_id": case_id,
                        "caption": caption,
                        "lifecycle_status": lifecycle_status,
                        "superseded_by_run_id": "" if lifecycle_status == "active" else job_id,
                        "superseded_reason": superseded_reason,
                        "metadata": {
                            "job_id": job_id,
                            "openai_batch_id": job.get("openai_batch_id"),
                            "case_id": case_id,
                            "provider": "openai",
                            "source": "openai_caption_batch",
                            "openai_batch_catchup": row.get("openai_batch_catchup")
                            if isinstance(row.get("openai_batch_catchup"), Mapping)
                            else {},
                        },
                    }
                )
            row_saved_qa = _dataset_caption_add_instruction_records(
                target_dataset_id,
                image_name,
                enriched,
                split=split,
            )
            saved_qa += row_saved_qa
        else:
            row_saved_qa = 0
        _openai_caption_batch_mark_row_imported(
            imported_rows_path,
            dataset_id=target_dataset_id,
            job_id=job_id,
            row=row,
            saved_caption=row_saved_caption,
            saved_qa_rows=row_saved_qa,
        )
        imported_row_keys.add(row_import_key)
        imported_images.add(image_name)
    final_import_status = "partial_imported" if (incomplete_rows or output_failed_rows or output_missing_result_rows) else "imported"
    import_report = {
        "status": final_import_status,
        "dataset_id": target_dataset_id,
        "rows": len(rows),
        "images": len(imported_images),
        "saved_captions": saved_captions,
        "saved_generated_qa_rows": saved_qa,
        "archived_generated_qa_rows": archived_generated_qa_rows,
        "skipped_rows": skipped_rows,
        "incomplete_rows": incomplete_rows,
        "failed_output_rows": output_failed_rows,
        "missing_result_rows": output_missing_result_rows,
        "already_imported_rows": already_imported_rows,
        "incomplete_row_samples": incomplete_row_samples,
        "target_verification": verification,
    }
    if (saved_captions or saved_qa) and bool(request_payload.instruction_dataset):
        job = _openai_caption_batch_attach_instruction_artifacts(
            job,
            dataset_id=target_dataset_id,
            payload=request_payload,
            import_report=import_report,
            force=True,
        )
        import_report = (
            dict(job.get("import_report"))
            if isinstance(job.get("import_report"), Mapping)
            else import_report
        )
    job["status"] = "collected" if (incomplete_rows or output_failed_rows or output_missing_result_rows) else "imported"
    job["message"] = (
        f"Imported OpenAI Batch output: {saved_captions} caption(s), "
        f"{saved_qa} generated QA row(s)."
        + (f" {incomplete_rows} incomplete row(s) remain held for catch-up." if incomplete_rows else "")
        + (f" {output_missing_result_rows} missing result row(s) should be retried with catch-up." if output_missing_result_rows else "")
        + (
            f" {max(0, output_failed_rows - output_missing_result_rows)} failed output row(s) remain."
            if output_failed_rows > output_missing_result_rows
            else ""
        )
    )
    job["import_report"] = import_report
    job["result"] = {
        **(dict(job.get("result") or {}) if isinstance(job.get("result"), Mapping) else {}),
        "import": import_report,
    }
    job["cost_summary"] = _openai_caption_batch_cost_summary(job)
    job = _openai_caption_batch_log(job, "OpenAI Batch outputs imported", report=import_report)
    return _openai_caption_batch_job_public(job)


def _openai_caption_batch_incomplete_cases_for_single_job(job: Mapping[str, Any]) -> List[Dict[str, Any]]:
    artifact_dir = _openai_caption_batch_artifact_dir(job)
    cases = _openai_caption_batch_load_json_list(artifact_dir / "cases.json")
    case_by_id = {str(case.get("case_id") or "").strip(): dict(case) for case in cases if isinstance(case, Mapping)}
    request_data = job.get("request") if isinstance(job.get("request"), Mapping) else {}
    try:
        normalized_request = QwenCaptionDatasetJobRequest(**dict(request_data or {}))
        request_imposed_source = normalized_request.instruction_qa_imposed_questions
    except Exception:
        request_imposed_source = (
            request_data.get("instruction_qa_imposed_questions")
            if isinstance(request_data.get("instruction_qa_imposed_questions"), list)
            else []
        )
    request_imposed = [
        str(question or "").strip()
        for question in request_imposed_source
        if str(question or "").strip()
    ]
    request_imposed_keys = {
        re.sub(r"\s+", " ", question.strip().lower())
        for question in request_imposed
        if question.strip()
    }
    rows = _openai_caption_batch_read_jsonl(artifact_dir / "incomplete_captions.jsonl")
    if not rows:
        # Recover older artifacts that wrote partial rows into captions.jsonl before
        # the accepted/incomplete split existed.
        rows = [
            row
            for row in _openai_caption_batch_read_jsonl(artifact_dir / "captions.jsonl")
            if _openai_caption_usage_number(row.get("generated_qa_target_pair_count"))
            and _openai_caption_usage_number(row.get("generated_qa_pair_count") or len(row.get("generated_qa_pairs") or []))
            < _openai_caption_usage_number(row.get("generated_qa_target_pair_count"))
        ]
    retryable_failure_reasons = {
        "missing_batch_result",
        "batch_row_error",
        "caption_missing",
        "output_truncated",
    }
    failed_result_rows = [
        row
        for row in _openai_caption_batch_read_jsonl(artifact_dir / "results.jsonl")
        if str(row.get("final_status") or "").strip().lower() == "failed"
        and (
            str(row.get("failure_reason") or "").strip() in retryable_failure_reasons
            or str(row.get("failure_reason") or "").strip().startswith("http_status_")
        )
    ]
    catchup_cases: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for row in failed_result_rows:
        case_id = str(row.get("case_id") or "").strip()
        if not case_id or case_id in seen:
            continue
        case = dict(case_by_id.get(case_id) or {})
        if not case:
            continue
        failure_reason = str(row.get("failure_reason") or "").strip()
        target = _openai_caption_usage_number(row.get("generated_qa_target_pair_count"))
        if target <= 0:
            target = _openai_caption_usage_number(
                request_data.get("target_generated_qa_per_image")
                or request_data.get("increment_generated_qa_per_image")
            )
        case["_openai_batch_catchup_source_job_id"] = str(job.get("job_id") or "")
        case["_openai_batch_missing_result_retry"] = failure_reason == "missing_batch_result"
        case["_openai_batch_failed_result_retry"] = failure_reason != "missing_batch_result"
        case["_openai_batch_retry_failure_reason"] = failure_reason or "failed_result"
        case["_openai_batch_total_qa_target"] = target
        case["_openai_batch_target_qa"] = target
        catchup_cases.append(case)
        seen.add(case_id)
    for row in rows:
        case_id = str(row.get("case_id") or "").strip()
        if not case_id or case_id in seen:
            continue
        case = dict(case_by_id.get(case_id) or {})
        if not case:
            continue
        failure_reason = str(row.get("failure_reason") or "").strip()
        caption_request = request_data.get("caption_request") if isinstance(request_data.get("caption_request"), Mapping) else {}
        output_cap = _openai_caption_usage_number(caption_request.get("max_new_tokens") if isinstance(caption_request, Mapping) else None)
        if output_cap <= 0:
            openai_meta = job.get("openai") if isinstance(job.get("openai"), Mapping) else {}
            output_cap = _openai_caption_usage_number(openai_meta.get("max_output_tokens") if isinstance(openai_meta, Mapping) else None)
        usage = row.get("usage") if isinstance(row.get("usage"), Mapping) else {}
        output_tokens = _openai_caption_usage_number(usage.get("output_tokens") if isinstance(usage, Mapping) else None)
        row_hit_output_cap = (
            failure_reason == "output_truncated"
            or bool(row.get("output_truncated"))
            or (output_cap > 0 and output_tokens >= max(1, output_cap - 4))
        )
        if row_hit_output_cap:
            target = _openai_caption_usage_number(row.get("generated_qa_target_pair_count"))
            if target <= 0:
                target = _openai_caption_usage_number(
                    request_data.get("target_generated_qa_per_image")
                    or request_data.get("increment_generated_qa_per_image")
                )
            case["_openai_batch_catchup_source_job_id"] = str(job.get("job_id") or "")
            case["_openai_batch_truncated_retry"] = True
            case["_openai_batch_retry_failure_reason"] = failure_reason or "output_truncated"
            case["_openai_batch_total_qa_target"] = target
            case["_openai_batch_target_qa"] = target
            catchup_cases.append(case)
            seen.add(case_id)
            continue
        pairs = row.get("generated_qa_pairs") if isinstance(row.get("generated_qa_pairs"), list) else []
        clean_pairs = [
            {"question": str(pair.get("question") or "").strip(), "answer": str(pair.get("answer") or "").strip()}
            for pair in pairs
            if isinstance(pair, Mapping) and str(pair.get("question") or "").strip() and str(pair.get("answer") or "").strip()
        ]
        target = _openai_caption_usage_number(row.get("generated_qa_target_pair_count"))
        missing_required = [
            str(question or "").strip()
            for question in (row.get("missing_required_questions") if isinstance(row.get("missing_required_questions"), list) else [])
            if str(question or "").strip()
        ]
        if target <= 0 and not missing_required:
            continue
        if missing_required:
            target = max(target, len(missing_required))
            keep_count = max(0, target - len(missing_required))
            missing_required_keys = {
                re.sub(r"\s+", " ", question.strip().lower())
                for question in missing_required
                if question.strip()
            }
            kept_pairs: List[Dict[str, str]] = []
            priority_pairs: List[Dict[str, str]] = []
            other_pairs: List[Dict[str, str]] = []
            for pair in clean_pairs:
                key = re.sub(r"\s+", " ", str(pair.get("question") or "").strip().lower())
                if key and key in request_imposed_keys and key not in missing_required_keys:
                    priority_pairs.append(pair)
                else:
                    other_pairs.append(pair)
            for pair in [*priority_pairs, *other_pairs]:
                if len(kept_pairs) >= keep_count:
                    break
                kept_pairs.append(pair)
            clean_pairs = kept_pairs
        missing = max(0, target - len(clean_pairs), len(missing_required))
        if missing <= 0:
            continue
        caption = str(row.get("caption") or "").strip()
        if not caption:
            continue
        case["_openai_batch_catchup_source_job_id"] = str(job.get("job_id") or "")
        case["_openai_batch_existing_caption"] = caption
        case["_openai_batch_existing_qa_pairs"] = clean_pairs[:100]
        case["_openai_batch_existing_qa_count"] = len(clean_pairs)
        case["_openai_batch_total_qa_target"] = target
        case["_openai_batch_target_qa"] = missing
        if missing_required:
            case["_openai_batch_missing_required_questions"] = missing_required
        catchup_cases.append(case)
        seen.add(case_id)
    return catchup_cases


def _openai_caption_batch_incomplete_cases(job: Mapping[str, Any]) -> List[Dict[str, Any]]:
    if str(job.get("kind") or "") == "openai_caption_batch_collection":
        cases: List[Dict[str, Any]] = []
        for child in _openai_caption_batch_collection_child_jobs(job):
            cases.extend(_openai_caption_batch_incomplete_cases_for_single_job(child))
        return cases
    return _openai_caption_batch_incomplete_cases_for_single_job(job)


def _openai_caption_batch_catchup_job(job_id: str) -> Dict[str, Any]:
    job = _openai_caption_batch_read(job_id)
    resolution = _openai_caption_batch_catchup_resolution(job)
    if resolution:
        state = str(resolution.get("state") or "").lower()
        if state in {"active", "ready", "resolved", "unknown"}:
            detail = (
                "openai_caption_batch_catchup_already_imported"
                if state == "resolved"
                else "openai_caption_batch_catchup_already_queued"
            )
            raise HTTPException(status_code=HTTP_409_CONFLICT, detail=detail)
    status = _openai_caption_batch_normalize_status(job.get("status"))
    if status == "completed_remote" or str(job.get("kind") or "") == "openai_caption_batch_collection":
        try:
            _openai_caption_batch_collect_job(job_id)
        except Exception:
            logger.debug("OpenAI Batch catch-up pre-collection failed for %s", job_id, exc_info=True)
    job = _openai_caption_batch_read(job_id)
    catchup_cases = _openai_caption_batch_incomplete_cases(job)
    if not catchup_cases:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_caption_batch_no_incomplete_rows")
    request_data = dict(job.get("request") or {})
    request_data["caption_provider"] = "openai"
    request_data["openai_service_tier"] = "batch"
    caption_request = dict(request_data.get("caption_request") or {})
    current_max_tokens = _openai_caption_usage_number(caption_request.get("max_new_tokens"))
    if current_max_tokens < OPENAI_CAPTION_BATCH_DEFAULT_MAX_OUTPUT_TOKENS:
        caption_request["max_new_tokens"] = OPENAI_CAPTION_BATCH_DEFAULT_MAX_OUTPUT_TOKENS
    request_data["caption_request"] = caption_request
    request_payload = QwenCaptionDatasetJobRequest(**request_data)
    manifest = {
        "dataset_label": str(job.get("dataset_label") or request_payload.dataset_id or "caption_dataset"),
    }
    catchup = _openai_caption_batch_start_with_cases(
        request_payload=request_payload,
        manifest=manifest,
        cases=catchup_cases,
        job_id_prefix="ocap_catchup",
        catchup_for_job_id=job_id,
    )
    source = _openai_caption_batch_read(job_id)
    source["last_catchup_job_id"] = catchup.get("job_id")
    source = _openai_caption_batch_log(
        source,
        "OpenAI Batch catch-up job queued",
        catchup_job_id=catchup.get("job_id"),
        incomplete_case_count=len(catchup_cases),
    )
    return catchup


def _openai_caption_batch_cancel_job(job_id: str) -> Dict[str, Any]:
    from tools import run_openai_caption_batch_smoke as batch_smoke
    import urllib.parse

    job = _openai_caption_batch_read(job_id)
    if str(job.get("kind") or "") == "openai_caption_batch_collection":
        for child in _openai_caption_batch_collection_child_jobs(job):
            child_id = str(child.get("job_id") or "").strip()
            if not child_id:
                continue
            child_status = _openai_caption_batch_normalize_status(child.get("status"))
            if child_status in OPENAI_CAPTION_BATCH_FINAL_STATUSES:
                continue
            try:
                _openai_caption_batch_cancel_job(child_id)
            except Exception:
                logger.debug("Failed to cancel OpenAI caption Batch shard %s", child_id, exc_info=True)
        job = _openai_caption_batch_refresh_collection_job(job_id)
        summary = job.get("shard_summary") if isinstance(job.get("shard_summary"), Mapping) else {}
        status_counts = summary.get("status_counts") if isinstance(summary.get("status_counts"), Mapping) else {}
        usable_shards = sum(int(status_counts.get(status) or 0) for status in ("completed_remote", "collected", "imported"))
        active_shards = int(summary.get("active_shards") or 0)
        if active_shards <= 0 and usable_shards <= 0:
            job["status"] = "cancelled"
        job["message"] = (
            "OpenAI Batch collection cancellation requested; completed, collected, "
            "and imported shard records were preserved."
        )
        job = _openai_caption_batch_log(job, "OpenAI Batch collection cancellation requested", summary=summary)
        return _openai_caption_batch_job_public(job)
    status = _openai_caption_batch_normalize_status(job.get("status"))
    if status in OPENAI_CAPTION_BATCH_FINAL_STATUSES:
        return _openai_caption_batch_job_public(job)
    batch_id = str(job.get("openai_batch_id") or "").strip()
    if batch_id:
        payload = QwenCaptionDatasetJobRequest(**dict(job.get("request") or {}))
        key = _openai_caption_batch_api_key(payload.openai_api_key_path)
        args = _openai_caption_batch_args(
            payload,
            request_path=Path(str(job.get("request_json") or _openai_caption_batch_artifact_dir(job) / "request_fields.json")),
        )
        try:
            response, headers = batch_smoke.request_json(
                key=key,
                method="POST",
                path=f"/batches/{urllib.parse.quote(batch_id)}/cancel",
                body={},
                timeout=args.timeout,
            )
            job["cancel_response"] = {"response": response, "headers": headers}
        except Exception as exc:
            job["cancel_response"] = {"error": str(exc)}
    job["status"] = "cancelled"
    job["message"] = "OpenAI Batch cancellation requested."
    job = _openai_caption_batch_log(job, "OpenAI Batch cancellation requested", openai_batch_id=batch_id)
    return _openai_caption_batch_job_public(job)


def _openai_caption_batch_file_inventory(artifact_dir: Path) -> Dict[str, Any]:
    names = [
        "openai_batch_job.json",
        "target_manifest.json",
        "cases.json",
        "manifest.json",
        "request_fields.json",
        "image_files.jsonl",
        "batch_input.jsonl",
        "batch_input_file.json",
        "batch.json",
        "batch_status.json",
        "batch_output.jsonl",
        "batch_error.jsonl",
        "captions.jsonl",
        "incomplete_captions.jsonl",
        "imported_rows.jsonl",
        "results.jsonl",
        "summary.json",
        "openai_batch_events.jsonl",
    ]
    files: Dict[str, Any] = {}
    for name in names:
        path = artifact_dir / name
        try:
            stat_result = path.stat()
            files[name] = {
                "exists": True,
                "bytes": int(stat_result.st_size),
                "modified_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(stat_result.st_mtime)),
            }
        except Exception:
            files[name] = {"exists": False}
    return files


def _openai_caption_batch_artifact_has_legacy_cases(source_dir: Path) -> bool:
    manifest = _openai_caption_batch_load_json_mapping(source_dir / "manifest.json")
    if isinstance(manifest.get("cases"), list) and manifest.get("cases"):
        return True
    cases_json = str(manifest.get("cases_json") or "").strip()
    if not cases_json:
        return False
    cases_path = Path(cases_json).expanduser()
    if not cases_path.is_absolute():
        cases_path = (source_dir / cases_path).resolve(strict=False)
    return cases_path.exists()


def _openai_caption_batch_read_events(artifact_dir: Path, limit: int = 200) -> List[Dict[str, Any]]:
    path = artifact_dir / "openai_batch_events.jsonl"
    if not path.exists():
        return []
    events: List[Dict[str, Any]] = []
    try:
        for line in path.read_text(encoding="utf-8").splitlines()[-limit:]:
            try:
                item = json.loads(line)
            except Exception:
                continue
            if isinstance(item, Mapping):
                events.append(dict(item))
    except Exception:
        return []
    return events


def _openai_caption_batch_detail(job_id: str, dataset_id: Optional[str] = None) -> Dict[str, Any]:
    job = _openai_caption_batch_read(job_id)
    public = _openai_caption_batch_job_public(
        job,
        dataset_id=dataset_id,
        include_children=True,
        include_match=bool(dataset_id),
    )
    artifact_dir = _openai_caption_batch_artifact_dir(job)
    public["artifact_inventory"] = _openai_caption_batch_file_inventory(artifact_dir)
    public["events"] = _openai_caption_batch_read_events(artifact_dir)
    if str(job.get("kind") or "") == "openai_caption_batch_collection":
        child_samples: List[Dict[str, Any]] = []
        for child in _openai_caption_batch_collection_child_jobs(job)[:25]:
            child_dir = _openai_caption_batch_artifact_dir(child)
            samples = _openai_caption_batch_output_samples(child_dir, limit=3)
            if (
                int(samples.get("accepted_caption_row_count") or 0)
                or int(samples.get("incomplete_caption_row_count") or 0)
                or int(samples.get("result_row_count") or 0)
            ):
                child_samples.append(
                    {
                        "job_id": child.get("job_id"),
                        "status": child.get("status"),
                        "samples": samples,
                    }
                )
        public["collected_output_samples"] = {
            "children": child_samples,
            "child_sample_limit": 25,
        }
    else:
        public["collected_output_samples"] = _openai_caption_batch_output_samples(artifact_dir)
    target_path = _openai_caption_batch_target_manifest_path(job, artifact_dir)
    if target_path.exists():
        try:
            target = json.loads(target_path.read_text(encoding="utf-8"))
            if isinstance(target, Mapping):
                public["target_snapshot_summary"] = {
                    "dataset_id": target.get("dataset_id"),
                    "dataset_label": target.get("dataset_label"),
                    "case_count": target.get("case_count"),
                    "dataset_fingerprint": target.get("dataset_fingerprint"),
                    "label_fingerprint": target.get("label_fingerprint"),
                    "target_hash": target.get("target_hash"),
                    "target_identity": target.get("target_identity") if isinstance(target.get("target_identity"), Mapping) else {},
                }
        except Exception:
            public["target_snapshot_summary"] = {"error": "target_manifest_unreadable"}
    return public


def _openai_caption_batch_archive_job(job_id: str, archived: bool = True) -> Dict[str, Any]:
    job = _openai_caption_batch_read(job_id)
    if archived:
        if str(job.get("kind") or "") == "openai_caption_batch_collection":
            refreshed = _openai_caption_batch_refresh_collection_job(job_id)
            summary = refreshed.get("shard_summary") if isinstance(refreshed.get("shard_summary"), Mapping) else {}
            if int(summary.get("active_shards") or 0) > 0:
                raise HTTPException(status_code=409, detail="openai_caption_batch_archive_active_collection")
            job = refreshed
        elif _openai_caption_batch_normalize_status(job.get("status")) in OPENAI_CAPTION_BATCH_ACTIVE_STATUSES:
            raise HTTPException(status_code=409, detail="openai_caption_batch_archive_active_job")
    job["archived"] = bool(archived)
    job["archived_at"] = _openai_caption_batch_now() if archived else ""
    job["message"] = "OpenAI Batch job archived." if archived else "OpenAI Batch job restored."
    job = _openai_caption_batch_log(job, job["message"])
    return _openai_caption_batch_job_public(job)


def _openai_caption_batch_response_from_artifact(source_dir: Path) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
    batch: Dict[str, Any] = {}
    status: Dict[str, Any] = {}
    candidates: List[Dict[str, Any]] = []
    if (source_dir / "batch.json").exists():
        try:
            loaded = json.loads((source_dir / "batch.json").read_text(encoding="utf-8"))
            if isinstance(loaded, Mapping):
                batch = dict(loaded)
                response = batch.get("response") if isinstance(batch.get("response"), Mapping) else {}
                if response:
                    candidates.append(dict(response))
        except Exception:
            batch = {}
    if (source_dir / "batch_status.json").exists():
        try:
            loaded = json.loads((source_dir / "batch_status.json").read_text(encoding="utf-8"))
            if isinstance(loaded, Mapping):
                status = dict(loaded)
                response = status.get("response") if isinstance(status.get("response"), Mapping) else {}
                if response:
                    candidates.append(dict(response))
        except Exception:
            status = {}
    response = _openai_caption_batch_best_response(candidates)
    return dict(batch), dict(status), dict(response) if isinstance(response, Mapping) else {}


def _openai_caption_batch_registered_sources() -> Dict[str, str]:
    registered: Dict[str, str] = {}
    root = _openai_caption_batch_root()
    try:
        children = [child for child in root.iterdir() if child.is_dir()]
    except Exception:
        children = []
    for child in children:
        path = child / "openai_batch_job.json"
        if not path.exists():
            continue
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(payload, Mapping):
            continue
        job_id = str(payload.get("job_id") or "").strip()
        for key in ("source_output_dir", "output_dir"):
            raw = str(payload.get(key) or "").strip()
            if raw and job_id:
                registered[str(Path(raw).expanduser().resolve(strict=False))] = job_id
    return registered


def _openai_caption_batch_scan_artifact(source_dir: Path, registered_sources: Mapping[str, str]) -> Dict[str, Any]:
    resolved = source_dir.expanduser().resolve(strict=False)
    inventory = _openai_caption_batch_file_inventory(resolved)
    _batch, _status, response = _openai_caption_batch_response_from_artifact(resolved)
    batch_id = str(response.get("id") or "").strip()
    registered_job_id = registered_sources.get(str(resolved), "")
    has_target = bool((inventory.get("target_manifest.json") or {}).get("exists"))
    has_cases = bool((inventory.get("cases.json") or {}).get("exists")) or _openai_caption_batch_artifact_has_legacy_cases(resolved)
    has_batch = bool((inventory.get("batch.json") or {}).get("exists"))
    has_status = bool((inventory.get("batch_status.json") or {}).get("exists"))
    has_outputs = bool((inventory.get("captions.jsonl") or {}).get("exists")) or bool((inventory.get("batch_output.jsonl") or {}).get("exists"))
    if registered_job_id:
        status = "registered"
        adoptable = False
        reason = "already_registered"
    elif batch_id and has_target:
        status = "adoptable"
        adoptable = True
        reason = "ready_to_adopt"
    elif batch_id and has_cases:
        status = "adoptable_unverified"
        adoptable = True
        reason = "target_manifest_missing_recoverable_from_cases"
    elif batch_id:
        status = "adoptable_unverified"
        adoptable = True
        reason = "target_manifest_missing"
    elif has_batch or has_status:
        status = "incomplete"
        adoptable = False
        reason = "batch_id_missing"
    else:
        status = "not_batch_artifact"
        adoptable = False
        reason = "batch_files_missing"
    return {
        "artifact_dir": str(resolved),
        "status": status,
        "adoptable": adoptable,
        "reason": reason,
        "registered_job_id": registered_job_id,
        "openai_batch_id": batch_id,
        "openai_status": str(response.get("status") or "").strip().lower(),
        "request_counts": dict(response.get("request_counts") or {}),
        "has_target_manifest": has_target,
        "has_cases": has_cases,
        "has_outputs": has_outputs,
        "inventory": inventory,
    }


def _openai_caption_batch_scan(payload: Mapping[str, Any]) -> Dict[str, Any]:
    path_values: List[Any] = []
    for key in ("artifact_dirs", "roots"):
        value = payload.get(key)
        if isinstance(value, list):
            path_values.extend(value)
    explicit_paths = [str(path or "").strip() for path in path_values if str(path or "").strip()]
    explicit_roots: List[Path] = []
    for raw in explicit_paths:
        candidate = Path(raw).expanduser()
        if not candidate.is_absolute():
            candidate = (Path.cwd() / candidate).resolve(strict=False)
        candidate = candidate.resolve(strict=False)
        if _qwen_caption_dataset_can_write_job_payload_dir(str(candidate)):
            explicit_roots.append(candidate)
    roots = [*explicit_roots, _openai_caption_batch_root(), QWEN_CAPTION_DATASET_JOB_ROOT]
    registered_sources = _openai_caption_batch_registered_sources()
    seen: Set[str] = set()
    seen_roots: Set[str] = set()
    artifacts: List[Dict[str, Any]] = []
    marker_names = {"batch.json", "batch_status.json", "target_manifest.json", "openai_batch_job.json"}
    visited_dirs = 0
    truncated = False
    for root in roots:
        try:
            root = root.expanduser().resolve(strict=False)
        except Exception:
            continue
        if not _qwen_caption_dataset_can_write_job_payload_dir(str(root)):
            continue
        root_key = str(root)
        if root_key in seen_roots:
            continue
        seen_roots.add(root_key)
        candidate_dirs: List[Path] = []
        try:
            immediate_children = sorted([child for child in root.iterdir() if child.is_dir()], key=lambda item: str(item))
        except Exception:
            immediate_children = []
        fast_candidates = [root, *immediate_children[:OPENAI_CAPTION_BATCH_SCAN_LIMIT]]
        for candidate in fast_candidates:
            try:
                names = {path.name for path in candidate.iterdir() if path.is_file()}
            except Exception:
                continue
            if marker_names & names:
                candidate_dirs.append(candidate)
                if len(candidate_dirs) >= OPENAI_CAPTION_BATCH_SCAN_LIMIT:
                    truncated = True
                    break
        if len(candidate_dirs) < OPENAI_CAPTION_BATCH_SCAN_LIMIT:
            root_visited_dirs = 0
            try:
                for dirpath, dirnames, filenames in os.walk(root):
                    visited_dirs += 1
                    root_visited_dirs += 1
                    if root_visited_dirs >= OPENAI_CAPTION_BATCH_SCAN_VISIT_LIMIT:
                        truncated = True
                        dirnames[:] = []
                        break
                    if marker_names & set(filenames):
                        candidate_dirs.append(Path(dirpath))
                        if len(candidate_dirs) >= OPENAI_CAPTION_BATCH_SCAN_LIMIT:
                            truncated = True
                            dirnames[:] = []
                            break
                    dirnames[:] = sorted(dirnames)
            except Exception:
                continue
        for candidate_dir in candidate_dirs:
            resolved_key = str(candidate_dir.expanduser().resolve(strict=False))
            if resolved_key in seen:
                continue
            seen.add(resolved_key)
            artifacts.append(_openai_caption_batch_scan_artifact(candidate_dir, registered_sources))
            if len(artifacts) >= OPENAI_CAPTION_BATCH_SCAN_LIMIT:
                truncated = True
                break
    return {
        "format": "tator_openai_caption_batch_scan_v1",
        "scanned_at": _openai_caption_batch_now(),
        "roots": [str(root) for root in roots],
        "artifact_count": len(artifacts),
        "artifacts": artifacts,
        "limit": OPENAI_CAPTION_BATCH_SCAN_LIMIT,
        "visited_dirs": visited_dirs,
        "truncated": truncated,
        "scan_limit_reached": truncated,
    }


def _openai_caption_batch_adopt(payload: Mapping[str, Any]) -> Dict[str, Any]:
    source_raw = str(payload.get("artifact_dir") or payload.get("output_dir") or "").strip()
    if not source_raw:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_caption_batch_artifact_dir_required")
    source_dir = Path(source_raw).expanduser()
    if not source_dir.is_absolute():
        source_dir = (Path.cwd() / source_dir).resolve(strict=False)
    source_dir = source_dir.resolve(strict=False)
    if not _qwen_caption_dataset_can_write_job_payload_dir(str(source_dir)):
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_caption_batch_artifact_dir_forbidden")
    batch, status, response = _openai_caption_batch_response_from_artifact(source_dir)
    response_metadata = response.get("metadata") if isinstance(response.get("metadata"), Mapping) else {}
    batch_id = str(response.get("id") or payload.get("openai_batch_id") or "").strip()
    if not batch_id:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_caption_batch_id_missing")
    job_id = f"ocap_adopt_{hashlib.sha1(str(source_dir).encode('utf-8')).hexdigest()[:12]}"
    manager_dir = _openai_caption_batch_job_dir(job_id)
    manager_dir.mkdir(parents=True, exist_ok=True)
    dataset_id = str(payload.get("dataset_id") or "").strip()
    target_snapshot: Dict[str, Any] = {}
    target_path = source_dir / "target_manifest.json"
    target_manifest_path = ""
    target_snapshot_status = "missing"
    if target_path.exists():
        try:
            loaded_target = json.loads(target_path.read_text(encoding="utf-8"))
            if isinstance(loaded_target, Mapping):
                target_snapshot = dict(loaded_target)
                dataset_id = dataset_id or str(target_snapshot.get("dataset_id") or "").strip()
                target_manifest_path = str(target_path)
                target_snapshot_status = "present"
        except Exception:
            target_snapshot = {}
    request_payload: Dict[str, Any] = {}
    request_path = source_dir / "request_fields.json"
    if request_path.exists():
        try:
            request_payload["caption_request"] = json.loads(request_path.read_text(encoding="utf-8"))
        except Exception:
            request_payload["caption_request"] = {}
    try:
        adopted_qa_count = int(payload.get("qa_count") or response_metadata.get("qa_count") or 8)
    except (TypeError, ValueError, OverflowError):
        adopted_qa_count = 8
    request_payload.update(
        {
            "dataset_id": dataset_id,
            "caption_provider": "openai",
            "openai_service_tier": "batch",
            "openai_model": str(payload.get("openai_model") or response_metadata.get("model") or "gpt-5.5"),
            "openai_image_detail": str(payload.get("openai_image_detail") or response_metadata.get("image_detail") or "original"),
            "openai_reasoning_effort": _openai_caption_normalize_reasoning_effort(
                payload.get("openai_reasoning_effort") or response_metadata.get("reasoning_effort")
            ),
            "openai_api_key_path": str(payload.get("openai_api_key_path") or "openAI_API_KEY_DoNotCommit"),
            "instruction_dataset": True,
            "include_generated_qa_in_training": True,
            "subcaptions_per_image": max(0, min(adopted_qa_count, 20)),
        }
    )
    if not target_snapshot:
        target_snapshot, target_manifest_path = _openai_caption_batch_synthesize_legacy_target_snapshot(
            source_dir=source_dir,
            manager_dir=manager_dir,
            dataset_id=dataset_id,
            request_payload=request_payload,
        )
        if target_snapshot:
            target_snapshot_status = "legacy_synthesized"
    job = {
        "job_id": job_id,
        "kind": "openai_caption_batch",
        "status": "in_progress",
        "message": (
            "Adopted OpenAI Batch artifact directory."
            if target_snapshot_status == "present"
            else "Adopted OpenAI Batch artifact directory with a recovered target snapshot; verify it against the selected dataset before import."
            if target_snapshot_status == "legacy_synthesized"
            else "Adopted OpenAI Batch artifact directory without a target snapshot; import will remain blocked until a safe target is available."
        ),
        "dataset_id": dataset_id,
        "dataset_label": target_snapshot.get("dataset_label") if target_snapshot else "",
        "dataset_fingerprint": target_snapshot.get("dataset_fingerprint") if target_snapshot else "",
        "label_fingerprint": target_snapshot.get("label_fingerprint") if target_snapshot else "",
        "target_identity": target_snapshot.get("target_identity") if isinstance(target_snapshot.get("target_identity"), Mapping) else {},
        "target_manifest": target_manifest_path,
        "target_snapshot_status": target_snapshot_status,
        "request": request_payload,
        "created_at": _openai_caption_batch_now(),
        "updated_at": _openai_caption_batch_now(),
        "output_dir": str(manager_dir),
        "source_output_dir": str(source_dir),
        "openai_batch_id": batch_id,
        "openai_status": str(response.get("status") or "").strip().lower(),
        "request_counts": dict(response.get("request_counts") or {}),
        "output_file_id": str(response.get("output_file_id") or "").strip(),
        "error_file_id": str(response.get("error_file_id") or "").strip(),
        "logs": [],
        "result": {"batch": response},
    }
    job = _openai_caption_batch_refresh_from_response(job, {"response": response})
    job = _openai_caption_batch_log(job, "OpenAI Batch artifact adopted", source_output_dir=str(source_dir))
    return _openai_caption_batch_job_public(job)


def _openai_caption_spend_cache_dir() -> Path:
    root = _openai_caption_batch_root() / "_spend_cache"
    root.mkdir(parents=True, exist_ok=True)
    return root


def _openai_caption_cost_amount_usd(result: Any) -> float:
    if not isinstance(result, Mapping):
        return 0.0
    amount = result.get("amount")
    if isinstance(amount, Mapping):
        currency = str(amount.get("currency") or "usd").strip().lower()
        if currency and currency != "usd":
            return 0.0
        try:
            return float(amount.get("value") or 0.0)
        except (TypeError, ValueError, OverflowError):
            return 0.0
    try:
        return float(amount or 0.0)
    except (TypeError, ValueError, OverflowError):
        return 0.0


def _openai_caption_cost_group_key(result: Mapping[str, Any], group_by: Sequence[str]) -> Tuple[Tuple[str, str], ...]:
    return tuple((field, str(result.get(field) if result.get(field) is not None else "")) for field in group_by)


def _openai_caption_summarize_costs_response(response: Mapping[str, Any], group_by: Sequence[str]) -> Dict[str, Any]:
    total = 0.0
    groups: Dict[Tuple[Tuple[str, str], ...], Dict[str, Any]] = {}
    bucket_count = 0
    result_count = 0
    buckets_out: List[Dict[str, Any]] = []
    for bucket in response.get("data") or []:
        if not isinstance(bucket, Mapping):
            continue
        bucket_count += 1
        bucket_total = 0.0
        bucket_results: List[Dict[str, Any]] = []
        for result in bucket.get("results") or []:
            if not isinstance(result, Mapping):
                continue
            result_count += 1
            amount = _openai_caption_cost_amount_usd(result)
            total += amount
            bucket_total += amount
            key = _openai_caption_cost_group_key(result, group_by)
            group = groups.setdefault(
                key,
                {
                    "group": {field: value for field, value in key},
                    "cost_usd": 0.0,
                    "result_count": 0,
                },
            )
            group["cost_usd"] = round(float(group.get("cost_usd") or 0.0) + amount, 6)
            group["result_count"] = int(group.get("result_count") or 0) + 1
            bucket_results.append(
                {
                    "cost_usd": round(amount, 6),
                    "group": {field: str(result.get(field) if result.get(field) is not None else "") for field in group_by},
                    "line_item": result.get("line_item"),
                }
            )
        buckets_out.append(
            {
                "start_time": bucket.get("start_time"),
                "end_time": bucket.get("end_time"),
                "cost_usd": round(bucket_total, 6),
                "result_count": len(bucket_results),
                "results": bucket_results[:50],
                "result_limit": 50,
            }
        )
    group_rows = sorted(groups.values(), key=lambda item: float(item.get("cost_usd") or 0.0), reverse=True)
    return {
        "total_cost_usd": round(total, 6),
        "currency": "usd",
        "bucket_count": bucket_count,
        "result_count": result_count,
        "groups": group_rows[:200],
        "group_limit": 200,
        "buckets": buckets_out[:60],
        "bucket_limit": 60,
    }


def _openai_caption_fetch_spend(payload: Mapping[str, Any]) -> Dict[str, Any]:
    from tools import run_openai_caption_batch_smoke as batch_smoke
    import urllib.parse

    key, key_source = _openai_caption_admin_api_key(payload.get("admin_key_path"))
    now_ts = int(time.time())
    days = _openai_caption_usage_number(payload.get("days") or 30)
    days = max(1, min(days or 30, 180))
    start_time = _openai_caption_usage_number(payload.get("start_time"))
    end_time = _openai_caption_usage_number(payload.get("end_time"))
    if not end_time:
        end_time = now_ts
    if not start_time:
        start_time = max(0, end_time - days * 86400)
    if start_time >= end_time:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="openai_spend_time_range_invalid")
    bucket_width = str(payload.get("bucket_width") or "1d").strip()
    if bucket_width not in {"1d", "1h"}:
        bucket_width = "1d"
    raw_group_by = payload.get("group_by")
    if isinstance(raw_group_by, str):
        group_by = [item.strip() for item in raw_group_by.split(",") if item.strip()]
    elif isinstance(raw_group_by, Sequence) and not isinstance(raw_group_by, (bytes, bytearray)):
        group_by = [str(item or "").strip() for item in raw_group_by if str(item or "").strip()]
    else:
        group_by = ["api_key_id", "model", "batch"]
    group_by = [item for item in group_by if item in OPENAI_CAPTION_COST_GROUPS]
    if not group_by:
        group_by = ["api_key_id"]
    query_items: List[Tuple[str, Any]] = [
        ("start_time", start_time),
        ("end_time", end_time),
        ("bucket_width", bucket_width),
        ("limit", max(1, min(_openai_caption_usage_number(payload.get("limit") or 180) or 180, 180))),
    ]
    for field in group_by:
        query_items.append(("group_by", field))
    api_key_ids = payload.get("api_key_ids")
    if isinstance(api_key_ids, str):
        key_ids = [item.strip() for item in api_key_ids.split(",") if item.strip()]
    elif isinstance(api_key_ids, Sequence) and not isinstance(api_key_ids, (bytes, bytearray)):
        key_ids = [str(item or "").strip() for item in api_key_ids if str(item or "").strip()]
    else:
        key_ids = []
    for api_key_id in key_ids[:50]:
        query_items.append(("api_key_ids", api_key_id))
    path = f"/organization/costs?{urllib.parse.urlencode(query_items)}"
    response, headers = batch_smoke.request_json(key=key, method="GET", path=path, timeout=60.0)
    summary = _openai_caption_summarize_costs_response(response, group_by)
    result = {
        "status": "ok",
        "updated_at": _openai_caption_batch_now(),
        "window_days": round((end_time - start_time) / 86400.0, 3),
        "start_time": start_time,
        "end_time": end_time,
        "bucket_width": bucket_width,
        "group_by": group_by,
        "admin_key_source": "OPENAI_ADMIN_KEY" if key_source == "OPENAI_ADMIN_KEY" else f"file:{Path(key_source).name}",
        "headers": headers,
        **summary,
        "docs_note": "Organization Costs API requires an admin key; per-job Batch cost summaries use local token usage and pricing estimates.",
    }
    cache_name = f"openai_spend_{start_time}_{end_time}_{hashlib.sha1(','.join(group_by).encode('utf-8')).hexdigest()[:8]}.json"
    try:
        cache_path = _openai_caption_spend_cache_dir() / cache_name
        cache_path.write_text(json.dumps(result, indent=2, sort_keys=True), encoding="utf-8")
        result["cache_path"] = str(cache_path)
    except Exception:
        logger.debug("Failed to cache OpenAI spend response", exc_info=True)
    return result


def _qwen_caption_dataset_job_dir(job_id: str, requested_output_dir: Optional[str] = None) -> Path:
    if requested_output_dir:
        requested = Path(str(requested_output_dir)).expanduser()
        if not requested.is_absolute():
            requested = (Path.cwd() / requested).resolve()
        allowed_roots = [
            Path.cwd().resolve(),
            QWEN_CAPTION_DATASET_JOB_ROOT.resolve(),
        ]
        try:
            resolved = requested.resolve(strict=False)
        except Exception as exc:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="caption_job_output_dir_invalid") from exc
        if not any(_path_is_within_root_impl(resolved, root) for root in allowed_roots):
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="caption_job_output_dir_forbidden")
        return resolved
    safe_job_id = _sanitize_yolo_run_id_impl(job_id) or job_id
    return QWEN_CAPTION_DATASET_JOB_ROOT / safe_job_id


def _qwen_caption_dataset_job_discovery_dir(job_id: str) -> Path:
    safe_job_id = _sanitize_yolo_run_id_impl(job_id) or job_id
    return QWEN_CAPTION_DATASET_JOB_ROOT / safe_job_id


def _qwen_caption_dataset_compact_discovery_payload(
    payload: Mapping[str, Any],
) -> Dict[str, Any]:
    """Keep only fields needed to decide whether a full job must be loaded."""

    request_data = (
        payload.get("request")
        if isinstance(payload.get("request"), Mapping)
        else {}
    )
    result_data = (
        payload.get("result")
        if isinstance(payload.get("result"), Mapping)
        else {}
    )
    compact_request = {
        key: request_data.get(key)
        for key in (
            "dataset_id",
            "output_dir",
            "set_and_forget",
            "auto_resume_count",
            "max_auto_resumes",
            "runner_no_output_timeout_seconds",
        )
        if request_data.get(key) is not None
    }
    compact_result: Dict[str, Any] = {
        key: result_data.get(key)
        for key in (
            "dataset_id",
            "output_dir",
            "artifact_cancelled_at",
            "cancelled_at",
            "processed",
            "total_cases",
            "failed",
            "quality_failed",
            "saved_text_labels",
            "generated_qa_rows",
            "auto_resumed_job_id",
            "attempts_seen",
            "failed_attempts",
        )
        if result_data.get(key) is not None
    }
    for key in (
        "preflight",
        "runner_heartbeat",
        "latest_caption",
        "captions",
        "runner_totals",
    ):
        if result_data.get(key):
            compact_result[key] = True
    strict_audit = (
        result_data.get("strict_audit")
        if isinstance(result_data.get("strict_audit"), Mapping)
        else {}
    )
    if strict_audit:
        compact_result["strict_audit"] = {
            "status": strict_audit.get("status"),
            "checks": [
                {
                    "name": check.get("name"),
                    "status": check.get("status"),
                    "invalid_rows": check.get("invalid_rows"),
                }
                for check in strict_audit.get("checks") or []
                if isinstance(check, Mapping)
            ],
        }
    return {
        key: payload.get(key)
        for key in (
            "job_id",
            "status",
            "error",
            "message",
            "output_dir",
            "created_at",
            "updated_at",
        )
        if payload.get(key) is not None
    } | {
        "request": compact_request,
        "result": compact_result,
    }


def _qwen_caption_dataset_write_discovery_summary(
    destination: Path,
    payload: Mapping[str, Any],
) -> None:
    job_path = destination / "job.json"
    try:
        stat_result = job_path.stat()
        envelope = {
            "schema": "qwen-caption-job-discovery-v2",
            "job_json_size": int(stat_result.st_size),
            "job_json_mtime_ns": int(stat_result.st_mtime_ns),
            "payload": _qwen_caption_dataset_compact_discovery_payload(payload),
        }
        summary_path = destination / QWEN_CAPTION_DATASET_DISCOVERY_FILENAME
        tmp_path = summary_path.with_suffix(
            f"{summary_path.suffix}.{uuid.uuid4().hex}.tmp"
        )
        tmp_path.write_text(
            json.dumps(envelope, separators=(",", ":"), sort_keys=True)
        )
        tmp_path.replace(summary_path)
    except Exception:
        logger.debug(
            "Failed to persist compact Qwen caption discovery summary",
            exc_info=True,
        )


def _qwen_caption_dataset_numeric(value: Any, fallback: float = 0.0) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError, OverflowError):
        return float(fallback)
    if not math.isfinite(number):
        return float(fallback)
    return number


def _qwen_caption_dataset_live_step_plan(worker_progress: Mapping[str, Any]) -> List[Dict[str, str]]:
    raw_plan = worker_progress.get("step_plan")
    if isinstance(raw_plan, list):
        plan: List[Dict[str, str]] = []
        for index, raw_entry in enumerate(raw_plan):
            if not isinstance(raw_entry, Mapping):
                continue
            step_id = str(raw_entry.get("id") or f"step_{index + 1}").strip() or f"step_{index + 1}"
            entry = {
                "id": step_id,
                "label": str(raw_entry.get("label") or step_id).strip() or step_id,
            }
            detail = str(raw_entry.get("detail") or "").strip()
            if detail:
                entry["detail"] = detail[:280]
            plan.append(entry)
        if plan:
            return plan
    return [
        {"id": "case_start", "label": "Select image"},
        {"id": "prompt_stack", "label": "Build prompt stack"},
        {"id": "caption", "label": "Run Qwen caption"},
        {"id": "save", "label": "Save caption result"},
        {"id": "next_image", "label": "Advance to next image"},
    ]


def _qwen_caption_dataset_live_io_events(worker_progress: Mapping[str, Any]) -> List[Dict[str, str]]:
    raw_events = worker_progress.get("io_events")
    if isinstance(raw_events, list):
        events: List[Dict[str, str]] = []
        for raw_event in raw_events[-8:]:
            if not isinstance(raw_event, Mapping):
                continue
            event = str(raw_event.get("event") or "event").strip() or "event"
            text = str(raw_event.get("text") or raw_event.get("text_tail") or "")
            entry = {
                "event": event,
                "title": str(raw_event.get("title") or event).strip() or event,
                "text": text[-2000:],
            }
            kind = str(raw_event.get("kind") or "").strip()
            if kind:
                entry["kind"] = kind
            run_id = str(raw_event.get("run_id") or "").strip()
            if run_id:
                entry["run_id"] = run_id
            events.append(entry)
        if events:
            return events
    last_event = worker_progress.get("last_io_event")
    if isinstance(last_event, Mapping):
        event = str(last_event.get("event") or "event").strip() or "event"
        text = str(last_event.get("text_tail") or "")
        if text:
            return [
                {
                    "event": event,
                    "title": str(last_event.get("step_label") or event).strip() or event,
                    "text": text[-2000:],
                }
            ]
    return []


def _qwen_caption_dataset_live_log_lines(job: QwenCaptionDatasetJob) -> List[str]:
    lines: List[str] = []
    for entry in list(job.logs[-12:]):
        if not isinstance(entry, Mapping):
            continue
        message = str(entry.get("message") or "").strip()
        if message:
            lines.append(message)
    return lines[-12:]


def _qwen_caption_dataset_job_live_progress(job: QwenCaptionDatasetJob) -> Dict[str, Any]:
    result = job.result if isinstance(job.result, Mapping) else {}
    request = job.request if isinstance(job.request, Mapping) else {}
    caption_request = request.get("caption_request") if isinstance(request.get("caption_request"), Mapping) else {}
    heartbeat = result.get("runner_heartbeat") if isinstance(result.get("runner_heartbeat"), Mapping) else {}
    worker_progress = (
        heartbeat.get("worker_progress")
        if isinstance(heartbeat.get("worker_progress"), Mapping)
        else {}
    )
    latest_caption = result.get("latest_caption") if isinstance(result.get("latest_caption"), Mapping) else {}
    latest_generated_qa_pairs = (
        latest_caption.get("generated_qa_pairs")
        if isinstance(latest_caption.get("generated_qa_pairs"), list)
        else []
    )
    latest_generated_qa_warning = (
        latest_caption.get("generated_qa_warning")
        if isinstance(latest_caption.get("generated_qa_warning"), Mapping)
        else None
    )
    worker_qa_accumulator = (
        worker_progress.get("instruction_qa_accumulator")
        if isinstance(worker_progress.get("instruction_qa_accumulator"), Mapping)
        else None
    )
    saved_qa_accumulator = (
        latest_caption.get("generated_qa_accumulator")
        if isinstance(latest_caption.get("generated_qa_accumulator"), Mapping)
        else None
    )
    qa_accumulator = worker_qa_accumulator or saved_qa_accumulator
    if isinstance(qa_accumulator, Mapping):
        accumulator_pairs = qa_accumulator.get("pairs")
        if isinstance(accumulator_pairs, list):
            latest_generated_qa_pairs = accumulator_pairs
        accumulator_warning = qa_accumulator.get("warning")
        if isinstance(accumulator_warning, Mapping) and latest_generated_qa_warning is None:
            latest_generated_qa_warning = accumulator_warning
    status = str(job.status or "").strip().lower()
    active = status in {"queued", "running", "cancelling"}
    phase_map = {
        "completed": "complete",
        "failed": "error",
        "interrupted": "error",
        "cancelled": "cancelled",
    }
    phase = phase_map.get(status)
    if not phase:
        phase = (
            str(worker_progress.get("phase") or "").strip()
            or str(heartbeat.get("phase") or "").strip()
            or ("queued" if status == "queued" else "running")
        )
    if active and phase == "complete":
        phase = str(heartbeat.get("phase") or "").strip() or "running"
    phase_label = str(worker_progress.get("phase_label") or "").strip()
    if active and phase_label.lower() == "complete":
        phase_label = ""
    if not phase_label:
        phase_label = {
            "queued": "Queued",
            "complete": "Complete",
            "error": "Error",
            "cancelled": "Cancelled",
        }.get(phase, "Captioning")

    total = int(
        max(
            0.0,
            _qwen_caption_dataset_numeric(heartbeat.get("total_cases"), result.get("total_cases") or 0),
        )
    )
    processed = int(
        max(
            0.0,
            _qwen_caption_dataset_numeric(heartbeat.get("processed"), result.get("processed") or 0),
        )
    )
    case_index = int(max(0.0, _qwen_caption_dataset_numeric(heartbeat.get("case_index"), 0.0)))
    worker_fraction = max(0.0, min(1.0, _qwen_caption_dataset_numeric(worker_progress.get("progress"), 0.0)))
    job_fraction = max(0.0, min(1.0, _qwen_caption_dataset_numeric(job.progress, 0.0)))
    if total > 0 and case_index > 0 and active:
        overall_progress = max(processed / float(total), ((case_index - 1) + worker_fraction) / float(total))
        progress = min(0.99, max(job_fraction, overall_progress))
    else:
        progress = job_fraction
    if phase == "complete":
        progress = 1.0
    elif phase in {"error", "cancelled"}:
        progress = max(progress, 1.0 if not active else progress)

    step_plan = _qwen_caption_dataset_live_step_plan(worker_progress)
    phase_step_indices = {
        "started": 1,
        "case_start": 1,
        "attempt_running": 3,
        "attempt_cooldown": 3,
        "case_complete": 4,
        "case_success_cooldown": 5,
        "finished": 5,
    }
    raw_step_index = worker_progress.get("step_index")
    step_index = int(max(0.0, _qwen_caption_dataset_numeric(raw_step_index, 0.0))) or None
    if step_index is None:
        step_index = phase_step_indices.get(str(heartbeat.get("phase") or "").strip())
    step_total = int(max(0.0, _qwen_caption_dataset_numeric(worker_progress.get("step_total"), len(step_plan))))
    if step_total <= 0:
        step_total = len(step_plan)
    step_id = (
        str(worker_progress.get("step_id") or "").strip()
        or str(heartbeat.get("worker_step_id") or "").strip()
        or str(heartbeat.get("phase") or phase).strip()
    )
    step_label = (
        str(worker_progress.get("step_label") or "").strip()
        or str(heartbeat.get("worker_step_label") or "").strip()
        or (step_plan[step_index - 1]["label"] if step_index and step_index <= len(step_plan) else phase_label)
    )

    image_name = str(heartbeat.get("image_name") or "").strip()
    stem = str(heartbeat.get("stem") or "").strip()
    case_id = str(heartbeat.get("case_id") or "").strip()
    case_name = str(heartbeat.get("case") or "").strip()
    display_case = image_name or stem or case_name
    detail_parts: List[str] = []
    if total > 0:
        image_counter = case_index if case_index > 0 else min(processed + 1, total)
        image_detail = f"Image {image_counter}/{total}"
        if display_case:
            image_detail = f"{image_detail}: {display_case}"
        detail_parts.append(image_detail)
    elif display_case:
        detail_parts.append(display_case)
    attempt = heartbeat.get("attempt")
    total_attempts = heartbeat.get("total_attempts")
    if attempt:
        attempt_text = f"attempt {attempt}"
        if total_attempts:
            attempt_text = f"{attempt_text}/{total_attempts}"
        detail_parts.append(attempt_text)
    worker_detail = str(worker_progress.get("step_detail") or worker_progress.get("message") or "").strip()
    if worker_detail:
        detail_parts.append(worker_detail)

    token_preview = str(worker_progress.get("token_preview_tail") or "").strip()
    live_output = token_preview
    if not token_preview and latest_caption and not active:
        token_preview = str(latest_caption.get("caption") or "").strip()
    generated_tokens = heartbeat.get("worker_generated_tokens", worker_progress.get("generated_tokens"))
    max_new_tokens = heartbeat.get("worker_max_new_tokens", worker_progress.get("max_new_tokens"))
    model_id = (
        str(worker_progress.get("model_id") or "").strip()
        or str(caption_request.get("model_id") or caption_request.get("model") or "").strip()
        or None
    )
    message = str(job.message or "").strip()
    if not message and active:
        message = "Caption job running"
    qa_target_count = _qwen_caption_dataset_numeric(
        (qa_accumulator or {}).get("target_pair_count")
        if isinstance(qa_accumulator, Mapping)
        else None,
        _qwen_caption_dataset_numeric(latest_caption.get("generated_qa_target_pair_count"), 0),
    )
    qa_accepted_count = _qwen_caption_dataset_numeric(
        (qa_accumulator or {}).get("accepted_pair_count")
        if isinstance(qa_accumulator, Mapping)
        else None,
        _qwen_caption_dataset_numeric(
            latest_caption.get("generated_qa_pair_count"),
            len(latest_generated_qa_pairs),
        ),
    )
    qa_rejected_count = _qwen_caption_dataset_numeric(
        (qa_accumulator or {}).get("rejected_pair_count")
        if isinstance(qa_accumulator, Mapping)
        else None,
        _qwen_caption_dataset_numeric(latest_caption.get("generated_qa_rejected_pair_count"), 0),
    )
    snapshot: Dict[str, Any] = {
        "run_id": f"caption_job:{job.job_id}",
        "backend_job_id": job.job_id,
        "active": active,
        "kind": "caption",
        "phase": phase,
        "phase_label": phase_label,
        "progress": max(0.0, min(1.0, progress)),
        "message": message,
        "model_id": model_id,
        "loaded": None,
        "local": None,
        "partial": None,
        "needs_download": None,
        "generated_tokens": generated_tokens,
        "max_new_tokens": max_new_tokens,
        "token_preview": token_preview,
        "live_output": live_output,
        "latest_generated_qa_pairs": latest_generated_qa_pairs[:20],
        "latest_generated_qa_pair_count": int(
            max(
                0.0,
                _qwen_caption_dataset_numeric(
                    qa_accepted_count if isinstance(qa_accumulator, Mapping) else latest_caption.get("generated_qa_pair_count"),
                    len(latest_generated_qa_pairs),
                ),
            )
        ),
        "latest_generated_qa_target_count": int(
            max(
                0.0,
                qa_target_count,
            )
        ),
        "latest_generated_qa_accepted_count": int(
            max(
                0.0,
                qa_accepted_count,
            )
        ),
        "latest_generated_qa_rejected_pair_count": int(
            max(
                0.0,
                qa_rejected_count,
            )
        ),
        "latest_generated_qa_status": str(
            (qa_accumulator or {}).get("status")
            if isinstance(qa_accumulator, Mapping)
            else ""
        ).strip()
        or (
            str(latest_generated_qa_warning.get("status") or "").strip()
            if isinstance(latest_generated_qa_warning, Mapping)
            else ""
        ),
        "latest_generated_qa_attempt_summary": (
            list((qa_accumulator or {}).get("attempt_summary") or [])
            if isinstance(qa_accumulator, Mapping)
            else list(latest_caption.get("generated_qa_attempt_summary") or [])
            if isinstance(latest_caption.get("generated_qa_attempt_summary"), list)
            else []
        )[:8],
        "latest_generated_qa_accumulator": dict(qa_accumulator)
        if isinstance(qa_accumulator, Mapping)
        else None,
        "latest_generated_qa_image_name": str(
            ((qa_accumulator or {}).get("image_name") if isinstance(qa_accumulator, Mapping) else "")
            or latest_caption.get("image_name")
            or ""
        ).strip(),
        "latest_generated_qa_case_id": str(
            ((qa_accumulator or {}).get("case_id") if isinstance(qa_accumulator, Mapping) else "")
            or latest_caption.get("case_id")
            or ""
        ).strip(),
        "latest_generated_qa_warning": latest_generated_qa_warning,
        "step_id": step_id,
        "step_index": step_index,
        "step_total": step_total,
        "step_label": step_label,
        "step_detail": " • ".join(detail_parts),
        "step_plan": step_plan,
        "io_events": _qwen_caption_dataset_live_io_events(worker_progress),
        "log_lines": _qwen_caption_dataset_live_log_lines(job),
        "updated_at": job.updated_at,
        "caption_dataset_progress": {
            "processed": processed,
            "total_cases": total,
            "case_index": case_index,
            "case": case_name,
            "image_name": image_name,
            "stem": stem,
            "case_id": case_id,
            "attempt": attempt,
            "failed": int(max(0.0, _qwen_caption_dataset_numeric(result.get("failed"), 0.0))),
            "saved_text_labels": int(max(0.0, _qwen_caption_dataset_numeric(result.get("saved_text_labels"), 0.0))),
        },
    }
    if phase in {"error", "cancelled"} and job.error:
        snapshot["error"] = job.error
    if phase in {"complete", "error", "cancelled"}:
        snapshot["completed_at"] = job.updated_at
    return snapshot


def _serialize_qwen_caption_dataset_job(job: QwenCaptionDatasetJob) -> Dict[str, Any]:
    live_progress = _qwen_caption_dataset_job_live_progress(job)
    serialized_progress = job.progress
    if str(job.status or "").strip().lower() in {"queued", "running", "cancelling"}:
        serialized_progress = _qwen_caption_dataset_numeric(
            live_progress.get("progress"),
            serialized_progress,
        )
    return {
        "job_id": job.job_id,
        "status": job.status,
        "progress": max(0.0, min(1.0, serialized_progress)),
        "message": job.message,
        "request": job.request,
        "result": job.result or {},
        "output_dir": job.output_dir,
        "error": job.error,
        "created_at": job.created_at,
        "updated_at": job.updated_at,
        "logs": list(job.logs[-100:]),
        "live_progress": live_progress,
    }


def _persist_qwen_caption_dataset_job(job: QwenCaptionDatasetJob) -> None:
    if not job.output_dir:
        return
    try:
        output_dir = Path(job.output_dir)
        output_dir.mkdir(parents=True, exist_ok=True)
        payload = _serialize_qwen_caption_dataset_job(job)
        tmp_path = output_dir / "job.json.tmp"
        tmp_path.write_text(json.dumps(payload, indent=2, sort_keys=True))
        tmp_path.replace(output_dir / "job.json")
        _qwen_caption_dataset_write_discovery_summary(output_dir, payload)
        discovery_dir = _qwen_caption_dataset_job_discovery_dir(job.job_id)
        if discovery_dir.resolve(strict=False) != output_dir.resolve(strict=False):
            discovery_dir.mkdir(parents=True, exist_ok=True)
            mirror_tmp_path = discovery_dir / "job.json.tmp"
            mirror_tmp_path.write_text(json.dumps(payload, indent=2, sort_keys=True))
            mirror_tmp_path.replace(discovery_dir / "job.json")
            _qwen_caption_dataset_write_discovery_summary(
                discovery_dir,
                payload,
            )
    except Exception:
        logger.debug("Failed to persist Qwen caption dataset job", exc_info=True)


def _qwen_caption_dataset_can_write_job_payload_dir(path_value: Any) -> bool:
    if not path_value:
        return False
    try:
        resolved = Path(str(path_value)).expanduser().resolve(strict=False)
    except Exception:
        return False
    try:
        allowed_roots = [
            Path.cwd().resolve(),
            QWEN_CAPTION_DATASET_JOB_ROOT.resolve(),
        ]
    except Exception:
        return False
    return any(_path_is_within_root_impl(resolved, root) for root in allowed_roots)


def _persist_qwen_caption_dataset_job_payload(payload: Mapping[str, Any]) -> None:
    job_id = str(payload.get("job_id") or "").strip()
    if not job_id:
        return
    destinations = [_qwen_caption_dataset_job_discovery_dir(job_id)]
    output_dir = str(payload.get("output_dir") or "").strip()
    if output_dir and _qwen_caption_dataset_can_write_job_payload_dir(output_dir):
        output_path = Path(output_dir).expanduser().resolve(strict=False)
        discovery_path = destinations[0].resolve(strict=False)
        if output_path != discovery_path:
            destinations.insert(0, output_path)
    for destination in destinations:
        try:
            destination.mkdir(parents=True, exist_ok=True)
            tmp_path = destination / "job.json.tmp"
            tmp_path.write_text(json.dumps(dict(payload), indent=2, sort_keys=True))
            tmp_path.replace(destination / "job.json")
            _qwen_caption_dataset_write_discovery_summary(
                destination,
                payload,
            )
        except Exception:
            logger.debug("Failed to persist Qwen caption dataset job payload", exc_info=True)


def _load_qwen_caption_dataset_job_payload(job_id: str) -> Optional[Dict[str, Any]]:
    job_path = _qwen_caption_dataset_job_discovery_dir(job_id) / "job.json"
    if not job_path.exists():
        return None
    try:
        payload = json.loads(job_path.read_text())
    except Exception:
        return None
    if not isinstance(payload, dict):
        return None
    if str(payload.get("status") or "") in {"queued", "running"}:
        payload["status"] = "interrupted"
        payload["message"] = "Interrupted while backend was not tracking the job"
    return payload


def _qwen_caption_dataset_caption_record_from_row(row: Mapping[str, Any]) -> Optional[Dict[str, Any]]:
    artifact_dir = str(row.get("artifact_dir") or "").strip()
    if not artifact_dir:
        return None
    result_path = Path(artifact_dir) / "result.json"
    if not result_path.exists():
        return None
    try:
        result = json.loads(result_path.read_text())
    except Exception:
        return None
    response = result.get("response") if isinstance(result.get("response"), dict) else {}
    caption = str((response or {}).get("caption") or "").strip()
    if not caption:
        return None
    case = result.get("case") if isinstance(result.get("case"), dict) else {}
    image_name = str(case.get("image_name") or Path(str(case.get("image_path") or "")).name).strip()
    split = str(case.get("split") or "").strip() or None
    if not image_name:
        return None
    recovery_events = (response or {}).get("recovery_events")
    generated_qa_pairs = _qwen_caption_dataset_generated_qa_pairs_from_row(row)
    record: Dict[str, Any] = {
        "case_id": str(row.get("case_id") or case.get("case_id") or "").strip(),
        "case": str(row.get("case") or case.get("name") or "").strip(),
        "stem": str(row.get("stem") or case.get("stem") or "").strip(),
        "image_name": image_name,
        "image_path": str(case.get("image_path") or "").strip(),
        "split": split,
        "caption": caption,
        "used_counts": (response or {}).get("used_counts") or {},
        "used_boxes": (response or {}).get("used_boxes"),
        "truncated": bool((response or {}).get("truncated")),
        "recovery_events": recovery_events if isinstance(recovery_events, list) else [],
        "generated_qa_pair_count": len(generated_qa_pairs)
        or int((response or {}).get("generated_qa_pair_count") or 0),
        "generated_qa_target_pair_count": int(
            (response or {}).get("generated_qa_target_pair_count") or 0
        ),
        "generated_qa_rejected_pair_count": int(
            (response or {}).get("generated_qa_rejected_pair_count") or 0
        ),
        "artifact_dir": artifact_dir,
    }
    if generated_qa_pairs:
        record["generated_qa_pairs"] = generated_qa_pairs[:20]
    if isinstance((response or {}).get("generated_qa_attempt_summary"), list):
        record["generated_qa_attempt_summary"] = (response or {}).get(
            "generated_qa_attempt_summary"
        )
    if isinstance((response or {}).get("generated_qa_accumulator"), Mapping):
        record["generated_qa_accumulator"] = (response or {}).get("generated_qa_accumulator")
    if isinstance((response or {}).get("generated_qa_warning"), Mapping):
        record["generated_qa_warning"] = (response or {}).get("generated_qa_warning")
    quality = result.get("caption_quality")
    if isinstance(quality, dict):
        record["caption_quality"] = quality
    return record


def _qwen_caption_dataset_save_caption_from_row(
    *,
    dataset_id: str,
    row: Mapping[str, Any],
    job: QwenCaptionDatasetJob,
    annotation_session_id: Optional[str] = None,
    make_primary: bool = False,
    payload: Optional[QwenCaptionDatasetJobRequest] = None,
) -> Optional[str]:
    if payload is not None and not _qwen_caption_dataset_persists_outputs(payload):
        return None
    record = _qwen_caption_dataset_caption_record_from_row(row)
    if not record:
        return None
    image_name = str(record.get("image_name") or "").strip()
    caption = str(record.get("caption") or "").strip()
    split = str(record.get("split") or "").strip() or None
    if not image_name or not caption:
        return None
    write_policy = str(getattr(payload, "write_policy", "") or "")
    if write_policy in {"qa_only_extend", "qa_only_replace"}:
        return None
    if (
        payload is not None
        and str(payload.completion_mode or "per_image_totals") == "incremental"
        and _qwen_caption_dataset_increment_base_caption_count(payload) <= 0
    ):
        _qwen_caption_dataset_job_log(
            job,
            f"base caption increment is zero {image_name}",
            image_name=image_name,
            write_policy=write_policy,
        )
        return None
    if payload is not None and write_policy == "replace_generated":
        archived = _qwen_caption_dataset_soft_archive_generated_outputs(
            dataset_id,
            image_name,
            job_id=job.job_id,
            split=split,
            archive_captions=True,
            archive_generated_qa=False,
            reason="replace_generated_before_save",
        )
        if archived.get("captions"):
            _qwen_caption_dataset_job_log(
                job,
                f"archived {archived['captions']} generated captions {image_name}",
                image_name=image_name,
                archived_captions=archived.get("captions"),
                write_policy=write_policy,
            )
    if (
        payload is not None
        and str(payload.completion_mode or "per_image_totals") == "per_image_totals"
        and write_policy in {"fill_missing", "qa_only_extend"}
        and str(row.get("final_status") or row.get("status") or "").strip() != "skipped_completed"
    ):
        counts = _qwen_caption_dataset_image_completion_counts(dataset_id, image_name, split=split)
        if int(counts.get("base_caption_count") or 0) >= _qwen_caption_dataset_base_caption_target(payload):
            _qwen_caption_dataset_job_log(
                job,
                f"base caption target already met {image_name}",
                image_name=image_name,
                write_policy=write_policy,
            )
            return None
    metadata = {
        "case_id": record.get("case_id"),
        "used_counts": record.get("used_counts") or {},
        "used_boxes": record.get("used_boxes"),
        "truncated": bool(record.get("truncated")),
        "recovery_events": record.get("recovery_events") or [],
        "caption_quality": record.get("caption_quality") or {},
        "artifact_dir": record.get("artifact_dir"),
    }
    if payload is not None:
        metadata.update(
            {
                "run_kind": str(payload.run_kind or "production"),
                "write_policy": write_policy or None,
                "completion_mode": str(payload.completion_mode or "per_image_totals"),
            }
        )
    payload = {
        "caption": caption,
        "split": split,
        "source": "qwen_caption_job",
        "title": str(record.get("case") or record.get("stem") or "").strip(),
        "make_primary": bool(make_primary),
        "metadata": metadata,
    }
    session_id = str(annotation_session_id or "").strip()
    if session_id:
        payload["session_id"] = session_id
    _add_caption_impl(
        dataset_id,
        image_name,
        payload,
        allow_active_caption_job_id=job.job_id,
    )
    _qwen_caption_dataset_job_log(job, f"saved caption {image_name}", image_name=image_name)
    return image_name


def _qwen_caption_dataset_row_recovery_events(row: Mapping[str, Any]) -> List[Mapping[str, Any]]:
    raw = row.get("recovery_events")
    if not isinstance(raw, list):
        return []
    return [event for event in raw if isinstance(event, Mapping)]


def _qwen_caption_dataset_row_has_loop_recovery(row: Mapping[str, Any]) -> bool:
    for event in _qwen_caption_dataset_row_recovery_events(row):
        action = str(event.get("action") or "").lower()
        message = str(event.get("message") or "").lower()
        detail = str(event.get("detail") or "").lower()
        if "loop" in action or "loop" in message or "loop" in detail:
            return True
    return False


def _qwen_caption_dataset_row_has_deterministic_recovery(row: Mapping[str, Any]) -> bool:
    if bool(row.get("parent_deterministic_recovery")):
        return True
    for event in _qwen_caption_dataset_row_recovery_events(row):
        action = str(event.get("action") or "").lower()
        attempt = str(event.get("attempt") or "").lower()
        call_kind = str(event.get("call_kind") or "").lower()
        if (
            action == "deterministic_recovery_succeeded"
            or attempt in {"deterministic_recovery", "parent_deterministic_recovery"}
            or call_kind == "deterministic"
        ):
            return True
    return False


def _qwen_caption_dataset_row_prompt_budget(row: Mapping[str, Any]) -> Mapping[str, Any]:
    raw = row.get("preview_prompt_budget")
    return raw if isinstance(raw, Mapping) else {}


def _qwen_caption_dataset_row_has_adapted_prompt_budget(row: Mapping[str, Any]) -> bool:
    budget = _qwen_caption_dataset_row_prompt_budget(row)
    try:
        return int(budget.get("adapted_sections") or 0) > 0
    except (TypeError, ValueError, OverflowError):
        return False


def _qwen_caption_dataset_row_max_prompt_tokens(row: Mapping[str, Any]) -> int:
    budget = _qwen_caption_dataset_row_prompt_budget(row)
    try:
        return max(0, int(budget.get("max_prompt_tokens") or 0))
    except (TypeError, ValueError, OverflowError):
        return 0


def _qwen_caption_dataset_row_io_event_count(row: Mapping[str, Any], event_name: str) -> int:
    raw_io = row.get("qwen_caption_io")
    if not isinstance(raw_io, Mapping):
        return 0
    event_counts = raw_io.get("event_counts")
    if isinstance(event_counts, Mapping):
        try:
            return max(0, int(event_counts.get(event_name) or 0))
        except (TypeError, ValueError, OverflowError):
            return 0
    direct_key = f"{event_name}_events"
    try:
        return max(0, int(raw_io.get(direct_key) or 0))
    except (TypeError, ValueError, OverflowError):
        return 0


def _qwen_caption_dataset_row_openai_usage(row: Mapping[str, Any]) -> Dict[str, int]:
    raw_io = row.get("qwen_caption_io")
    if not isinstance(raw_io, Mapping):
        return {}
    usage = raw_io.get("usage")
    if not isinstance(usage, Mapping):
        return {}
    return _openai_caption_usage_counts(usage)


def _qwen_caption_dataset_add_openai_usage(summary: Dict[str, Any], row: Mapping[str, Any]) -> None:
    usage = _qwen_caption_dataset_row_openai_usage(row)
    if not usage:
        return
    existing = (
        summary.get("openai_usage")
        if isinstance(summary.get("openai_usage"), Mapping)
        else {
            "input_tokens": 0,
            "output_tokens": 0,
            "total_tokens": 0,
            "cached_input_tokens": 0,
            "reasoning_tokens": 0,
        }
    )
    combined = _openai_caption_usage_add(existing, usage)
    summary["openai_usage"] = combined
    raw_io = row.get("qwen_caption_io") if isinstance(row.get("qwen_caption_io"), Mapping) else {}
    summary["openai_usage_call_rows"] = int(summary.get("openai_usage_call_rows") or 0) + int(
        raw_io.get("usage_rows") or 0
    )
    summary["openai_cost_summary"] = _openai_caption_cost_from_usage(
        usage=combined,
        model=summary.get("openai_model") or "gpt-5.5",
        service_tier=summary.get("openai_service_tier") or "standard",
        source="standard_runner_response_usage",
        row_count=int(summary.get("processed") or 0),
    )


def _qwen_caption_dataset_row_generated_qa_warning(row: Mapping[str, Any]) -> bool:
    warning = row.get("generated_qa_warning") or row.get("instruction_qa_warning")
    if isinstance(warning, Mapping):
        return True
    status = str(row.get("instruction_qa_status") or "").strip().lower()
    if status in {"error", "underfilled", "empty", "instruction_qa_failed"}:
        return True
    target = int(max(0.0, _qwen_caption_dataset_numeric(row.get("generated_qa_target_pair_count"), 0.0)))
    accepted = int(max(0.0, _qwen_caption_dataset_numeric(row.get("generated_qa_pair_count"), 0.0)))
    return target > 0 and accepted < target


def _qwen_caption_dataset_row_generated_qa_error(row: Mapping[str, Any]) -> bool:
    status = str(row.get("instruction_qa_status") or "").strip().lower()
    if status in {"error", "instruction_qa_failed"}:
        return True
    warning = row.get("generated_qa_warning") or row.get("instruction_qa_warning")
    if isinstance(warning, Mapping):
        return str(warning.get("type") or "").strip() == "InstructionQaGenerationWarning"
    return False


def _qwen_caption_dataset_row_generated_qa_underfilled(row: Mapping[str, Any]) -> bool:
    return str(row.get("instruction_qa_status") or "").strip().lower() == "underfilled"


def _qwen_caption_dataset_row_generated_qa_zero_pair(row: Mapping[str, Any]) -> bool:
    target = int(max(0.0, _qwen_caption_dataset_numeric(row.get("generated_qa_target_pair_count"), 0.0)))
    accepted = int(max(0.0, _qwen_caption_dataset_numeric(row.get("generated_qa_pair_count"), 0.0)))
    return target > 0 and accepted <= 0


def _qwen_caption_dataset_degraded_rates(
    *,
    processed: int,
    attempts_seen: int,
    failed: int,
    quality_failed: int,
    failed_attempts: int,
    recovery_event_cases: int,
    recovery_events: int,
    loop_recovery_cases: int,
    deterministic_recovery_cases: int,
    prompt_budget_adapted_cases: int,
    max_prompt_tokens: int,
    stream_loop_detected_cases: int = 0,
    stream_loop_detected_events: int = 0,
    loop_trim_cases: int = 0,
    loop_trim_events: int = 0,
    signal_exit_attempts: int = 0,
    generated_qa_warning_cases: int = 0,
    generated_qa_error_cases: int = 0,
    generated_qa_underfilled_cases: int = 0,
    generated_qa_zero_pair_cases: int = 0,
) -> Dict[str, Any]:
    processed = max(0, int(processed or 0))
    attempts_seen = max(0, int(attempts_seen or 0))

    def _rate(numerator: int, denominator: int) -> float:
        return 0.0 if denominator <= 0 else float(max(0, int(numerator or 0))) / float(denominator)

    return {
        "processed_cases": processed,
        "attempt_rows": attempts_seen,
        "failed_cases": max(0, int(failed or 0)),
        "quality_failed_cases": max(0, int(quality_failed or 0)),
        "failed_attempt_rows": max(0, int(failed_attempts or 0)),
        "signal_exit_attempt_rows": max(0, int(signal_exit_attempts or 0)),
        "recovery_event_cases": max(0, int(recovery_event_cases or 0)),
        "recovery_events": max(0, int(recovery_events or 0)),
        "loop_recovery_cases": max(0, int(loop_recovery_cases or 0)),
        "deterministic_recovery_cases": max(0, int(deterministic_recovery_cases or 0)),
        "prompt_budget_adapted_cases": max(0, int(prompt_budget_adapted_cases or 0)),
        "max_prompt_tokens": max(0, int(max_prompt_tokens or 0)),
        "stream_loop_detected_cases": max(0, int(stream_loop_detected_cases or 0)),
        "stream_loop_detected_events": max(0, int(stream_loop_detected_events or 0)),
        "loop_trim_cases": max(0, int(loop_trim_cases or 0)),
        "loop_trim_events": max(0, int(loop_trim_events or 0)),
        "generated_qa_warning_cases": max(0, int(generated_qa_warning_cases or 0)),
        "generated_qa_error_cases": max(0, int(generated_qa_error_cases or 0)),
        "generated_qa_underfilled_cases": max(0, int(generated_qa_underfilled_cases or 0)),
        "generated_qa_zero_pair_cases": max(0, int(generated_qa_zero_pair_cases or 0)),
        "failed_case_rate": _rate(failed, processed),
        "quality_failure_rate": _rate(quality_failed, processed),
        "failed_attempt_row_rate": _rate(failed_attempts, attempts_seen),
        "signal_exit_attempt_row_rate": _rate(signal_exit_attempts, attempts_seen),
        "recovery_event_case_rate": _rate(recovery_event_cases, processed),
        "loop_recovery_case_rate": _rate(loop_recovery_cases, processed),
        "deterministic_recovery_case_rate": _rate(deterministic_recovery_cases, processed),
        "stream_loop_detected_case_rate": _rate(stream_loop_detected_cases, processed),
        "loop_trim_case_rate": _rate(loop_trim_cases, processed),
        "generated_qa_warning_case_rate": _rate(generated_qa_warning_cases, processed),
        "generated_qa_error_case_rate": _rate(generated_qa_error_cases, processed),
        "generated_qa_underfilled_case_rate": _rate(generated_qa_underfilled_cases, processed),
        "generated_qa_zero_pair_case_rate": _rate(generated_qa_zero_pair_cases, processed),
    }


def _qwen_caption_dataset_degraded_rates_from_rows(
    rows: Sequence[Mapping[str, Any]],
) -> Dict[str, Any]:
    latest: Dict[str, Mapping[str, Any]] = {}
    failed_attempts = 0
    signal_exit_attempts = 0
    for index, row in enumerate(rows):
        final_status = str(row.get("final_status") or row.get("status") or "unknown")
        status = str(row.get("status") or "").strip().lower()
        if final_status == "failed_attempt" or status in {"timeout", "exception", "missing_result"}:
            failed_attempts += 1
        if row.get("return_signal") is not None or str(row.get("attempt_failure_kind") or "") == "signal_exit":
            signal_exit_attempts += 1
        key = str(row.get("case_id") or row.get("case") or row.get("stem") or f"row_{index}").strip()
        latest[key] = row
    ok_statuses = {"ok", "skipped_completed", "skipped_existing_caption", "preview_only"}
    latest_rows = list(latest.values())
    failed = sum(
        1
        for row in latest_rows
        if str(row.get("final_status") or row.get("status") or "unknown") not in ok_statuses
    )
    quality_failed = sum(1 for row in latest_rows if row.get("quality_failures"))
    recovery_event_cases = sum(1 for row in latest_rows if _qwen_caption_dataset_row_recovery_events(row))
    recovery_events = sum(len(_qwen_caption_dataset_row_recovery_events(row)) for row in latest_rows)
    loop_recovery_cases = sum(1 for row in latest_rows if _qwen_caption_dataset_row_has_loop_recovery(row))
    deterministic_recovery_cases = sum(
        1 for row in latest_rows if _qwen_caption_dataset_row_has_deterministic_recovery(row)
    )
    prompt_budget_adapted_cases = sum(
        1 for row in latest_rows if _qwen_caption_dataset_row_has_adapted_prompt_budget(row)
    )
    max_prompt_tokens = max(
        (_qwen_caption_dataset_row_max_prompt_tokens(row) for row in latest_rows),
        default=0,
    )
    stream_loop_detected_cases = sum(
        1
        for row in latest_rows
        if _qwen_caption_dataset_row_io_event_count(row, "stream_loop_detected") > 0
    )
    stream_loop_detected_events = sum(
        _qwen_caption_dataset_row_io_event_count(row, "stream_loop_detected")
        for row in latest_rows
    )
    loop_trim_cases = sum(
        1 for row in latest_rows if _qwen_caption_dataset_row_io_event_count(row, "loop_trim") > 0
    )
    loop_trim_events = sum(
        _qwen_caption_dataset_row_io_event_count(row, "loop_trim")
        for row in latest_rows
    )
    generated_qa_warning_cases = sum(
        1 for row in latest_rows if _qwen_caption_dataset_row_generated_qa_warning(row)
    )
    generated_qa_error_cases = sum(
        1 for row in latest_rows if _qwen_caption_dataset_row_generated_qa_error(row)
    )
    generated_qa_underfilled_cases = sum(
        1 for row in latest_rows if _qwen_caption_dataset_row_generated_qa_underfilled(row)
    )
    generated_qa_zero_pair_cases = sum(
        1 for row in latest_rows if _qwen_caption_dataset_row_generated_qa_zero_pair(row)
    )
    return _qwen_caption_dataset_degraded_rates(
        processed=len(latest_rows),
        attempts_seen=len(rows),
        failed=failed,
        quality_failed=quality_failed,
        failed_attempts=failed_attempts,
        signal_exit_attempts=signal_exit_attempts,
        recovery_event_cases=recovery_event_cases,
        recovery_events=recovery_events,
        loop_recovery_cases=loop_recovery_cases,
        deterministic_recovery_cases=deterministic_recovery_cases,
        prompt_budget_adapted_cases=prompt_budget_adapted_cases,
        max_prompt_tokens=max_prompt_tokens,
        stream_loop_detected_cases=stream_loop_detected_cases,
        stream_loop_detected_events=stream_loop_detected_events,
        loop_trim_cases=loop_trim_cases,
        loop_trim_events=loop_trim_events,
        generated_qa_warning_cases=generated_qa_warning_cases,
        generated_qa_error_cases=generated_qa_error_cases,
        generated_qa_underfilled_cases=generated_qa_underfilled_cases,
        generated_qa_zero_pair_cases=generated_qa_zero_pair_cases,
    )


def _qwen_caption_dataset_rate_threshold(value: Any, *, default: float) -> float:
    try:
        threshold = float(value) if value is not None else float(default)
    except (TypeError, ValueError, OverflowError):
        threshold = float(default)
    if not math.isfinite(threshold):
        threshold = float(default)
    return -1.0 if threshold < 0 else max(0.0, min(threshold, 1.0))


def _qwen_caption_dataset_set_and_forget(request_data: Mapping[str, Any]) -> bool:
    value = request_data.get("set_and_forget")
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes", "on"}


def _qwen_caption_dataset_degraded_thresholds_from_request(
    request_data: Mapping[str, Any],
) -> Dict[str, float]:
    loop_default = (
        QWEN_CAPTION_SET_AND_FORGET_MAX_LOOP_RECOVERY_RATE
        if _qwen_caption_dataset_set_and_forget(request_data)
        else 0.0
    )
    deterministic_default = (
        QWEN_CAPTION_SET_AND_FORGET_MAX_DETERMINISTIC_RECOVERY_RATE
        if _qwen_caption_dataset_set_and_forget(request_data)
        else 0.0
    )
    signal_exit_default = (
        QWEN_CAPTION_SET_AND_FORGET_MAX_SIGNAL_EXIT_ATTEMPT_RATE
        if _qwen_caption_dataset_set_and_forget(request_data)
        else 0.0
    )
    return {
        "max_failed_case_rate": _qwen_caption_dataset_rate_threshold(
            request_data.get("max_failed_case_rate"),
            default=0.0,
        ),
        "max_quality_failure_rate": _qwen_caption_dataset_rate_threshold(
            request_data.get("max_quality_failure_rate"),
            default=0.0,
        ),
        "max_recovery_event_case_rate": _qwen_caption_dataset_rate_threshold(
            request_data.get("max_recovery_event_case_rate"),
            default=0.25,
        ),
        "max_loop_recovery_case_rate": _qwen_caption_dataset_rate_threshold(
            request_data.get("max_loop_recovery_case_rate"),
            default=loop_default,
        ),
        "max_deterministic_recovery_case_rate": _qwen_caption_dataset_rate_threshold(
            request_data.get("max_deterministic_recovery_case_rate"),
            default=deterministic_default,
        ),
        "max_failed_attempt_row_rate": _qwen_caption_dataset_rate_threshold(
            request_data.get("max_failed_attempt_row_rate"),
            default=0.25,
        ),
        "max_signal_exit_attempt_row_rate": _qwen_caption_dataset_rate_threshold(
            request_data.get("max_signal_exit_attempt_row_rate"),
            default=signal_exit_default,
        ),
    }


def _qwen_caption_dataset_min_rate_cases(request_data: Mapping[str, Any]) -> int:
    try:
        min_rate_cases = int(request_data.get("min_rate_cases") or 20)
    except (TypeError, ValueError, OverflowError):
        min_rate_cases = 20
    return max(1, min(min_rate_cases, 1_000_000))


def _qwen_caption_dataset_min_loop_recovery_rate_cases(
    *,
    threshold: float,
    min_rate_cases: int,
) -> int:
    base = max(1, int(min_rate_cases or 0))
    if threshold <= 0 or threshold >= 0.1:
        return base
    min_events = max(1, int(QWEN_CAPTION_MIN_LOOP_RECOVERY_RATE_EVENTS or 0))
    return max(base, int(math.ceil(min_events / threshold)))


def _qwen_caption_dataset_min_deterministic_recovery_rate_cases(
    *,
    threshold: float,
    min_rate_cases: int,
) -> int:
    base = max(1, int(min_rate_cases or 0))
    if threshold <= 0 or threshold >= 0.1:
        return base
    min_events = max(1, int(QWEN_CAPTION_MIN_DETERMINISTIC_RECOVERY_RATE_EVENTS or 0))
    return max(base, int(math.ceil(min_events / threshold)))


def _qwen_caption_dataset_degraded_policy(
    rates: Mapping[str, Any],
    request_data: Mapping[str, Any],
    *,
    terminal: bool,
) -> Dict[str, Any]:
    thresholds = _qwen_caption_dataset_degraded_thresholds_from_request(request_data)
    min_rate_cases = _qwen_caption_dataset_min_rate_cases(request_data)
    min_loop_recovery_rate_cases = _qwen_caption_dataset_min_loop_recovery_rate_cases(
        threshold=float(thresholds["max_loop_recovery_case_rate"]),
        min_rate_cases=min_rate_cases,
    )
    min_deterministic_recovery_rate_cases = (
        _qwen_caption_dataset_min_deterministic_recovery_rate_cases(
            threshold=float(thresholds["max_deterministic_recovery_case_rate"]),
            min_rate_cases=min_rate_cases,
        )
    )
    try:
        processed = int(rates.get("processed_cases") or 0)
    except (TypeError, ValueError, OverflowError):
        processed = 0
    active = bool(terminal) or processed >= min_rate_cases
    violations: List[Dict[str, Any]] = []
    for threshold_key, rate_key in (
        ("max_failed_case_rate", "failed_case_rate"),
        ("max_quality_failure_rate", "quality_failure_rate"),
        ("max_recovery_event_case_rate", "recovery_event_case_rate"),
        ("max_loop_recovery_case_rate", "loop_recovery_case_rate"),
        ("max_deterministic_recovery_case_rate", "deterministic_recovery_case_rate"),
        ("max_failed_attempt_row_rate", "failed_attempt_row_rate"),
        ("max_signal_exit_attempt_row_rate", "signal_exit_attempt_row_rate"),
    ):
        threshold = float(thresholds[threshold_key])
        if threshold < 0:
            continue
        try:
            actual = float(rates.get(rate_key) or 0.0)
        except (TypeError, ValueError, OverflowError):
            actual = 0.0
        if actual > threshold:
            violation = {
                "rate": rate_key,
                "actual": actual,
                "threshold": threshold,
            }
            if (
                rate_key in {"loop_recovery_case_rate", "deterministic_recovery_case_rate"}
                and not terminal
                and threshold > 0
                and processed
                < (
                    min_loop_recovery_rate_cases
                    if rate_key == "loop_recovery_case_rate"
                    else min_deterministic_recovery_rate_cases
                )
            ):
                floor = (
                    min_loop_recovery_rate_cases
                    if rate_key == "loop_recovery_case_rate"
                    else min_deterministic_recovery_rate_cases
                )
                violation["active"] = False
                violation["deferred_by_sample_floor"] = True
                violation["detail"] = (
                    f"{rate_key} is above threshold, but the live sample is below "
                    f"the rate activation floor of {floor} cases"
                )
            else:
                violation["active"] = active
            violations.append(violation)
    active_violations = [violation for violation in violations if violation.get("active")]
    return {
        "active": active,
        "min_rate_cases": min_rate_cases,
        "min_loop_recovery_rate_cases": min_loop_recovery_rate_cases,
        "min_deterministic_recovery_rate_cases": min_deterministic_recovery_rate_cases,
        "thresholds": thresholds,
        "violations": violations,
        "active_violations": active_violations,
    }


def _qwen_caption_dataset_degraded_policy_from_payload(
    payload: Mapping[str, Any],
    *,
    terminal: bool = True,
) -> Dict[str, Any]:
    request_data = payload.get("request") if isinstance(payload.get("request"), Mapping) else {}
    result_data = payload.get("result") if isinstance(payload.get("result"), Mapping) else {}
    rates = result_data.get("degraded_rates") if isinstance(result_data.get("degraded_rates"), Mapping) else {}
    return _qwen_caption_dataset_degraded_policy(rates, request_data, terminal=terminal)


def _qwen_caption_dataset_degraded_policy_reprocesses_recovery(policy: Mapping[str, Any]) -> bool:
    for violation in policy.get("active_violations") or policy.get("violations") or []:
        if not isinstance(violation, Mapping):
            continue
        if str(violation.get("rate") or "") in {
            "recovery_event_case_rate",
            "loop_recovery_case_rate",
            "deterministic_recovery_case_rate",
        }:
            return True
    return False


def _qwen_caption_dataset_strict_audit(
    output_dir: Path,
    request_data: Mapping[str, Any],
    *,
    max_heartbeat_age_seconds: float,
) -> Dict[str, Any]:
    try:
        from tools import audit_qwen_caption_soak as caption_audit

        thresholds = _qwen_caption_dataset_degraded_thresholds_from_request(request_data)
        return caption_audit.audit_soak(
            output_dir,
            max_heartbeat_age_seconds=max_heartbeat_age_seconds,
            allow_running_incomplete=False,
            max_failed_case_rate=thresholds["max_failed_case_rate"],
            max_quality_failure_rate=thresholds["max_quality_failure_rate"],
            max_recovery_event_case_rate=thresholds["max_recovery_event_case_rate"],
            max_loop_recovery_case_rate=thresholds["max_loop_recovery_case_rate"],
            max_deterministic_recovery_case_rate=thresholds["max_deterministic_recovery_case_rate"],
            max_failed_attempt_row_rate=thresholds["max_failed_attempt_row_rate"],
            max_signal_exit_attempt_row_rate=thresholds["max_signal_exit_attempt_row_rate"],
            min_rate_cases=_qwen_caption_dataset_min_rate_cases(request_data),
            set_and_forget=_qwen_caption_dataset_set_and_forget(request_data),
            require_saved_text_labels=_qwen_caption_dataset_request_bool(
                request_data.get("save_text_labels"),
                default=False,
            ),
        )
    except Exception as exc:  # noqa: BLE001
        return {
            "status": "error",
            "output_dir": str(output_dir),
            "checks": [
                {
                    "name": "backend_strict_audit",
                    "status": "error",
                    "detail": str(exc),
                    "error_type": type(exc).__name__,
                }
            ],
        }


