def _qwen_caption_dataset_requested_runner_settings(
    *,
    request_path: Path,
    caption_runner_model_fields: Mapping[str, Any],
    runner_profile: Mapping[str, Any] | None = None,
    payload: Optional[QwenCaptionDatasetJobRequest] = None,
) -> Dict[str, Any]:
    from tools import run_qwen_caption_flow_benchmark as caption_runner

    args_data = dict(caption_runner.RUN_SETTINGS_ARG_DEFAULTS)
    request_template = caption_runner.load_request_template(request_path)
    strategy = (
        str(request_template.get("caption_windowed_full_image_strategy") or args_data["windowed_full_image_strategy"])
        .strip()
        .lower()
        .replace("-", "_")
    )
    if strategy in {"text", "text_only", "window_text", "windowed_text", "observations", "skip_visual"}:
        strategy = "text_only"
    elif strategy not in {"visual", "text_only"}:
        strategy = "visual"
    args_data.update(
        {
            "request_json": request_path,
            "windowed_full_image_strategy": strategy,
            "model_id": str(caption_runner_model_fields.get("model_id") or args_data["model_id"]),
            "refinement_model_id": str(
                caption_runner_model_fields.get("refinement_model_id")
                or args_data["refinement_model_id"]
            ),
            "fallback_model_id": str(
                caption_runner_model_fields.get("fallback_model_id")
                or args_data["fallback_model_id"]
            ),
            "loop_recovery": str(
                caption_runner_model_fields.get("loop_recovery")
                or args_data["loop_recovery"]
            ),
        }
    )
    if payload is not None:
        args_data.update(
            {
                "instruction_dataset": bool(payload.instruction_dataset),
                "caption_provider": str(payload.caption_provider or "local_qwen"),
                "openai_model": str(payload.openai_model or "gpt-5.5"),
                "openai_image_detail": str(payload.openai_image_detail or "original"),
                "openai_reasoning_effort": _openai_caption_normalize_reasoning_effort(payload.openai_reasoning_effort),
                "openai_api_key_file": str(payload.openai_api_key_path or "openAI_API_KEY_DoNotCommit"),
                "openai_service_tier": str(payload.openai_service_tier or "batch"),
                "openai_timeout": float(payload.openai_timeout_seconds or 120.0),
                "subcaptions_per_image": _qwen_caption_dataset_effective_generated_qa_request_count(payload),
                "include_caption0_in_training": _qwen_caption_dataset_effective_include_caption0_in_training(payload),
                "include_generated_qa_in_training": bool(payload.include_generated_qa_in_training),
                "include_deterministic_metadata_qa": bool(payload.include_deterministic_metadata_qa),
                "instruction_qa_imposed_questions": list(payload.instruction_qa_imposed_questions or []),
                "instruction_qa_max_topup_attempts": int(payload.instruction_qa_max_topup_attempts or 0),
                "instruction_qa_restrict_speculative_language": bool(
                    payload.instruction_qa_restrict_speculative_language
                ),
                "include_source_annotations_in_generator_context": bool(
                    payload.include_source_annotations_in_generator_context
                ),
                "strict_grounding": bool(payload.strict_grounding),
                "qa_mix": str(payload.qa_mix or "balanced"),
                "answer_format": str(payload.answer_format or "natural"),
            }
        )
    if isinstance(runner_profile, Mapping):
        for key in (
            "mlx_max_image_side",
            "retry_image_side_scale",
            "min_retry_image_side",
            "cooldown_after_success",
        ):
            if key in runner_profile:
                args_data[key] = runner_profile[key]
    return caption_runner.run_settings_payload(SimpleNamespace(**args_data))


def _qwen_caption_dataset_runner_profile(payload: QwenCaptionDatasetJobRequest) -> Dict[str, Any]:
    request = payload.caption_request if isinstance(payload.caption_request, Mapping) else {}

    def _int_setting(*names: str, default: int) -> int:
        for name in names:
            raw = request.get(name)
            if raw is None or str(raw).strip() == "":
                continue
            try:
                parsed = int(float(raw))
            except (TypeError, ValueError, OverflowError):
                continue
            if parsed > 0:
                return max(1, min(parsed, 4096))
        return max(1, min(int(default), 4096))

    def _float_setting(*names: str, default: float) -> float:
        for name in names:
            raw = request.get(name)
            if raw is None or str(raw).strip() == "":
                continue
            try:
                parsed = float(raw)
            except (TypeError, ValueError, OverflowError):
                continue
            if math.isfinite(parsed):
                return max(0.0, min(parsed, 1.0))
        return max(0.0, min(float(default), 1.0))

    def _duration_setting(*names: str, default: float) -> float:
        for name in names:
            raw = request.get(name)
            if raw is None or str(raw).strip() == "":
                continue
            try:
                parsed = float(raw)
            except (TypeError, ValueError, OverflowError):
                continue
            if math.isfinite(parsed):
                return max(0.0, min(parsed, 300.0))
        return max(0.0, min(float(default), 300.0))

    default_max_side = (
        QWEN_CAPTION_SET_AND_FORGET_MLX_MAX_IMAGE_SIDE
        if bool(payload.set_and_forget)
        else QWEN_CAPTION_MLX_MAX_IMAGE_SIDE
    )
    default_min_retry_side = (
        QWEN_CAPTION_SET_AND_FORGET_MIN_RETRY_IMAGE_SIDE
        if bool(payload.set_and_forget)
        else QWEN_CAPTION_MIN_RETRY_IMAGE_SIDE
    )
    default_success_cooldown = (
        QWEN_CAPTION_SET_AND_FORGET_COOLDOWN_AFTER_SUCCESS_SECONDS
        if bool(payload.set_and_forget)
        else 0.0
    )
    if payload.cooldown_after_success_seconds is not None:
        try:
            success_cooldown = float(payload.cooldown_after_success_seconds)
        except (TypeError, ValueError, OverflowError):
            success_cooldown = default_success_cooldown
        if not math.isfinite(success_cooldown):
            success_cooldown = default_success_cooldown
        success_cooldown = max(0.0, min(success_cooldown, 300.0))
    else:
        success_cooldown = _duration_setting(
            "runner_cooldown_after_success_seconds",
            "cooldown_after_success_seconds",
            "cooldown_after_success",
            default=default_success_cooldown,
        )
    return {
        "mlx_max_image_side": _int_setting(
            "runner_mlx_max_image_side",
            "mlx_max_image_side",
            default=default_max_side,
        ),
        "retry_image_side_scale": _float_setting(
            "runner_retry_image_side_scale",
            "retry_image_side_scale",
            default=QWEN_CAPTION_RETRY_IMAGE_SIDE_SCALE,
        ),
        "min_retry_image_side": _int_setting(
            "runner_min_retry_image_side",
            "min_retry_image_side",
            default=default_min_retry_side,
        ),
        "cooldown_after_success": success_cooldown,
    }


def _qwen_caption_dataset_required_pilot_certification(
    payload: QwenCaptionDatasetJobRequest,
    *,
    output_dir: Path,
    request_data: Mapping[str, Any],
    max_heartbeat_age_seconds: float,
    expected_run_settings_fingerprint: str | None = None,
) -> Optional[Dict[str, Any]]:
    if not bool(payload.require_pilot_certification):
        return None
    report_path = output_dir / "required_pilot_certification.json"
    try:
        if not payload.pilot_output_dir:
            report: Dict[str, Any] = {
                "status": "error",
                "checks": [
                    {
                        "name": "pilot_output_dir",
                        "status": "error",
                        "detail": "pilot_output_dir is required when require_pilot_certification is true",
                    }
                ],
            }
        else:
            from tools import certify_qwen_caption_soak as caption_certify

            pilot_output_dir = _qwen_caption_dataset_job_dir(
                "pilot_certification",
                payload.pilot_output_dir,
            )
            if _paths_match_resolved(pilot_output_dir, output_dir):
                report = {
                    "status": "error",
                    "checks": [
                        {
                            "name": "pilot_output_dir_isolated",
                            "status": "error",
                            "detail": (
                                "pilot_output_dir must be separate from the caption job output_dir "
                                "for set-and-forget pilot certification"
                            ),
                            "pilot_output_dir": str(pilot_output_dir),
                            "target_output_dir": str(output_dir),
                        }
                    ],
                }
            else:
                thresholds = _qwen_caption_dataset_degraded_thresholds_from_request(request_data)
                report = caption_certify.certify_soak(
                    pilot_output_dir,
                    target_cases=int(payload.pilot_target_cases or 10000),
                    max_duration_hours=float(payload.pilot_max_duration_hours or 336.0),
                    max_p95_duration_hours=(
                        float(payload.pilot_max_p95_duration_hours)
                        if payload.pilot_max_p95_duration_hours is not None
                        else None
                    ),
                    min_pilot_cases=int(payload.pilot_min_cases or QWEN_CAPTION_DEFAULT_PILOT_MIN_CASES),
                    duration_safety_factor=float(payload.pilot_duration_safety_factor or 1.25),
                    max_heartbeat_age_seconds=max_heartbeat_age_seconds,
                    max_failed_case_rate=thresholds["max_failed_case_rate"],
                    max_quality_failure_rate=thresholds["max_quality_failure_rate"],
                    max_recovery_event_case_rate=thresholds["max_recovery_event_case_rate"],
                    max_loop_recovery_case_rate=thresholds["max_loop_recovery_case_rate"],
                    max_deterministic_recovery_case_rate=thresholds["max_deterministic_recovery_case_rate"],
                    max_failed_attempt_row_rate=thresholds["max_failed_attempt_row_rate"],
                    max_signal_exit_attempt_row_rate=thresholds["max_signal_exit_attempt_row_rate"],
                    min_rate_cases=_qwen_caption_dataset_min_rate_cases(request_data),
                    set_and_forget=_qwen_caption_dataset_set_and_forget(request_data),
                    expected_run_settings_fingerprint=expected_run_settings_fingerprint,
                    require_prompt_budget_data=bool(payload.pilot_require_prompt_budget_data),
                    max_prompt_tokens=int(payload.pilot_max_prompt_tokens or 0),
                    max_prompt_budget_adapted_case_rate=float(
                        payload.pilot_max_prompt_budget_adapted_case_rate
                        if payload.pilot_max_prompt_budget_adapted_case_rate is not None
                        else 1.0
                    ),
                    deterministic_recovery_confidence=float(
                        payload.pilot_deterministic_recovery_confidence
                        if payload.pilot_deterministic_recovery_confidence is not None
                        else QWEN_CAPTION_DEFAULT_PILOT_DETERMINISTIC_RECOVERY_CONFIDENCE
                    ),
                )
    except HTTPException as exc:
        report = {
            "status": "error",
            "checks": [
                {
                    "name": "pilot_output_dir",
                    "status": "error",
                    "detail": str(exc.detail or exc),
                }
            ],
        }
    except Exception as exc:  # noqa: BLE001
        report = {
            "status": "error",
            "checks": [
                {
                    "name": "pilot_certification",
                    "status": "error",
                    "detail": str(exc),
                    "error_type": type(exc).__name__,
                }
            ],
        }
    report = _qwen_caption_dataset_enforce_pilot_generated_evidence(
        report,
        min_pilot_cases=int(payload.pilot_min_cases or QWEN_CAPTION_DEFAULT_PILOT_MIN_CASES),
        set_and_forget=_qwen_caption_dataset_set_and_forget(request_data),
    )
    report = _qwen_caption_dataset_enforce_pilot_qwen_caption_io_source(
        report,
        require_prompt_budget_data=bool(payload.pilot_require_prompt_budget_data),
        set_and_forget=_qwen_caption_dataset_set_and_forget(request_data),
    )
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


def _qwen_caption_dataset_enforce_pilot_generated_evidence(
    report: Mapping[str, Any],
    *,
    min_pilot_cases: int,
    set_and_forget: bool,
) -> Dict[str, Any]:
    checked_report = dict(report or {})
    if not bool(set_and_forget) or str(checked_report.get("status") or "").lower() != "ok":
        return checked_report
    evidence = checked_report.get("generated_case_evidence")
    evidence = evidence if isinstance(evidence, Mapping) else {}
    generated_cases = _qwen_caption_dataset_request_int(
        checked_report.get("generated_pilot_cases") or evidence.get("generated_cases"),
        default=0,
    )
    required_cases = max(1, int(min_pilot_cases or QWEN_CAPTION_DEFAULT_PILOT_MIN_CASES))
    if generated_cases >= required_cases:
        return checked_report
    checks = list(checked_report.get("checks") or [])
    checks.append(
        {
            "name": "backend_generated_pilot_evidence_gate",
            "status": "error",
            "detail": (
                "set-and-forget pilot certification is missing enough generated "
                "model-success evidence"
            ),
            "generated_pilot_cases": generated_cases,
            "min_pilot_cases": required_cases,
            "has_generated_case_evidence": bool(evidence),
        }
    )
    checked_report["checks"] = checks
    checked_report["status"] = "error"
    return checked_report


def _qwen_caption_dataset_enforce_pilot_qwen_caption_io_source(
    report: Mapping[str, Any],
    *,
    require_prompt_budget_data: bool,
    set_and_forget: bool,
) -> Dict[str, Any]:
    checked_report = dict(report or {})
    if (
        not bool(set_and_forget)
        or not bool(require_prompt_budget_data)
        or str(checked_report.get("status") or "").lower() != "ok"
    ):
        return checked_report
    source_report = checked_report.get("qwen_caption_io_sources")
    source_report = source_report if isinstance(source_report, Mapping) else {}
    source_counts_raw = source_report.get("source_counts")
    source_counts = source_counts_raw if isinstance(source_counts_raw, Mapping) else {}
    normalized_source_counts = {
        str(source): _qwen_caption_dataset_request_int(count, default=0)
        for source, count in source_counts.items()
        if str(source)
    }
    accepted_sources = {"qwen_caption_io_per_run"}
    accepted_observed_sources = [
        source
        for source, count in sorted(normalized_source_counts.items())
        if source in accepted_sources and count > 0
    ]
    unsupported_sources = [
        source
        for source, count in sorted(normalized_source_counts.items())
        if source not in accepted_sources and count > 0
    ]
    required_rows = _qwen_caption_dataset_request_int(source_report.get("required_rows"), default=0)
    valid_rows = _qwen_caption_dataset_request_int(
        source_report.get("valid_runtime_prompt_budget_rows"),
        default=0,
    )
    invalid_rows = _qwen_caption_dataset_request_int(
        source_report.get("invalid_runtime_rows_count"),
        default=0,
    )
    missing_rows = _qwen_caption_dataset_request_int(
        source_report.get("missing_runtime_rows_count"),
        default=0,
    )
    if (
        bool(source_report)
        and required_rows > 0
        and valid_rows >= required_rows
        and invalid_rows == 0
        and missing_rows == 0
        and accepted_observed_sources
        and not unsupported_sources
    ):
        return checked_report
    checks = list(checked_report.get("checks") or [])
    checks.append(
        {
            "name": "backend_qwen_caption_io_source_gate",
            "status": "error",
            "detail": (
                "set-and-forget pilot certification is missing complete run-bound "
                "qwen_caption_io prompt-budget evidence"
            ),
            "has_source_report": bool(source_report),
            "required_rows": required_rows,
            "valid_runtime_prompt_budget_rows": valid_rows,
            "invalid_runtime_rows_count": invalid_rows,
            "missing_runtime_rows_count": missing_rows,
            "source_counts": normalized_source_counts,
            "accepted_sources": sorted(accepted_sources),
            "accepted_observed_sources": accepted_observed_sources,
            "unsupported_sources": unsupported_sources,
        }
    )
    checked_report["checks"] = checks
    checked_report["status"] = "error"
    return checked_report


def _qwen_caption_dataset_large_set_and_forget_pilot_config_report(
    payload: QwenCaptionDatasetJobRequest,
    *,
    output_dir: Path,
    total_cases: int,
) -> Optional[Dict[str, Any]]:
    threshold_cases = int(QWEN_CAPTION_SET_AND_FORGET_REQUIRE_PILOT_CASES)
    if (
        not bool(payload.set_and_forget)
        or bool(payload.preview_only)
        or not bool(payload.require_pilot_certification)
        or threshold_cases <= 0
        or int(total_cases or 0) < threshold_cases
    ):
        return None
    checks: List[Dict[str, Any]] = []

    def add(name: str, ok: bool, detail: str, **fields: Any) -> None:
        checks.append(
            {
                "name": name,
                "status": "ok" if ok else "error",
                "detail": detail,
                **fields,
            }
        )

    pilot_dir: Optional[Path] = None
    if not payload.pilot_output_dir:
        add(
            "pilot_output_dir",
            False,
            "pilot_output_dir is required before starting a large set-and-forget caption job",
        )
    else:
        try:
            pilot_dir = _qwen_caption_dataset_job_dir(
                "pilot_certification",
                payload.pilot_output_dir,
            )
        except HTTPException as exc:
            add(
                "pilot_output_dir",
                False,
                str(exc.detail or exc),
            )
        else:
            add(
                "pilot_output_dir_isolated",
                not _paths_match_resolved(pilot_dir, output_dir),
                (
                    "pilot artifacts are isolated from the caption job output directory"
                    if not _paths_match_resolved(pilot_dir, output_dir)
                    else "pilot_output_dir must be separate from the caption job output_dir "
                    "for set-and-forget pilot certification"
                ),
                pilot_output_dir=str(pilot_dir),
                target_output_dir=str(output_dir),
            )

    try:
        pilot_min_cases = int(payload.pilot_min_cases or 0)
    except (TypeError, ValueError, OverflowError):
        pilot_min_cases = 0
    add(
        "pilot_min_cases",
        pilot_min_cases >= QWEN_CAPTION_DEFAULT_PILOT_MIN_CASES,
        (
            f"pilot min cases is {pilot_min_cases}; large set-and-forget requires at least "
            f"{QWEN_CAPTION_DEFAULT_PILOT_MIN_CASES}"
        ),
        pilot_min_cases=pilot_min_cases,
        required_min_pilot_cases=QWEN_CAPTION_DEFAULT_PILOT_MIN_CASES,
    )
    add(
        "pilot_prompt_budget_required",
        bool(payload.pilot_require_prompt_budget_data),
        "pilot prompt-budget telemetry is required before starting a large set-and-forget caption job",
    )
    try:
        pilot_max_prompt_tokens = int(payload.pilot_max_prompt_tokens or 0)
    except (TypeError, ValueError, OverflowError):
        pilot_max_prompt_tokens = 0
    add(
        "pilot_prompt_size_ceiling",
        pilot_max_prompt_tokens > 0,
        "pilot max prompt tokens must be positive before starting a large set-and-forget caption job",
        max_prompt_tokens=pilot_max_prompt_tokens,
    )
    p95_value = payload.pilot_max_p95_duration_hours
    try:
        pilot_max_p95_duration_hours = float(p95_value) if p95_value is not None else -1.0
    except (TypeError, ValueError, OverflowError):
        pilot_max_p95_duration_hours = -1.0
    add(
        "pilot_p95_duration_gate",
        pilot_max_p95_duration_hours > 0,
        "pilot p95 projected-duration gate must be positive before starting a large set-and-forget caption job",
        max_p95_duration_hours=pilot_max_p95_duration_hours,
    )
    try:
        adapted_case_rate = float(
            payload.pilot_max_prompt_budget_adapted_case_rate
            if payload.pilot_max_prompt_budget_adapted_case_rate is not None
            else -1.0
        )
    except (TypeError, ValueError, OverflowError):
        adapted_case_rate = -1.0
    add(
        "pilot_prompt_budget_adaptation_gate",
        adapted_case_rate >= 0.0,
        "pilot prompt-budget adaptation-rate gate must be enabled before starting a large set-and-forget caption job",
        max_prompt_budget_adapted_case_rate=adapted_case_rate,
    )
    try:
        deterministic_recovery_confidence = float(
            payload.pilot_deterministic_recovery_confidence
            if payload.pilot_deterministic_recovery_confidence is not None
            else QWEN_CAPTION_DEFAULT_PILOT_DETERMINISTIC_RECOVERY_CONFIDENCE
        )
    except (TypeError, ValueError, OverflowError):
        deterministic_recovery_confidence = 0.0
    add(
        "pilot_deterministic_recovery_confidence",
        deterministic_recovery_confidence > 0.0,
        "pilot deterministic-recovery confidence certification must be enabled before starting a large set-and-forget caption job",
        deterministic_recovery_confidence=deterministic_recovery_confidence,
        required_default_confidence=QWEN_CAPTION_DEFAULT_PILOT_DETERMINISTIC_RECOVERY_CONFIDENCE,
    )
    status = "ok" if all(str(check.get("status") or "") == "ok" for check in checks) else "error"
    return {
        "status": status,
        "required": True,
        "total_cases": int(total_cases or 0),
        "threshold_cases": threshold_cases,
        "output_dir": str(output_dir),
        "pilot_output_dir": str(pilot_dir) if pilot_dir is not None else str(payload.pilot_output_dir or ""),
        "checks": checks,
    }


def _qwen_caption_dataset_large_set_and_forget_supervision_report(
    payload: QwenCaptionDatasetJobRequest,
    *,
    total_cases: int,
) -> Optional[Dict[str, Any]]:
    threshold_cases = int(QWEN_CAPTION_SET_AND_FORGET_REQUIRE_PILOT_CASES)
    if (
        not bool(payload.set_and_forget)
        or bool(payload.preview_only)
        or not bool(QWEN_CAPTION_SET_AND_FORGET_REQUIRE_BACKEND_SUPERVISION)
        or threshold_cases <= 0
        or int(total_cases or 0) < threshold_cases
    ):
        return None
    supervision = _qwen_backend_supervision_status()
    restart_capable = bool(supervision.get("restart_capable"))
    set_and_forget_ready = bool(supervision.get("set_and_forget_ready"))
    restart_policy = (
        supervision.get("restart_policy")
        if isinstance(supervision.get("restart_policy"), Mapping)
        else {}
    )
    return {
        "status": "ok" if set_and_forget_ready else "error",
        "required": True,
        "total_cases": int(total_cases or 0),
        "threshold_cases": threshold_cases,
        "supervision": supervision,
        "checks": [
            {
                "name": "backend_crash_supervision",
                "status": "ok" if restart_capable else "error",
                "detail": (
                    "backend is running under crash-restart supervision"
                    if restart_capable
                    else "large set-and-forget caption jobs require backend crash-restart supervision"
                ),
                "restart_capable": restart_capable,
                "launcher": supervision.get("launcher"),
                "restart_on_crash": supervision.get("restart_on_crash"),
            },
            {
                "name": "backend_restart_policy",
                "status": "ok" if set_and_forget_ready else "error",
                "detail": (
                    "backend crash-restart policy is large-run ready"
                    if set_and_forget_ready
                    else "large set-and-forget caption jobs require unlimited backend restarts or a sufficient bounded restart policy"
                ),
                "restart_policy_status": restart_policy.get("status"),
                "restart_policy_ready": set_and_forget_ready,
                "restart_max": supervision.get("restart_max"),
                "restart_delay": supervision.get("restart_delay"),
                "restart_max_delay": supervision.get("restart_max_delay"),
                "min_restart_attempts": restart_policy.get("min_restart_attempts"),
                "max_restart_delay_seconds": restart_policy.get("max_restart_delay_seconds"),
                "policy_checks": restart_policy.get("checks") or [],
            },
        ],
    }


def _qwen_caption_dataset_result_summary_from_runner_summary(
    summary: Mapping[str, Any],
) -> Dict[str, Any]:
    rows = summary.get("rows") if isinstance(summary.get("rows"), list) else []
    ok_statuses = {"ok", "skipped_completed", "skipped_existing_caption", "preview_only"}
    rows_are_complete = bool(rows) and not bool(summary.get("rows_truncated"))
    if rows_are_complete:
        final_statuses = [
            str(row.get("final_status") or row.get("status") or "unknown")
            for row in rows
            if isinstance(row, Mapping)
        ]
        failed = sum(1 for status in final_statuses if status not in ok_statuses)
        quality_failed = sum(
            1
            for row in rows
            if isinstance(row, Mapping) and bool(row.get("quality_failures"))
        )
        generated_qa_warning = sum(
            1
            for row in rows
            if isinstance(row, Mapping) and _qwen_caption_dataset_row_generated_qa_warning(row)
        )
        generated_qa_error = sum(
            1
            for row in rows
            if isinstance(row, Mapping) and _qwen_caption_dataset_row_generated_qa_error(row)
        )
        generated_qa_underfilled = sum(
            1
            for row in rows
            if isinstance(row, Mapping) and _qwen_caption_dataset_row_generated_qa_underfilled(row)
        )
        generated_qa_zero_pair = sum(
            1
            for row in rows
            if isinstance(row, Mapping) and _qwen_caption_dataset_row_generated_qa_zero_pair(row)
        )
        return {
            "processed": len(final_statuses),
            "failed": failed,
            "quality_failed": quality_failed,
            "generated_qa_warning": generated_qa_warning,
            "generated_qa_error": generated_qa_error,
            "generated_qa_underfilled": generated_qa_underfilled,
            "generated_qa_zero_pair": generated_qa_zero_pair,
            "runner_totals": dict(Counter(final_statuses)),
            "degraded_rates": _qwen_caption_dataset_degraded_rates_from_rows(
                [row for row in rows if isinstance(row, Mapping)]
            ),
        }
    totals = summary.get("totals")
    if not isinstance(totals, Mapping):
        return {}
    runner_totals: Dict[str, int] = {}
    for key, value in totals.items():
        try:
            runner_totals[str(key)] = max(0, int(value))
        except (TypeError, ValueError, OverflowError):
            continue
    if not runner_totals:
        return {}
    try:
        processed = max(0, int(summary.get("total_cases") or sum(runner_totals.values())))
    except (TypeError, ValueError, OverflowError):
        processed = sum(runner_totals.values())
    failed = sum(
        count
        for status, count in runner_totals.items()
        if status not in ok_statuses
    )
    try:
        quality_failed = max(0, int(summary.get("quality_failed_cases") or 0))
    except (TypeError, ValueError, OverflowError):
        quality_failed = 0
    try:
        generated_qa_warning = max(0, int(summary.get("generated_qa_warning_cases") or 0))
    except (TypeError, ValueError, OverflowError):
        generated_qa_warning = 0
    try:
        generated_qa_error = max(0, int(summary.get("generated_qa_error_cases") or 0))
    except (TypeError, ValueError, OverflowError):
        generated_qa_error = 0
    try:
        generated_qa_underfilled = max(0, int(summary.get("generated_qa_underfilled_cases") or 0))
    except (TypeError, ValueError, OverflowError):
        generated_qa_underfilled = 0
    try:
        generated_qa_zero_pair = max(0, int(summary.get("generated_qa_zero_pair_cases") or 0))
    except (TypeError, ValueError, OverflowError):
        generated_qa_zero_pair = 0
    result = {
        "processed": processed,
        "failed": failed,
        "quality_failed": quality_failed,
        "generated_qa_warning": generated_qa_warning,
        "generated_qa_error": generated_qa_error,
        "generated_qa_underfilled": generated_qa_underfilled,
        "generated_qa_zero_pair": generated_qa_zero_pair,
        "runner_totals": runner_totals,
    }
    degraded_rates = summary.get("degraded_rates")
    if isinstance(degraded_rates, Mapping):
        result["degraded_rates"] = dict(degraded_rates)
    return result


def _qwen_caption_dataset_effective_request_fields(
    request_fields: Mapping[str, Any],
    *,
    set_and_forget: bool = False,
) -> Tuple[Dict[str, Any], Dict[str, str]]:
    fields = dict(request_fields or {})
    caption_mode = str(fields.get("caption_mode") or "full").strip().lower()
    if caption_mode == "hybrid":
        caption_mode = "windowed"
    if caption_mode not in {"full", "windowed"}:
        caption_mode = "full"
    fields["caption_mode"] = caption_mode
    has_explicit_windowed_strategy = (
        "caption_windowed_full_image_strategy" in fields
        and str(fields.get("caption_windowed_full_image_strategy") or "").strip() != ""
    )
    strategy = (
        str(fields.get("caption_windowed_full_image_strategy") or "")
        .strip()
        .lower()
        .replace("-", "_")
    )
    if strategy in {"text", "text_only", "window_text", "windowed_text", "observations", "skip_visual"}:
        strategy = "text_only"
    elif strategy not in {"visual", "text_only"}:
        strategy = "text_only" if bool(set_and_forget) and caption_mode == "windowed" else "visual"
    if bool(set_and_forget) and caption_mode == "windowed" and not has_explicit_windowed_strategy:
        strategy = "text_only"
    fields["caption_windowed_full_image_strategy"] = strategy
    variant = str(fields.get("model_variant") or "auto").strip()
    if variant not in {"auto", "Instruct", "Thinking"}:
        variant = "auto"
    fields["model_variant"] = variant
    model_id = str(fields.get("model_id") or "").strip()
    if model_id.lower() in {"", "active", "auto", "default"}:
        model_id = _resolve_qwen_variant_model_id_impl(QWEN_MLX_CAPTION_MODEL_NAME, variant)
    fields["model_id"] = model_id
    refinement_model_id = str(fields.get("refinement_model_id") or "same").strip() or "same"
    fields["refinement_model_id"] = refinement_model_id
    fallback_model_id = str(fields.get("caption_fallback_model_id") or "auto").strip() or "auto"
    fields["caption_fallback_model_id"] = fallback_model_id
    loop_recovery = str(fields.get("caption_loop_recovery_mode") or "safe_retry_fallback").strip()
    if loop_recovery not in {"off", "safe_retry", "safe_retry_fallback"}:
        loop_recovery = "safe_retry_fallback"
    fields["caption_loop_recovery_mode"] = loop_recovery
    return fields, {
        "model_id": model_id,
        "model_variant": variant,
        "refinement_model_id": refinement_model_id,
        "fallback_model_id": fallback_model_id,
        "loop_recovery": loop_recovery,
    }


def _qwen_caption_dataset_read_runner_heartbeat(
    heartbeat_path: Path,
    *,
    last_mtime: float = 0.0,
) -> Tuple[float, Optional[Dict[str, Any]]]:
    try:
        stat_result = heartbeat_path.stat()
    except FileNotFoundError:
        return last_mtime, None
    except Exception:
        return last_mtime, None
    mtime = float(stat_result.st_mtime or 0.0)
    if mtime <= last_mtime:
        return last_mtime, None
    try:
        payload = json.loads(heartbeat_path.read_text())
    except Exception:
        return mtime, None
    if not isinstance(payload, dict):
        return mtime, None
    return mtime, payload


def _qwen_caption_dataset_runner_heartbeat_message(heartbeat: Mapping[str, Any]) -> str:
    phase = str(heartbeat.get("phase") or "heartbeat").replace("_", " ")
    processed = heartbeat.get("processed")
    total = heartbeat.get("total_cases")
    image_name = str(heartbeat.get("image_name") or "").strip()
    stem = str(heartbeat.get("stem") or "").strip()
    case_name = str(heartbeat.get("case") or "").strip()
    display_case = image_name or stem or case_name
    attempt = heartbeat.get("attempt")
    worker_progress = (
        heartbeat.get("worker_progress")
        if isinstance(heartbeat.get("worker_progress"), Mapping)
        else {}
    )
    parts = [f"Caption runner {phase}"]
    if display_case:
        parts.append(display_case)
    if attempt:
        parts.append(f"attempt {attempt}")
    if processed is not None and total:
        parts.append(f"{processed}/{total} complete")
    worker_step = str(
        heartbeat.get("worker_step_label")
        or worker_progress.get("step_label")
        or worker_progress.get("phase_label")
        or ""
    ).strip()
    worker_message = str(
        heartbeat.get("worker_message")
        or worker_progress.get("message")
        or ""
    ).strip()
    if worker_step:
        qwen_detail = f"Qwen: {worker_step}"
        if worker_message and worker_message != worker_step:
            qwen_detail = f"{qwen_detail}: {worker_message}"
        generated = heartbeat.get("worker_generated_tokens", worker_progress.get("generated_tokens"))
        max_tokens = heartbeat.get("worker_max_new_tokens", worker_progress.get("max_new_tokens"))
        if generated is not None and max_tokens:
            qwen_detail = f"{qwen_detail} ({generated}/{max_tokens} tokens)"
        parts.append(qwen_detail)
    return "; ".join(parts)


def _qwen_caption_dataset_stop_process(process: subprocess.Popen[Any], *, kill_timeout: float = 10.0) -> None:
    if process.poll() is not None:
        return
    try:
        process.terminate()
    except Exception:
        return
    try:
        process.wait(timeout=kill_timeout)
    except subprocess.TimeoutExpired:
        try:
            process.kill()
        except Exception:
            pass
    except Exception:
        pass


def _qwen_caption_dataset_live_auto_resume_after_failure(job: QwenCaptionDatasetJob) -> None:
    if not _qwen_caption_dataset_job_should_live_auto_resume(job):
        return
    try:
        resumed_job = _resume_qwen_caption_dataset_job(job.job_id, auto_resume=True)
        result_data = dict(job.result or {})
        result_data["auto_resumed_job_id"] = resumed_job.job_id
        result_data["auto_resumed_at"] = time.time()
        result_data["auto_resumed_from_error"] = job.error
        job.result = result_data
        job.message = f"Auto-resumed as {resumed_job.job_id}"
        _qwen_caption_dataset_job_log(
            job,
            "scheduled set-and-forget auto-resume",
            resumed_job_id=resumed_job.job_id,
            failure_error=job.error,
        )
        _persist_qwen_caption_dataset_job(job)
    except Exception:
        logger.exception("Failed to live auto-resume Qwen caption dataset job %s", job.job_id)


def _run_qwen_caption_dataset_job(job: QwenCaptionDatasetJob, payload: QwenCaptionDatasetJobRequest) -> None:
    job.status = "running"
    job.message = "Preparing caption dataset job"
    job.request = model_dump_compat(payload)
    job.updated_at = time.time()
    _persist_qwen_caption_dataset_job(job)
    process: Optional[subprocess.Popen[str]] = None
    try:
        job_output_dir = Path(job.output_dir or _qwen_caption_dataset_job_dir(job.job_id))
        job_output_dir.mkdir(parents=True, exist_ok=True)
        job.output_dir = str(job_output_dir)
        runner_output_dir = (
            _qwen_caption_dataset_job_dir(job.job_id, payload.output_dir)
            if payload.output_dir
            else job_output_dir
        )
        runner_output_dir.mkdir(parents=True, exist_ok=True)
        dataset_entry = _resolve_dataset_entry(payload.dataset_id)
        if _qwen_caption_dataset_requires_annotation_write(payload):
            _require_dataset_annotation_lock_owner_if_active(
                dataset_entry,
                _qwen_caption_dataset_annotation_lock_payload(payload),
            )
        resume_manifest_cases = (
            _qwen_caption_dataset_resume_manifest_cases(runner_output_dir)
            if bool(payload.resume) and bool(payload.output_dir)
            else None
        )
        if resume_manifest_cases is not None:
            manifest = _annotation_manifest_for_entry(dataset_entry)
            cases = resume_manifest_cases
        else:
            manifest, cases = _qwen_caption_dataset_cases(payload, output_dir=runner_output_dir)
        if not cases:
            job.status = "completed"
            job.progress = 1.0
            job.message = "No target images needed captioning"
            job.result = {
                "dataset_id": payload.dataset_id,
                "total_cases": 0,
                "processed": 0,
                "saved_text_labels": 0,
                "output_dir": str(runner_output_dir),
                "job_output_dir": str(job_output_dir),
            }
            _qwen_caption_dataset_try_materialize_instruction_artifacts(
                job,
                payload,
                artifact_dir=runner_output_dir / "instruction_artifacts",
            )
            if job.status == "completed" and bool(payload.instruction_dataset):
                job.message = "No target images needed captioning; training dataset artifacts materialized"
            job.updated_at = time.time()
            _persist_qwen_caption_dataset_job(job)
            return
        caption_request_fields, caption_runner_model_fields = _qwen_caption_dataset_effective_request_fields(
            payload.caption_request or {},
            set_and_forget=bool(payload.set_and_forget),
        )
        effective_request = dict(job.request or {})
        effective_request["caption_request"] = dict(caption_request_fields)
        job.request = effective_request
        _persist_qwen_caption_dataset_job(job)
        cases_path = job_output_dir / "cases.json"
        request_path = job_output_dir / "request_fields.json"
        cases_path.write_text(json.dumps(cases, indent=2, sort_keys=True))
        request_path.write_text(json.dumps(caption_request_fields, indent=2, sort_keys=True))
        runner_profile = _qwen_caption_dataset_runner_profile(payload)
        requested_runner_settings = _qwen_caption_dataset_requested_runner_settings(
            request_path=request_path,
            caption_runner_model_fields=caption_runner_model_fields,
            runner_profile=runner_profile,
            payload=payload,
        )
        requested_runner_args = (
            dict(requested_runner_settings.get("caption_args"))
            if isinstance(requested_runner_settings.get("caption_args"), Mapping)
            else {}
        )
        total = len(cases)
        dataset_root = _dataset_effective_root_from_entry(dataset_entry)
        result_summary: Dict[str, Any] = {
            "dataset_id": payload.dataset_id,
            "dataset_label": manifest.get("dataset_label") or payload.dataset_id,
            "total_cases": total,
            "processed": 0,
            "attempts_seen": 0,
            "failed_attempts": 0,
            "failed": 0,
            "quality_failed": 0,
            "saved_text_labels": 0,
            "output_dir": str(runner_output_dir),
            "job_output_dir": str(job_output_dir),
            "results_jsonl": str(runner_output_dir / "results.jsonl"),
            "captions_jsonl": str(runner_output_dir / "captions.jsonl"),
            "summary_json": str(runner_output_dir / "summary.json"),
            "heartbeat_json": str(runner_output_dir / "heartbeat.json"),
            "runner_artifact_log_bytes": payload.runner_artifact_log_bytes,
            "runner_profile": dict(runner_profile),
            "caption_provider": str(payload.caption_provider or "local_qwen"),
            "openai_model": str(payload.openai_model or "gpt-5.5")
            if str(payload.caption_provider or "local_qwen") == "openai"
            else None,
            "openai_image_detail": str(payload.openai_image_detail or "original")
            if str(payload.caption_provider or "local_qwen") == "openai"
            else None,
            "openai_reasoning_effort": _openai_caption_normalize_reasoning_effort(payload.openai_reasoning_effort)
            if str(payload.caption_provider or "local_qwen") == "openai"
            else None,
            "openai_service_tier": str(payload.openai_service_tier or "batch")
            if str(payload.caption_provider or "local_qwen") == "openai"
            else None,
            "effective_model_fields": dict(caption_runner_model_fields),
            "requested_run_settings": dict(requested_runner_settings),
            "instruction_dataset": bool(payload.instruction_dataset),
            "generated_qa_rows": 0,
        }
        job.result = dict(result_summary)
        pilot_required_threshold = int(QWEN_CAPTION_SET_AND_FORGET_REQUIRE_PILOT_CASES)
        if (
            bool(payload.set_and_forget)
            and not bool(payload.preview_only)
            and not bool(payload.require_pilot_certification)
            and pilot_required_threshold > 0
            and total >= pilot_required_threshold
        ):
            pilot_requirement_report = {
                "status": "error",
                "required": True,
                "total_cases": total,
                "threshold_cases": pilot_required_threshold,
                "checks": [
                    {
                        "name": "set_and_forget_pilot_required",
                        "status": "error",
                        "detail": (
                            "certified pilot is required before starting a set-and-forget "
                            f"caption job with {total} cases"
                        ),
                    }
                ],
            }
            result_summary["required_pilot_certification"] = pilot_requirement_report
            job.result = dict(result_summary)
            job.status = "failed"
            job.progress = 1.0
            job.error = "caption_runner_pilot_required"
            job.message = (
                "Certified pilot required before starting this set-and-forget caption job "
                f"({total} cases, threshold {pilot_required_threshold})."
            )
            job.updated_at = time.time()
            _qwen_caption_dataset_job_log(
                job,
                "caption runner pilot certification required",
                required_pilot_certification=pilot_requirement_report,
            )
            _persist_qwen_caption_dataset_job(job)
            return
        pilot_config_report = _qwen_caption_dataset_large_set_and_forget_pilot_config_report(
            payload,
            output_dir=runner_output_dir,
            total_cases=total,
        )
        if pilot_config_report is not None and str(pilot_config_report.get("status") or "").lower() != "ok":
            result_summary["required_pilot_certification"] = pilot_config_report
            job.result = dict(result_summary)
            failed_checks = [
                check
                for check in (pilot_config_report.get("checks") or [])
                if isinstance(check, Mapping) and str(check.get("status") or "").lower() != "ok"
            ]
            first_detail = str(failed_checks[0].get("detail") if failed_checks else "pilot configuration failed")
            job.status = "failed"
            job.progress = 1.0
            job.error = "caption_runner_pilot_certification_failed"
            job.message = f"Pilot certification configuration failed: {first_detail}"
            job.updated_at = time.time()
            _qwen_caption_dataset_job_log(
                job,
                "caption runner pilot certification configuration failed",
                required_pilot_certification=pilot_config_report,
            )
            _persist_qwen_caption_dataset_job(job)
            return
        supervision_report = _qwen_caption_dataset_large_set_and_forget_supervision_report(
            payload,
            total_cases=total,
        )
        if supervision_report is not None:
            result_summary["backend_supervision"] = supervision_report
            job.result = dict(result_summary)
            if str(supervision_report.get("status") or "").lower() != "ok":
                failed_checks = [
                    check
                    for check in (supervision_report.get("checks") or [])
                    if isinstance(check, Mapping) and str(check.get("status") or "").lower() != "ok"
                ]
                first_detail = str(failed_checks[0].get("detail") if failed_checks else "backend supervision required")
                job.status = "failed"
                job.progress = 1.0
                job.error = "caption_runner_backend_supervision_required"
                job.message = f"Backend supervision required: {first_detail}"
                job.updated_at = time.time()
                _qwen_caption_dataset_job_log(
                    job,
                    "caption runner backend crash supervision required",
                    backend_supervision=supervision_report,
                )
                _persist_qwen_caption_dataset_job(job)
                return
        try:
            from tools import preflight_qwen_caption_soak as caption_preflight

            preflight_report = caption_preflight.preflight_soak(
                SimpleNamespace(
                    dataset_root=Path(dataset_root),
                    cases_json=cases_path,
                    request_json=request_path,
                    output_dir=runner_output_dir,
                    all_images=False,
                    caption_mode="full",
                    sample_size=0,
                    sample_seed=13,
                    case=[],
                    limit=0,
                    resume=bool(payload.resume),
                    save_dataset_text_labels=bool(payload.save_text_labels),
                    attempts=payload.attempts,
                    max_artifact_log_bytes=payload.runner_artifact_log_bytes,
                    min_free_gb=payload.runner_min_free_gb,
                    disk_safety_factor=payload.runner_disk_safety_factor,
                    max_heartbeat_age=max(300.0, float(payload.runner_no_output_timeout_seconds or 0.0)),
                    model_id=caption_runner_model_fields["model_id"],
                    model_variant=caption_runner_model_fields["model_variant"],
                    refinement_model_id=caption_runner_model_fields["refinement_model_id"],
                    fallback_model_id=caption_runner_model_fields["fallback_model_id"],
                    loop_recovery=caption_runner_model_fields["loop_recovery"],
                    caption_provider=str(payload.caption_provider or "local_qwen"),
                    allow_model_download=bool(payload.allow_model_download),
                    preview_only=bool(payload.preview_only),
                    max_boxes=requested_runner_args.get("max_boxes", 0),
                    max_new_tokens=requested_runner_args.get("max_new_tokens"),
                    final_sentences=requested_runner_args.get("final_sentences", 8),
                    window_size=requested_runner_args.get("window_size", QWEN_WINDOW_DEFAULT_SIZE),
                    window_overlap=requested_runner_args.get("window_overlap", QWEN_WINDOW_DEFAULT_OVERLAP),
                    mlx_max_image_side=requested_runner_args.get(
                        "mlx_max_image_side",
                        runner_profile["mlx_max_image_side"],
                    ),
                    retry_image_side_scale=requested_runner_args.get(
                        "retry_image_side_scale",
                        runner_profile["retry_image_side_scale"],
                    ),
                    min_retry_image_side=requested_runner_args.get(
                        "min_retry_image_side",
                        runner_profile["min_retry_image_side"],
                    ),
                    cooldown_after_success=requested_runner_args.get(
                        "cooldown_after_success",
                        runner_profile["cooldown_after_success"],
                    ),
                    temperature=requested_runner_args.get("temperature", 0.2),
                    top_p=requested_runner_args.get("top_p", 0.8),
                    top_k=requested_runner_args.get("top_k", 20),
                    use_sampling=bool(requested_runner_args.get("use_sampling", False)),
                    prompt=requested_runner_args.get("prompt", ""),
                    instruction_dataset=bool(requested_runner_args.get("instruction_dataset", False)),
                    subcaptions_per_image=int(requested_runner_args.get("subcaptions_per_image") or 0),
                    include_caption0_in_training=bool(
                        requested_runner_args.get("include_caption0_in_training", True)
                    ),
                    include_generated_qa_in_training=bool(
                        requested_runner_args.get("include_generated_qa_in_training", True)
                    ),
                    include_deterministic_metadata_qa=bool(
                        requested_runner_args.get("include_deterministic_metadata_qa", False)
                    ),
                    instruction_qa_imposed_questions=list(
                        requested_runner_args.get("instruction_qa_imposed_questions") or []
                    ),
                    instruction_qa_max_topup_attempts=int(
                        requested_runner_args.get("instruction_qa_max_topup_attempts") or 0
                    ),
                    instruction_qa_restrict_speculative_language=bool(
                        requested_runner_args.get("instruction_qa_restrict_speculative_language", False)
                    ),
                    instruction_max_new_tokens=requested_runner_args.get("instruction_max_new_tokens"),
                    include_source_annotations_in_generator_context=bool(
                        requested_runner_args.get("include_source_annotations_in_generator_context", True)
                    ),
                    strict_grounding=bool(requested_runner_args.get("strict_grounding", True)),
                    qa_mix=str(requested_runner_args.get("qa_mix") or "balanced"),
                    answer_format=str(requested_runner_args.get("answer_format") or "natural"),
                )
            )
        except Exception as exc:  # noqa: BLE001
            preflight_report = {
                "status": "error",
                "checks": [
                    {
                        "name": "backend_preflight",
                        "status": "error",
                        "detail": str(exc),
                        "error_type": type(exc).__name__,
                    }
                ],
            }
        result_summary["preflight"] = preflight_report
        job.result = dict(result_summary)
        if str(preflight_report.get("status") or "").lower() == "error":
            failed_checks = [
                check
                for check in (preflight_report.get("checks") or [])
                if isinstance(check, Mapping) and str(check.get("status") or "").lower() == "error"
            ]
            first_detail = str(failed_checks[0].get("detail") if failed_checks else "preflight failed")
            job.status = "failed"
            job.progress = 1.0
            job.error = "caption_runner_preflight_failed"
            job.message = f"Caption runner preflight failed: {first_detail}"
            job.updated_at = time.time()
            _qwen_caption_dataset_job_log(
                job,
                "caption runner preflight failed",
                preflight=preflight_report,
            )
            _persist_qwen_caption_dataset_job(job)
            return
        pilot_certification_report = _qwen_caption_dataset_required_pilot_certification(
            payload,
            output_dir=runner_output_dir,
            request_data=job.request if isinstance(job.request, Mapping) else model_dump_compat(payload),
            max_heartbeat_age_seconds=max(300.0, float(payload.runner_no_output_timeout_seconds or 0.0)),
            expected_run_settings_fingerprint=str(requested_runner_settings.get("fingerprint") or ""),
        )
        if pilot_certification_report is not None:
            result_summary["required_pilot_certification"] = pilot_certification_report
            job.result = dict(result_summary)
            certification_status = str(pilot_certification_report.get("status") or "error").lower()
            if certification_status != "ok":
                failed_checks = [
                    check
                    for check in (pilot_certification_report.get("checks") or [])
                    if isinstance(check, Mapping) and str(check.get("status") or "").lower() != "ok"
                ]
                first_detail = str(failed_checks[0].get("detail") if failed_checks else certification_status)
                job.status = "failed"
                job.progress = 1.0
                job.error = "caption_runner_pilot_certification_failed"
                job.message = f"Pilot certification failed: {first_detail}"
                job.updated_at = time.time()
                _qwen_caption_dataset_job_log(
                    job,
                    "caption runner pilot certification failed",
                    pilot_certification=pilot_certification_report,
                )
                _persist_qwen_caption_dataset_job(job)
                return
            _qwen_caption_dataset_job_log(
                job,
                "caption runner pilot certification passed",
                pilot_certification=pilot_certification_report,
            )
            _persist_qwen_caption_dataset_job(job)
        cmd = [
            sys.executable,
            str(Path(__file__).resolve().parent / "tools" / "run_qwen_caption_flow_benchmark.py"),
            "--cases-json",
            str(cases_path),
            "--request-json",
            str(request_path),
            "--dataset-root",
            str(dataset_root),
            "--output-dir",
            str(runner_output_dir),
            "--caption-provider",
            str(payload.caption_provider or "local_qwen"),
            "--openai-model",
            str(payload.openai_model or "gpt-5.5"),
            "--openai-image-detail",
            str(payload.openai_image_detail or "original"),
            "--openai-reasoning-effort",
            _openai_caption_normalize_reasoning_effort(payload.openai_reasoning_effort),
            "--openai-api-key-file",
            str(payload.openai_api_key_path or "openAI_API_KEY_DoNotCommit"),
            "--openai-service-tier",
            str(payload.openai_service_tier or "batch"),
            "--openai-timeout",
            str(float(payload.openai_timeout_seconds or 120.0)),
            "--attempts",
            str(payload.attempts),
            "--timeout",
            str(payload.per_image_timeout_seconds),
            "--cooldown-after-crash",
            str(payload.cooldown_after_crash_seconds),
            "--cooldown-after-success",
            str(runner_profile["cooldown_after_success"]),
            "--max-failures",
            str(payload.max_failures),
            "--heartbeat-interval",
            str(payload.runner_heartbeat_interval_seconds),
            "--max-artifact-log-bytes",
            str(payload.runner_artifact_log_bytes),
            "--model-id",
            caption_runner_model_fields["model_id"],
            "--refinement-model-id",
            caption_runner_model_fields["refinement_model_id"],
            "--fallback-model-id",
            caption_runner_model_fields["fallback_model_id"],
            "--loop-recovery",
            caption_runner_model_fields["loop_recovery"],
            "--windowed-full-image-strategy",
            str(caption_request_fields.get("caption_windowed_full_image_strategy") or "visual"),
            "--mlx-max-image-side",
            str(runner_profile["mlx_max_image_side"]),
            "--retry-image-side-scale",
            str(runner_profile["retry_image_side_scale"]),
            "--min-retry-image-side",
            str(runner_profile["min_retry_image_side"]),
        ]
        if bool(payload.resume):
            cmd.append("--resume")
        if bool(payload.resume_reprocess_recovery_events):
            cmd.append("--resume-reprocess-recovery-events")
        if bool(payload.preview_only):
            cmd.append("--preview-only")
        if bool(payload.continue_on_quality_failures):
            cmd.append("--continue-on-quality-failures")
        if bool(payload.save_text_labels):
            cmd.append("--save-dataset-text-labels")
        if bool(payload.instruction_dataset):
            cmd.append("--instruction-dataset")
        effective_subcaptions = _qwen_caption_dataset_effective_generated_qa_request_count(payload)
        if effective_subcaptions > 0:
            cmd.extend(["--subcaptions-per-image", str(effective_subcaptions)])
        if not _qwen_caption_dataset_effective_include_caption0_in_training(payload):
            cmd.append("--no-include-caption0-in-training")
        if not bool(payload.include_generated_qa_in_training):
            cmd.append("--no-include-generated-qa-in-training")
        if bool(payload.include_deterministic_metadata_qa):
            cmd.append("--include-deterministic-metadata-qa")
        for question in list(payload.instruction_qa_imposed_questions or []):
            cmd.extend(["--instruction-qa-imposed-question", str(question)])
        cmd.extend(
            [
                "--instruction-qa-max-topup-attempts",
                str(int(payload.instruction_qa_max_topup_attempts or 0)),
            ]
        )
        if bool(payload.instruction_qa_restrict_speculative_language):
            cmd.append("--restrict-speculative-qa-language")
        cmd.extend(["--qa-mix", str(payload.qa_mix or "balanced")])
        cmd.extend(["--answer-format", str(payload.answer_format or "natural")])
        if not bool(payload.include_source_annotations_in_generator_context):
            cmd.append("--no-source-annotations-in-generator-context")
        if not bool(payload.strict_grounding):
            cmd.append("--relaxed-instruction-grounding")
        env = os.environ.copy()
        env.setdefault("NO_ALBUMENTATIONS_UPDATE", "1")
        _qwen_caption_dataset_job_log(
            job,
            "starting caption runner",
            command=_qwen_caption_dataset_mask_command_for_log(cmd),
        )
        process = subprocess.Popen(
            cmd,
            cwd=str(Path(__file__).resolve().parent),
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            env=env,
        )
        job.process = process
        _persist_qwen_caption_dataset_job(job)
        runner_stdout = process.stdout
        if runner_stdout is None:
            raise RuntimeError("caption_runner_stdout_unavailable")
        case_statuses: Dict[str, str] = {}
        quality_failed_cases: Set[str] = set()
        recovery_event_cases: Set[str] = set()
        loop_recovery_cases: Set[str] = set()
        deterministic_recovery_cases: Set[str] = set()
        prompt_budget_adapted_cases: Set[str] = set()
        stream_loop_detected_cases: Set[str] = set()
        loop_trim_cases: Set[str] = set()
        recovery_events_seen = 0
        signal_exit_attempts_seen = 0
        stream_loop_detected_events_seen = 0
        loop_trim_events_seen = 0
        max_prompt_tokens = 0
        stdout_queue: "queue.Queue[Optional[str]]" = queue.Queue()

        def _read_runner_stdout() -> None:
            try:
                for stdout_line in runner_stdout:
                    stdout_queue.put(stdout_line)
            finally:
                stdout_queue.put(None)

        stdout_thread = threading.Thread(
            target=_read_runner_stdout,
            name=f"qwen-caption-runner-stdout-{job.job_id}",
            daemon=True,
        )
        stdout_thread.start()
        no_output_timeout = float(payload.runner_no_output_timeout_seconds or 0.0)
        last_output_at = time.monotonic()
        heartbeat_path = runner_output_dir / "heartbeat.json"
        last_heartbeat_mtime = 0.0
        last_heartbeat_seq: Any = None

        def _apply_runner_heartbeat() -> None:
            nonlocal last_heartbeat_mtime, last_heartbeat_seq, last_output_at, result_summary
            last_heartbeat_mtime, heartbeat = _qwen_caption_dataset_read_runner_heartbeat(
                heartbeat_path,
                last_mtime=last_heartbeat_mtime,
            )
            if not heartbeat:
                return
            result_summary["runner_heartbeat"] = heartbeat
            heartbeat_seq = heartbeat.get("seq")
            new_phase = heartbeat_seq is None or heartbeat_seq != last_heartbeat_seq
            if new_phase:
                last_heartbeat_seq = heartbeat_seq
                last_output_at = time.monotonic()
                job.message = _qwen_caption_dataset_runner_heartbeat_message(heartbeat)
                _qwen_caption_dataset_job_log(
                    job,
                    "runner heartbeat",
                    heartbeat=heartbeat,
                )
            heartbeat_total = int(
                max(
                    0.0,
                    _qwen_caption_dataset_numeric(
                        heartbeat.get("total_cases"),
                        result_summary.get("total_cases") or total,
                    ),
                )
            )
            heartbeat_processed = int(
                max(
                    0.0,
                    _qwen_caption_dataset_numeric(
                        heartbeat.get("processed"),
                        result_summary.get("processed") or 0,
                    ),
                )
            )
            heartbeat_case_index = int(
                max(0.0, _qwen_caption_dataset_numeric(heartbeat.get("case_index"), 0.0))
            )
            heartbeat_worker_progress = (
                heartbeat.get("worker_progress")
                if isinstance(heartbeat.get("worker_progress"), Mapping)
                else {}
            )
            heartbeat_worker_fraction = max(
                0.0,
                min(
                    1.0,
                    _qwen_caption_dataset_numeric(
                        heartbeat_worker_progress.get("progress"),
                        0.0,
                    ),
                ),
            )
            if heartbeat_total > 0:
                heartbeat_fraction = heartbeat_processed / float(heartbeat_total)
                if heartbeat_case_index > 0:
                    heartbeat_fraction = max(
                        heartbeat_fraction,
                        ((heartbeat_case_index - 1) + heartbeat_worker_fraction)
                        / float(heartbeat_total),
                    )
                job.progress = min(0.99, max(job.progress, heartbeat_fraction))
            job.result = dict(result_summary)
            job.updated_at = time.time()
            _persist_qwen_caption_dataset_job(job)

        def _handle_runner_row(row: Mapping[str, Any]) -> None:
            nonlocal last_output_at, max_prompt_tokens, recovery_events_seen, result_summary
            nonlocal signal_exit_attempts_seen
            nonlocal stream_loop_detected_events_seen, loop_trim_events_seen
            last_output_at = time.monotonic()
            result_summary["attempts_seen"] = int(result_summary.get("attempts_seen") or 0) + 1
            case_key = str(row.get("case_id") or row.get("case") or row.get("stem") or "").strip()
            if not case_key:
                case_key = f"unknown_{result_summary['attempts_seen']}"
            final_status = str(row.get("final_status") or row.get("status") or "unknown")
            if final_status == "failed_attempt":
                result_summary["failed_attempts"] = int(result_summary.get("failed_attempts") or 0) + 1
                processed = len(case_statuses)
            else:
                case_statuses[case_key] = final_status
                processed = len(case_statuses)
            if row.get("return_signal") is not None or str(row.get("attempt_failure_kind") or "") == "signal_exit":
                signal_exit_attempts_seen += 1
            result_summary["processed"] = processed
            if str(payload.caption_provider or "local_qwen") == "openai":
                _qwen_caption_dataset_add_openai_usage(result_summary, row)
            ok_statuses = {"ok", "skipped_completed", "skipped_existing_caption", "preview_only"}
            result_summary["failed"] = sum(
                1 for status in case_statuses.values() if status not in ok_statuses
            )
            result_summary["runner_totals"] = dict(Counter(case_statuses.values()))
            if row.get("quality_failures"):
                quality_failed_cases.add(case_key)
            result_summary["quality_failed"] = len(quality_failed_cases)
            recovery_events = _qwen_caption_dataset_row_recovery_events(row)
            if recovery_events:
                recovery_event_cases.add(case_key)
                recovery_events_seen += len(recovery_events)
            if _qwen_caption_dataset_row_has_loop_recovery(row):
                loop_recovery_cases.add(case_key)
            if _qwen_caption_dataset_row_has_deterministic_recovery(row):
                deterministic_recovery_cases.add(case_key)
            if _qwen_caption_dataset_row_has_adapted_prompt_budget(row):
                prompt_budget_adapted_cases.add(case_key)
            stream_loop_events = _qwen_caption_dataset_row_io_event_count(
                row,
                "stream_loop_detected",
            )
            if stream_loop_events > 0:
                stream_loop_detected_cases.add(case_key)
                stream_loop_detected_events_seen += stream_loop_events
            loop_trim_events = _qwen_caption_dataset_row_io_event_count(row, "loop_trim")
            if loop_trim_events > 0:
                loop_trim_cases.add(case_key)
                loop_trim_events_seen += loop_trim_events
            max_prompt_tokens = max(max_prompt_tokens, _qwen_caption_dataset_row_max_prompt_tokens(row))
            result_summary["degraded_rates"] = _qwen_caption_dataset_degraded_rates(
                processed=processed,
                attempts_seen=int(result_summary.get("attempts_seen") or 0),
                failed=int(result_summary.get("failed") or 0),
                quality_failed=len(quality_failed_cases),
                failed_attempts=int(result_summary.get("failed_attempts") or 0),
                signal_exit_attempts=signal_exit_attempts_seen,
                recovery_event_cases=len(recovery_event_cases),
                recovery_events=recovery_events_seen,
                loop_recovery_cases=len(loop_recovery_cases),
                deterministic_recovery_cases=len(deterministic_recovery_cases),
                prompt_budget_adapted_cases=len(prompt_budget_adapted_cases),
                max_prompt_tokens=max_prompt_tokens,
                stream_loop_detected_cases=len(stream_loop_detected_cases),
                stream_loop_detected_events=stream_loop_detected_events_seen,
                loop_trim_cases=len(loop_trim_cases),
                loop_trim_events=loop_trim_events_seen,
            )
            caption_bearing_statuses = {"ok", "skipped_completed"}
            if final_status in caption_bearing_statuses:
                caption_record = _qwen_caption_dataset_caption_record_from_row(row)
                if caption_record:
                    result_summary["latest_caption"] = caption_record
                    captions = list(result_summary.get("captions") or [])
                    if total <= 25 or len(captions) < 5:
                        captions.append(caption_record)
                    result_summary["captions"] = captions[-25:]
            if bool(payload.save_text_labels) and final_status in caption_bearing_statuses:
                saved = _qwen_caption_dataset_save_caption_from_row(
                    dataset_id=payload.dataset_id,
                    row=row,
                    job=job,
                    annotation_session_id=payload.annotation_session_id,
                    make_primary=bool(payload.generated_make_primary),
                    payload=payload,
                )
                if saved:
                    result_summary["saved_text_labels"] = int(result_summary.get("saved_text_labels") or 0) + 1
            if bool(payload.instruction_dataset) and final_status in caption_bearing_statuses:
                added = _qwen_caption_dataset_save_instruction_records_from_row(
                    dataset_id=payload.dataset_id,
                    row=row,
                    job=job,
                    payload=payload,
                )
                if added:
                    result_summary["generated_qa_rows"] = int(result_summary.get("generated_qa_rows") or 0) + added
            job.progress = max(0.0, min(1.0, processed / float(max(1, total))))
            if final_status == "failed_attempt":
                job.message = f"Caption retry pending after failed attempt; {processed}/{total} complete"
            else:
                job.message = f"Captioned {processed}/{total}"
            job.result = dict(result_summary)
            job.updated_at = time.time()
            _qwen_caption_dataset_job_log(
                job,
                f"{row.get('case') or row.get('stem')}: {row.get('final_status') or row.get('status')}",
                row=row,
            )
            _persist_qwen_caption_dataset_job(job)

        while True:
            if job.cancel_event.is_set():
                break
            if process.poll() is not None and not stdout_thread.is_alive() and stdout_queue.empty():
                break
            _apply_runner_heartbeat()
            wait_seconds = 1.0
            if no_output_timeout > 0:
                elapsed = time.monotonic() - last_output_at
                remaining = no_output_timeout - elapsed
                if remaining <= 0:
                    result_summary["watchdog_timeout_seconds"] = no_output_timeout
                    job.status = "failed"
                    job.error = "caption_runner_no_output_timeout"
                    job.message = (
                        f"Caption runner made no heartbeat or result progress for "
                        f"{no_output_timeout:.0f}s"
                    )
                    job.result = dict(result_summary)
                    job.updated_at = time.time()
                    _qwen_caption_dataset_job_log(
                        job,
                        job.message,
                        timeout_seconds=no_output_timeout,
                    )
                    _qwen_caption_dataset_stop_process(process)
                    _persist_qwen_caption_dataset_job(job)
                    return
                wait_seconds = max(0.05, min(1.0, remaining))
            try:
                raw_line = stdout_queue.get(timeout=wait_seconds)
            except queue.Empty:
                continue
            if raw_line is None:
                break
            line = raw_line.strip()
            if not line:
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError:
                _qwen_caption_dataset_job_log(job, line)
                continue
            _handle_runner_row(row)
        if job.cancel_event.is_set():
            _qwen_caption_dataset_stop_process(process)
            job.status = "cancelled"
            job.message = "Cancelled"
            _persist_qwen_caption_dataset_job(job)
            return
        return_code = process.wait()
        if return_code == 0:
            job.status = "completed"
            job.progress = 1.0
            failed_count = int(result_summary.get("failed") or 0)
            job.message = (
                f"Caption dataset job complete with {failed_count} failed"
                if failed_count
                else "Caption dataset job complete"
            )
        else:
            job.status = "failed"
            job.error = f"caption_runner_exit_{return_code}"
            job.message = "Caption dataset job failed"
        job.result = dict(result_summary)
        summary_path = runner_output_dir / "summary.json"
        if summary_path.exists():
            try:
                runner_summary = json.loads(summary_path.read_text())
                job.result["runner_summary"] = runner_summary
                final_counts = _qwen_caption_dataset_result_summary_from_runner_summary(runner_summary)
                if final_counts:
                    job.result.update(final_counts)
            except Exception:
                pass
        strict_audit_report = _qwen_caption_dataset_strict_audit(
            runner_output_dir,
            job.request if isinstance(job.request, Mapping) else model_dump_compat(payload),
            max_heartbeat_age_seconds=max(300.0, float(payload.runner_no_output_timeout_seconds or 0.0)),
        )
        job.result["strict_audit"] = strict_audit_report
        if return_code == 0 and bool(payload.set_and_forget):
            degraded_rates = (
                job.result.get("degraded_rates")
                if isinstance(job.result.get("degraded_rates"), Mapping)
                else result_summary.get("degraded_rates")
            )
            degraded_policy = _qwen_caption_dataset_degraded_policy(
                degraded_rates if isinstance(degraded_rates, Mapping) else {},
                job.request if isinstance(job.request, Mapping) else model_dump_compat(payload),
                terminal=True,
            )
            job.result["degraded_policy"] = degraded_policy
            if degraded_policy.get("active_violations"):
                details = ", ".join(
                    f"{item['rate']}={float(item['actual']):.3f}>{float(item['threshold']):.3f}"
                    for item in degraded_policy["active_violations"]
                    if isinstance(item, Mapping)
                    and item.get("rate") is not None
                    and item.get("actual") is not None
                    and item.get("threshold") is not None
                )
                job.status = "failed"
                job.error = "caption_runner_degraded_rates"
                job.message = f"Caption dataset job exceeded health gates: {details}"
                job.result["degraded_rate_violations"] = degraded_policy["active_violations"]
            strict_audit_status = str(strict_audit_report.get("status") or "error").lower()
            if job.status != "failed" and strict_audit_status != "ok":
                failed_checks = [
                    check
                    for check in (strict_audit_report.get("checks") or [])
                    if isinstance(check, Mapping) and str(check.get("status") or "").lower() != "ok"
                ]
                first_detail = str(failed_checks[0].get("detail") if failed_checks else strict_audit_status)
                job.status = "failed"
                job.error = "caption_runner_strict_audit_failed"
                job.message = f"Caption dataset job failed strict artifact audit: {first_detail}"
        if return_code == 0 and job.status != "failed" and bool(payload.instruction_dataset):
            _qwen_caption_dataset_try_materialize_instruction_artifacts(
                job,
                payload,
                artifact_dir=runner_output_dir / "instruction_artifacts",
            )
            if job.status != "failed":
                failed_count = int(job.result.get("failed") or result_summary.get("failed") or 0)
                job.message = (
                    f"Caption dataset job complete with {failed_count} failed; training dataset artifacts materialized"
                    if failed_count
                    else "Caption dataset job complete; training dataset artifacts materialized"
                )
    except HTTPException as exc:
        job.status = "failed"
        job.error = str(exc.detail or exc)
        job.message = "Failed"
    except Exception as exc:  # noqa: BLE001
        logger.exception("Qwen caption dataset job %s failed", job.job_id)
        job.status = "failed"
        job.error = str(exc)
        job.message = "Failed"
    finally:
        if process is not None and process.poll() is None:
            try:
                process.terminate()
            except Exception:
                pass
        job.process = None
        job.updated_at = time.time()
        _persist_qwen_caption_dataset_job(job)
        _qwen_caption_dataset_live_auto_resume_after_failure(job)


def _qwen_caption_dataset_requires_annotation_write(
    payload: QwenCaptionDatasetJobRequest,
) -> bool:
    return bool(payload.save_text_labels) or bool(payload.instruction_dataset)


def _qwen_caption_dataset_annotation_lock_payload(
    payload: QwenCaptionDatasetJobRequest,
) -> Dict[str, str]:
    lock_payload: Dict[str, str] = {}
    session_id = str(payload.annotation_session_id or "").strip()
    if session_id:
        lock_payload["session_id"] = session_id
    return lock_payload


def _preflight_qwen_caption_dataset_annotation_lock(
    payload: QwenCaptionDatasetJobRequest,
) -> None:
    if not _qwen_caption_dataset_requires_annotation_write(payload):
        return
    dataset_entry = _resolve_dataset_entry(payload.dataset_id)
    _require_dataset_annotation_lock_owner_if_active(
        dataset_entry,
        _qwen_caption_dataset_annotation_lock_payload(payload),
    )


def _start_qwen_caption_dataset_job(
    payload: QwenCaptionDatasetJobRequest,
    *,
    force_default_output_dir: bool = False,
) -> QwenCaptionDatasetJob:
    _preflight_openai_caption_provider_request(payload)
    job_id = f"qcap_{uuid.uuid4().hex[:8]}"
    output_dir = _qwen_caption_dataset_job_dir(
        job_id,
        None if force_default_output_dir else payload.output_dir,
    )
    job = QwenCaptionDatasetJob(job_id=job_id, output_dir=str(output_dir))
    job.request = model_dump_compat(payload)
    with QWEN_CAPTION_DATASET_JOBS_LOCK:
        active = _qwen_caption_dataset_active_job_from_jobs(
            payload.dataset_id,
            list(QWEN_CAPTION_DATASET_JOBS.values()),
        )
        if active:
            active_job_id = str(active.get("job_id") or "").strip() or "unknown"
            active_status = str(active.get("status") or "").strip() or "active"
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail=f"qwen_caption_dataset_job_active:{active_job_id}:{active_status}",
            )
        persisted_active = _qwen_caption_dataset_active_persisted_job(payload.dataset_id)
        if persisted_active:
            active_job_id = str(persisted_active.get("job_id") or "").strip() or "unknown"
            active_status = str(persisted_active.get("status") or "").strip() or "active"
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail=f"qwen_caption_dataset_job_active:{active_job_id}:{active_status}",
            )
        QWEN_CAPTION_DATASET_JOBS[job.job_id] = job
    try:
        _preflight_qwen_caption_dataset_annotation_lock(payload)
        thread = threading.Thread(
            target=_run_qwen_caption_dataset_job,
            args=(job, payload),
            daemon=True,
            name=f"qwen-caption-dataset-{job_id}",
        )
        thread.start()
    except Exception:
        with QWEN_CAPTION_DATASET_JOBS_LOCK:
            if QWEN_CAPTION_DATASET_JOBS.get(job.job_id) is job:
                QWEN_CAPTION_DATASET_JOBS.pop(job.job_id, None)
        raise
    return job


def _qwen_caption_dataset_serialized_job(job_id: str) -> Dict[str, Any]:
    with QWEN_CAPTION_DATASET_JOBS_LOCK:
        live_job = QWEN_CAPTION_DATASET_JOBS.get(job_id)
    if live_job:
        return _serialize_qwen_caption_dataset_job(live_job)
    persisted = _load_qwen_caption_dataset_job_payload(job_id)
    if persisted:
        return persisted
    raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="qwen_caption_dataset_job_not_found")


def _qwen_caption_dataset_request_bool(value: Any, *, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    raw = str(value).strip().lower()
    if raw in {"1", "true", "yes", "on"}:
        return True
    if raw in {"0", "false", "no", "off"}:
        return False
    return default


def _qwen_caption_dataset_request_int(value: Any, *, default: int = 0) -> int:
    if value is None:
        return default
    try:
        return int(value)
    except (TypeError, ValueError, OverflowError):
        return default


def _qwen_caption_dataset_request_float(value: Any, *, default: float = 0.0) -> float:
    if value is None:
        return default
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return default


def _qwen_caption_dataset_normalize_path_key(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    try:
        return str(Path(raw).expanduser().resolve(strict=False))
    except Exception:
        return raw


def _qwen_caption_dataset_path_has_pytest_marker(value: Any) -> bool:
    raw = str(value or "").strip().replace("\\", "/").lower()
    return bool(raw) and (
        "/pytest-of-" in raw
        or "/pytest-" in raw
        or raw.startswith("pytest-")
    )


def _qwen_caption_dataset_job_hidden_reason(payload: Mapping[str, Any]) -> str:
    # Pytest artifacts can be mirrored into the normal discovery root if a test
    # process points output_dir at a temp tree. Do not let those stale records
    # auto-resume in a real app session, but keep tests with monkeypatched temp
    # roots unaffected.
    if _qwen_caption_dataset_path_has_pytest_marker(QWEN_CAPTION_DATASET_JOB_ROOT):
        return ""
    request_data = payload.get("request") if isinstance(payload.get("request"), Mapping) else {}
    result_data = payload.get("result") if isinstance(payload.get("result"), Mapping) else {}
    for output_value in (
        request_data.get("output_dir") if isinstance(request_data, Mapping) else None,
        result_data.get("output_dir") if isinstance(result_data, Mapping) else None,
        payload.get("output_dir"),
    ):
        if output_value and _qwen_caption_dataset_path_has_pytest_marker(output_value):
            return "ephemeral_test_output"
    return ""


def _qwen_caption_dataset_job_artifact_key(payload: Mapping[str, Any]) -> str:
    request_data = payload.get("request") if isinstance(payload.get("request"), Mapping) else {}
    result_data = payload.get("result") if isinstance(payload.get("result"), Mapping) else {}
    for candidate in (
        request_data.get("output_dir"),
        result_data.get("output_dir"),
        payload.get("output_dir"),
    ):
        key = _qwen_caption_dataset_normalize_path_key(candidate)
        if key:
            return key
    return ""


def _qwen_caption_dataset_artifact_cancel_marker_path(artifact_key: str) -> Optional[Path]:
    if not artifact_key:
        return None
    if not _qwen_caption_dataset_can_write_job_payload_dir(artifact_key):
        return None
    return Path(artifact_key).expanduser().resolve(strict=False) / QWEN_CAPTION_DATASET_ARTIFACT_CANCEL_MARKER


def _qwen_caption_dataset_artifact_cancel_marker(artifact_key: str) -> Optional[Dict[str, Any]]:
    marker_path = _qwen_caption_dataset_artifact_cancel_marker_path(artifact_key)
    if marker_path is None or not marker_path.exists():
        return None
    try:
        marker = json.loads(marker_path.read_text())
    except Exception:
        return {"cancelled": True, "marker_path": str(marker_path)}
    if not isinstance(marker, Mapping):
        return {"cancelled": True, "marker_path": str(marker_path)}
    result = dict(marker)
    result["cancelled"] = True
    result["marker_path"] = str(marker_path)
    return result


def _qwen_caption_dataset_payload_has_cancel_state(payload: Mapping[str, Any]) -> bool:
    status = str(payload.get("status") or "").strip().lower()
    if status == "cancelled":
        return True
    result_data = payload.get("result") if isinstance(payload.get("result"), Mapping) else {}
    return bool(result_data.get("artifact_cancelled_at") or result_data.get("cancelled_at"))


def _qwen_caption_dataset_artifact_cancelled_by_persisted_owner(
    artifact_key: str,
    *,
    exclude_job_id: str = "",
) -> bool:
    if not artifact_key:
        return False
    for persisted in _iter_persisted_qwen_caption_dataset_job_payloads():
        persisted_job_id = str(persisted.get("job_id") or "").strip()
        if exclude_job_id and persisted_job_id == exclude_job_id:
            continue
        if _qwen_caption_dataset_job_artifact_key(persisted) != artifact_key:
            continue
        if _qwen_caption_dataset_payload_has_cancel_state(persisted):
            return True
    return False


def _qwen_caption_dataset_job_cancelled_by_user(payload: Mapping[str, Any]) -> bool:
    if _qwen_caption_dataset_payload_has_cancel_state(payload):
        return True
    artifact_key = _qwen_caption_dataset_job_artifact_key(payload)
    return bool(_qwen_caption_dataset_artifact_cancel_marker(artifact_key))


def _qwen_caption_dataset_cancel_payload(
    payload: Mapping[str, Any],
    *,
    cancelled_at: float,
    cancelled_by_job_id: str,
    reason: str,
) -> Dict[str, Any]:
    updated = dict(payload)
    status = str(updated.get("status") or "").strip().lower()
    if status != "completed":
        updated["status"] = "cancelled"
        updated["message"] = "Cancellation requested"
    updated["updated_at"] = cancelled_at
    result_data = dict(updated.get("result") if isinstance(updated.get("result"), Mapping) else {})
    result_data.setdefault("cancelled_at", cancelled_at)
    result_data["artifact_cancelled_at"] = cancelled_at
    result_data["artifact_cancelled_by_job_id"] = cancelled_by_job_id
    result_data["artifact_cancel_reason"] = reason
    updated["result"] = result_data
    logs = list(updated.get("logs") if isinstance(updated.get("logs"), list) else [])
    seqs = [
        _qwen_caption_dataset_request_int(log.get("seq"), default=0)
        for log in logs
        if isinstance(log, Mapping)
    ]
    logs.append(
        {
            "seq": (max(seqs) if seqs else 0) + 1,
            "time": cancelled_at,
            "message": "caption artifact lineage cancelled",
            "cancelled_by_job_id": cancelled_by_job_id,
            "reason": reason,
        }
    )
    updated["logs"] = logs[-300:]
    return updated


def _qwen_caption_dataset_write_artifact_cancel_marker(
    artifact_key: str,
    *,
    cancelled_at: float,
    cancelled_by_job_id: str,
    reason: str,
) -> Optional[Dict[str, Any]]:
    marker_path = _qwen_caption_dataset_artifact_cancel_marker_path(artifact_key)
    if marker_path is None:
        return None
    marker = {
        "cancelled": True,
        "cancelled_at": cancelled_at,
        "cancelled_by_job_id": cancelled_by_job_id,
        "reason": reason,
    }
    try:
        marker_path.parent.mkdir(parents=True, exist_ok=True)
        tmp_path = marker_path.with_name(f"{marker_path.name}.tmp")
        tmp_path.write_text(json.dumps(marker, indent=2, sort_keys=True))
        tmp_path.replace(marker_path)
    except Exception:
        logger.debug("Failed to persist Qwen caption artifact cancellation marker", exc_info=True)
        return None
    marker["marker_path"] = str(marker_path)
    return marker


def _qwen_caption_dataset_apply_cancel_to_job(
    job: QwenCaptionDatasetJob,
    *,
    cancelled_at: float,
    cancelled_by_job_id: str,
    reason: str,
) -> None:
    job.cancel_event.set()
    if job.process is not None and job.process.poll() is None:
        _qwen_caption_dataset_stop_process(job.process)
    if job.status != "completed":
        job.status = "cancelled"
        job.message = "Cancellation requested"
    result_data = dict(job.result or {})
    result_data.setdefault("cancelled_at", cancelled_at)
    result_data["artifact_cancelled_at"] = cancelled_at
    result_data["artifact_cancelled_by_job_id"] = cancelled_by_job_id
    result_data["artifact_cancel_reason"] = reason
    job.result = result_data
    job.updated_at = cancelled_at
    _qwen_caption_dataset_job_log(
        job,
        "caption artifact lineage cancelled",
        cancelled_by_job_id=cancelled_by_job_id,
        reason=reason,
    )


def _qwen_caption_dataset_cancel_artifact_lineage(
    payload: Mapping[str, Any],
    *,
    cancelled_by_job_id: str,
    reason: str = "user_cancelled",
) -> Dict[str, Any]:
    cancelled_at = time.time()
    artifact_key = _qwen_caption_dataset_job_artifact_key(payload)
    if artifact_key:
        _qwen_caption_dataset_write_artifact_cancel_marker(
            artifact_key,
            cancelled_at=cancelled_at,
            cancelled_by_job_id=cancelled_by_job_id,
            reason=reason,
        )

    with QWEN_CAPTION_DATASET_JOBS_LOCK:
        live_jobs = list(QWEN_CAPTION_DATASET_JOBS.values())
    for live_job in live_jobs:
        live_payload = _serialize_qwen_caption_dataset_job(live_job)
        if artifact_key and _qwen_caption_dataset_job_artifact_key(live_payload) != artifact_key:
            continue
        if not artifact_key and live_job.job_id != cancelled_by_job_id:
            continue
        _qwen_caption_dataset_apply_cancel_to_job(
            live_job,
            cancelled_at=cancelled_at,
            cancelled_by_job_id=cancelled_by_job_id,
            reason=reason,
        )
        _persist_qwen_caption_dataset_job(live_job)

    requested_payload: Optional[Dict[str, Any]] = None
    for persisted in _iter_persisted_qwen_caption_dataset_job_payloads():
        persisted_job_id = str(persisted.get("job_id") or "").strip()
        if artifact_key and _qwen_caption_dataset_job_artifact_key(persisted) != artifact_key:
            continue
        if not artifact_key and persisted_job_id != cancelled_by_job_id:
            continue
        updated = _qwen_caption_dataset_cancel_payload(
            persisted,
            cancelled_at=cancelled_at,
            cancelled_by_job_id=cancelled_by_job_id,
            reason=reason,
        )
        _persist_qwen_caption_dataset_job_payload(updated)
        if persisted_job_id == cancelled_by_job_id:
            requested_payload = updated

    if requested_payload is not None:
        return requested_payload
    return _qwen_caption_dataset_cancel_payload(
        payload,
        cancelled_at=cancelled_at,
        cancelled_by_job_id=cancelled_by_job_id,
        reason=reason,
    )


def _qwen_caption_dataset_job_is_active_artifact_owner(payload: Mapping[str, Any]) -> bool:
    status = str(payload.get("status") or "").strip().lower()
    return status in {"queued", "running", "cancelling"}


def _qwen_caption_dataset_pid_is_alive(pid: Any) -> bool:
    try:
        pid_int = int(pid)
    except (TypeError, ValueError, OverflowError):
        return False
    if pid_int <= 0:
        return False
    try:
        os.kill(pid_int, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False
    return True


def _qwen_caption_dataset_artifact_runner_lock(artifact_key: str) -> Dict[str, Any]:
    if not artifact_key:
        return {}
    lock_path = Path(artifact_key) / ".runner.lock"
    try:
        lock = json.loads(lock_path.read_text())
    except FileNotFoundError:
        return {}
    except Exception:
        return {}
    if not isinstance(lock, Mapping):
        return {}
    result = dict(lock)
    result["lock_path"] = str(lock_path)
    result["pid_alive"] = _qwen_caption_dataset_pid_is_alive(result.get("pid"))
    return result


def _qwen_caption_dataset_artifact_has_live_runner_lock(artifact_key: str) -> bool:
    lock = _qwen_caption_dataset_artifact_runner_lock(artifact_key)
    return bool(lock.get("pid_alive"))


def _qwen_caption_dataset_job_sort_value(payload: Mapping[str, Any]) -> float:
    for key in ("updated_at", "created_at"):
        if payload.get(key) is None:
            continue
        try:
            return float(payload.get(key))
        except (TypeError, ValueError, OverflowError):
            continue
    return 0.0


def _qwen_caption_dataset_job_auto_resume_limit(request_data: Mapping[str, Any]) -> int:
    explicit = request_data.get("max_auto_resumes")
    if explicit is None:
        return int(QWEN_CAPTION_SET_AND_FORGET_MAX_AUTO_RESUMES)
    return max(0, _qwen_caption_dataset_request_int(explicit, default=0))


def _qwen_caption_dataset_job_has_jsonl_corruption(payload: Mapping[str, Any]) -> bool:
    result_data = payload.get("result") if isinstance(payload.get("result"), Mapping) else {}
    strict_audit = (
        result_data.get("strict_audit")
        if isinstance(result_data.get("strict_audit"), Mapping)
        else {}
    )
    for check in strict_audit.get("checks") or []:
        if not isinstance(check, Mapping):
            continue
        name = str(check.get("name") or "").strip()
        status = str(check.get("status") or "").strip().lower()
        if name in {"results_jsonl", "captions_jsonl"} and status == "error" and check.get("invalid_rows"):
            return True
    return False


def _qwen_caption_dataset_job_hard_resume_error(error: Any) -> bool:
    error_code = str(error or "").strip()
    return error_code in {
        "caption_runner_preflight_failed",
        "caption_runner_pilot_required",
        "caption_runner_pilot_certification_failed",
        "caption_runner_backend_supervision_required",
    }


def _qwen_caption_dataset_job_has_resume_evidence(payload: Mapping[str, Any]) -> bool:
    result_data = payload.get("result") if isinstance(payload.get("result"), Mapping) else {}
    if not isinstance(result_data, Mapping) or not result_data:
        return False
    evidence_keys = {
        "preflight",
        "runner_heartbeat",
        "strict_audit",
        "latest_caption",
        "captions",
        "runner_totals",
    }
    if any(result_data.get(key) for key in evidence_keys):
        return True
    for numeric_key in ("processed", "total_cases", "attempts_seen", "failed_attempts"):
        if result_data.get(numeric_key) is not None:
            return True
    return False


def _qwen_caption_dataset_reconcile_completed_artifact(
    payload: Mapping[str, Any],
    *,
    artifact_key: str,
) -> Optional[Dict[str, Any]]:
    if not artifact_key:
        return None
    job_id = str(payload.get("job_id") or "").strip()
    metadata_output_dir = str(payload.get("output_dir") or "").strip()
    request_data = payload.get("request") if isinstance(payload.get("request"), Mapping) else {}
    if not job_id or not metadata_output_dir or not request_data:
        return None
    max_heartbeat_age = max(
        300.0,
        _qwen_caption_dataset_request_float(request_data.get("runner_no_output_timeout_seconds"), default=0.0),
    )
    artifact_dir = Path(artifact_key)
    strict_audit_report = _qwen_caption_dataset_strict_audit(
        artifact_dir,
        request_data,
        max_heartbeat_age_seconds=max_heartbeat_age,
    )
    if str(strict_audit_report.get("status") or "").strip().lower() != "ok":
        return None
    result_data = dict(payload.get("result") if isinstance(payload.get("result"), Mapping) else {})
    result_data.update(
        {
            "output_dir": artifact_key,
            "processed": strict_audit_report.get("processed_cases"),
            "total_cases": strict_audit_report.get("expected_cases"),
            "failed": strict_audit_report.get("failed_cases"),
            "quality_failed": strict_audit_report.get("quality_failed_cases"),
            "degraded_rates": strict_audit_report.get("degraded_rates"),
            "strict_audit": strict_audit_report,
        }
    )
    summary_path = artifact_dir / "summary.json"
    if summary_path.exists():
        try:
            runner_summary = json.loads(summary_path.read_text())
            if isinstance(runner_summary, Mapping):
                result_data["runner_summary"] = dict(runner_summary)
                final_counts = _qwen_caption_dataset_result_summary_from_runner_summary(runner_summary)
                if final_counts:
                    result_data.update(final_counts)
        except Exception:
            pass
    job = QwenCaptionDatasetJob(job_id=job_id, output_dir=metadata_output_dir)
    job.status = "completed"
    job.progress = 1.0
    job.message = "Caption dataset job complete from existing artifacts"
    job.request = dict(request_data)
    job.result = result_data
    job.error = None
    job.created_at = _qwen_caption_dataset_request_float(payload.get("created_at"), default=time.time())
    job.logs = list(payload.get("logs") if isinstance(payload.get("logs"), list) else [])
    job.log_seq = max(
        [
            _qwen_caption_dataset_request_int(log.get("seq"), default=0)
            for log in job.logs
            if isinstance(log, Mapping)
        ]
        or [0]
    )
    _qwen_caption_dataset_job_log(
        job,
        "set-and-forget artifacts already completed; no auto-resume needed",
        artifact_dir=artifact_key,
        strict_audit_status="ok",
    )
    _persist_qwen_caption_dataset_job(job)
    return _serialize_qwen_caption_dataset_job(job)


def _qwen_caption_dataset_job_should_auto_resume(
    payload: Mapping[str, Any],
    *,
    suppress_hidden: bool = True,
) -> bool:
    if not bool(QWEN_CAPTION_SET_AND_FORGET_AUTO_RESUME):
        return False
    if suppress_hidden and _qwen_caption_dataset_job_hidden_reason(payload):
        return False
    if _qwen_caption_dataset_job_cancelled_by_user(payload):
        return False
    request_data = payload.get("request") if isinstance(payload.get("request"), Mapping) else {}
    if not request_data:
        return False
    if not _qwen_caption_dataset_request_bool(request_data.get("set_and_forget"), default=False):
        return False
    status = str(payload.get("status") or "").strip().lower()
    if status not in {"queued", "running", "interrupted", "failed"}:
        return False
    error = str(payload.get("error") or "").strip()
    if status == "interrupted" and not _qwen_caption_dataset_job_has_resume_evidence(payload):
        return False
    if status == "failed":
        if _qwen_caption_dataset_job_hard_resume_error(error):
            return False
        if error in {
            "caption_runner_preflight_failed",
            "caption_runner_pilot_required",
            "caption_runner_pilot_certification_failed",
            "caption_runner_backend_supervision_required",
        }:
            return False
        if (
            error != "caption_runner_no_output_timeout"
            and error != "caption_runner_degraded_rates"
            and error != "caption_runner_strict_audit_failed"
            and not error.startswith("caption_runner_exit_")
        ):
            return False
        if error == "caption_runner_strict_audit_failed" and _qwen_caption_dataset_job_has_jsonl_corruption(payload):
            return False
    output_dir = str(payload.get("output_dir") or "").strip()
    if not output_dir:
        return False
    auto_resume_count = _qwen_caption_dataset_request_int(request_data.get("auto_resume_count"), default=0)
    max_auto_resumes = _qwen_caption_dataset_job_auto_resume_limit(request_data)
    return max_auto_resumes > 0 and auto_resume_count < max_auto_resumes


def _qwen_caption_dataset_job_should_live_auto_resume(job: QwenCaptionDatasetJob) -> bool:
    status = str(job.status or "").strip().lower()
    if status != "failed":
        return False
    error = str(job.error or "").strip()
    if (
        error != "caption_runner_no_output_timeout"
        and error != "caption_runner_degraded_rates"
        and error != "caption_runner_strict_audit_failed"
        and not error.startswith("caption_runner_exit_")
    ):
        return False
    return _qwen_caption_dataset_job_should_auto_resume(
        _serialize_qwen_caption_dataset_job(job),
        suppress_hidden=False,
    )


def _resume_qwen_caption_dataset_job(
    job_id: str,
    *,
    auto_resume: bool = False,
) -> QwenCaptionDatasetJob:
    existing = _qwen_caption_dataset_serialized_job(job_id)
    status = str(existing.get("status") or "").strip().lower()
    if status in {"queued", "running"}:
        raise HTTPException(status_code=HTTP_409_CONFLICT, detail="qwen_caption_dataset_job_still_running")
    if _qwen_caption_dataset_job_cancelled_by_user(existing):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="qwen_caption_dataset_job_not_resumable:user_cancelled",
        )
    artifact_key = _qwen_caption_dataset_job_artifact_key(existing)
    if _qwen_caption_dataset_artifact_cancelled_by_persisted_owner(
        artifact_key,
        exclude_job_id=job_id,
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="qwen_caption_dataset_job_not_resumable:user_cancelled",
        )
    error = str(existing.get("error") or "").strip()
    if status == "failed" and _qwen_caption_dataset_job_hard_resume_error(error):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=f"qwen_caption_dataset_job_not_resumable:{error}",
        )
    if status == "interrupted" and not _qwen_caption_dataset_job_has_resume_evidence(existing):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="qwen_caption_dataset_job_not_resumable:interrupted_without_runner_evidence",
        )
    request_data = existing.get("request") if isinstance(existing.get("request"), Mapping) else {}
    if not request_data:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="qwen_caption_dataset_job_missing_request")
    output_dir = str(request_data.get("output_dir") or existing.get("output_dir") or "").strip()
    if not output_dir:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="qwen_caption_dataset_job_missing_output_dir")
    resume_request = dict(request_data)
    resume_request["resume"] = True
    resume_request["output_dir"] = output_dir
    if auto_resume:
        resume_request["auto_resume_count"] = (
            _qwen_caption_dataset_request_int(request_data.get("auto_resume_count"), default=0) + 1
        )
        policy = _qwen_caption_dataset_degraded_policy_from_payload(existing, terminal=True)
        if _qwen_caption_dataset_degraded_policy_reprocesses_recovery(policy):
            resume_request["resume_reprocess_recovery_events"] = True
    payload = QwenCaptionDatasetJobRequest(**resume_request)
    job = _start_qwen_caption_dataset_job(payload, force_default_output_dir=True)
    _qwen_caption_dataset_job_log(
        job,
        "auto-resumed caption dataset job" if auto_resume else "resumed caption dataset job",
        resumed_from_job_id=job_id,
        resumed_from_status=status or None,
        output_dir=output_dir,
        auto_resume=bool(auto_resume),
        auto_resume_count=payload.auto_resume_count,
    )
    _persist_qwen_caption_dataset_job(job)
    return job


def _qwen_caption_dataset_job_should_adopt_live_runner(
    payload: Mapping[str, Any],
    *,
    artifact_key: str,
    runner_lock: Mapping[str, Any],
) -> bool:
    if not bool(QWEN_CAPTION_SET_AND_FORGET_AUTO_RESUME):
        return False
    if not artifact_key or not bool(runner_lock.get("pid_alive")):
        return False
    if _qwen_caption_dataset_artifact_cancel_marker(artifact_key):
        return False
    if _qwen_caption_dataset_artifact_cancelled_by_persisted_owner(artifact_key):
        return False
    request_data = payload.get("request") if isinstance(payload.get("request"), Mapping) else {}
    if not request_data:
        return False
    if _qwen_caption_dataset_job_cancelled_by_user(payload):
        return False
    if not _qwen_caption_dataset_request_bool(request_data.get("set_and_forget"), default=False):
        return False
    if not str(payload.get("job_id") or "").strip() or not str(payload.get("output_dir") or "").strip():
        return False
    status = str(payload.get("status") or "").strip().lower()
    if status in {"queued", "running", "interrupted"}:
        return True
    if status == "failed":
        return _qwen_caption_dataset_job_should_auto_resume(payload)
    return False


def _qwen_caption_dataset_adopted_audit_message(
    audit: Mapping[str, Any],
    *,
    runner_lock: Mapping[str, Any],
) -> str:
    expected = _qwen_caption_dataset_request_int(audit.get("expected_cases"), default=0)
    processed = _qwen_caption_dataset_request_int(audit.get("processed_cases"), default=0)
    heartbeat = audit.get("heartbeat") if isinstance(audit.get("heartbeat"), Mapping) else {}
    heartbeat_status = str(heartbeat.get("status") or "").strip() or "unknown"
    phase = str(heartbeat.get("phase") or "").strip().replace("_", " ")
    pid = runner_lock.get("pid") or heartbeat.get("pid")
    if expected > 0:
        base = f"Adopted running caption worker; {processed}/{expected} complete"
    else:
        base = "Adopted running caption worker"
    details = []
    if pid:
        details.append(f"pid {pid}")
    if heartbeat_status:
        details.append(f"status {heartbeat_status}")
    if phase:
        details.append(f"phase {phase}")
    return f"{base} ({', '.join(details)})" if details else base


def _qwen_caption_dataset_apply_adopted_live_audit(
    job: QwenCaptionDatasetJob,
    *,
    artifact_key: str,
    audit: Mapping[str, Any],
    runner_lock: Mapping[str, Any],
) -> None:
    result_data = dict(job.result or {})
    expected = _qwen_caption_dataset_request_int(audit.get("expected_cases"), default=0)
    processed = _qwen_caption_dataset_request_int(audit.get("processed_cases"), default=0)
    failed = _qwen_caption_dataset_request_int(audit.get("failed_cases"), default=0)
    quality_failed = _qwen_caption_dataset_request_int(audit.get("quality_failed_cases"), default=0)
    heartbeat = audit.get("heartbeat") if isinstance(audit.get("heartbeat"), Mapping) else {}
    result_data.update(
        {
            "adopted_live_runner": True,
            "adopted_live_runner_at": result_data.get("adopted_live_runner_at") or time.time(),
            "adopted_runner_lock": dict(runner_lock),
            "live_audit": dict(audit),
            "output_dir": artifact_key,
            "processed": processed,
            "total_cases": expected or result_data.get("total_cases") or 0,
            "failed": failed,
            "quality_failed": quality_failed,
            "degraded_rates": audit.get("degraded_rates") or result_data.get("degraded_rates") or {},
        }
    )
    if heartbeat:
        result_data["runner_heartbeat"] = dict(heartbeat)
    job.status = "running"
    if expected > 0:
        job.progress = max(0.0, min(0.999, processed / float(max(1, expected))))
    job.message = _qwen_caption_dataset_adopted_audit_message(
        audit,
        runner_lock=runner_lock,
    )
    job.result = result_data
    job.updated_at = time.time()


def _qwen_caption_dataset_finalize_adopted_live_runner(
    job: QwenCaptionDatasetJob,
    *,
    artifact_key: str,
    request_data: Mapping[str, Any],
    max_heartbeat_age_seconds: float,
) -> None:
    artifact_dir = Path(artifact_key)
    strict_audit_report = _qwen_caption_dataset_strict_audit(
        artifact_dir,
        request_data,
        max_heartbeat_age_seconds=max_heartbeat_age_seconds,
    )
    result_data = dict(job.result or {})
    result_data["strict_audit"] = strict_audit_report
    result_data["output_dir"] = artifact_key
    summary_path = artifact_dir / "summary.json"
    if summary_path.exists():
        try:
            runner_summary = json.loads(summary_path.read_text())
            if isinstance(runner_summary, Mapping):
                result_data["runner_summary"] = dict(runner_summary)
                final_counts = _qwen_caption_dataset_result_summary_from_runner_summary(runner_summary)
                if final_counts:
                    result_data.update(final_counts)
        except Exception:
            pass
    if str(strict_audit_report.get("status") or "").strip().lower() == "ok":
        result_data.update(
            {
                "processed": strict_audit_report.get("processed_cases"),
                "total_cases": strict_audit_report.get("expected_cases"),
                "failed": strict_audit_report.get("failed_cases"),
                "quality_failed": strict_audit_report.get("quality_failed_cases"),
                "degraded_rates": strict_audit_report.get("degraded_rates"),
            }
        )
        job.status = "completed"
        job.progress = 1.0
        job.error = None
        job.message = "Caption dataset job complete from adopted runner"
    else:
        failed_checks = [
            check
            for check in (strict_audit_report.get("checks") or [])
            if isinstance(check, Mapping) and str(check.get("status") or "").lower() != "ok"
        ]
        first_detail = str(failed_checks[0].get("detail") if failed_checks else "strict artifact audit failed")
        job.status = "failed"
        job.error = "caption_runner_strict_audit_failed"
        job.message = f"Adopted caption runner stopped before a valid terminal artifact: {first_detail}"
    job.result = result_data
    job.updated_at = time.time()
    _persist_qwen_caption_dataset_job(job)


def _monitor_adopted_qwen_caption_dataset_runner(
    job: QwenCaptionDatasetJob,
    request_data: Mapping[str, Any],
    artifact_key: str,
) -> None:
    request_data = dict(request_data or {})
    max_heartbeat_age = max(
        300.0,
        _qwen_caption_dataset_request_float(
            request_data.get("runner_no_output_timeout_seconds"),
            default=0.0,
        ),
    )
    poll_seconds = max(0.5, float(QWEN_CAPTION_SET_AND_FORGET_ADOPTION_POLL_SECONDS or 0.0))
    artifact_dir = Path(artifact_key)
    try:
        _qwen_caption_dataset_job_log(
            job,
            "adopted live set-and-forget caption runner",
            artifact_dir=artifact_key,
        )
        while not job.cancel_event.is_set():
            runner_lock = _qwen_caption_dataset_artifact_runner_lock(artifact_key)
            audit = _qwen_caption_dataset_live_audit(
                artifact_dir,
                request_data,
                max_heartbeat_age_seconds=max_heartbeat_age,
            )
            _qwen_caption_dataset_apply_adopted_live_audit(
                job,
                artifact_key=artifact_key,
                audit=audit,
                runner_lock=runner_lock,
            )
            _persist_qwen_caption_dataset_job(job)
            heartbeat = audit.get("heartbeat") if isinstance(audit.get("heartbeat"), Mapping) else {}
            heartbeat_status = str(heartbeat.get("status") or "").strip().lower()
            lock_alive = bool(runner_lock.get("pid_alive"))
            if heartbeat_status in {"completed", "failed"} or not lock_alive:
                _qwen_caption_dataset_finalize_adopted_live_runner(
                    job,
                    artifact_key=artifact_key,
                    request_data=request_data,
                    max_heartbeat_age_seconds=max_heartbeat_age,
                )
                return
            job.cancel_event.wait(poll_seconds)
        job.status = "cancelled"
        job.message = "Cancelled"
    except Exception as exc:  # noqa: BLE001
        logger.exception("Adopted Qwen caption dataset runner monitor %s failed", job.job_id)
        job.status = "failed"
        job.error = str(exc)
        job.message = "Adopted caption runner monitor failed"
    finally:
        job.process = None
        job.updated_at = time.time()
        _persist_qwen_caption_dataset_job(job)
        _qwen_caption_dataset_live_auto_resume_after_failure(job)


def _adopt_live_qwen_caption_dataset_job(
    payload: Mapping[str, Any],
    *,
    artifact_key: str,
    runner_lock: Mapping[str, Any],
) -> Optional[QwenCaptionDatasetJob]:
    if not _qwen_caption_dataset_job_should_adopt_live_runner(
        payload,
        artifact_key=artifact_key,
        runner_lock=runner_lock,
    ):
        return None
    job_id = str(payload.get("job_id") or "").strip()
    metadata_output_dir = str(payload.get("output_dir") or "").strip()
    request_data = payload.get("request") if isinstance(payload.get("request"), Mapping) else {}
    if not job_id or not metadata_output_dir or not request_data:
        return None
    with QWEN_CAPTION_DATASET_JOBS_LOCK:
        existing = QWEN_CAPTION_DATASET_JOBS.get(job_id)
    if existing is not None:
        return existing
    job = QwenCaptionDatasetJob(job_id=job_id, output_dir=metadata_output_dir)
    job.status = "queued"
    job.progress = _qwen_caption_dataset_request_float(payload.get("progress"), default=0.0)
    job.message = "Adopting live set-and-forget caption runner"
    job.request = dict(request_data)
    job.result = dict(payload.get("result") if isinstance(payload.get("result"), Mapping) else {})
    job.error = None
    job.created_at = _qwen_caption_dataset_request_float(payload.get("created_at"), default=time.time())
    job.logs = list(payload.get("logs") if isinstance(payload.get("logs"), list) else [])
    job.log_seq = max(
        [
            _qwen_caption_dataset_request_int(log.get("seq"), default=0)
            for log in job.logs
            if isinstance(log, Mapping)
        ]
        or [0]
    )
    _register_job_and_start_thread(
        job=job,
        registry=QWEN_CAPTION_DATASET_JOBS,
        lock=QWEN_CAPTION_DATASET_JOBS_LOCK,
        target=_monitor_adopted_qwen_caption_dataset_runner,
        args=(job, dict(request_data), artifact_key),
        name=f"qwen-caption-adopt-{job_id}",
    )
    return job


def _iter_persisted_qwen_caption_dataset_job_payloads() -> List[Dict[str, Any]]:
    payloads: List[Dict[str, Any]] = []
    try:
        children = sorted(
            [child for child in QWEN_CAPTION_DATASET_JOB_ROOT.iterdir() if child.is_dir()],
            key=lambda child: child.stat().st_mtime,
            reverse=True,
        )
    except Exception:
        return payloads
    for child in children:
        payload = _load_qwen_caption_dataset_job_payload(child.name)
        if isinstance(payload, dict):
            payloads.append(payload)
    return payloads


def _qwen_caption_dataset_load_discovery_summary(
    child: Path,
) -> Optional[Dict[str, Any]]:
    """Load a compact, stat-invalidated summary, migrating legacy jobs once."""

    job_path = child / "job.json"
    try:
        job_stat = job_path.stat()
    except OSError:
        return None
    summary_path = child / QWEN_CAPTION_DATASET_DISCOVERY_FILENAME
    try:
        envelope = json.loads(summary_path.read_text())
        if (
            isinstance(envelope, dict)
            and envelope.get("schema") == "qwen-caption-job-discovery-v2"
            and int(envelope.get("job_json_size") or -1)
            == int(job_stat.st_size)
            and int(envelope.get("job_json_mtime_ns") or -1)
            == int(job_stat.st_mtime_ns)
            and isinstance(envelope.get("payload"), dict)
        ):
            payload = dict(envelope["payload"])
        else:
            payload = {}
    except Exception:
        payload = {}
    if not payload:
        full_payload = _load_qwen_caption_dataset_job_payload(child.name)
        if not isinstance(full_payload, dict):
            return None
        payload = _qwen_caption_dataset_compact_discovery_payload(full_payload)
        _qwen_caption_dataset_write_discovery_summary(child, full_payload)
    if str(payload.get("status") or "") in {"queued", "running"}:
        payload["status"] = "interrupted"
        payload["message"] = "Interrupted while backend was not tracking the job"
    return payload


def _iter_persisted_qwen_caption_dataset_job_summaries() -> Iterator[Dict[str, Any]]:
    try:
        children = sorted(
            (
                child
                for child in QWEN_CAPTION_DATASET_JOB_ROOT.iterdir()
                if child.is_dir()
            ),
            key=lambda child: child.stat().st_mtime,
            reverse=True,
        )
    except Exception:
        return
    for child in children:
        payload = _qwen_caption_dataset_load_discovery_summary(child)
        if isinstance(payload, dict):
            yield payload


def _auto_resume_qwen_caption_dataset_jobs() -> List[Dict[str, Any]]:
    if not _QWEN_CAPTION_SET_AND_FORGET_AUTO_RESUME_LOCK.acquire(blocking=False):
        return []
    try:
        with QWEN_CAPTION_DATASET_JOBS_LOCK:
            live_jobs = [_serialize_qwen_caption_dataset_job(job) for job in QWEN_CAPTION_DATASET_JOBS.values()]
        live_artifacts = {
            _qwen_caption_dataset_job_artifact_key(job)
            for job in live_jobs
            if _qwen_caption_dataset_job_is_active_artifact_owner(job)
        }
        live_artifacts.discard("")
        latest_by_artifact: Dict[str, Dict[str, Any]] = {}
        cancelled_artifacts: Set[str] = set()
        for payload in _iter_persisted_qwen_caption_dataset_job_summaries():
            if _qwen_caption_dataset_job_hidden_reason(payload):
                continue
            if _qwen_caption_dataset_job_cancelled_by_user(payload):
                cancelled_key = _qwen_caption_dataset_job_artifact_key(payload)
                if cancelled_key:
                    cancelled_artifacts.add(cancelled_key)
                continue
            artifact_key = _qwen_caption_dataset_job_artifact_key(payload)
            if not artifact_key or artifact_key in live_artifacts:
                continue
            current = latest_by_artifact.get(artifact_key)
            if current is None or _qwen_caption_dataset_job_sort_value(payload) > _qwen_caption_dataset_job_sort_value(current):
                latest_by_artifact[artifact_key] = payload

        resumed: List[Dict[str, Any]] = []
        for summary_payload in sorted(
            latest_by_artifact.values(),
            key=_qwen_caption_dataset_job_sort_value,
            reverse=True,
        ):
            artifact_key = _qwen_caption_dataset_job_artifact_key(
                summary_payload
            )
            if artifact_key in cancelled_artifacts:
                continue
            runner_lock = _qwen_caption_dataset_artifact_runner_lock(artifact_key)
            should_adopt = bool(runner_lock.get("pid_alive"))
            should_resume = _qwen_caption_dataset_job_should_auto_resume(
                summary_payload
            )
            if not should_adopt and not should_resume:
                continue
            job_id = str(summary_payload.get("job_id") or "").strip()
            if not job_id:
                continue
            payload = _load_qwen_caption_dataset_job_payload(job_id)
            if not isinstance(payload, dict):
                continue
            if _qwen_caption_dataset_job_hidden_reason(payload):
                continue
            if _qwen_caption_dataset_job_cancelled_by_user(payload):
                continue
            if runner_lock.get("pid_alive"):
                adopted = _adopt_live_qwen_caption_dataset_job(
                    payload,
                    artifact_key=artifact_key,
                    runner_lock=runner_lock,
                )
                if adopted is not None:
                    resumed.append(_serialize_qwen_caption_dataset_job(adopted))
                continue
            reconciled = _qwen_caption_dataset_reconcile_completed_artifact(payload, artifact_key=artifact_key)
            if reconciled is not None:
                continue
            if not _qwen_caption_dataset_job_should_auto_resume(payload):
                continue
            try:
                job = _resume_qwen_caption_dataset_job(job_id, auto_resume=True)
            except Exception:
                logger.exception("Failed to auto-resume Qwen caption dataset job %s", job_id)
                continue
            resumed.append(_serialize_qwen_caption_dataset_job(job))
        return resumed
    finally:
        _QWEN_CAPTION_SET_AND_FORGET_AUTO_RESUME_LOCK.release()


def _qwen_caption_set_and_forget_auto_resume_sweep_once(reason: str) -> List[Dict[str, Any]]:
    resumed = _auto_resume_qwen_caption_dataset_jobs()
    if resumed:
        logger.info(
            "Auto-resumed %d set-and-forget Qwen caption dataset job(s) during %s sweep",
            len(resumed),
            reason,
        )
    return resumed


def _startup_auto_resume_qwen_caption_dataset_jobs() -> None:
    global _QWEN_CAPTION_SET_AND_FORGET_STARTUP_DONE
    if not bool(QWEN_CAPTION_SET_AND_FORGET_AUTO_RESUME):
        return
    with _QWEN_CAPTION_SET_AND_FORGET_STARTUP_LOCK:
        if _QWEN_CAPTION_SET_AND_FORGET_STARTUP_DONE:
            return
        _QWEN_CAPTION_SET_AND_FORGET_STARTUP_DONE = True

    def _run() -> None:
        _qwen_caption_set_and_forget_auto_resume_sweep_once("startup")
        interval = max(0.0, float(QWEN_CAPTION_SET_AND_FORGET_SWEEP_INTERVAL_SECONDS or 0.0))
        while interval > 0 and not _QWEN_CAPTION_SET_AND_FORGET_SWEEPER_STOP.wait(interval):
            _qwen_caption_set_and_forget_auto_resume_sweep_once("periodic")

    threading.Thread(
        target=_run,
        name="qwen-caption-set-and-forget-auto-resume",
        daemon=True,
    ).start()


def startup_qwen_caption_set_and_forget_jobs() -> None:
    _startup_auto_resume_qwen_caption_dataset_jobs()


app.router.on_startup.append(startup_qwen_caption_set_and_forget_jobs)


def _get_qwen_caption_dataset_job(job_id: str) -> QwenCaptionDatasetJob:
    with QWEN_CAPTION_DATASET_JOBS_LOCK:
        job = QWEN_CAPTION_DATASET_JOBS.get(job_id)
    if not job:
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="qwen_caption_dataset_job_not_found")
    return job


def register_dataset_path(
    path: str,
    dataset_id: Optional[str],
    label: Optional[str],
    context: Optional[str],
    notes: Optional[str],
    force_new: Optional[bool] = None,
    strict: Optional[bool] = None,
):
    dataset_root = _validate_linked_dataset_path(path)
    _validate_linked_dataset_shape(dataset_root, strict=bool(strict is None or strict))
    source_signature = _compute_dir_signature_impl(dataset_root)
    if not bool(force_new):
        for candidate in _list_all_datasets():
            if str(candidate.get("storage_mode") or "").strip().lower() != "linked":
                continue
            linked_root_raw = str(candidate.get("linked_root") or "").strip()
            if linked_root_raw:
                try:
                    if Path(linked_root_raw).expanduser().resolve() == dataset_root:
                        return candidate
                except Exception:
                    pass
            if (
                source_signature
                and str(candidate.get("signature") or "").strip() == source_signature
            ):
                return candidate
    base_id = _sanitize_yolo_run_id_impl(dataset_id or dataset_root.name) or "linked_dataset"
    registry_root = _dataset_registry_storage_root(
        create=True, detail="dataset_register_target_invalid"
    )
    dataset_id_final = _unique_dataset_name(base_id, root=registry_root)
    registry_dir = _dataset_registry_child_dir(
        dataset_id_final, detail="dataset_register_target_invalid"
    )
    if registry_dir.exists() or registry_dir.is_symlink():
        raise HTTPException(status_code=HTTP_409_CONFLICT, detail="dataset_register_target_exists")
    try:
        registry_dir.mkdir(parents=True, exist_ok=True)
        meta = _build_linked_dataset_metadata(
            dataset_id=dataset_id_final,
            dataset_root=dataset_root,
            label=label,
            context=context,
            notes=notes,
        )
        meta["signature"] = source_signature
        _write_dataset_metadata_json(registry_dir / DATASET_META_NAME, registry_dir, meta)
        entry = _resolve_dataset_entry_impl(dataset_id_final, list_all_datasets_fn=_list_all_datasets)
        if not entry:
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR, detail="dataset_register_failed"
            )
        return entry
    except Exception:
        try:
            _delete_dataset_tree_or_link(registry_dir, [registry_root])
        except Exception:
            pass
        raise


def _transient_session_state_storage_root(*, create: bool = True) -> Path:
    try:
        raw_root = Path(DATASET_TRANSIENT_STATE_ROOT)
        if _storage_path_has_symlink_component(raw_root):
            raise ValueError("transient state root has a symlink component")
        if create:
            raw_root.mkdir(parents=True, exist_ok=True)
        if _storage_path_has_symlink_component(raw_root):
            raise ValueError("transient state root has a symlink component")
        if raw_root.exists() and not raw_root.is_dir():
            raise ValueError("transient state root is not a directory")
        return raw_root.resolve(strict=False)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="transient_session_state_root_invalid",
        ) from exc


def _transient_session_state_path(session_id: str, *, create_root: bool = True) -> Path:
    sid = str(session_id or "").strip()
    if not sid:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="transient_session_required",
        )
    root = _transient_session_state_storage_root(create=create_root)
    digest = hashlib.sha256(sid.encode("utf-8")).hexdigest()
    path = root / f"{digest}.json"
    # The filename is a digest and the parent is already resolved/guarded.
    # Do not resolve the leaf here: an attacker-controlled symlink leaf must
    # reach the no-follow reader so it can be quarantined without touching its
    # target.
    if path.parent != root:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="transient_session_state_path_invalid",
        )
    return path


def _fsync_directory(path: Path) -> None:
    flags = os.O_RDONLY
    if hasattr(os, "O_DIRECTORY"):
        flags |= os.O_DIRECTORY
    fd = os.open(path, flags)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def _quarantine_invalid_transient_state_locked(path: Path) -> Optional[Path]:
    root = _transient_session_state_storage_root(create=True)
    if path.parent.resolve(strict=False) != root or not (path.exists() or path.is_symlink()):
        return None
    invalid_root = root / ".invalid"
    if invalid_root.is_symlink() or _storage_path_has_symlink_component(invalid_root):
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="transient_session_state_quarantine_invalid",
        )
    invalid_root.mkdir(parents=True, exist_ok=True)
    if invalid_root.is_symlink() or not invalid_root.is_dir():
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="transient_session_state_quarantine_invalid",
        )
    destination = invalid_root / (
        f"{path.name}.{int(time.time() * 1000)}.{uuid.uuid4().hex[:8]}.invalid"
    )
    os.replace(path, destination)
    _fsync_directory(invalid_root)
    _fsync_directory(root)
    logger.error("Quarantined invalid transient annotation state at %s", destination)
    return destination


def _transient_session_state_read_path_locked(path: Path) -> Optional[Dict[str, Any]]:
    try:
        root = _transient_session_state_storage_root(create=True)
        if path.parent.resolve(strict=False) != root:
            return None
        if path.is_symlink() or not path.exists() or not path.is_file():
            return None
        flags = os.O_RDONLY
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        fd = os.open(path, flags)
        try:
            info = os.fstat(fd)
            if not stat.S_ISREG(info.st_mode):
                return None
            if info.st_size < 2 or info.st_size > DATASET_TRANSIENT_STATE_MAX_BYTES:
                return None
            with os.fdopen(fd, "r", encoding="utf-8") as handle:
                fd = -1
                payload = json.load(handle)
        finally:
            if fd >= 0:
                os.close(fd)
        if not isinstance(payload, dict):
            return None
        if int(payload.get("_state_schema_version") or 0) != DATASET_TRANSIENT_STATE_SCHEMA_VERSION:
            return None
        sid = str(payload.get("session_id") or "").strip()
        if not sid:
            return None
        try:
            expires_at = float(payload.get("expires_at"))
            int(payload.get("_state_revision") or 0)
        except Exception:
            return None
        if not math.isfinite(expires_at):
            return None
        expected = _transient_session_state_path(sid, create_root=True)
        if expected.name != path.name:
            return None
        if not str(payload.get("dataset_root") or "").strip():
            return None
        return payload
    except HTTPException:
        raise
    except Exception:
        logger.warning("Ignoring invalid transient annotation state file %s", path)
        return None


def _transient_session_state_load_locked(session_id: str) -> Optional[Dict[str, Any]]:
    path = _transient_session_state_path(session_id, create_root=True)
    payload = _transient_session_state_read_path_locked(path)
    if payload is None and (path.exists() or path.is_symlink()):
        _quarantine_invalid_transient_state_locked(path)
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="transient_session_state_invalid",
        )
    if payload is None:
        return None
    if str(payload.get("session_id") or "").strip() != str(session_id or "").strip():
        return None
    return payload


def _transient_session_state_write_locked(
    session_id: str,
    session: Dict[str, Any],
) -> Dict[str, Any]:
    sid = str(session_id or "").strip()
    path = _transient_session_state_path(sid, create_root=True)
    root = path.parent.resolve(strict=True)
    stored = dict(session or {})
    stored["session_id"] = sid
    stored["_state_schema_version"] = DATASET_TRANSIENT_STATE_SCHEMA_VERSION
    stored["_state_persisted_at"] = time.time()
    encoded = json.dumps(stored, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
    if len(encoded) > DATASET_TRANSIENT_STATE_MAX_BYTES:
        raise HTTPException(status_code=413, detail="transient_session_state_too_large")
    tmp_path = root / f".{path.name}.{uuid.uuid4().hex}.tmp"
    try:
        if path.is_symlink():
            raise ValueError("transient state target is a symlink")
        if path.exists() and not path.is_file():
            raise ValueError("transient state target is not a file")
        if tmp_path.is_symlink() or tmp_path.exists():
            raise ValueError("transient state temporary target already exists")
        for candidate in (path, tmp_path):
            resolved = candidate.resolve(strict=False)
            if resolved.parent != root or not _path_is_within_root_impl(resolved, root):
                raise ValueError("transient state target escapes root")
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        fd = os.open(tmp_path, flags, 0o600)
        with os.fdopen(fd, "wb") as handle:
            handle.write(encoded)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
        _fsync_directory(root)
        return stored
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="transient_session_persist_failed",
        ) from exc
    finally:
        try:
            if tmp_path.exists() or tmp_path.is_symlink():
                tmp_path.unlink(missing_ok=True)
        except OSError:
            pass


def _transient_session_state_delete_locked(session_id: str) -> None:
    path = _transient_session_state_path(session_id, create_root=True)
    try:
        if path.is_symlink() or path.is_file():
            path.unlink(missing_ok=True)
            _fsync_directory(path.parent)
    except OSError as exc:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="transient_session_state_delete_failed",
        ) from exc


def _purge_expired_transient_sessions(
    now_ts: Optional[float] = None,
    *,
    include_persisted: bool = True,
) -> int:
    now = float(now_ts) if now_ts is not None else time.time()
    removed_ids: Set[str] = set()
    with DATASET_TRANSIENT_LOCK:
        stale_ids: List[str] = []
        invalid_ids: List[str] = []
        for sid, session in DATASET_TRANSIENT_SESSIONS.items():
            expires_raw = session.get("expires_at")
            try:
                expires_at = float(expires_raw)
            except Exception:
                invalid_ids.append(sid)
                continue
            if expires_at <= now:
                stale_ids.append(sid)
        for sid in invalid_ids:
            session = DATASET_TRANSIENT_SESSIONS.pop(sid, None) or {}
            if _transient_session_is_durable(session):
                path = _transient_session_state_path(sid, create_root=True)
                if path.exists() or path.is_symlink():
                    _quarantine_invalid_transient_state_locked(path)
            logger.error("Discarded invalid in-memory transient session expiry for %s", sid)
        for sid in stale_ids:
            DATASET_TRANSIENT_SESSIONS.pop(sid, None)
            # expires_at is an active in-memory lease, not user-data
            # retention. The durable overlay remains available for lazy
            # resume with its opaque session id.
            removed_ids.add(sid)

        if include_persisted:
            root = _transient_session_state_storage_root(create=True)
            for path in root.iterdir():
                if path.name.endswith(".tmp"):
                    if path.is_symlink() or path.is_file():
                        path.unlink(missing_ok=True)
                        _fsync_directory(root)
                    continue
                if path.suffix.lower() != ".json":
                    continue
                payload = _transient_session_state_read_path_locked(path)
                if payload is None:
                    if path.is_symlink() or path.is_file():
                        _quarantine_invalid_transient_state_locked(path)
                    continue
                sid = str(payload.get("session_id") or "").strip()
                try:
                    expires_at = float(payload.get("expires_at"))
                except Exception:
                    _quarantine_invalid_transient_state_locked(path)
                    DATASET_TRANSIENT_SESSIONS.pop(sid, None)
                    continue
                if expires_at <= now:
                    # Leave expired durable state in place. Lazy access clears
                    # the stale lock and renews the lease; only explicit Delete
                    # hard-removes acknowledged annotation state.
                    DATASET_TRANSIENT_SESSIONS.pop(sid, None)
                    removed_ids.add(sid)
    return len(removed_ids)


def open_dataset_path(path: str, strict: Optional[bool] = None):
    _purge_expired_transient_sessions()
    dataset_root = _validate_linked_dataset_path(path)
    layout = _validate_linked_dataset_shape(dataset_root, strict=bool(strict is None or strict))
    session_id = uuid.uuid4().hex
    classes = _dataset_labelmap_from_root(dataset_root)
    label = dataset_root.name
    now = time.time()
    expires_at = now + float(DATASET_TRANSIENT_SESSION_TTL_SECONDS)
    with DATASET_TRANSIENT_LOCK:
        session = {
            "session_id": session_id,
            "dataset_root": str(dataset_root),
            "label": label,
            "classes": classes,
            "yolo_layout": layout.get("yolo_layout") or "flat",
            "created_at": now,
            "updated_at": now,
            "expires_at": expires_at,
            "annotation_status": "new",
            "annotation_notes": "",
            "annotation_cursor": None,
            "annotation_progress": {},
            "annotation_lock": {},
            "overlay_labels": {},
            "overlay_text": {},
            "_state_revision": 0,
        }
        session = _transient_session_state_write_locked(session_id, session)
        DATASET_TRANSIENT_SESSIONS[session_id] = session
    return {
        "session_id": session_id,
        "expires_at": expires_at,
        "session_revision": int(session.get("_state_revision") or 0),
        "dataset": {
            "id": f"transient:{session_id}",
            "label": label,
            "dataset_root": str(dataset_root),
            "storage_mode": "transient",
            "classes": classes,
            "yolo_layout": layout.get("yolo_layout") or "flat",
        },
    }


def _transient_session_is_durable(session: Mapping[str, Any]) -> bool:
    try:
        return (
            int(session.get("_state_schema_version") or 0)
            == DATASET_TRANSIENT_STATE_SCHEMA_VERSION
        )
    except Exception:
        return False


def _resolve_transient_session_locked(
    session_id: str,
    *,
    now: float,
    touch: bool = True,
) -> Dict[str, Any]:
    sid = str(session_id or "").strip()
    session = DATASET_TRANSIENT_SESSIONS.get(sid)
    restored = False
    if not session:
        session = _transient_session_state_load_locked(sid)
        if session:
            restored = True
        else:
            raise HTTPException(
                status_code=HTTP_404_NOT_FOUND,
                detail="transient_session_not_found",
            )
    session = copy.deepcopy(session)
    try:
        expires_at = float(session.get("expires_at"))
    except Exception:
        if _transient_session_is_durable(session):
            DATASET_TRANSIENT_SESSIONS.pop(sid, None)
            path = _transient_session_state_path(sid, create_root=True)
            if path.exists() or path.is_symlink():
                _quarantine_invalid_transient_state_locked(path)
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                detail="transient_session_state_invalid",
            )
        expires_at = now + float(DATASET_TRANSIENT_SESSION_TTL_SECONDS)
    resumed_after_expiry = expires_at <= now
    if resumed_after_expiry:
        # Lease expiry releases the stale editor lock, but never destroys
        # acknowledged labels/text/cursor state. Possession of the opaque
        # session id can lazily resume the same transient overlay.
        session["annotation_lock"] = {}
        session["resumed_after_expiry_at"] = now
    if not touch:
        return copy.deepcopy(session)
    session["updated_at"] = now
    session["expires_at"] = now + float(DATASET_TRANSIENT_SESSION_TTL_SECONDS)
    if resumed_after_expiry:
        try:
            session["_state_revision"] = int(session.get("_state_revision") or 0) + 1
        except Exception:
            session["_state_revision"] = 1
    try:
        persisted_at = float(session.get("_state_persisted_at") or 0.0)
    except Exception:
        persisted_at = 0.0
    if restored or resumed_after_expiry or (
        _transient_session_is_durable(session)
        and now - persisted_at >= DATASET_TRANSIENT_STATE_REFRESH_SECONDS
    ):
        session = _transient_session_state_write_locked(sid, session)
    DATASET_TRANSIENT_SESSIONS[sid] = session
    return copy.deepcopy(session)


def _resolve_transient_session(session_id: str) -> Dict[str, Any]:
    sid = str(session_id or "").strip()
    if not sid:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="transient_session_required")
    now = time.time()
    with DATASET_TRANSIENT_LOCK:
        session = _resolve_transient_session_locked(sid, now=now)
    _purge_expired_transient_sessions(now_ts=now, include_persisted=False)
    return session


def _class_analysis_snapshot_record_identity(record: Mapping[str, Any]) -> str:
    """Bind an internal transient session to one immutable snapshot record."""

    images: List[Dict[str, str]] = []
    for raw in record.get("images") or []:
        if not isinstance(raw, Mapping):
            return ""
        relpath = str(raw.get("image_relpath") or "").strip()
        sha256 = str(raw.get("image_sha256") or "").strip().lower()
        if not relpath or re.fullmatch(r"[0-9a-f]{64}", sha256) is None:
            return ""
        images.append({"image_relpath": relpath, "image_sha256": sha256})
    if not images:
        return ""
    payload = {
        "snapshot_id": str(record.get("snapshot_id") or "").strip(),
        "workspace_dir": str(record.get("workspace_dir") or "").strip(),
        "labelmap": [str(value or "") for value in (record.get("labelmap") or [])],
        "images": sorted(
            images,
            key=lambda row: (row["image_relpath"], row["image_sha256"]),
        ),
    }
    return hashlib.sha256(
        json.dumps(
            payload,
            ensure_ascii=True,
            separators=(",", ":"),
            sort_keys=True,
        ).encode("utf-8")
    ).hexdigest()


def _transient_session_dataset_root(session: Mapping[str, Any]) -> Path:
    """Resolve ordinary roots normally and snapshot roots through their registry."""

    if str(session.get("source_kind") or "") != "class_analysis_snapshot":
        return _validate_linked_dataset_path(str(session.get("dataset_root") or ""))
    snapshot_id = str(session.get("class_analysis_snapshot_id") or "").strip()
    expected_identity = str(
        session.get("class_analysis_snapshot_identity") or ""
    ).strip()
    if not snapshot_id or not expected_identity:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="class_analysis_annotation_source_identity_missing",
        )
    with CLASS_ANALYSIS_ACTIVE_SNAPSHOTS_LOCK:
        record = CLASS_ANALYSIS_ACTIVE_SNAPSHOTS.get(snapshot_id)
        if not isinstance(record, Mapping):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="class_analysis_annotation_source_snapshot_missing",
            )
        observed_identity = str(record.get("_annotation_source_identity") or "").strip()
        if not observed_identity:
            observed_identity = _class_analysis_snapshot_record_identity(record)
            if observed_identity and isinstance(record, dict):
                record["_annotation_source_identity"] = observed_identity
        workspace_value = str(record.get("workspace_dir") or "").strip()
    if not observed_identity or observed_identity != expected_identity:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="class_analysis_annotation_source_snapshot_changed",
        )
    try:
        workspace = Path(workspace_value).resolve(strict=True)
        stored_root = Path(str(session.get("dataset_root") or "")).resolve(strict=True)
        class_root = CLASS_ANALYSIS_ROOT.resolve(strict=True)
    except Exception as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="class_analysis_annotation_source_missing",
        ) from exc
    if (
        workspace != stored_root
        or not workspace.is_dir()
        or _storage_path_has_symlink_component(workspace)
        or not _path_is_within_root_impl(workspace, class_root)
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="class_analysis_annotation_source_changed",
        )
    return workspace


def _transient_session_annotation_source_root(
    session: Mapping[str, Any],
    dataset_root: Path,
) -> Path:
    if str(session.get("source_kind") or "") != "class_analysis_snapshot":
        return dataset_root
    job_id = str(session.get("class_analysis_job_id") or "").strip()
    source_value = str(
        session.get("class_analysis_annotation_source_root") or ""
    ).strip()
    if not job_id or not source_value:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="class_analysis_annotation_source_identity_missing",
        )
    try:
        job_root = _class_analysis_job_dir(job_id).resolve(strict=True)
        source_root = Path(source_value).resolve(strict=True)
        expected_root = (job_root / "annotation_source").resolve(strict=True)
    except Exception as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="class_analysis_annotation_source_missing",
        ) from exc
    if (
        source_root != expected_root
        or source_root.is_symlink()
        or not source_root.is_dir()
        or _storage_path_has_symlink_component(source_root)
        or not _path_is_within_root_impl(source_root, job_root)
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="class_analysis_annotation_source_changed",
        )
    return source_root


def _mutate_transient_session(
    session_id: str,
    mutate_fn: Callable[[Dict[str, Any]], Any],
    *,
    expected_revision: Optional[int] = None,
    increment_revision: bool = True,
    persist: bool = True,
) -> Tuple[Dict[str, Any], Any, bool]:
    sid = str(session_id or "").strip()
    if not sid:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="transient_session_required")
    with DATASET_TRANSIENT_LOCK:
        current = _resolve_transient_session_locked(sid, now=time.time(), touch=False)
        try:
            current_revision = int(current.get("_state_revision") or 0)
        except Exception:
            current_revision = 0
        if expected_revision is not None and current_revision != int(expected_revision):
            return current, None, False
        working = copy.deepcopy(current)
        outcome = mutate_fn(working)
        now = time.time()
        working["updated_at"] = now
        working["expires_at"] = now + float(DATASET_TRANSIENT_SESSION_TTL_SECONDS)
        working["_state_revision"] = current_revision + (1 if increment_revision else 0)
        if persist and _transient_session_is_durable(working):
            # Disk is committed before the shared in-memory reference changes.
            # A failed fsync/replace therefore fails the request without
            # acknowledging state that cannot survive a process restart.
            working = _transient_session_state_write_locked(sid, working)
        DATASET_TRANSIENT_SESSIONS[sid] = working
        return copy.deepcopy(working), outcome, True


def delete_transient_dataset(session_id: str) -> Dict[str, Any]:
    sid = str(session_id or "").strip()
    if not sid:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="transient_session_required")
    _annotation_export_revoke_identity(f"transient:{sid}")
    with DATASET_TRANSIENT_LOCK:
        _resolve_transient_session_locked(sid, now=time.time(), touch=False)
        DATASET_TRANSIENT_SESSIONS.pop(sid, None)
        _transient_session_state_delete_locked(sid)
    _purge_expired_transient_sessions(include_persisted=True)
    return {"status": "deleted", "session_id": sid}


def save_transient_dataset(
    session_id: str,
    dataset_id: Optional[str],
    label: Optional[str],
    context: Optional[str],
    notes: Optional[str],
    expected_revision: Optional[int] = None,
):
    sid = str(session_id or "").strip()
    with DATASET_TRANSIENT_LOCK:
        session = _resolve_transient_session_locked(sid, now=time.time(), touch=False)
        try:
            source_revision = int(session.get("_state_revision") or 0)
        except Exception:
            source_revision = 0
        if expected_revision is not None:
            try:
                requested_revision = int(expected_revision)
            except Exception as exc:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="transient_session_revision_invalid",
                ) from exc
            if requested_revision != source_revision:
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail="transient_session_revision_conflict",
                )
        session = copy.deepcopy(session)
    dataset_root = _transient_session_dataset_root(session)
    base_id = _sanitize_yolo_run_id_impl(dataset_id or dataset_root.name) or "linked_dataset"
    registry_root = _dataset_registry_storage_root(
        create=True, detail="dataset_register_target_invalid"
    )
    dataset_id_final = _unique_dataset_name(base_id, root=registry_root)
    registry_dir = _dataset_registry_child_dir(
        dataset_id_final, detail="dataset_register_target_invalid"
    )
    if registry_dir.exists() or registry_dir.is_symlink():
        raise HTTPException(status_code=HTTP_409_CONFLICT, detail="dataset_register_target_exists")
    try:
        registry_dir.mkdir(parents=True, exist_ok=True)
        meta = _build_linked_dataset_metadata(
            dataset_id=dataset_id_final,
            dataset_root=dataset_root,
            label=label or session.get("label"),
            context=context,
            notes=notes or session.get("annotation_notes"),
        )
        session_classes = [
            str(item).strip() for item in (session.get("classes") or []) if str(item).strip()
        ]
        if session_classes:
            meta["classes"] = session_classes
            meta["yolo_labelmap_path"] = str(registry_dir / "labelmap.txt")
            meta["labelmap_source"] = "registry_overlay"
        if isinstance(session.get("annotation_progress"), dict):
            meta["annotation_progress"] = dict(session.get("annotation_progress") or {})
        if session.get("annotation_cursor") is not None:
            meta["annotation_cursor"] = session.get("annotation_cursor")
        if session.get("annotation_status"):
            meta["annotation_status"] = session.get("annotation_status")
        meta["transient_source_session_id"] = sid
        meta["transient_source_revision"] = source_revision
        if session_classes:
            _annotation_write_labelmap_file(
                registry_dir / "labelmap.txt",
                [registry_dir.resolve()],
                session_classes,
            )
        _write_dataset_metadata_json(registry_dir / DATASET_META_NAME, registry_dir, meta)
        persisted_entry = {
            "dataset_root": str(dataset_root),
            "registry_root": str(registry_dir),
            "yolo_layout": str(session.get("yolo_layout") or "flat"),
        }
        _persist_transient_overlays_to_entry(persisted_entry, session)
        entry = _resolve_dataset_entry_impl(dataset_id_final, list_all_datasets_fn=_list_all_datasets)
        if not entry:
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR, detail="dataset_register_failed"
            )
        with DATASET_TRANSIENT_LOCK:
            current = _resolve_transient_session_locked(sid, now=time.time(), touch=False)
            try:
                current_revision = int(current.get("_state_revision") or 0)
            except Exception:
                current_revision = -1
            if current_revision != source_revision:
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail="transient_session_changed_during_save",
                )
        response = dict(entry)
        response["source_session_id"] = sid
        response["source_session_revision"] = source_revision
        return response
    except Exception:
        try:
            _delete_dataset_tree_or_link(registry_dir, [registry_root])
        except Exception:
            pass
        raise


def start_dataset_annotation_session(dataset_id: str, payload: Dict[str, Any]):
    entry = _resolve_dataset_entry(dataset_id)
    with _dataset_annotation_mutation_lock(entry):
        _dataset_effective_root_from_entry(entry)
        _meta_path, meta = _annotation_load_or_create_meta(entry)
        lock_update = _annotation_update_lock(
            meta, payload or {}, force=bool((payload or {}).get("force"))
        )
        if not lock_update.get("ok"):
            return {
                "status": "warning",
                "warning": lock_update.get("warning"),
                "lock": lock_update.get("lock"),
                "dataset_id": dataset_id,
            }
        _annotation_persist_meta(entry, meta)
        return {
            "status": "ok",
            "dataset_id": dataset_id,
            "lock": lock_update.get("lock"),
        }


def heartbeat_dataset_annotation_session(dataset_id: str, payload: Dict[str, Any]):
    return start_dataset_annotation_session(dataset_id, payload or {})


def stop_dataset_annotation_session(dataset_id: str, payload: Dict[str, Any]):
    entry = _resolve_dataset_entry(dataset_id)
    with _dataset_annotation_mutation_lock(entry):
        _meta_path, meta = _annotation_load_or_create_meta(entry)
        released = _annotation_release_lock(meta, payload or {})
        if not released.get("ok"):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail=released.get("warning") or "annotation_lock_active",
            )
        _annotation_persist_meta(entry, meta)
        return {"status": "ok", "dataset_id": dataset_id, "lock": {}}


def get_dataset_annotation_manifest(dataset_id: str):
    entry = _resolve_dataset_entry(dataset_id)
    return _class_analysis_enrich_annotation_manifest(
        _annotation_manifest_for_entry(entry)
    )


def _resolve_annotation_image_path(
    dataset_root: Path, yolo_layout: str, split: str, image_relpath: Path
) -> Path:
    dataset_root = dataset_root.resolve()
    if yolo_layout == "split":
        image_path = dataset_root / split / "images" / image_relpath
    else:
        image_path = dataset_root / "images" / image_relpath
        if not image_path.exists():
            image_path = dataset_root / image_relpath
    if not image_path.exists():
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="annotation_image_not_found")
    resolved = image_path.resolve()
    if not _path_is_within_root_impl(resolved, dataset_root):
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="annotation_image_not_found")
    return resolved


def get_dataset_annotation_image(dataset_id: str, split: str, image_relpath: str):
    entry = _resolve_dataset_entry(dataset_id)
    dataset_root = _dataset_effective_root_from_entry(entry)
    split_norm = _annotation_normalise_split(split)
    rel = _annotation_normalise_image_relpath(image_relpath)
    image_path = _resolve_annotation_image_path(
        dataset_root, str(entry.get("yolo_layout") or "flat"), split_norm, rel
    )
    return FileResponse(str(image_path))


def save_dataset_annotation_snapshot(dataset_id: str, payload: Dict[str, Any]):
    payload = payload or {}
    entry = _resolve_dataset_entry(dataset_id)
    with _dataset_annotation_mutation_lock(entry):
        dataset_root = _dataset_effective_root_from_entry(entry)
        _meta_path, meta = _annotation_load_or_create_meta(entry)
        _require_annotation_lock_owner(meta, payload)
        expected_session_revision = payload.get("expected_session_revision")
        current_session_revision = int(meta.get("annotation_revision") or 0)
        if (
            expected_session_revision is not None
            and int(expected_session_revision) != current_session_revision
        ):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="annotation_session_revision_changed",
            )
        status_value = _annotation_requested_status(payload)
        normalised_records = _normalise_annotation_snapshot_records(payload.get("records"))
        yolo_layout = str(entry.get("yolo_layout") or "flat")
        _validate_annotation_snapshot_record_images(
            dataset_root,
            yolo_layout,
            normalised_records,
        )

        has_overlay_mutations = any(
            has_label_lines or has_text_label
            for _split, _rel, has_label_lines, _lines, has_text_label, _text
            in normalised_records
        )
        overlay_root = (
            _dataset_overlay_root_from_entry(entry, ensure=True)
            if has_overlay_mutations
            else None
        )
        progress = _annotation_progress_cache_value(meta)

        # Read each unique record's effective pre-save state exactly once.
        # Duplicate records in one payload are then evaluated sequentially
        # against the state left by the preceding record. An unknown cache does
        # not need presence reads at all: its safe response remains unknown.
        presence_by_key: Dict[str, Tuple[bool, bool]] = {}
        if progress is not None:
            for split, rel, _has_lines, _lines, _has_text, _text in normalised_records:
                key = f"{split}:{rel.as_posix()}"
                if key in presence_by_key:
                    continue
                old_has_lines = any(
                    str(line).strip()
                    for line in _annotation_effective_label_lines(entry, split, rel)
                )
                old_has_text = bool(
                    _annotation_effective_text_label(entry, rel, split).strip()
                )
                presence_by_key[key] = (old_has_lines, old_has_text)

        preview_presence = dict(presence_by_key)
        progress_may_change = False
        if progress is not None:
            for split, rel, has_label_lines, label_lines, has_text_label, text_value in normalised_records:
                key = f"{split}:{rel.as_posix()}"
                old_has_lines, old_has_text = preview_presence[key]
                new_has_lines = (
                    any(str(line).strip() for line in label_lines)
                    if has_label_lines
                    else old_has_lines
                )
                new_has_text = (
                    bool(str(text_value or "").strip())
                    if has_text_label
                    else old_has_text
                )
                progress_may_change = progress_may_change or (
                    new_has_lines != old_has_lines or new_has_text != old_has_text
                )
                preview_presence[key] = (new_has_lines, new_has_text)

        # Once overlay writes begin, a crash or a later write failure can leave
        # a valid subset committed. Persist the cache invalidation first; only
        # republish the O(records) delta after every count-changing overlay
        # write succeeds. Geometry/content-only edits preserve the counters and
        # need only the final metadata write.
        if progress is not None and progress_may_change:
            _annotation_invalidate_progress_cache(meta)
            _annotation_persist_meta(entry, meta)

        progress_labeled = (
            int(progress["images_with_bbox_or_seg"])
            if progress is not None
            else 0
        )
        progress_text_labeled = (
            int(progress["images_with_text_label"])
            if progress is not None
            else 0
        )
        progress_total = int(progress["images_total"]) if progress is not None else 0

        for split, rel, has_label_lines, label_lines, has_text_label, text_value in normalised_records:
            key = f"{split}:{rel.as_posix()}"
            old_has_lines, old_has_text = presence_by_key.get(key, (False, False))
            new_has_lines = old_has_lines
            new_has_text = old_has_text
            if has_label_lines:
                label_path = _annotation_overlay_label_path(entry, split, rel)
                _annotation_write_text_within_root(
                    label_path,
                    overlay_root,
                    "\n".join(label_lines) + ("\n" if label_lines else ""),
                )
                new_has_lines = any(str(line).strip() for line in label_lines)
            if has_text_label:
                text_path = _annotation_overlay_text_path(entry, rel, split=split)
                _annotation_write_text_within_root(text_path, overlay_root, text_value)
                new_has_text = bool(str(text_value or "").strip())
            presence_by_key[key] = (new_has_lines, new_has_text)
            if progress is not None:
                progress_labeled += int(new_has_lines) - int(old_has_lines)
                progress_text_labeled += int(new_has_text) - int(old_has_text)
                if (
                    progress_labeled < 0
                    or progress_text_labeled < 0
                    or progress_labeled > progress_total
                    or progress_text_labeled > progress_total
                ):
                    # The supposedly current cache disagreed with the effective
                    # files (for example after an external linked-root edit).
                    # Do not publish clamped-but-wrong counters.
                    progress = None

        if status_value:
            meta["annotation_status"] = status_value
        if "notes" in payload:
            meta["annotation_notes"] = str(payload.get("notes") or "")
        if "cursor" in payload:
            meta["annotation_cursor"] = payload.get("cursor")

        if progress is not None:
            saved_progress = _annotation_set_progress_cache(
                meta,
                {
                    "images_total": progress_total,
                    "images_with_bbox_or_seg": progress_labeled,
                    "images_with_text_label": progress_text_labeled,
                },
            )
        else:
            _annotation_invalidate_progress_cache(meta)
            saved_progress = {}
        if normalised_records:
            meta["annotation_revision"] = int(meta.get("annotation_revision") or 0) + 1
        _annotation_persist_meta(entry, meta)
        saved_record_by_key: Dict[str, Dict[str, Any]] = {}
        for split, rel, has_lines, lines, _has_text, _text in normalised_records:
            key = f"{split}:{rel.as_posix()}"
            saved_record = saved_record_by_key.get(key)
            if saved_record is None:
                image_path = _resolve_annotation_image_path(
                    dataset_root,
                    yolo_layout,
                    split,
                    rel,
                )
                saved_record = {
                    "split": split,
                    "image_relpath": rel.as_posix(),
                    "annotation_source_identity": _annotation_image_source_identity(
                        source_mode="linked",
                        source_id=dataset_id,
                        split=split,
                        image_relpath=rel,
                        image_path=image_path,
                        yolo_layout=yolo_layout,
                    ),
                }
                saved_record_by_key[key] = saved_record
            # The normalized payload is applied sequentially. The last label
            # mutation for this image therefore defines the committed CAS
            # revision. Text-only records deliberately omit a revision rather
            # than rereading the effective label file just to build a receipt.
            if has_lines:
                saved_record["annotation_record_revision"] = (
                    _annotation_image_label_revision(lines)
                )
        return {
            "status": "saved",
            "dataset_id": dataset_id,
            "progress": saved_progress,
            "session_revision": int(meta.get("annotation_revision") or 0),
            "records": list(saved_record_by_key.values()),
        }


def _patch_dataset_annotation_meta_unlocked(dataset_id: str, payload: Dict[str, Any]):
    payload = payload or {}
    entry = _resolve_dataset_entry(dataset_id)
    _meta_path, meta = _annotation_load_or_create_meta(entry)
    _require_annotation_lock_owner(meta, payload)
    status_value = _annotation_requested_status(payload)
    saved_labelmap: Optional[List[str]] = None
    if "labelmap" in payload:
        saved_labelmap = _normalize_labelmap_payload(payload.get("labelmap"))
        dataset_root = _dataset_effective_root_from_entry(entry)
        labelmap_path = _annotation_labelmap_write_path(entry, dataset_root)
        storage_root = _dataset_guarded_meta_storage_root_from_entry(
            entry,
            ensure=False,
            detail="labelmap_path_forbidden",
        )
        storage_mode = str(entry.get("storage_mode") or "managed").strip().lower()
        allowed_labelmap_roots = (
            [storage_root.resolve()]
            if storage_mode == "linked"
            else [dataset_root.resolve(), storage_root.resolve()]
        )
        try:
            _annotation_write_labelmap_file(
                labelmap_path,
                allowed_labelmap_roots,
                saved_labelmap,
            )
        except HTTPException:
            raise
        except Exception as exc:  # noqa: BLE001
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                detail=f"labelmap_save_failed:{exc}",
            ) from exc
        storage_root = _dataset_guarded_meta_storage_root_from_entry(
            entry,
            ensure=True,
            detail="dataset_metadata_path_forbidden",
        )
        dataset_meta = _load_json_metadata(_dataset_meta_path_for_entry(entry)) or dict(entry)
        dataset_meta["classes"] = list(saved_labelmap)
        dataset_meta["yolo_labelmap_path"] = str(labelmap_path)
        if storage_mode == "linked":
            dataset_meta["labelmap_source"] = "registry_overlay"
        dataset_meta["signature"] = _compute_dir_signature_impl(dataset_root)
        meta["classes"] = list(saved_labelmap)
        meta["yolo_labelmap_path"] = str(labelmap_path)
        if storage_mode == "linked":
            meta["labelmap_source"] = "registry_overlay"
        meta["signature"] = dataset_meta["signature"]
        _write_dataset_metadata_json(storage_root / DATASET_META_NAME, storage_root, dataset_meta)
    if status_value:
        meta["annotation_status"] = status_value
    if "notes" in payload:
        meta["annotation_notes"] = str(payload.get("notes") or "")
    if "cursor" in payload:
        meta["annotation_cursor"] = payload.get("cursor")
    if saved_labelmap is not None:
        meta["annotation_revision"] = int(meta.get("annotation_revision") or 0) + 1
    _annotation_persist_meta(entry, meta)
    return {
        "status": "saved",
        "dataset_id": dataset_id,
        "annotation_status": meta.get("annotation_status") or "new",
        "annotation_notes": str(meta.get("annotation_notes") or ""),
        "annotation_cursor": meta.get("annotation_cursor"),
        "labelmap": saved_labelmap,
        "session_revision": int(meta.get("annotation_revision") or 0),
    }


def patch_dataset_annotation_meta(dataset_id: str, payload: Dict[str, Any]):
    entry = _resolve_dataset_entry(dataset_id)
    with _dataset_annotation_mutation_lock(entry):
        return _patch_dataset_annotation_meta_unlocked(dataset_id, payload)


def start_transient_annotation_session(session_id: str, payload: Dict[str, Any]):
    request_payload = dict(payload or {})

    def _update_lock(session: Dict[str, Any]) -> Dict[str, Any]:
        return _annotation_update_lock(
            session,
            request_payload,
            force=bool(request_payload.get("force")),
        )

    session, lock_update, _committed = _mutate_transient_session(
        session_id,
        _update_lock,
    )
    if not lock_update.get("ok"):
        return {
            "status": "warning",
            "session_id": session_id,
            "warning": lock_update.get("warning"),
            "lock": lock_update.get("lock"),
            "session_revision": int(session.get("_state_revision") or 0),
        }
    return {
        "status": "ok",
        "session_id": session_id,
        "lock": lock_update.get("lock"),
        "session_revision": int(session.get("_state_revision") or 0),
        "resumed_after_expiry_at": session.get("resumed_after_expiry_at"),
    }


def heartbeat_transient_annotation_session(session_id: str, payload: Dict[str, Any]):
    request_payload = dict(payload or {})

    def _update_lock(session: Dict[str, Any]) -> Dict[str, Any]:
        return _annotation_update_lock(
            session,
            request_payload,
            force=bool(request_payload.get("force")),
        )

    session, lock_update, _committed = _mutate_transient_session(
        session_id,
        _update_lock,
        increment_revision=False,
        persist=False,
    )
    if not lock_update.get("ok"):
        return {
            "status": "warning",
            "session_id": session_id,
            "warning": lock_update.get("warning"),
            "lock": lock_update.get("lock"),
            "session_revision": int(session.get("_state_revision") or 0),
        }
    return {
        "status": "ok",
        "session_id": session_id,
        "lock": lock_update.get("lock"),
        "session_revision": int(session.get("_state_revision") or 0),
    }


def stop_transient_annotation_session(session_id: str, payload: Dict[str, Any]):
    request_payload = dict(payload or {})

    def _release_lock(session: Dict[str, Any]) -> Dict[str, Any]:
        released = _annotation_release_lock(session, request_payload)
        if not released.get("ok"):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail=released.get("warning") or "annotation_lock_active",
            )
        return released

    session, released, _committed = _mutate_transient_session(
        session_id,
        _release_lock,
    )
    return {
        "status": "ok",
        "session_id": session_id,
        "lock": {},
        "session_revision": int(session.get("_state_revision") or 0),
    }


def get_transient_annotation_manifest(session_id: str):
    session = _resolve_transient_session(session_id)
    try:
        source_revision = int(session.get("_state_revision") or 0)
    except Exception:
        source_revision = 0
    dataset_root = _transient_session_dataset_root(session)
    yolo_layout = str(session.get("yolo_layout") or "flat")
    annotation_source_root = _transient_session_annotation_source_root(
        session,
        dataset_root,
    )
    rows: List[Dict[str, Any]] = []
    overlay_labels = (
        session.get("overlay_labels") if isinstance(session.get("overlay_labels"), dict) else {}
    )
    overlay_text = (
        session.get("overlay_text") if isinstance(session.get("overlay_text"), dict) else {}
    )
    base_entry = {
        "dataset_root": str(dataset_root),
        "yolo_layout": yolo_layout,
        "registry_root": None,
    }
    for image in _annotation_collect_images(base_entry):
        split = _annotation_normalise_split(image.get("split"))
        rel = _annotation_normalise_image_relpath(image.get("image_relpath"))
        key = f"{split}:{rel.as_posix()}"
        if key in overlay_labels:
            lines = [str(x).strip() for x in (overlay_labels.get(key) or []) if str(x).strip()]
        else:
            source_path = _annotation_source_label_path(
                annotation_source_root,
                yolo_layout,
                split,
                rel,
            )
            source_text = _annotation_read_text_within_root(
                source_path,
                annotation_source_root,
            )
            lines = (
                [ln.strip() for ln in source_text.splitlines() if ln.strip()]
                if source_text is not None
                else []
            )
        if key in overlay_text:
            text_val = str(overlay_text.get(key) or "")
        else:
            text_val = _annotation_source_text_value(
                annotation_source_root,
                rel,
                split=split,
                yolo_layout=yolo_layout,
            )
        rows.append(
            {
                "split": split,
                "image_relpath": str(rel.as_posix()),
                "image_name": rel.name,
                "label_lines": lines,
                "annotation_record_revision": _annotation_image_label_revision(
                    lines
                ),
                "annotation_source_identity": _annotation_image_source_identity(
                    source_mode="transient",
                    source_id=session_id,
                    split=split,
                    image_relpath=rel,
                    image_path=Path(image.get("image_path")),
                    yolo_layout=yolo_layout,
                ),
                "text_label": text_val,
            }
        )
    progress = _annotation_progress_from_rows(rows)

    def _store_progress(current: Dict[str, Any]) -> None:
        current["annotation_progress"] = progress

    # Image collection can be expensive. Do not hold the session lock while
    # scanning the source tree, and do not publish progress computed from an
    # older overlay revision after a concurrent snapshot/meta/heartbeat commit.
    committed_session, _outcome, _committed = _mutate_transient_session(
        session_id,
        _store_progress,
        expected_revision=source_revision,
        increment_revision=False,
    )
    return _class_analysis_enrich_annotation_manifest({
        "session_id": session_id,
        "session_revision": source_revision,
        "dataset_label": session.get("label") or dataset_root.name,
        "dataset_root": str(dataset_root),
        "storage_mode": "transient",
        "labelmap": list(session.get("classes") or []),
        "yolo_layout": yolo_layout,
        "status": session.get("annotation_status") or "new",
        "notes": str(session.get("annotation_notes") or ""),
        "cursor": session.get("annotation_cursor"),
        "lock": (
            session.get("annotation_lock")
            if isinstance(session.get("annotation_lock"), dict)
            else {}
        ),
        "progress": progress,
        "images": rows,
        "source_kind": str(session.get("source_kind") or ""),
        "class_analysis_job_id": str(session.get("class_analysis_job_id") or ""),
        "class_analysis_snapshot_id": str(
            session.get("class_analysis_snapshot_id") or ""
        ),
        "class_analysis_input_digest": str(
            session.get("class_analysis_input_digest") or ""
        ),
    })


def get_transient_annotation_image(session_id: str, split: str, image_relpath: str):
    session = _resolve_transient_session(session_id)
    dataset_root = _transient_session_dataset_root(session)
    split_norm = _annotation_normalise_split(split)
    rel = _annotation_normalise_image_relpath(image_relpath)
    image_path = _resolve_annotation_image_path(
        dataset_root, str(session.get("yolo_layout") or "flat"), split_norm, rel
    )
    return FileResponse(str(image_path))


def save_transient_annotation_snapshot(session_id: str, payload: Dict[str, Any]):
    payload = payload or {}
    session = _resolve_transient_session(session_id)
    status_value = _annotation_requested_status(payload)
    normalised_records = _normalise_annotation_snapshot_records(payload.get("records"))
    if normalised_records:
        dataset_root = _transient_session_dataset_root(session)
        yolo_layout = str(session.get("yolo_layout") or "flat")
        annotation_source_root = _transient_session_annotation_source_root(
            session,
            dataset_root,
        )
        _validate_annotation_snapshot_record_images(
            dataset_root,
            yolo_layout,
            normalised_records,
        )
    else:
        dataset_root = None
        annotation_source_root = None
        yolo_layout = str(session.get("yolo_layout") or "flat")
    source_presence: Dict[str, Tuple[bool, bool]] = {}
    session_labels = session.get("overlay_labels") if isinstance(session.get("overlay_labels"), dict) else {}
    session_text = session.get("overlay_text") if isinstance(session.get("overlay_text"), dict) else {}
    for split, rel, _has_lines, _lines, _has_text, _text_value in normalised_records:
        key = f"{split}:{rel.as_posix()}"
        if key in source_presence:
            continue
        if key in session_labels:
            old_has_lines = any(str(item).strip() for item in (session_labels.get(key) or []))
        else:
            source_label_path = _annotation_source_label_path(
                annotation_source_root,
                yolo_layout,
                split,
                rel,
            )
            source_label_text = _annotation_read_text_within_root(
                source_label_path,
                annotation_source_root,
            )
            old_has_lines = bool(source_label_text and source_label_text.strip())
        if key in session_text:
            old_has_text = bool(str(session_text.get(key) or "").strip())
        else:
            old_has_text = bool(
                _annotation_source_text_value(
                    annotation_source_root,
                    rel,
                    split=split,
                    yolo_layout=yolo_layout,
                ).strip()
            )
        source_presence[key] = (old_has_lines, old_has_text)

    def _apply_snapshot(current: Dict[str, Any]) -> None:
        _require_annotation_lock_owner(current, payload)
        overlay_labels = (
            dict(current.get("overlay_labels"))
            if isinstance(current.get("overlay_labels"), dict)
            else {}
        )
        overlay_text = (
            dict(current.get("overlay_text"))
            if isinstance(current.get("overlay_text"), dict)
            else {}
        )
        progress = (
            dict(current.get("annotation_progress"))
            if isinstance(current.get("annotation_progress"), dict)
            else {}
        )
        try:
            progress_total = int(progress.get("images_total"))
            progress_labeled = int(progress.get("images_with_bbox_or_seg"))
            progress_text_labeled = int(progress.get("images_with_text_label"))
            progress_is_known = progress_total >= 0
        except Exception:
            progress_total = 0
            progress_labeled = 0
            progress_text_labeled = 0
            progress_is_known = False
        for split, rel, has_label_lines, label_lines, has_text_label, text_value in normalised_records:
            key = f"{split}:{rel.as_posix()}"
            baseline_lines, baseline_text = source_presence.get(key, (False, False))
            old_has_lines = (
                any(str(item).strip() for item in (overlay_labels.get(key) or []))
                if key in overlay_labels
                else baseline_lines
            )
            old_has_text = (
                bool(str(overlay_text.get(key) or "").strip())
                if key in overlay_text
                else baseline_text
            )
            new_has_lines = (
                any(str(item).strip() for item in label_lines)
                if has_label_lines
                else old_has_lines
            )
            new_has_text = (
                bool(str(text_value or "").strip())
                if has_text_label
                else old_has_text
            )
            if has_label_lines:
                overlay_labels[key] = label_lines
            if has_text_label:
                overlay_text[key] = text_value
            if progress_is_known:
                progress_labeled += int(new_has_lines) - int(old_has_lines)
                progress_text_labeled += int(new_has_text) - int(old_has_text)
        current["overlay_labels"] = overlay_labels
        current["overlay_text"] = overlay_text
        if progress_is_known:
            progress_labeled = max(0, min(progress_total, progress_labeled))
            progress_text_labeled = max(0, min(progress_total, progress_text_labeled))
            progress.update(
                {
                    "images_total": progress_total,
                    "images_with_bbox_or_seg": progress_labeled,
                    "images_with_text_label": progress_text_labeled,
                    "percent_labeled": (
                        100.0 * progress_labeled / progress_total
                        if progress_total > 0
                        else 0.0
                    ),
                    "percent_text_labeled": (
                        100.0 * progress_text_labeled / progress_total
                        if progress_total > 0
                        else 0.0
                    ),
                }
            )
            current["annotation_progress"] = progress
        if status_value:
            current["annotation_status"] = status_value
        if "notes" in payload:
            current["annotation_notes"] = str(payload.get("notes") or "")
        if "cursor" in payload:
            current["annotation_cursor"] = payload.get("cursor")

    expected_session_revision = payload.get("expected_session_revision")
    committed_session, _outcome, committed = _mutate_transient_session(
        session_id,
        _apply_snapshot,
        expected_revision=(
            int(expected_session_revision)
            if expected_session_revision is not None
            else None
        ),
    )
    if not committed:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="annotation_session_revision_changed",
        )
    saved_record_by_key: Dict[str, Dict[str, Any]] = {}
    for split, rel, has_lines, lines, _has_text, _text in normalised_records:
        key = f"{split}:{rel.as_posix()}"
        saved_record = saved_record_by_key.get(key)
        if saved_record is None:
            image_path = _resolve_annotation_image_path(
                dataset_root,
                yolo_layout,
                split,
                rel,
            )
            saved_record = {
                "split": split,
                "image_relpath": rel.as_posix(),
                "annotation_source_identity": _annotation_image_source_identity(
                    source_mode="transient",
                    source_id=session_id,
                    split=split,
                    image_relpath=rel,
                    image_path=image_path,
                    yolo_layout=yolo_layout,
                ),
            }
            saved_record_by_key[key] = saved_record
        if has_lines:
            saved_record["annotation_record_revision"] = (
                _annotation_image_label_revision(lines)
            )
    return {
        "status": "saved",
        "session_id": session_id,
        "progress": committed_session.get("annotation_progress") or {},
        "session_revision": int(committed_session.get("_state_revision") or 0),
        "records": list(saved_record_by_key.values()),
    }


def patch_transient_annotation_meta(session_id: str, payload: Dict[str, Any]):
    payload = payload or {}
    status_value = _annotation_requested_status(payload)
    saved_labelmap: Optional[List[str]] = None
    if "labelmap" in payload:
        saved_labelmap = _normalize_labelmap_payload(payload.get("labelmap"))

    def _apply_meta(current: Dict[str, Any]) -> None:
        _require_annotation_lock_owner(current, payload)
        if saved_labelmap is not None:
            current["classes"] = list(saved_labelmap)
            current["labelmap_source"] = "transient_session"
        if status_value:
            current["annotation_status"] = status_value
        if "notes" in payload:
            current["annotation_notes"] = str(payload.get("notes") or "")
        if "cursor" in payload:
            current["annotation_cursor"] = payload.get("cursor")

    session, _outcome, _committed = _mutate_transient_session(
        session_id,
        _apply_meta,
    )
    return {
        "status": "saved",
        "session_id": session_id,
        "annotation_status": session.get("annotation_status") or "new",
        "annotation_notes": str(session.get("annotation_notes") or ""),
        "annotation_cursor": session.get("annotation_cursor"),
        "labelmap": saved_labelmap,
        "session_revision": int(session.get("_state_revision") or 0),
    }


def _class_analysis_authoritative_record_count(
    payload: Mapping[str, Any],
) -> Tuple[int, str]:
    """Count source annotations server-side when the source is already resolvable."""
    try:
        source = _class_analysis_source(dict(payload))
        manifest = source.get("manifest") if isinstance(source, Mapping) else None
        images = manifest.get("images") if isinstance(manifest, Mapping) else None
        if isinstance(images, list):
            selected_scope = str(
                payload.get("analysis_scope")
                or payload.get("scope")
                or "all_classes"
            ).strip().lower() == "selected_class"
            selected_class_id: Optional[int] = -1 if selected_scope else None
            if selected_scope:
                class_name = str(payload.get("class_name") or "").strip()
                labelmap = [str(value) for value in (source.get("labelmap") or [])]
                if class_name in labelmap:
                    selected_class_id = labelmap.index(class_name)
            count = 0
            for image in images:
                if not isinstance(image, Mapping):
                    continue
                for raw_line in image.get("label_lines") or []:
                    parts = str(raw_line or "").strip().split()
                    if not parts or re.fullmatch(r"[0-9]+", parts[0]) is None:
                        continue
                    if selected_class_id is not None and int(parts[0]) != selected_class_id:
                        continue
                    count += 1
            sample_cap = _coerce_int(payload.get("sample_cap"), 0, minimum=0)
            if sample_cap > 0:
                count = min(count, sample_cap)
            return count, "server_source"
    except Exception:
        # The first transient-workspace preflight can precede source upload. The
        # enqueue path repeats preflight once the server owns the source.
        pass

    record_count = _coerce_int(
        payload.get("record_count", payload.get("object_count")),
        0,
        minimum=0,
    )
    sample_cap = _coerce_int(payload.get("sample_cap"), 0, minimum=0)
    if sample_cap > 0:
        record_count = min(record_count, sample_cap) if record_count else sample_cap
    return record_count, "client_estimate"


def _class_analysis_resolved_recipe(payload: Mapping[str, Any]) -> Dict[str, Any]:
    """Describe the exact analysis roles without changing runtime behavior."""
    explicit_recipe = payload.get("quality_recipe") or payload.get("recipe_preset")
    legacy_explicit_recipe_controls = any(
        key in payload
        for key in (
            "encoder_type",
            "encoder_model",
            "embedding_aggregation",
            "dinov3_pooling",
            "cradio_pooling",
        )
    )
    recipe_id = str(
        explicit_recipe
        or ("custom" if legacy_explicit_recipe_controls else THOROUGH_QUALITY_RECIPE)
    ).strip().lower()
    if recipe_id not in {
        THOROUGH_QUALITY_RECIPE,
        PRECISE_COMPACT_RECIPE,
        FAST_MAP_RECIPE,
        "custom",
    }:
        recipe_id = THOROUGH_QUALITY_RECIPE
    quality_recipe = resolve_quality_recipe(recipe_id, payload)
    encoder_type = str(payload.get("encoder_type") or "dinov3").strip().lower()
    encoder_model = str(payload.get("encoder_model") or "").strip()
    if encoder_type not in {"dinov3", "clip", "cradio"}:
        encoder_type = "dinov3"
    encoder_model_lower = encoder_model.lower()
    if encoder_type == "cradio":
        base_dimensions = 4608
        if str(payload.get("cradio_pooling") or "summary").strip().lower() == "summary_spatial_concat":
            base_dimensions *= 2
    elif encoder_type == "clip":
        base_dimensions = 768
    else:
        base_dimensions = (
            384
            if "vits" in encoder_model_lower
            else 768
            if "vitb" in encoder_model_lower
            else 1536
            if "vitg" in encoder_model_lower or "vith" in encoder_model_lower
            else 1024
        )
        if str(payload.get("dinov3_pooling") or "pooler").strip().lower() == "cls_patch_concat":
            base_dimensions *= 2
    view_mode = str(payload.get("embedding_view_mode") or "single").strip().lower()
    if view_mode in {
        "tight_standard",
        "standard_context",
        "tight_context",
    }:
        base_dimensions *= 2
    aggregation = str(
        payload.get("embedding_aggregation") or "pooled"
    ).strip().lower()
    salad_settings = class_analysis_salad_settings(payload)
    compact_components: List[Dict[str, Any]] = []
    if recipe_id in {THOROUGH_QUALITY_RECIPE, PRECISE_COMPACT_RECIPE}:
        dino_weight, sam_weight, salad_weight = salad_settings.fusion_weights
        compact_dimensions = base_dimensions + 256 + salad_settings.descriptor_dim
        compact_components = [
            {
                "id": "dinov3",
                "label": "DINOv3 tight and context",
                "dimensions": int(base_dimensions),
                "weight": float(dino_weight),
            },
            {
                "id": "sam3",
                "label": "SAM3 mask descriptor",
                "dimensions": 256,
                "weight": float(sam_weight),
            },
            {
                "id": "salad",
                "label": f"SALAD {salad_settings.preset}",
                "dimensions": int(salad_settings.descriptor_dim),
                "weight": float(salad_weight),
            },
        ]
    elif recipe_id == FAST_MAP_RECIPE:
        compact_dimensions = base_dimensions
        compact_components = [
            {
                "id": "dinov3",
                "label": "DINOv3 single view",
                "dimensions": int(base_dimensions),
                "weight": 1.0,
            }
        ]
    else:
        compact_dimensions = base_dimensions
        compact_components = [
            {
                "id": encoder_type,
                "label": encoder_type.upper() if encoder_type != "dinov3" else "DINOv3",
                "dimensions": int(base_dimensions),
                "weight": 1.0,
            }
        ]
        if aggregation in {
            CLASS_ANALYSIS_SAM3_MASK_FUSION_SCHEMA,
            CLASS_ANALYSIS_SAM3_SALAD_FUSION_SCHEMA,
        }:
            compact_components[0]["weight"] = float(
                CLASS_ANALYSIS_SAM3_MASK_FUSION_DINO_WEIGHT
                if aggregation == CLASS_ANALYSIS_SAM3_MASK_FUSION_SCHEMA
                else salad_settings.fusion_weights[0]
            )
            compact_components.append(
                {
                    "id": "sam3",
                    "label": "SAM3 mask descriptor",
                    "dimensions": 256,
                    "weight": float(
                        CLASS_ANALYSIS_SAM3_MASK_FUSION_SAM_WEIGHT
                        if aggregation == CLASS_ANALYSIS_SAM3_MASK_FUSION_SCHEMA
                        else salad_settings.fusion_weights[1]
                    ),
                }
            )
            compact_dimensions += 256
        if aggregation == CLASS_ANALYSIS_SAM3_SALAD_FUSION_SCHEMA:
            compact_components.append(
                {
                    "id": "salad",
                    "label": f"SALAD {salad_settings.preset}",
                    "dimensions": int(salad_settings.descriptor_dim),
                    "weight": float(salad_settings.fusion_weights[2]),
                }
            )
            compact_dimensions += salad_settings.descriptor_dim

    requested_feature_mode = str(payload.get("feature_mode") or "").strip().lower()
    if recipe_id == THOROUGH_QUALITY_RECIPE:
        feature_mode = "multi_backbone_fusion"
        label = "Thorough: multi-backbone"
        branches = [
            {
                "id": "compact",
                "label": "DINOv3 + SAM3 + SALAD",
                "dimensions": int(compact_dimensions),
                "weight": float(quality_recipe.compact_weight),
                "components": compact_components,
            },
            {
                "id": "cradio",
                "label": "C-RADIO summary",
                "dimensions": 4608,
                "weight": float(quality_recipe.cradio_weight),
                "components": [],
            },
        ]
    elif recipe_id == PRECISE_COMPACT_RECIPE:
        feature_mode = "compact_fusion"
        label = "Balanced: compact fusion"
        branches = [
            {
                "id": "compact",
                "label": "DINOv3 + SAM3 + SALAD",
                "dimensions": int(compact_dimensions),
                "weight": 1.0,
                "components": compact_components,
            }
        ]
    elif recipe_id == FAST_MAP_RECIPE:
        feature_mode = "single_backbone"
        label = "Fast: DINOv3"
        branches = compact_components
    else:
        feature_mode = requested_feature_mode if requested_feature_mode in {
            "single_backbone",
            "compact_fusion",
            "multi_backbone_fusion",
        } else (
            "compact_fusion" if len(compact_components) > 1 else "single_backbone"
        )
        label = "Custom"
        branches = [
            {
                "id": "compact" if len(compact_components) > 1 else encoder_type,
                "label": (
                    "Custom compact fusion"
                    if len(compact_components) > 1
                    else compact_components[0]["label"]
                ),
                "dimensions": int(compact_dimensions),
                "weight": 1.0,
                "components": compact_components if len(compact_components) > 1 else [],
            }
        ]
        if quality_recipe.use_cradio:
            feature_mode = "multi_backbone_fusion"
            branches[0]["weight"] = float(quality_recipe.compact_weight)
            branches.append(
                {
                    "id": "cradio",
                    "label": "C-RADIO summary",
                    "dimensions": 4608,
                    "weight": float(quality_recipe.cradio_weight),
                    "components": [],
                }
            )
    total_dimensions = sum(int(branch.get("dimensions") or 0) for branch in branches)
    if recipe_id in {THOROUGH_QUALITY_RECIPE, PRECISE_COMPACT_RECIPE, "custom"}:
        ranking_signals = [
            "compact_logistic_disagreement",
            "compact_neighbor_disagreement",
        ]
        if quality_recipe.use_cradio:
            ranking_signals.extend(
                [
                    "cradio_logistic_disagreement",
                    "cradio_neighbor_disagreement",
                ]
            )
        if quality_recipe.use_el2n:
            ranking_signals.append("el2n")
    else:
        ranking_signals = ["neighbor_disagreement"]
    analysis_scope = str(
        payload.get("analysis_scope") or "selected_class"
    ).strip().lower()
    proposals_enabled = bool(
        recipe_id in {THOROUGH_QUALITY_RECIPE, PRECISE_COMPACT_RECIPE, "custom"}
        and analysis_scope != "selected_class"
    )
    refinement_enabled = bool(
        payload.get("deep_evidence_pass", payload.get("refine_outliers", False))
    )
    projection = str(payload.get("projection") or "pca").strip().lower()
    if projection != "umap":
        projection = "pca"
    resolved: Dict[str, Any] = {
        "schema": "class-analysis-resolved-recipe",
        "recipe_id": recipe_id,
        "label": label,
        "feature_mode": feature_mode,
        "projection_features": {
            "mode": feature_mode,
            "branches": branches,
            "total_dimensions": int(total_dimensions),
            "normalization": "unit_rows_sqrt_weight_concat_unit_rows",
            "projection": projection,
            "projection_mode": str(payload.get("projection_mode") or ""),
            "uses_merged_features": bool(
                recipe_id in {THOROUGH_QUALITY_RECIPE, PRECISE_COMPACT_RECIPE, "custom"}
            ),
        },
        "ranking_features": {
            "signals": ranking_signals,
            "uses_cradio": bool(quality_recipe.use_cradio),
            "uses_el2n": bool(quality_recipe.use_el2n),
            "compact_weight": float(quality_recipe.compact_weight),
            "cradio_weight": float(quality_recipe.cradio_weight),
            "late_compact_weight": float(quality_recipe.late_compact_weight),
            "late_cradio_weight": float(quality_recipe.late_cradio_weight),
            "late_weight": float(quality_recipe.late_weight),
            "el2n_weight": float(quality_recipe.el2n_weight),
        },
        "class_proposal_features": {
            "enabled": proposals_enabled,
            "source": "source_disjoint_rbf_on_projection_features"
            if proposals_enabled
            else None,
        },
        "spatial_refinement": {
            "enabled": refinement_enabled,
            "mechanisms": [
                "dinov3_spatial_tokens",
                "tokencut_regions",
                "per_class_overlays",
                "wider_context",
            ]
            if refinement_enabled
            else [],
            "invokes_vlm": False,
        },
        "downstream_review_artifacts": {
            "available": refinement_enabled,
            "consumable_by_separate_vlm_review": refinement_enabled,
        },
        "execution_plan": {
            "requested_memory_policy": str(
                payload.get("quality_memory_policy") or "auto"
            ),
            "resolved_memory_policy": str(
                payload.get("quality_resolved_memory_policy")
                or payload.get("quality_memory_policy")
                or "auto"
            ),
        },
    }
    phase_specs = [
        ("preflight", "Preparing the analysis", "dataset, cache, and memory plan"),
        ("models", "Loading the feature tools", ", ".join(str(branch.get("label") or "") for branch in branches)),
    ]
    if any(
        component.get("id") == "salad"
        for branch in branches
        for component in (branch.get("components") or [])
    ):
        phase_specs.append(("salad", "Learning spatial pooling", f"SALAD {salad_settings.preset}"))
    phase_specs.append(("features", "Describing each object", label))
    if feature_mode != "single_backbone":
        phase_specs.append(("fusion", "Combining feature branches", f"{total_dimensions}-D representation"))
    phase_specs.append(("ranking", "Testing labels against class structure", ", ".join(ranking_signals)))
    phase_specs.append(("projection", f"Building the {projection.upper()} map", f"{total_dimensions}-D input"))
    if refinement_enabled:
        phase_specs.append(("refinement", "Building spatial evidence", "DINO spatial tokens and TokenCut overlays"))
    phase_specs.extend(
        [
            ("finalization", "Preparing the review queue", "real candidates and proposed classes"),
            ("complete", "Analysis ready", "map and review queue ready"),
        ]
    )
    resolved["progress_phases"] = [
        {"id": phase_id, "label": phase_label, "detail": phase_detail}
        for phase_id, phase_label, phase_detail in phase_specs
    ]
    return resolved


def _class_analysis_quality_preflight(payload: Mapping[str, Any]) -> Dict[str, Any]:
    """Resolve a stable execution plan plus current host-risk telemetry."""
    record_count, count_source = _class_analysis_authoritative_record_count(payload)
    resolved_recipe = _class_analysis_resolved_recipe(payload)
    recipe = str(resolved_recipe["recipe_id"])
    projection_features = resolved_recipe["projection_features"]
    if recipe == THOROUGH_QUALITY_RECIPE or bool(
        resolved_recipe.get("ranking_features", {}).get("uses_cradio")
    ):
        compact_dimensions = sum(
            int(branch.get("dimensions") or 0)
            for branch in projection_features.get("branches") or []
            if str(branch.get("id") or "") != "cradio"
        )
        cradio_dimensions = sum(
            int(branch.get("dimensions") or 0)
            for branch in projection_features.get("branches") or []
            if str(branch.get("id") or "") == "cradio"
        )
    else:
        compact_dimensions = int(projection_features.get("total_dimensions") or 0)
        cradio_dimensions = 0
    available_mb = available_quality_memory_mb()
    estimated_incremental_mb = estimate_quality_workspace_mb(
        record_count,
        compact_dimensions,
        cradio_dimensions,
    )
    requested_policy = str(payload.get("quality_memory_policy") or "auto").strip().lower()
    if requested_policy not in {"auto", "full", "budgeted"}:
        requested_policy = "auto"
    raw_budget = payload.get("quality_memory_budget_mb")
    budget_mb = (
        min(
            QUALITY_MEMORY_MAX_MB,
            _coerce_int(
                raw_budget,
                recommended_quality_memory_mb(available_mb),
                minimum=QUALITY_MEMORY_MIN_MB,
            ),
        )
        if raw_budget not in (None, "")
        else recommended_quality_memory_mb(available_mb)
    )
    try:
        import psutil

        baseline_rss_mb = int(psutil.Process(os.getpid()).memory_info().rss // (1024 * 1024))
    except Exception:
        baseline_rss_mb = 0
    model_residency_mb = {
        THOROUGH_QUALITY_RECIPE: 8192,
        PRECISE_COMPACT_RECIPE: 3072,
        FAST_MAP_RECIPE: 2048,
    }.get(recipe, 4096)
    runtime_pair_count = int(record_count * max(0, record_count - 1))
    runtime_risk = (
        "quadratic_extreme"
        if runtime_pair_count >= 1_000_000_000
        else "quadratic_high"
        if runtime_pair_count >= 100_000_000
        else "normal"
    )
    if estimated_incremental_mb > max(1, available_mb) * 1.25:
        memory_risk = "severe"
    elif estimated_incremental_mb > max(1, available_mb):
        memory_risk = "exceeds_available"
    elif estimated_incremental_mb > budget_mb:
        memory_risk = "elevated"
    else:
        memory_risk = "fits_budget"
    resolved_policy = requested_policy
    if requested_policy == "auto":
        resolved_policy = (
            "full"
            if memory_risk == "fits_budget"
            and runtime_risk == "normal"
            and record_count <= CLASS_ANALYSIS_EXACT_NEIGHBOR_LIMIT
            else "budgeted"
        )
    requires_confirmation = bool(
        requested_policy == "full"
        and (memory_risk != "fits_budget" or runtime_risk != "normal")
    )
    resolved_budget_mb = budget_mb if resolved_policy == "budgeted" else None
    execution_plan = {
        "schema": "class-analysis-execution-plan-v2",
        "record_count": record_count,
        "recipe": recipe,
        "projection": str(payload.get("projection") or "pca"),
        "requested_policy": requested_policy,
        "resolved_policy": resolved_policy,
        "requested_budget_mb": (
            _coerce_int(raw_budget, 0, minimum=0)
            if raw_budget not in (None, "")
            else None
        ),
        "resolved_budget_mb": resolved_budget_mb,
        "runtime_risk": runtime_risk,
    }
    execution_plan_id = hashlib.sha256(
        json.dumps(execution_plan, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    digest_payload = {
        **execution_plan,
        "estimated_incremental_mb": estimated_incremental_mb,
        "memory_risk": memory_risk,
    }
    preflight_digest = hashlib.sha256(
        json.dumps(digest_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    resolved_recipe["execution_plan"] = {
        **dict(resolved_recipe.get("execution_plan") or {}),
        "execution_plan_id": execution_plan_id,
        "record_count": record_count,
        "requested_memory_policy": requested_policy,
        "resolved_memory_policy": resolved_policy,
        "resolved_memory_budget_mb": resolved_budget_mb,
        "runtime_risk": runtime_risk,
        "memory_risk": memory_risk,
    }
    return {
        "schema": "class-analysis-preflight-v2",
        "preflight_digest": preflight_digest,
        "execution_plan_id": execution_plan_id,
        "record_count": record_count,
        "record_count_source": count_source,
        "requested_policy": requested_policy,
        "resolved_policy": resolved_policy,
        "budget_mb": resolved_budget_mb,
        "baseline_backend_rss_mb": baseline_rss_mb,
        "estimated_model_residency_mb": model_residency_mb,
        "estimated_peak_incremental_mb": estimated_incremental_mb,
        "available_memory_mb": available_mb,
        "memory_risk": memory_risk,
        "requires_confirmation": requires_confirmation,
        "runtime_risk": runtime_risk,
        "execution_plan": execution_plan,
        "resolved_recipe": resolved_recipe,
        "progress_phases": list(resolved_recipe.get("progress_phases") or []),
        "algorithm_plan": {
            "quality": (
                "all_object_in_memory_with_bounded_superlinear_models"
                if resolved_policy == "full"
                else "streaming_memmap"
            ),
            "projection": "selected_full_projection" if resolved_policy == "full" else "incremental_or_landmark",
            "neighbors": (
                "exact_below_ceiling_then_ann_all_query"
                if resolved_policy == "full"
                else "low_memory_ann_with_exact_fallback"
            ),
        },
    }


@app.post("/class_analysis/preflight")
def preflight_class_analysis(payload: Dict[str, Any]) -> Dict[str, Any]:
    normalized = _normalize_class_analysis_request(payload)
    return _class_analysis_quality_preflight(normalized)


