def _class_analysis_log(job: ClassAnalysisJob, message: str) -> None:
    entry = {"timestamp": time.time(), "message": str(message or "")}
    job.logs.append(entry)
    if len(job.logs) > MAX_JOB_LOGS:
        job.logs[:] = job.logs[-MAX_JOB_LOGS:]
    job.message = str(message or "")
    job.updated_at = time.time()
    try:
        logger.info("[class-analysis %s] %s", job.job_id[:8], message)
    except Exception:
        pass


def _class_analysis_update(
    job: ClassAnalysisJob,
    *,
    status: Optional[str] = None,
    progress: Optional[float] = None,
    message: Optional[str] = None,
    phase_id: Optional[str] = None,
    phase_label: Optional[str] = None,
    phase_detail: Optional[str] = None,
    completed_units: Optional[int] = None,
    total_units: Optional[int] = None,
    active_component: Optional[str] = None,
    error: Optional[str] = None,
    result: Optional[Dict[str, Any]] = None,
) -> None:
    if status is not None:
        job.status = status
    if progress is not None:
        job.progress = clamp_progress(progress, fallback=job.progress)
    if message is not None:
        if str(message or "") != str(job.message or ""):
            _class_analysis_log(job, str(message or ""))
        else:
            job.message = str(message or "")
            job.updated_at = time.time()
        if phase_detail is None:
            job.phase_detail = str(message or "")
    if phase_id is not None:
        job.phase_id = str(phase_id or "")
    if phase_label is not None:
        job.phase_label = str(phase_label or "")
    if phase_detail is not None:
        job.phase_detail = str(phase_detail or "")
    if completed_units is not None:
        job.phase_completed_units = max(0, int(completed_units))
    if total_units is not None:
        job.phase_total_units = max(0, int(total_units))
    if active_component is not None:
        job.active_component = str(active_component or "")
    if error is not None:
        job.error = error
    if result is not None:
        job.result = result
        job.updated_at = time.time()


def _serialize_class_analysis_job(job: ClassAnalysisJob) -> Dict[str, Any]:
    compact_summary = getattr(job, "summary", None)
    persisted_result = getattr(job, "result", None)
    summary = (
        compact_summary
        if isinstance(compact_summary, dict) and compact_summary
        else (persisted_result or {}).get("summary")
        if isinstance(persisted_result, dict)
        else None
    )
    progress_state = {
        "phase_id": str(getattr(job, "phase_id", "") or ""),
        "phase_label": str(getattr(job, "phase_label", "") or ""),
        "phase_detail": str(getattr(job, "phase_detail", "") or job.message or ""),
        "completed_units": int(getattr(job, "phase_completed_units", 0) or 0),
        "total_units": int(getattr(job, "phase_total_units", 0) or 0),
        "overall_fraction": json_sanitize(job.progress),
        "active_component": str(getattr(job, "active_component", "") or ""),
        "job_id": str(job.job_id or ""),
        "analysis_generation": str(job.request.get("analysis_generation") or ""),
        "phases": json_sanitize(getattr(job, "progress_phases", []) or []),
        "cache": json_sanitize(getattr(job, "cache_status", {}) or {}),
    }
    return {
        "job_id": job.job_id,
        "run_fingerprint": str(job.request.get("run_fingerprint") or ""),
        "snapshot_id": str(job.request.get("snapshot_id") or ""),
        "status": job.status,
        "progress": json_sanitize(job.progress),
        "progress_state": progress_state,
        "message": job.message,
        "request": json_sanitize(job.request),
        "logs": json_sanitize(job.logs),
        "summary": json_sanitize(summary),
        "runtime": json_sanitize(getattr(job, "runtime", None)),
        "stage": str(getattr(job, "stage", "") or ""),
        "stage_index": int(getattr(job, "stage_index", 0) or 0),
        "stage_count": int(getattr(job, "stage_count", 0) or 0),
        "stage_processed": int(getattr(job, "stage_processed", 0) or 0),
        "stage_total": int(getattr(job, "stage_total", 0) or 0),
        "error": json_sanitize(job.error),
        "created_at": job.created_at,
        "updated_at": job.updated_at,
    }


def _serialize_class_analysis_cluster_job(job: ClassAnalysisClusterJob) -> Dict[str, Any]:
    return {
        "cluster_job_id": job.job_id,
        "job_id": job.job_id,
        "parent_job_id": job.parent_job_id,
        "status": job.status,
        "progress": json_sanitize(job.progress),
        "message": job.message,
        "request": json_sanitize(job.request),
        "logs": json_sanitize(job.logs),
        "summary": json_sanitize(
            (job.result or {}).get("summary") if isinstance(job.result, dict) else None
        ),
        "result": json_sanitize(job.result),
        "error": json_sanitize(job.error),
        "created_at": job.created_at,
        "updated_at": job.updated_at,
    }


def _class_analysis_json_safe(value: Any) -> Any:
    if isinstance(value, np.ndarray):
        return [_class_analysis_json_safe(v) for v in value.tolist()]
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, dict):
        return {str(k): _class_analysis_json_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_class_analysis_json_safe(v) for v in value]
    return value


def _class_analysis_json_encoder_default(value: Any) -> Any:
    """Convert the non-standard scalar/array values used in analysis JSON.

    This is intentionally a ``JSONEncoder.default`` callback rather than a
    recursive pre-pass.  Keeping conversion lazy is what lets the class
    analysis artifact writer bound publication memory for large results.
    """

    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    raise TypeError(
        f"Object of type {value.__class__.__name__} is not JSON serializable"
    )


def _class_analysis_safe_slug(value: str, fallback: str = "source") -> str:
    cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", str(value or "")).strip("._-")
    return cleaned or fallback


def _class_analysis_safe_relpath(value: str, fallback: str = "image.jpg") -> Path:
    parts = []
    for raw_part in Path(str(value or "")).parts:
        if raw_part in {"", ".", ".."}:
            continue
        safe = _class_analysis_safe_slug(raw_part, "")
        if safe:
            parts.append(safe)
    if not parts:
        parts = [fallback]
    return Path(*parts)


def _class_analysis_storage_root(
    *,
    create: bool = True,
    detail: str = "class_analysis_path_invalid",
) -> Path:
    try:
        raw_root = CLASS_ANALYSIS_ROOT
        if _storage_path_has_symlink_component(raw_root):
            raise ValueError("class analysis root is a symlink")
        if create:
            raw_root.mkdir(parents=True, exist_ok=True)
        if _storage_path_has_symlink_component(raw_root):
            raise ValueError("class analysis root is a symlink")
        if raw_root.exists() and not raw_root.is_dir():
            raise ValueError("class analysis root is not a directory")
        return raw_root.resolve(strict=False)
    except Exception as exc:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail=detail) from exc


def _class_analysis_cache_storage_root(*, create: bool = False) -> Optional[Path]:
    try:
        raw_root = CLASS_ANALYSIS_CACHE_ROOT
        if _storage_path_has_symlink_component(raw_root):
            return None
        if create:
            raw_root.mkdir(parents=True, exist_ok=True)
        if _storage_path_has_symlink_component(raw_root):
            return None
        if raw_root.exists() and not raw_root.is_dir():
            return None
        if not create and not raw_root.exists():
            return None
        return raw_root.resolve(strict=False)
    except Exception:
        return None


def _class_analysis_archive_job_audits(job_dir: Path, audit_root: Path) -> None:
    qwen_dir = job_dir / "qwen_reviews"
    if not qwen_dir.is_dir() or qwen_dir.is_symlink():
        return
    audit_root.mkdir(parents=True, exist_ok=True)
    destination = audit_root / job_dir.name
    if destination.exists():
        destination = audit_root / f"{job_dir.name}_{uuid.uuid4().hex[:8]}"
    os.replace(qwen_dir, destination)


def _class_analysis_delete_quarantined(paths: Sequence[Path]) -> None:
    """Delete validated quarantine roots outside the API process.

    Recursive deletion can spend minutes walking hundreds of thousands of
    small cache files. Running it in a child interpreter keeps that filesystem
    work from monopolizing this process's GIL and starving HTTP requests.
    """

    serialized_paths = json.dumps([str(Path(path)) for path in paths])
    cleanup_script = (
        "import json, os, shutil, sys\n"
        "from pathlib import Path\n"
        "try:\n"
        "    os.nice(10)\n"
        "except (AttributeError, OSError):\n"
        "    pass\n"
        "for raw_path in json.loads(sys.argv[1]):\n"
        "    path = Path(raw_path)\n"
        "    if path.is_dir() and not path.is_symlink():\n"
        "        shutil.rmtree(path, ignore_errors=False)\n"
        "    else:\n"
        "        path.unlink(missing_ok=True)\n"
    )
    completed = subprocess.run(
        [sys.executable, "-c", cleanup_script, serialized_paths],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
    )
    if completed.returncode != 0:
        detail = str(completed.stderr or "").strip()
        raise RuntimeError(
            f"class_analysis_quarantine_delete_failed:{detail[-1000:] or completed.returncode}"
        )


def _class_analysis_enforce_cache_budget() -> Dict[str, int]:
    """Apply a filesystem-only LRU budget without a startup database reload."""

    cache_root = _class_analysis_cache_storage_root(create=True)
    if cache_root is None:
        return {"files": 0, "bytes": 0, "removed_files": 0, "removed_bytes": 0}
    files: List[Tuple[float, int, Path]] = []
    total_bytes = 0
    removed_files = 0
    removed_bytes = 0
    removed_session_bytes = 0
    remaining_session_bytes = 0
    removed_budget_files = 0
    protected_temp_files = 0
    now = time.time()
    try:
        for candidate in cache_root.rglob("*"):
            try:
                if candidate.is_symlink():
                    candidate.unlink(missing_ok=True)
                    removed_files += 1
                    continue
                if not candidate.is_file():
                    continue
                if not _path_is_within_root_impl(candidate.resolve(strict=False), cache_root):
                    continue
                stat_result = candidate.stat()
                size = max(0, int(stat_result.st_size))
                if candidate.name.endswith((".tmp", ".partial")):
                    age_seconds = max(0.0, now - float(stat_result.st_mtime))
                    if age_seconds >= float(
                        CLASS_ANALYSIS_CACHE_STALE_TEMP_SECONDS
                    ):
                        candidate.unlink(missing_ok=True)
                        removed_files += 1
                        removed_bytes += size
                    else:
                        # Atomic cache writers use this suffix. A concurrent
                        # janitor must account for the bytes but never unlink
                        # a live writer or include it in LRU eviction.
                        total_bytes += size
                        protected_temp_files += 1
                    continue
                files.append((float(stat_result.st_mtime), size, candidate))
                total_bytes += size
            except OSError:
                continue
        with CLASS_ANALYSIS_STORAGE_POLICY_LOCK:
            budget = int(CLASS_ANALYSIS_CACHE_MAX_BYTES)
        active_users = _class_analysis_cache_active_users()
        if active_users:
            return {
                "files": max(0, len(files) + protected_temp_files),
                "bytes": max(0, total_bytes),
                "removed_files": removed_files,
                "removed_bytes": removed_bytes,
                "removed_session_bytes": 0,
                "remaining_session_bytes": 0,
            }
        active_job_ids = {
            str(row.get("job_id") or "")
            for row in active_users
        }
        try:
            latest = _latest_class_analysis_session(CLASS_ANALYSIS_ROOT)
        except ClassAnalysisSessionManifestError:
            latest = None
        latest_job_id = str((latest or {}).get("job_id") or "")
        pinned_ids = {job_id for job_id in {*active_job_ids, latest_job_id} if job_id}
        sessions = recoverable_session_inventory(
            CLASS_ANALYSIS_ROOT,
            pinned_job_ids=pinned_ids,
        )
        session_victims = choose_unpinned_session_evictions(
            sessions["sessions"],
            cache_bytes=total_bytes,
            max_bytes=budget,
        )
        quarantined_sessions: List[Path] = []
        removed_session_bytes = 0
        audit_root = CLASS_ANALYSIS_ROOT / "audit"
        for row in session_victims:
            candidate = Path(str(row.get("path") or ""))
            if (
                candidate.parent.resolve(strict=False) != CLASS_ANALYSIS_ROOT.resolve(strict=False)
                or candidate.name in pinned_ids
                or not candidate.is_dir()
                or candidate.is_symlink()
            ):
                continue
            try:
                _class_analysis_archive_job_audits(candidate, audit_root)
                quarantine = CLASS_ANALYSIS_ROOT / f".purge-session-{candidate.name}-{uuid.uuid4().hex}"
                os.replace(candidate, quarantine)
                quarantined_sessions.append(quarantine)
                removed_session_bytes += max(0, int(row.get("bytes") or 0))
            except OSError:
                continue
        if quarantined_sessions:
            _class_analysis_delete_quarantined(quarantined_sessions)
        remaining_session_bytes = max(0, int(sessions["total_bytes"]) - removed_session_bytes)
        cache_budget = max(0, budget - remaining_session_bytes)
        if cache_budget <= 0:
            victims = files
        elif total_bytes > cache_budget:
            victims = []
            remaining = total_bytes
            for entry in sorted(files, key=lambda item: item[0]):
                if remaining <= cache_budget:
                    break
                victims.append(entry)
                remaining -= entry[1]
        else:
            victims = []
        for _mtime, size, candidate in victims:
            try:
                candidate.unlink(missing_ok=True)
                total_bytes -= size
                removed_files += 1
                removed_budget_files += 1
                removed_bytes += size
            except OSError:
                continue
        for directory in sorted(
            [path for path in cache_root.rglob("*") if path.is_dir()],
            key=lambda path: len(path.parts),
            reverse=True,
        ):
            try:
                directory.rmdir()
            except OSError:
                pass
    except Exception:
        logger.exception("Class analysis cache budget enforcement failed")
    return {
        "files": max(
            0,
            len(files) - removed_budget_files + protected_temp_files,
        ),
        "bytes": max(0, total_bytes),
        "removed_files": removed_files,
        "removed_bytes": removed_bytes,
        "removed_session_bytes": removed_session_bytes,
        "remaining_session_bytes": remaining_session_bytes,
    }


def _class_analysis_startup_cleanup_worker() -> None:
    ready_for_analysis = False
    with CLASS_ANALYSIS_STARTUP_CLEANUP_LOCK:
        CLASS_ANALYSIS_STARTUP_CLEANUP_STATE.update(
            {
                "status": "quarantining",
                "started_at": time.time(),
                "ready_at": None,
                "completed_at": None,
                "error": None,
            }
        )
    try:
        root = _class_analysis_storage_root(create=True)
        purge_parent = root / ".purge"
        if _class_analysis_prepare_dir(purge_parent, root) is None:
            raise RuntimeError("class_analysis_cleanup_quarantine_invalid")
        stale_quarantined = list(purge_parent.iterdir())
        purge_root = purge_parent / f"startup_{uuid.uuid4().hex[:12]}"
        audit_root = root / "audit"
        if _class_analysis_prepare_dir(purge_root, root) is None:
            raise RuntimeError("class_analysis_cleanup_quarantine_invalid")
        if _class_analysis_prepare_dir(audit_root, root) is None:
            raise RuntimeError("class_analysis_audit_root_invalid")
        targets: List[Path] = []
        runtime_root = root / "runtime"
        if runtime_root.exists():
            targets.append(runtime_root)
        for child in root.iterdir():
            if child.name in {".purge", "audit", "exports"} or child.name.startswith("bench_"):
                continue
            if child in targets:
                continue
            if child.name.startswith(("ca_", "cac_")):
                if child.is_dir() and not child.is_symlink():
                    _class_analysis_archive_job_audits(child, audit_root)
                targets.append(child)
            elif child.is_file() and child.suffix.lower() in {".sqlite", ".sqlite-wal", ".sqlite-shm"}:
                targets.append(child)
        with CLASS_ANALYSIS_STARTUP_CLEANUP_LOCK:
            CLASS_ANALYSIS_STARTUP_CLEANUP_STATE["targets"] = len(targets)
        quarantined: List[Path] = []
        for target in targets:
            if not target.exists() and not target.is_symlink():
                continue
            if not _path_is_within_root_impl(target.resolve(strict=False), root):
                raise RuntimeError("class_analysis_cleanup_target_outside_root")
            destination = purge_root / f"{target.name}_{uuid.uuid4().hex[:8]}"
            os.replace(target, destination)
            quarantined.append(destination)
        if _class_analysis_cache_storage_root(create=True) is None:
            raise RuntimeError("class_analysis_cache_root_recreate_failed")
        with CLASS_ANALYSIS_RUN_FINGERPRINTS_LOCK:
            CLASS_ANALYSIS_RUN_FINGERPRINTS.clear()
        with CLASS_ANALYSIS_ACTIVE_SNAPSHOTS_LOCK:
            CLASS_ANALYSIS_ACTIVE_SNAPSHOTS.clear()
        with CLASS_ANALYSIS_FILE_HASH_CACHE_LOCK:
            CLASS_ANALYSIS_FILE_HASH_CACHE.clear()
        ready_for_analysis = True
        with CLASS_ANALYSIS_STARTUP_CLEANUP_LOCK:
            CLASS_ANALYSIS_STARTUP_CLEANUP_STATE.update(
                {"status": "deleting", "ready_at": time.time(), "error": None}
            )
        delete_targets = [*stale_quarantined, *quarantined]
        for target in delete_targets:
            if not _path_is_within_root_impl(target.resolve(strict=False), purge_parent):
                raise RuntimeError("class_analysis_stale_quarantine_outside_root")
        _class_analysis_delete_quarantined(delete_targets)
        try:
            purge_root.rmdir()
            purge_root.parent.rmdir()
        except OSError:
            pass
        with CLASS_ANALYSIS_STARTUP_CLEANUP_LOCK:
            CLASS_ANALYSIS_STARTUP_CLEANUP_STATE.update(
                {"status": "completed", "completed_at": time.time(), "error": None}
            )
        threading.Thread(
            target=_class_analysis_enforce_cache_budget,
            name="class-analysis-cache-janitor",
            daemon=True,
        ).start()
    except Exception as exc:
        logger.exception("Class analysis startup cleanup failed")
        with CLASS_ANALYSIS_STARTUP_CLEANUP_LOCK:
            CLASS_ANALYSIS_STARTUP_CLEANUP_STATE.update(
                {
                    "status": "deletion_failed" if ready_for_analysis else "failed",
                    "completed_at": time.time(),
                    "error": str(exc),
                }
            )


def _class_analysis_restore_active_snapshots_from_disk() -> int:
    """Restore browser-reusable active snapshots when runtime purge is off."""

    root = _class_analysis_storage_root(create=True)
    restored: Dict[str, Dict[str, Any]] = {}
    try:
        children = list(root.iterdir())
    except OSError:
        return 0
    for job_dir in children:
        if (
            not job_dir.name.startswith("ca_")
            or not job_dir.is_dir()
            or job_dir.is_symlink()
        ):
            continue
        workspace_dir = job_dir / "active_workspace"
        snapshot_path = _safe_existing_regular_file_within_root_impl(
            workspace_dir / "snapshot.json",
            workspace_dir,
        )
        if snapshot_path is None:
            continue
        try:
            snapshot = _class_analysis_json_artifact_snapshot(snapshot_path)
            payload = snapshot.get("payload")
            if not isinstance(payload, dict):
                continue
            snapshot_id = str(payload.get("snapshot_id") or "").strip()
            images = payload.get("images")
            labelmap = payload.get("labelmap")
            restored_payload = {
                **dict(payload),
                # The manifest can move with the portable analysis root. Its
                # containing active_workspace is authoritative; the persisted
                # absolute path is only historical metadata after a move.
                "workspace_dir": str(workspace_dir.resolve(strict=True)),
            }
            if (
                not snapshot_id
                or not isinstance(images, list)
                or not isinstance(labelmap, list)
                or _class_analysis_active_snapshot_record_workspace(
                    restored_payload,
                    snapshot_id=snapshot_id,
                    images=images,
                    labelmap=labelmap,
                )
                is None
            ):
                continue
            _class_analysis_require_snapshot_path_unchanged(
                snapshot_path,
                snapshot,
                detail="class_analysis_active_snapshot_manifest",
            )
            existing = restored.get(snapshot_id)
            if existing is None or float(
                restored_payload.get("created_at") or 0.0
            ) > float(existing.get("created_at") or 0.0):
                restored[snapshot_id] = restored_payload
        except Exception:
            continue
    with CLASS_ANALYSIS_ACTIVE_SNAPSHOTS_LOCK:
        CLASS_ANALYSIS_ACTIVE_SNAPSHOTS.update(restored)
    return len(restored)


def _start_class_analysis_startup_cleanup() -> None:
    if not CLASS_ANALYSIS_PURGE_ON_START:
        restored_snapshots = _class_analysis_restore_active_snapshots_from_disk()
        with CLASS_ANALYSIS_STARTUP_CLEANUP_LOCK:
            CLASS_ANALYSIS_STARTUP_CLEANUP_STATE.update(
                {
                    "status": "disabled",
                    "ready_at": time.time(),
                    "completed_at": time.time(),
                    "error": None,
                    "restored_active_snapshots": restored_snapshots,
                }
            )
        threading.Thread(
            target=_class_analysis_enforce_cache_budget,
            name="class-analysis-cache-janitor",
            daemon=True,
        ).start()
        return
    if os.environ.get("PYTEST_CURRENT_TEST"):
        with CLASS_ANALYSIS_STARTUP_CLEANUP_LOCK:
            CLASS_ANALYSIS_STARTUP_CLEANUP_STATE.update(
                {"status": "test_skipped", "ready_at": time.time(), "completed_at": time.time(), "error": None}
            )
        return
    with CLASS_ANALYSIS_STARTUP_CLEANUP_LOCK:
        if CLASS_ANALYSIS_STARTUP_CLEANUP_STATE.get("status") in {
            "queued",
            "quarantining",
            "deleting",
            "completed",
            "deletion_failed",
        }:
            return
        CLASS_ANALYSIS_STARTUP_CLEANUP_STATE["status"] = "queued"
    threading.Thread(
        target=_class_analysis_startup_cleanup_worker,
        name="class-analysis-startup-cleanup",
        daemon=True,
    ).start()


def _class_analysis_job_dir(
    job_id: str,
    *,
    create: bool = False,
    detail: str = "class_analysis_path_invalid",
) -> Path:
    safe_job_id = _class_analysis_safe_slug(str(job_id or ""), "job")
    try:
        root = _class_analysis_storage_root(create=True, detail=detail)
        candidate = root / safe_job_id
        if _storage_path_has_symlink_component(candidate):
            raise ValueError("class analysis job dir is a symlink")
        if create:
            candidate.mkdir(parents=True, exist_ok=True)
        if _storage_path_has_symlink_component(candidate):
            raise ValueError("class analysis job dir is a symlink")
        if candidate.exists() and not candidate.is_dir():
            raise ValueError("class analysis job path is not a directory")
        resolved = candidate.resolve(strict=False)
        if not _path_is_within_root_impl(resolved, root) or resolved.parent != root:
            raise ValueError("class analysis job path escapes root")
        return resolved
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail=detail) from exc


def _class_analysis_active_workspace_paths(
    workspace_dir_value: Any,
    manifest_path_value: Any,
) -> Tuple[Path, Optional[Path]]:
    try:
        class_root = _class_analysis_storage_root(
            create=True,
            detail="active_workspace_path_invalid",
        )
        workspace_raw = Path(str(workspace_dir_value or "")).expanduser()
        if _storage_path_has_symlink_component(workspace_raw):
            raise ValueError("active workspace dir is a symlink")
        workspace_dir = workspace_raw.resolve(strict=True)
        if not workspace_dir.is_dir() or not _path_is_within_root_impl(workspace_dir, class_root):
            raise ValueError("active workspace dir is outside class analysis root")
        manifest_path: Optional[Path] = None
        manifest_raw_value = str(manifest_path_value or "").strip()
        if manifest_raw_value:
            manifest_raw = Path(manifest_raw_value).expanduser()
            if _storage_path_has_symlink_component(manifest_raw):
                raise ValueError("active workspace manifest is a symlink")
            manifest_path = manifest_raw.resolve(strict=True)
            if (
                not manifest_path.is_file()
                or not _path_is_within_root_impl(manifest_path, workspace_dir)
            ):
                raise ValueError("active workspace manifest is outside active workspace")
        return workspace_dir, manifest_path
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="active_workspace_path_invalid") from exc


def _class_analysis_source_locator(payload: Mapping[str, Any]) -> Dict[str, Any]:
    """Resolve only the image root/layout needed for lazy thumbnail reads."""

    source_mode = str(
        payload.get("source_mode") or payload.get("mode") or "linked"
    ).strip().lower()
    if source_mode in {"active_workspace", "workspace"}:
        workspace_dir, _manifest_path = _class_analysis_active_workspace_paths(
            payload.get("workspace_dir"),
            None,
        )
        return {
            "dataset_root": workspace_dir,
            "yolo_layout": str(payload.get("yolo_layout") or "flat"),
        }
    if source_mode in {"dataset", "linked"}:
        dataset_id = str(payload.get("dataset_id") or "").strip()
        if not dataset_id:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="dataset_id_required",
            )
        entry = _resolve_dataset_entry(dataset_id)
        return {
            "dataset_root": _dataset_effective_root_from_entry(entry),
            "yolo_layout": str(entry.get("yolo_layout") or "flat"),
        }
    if source_mode in {"transient", "open_path"}:
        session_id = str(payload.get("session_id") or "").strip()
        if not session_id:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="session_id_required",
            )
        session = _resolve_transient_session(session_id)
        return {
            "dataset_root": _validate_linked_dataset_path(
                str(session.get("dataset_root") or "")
            ),
            "yolo_layout": str(session.get("yolo_layout") or "flat"),
        }
    raise HTTPException(
        status_code=HTTP_400_BAD_REQUEST,
        detail="class_analysis_source_invalid",
    )


def _class_analysis_source(payload: Dict[str, Any]) -> Dict[str, Any]:
    source_mode = str(payload.get("source_mode") or payload.get("mode") or "linked").strip().lower()
    if source_mode in {"active_workspace", "workspace"}:
        workspace_dir, manifest_path = _class_analysis_active_workspace_paths(
            payload.get("workspace_dir"),
            payload.get("workspace_manifest_path"),
        )
        manifest_path_raw = str(payload.get("workspace_manifest_path") or "").strip()
        manifest = payload.get("workspace_manifest") if isinstance(payload.get("workspace_manifest"), dict) else None
        if manifest is None and manifest_path_raw and manifest_path is not None:
            manifest = _load_json_metadata(manifest_path) or {}
        if not isinstance(manifest, dict):
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="active_workspace_manifest_invalid")
        labelmap = [str(x) for x in manifest.get("labelmap") or payload.get("labelmap") or []]
        snapshot_id = str(payload.get("snapshot_id") or manifest.get("snapshot_id") or "").strip()
        stable_source_id = snapshot_id or str(payload.get("workspace_id") or payload.get("job_id") or "active")
        return {
            "source_mode": "active_workspace",
            "source_id": stable_source_id,
            "source_key": f"active:{stable_source_id}",
            "dataset_root": workspace_dir,
            "yolo_layout": str(payload.get("yolo_layout") or manifest.get("yolo_layout") or "flat"),
            "manifest": manifest,
            "labelmap": labelmap,
        }
    if source_mode in {"dataset", "linked"}:
        dataset_id = str(payload.get("dataset_id") or "").strip()
        if not dataset_id:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="dataset_id_required")
        entry = _resolve_dataset_entry(dataset_id)
        dataset_root = _dataset_effective_root_from_entry(entry)
        manifest = _annotation_manifest_for_entry(entry)
        return {
            "source_mode": "linked",
            "source_id": dataset_id,
            "source_key": f"linked:{dataset_id}",
            "dataset_root": dataset_root,
            "yolo_layout": str(entry.get("yolo_layout") or "flat"),
            "manifest": manifest,
            "labelmap": list(manifest.get("labelmap") or entry.get("classes") or []),
        }
    if source_mode in {"transient", "open_path"}:
        session_id = str(payload.get("session_id") or "").strip()
        if not session_id:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="session_id_required")
        session = _resolve_transient_session(session_id)
        dataset_root = _transient_session_dataset_root(session)
        manifest = get_transient_annotation_manifest(session_id)
        return {
            "source_mode": "transient",
            "source_id": session_id,
            "source_key": f"transient:{session_id}",
            "dataset_root": dataset_root,
            "yolo_layout": str(session.get("yolo_layout") or "flat"),
            "manifest": manifest,
            "labelmap": list(manifest.get("labelmap") or session.get("classes") or []),
        }
    raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="class_analysis_source_invalid")


def _class_analysis_parse_yolo_geometry(
    line: str,
    *,
    image_width: int,
    image_height: int,
) -> Optional[Dict[str, Any]]:
    parts = str(line or "").strip().split()
    if len(parts) < 5:
        return None
    if re.fullmatch(r"[0-9]+", parts[0]) is None:
        return None
    try:
        class_id = int(parts[0])
    except Exception:
        return None
    if len(parts) >= 7:
        points: List[Tuple[float, float]] = []
        for idx in range(1, len(parts) - 1, 2):
            try:
                nx = float(parts[idx])
                ny = float(parts[idx + 1])
            except Exception:
                return None
            if not math.isfinite(nx) or not math.isfinite(ny):
                return None
            points.append(
                (
                    max(0.0, min(float(image_width), nx * float(image_width))),
                    max(0.0, min(float(image_height), ny * float(image_height))),
                )
            )
        if len(points) < 3:
            return None
        xs = [pt[0] for pt in points]
        ys = [pt[1] for pt in points]
        x1, x2 = max(0.0, min(xs)), min(float(image_width), max(xs))
        y1, y2 = max(0.0, min(ys)), min(float(image_height), max(ys))
        if x2 <= x1 or y2 <= y1:
            return None
        return {
            "class_id": class_id,
            "kind": "polygon",
            "bbox_xyxy": [x1, y1, x2, y2],
            "points": [[float(x), float(y)] for x, y in points],
        }
    try:
        cx = float(parts[1]) * float(image_width)
        cy = float(parts[2]) * float(image_height)
        bw = float(parts[3]) * float(image_width)
        bh = float(parts[4]) * float(image_height)
    except Exception:
        return None
    if not all(math.isfinite(value) for value in (cx, cy, bw, bh)):
        return None
    if bw <= 0 or bh <= 0:
        return None
    x1 = max(0.0, min(float(image_width), cx - (bw / 2.0)))
    y1 = max(0.0, min(float(image_height), cy - (bh / 2.0)))
    x2 = max(0.0, min(float(image_width), cx + (bw / 2.0)))
    y2 = max(0.0, min(float(image_height), cy + (bh / 2.0)))
    if x2 <= x1 or y2 <= y1:
        return None
    return {"class_id": class_id, "kind": "bbox", "bbox_xyxy": [x1, y1, x2, y2]}


def _class_analysis_parse_yolo_geometry_for_identity(
    line: str,
    *,
    image_width: int,
    image_height: int,
) -> Tuple[Optional[Dict[str, Any]], Optional[int]]:
    """Parse geometry even when the row's class token is corrupt.

    Exact reassignment verification must count a same-geometry malformed row
    as an ambiguity instead of ignoring it and certifying the remaining row as
    unique. The returned class id is therefore ``None`` unless the original
    token is a canonical non-negative integer.
    """

    parts = str(line or "").strip().split()
    if len(parts) < 5:
        return None, None
    strict_class_id: Optional[int] = None
    if re.fullmatch(r"[0-9]+", parts[0]):
        try:
            strict_class_id = int(parts[0])
        except (TypeError, ValueError, OverflowError):
            strict_class_id = None
    geometry_line = " ".join(["0", *parts[1:]])
    parsed = _class_analysis_parse_yolo_geometry(
        geometry_line,
        image_width=image_width,
        image_height=image_height,
    )
    return parsed, strict_class_id


def _class_analysis_exact_frozen_review_geometry(
    event: Mapping[str, Any],
    *,
    image_width: int,
    image_height: int,
) -> Optional[Dict[str, Any]]:
    point = event.get("point")
    bbox_payload = (
        point.get("bbox") if isinstance(point, Mapping) else None
    )
    if not isinstance(bbox_payload, Mapping):
        return None
    label_line = str(bbox_payload.get("label_line") or "").strip()
    if label_line:
        parsed, _class_id = _class_analysis_parse_yolo_geometry_for_identity(
            label_line,
            image_width=image_width,
            image_height=image_height,
        )
        if isinstance(parsed, Mapping):
            return _class_analysis_canonical_review_geometry(
                parsed,
                image_width=image_width,
                image_height=image_height,
            )
    bbox_xyxy = list(bbox_payload.get("xyxy") or [])[:4]
    if len(bbox_xyxy) != 4:
        return None
    try:
        legacy_geometry = {
            "kind": str(bbox_payload.get("kind") or "bbox"),
            "bbox_xyxy": [float(value) for value in bbox_xyxy],
        }
    except (TypeError, ValueError, OverflowError):
        return None
    # Legacy snapshots without label_line can still bind exact normalized bbox
    # geometry. Polygon envelopes are insufficient to identify a polygon and
    # therefore deliberately fail closed.
    if str(legacy_geometry["kind"]).strip().lower() == "polygon":
        return None
    return _class_analysis_canonical_review_geometry(
        legacy_geometry,
        image_width=image_width,
        image_height=image_height,
    )


def _class_analysis_resolve_persisted_review_class(
    *,
    event: Mapping[str, Any],
    label_lines: Iterable[str],
    labelmap: Sequence[str],
    target_bbox: Sequence[float],
    image_width: int,
    image_height: int,
    require_unique: bool,
) -> Optional[str]:
    if require_unique:
        frozen_geometry = _class_analysis_exact_frozen_review_geometry(
            event,
            image_width=image_width,
            image_height=image_height,
        )
        if frozen_geometry is None:
            return None
        matching_geometry_count = 0
        resolved_class: Optional[str] = None
        for line in label_lines:
            parsed, class_id = _class_analysis_parse_yolo_geometry_for_identity(
                line,
                image_width=image_width,
                image_height=image_height,
            )
            if not isinstance(parsed, Mapping):
                continue
            candidate_geometry = _class_analysis_canonical_review_geometry(
                parsed,
                image_width=image_width,
                image_height=image_height,
            )
            if candidate_geometry != frozen_geometry:
                continue
            matching_geometry_count += 1
            if class_id is not None and 0 <= class_id < len(labelmap):
                resolved_class = str(labelmap[class_id] or "").strip() or None
            else:
                resolved_class = None
        return resolved_class if matching_geometry_count == 1 else None

    best_iou = 0.0
    resolved_class = None
    for line in label_lines:
        parsed = _class_analysis_parse_yolo_geometry(
            line,
            image_width=image_width,
            image_height=image_height,
        )
        if not isinstance(parsed, Mapping):
            continue
        candidate_bbox = parsed.get("bbox_xyxy") or []
        iou = _class_analysis_bbox_iou(target_bbox, candidate_bbox)
        class_id = int(parsed.get("class_id") or 0)
        if (
            iou > best_iou
            and iou >= 0.98
            and 0 <= class_id < len(labelmap)
        ):
            best_iou = iou
            resolved_class = str(labelmap[class_id] or "").strip() or None
    return resolved_class


def _class_analysis_crop_bounds(
    bbox_xyxy: Sequence[float],
    *,
    image_width: int,
    image_height: int,
    crop_mode: str,
    padding_ratio: float,
) -> Tuple[int, int, int, int]:
    return _embedding_crop_bounds(
        bbox_xyxy,
        image_width=image_width,
        image_height=image_height,
        crop_mode=crop_mode,
        padding_ratio=padding_ratio,
    )


def _class_analysis_cache_digest(value: Any) -> str:
    payload = json.dumps(_class_analysis_json_safe(value), sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _class_analysis_canonical_review_geometry(
    parsed: Mapping[str, Any],
    *,
    image_width: Optional[int] = None,
    image_height: Optional[int] = None,
) -> Dict[str, Any]:
    """Return a stable geometry identity independent of harmless YOLO rewrites.

    Dataset-backed editing serializes normalized YOLO coordinates to six
    decimal places. Fingerprinting higher-precision pixel coordinates made a
    hydrate/save round trip look like a different object. In production the
    image dimensions are available, so use the same normalized six-decimal
    representation as the editor.
    """

    bbox_raw = list(parsed.get("bbox_xyxy") or [])[:4]
    bbox = [round(float(value), 6) for value in bbox_raw]
    kind = str(parsed.get("kind") or "bbox").strip().lower()
    width = float(image_width or 0)
    height = float(image_height or 0)
    normalized = width > 0 and height > 0
    if kind != "polygon":
        if normalized and len(bbox) == 4:
            x1, y1, x2, y2 = bbox
            return {
                "kind": "bbox",
                "coordinate_space": "normalized_6dp",
                "bbox_cxcywh": [
                    round(((x1 + x2) / 2.0) / width, 6),
                    round(((y1 + y2) / 2.0) / height, 6),
                    round((x2 - x1) / width, 6),
                    round((y2 - y1) / height, 6),
                ],
            }
        return {"kind": "bbox", "bbox_xyxy": bbox}

    points = [
        (
            round(float(pair[0]) / width, 6)
            if normalized
            else round(float(pair[0]), 6),
            round(float(pair[1]) / height, 6)
            if normalized
            else round(float(pair[1]), 6),
        )
        for pair in (parsed.get("points") or [])
        if isinstance(pair, (list, tuple)) and len(pair) >= 2
    ]
    if len(points) > 1 and points[0] == points[-1]:
        points.pop()
    if not points:
        return {"kind": "polygon", "bbox_xyxy": bbox, "points": []}

    # YOLO polygon rings may be serialized clockwise or counter-clockwise and
    # may start at any vertex. Choose the lexicographically smallest rotation
    # across both directions so those order-only changes do not resurrect an
    # already-reviewed object.
    rotations: List[Tuple[Tuple[float, float], ...]] = []
    for candidate in (points, list(reversed(points))):
        rotations.extend(
            tuple(candidate[offset:] + candidate[:offset])
            for offset in range(len(candidate))
        )
    canonical_points = min(rotations)
    canonical: Dict[str, Any] = {
        "kind": "polygon",
        "points": [[x, y] for x, y in canonical_points],
    }
    if normalized:
        canonical["coordinate_space"] = "normalized_6dp"
    else:
        canonical["bbox_xyxy"] = bbox
    return canonical


def _class_analysis_review_object_key(
    *,
    source_key: str,
    image_sha256: str,
    split: str,
    image_relpath: str,
    class_name: str,
    geometry: Mapping[str, Any],
    image_width: Optional[int] = None,
    image_height: Optional[int] = None,
    annotation_entity_id: str = "",
) -> str:
    """Fingerprint one annotation without depending on label-file line order."""

    stable_entity_id = str(annotation_entity_id or "").strip()
    if stable_entity_id:
        return f"cro_{hashlib.sha256(('entity:' + stable_entity_id).encode('utf-8')).hexdigest()}"

    raw_source_key = str(source_key or "").strip()
    if raw_source_key.startswith("active:"):
        # Active snapshot ids cover the whole image set. Keeping that hash in
        # an object identity would invalidate every human decision whenever an
        # unrelated image is added or removed.
        source_scope = "active_workspace"
    elif raw_source_key.startswith("transient:"):
        source_scope = "transient_workspace"
    else:
        # Linked dataset ids are durable and prevent identical exported assets
        # in distinct registered datasets from sharing review decisions.
        source_scope = raw_source_key
    identity = {
        "schema": CLASS_ANALYSIS_REVIEW_OBJECT_KEY_SCHEMA,
        "source_scope": source_scope,
        "image_sha256": str(image_sha256 or "").strip().lower(),
        "split": _annotation_normalise_split(split),
        "image_relpath": _annotation_normalise_image_relpath(image_relpath).as_posix(),
        "class_name": str(class_name or "").strip(),
        "geometry": _class_analysis_canonical_review_geometry(
            geometry,
            image_width=image_width,
            image_height=image_height,
        ),
    }
    encoded = json.dumps(
        _class_analysis_json_safe(identity),
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    return f"cro_{hashlib.sha256(encoded.encode('utf-8')).hexdigest()}"


def _class_analysis_file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


def _class_analysis_file_snapshot_cached(path: Path) -> Dict[str, Any]:
    """Return a cached digest together with the exact opened-file identity."""

    resolved = Path(path).resolve(strict=True)
    with _class_analysis_open_regular_binary_nofollow(resolved) as (
        handle,
        opened_stat,
    ):
        opened_identity = _class_analysis_artifact_stat_identity(opened_stat)
        key = (
            str(resolved),
            opened_identity["device"],
            opened_identity["inode"],
            opened_identity["size"],
            opened_identity["mtime_ns"],
            opened_identity["ctime_ns"],
        )
        with CLASS_ANALYSIS_FILE_HASH_CACHE_LOCK:
            cached = CLASS_ANALYSIS_FILE_HASH_CACHE.get(key)
        if cached:
            if _class_analysis_artifact_stat_identity(
                os.fstat(handle.fileno())
            ) != opened_identity:
                raise ValueError("class_analysis_hash_source_changed")
            digest = cached
        else:
            digest = _class_analysis_binary_handle_sha256(handle)
            if _class_analysis_artifact_stat_identity(
                os.fstat(handle.fileno())
            ) != opened_identity:
                raise ValueError("class_analysis_hash_source_changed")
            with CLASS_ANALYSIS_FILE_HASH_CACHE_LOCK:
                if len(CLASS_ANALYSIS_FILE_HASH_CACHE) >= 100_000:
                    CLASS_ANALYSIS_FILE_HASH_CACHE.clear()
                CLASS_ANALYSIS_FILE_HASH_CACHE[key] = digest
    return {
        "sha256": digest,
        "bytes": opened_identity["size"],
        "file_identity": opened_identity,
        "resolved_path": str(resolved),
    }


def _class_analysis_file_sha256_cached(path: Path) -> str:
    return str(_class_analysis_file_snapshot_cached(path)["sha256"])


def _class_analysis_review_source_key_for_point(
    job: "ClassAnalysisJob",
    point: Mapping[str, Any],
) -> str:
    """Recover the source scope needed by legacy review metadata."""

    result_summary = (
        job.result.get("summary")
        if isinstance(job.result, dict) and isinstance(job.result.get("summary"), dict)
        else {}
    )
    for candidate in (
        point.get("source_key"),
        (job.summary or {}).get("source_key"),
        result_summary.get("source_key"),
    ):
        clean = str(candidate or "").strip()
        if clean:
            return clean

    request_payload = job.request if isinstance(job.request, dict) else {}
    source_mode = str(
        request_payload.get("source_mode") or request_payload.get("mode") or ""
    ).strip().lower()
    if source_mode in {"active_workspace", "workspace"}:
        source_id = str(
            request_payload.get("snapshot_id")
            or request_payload.get("workspace_id")
            or point.get("source_id")
            or (job.summary or {}).get("source_id")
            or job.job_id
        ).strip()
        return f"active:{source_id}" if source_id else ""
    if source_mode in {"dataset", "linked"}:
        dataset_id = str(
            request_payload.get("dataset_id")
            or point.get("source_id")
            or (job.summary or {}).get("source_id")
        ).strip()
        return f"linked:{dataset_id}" if dataset_id else ""
    if source_mode in {"transient", "open_path"}:
        session_id = str(
            request_payload.get("session_id")
            or point.get("source_id")
            or (job.summary or {}).get("source_id")
        ).strip()
        return f"transient:{session_id}" if session_id else ""
    return ""


def _class_analysis_backfill_review_object_key(
    job: "ClassAnalysisJob",
    point: Mapping[str, Any],
) -> Dict[str, Any]:
    """Derive a durable key for completed jobs created before key persistence.

    The completed job's indexed geometry remains the source of truth. A later
    bbox edit in the active labeling workspace must not make an already-rendered
    review button fail or silently target the edited geometry.
    """

    hydrated = dict(point)
    existing = str(hydrated.get("review_object_key") or "").strip()
    annotation_entity_id = str(
        hydrated.get("annotation_entity_id") or ""
    ).strip()
    raw_conflict = hydrated.get("dual_bbox_conflict")
    pair_review_key = str(
        hydrated.get("pair_review_key")
        or (
            raw_conflict.get("pair_review_key")
            if isinstance(raw_conflict, Mapping)
            else ""
        )
        or ""
    ).strip()
    if annotation_entity_id and not pair_review_key:
        hydrated["review_object_key"] = _class_analysis_review_object_key(
            source_key="",
            image_sha256="",
            split="",
            image_relpath="",
            class_name="",
            geometry={},
            annotation_entity_id=annotation_entity_id,
        )
        return hydrated
    if re.fullmatch(r"cro_[0-9a-f]{64}", existing):
        return hydrated

    source_key = _class_analysis_review_source_key_for_point(job, hydrated)
    if not source_key:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_object_key_missing",
        )

    source = _class_analysis_source_locator(job.request)
    split = _annotation_normalise_split(hydrated.get("split"))
    rel = _annotation_normalise_image_relpath(hydrated.get("image_relpath"))
    image_path = _resolve_annotation_image_path(
        Path(source["dataset_root"]),
        str(source.get("yolo_layout") or "flat"),
        split,
        rel,
    )
    try:
        with Image.open(image_path) as loaded:
            image_width, image_height = loaded.size
    except Exception as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_object_key_missing",
        ) from exc

    geometry: Mapping[str, Any] = hydrated
    stored_label_line = str(hydrated.get("label_line") or "").strip()
    if stored_label_line:
        parsed = _class_analysis_parse_yolo_geometry(
            stored_label_line,
            image_width=int(image_width),
            image_height=int(image_height),
        )
        if parsed is not None:
            geometry = parsed

    image_sha256 = str(hydrated.get("image_sha256") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", image_sha256):
        image_sha256 = _class_analysis_file_sha256_cached(image_path)
    hydrated["review_object_key"] = _class_analysis_review_object_key(
        source_key=source_key,
        image_sha256=image_sha256,
        split=split,
        image_relpath=rel.as_posix(),
        class_name=str(hydrated.get("class_name") or ""),
        geometry=geometry,
        image_width=int(image_width),
        image_height=int(image_height),
        annotation_entity_id=annotation_entity_id,
    )
    hydrated["image_sha256"] = image_sha256
    return hydrated


def _class_analysis_dual_bbox_pair_key_from_object_keys(
    current_review_object_key: str,
    other_review_object_key: str,
) -> str:
    """Return the direction-independent key for two canonical annotations."""

    current_key = str(current_review_object_key or "").strip()
    other_key = str(other_review_object_key or "").strip()
    if (
        re.fullmatch(r"cro_[0-9a-f]{64}", current_key) is None
        or re.fullmatch(r"cro_[0-9a-f]{64}", other_key) is None
        or current_key == other_key
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_pair_identity_missing",
        )
    encoded = json.dumps(
        {
            "schema": CLASS_ANALYSIS_DUAL_BBOX_PAIR_KEY_SCHEMA,
            "annotation_review_object_keys": sorted(
                (current_key, other_key)
            ),
        },
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    return f"crp_{hashlib.sha256(encoded.encode('utf-8')).hexdigest()}"


def _class_analysis_dual_bbox_pair_review_key(
    job: "ClassAnalysisJob",
    point: Mapping[str, Any],
    conflict: Mapping[str, Any],
    *,
    source: Optional[Mapping[str, Any]] = None,
    image_identity_cache: Optional[
        Dict[Tuple[str, str], Tuple[int, int, str]]
    ] = None,
) -> Tuple[str, str, str]:
    """Bind one dual-box decision to the two immutable annotations.

    Point ids include label-line position, so they are useful for locating an
    analysis row but are not a durable pair identity.  The pair key is instead
    the ordered hash of the two canonical review-object keys.  This makes the
    same conflict resolve identically when it is presented from the opposite
    box on a later analysis.
    """

    current = _class_analysis_backfill_review_object_key(job, point)
    current_key = str(current.get("review_object_key") or "").strip()
    source_key = _class_analysis_review_source_key_for_point(job, current)
    if not source_key or not re.fullmatch(r"cro_[0-9a-f]{64}", current_key):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_pair_identity_missing",
        )
    other_class = str(
        conflict.get("other_class_name") or conflict.get("class_name") or ""
    ).strip()
    other_bbox = list(conflict.get("other_bbox_xyxy") or [])[:4]
    try:
        other_bbox = [float(value) for value in other_bbox]
    except (TypeError, ValueError) as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_pair_identity_missing",
        ) from exc
    if (
        not other_class
        or len(other_bbox) != 4
        or not all(math.isfinite(value) for value in other_bbox)
        or other_bbox[2] <= other_bbox[0]
        or other_bbox[3] <= other_bbox[1]
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_pair_identity_missing",
        )
    resolved_source = (
        dict(source)
        if isinstance(source, Mapping)
        else _class_analysis_source_locator(job.request)
    )
    split = _annotation_normalise_split(current.get("split"))
    rel = _annotation_normalise_image_relpath(current.get("image_relpath"))
    image_path = _resolve_annotation_image_path(
        Path(resolved_source["dataset_root"]),
        str(resolved_source.get("yolo_layout") or "flat"),
        split,
        rel,
    )
    image_cache_key = (split, rel.as_posix())
    cached_identity = (
        image_identity_cache.get(image_cache_key)
        if isinstance(image_identity_cache, dict)
        else None
    )
    if cached_identity is not None:
        image_width, image_height, image_sha256 = cached_identity
    else:
        try:
            with Image.open(image_path) as loaded:
                image_width, image_height = loaded.size
        except Exception as exc:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="dual_bbox_pair_identity_missing",
            ) from exc
        image_sha256 = str(
            current.get("image_sha256")
            or current.get("_image_sha256")
            or ""
        ).strip().lower()
        if not re.fullmatch(r"[0-9a-f]{64}", image_sha256):
            image_sha256 = _class_analysis_file_sha256_cached(image_path)
        if isinstance(image_identity_cache, dict):
            image_identity_cache[image_cache_key] = (
                int(image_width),
                int(image_height),
                image_sha256,
            )
    other_key = _class_analysis_review_object_key(
        source_key=source_key,
        image_sha256=image_sha256,
        split=split,
        image_relpath=rel.as_posix(),
        class_name=other_class,
        geometry={"kind": "bbox", "bbox_xyxy": other_bbox},
        image_width=int(image_width),
        image_height=int(image_height),
    )
    pair_key = _class_analysis_dual_bbox_pair_key_from_object_keys(
        current_key,
        other_key,
    )
    return pair_key, current_key, other_key


def _class_analysis_validated_dual_bbox_conflict(
    job: "ClassAnalysisJob",
    point: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> Tuple[Dict[str, Any], str, str, str]:
    """Validate a pair action exclusively against persisted analysis data."""

    conflict = point.get("dual_bbox_conflict")
    if not isinstance(conflict, Mapping) or conflict.get("enabled") is False:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_conflict_missing",
        )
    trusted = dict(conflict)
    point_id = str(point.get("point_id") or "").strip()
    conflict_point_id = str(trusted.get("point_id") or point_id).strip()
    other_point_id = str(trusted.get("other_point_id") or "").strip()
    requested_conflict = payload.get("dual_bbox_conflict")
    requested_conflict = (
        requested_conflict if isinstance(requested_conflict, Mapping) else {}
    )
    requested_other_id = str(
        requested_conflict.get("other_point_id")
        or payload.get("other_point_id")
        or ""
    ).strip()
    current_class = str(point.get("class_name") or "").strip()
    current_kind = str(point.get("kind") or "bbox").strip().lower()
    conflict_current_kind = str(
        trusted.get("current_geometry_kind") or current_kind
    ).strip().lower()
    conflict_other_kind = str(
        trusted.get("other_geometry_kind") or "bbox"
    ).strip().lower()
    conflict_current_class = str(
        trusted.get("current_class") or current_class
    ).strip()
    other_class = str(
        trusted.get("other_class_name") or trusted.get("class_name") or ""
    ).strip()
    target_bbox = list(trusted.get("target_bbox_xyxy") or [])[:4]
    point_bbox = list(point.get("bbox_xyxy") or [])[:4]
    other_bbox = list(trusted.get("other_bbox_xyxy") or [])[:4]
    try:
        target_bbox = [float(value) for value in target_bbox]
        point_bbox = [float(value) for value in point_bbox]
        other_bbox = [float(value) for value in other_bbox]
    except (TypeError, ValueError) as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_conflict_stale",
        ) from exc
    bbox_matches = (
        len(target_bbox) == 4
        and len(point_bbox) == 4
        and all(
            math.isclose(
                left,
                right,
                rel_tol=0.0,
                abs_tol=CLASS_ANALYSIS_DUAL_BBOX_COORDINATE_TOLERANCE,
            )
            for left, right in zip(target_bbox, point_bbox)
        )
    )
    geometry = _class_analysis_bbox_overlap_geometry(target_bbox, other_bbox)
    if (
        not point_id
        or conflict_point_id != point_id
        or not other_point_id
        or other_point_id == point_id
        or (requested_other_id and requested_other_id != other_point_id)
        or not current_class
        or current_kind != "bbox"
        or conflict_current_kind != "bbox"
        or conflict_other_kind != "bbox"
        or conflict_current_class != current_class
        or not other_class
        or other_class == current_class
        or not bbox_matches
        or geometry is None
        or str(geometry.get("relation") or "") != "duplicate_like"
        or str(
            trusted.get("relation")
            or geometry.get("relation")
            or ""
        ) != "duplicate_like"
        or _annotation_normalise_split(trusted.get("split"))
        != _annotation_normalise_split(point.get("split"))
        or _annotation_normalise_image_relpath(
            trusted.get("image_relpath") or point.get("image_relpath")
        )
        != _annotation_normalise_image_relpath(point.get("image_relpath"))
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_conflict_stale",
        )
    persisted_pair_key = str(trusted.get("pair_review_key") or "").strip()
    persisted_current_key = str(
        trusted.get("current_review_object_key") or ""
    ).strip()
    persisted_other_key = str(
        trusted.get("other_review_object_key") or ""
    ).strip()
    if any((persisted_pair_key, persisted_current_key, persisted_other_key)):
        hydrated = _class_analysis_backfill_review_object_key(job, point)
        point_review_key = str(
            hydrated.get("review_object_key") or ""
        ).strip()
        if (
            re.fullmatch(r"crp_[0-9a-f]{64}", persisted_pair_key) is None
            or re.fullmatch(r"cro_[0-9a-f]{64}", persisted_current_key) is None
            or re.fullmatch(r"cro_[0-9a-f]{64}", persisted_other_key) is None
            or persisted_current_key == persisted_other_key
            or point_review_key != persisted_current_key
            or _class_analysis_dual_bbox_pair_key_from_object_keys(
                persisted_current_key,
                persisted_other_key,
            )
            != persisted_pair_key
        ):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="dual_bbox_pair_identity_missing",
            )
        pair_key = persisted_pair_key
        current_key = persisted_current_key
        other_key = persisted_other_key
    else:
        # Compatibility for analyses created before canonical pair identities
        # were persisted. Modern history deletion never depends on a mutable
        # source image merely to rediscover an already-frozen pair key.
        pair_key, current_key, other_key = (
            _class_analysis_dual_bbox_pair_review_key(job, point, trusted)
        )
    trusted["pair_review_key"] = pair_key
    trusted["current_review_object_key"] = current_key
    trusted["other_review_object_key"] = other_key
    return trusted, pair_key, current_key, other_key


def _class_analysis_point_is_dual_bbox_resolution_task(
    point: Mapping[str, Any],
) -> bool:
    """Return whether one persisted point requires pair-level review actions.

    Some older analysis snapshots carried lightweight overlap diagnostics under
    ``dual_bbox_conflict`` without representing the exact two-annotation
    resolution workflow.  The pair-only guard therefore keys off the canonical
    review mode and complete pair identity/geometry, rather than the mere
    presence of diagnostic overlap context.
    """

    conflict = point.get("dual_bbox_conflict")
    if not isinstance(conflict, Mapping) or conflict.get("enabled") is False:
        return False
    review_mode = str(conflict.get("review_mode") or "").strip()
    point_id = str(point.get("point_id") or conflict.get("point_id") or "").strip()
    conflict_point_id = str(conflict.get("point_id") or point_id).strip()
    other_point_id = str(conflict.get("other_point_id") or "").strip()
    current_class = str(
        conflict.get("current_class") or point.get("class_name") or ""
    ).strip()
    other_class = str(
        conflict.get("other_class_name") or conflict.get("class_name") or ""
    ).strip()

    def _is_bbox(value: Any) -> bool:
        try:
            coordinates = [float(item) for item in list(value or [])[:4]]
        except (TypeError, ValueError, OverflowError):
            return False
        return len(coordinates) == 4 and all(
            math.isfinite(item) for item in coordinates
        )

    return bool(
        review_mode.startswith("dual_bbox_annotation_resolution")
        and point_id
        and conflict_point_id == point_id
        and other_point_id
        and other_point_id != point_id
        and current_class
        and other_class
        and current_class != other_class
        and _is_bbox(
            conflict.get("target_bbox_xyxy") or point.get("bbox_xyxy")
        )
        and _is_bbox(conflict.get("other_bbox_xyxy"))
    )


def _class_analysis_require_dual_bbox_pair_action(
    point: Mapping[str, Any],
    *,
    action: str,
    allow_pair_clear: bool = False,
) -> None:
    """Reject ordinary single-object controls for an exact dual-bbox task."""

    if not _class_analysis_point_is_dual_bbox_resolution_task(point):
        return
    safe_action = str(action or "").strip().lower()
    if safe_action in CLASS_ANALYSIS_DUAL_BBOX_REVIEW_DISPOSITIONS:
        return
    if safe_action == "clear" and allow_pair_clear:
        return
    if safe_action in {"undo_review", "discard"}:
        return
    raise HTTPException(
        status_code=HTTP_409_CONFLICT,
        detail="dual_bbox_pair_action_required",
    )


def _class_analysis_dual_bbox_pair_resolution_record(
    *,
    action: str,
    point: Mapping[str, Any],
    conflict: Mapping[str, Any],
    pair_review_key: str,
    current_review_object_key: str,
    other_review_object_key: str,
    annotation_commit_attestation: Optional[Mapping[str, Any]],
) -> Dict[str, Any]:
    """Build one canonical, server-owned pair-decision record.

    The browser may identify the requested action, but pair identity always
    comes from the persisted analysis and canonical review-object keys.  This
    record is shared by the durable disposition ledger and the opt-in training
    corpus so the two stores cannot describe different annotation pairs.
    """

    safe_action = str(action or "").strip().lower()
    if safe_action not in CLASS_ANALYSIS_DUAL_BBOX_REVIEW_DISPOSITIONS:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="dual_bbox_disposition_invalid",
        )
    current_point_id = str(point.get("point_id") or "").strip()
    other_point_id = str(conflict.get("other_point_id") or "").strip()
    current_class = str(point.get("class_name") or "").strip()
    other_class = str(
        conflict.get("other_class_name")
        or conflict.get("class_name")
        or ""
    ).strip()
    safe_pair_key = str(pair_review_key or "").strip()
    safe_current_key = str(current_review_object_key or "").strip()
    safe_other_key = str(other_review_object_key or "").strip()
    if (
        not current_point_id
        or not other_point_id
        or current_point_id == other_point_id
        or not current_class
        or not other_class
        or current_class == other_class
        or re.fullmatch(r"crp_[0-9a-f]{64}", safe_pair_key) is None
        or re.fullmatch(r"cro_[0-9a-f]{64}", safe_current_key) is None
        or re.fullmatch(r"cro_[0-9a-f]{64}", safe_other_key) is None
        or safe_current_key == safe_other_key
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_pair_identity_missing",
        )
    delete_action = safe_action in {
        "delete_current_box",
        "delete_overlapping_box",
    }
    expected_deleted_point_id = (
        current_point_id
        if safe_action == "delete_current_box"
        else other_point_id
        if safe_action == "delete_overlapping_box"
        else ""
    )
    if delete_action:
        if not isinstance(annotation_commit_attestation, Mapping):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="dual_bbox_deletion_attestation_required",
            )
        safe_deleted_point_id = str(
            annotation_commit_attestation.get("deleted_point_id") or ""
        ).strip()
        if safe_deleted_point_id != expected_deleted_point_id:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="dual_bbox_deleted_point_mismatch",
            )
    else:
        safe_deleted_point_id = ""

    return {
        "schema": CLASS_ANALYSIS_DUAL_BBOX_PAIR_KEY_SCHEMA,
        "action": safe_action,
        "pair_review_key": safe_pair_key,
        "current_review_object_key": safe_current_key,
        "other_review_object_key": safe_other_key,
        "point_id": current_point_id,
        "other_point_id": other_point_id,
        "current_class": current_class,
        "other_class": other_class,
        "current_bbox_xyxy": [
            round(float(value), 6)
            for value in list(conflict.get("target_bbox_xyxy") or [])[:4]
        ],
        "other_bbox_xyxy": [
            round(float(value), 6)
            for value in list(conflict.get("other_bbox_xyxy") or [])[:4]
        ],
        "deleted_point_id": (
            safe_deleted_point_id if delete_action else ""
        ),
        "annotation_mutation_committed": bool(
            delete_action and isinstance(annotation_commit_attestation, Mapping)
        ),
        "annotation_commit_attestation": (
            copy.deepcopy(dict(annotation_commit_attestation))
            if delete_action and isinstance(annotation_commit_attestation, Mapping)
            else None
        ),
    }


def _class_analysis_embedding_head_cache_identity(
    head: Mapping[str, Any],
) -> Dict[str, Any]:
    """Describe every feature-producing input that affects cached values."""

    encoder_type = str(head.get("encoder_type") or "dinov3").strip().lower()
    identity: Dict[str, Any] = {
        "schema": CLASS_ANALYSIS_ENCODER_IDENTITY_SCHEMA,
        "encoder_type": encoder_type,
        "encoder_model": str(
            head.get("encoder_model") or head.get("clip_model") or ""
        ).strip(),
        "normalize_embeddings": bool(head.get("normalize_embeddings", True)),
        "dinov3_pooling": _embedding_normalize_dinov3_pooling(
            head.get("dinov3_pooling")
        ),
        "cradio_pooling": normalize_cradio_pooling(head.get("cradio_pooling")),
        "embedding_aggregation": _embedding_normalize_aggregation(
            head.get("embedding_aggregation")
        ),
        "embedding_salad_head_id": str(
            head.get("embedding_salad_head_id") or ""
        ).strip(),
        "embedding_salad_training_fingerprint": str(
            head.get("embedding_salad_training_fingerprint") or ""
        ),
        "salad_settings": {
            key: head.get(key)
            for key in (
                "salad_preset",
                "salad_num_clusters",
                "salad_cluster_dim",
                "salad_token_dim",
                "salad_hidden_dim",
                "salad_dropout",
                "salad_sinkhorn_iters",
                "salad_sinkhorn_reg",
                "salad_epochs",
                "salad_batch_size",
                "salad_max_train_objects",
                "salad_token_budget_mb",
                "salad_weight",
                "salad_learning_rate",
                "salad_weight_decay",
                "salad_temperature",
            )
            if head.get(key) is not None
        },
    }
    if encoder_type == "cradio":
        runtime = cradio_runtime_identity(
            identity["encoder_model"],
            requested_backend=head.get("cradio_backend"),
            pooling=identity["cradio_pooling"],
            output_mode=str(
                head.get("cradio_output_mode") or "summary_and_spatial"
            ),
        )
        cache_runtime = {
            key: runtime.get(key)
            for key in (
                "schema",
                "model",
                "requested_backend",
                "resolved_backend",
                "dtype",
                "transport",
                "implementation_abi",
                "input_size",
                "output_mode",
                "checkpoint_sha256",
                "checkpoint_bytes",
                "persistent_cache_safe",
                "compile_forward",
                "cider_fusion",
                "cider_fusion_targets",
            )
        }
        if not bool(runtime.get("persistent_cache_safe")):
            cache_runtime["process_epoch"] = CLASS_ANALYSIS_UNRESOLVED_RUNTIME_EPOCH
        identity["runtime"] = cache_runtime
    return identity


def _class_analysis_encoder_runtime_metadata(
    head: Mapping[str, Any],
) -> Dict[str, Any]:
    encoder_type = str(head.get("encoder_type") or "dinov3").strip().lower()
    if encoder_type == "cradio":
        runtime = cradio_runtime_identity(
            head.get("encoder_model") or head.get("clip_model"),
            requested_backend=head.get("cradio_backend"),
            pooling=head.get("cradio_pooling"),
            output_mode=str(
                head.get("cradio_output_mode") or "summary_and_spatial"
            ),
        )
        runtime.pop("checkpoint_path", None)
        return runtime
    return {
        "schema": CLASS_ANALYSIS_ENCODER_IDENTITY_SCHEMA,
        "model": str(
            head.get("encoder_model") or head.get("clip_model") or ""
        ),
        "resolved_backend": (
            str(dinov3_model_device or "unresolved")
            if encoder_type == "dinov3"
            else "torch"
        ),
        "pooling": str(head.get("dinov3_pooling") or ""),
        "persistent_cache_safe": True,
    }


def _class_analysis_feature_batch_plan(
    payload: Mapping[str, Any],
    head: Mapping[str, Any],
) -> Dict[str, Any]:
    """Resolve a measured default while preserving an explicit expert override."""

    policy = str(payload.get("feature_batch_policy") or "auto").strip().lower()
    if policy not in {"auto", "manual"}:
        policy = "auto"
    if policy == "manual":
        return {
            "policy": "manual",
            "batch_size": min(
                128,
                _coerce_int(payload.get("batch_size"), 8, minimum=1),
            ),
            "reason": "explicit_request",
        }

    encoder_type = str(head.get("encoder_type") or "dinov3").strip().lower()
    if encoder_type != "cradio":
        return {
            "policy": "encoder_default",
            "batch_size": 64,
            "reason": "non_cradio_default",
        }

    runtime = _class_analysis_encoder_runtime_metadata(head)
    if str(runtime.get("resolved_backend") or "") != "mlx":
        return {
            "policy": "torch_conservative",
            "batch_size": 4,
            "reason": "cradio_torch_fallback",
        }
    canonical_size = min(
        1024,
        _coerce_int(payload.get("canonical_size"), 336, minimum=64),
    )
    if canonical_size <= 352:
        batch_size = 12
    elif canonical_size <= 448:
        batch_size = 8
    else:
        batch_size = 4
    if "radiov4-h" in str(runtime.get("model") or "").lower():
        batch_size = max(1, batch_size // 2)
    return {
        "policy": CLASS_ANALYSIS_CRADIO_BATCH_POLICY,
        "batch_size": batch_size,
        "reason": "measured_native_mlx_throughput",
        "canonical_size": canonical_size,
        "compile_forward": bool(runtime.get("compile_forward")),
    }


def _class_analysis_image_pack_group_key(
    image_sha256: str,
    records: Sequence[Mapping[str, Any]],
) -> str:
    """Address one image chunk without binding it to mutable crop geometry."""

    slots: List[Any] = []
    for fallback_index, record in enumerate(records):
        slot = record.get("label_line_index")
        if slot is None:
            slot = record.get("image_row_index")
        if slot is None:
            slot = fallback_index
        slots.append(slot)
    return _class_analysis_cache_digest(
        {
            "version": CLASS_ANALYSIS_CACHE_VERSION,
            "image_sha256": str(image_sha256 or "").lower(),
            "annotation_slots": slots,
        }
    )


def _class_analysis_image_pack_path(image_pack_key: str, head: Mapping[str, Any]) -> Path:
    safe_key = re.sub(r"[^a-fA-F0-9]", "", str(image_pack_key or ""))[:64]
    if not safe_key:
        safe_key = hashlib.sha256(str(image_pack_key or "empty").encode("utf-8")).hexdigest()
    head_key = _class_analysis_cache_digest(
        _class_analysis_embedding_head_cache_identity(head)
    )[:20]
    return CLASS_ANALYSIS_CACHE_ROOT / "image_packs" / safe_key[:2] / f"{safe_key}-{head_key}.npz"


def _class_analysis_load_image_pack(
    image_pack_key: str,
    head: Mapping[str, Any],
    object_keys: Sequence[str],
    *,
    allow_partial: bool = False,
    diagnostics: Optional[Dict[str, Any]] = None,
) -> Optional[List[Optional[np.ndarray]]]:
    def note(**values: Any) -> None:
        if diagnostics is not None:
            diagnostics.update(values)

    cache_root = _class_analysis_cache_storage_root(create=False)
    if cache_root is None:
        note(status="cache_unavailable", bytes_read=0)
        return None
    path = _class_analysis_image_pack_path(image_pack_key, head)
    safe_path = _safe_existing_regular_file_within_root_impl(path, cache_root)
    if safe_path is None:
        note(status="cold", bytes_read=0)
        return None
    opened_identity: Optional[Tuple[int, int]] = None
    try:
        requested_keys = [str(value) for value in object_keys]
        with _class_analysis_open_regular_binary_nofollow(safe_path) as (
            handle,
            opened_stat,
        ):
            opened_identity = (
                int(opened_stat.st_dev),
                int(opened_stat.st_ino),
            )
            if int(opened_stat.st_size) > (
                CLASS_ANALYSIS_IMAGE_PACK_MAX_TOTAL_BYTES
                + 3 * CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES
                + 1024 * 1024
            ):
                raise ValueError("class_analysis_image_pack_too_large")
            headers = _class_analysis_preflight_npz_headers(
                handle,
                expected_arrays={
                    "version": {},
                    "object_keys": {},
                    "embeddings": {},
                },
                max_array_bytes=CLASS_ANALYSIS_IMAGE_PACK_MAX_ARRAY_BYTES,
                max_total_bytes=CLASS_ANALYSIS_IMAGE_PACK_MAX_TOTAL_BYTES,
            )
            version_header = headers["version"]
            keys_header = headers["object_keys"]
            embeddings_header = headers["embeddings"]
            stored_count = int(keys_header["shape"][0]) if len(keys_header["shape"]) == 1 else -1
            if (
                version_header["shape"] != (1,)
                or version_header["dtype"].kind not in {"U", "S"}
                or int(version_header["declared_bytes"]) > 4096
                or stored_count < 0
                or keys_header["dtype"].kind not in {"U", "S"}
                or int(keys_header["declared_bytes"])
                > CLASS_ANALYSIS_IMAGE_PACK_MAX_METADATA_BYTES
                or len(embeddings_header["shape"]) != 2
                or embeddings_header["shape"][0] != stored_count
                or embeddings_header["shape"][1] <= 0
                or embeddings_header["dtype"] != np.dtype(np.float32)
            ):
                raise ValueError("class_analysis_image_pack_contract_invalid")
            with np.load(
                handle,
                allow_pickle=False,
                max_header_size=CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES,
            ) as payload:
                version_array = np.asarray(payload["version"])
                key_array = np.asarray(payload["object_keys"])
                embeddings = np.asarray(payload["embeddings"])
            version = str(version_array[0])
            stored_keys = [str(value) for value in key_array.tolist()]
            if (
                version_array.shape != (1,)
                or version_array.dtype.kind not in {"U", "S"}
                or key_array.shape != (stored_count,)
                or key_array.dtype.kind not in {"U", "S"}
                or embeddings.shape != embeddings_header["shape"]
                or embeddings.dtype != np.dtype(np.float32)
                or version != CLASS_ANALYSIS_CACHE_VERSION
                or len(set(stored_keys)) != len(stored_keys)
                or not _class_analysis_array_all_finite_chunked(embeddings)
            ):
                raise ValueError("class_analysis_image_pack_payload_invalid")
            if _class_analysis_artifact_stat_identity(
                os.fstat(handle.fileno())
            ) != _class_analysis_artifact_stat_identity(opened_stat):
                raise ValueError("class_analysis_image_pack_changed")
            try:
                os.utime(handle.fileno(), None)
            except OSError:
                pass
        stored_by_key = {
            key: embeddings[idx].astype(np.float32, copy=False)
            for idx, key in enumerate(stored_keys)
        }
        resolved = [stored_by_key.get(key) for key in requested_keys]
        hit_count = sum(value is not None for value in resolved)
        note(
            status=(
                "full_hit"
                if hit_count == len(requested_keys)
                else "object_changed"
                if hit_count > 0
                else "object_set_changed"
            ),
            hits=hit_count,
            misses=max(0, len(requested_keys) - hit_count),
            bytes_read=int(safe_path.stat().st_size),
        )
        if not allow_partial and hit_count != len(requested_keys):
            return None
        return resolved
    except Exception as exc:
        note(status="invalid", error=str(exc), bytes_read=0)
        _class_analysis_remove_disposable_if_same_inode(
            safe_path,
            opened_identity,
        )
        return None


def _class_analysis_write_image_pack(
    image_pack_key: str,
    head: Mapping[str, Any],
    object_keys: Sequence[str],
    embeddings: Sequence[np.ndarray],
) -> bool:
    if not image_pack_key or not object_keys or len(object_keys) != len(embeddings):
        return False
    try:
        cache_root = _class_analysis_cache_storage_root(create=True)
        if cache_root is None:
            return False
        matrix = np.stack([np.asarray(item, dtype=np.float32) for item in embeddings], axis=0)
        _class_analysis_write_npz(
            _class_analysis_image_pack_path(image_pack_key, head),
            cache_root,
            version=np.asarray([CLASS_ANALYSIS_CACHE_VERSION]),
            object_keys=np.asarray([str(value) for value in object_keys]),
            embeddings=matrix,
        )
        return True
    except Exception:
        return False


def _class_analysis_embedding_cache_path(cache_key: str) -> Path:
    safe_key = re.sub(r"[^a-fA-F0-9]", "", str(cache_key or ""))[:64]
    if not safe_key:
        safe_key = hashlib.sha256(str(cache_key or "empty").encode("utf-8")).hexdigest()
    return CLASS_ANALYSIS_CACHE_ROOT / "embeddings" / safe_key[:2] / f"{safe_key}.npy"


def _class_analysis_thumbnail_cache_path(crop_cache_key: str) -> Path:
    safe_key = re.sub(r"[^a-fA-F0-9]", "", str(crop_cache_key or ""))[:64]
    if not safe_key:
        safe_key = hashlib.sha256(str(crop_cache_key or "empty").encode("utf-8")).hexdigest()
    return CLASS_ANALYSIS_CACHE_ROOT / "thumbnails" / safe_key[:2] / f"{safe_key}.jpg"


def _class_analysis_prepare_write_path(path: Path, root: Path) -> Optional[Path]:
    try:
        root_resolved = root.resolve()
        if _storage_path_has_symlink_component(root):
            return None
        raw_path = Path(path)
        parent = raw_path.parent
        if _storage_path_has_symlink_component(parent):
            return None
        parent_resolved = parent.resolve(strict=False)
        if not _path_is_within_root_impl(parent_resolved, root_resolved):
            return None
        parent.mkdir(parents=True, exist_ok=True)
        if _storage_path_has_symlink_component(parent):
            return None
        if raw_path.is_symlink():
            raw_path.unlink(missing_ok=True)
        elif raw_path.exists() and raw_path.is_dir():
            return None
        target_resolved = raw_path.resolve(strict=False)
    except Exception:
        return None
    if not _path_is_within_root_impl(target_resolved, root_resolved):
        return None
    return raw_path


def _class_analysis_prepare_dir(path: Path, root: Path) -> Optional[Path]:
    try:
        root_resolved = root.resolve()
        if _storage_path_has_symlink_component(root):
            return None
        raw_path = Path(path)
        if _storage_path_has_symlink_component(raw_path):
            return None
        parent_resolved = raw_path.parent.resolve(strict=False)
        if not _path_is_within_root_impl(parent_resolved, root_resolved):
            return None
        raw_path.mkdir(parents=True, exist_ok=True)
        if _storage_path_has_symlink_component(raw_path) or not raw_path.is_dir():
            return None
        resolved = raw_path.resolve(strict=True)
    except Exception:
        return None
    if not _path_is_within_root_impl(resolved, root_resolved):
        return None
    return resolved


def _class_analysis_prepare_private_audit_dir(
    path: Path,
    root: Path,
    *,
    detail: str,
) -> Path:
    """Create one private audit directory and persist its parent entry."""

    raw_path = Path(path)
    existed = raw_path.exists() and raw_path.is_dir() and not raw_path.is_symlink()
    prepared = _class_analysis_prepare_dir(raw_path, root)
    if prepared is None:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail=detail,
        )
    try:
        previous_mode = int(prepared.stat().st_mode) & 0o777
        os.chmod(prepared, 0o700)
        if not existed or previous_mode != 0o700:
            _fsync_directory(prepared)
            _fsync_directory(prepared.parent)
    except Exception as exc:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail=detail,
        ) from exc
    return prepared


def _class_analysis_write_json(
    path: Path,
    root: Path,
    value: Any,
    *,
    artifact_snapshot: Optional[Dict[str, Any]] = None,
) -> Path:
    # ``result.json`` can contain hundreds of thousands of graph points.  A
    # recursive ``_class_analysis_json_safe`` copy followed by ``json.dumps``
    # briefly retained both a second Python object graph and the complete JSON
    # string.  Stream encoder chunks directly into the existing atomic binary
    # writer instead.  NumPy values are converted only when the encoder reaches
    # them; the public result path removes the large coordinate arrays before
    # this writer runs.
    encoder = json.JSONEncoder(
        ensure_ascii=False,
        indent=2,
        default=_class_analysis_json_encoder_default,
    )

    written_sha256 = hashlib.sha256()
    written_bytes = 0

    def writer(handle: Any) -> None:
        nonlocal written_bytes
        buffered = bytearray()
        for chunk in encoder.iterencode(value):
            encoded = chunk.encode("utf-8")
            if buffered and len(buffered) + len(encoded) > 1024 * 1024:
                handle.write(buffered)
                written_sha256.update(buffered)
                written_bytes += len(buffered)
                buffered.clear()
            buffered.extend(encoded)
        if buffered:
            handle.write(buffered)
            written_sha256.update(buffered)
            written_bytes += len(buffered)

    _write_binary_within_root_atomic(
        path,
        root,
        writer,
        detail="class_analysis_write_path_forbidden",
        context="class analysis",
    )
    if artifact_snapshot is not None:
        artifact_snapshot.clear()
        artifact_snapshot.update(
            {
                # Identity is intentional: the digest above was produced by
                # encoding this exact object graph.
                "payload": value,
                "sha256": written_sha256.hexdigest(),
                "bytes": int(written_bytes),
            }
        )
    return path


def _class_analysis_write_audit_json(
    path: Path,
    root: Path,
    value: Any,
    *,
    detail: str,
) -> Path:
    _write_text_within_root_atomic(
        path,
        root,
        json.dumps(_class_analysis_json_safe(value), ensure_ascii=False, indent=2),
        detail=detail,
        context="class analysis audit",
        file_mode=0o600,
        durable=True,
        error_status_code=HTTP_500_INTERNAL_SERVER_ERROR,
    )
    return path


def _class_analysis_write_audit_binary(
    path: Path,
    root: Path,
    writer: Callable[[Any], None],
    *,
    detail: str,
) -> Path:
    _write_binary_within_root_atomic(
        path,
        root,
        writer,
        detail=detail,
        context="class analysis audit",
        file_mode=0o600,
        durable=True,
        error_status_code=HTTP_500_INTERNAL_SERVER_ERROR,
    )
    return path


def _class_analysis_write_text(path: Path, root: Path, text: str) -> Path:
    _write_text_within_root_atomic(
        path,
        root,
        text,
        detail="class_analysis_write_path_forbidden",
        context="class analysis",
    )
    return path


def _class_analysis_review_disposition_root(
    *,
    create: bool,
    strict: bool = False,
) -> Optional[Path]:
    """Return the durable human-review ledger root.

    The ledger deliberately lives below ``audit``. Startup cleanup removes
    disposable analysis jobs and caches, but preserves this explicit human
    review history.
    """

    class_root = _class_analysis_storage_root(create=create)
    audit_root = class_root / "audit"
    ledger_root = audit_root / "human_review_dispositions"
    if create:
        _class_analysis_prepare_private_audit_dir(
            audit_root,
            class_root,
            detail="review_disposition_ledger_unavailable",
        )
        return _class_analysis_prepare_private_audit_dir(
            ledger_root,
            class_root,
            detail="review_disposition_ledger_unavailable",
        )
    if not ledger_root.exists() and not ledger_root.is_symlink():
        return None
    try:
        prepared = _class_analysis_prepare_private_audit_dir(
            ledger_root,
            class_root,
            detail="review_disposition_ledger_unavailable",
        )
    except HTTPException:
        if strict:
            raise
        return None
    return prepared


def _class_analysis_review_disposition_shard(
    review_object_key: str,
) -> Tuple[str, threading.Lock]:
    match = re.fullmatch(
        r"(?:cro|crp|crj)_([0-9a-f]{64})",
        str(review_object_key or "").strip(),
    )
    if match is None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_object_key_missing",
        )
    shard_id = match.group(1)[:2]
    return shard_id, CLASS_ANALYSIS_REVIEW_DISPOSITION_LOCKS[int(shard_id, 16)]


def _class_analysis_review_reassignment_key(
    review_object_key: str,
    analysis_job_id: str,
) -> str:
    """Scope a class correction to the frozen analysis that proposed it.

    Ordinary confirm/skip decisions intentionally follow the same class and
    geometry across analyses. A class correction must not: if an operator
    later changes the object back to its old class, an old A->B decision must
    not suppress the new A annotation. The originating analysis id is
    therefore part of this ledger identity.
    """

    source_key = str(review_object_key or "").strip()
    job_id = str(analysis_job_id or "").strip()
    if (
        re.fullmatch(r"cro_[0-9a-f]{64}", source_key) is None
        or not job_id
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_reassignment_identity_missing",
        )
    digest = hashlib.sha256(
        json.dumps(
            {
                "schema": CLASS_ANALYSIS_REVIEW_REASSIGNMENT_KEY_SCHEMA,
                "analysis_job_id": job_id,
                "source_review_object_key": source_key,
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    # Keep the job-scoped key in the same physical shard as its source
    # object. This lets one shard lock atomically arbitrate a global
    # confirm/skip row (cro_) against the same job's class correction (crj_)
    # instead of allowing contradictory rows in two independently committed
    # files.
    source_digest = source_key.removeprefix("cro_")
    return f"crj_{source_digest[:2]}{digest[2:]}"


@contextmanager
def _class_analysis_review_disposition_file_lock(
    ledger_root: Path,
    shard_id: str,
) -> Iterator[None]:
    """Serialize a shard read-modify-write across backend processes."""

    lock_path = _class_analysis_prepare_write_path(
        ledger_root / f".{shard_id}.lock",
        ledger_root,
    )
    if lock_path is None:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_unavailable",
        )
    flags = os.O_RDWR | os.O_CREAT | os.O_APPEND
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd: Optional[int] = None
    try:
        fd = os.open(lock_path, flags, 0o600)
        if hasattr(os, "fchmod"):
            os.fchmod(fd, 0o600)
    except Exception as exc:
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_unavailable",
        ) from exc
    with os.fdopen(fd, "a+b") as handle:
        fd = None  # fdopen owns and closes the descriptor from here.
        try:
            import fcntl

            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)

            def unlock() -> None:
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
        except ImportError:
            # Windows fallback. Lock one persistent byte at the start of the
            # shard lock file; the per-process threading lock still protects
            # callers in this interpreter.
            import msvcrt

            handle.seek(0)
            if handle.read(1) == b"":
                handle.seek(0)
                handle.write(b"\0")
                handle.flush()
            handle.seek(0)
            msvcrt.locking(handle.fileno(), msvcrt.LK_LOCK, 1)

            def unlock() -> None:
                handle.seek(0)
                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
        try:
            yield
        finally:
            unlock()


def _class_analysis_load_review_disposition_shard(
    ledger_root: Path,
    shard_id: str,
    *,
    strict: bool,
) -> Dict[str, Any]:
    shard_path = ledger_root / f"{shard_id}.json"
    existing = _safe_existing_regular_file_within_root_impl(shard_path, ledger_root)
    if existing is None:
        if shard_path.exists() or shard_path.is_symlink():
            if strict:
                raise HTTPException(
                    status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                    detail="review_disposition_ledger_invalid",
                )
        return {
            "schema": CLASS_ANALYSIS_REVIEW_DISPOSITION_SCHEMA,
            "shard": shard_id,
            "entries": {},
            "deleted_action_ids": {},
        }
    try:
        if int(existing.stat().st_size) > 64 * 1024 * 1024:
            raise ValueError("review disposition shard is too large")
        payload = json.loads(existing.read_text(encoding="utf-8"))
        if (
            not isinstance(payload, dict)
            or payload.get("schema") != CLASS_ANALYSIS_REVIEW_DISPOSITION_SCHEMA
            or payload.get("shard") != shard_id
            or not isinstance(payload.get("entries"), dict)
            or (
                "deleted_action_ids" in payload
                and not isinstance(payload.get("deleted_action_ids"), dict)
            )
        ):
            raise ValueError("review disposition shard schema mismatch")
        payload.setdefault("deleted_action_ids", {})
        return payload
    except Exception as exc:
        if strict:
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                detail="review_disposition_ledger_invalid",
            ) from exc
        logger.error(
            "Ignoring unreadable class-analysis review disposition shard %s: %s",
            shard_id,
            exc,
        )
        return {
            "schema": CLASS_ANALYSIS_REVIEW_DISPOSITION_SCHEMA,
            "shard": shard_id,
            "entries": {},
            "deleted_action_ids": {},
        }


def _class_analysis_read_review_disposition_shard_bytes(
    ledger_root: Path,
    shard_id: str,
) -> bytes:
    """Read one existing shard exactly for same-request rollback."""

    shard_path = ledger_root / f"{shard_id}.json"
    existing = _safe_existing_regular_file_within_root_impl(
        shard_path,
        ledger_root,
    )
    if existing is None:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_invalid",
        )
    try:
        with _class_analysis_open_regular_binary_nofollow(existing) as (
            handle,
            opened_stat,
        ):
            if int(opened_stat.st_size) > 64 * 1024 * 1024:
                raise ValueError("review disposition shard is too large")
            original = handle.read((64 * 1024 * 1024) + 1)
        if len(original) > 64 * 1024 * 1024:
            raise ValueError("review disposition shard is too large")
        return bytes(original)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_invalid",
        ) from exc


def _class_analysis_restore_review_disposition_shard_bytes(
    ledger_root: Path,
    shard_id: str,
    original: bytes,
) -> None:
    """Atomically restore the exact pre-request bytes for one shard."""

    _write_binary_within_root_atomic(
        ledger_root / f"{shard_id}.json",
        ledger_root,
        lambda handle: handle.write(original),
        detail="review_disposition_ledger_unavailable",
        context="class analysis review disposition rollback",
        file_mode=0o600,
        durable=True,
        error_status_code=HTTP_500_INTERNAL_SERVER_ERROR,
    )


def _class_analysis_validated_review_disposition_entry(
    review_object_key: str,
    stored: Any,
) -> Tuple[str, float, str, Dict[str, Any]]:
    """Validate one requested ledger row before hydration or mutation.

    Corruption in an unrelated key or shard must not make healthy review
    history unavailable. Once a key is requested, however, silently treating
    an unusable row as absent would resurface an already-reviewed candidate and
    make the UI unable to clear it safely.
    """

    if not isinstance(stored, dict):
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_invalid",
        )
    stored_key = str(stored.get("review_object_key") or "").strip()
    stored_disposition = str(
        stored.get("disposition") or ""
    ).strip().lower()
    raw_reviewed_at = stored.get("updated_at")
    try:
        stored_reviewed_at = (
            float("nan")
            if isinstance(raw_reviewed_at, bool)
            else float(raw_reviewed_at)
        )
    except (TypeError, ValueError, OverflowError):
        stored_reviewed_at = float("nan")
    stored_revision = str(stored.get("entry_revision") or "").strip()
    stored_client_action_id = str(
        stored.get("client_action_id") or ""
    ).strip()
    stored_target_class = str(
        stored.get("target_class") or ""
    ).strip()
    stored_source_class = str(stored.get("class_name") or "").strip()
    stored_analysis_job_id = str(
        stored.get("analysis_job_id") or ""
    ).strip()
    stored_point_id = str(stored.get("point_id") or "").strip()
    stored_source_review_object_key = str(
        stored.get("source_review_object_key") or ""
    ).strip()
    stored_annotation_target = stored.get("annotation_target")
    stored_single_bbox_attestation = stored.get(
        "single_bbox_deletion_attestation"
    )
    stored_reassignment_attestation = stored.get(
        "class_reassignment_attestation"
    )
    normalized_annotation_target: Optional[Dict[str, str]] = None
    annotation_target_valid = True
    if stored_disposition == "reassign_class":
        try:
            normalized_annotation_target = (
                _class_analysis_vignette_training_annotation_target(
                    stored_annotation_target
                )
            )
        except HTTPException:
            annotation_target_valid = False
        if normalized_annotation_target != stored_annotation_target:
            annotation_target_valid = False
    single_bbox_attestation_valid = True
    if stored_disposition == "delete_bbox" and (
        stored_single_bbox_attestation is not None
    ):
        single_target_valid = False
        single_verified_at = float("nan")
        try:
            single_target = (
                _class_analysis_vignette_training_annotation_target(
                    stored_single_bbox_attestation.get("annotation_target")
                )
                if isinstance(stored_single_bbox_attestation, Mapping)
                else None
            )
            single_target_valid = bool(
                single_target is not None
                and single_target
                    == stored_single_bbox_attestation.get(
                        "annotation_target"
                    )
            )
            single_verified_at = float(
                stored_single_bbox_attestation.get("verified_at")
            )
        except (HTTPException, TypeError, ValueError, OverflowError):
            single_target_valid = False
        single_verification_method = str(
            stored_single_bbox_attestation.get("verification_method") or ""
        ) if isinstance(stored_single_bbox_attestation, Mapping) else ""
        single_is_already_absent = bool(
            single_verification_method
            == CLASS_ANALYSIS_SINGLE_BBOX_ALREADY_ABSENT_VERIFICATION_METHOD
        )
        single_transition_contract_valid = bool(
            single_verification_method
            == CLASS_ANALYSIS_SINGLE_BBOX_DELETION_LEGACY_VERIFICATION_METHOD
            or (
                single_verification_method
                == CLASS_ANALYSIS_SINGLE_BBOX_DELETION_VERIFICATION_METHOD
                and re.fullmatch(
                    r"[0-9a-f]{64}",
                    str(
                        stored_single_bbox_attestation.get(
                            "deleted_label_line_sha256"
                        )
                        or ""
                    ),
                )
                is not None
                and isinstance(
                    stored_single_bbox_attestation.get(
                        "deleted_label_line_index"
                    ),
                    int,
                )
                and not isinstance(
                    stored_single_bbox_attestation.get(
                        "deleted_label_line_index"
                    ),
                    bool,
                )
                and stored_single_bbox_attestation.get(
                    "deleted_label_line_index"
                )
                >= 0
            )
            or (
                single_is_already_absent
                and str(
                    stored_single_bbox_attestation.get("deletion_state")
                    or ""
                )
                == "already_absent"
                and not str(
                    stored_single_bbox_attestation.get(
                        "deleted_label_line_sha256"
                    )
                    or ""
                )
                and stored_single_bbox_attestation.get(
                    "deleted_label_line_index"
                )
                is None
            )
        )
        single_revision_contract_valid = bool(
            isinstance(stored_single_bbox_attestation, Mapping)
            and (
                    stored_single_bbox_attestation.get("before_revision")
                    == stored_single_bbox_attestation.get(
                        "committed_revision"
                    )
                )
                == single_is_already_absent
        )
        single_bbox_attestation_valid = bool(
            isinstance(stored_single_bbox_attestation, Mapping)
            and stored_single_bbox_attestation.get("schema")
                == CLASS_ANALYSIS_SINGLE_BBOX_DELETION_ATTESTATION_SCHEMA
            and stored_single_bbox_attestation.get("committed") is True
            and str(
                stored_single_bbox_attestation.get("review_object_key") or ""
            )
                == review_object_key
            and str(
                stored_single_bbox_attestation.get("analysis_job_id") or ""
            )
                == stored_analysis_job_id
            and str(
                stored_single_bbox_attestation.get("point_id") or ""
            )
                == stored_point_id
            and single_target_valid
            and re.fullmatch(
                r"alr1_[0-9a-f]{64}",
                str(
                    stored_single_bbox_attestation.get(
                        "before_revision"
                    )
                    or ""
                ),
            )
            is not None
            and re.fullmatch(
                r"alr1_[0-9a-f]{64}",
                str(
                    stored_single_bbox_attestation.get(
                        "committed_revision"
                    )
                    or ""
                ),
            )
            is not None
            and single_revision_contract_valid
            and re.fullmatch(
                r"asi1_[0-9a-f]{64}",
                str(
                    stored_single_bbox_attestation.get("source_identity")
                    or ""
                ),
            )
            is not None
            and re.fullmatch(
                r"[0-9a-f]{64}",
                str(
                    stored_single_bbox_attestation.get("image_sha256") or ""
                ),
            )
            is not None
            and isinstance(
                stored_single_bbox_attestation.get("committed_label_count"),
                int,
            )
            and not isinstance(
                stored_single_bbox_attestation.get("committed_label_count"),
                bool,
            )
            and stored_single_bbox_attestation.get("committed_label_count")
                >= 0
            and math.isfinite(single_verified_at)
            and single_verified_at > 0.0
            and single_transition_contract_valid
            and str(
                stored_single_bbox_attestation.get("attestation_sha256") or ""
            )
                == _class_analysis_single_bbox_deletion_attestation_hash(
                    stored_single_bbox_attestation
                )
        )
    elif stored_single_bbox_attestation is not None:
        single_bbox_attestation_valid = False
    reassignment_attestation_valid = True
    if (
        stored_disposition == "reassign_class"
        and stored_reassignment_attestation is not None
    ):
        reassignment_verified_at = float("nan")
        reassignment_geometry = (
            stored_reassignment_attestation.get("geometry_edit")
            if isinstance(stored_reassignment_attestation, Mapping)
            else None
        )
        try:
            reassignment_verified_at = float(
                stored_reassignment_attestation.get("verified_at")
            )
            reassignment_target = (
                _class_analysis_vignette_training_annotation_target(
                    stored_reassignment_attestation.get(
                        "annotation_target"
                    )
                )
            )
        except (HTTPException, TypeError, ValueError, OverflowError):
            reassignment_target = None
        reassignment_verification_method = str(
            stored_reassignment_attestation.get("verification_method") or ""
        ) if isinstance(stored_reassignment_attestation, Mapping) else ""
        reassignment_transition_mode = str(
            stored_reassignment_attestation.get("transition_mode") or ""
        ) if isinstance(stored_reassignment_attestation, Mapping) else ""
        reassignment_is_already_committed = bool(
            reassignment_verification_method
            == CLASS_ANALYSIS_CLASS_REASSIGNMENT_ALREADY_COMMITTED_VERIFICATION_METHOD
        )
        reassignment_revisions_match = bool(
            isinstance(stored_reassignment_attestation, Mapping)
            and str(
                stored_reassignment_attestation.get("before_revision") or ""
            )
            == str(
                stored_reassignment_attestation.get("committed_revision") or ""
            )
        )
        reassignment_transition_contract_valid = bool(
            (
                reassignment_is_already_committed
                and reassignment_transition_mode == "already_committed"
                and not str(
                    stored_reassignment_attestation.get(
                        "reconstructed_before_label_line_sha256"
                    )
                    or ""
                )
                and stored_reassignment_attestation.get(
                    "reconstructed_before_label_line_index"
                ) is None
            )
            or (
                not reassignment_is_already_committed
                and reassignment_transition_mode in {
                    "geometry_precommitted",
                    "geometry_and_class_same_commit",
                }
                and reassignment_verification_method
                    == CLASS_ANALYSIS_CLASS_REASSIGNMENT_VERIFICATION_METHOD
            )
        )
        reassignment_attestation_valid = bool(
            isinstance(stored_reassignment_attestation, Mapping)
            and stored_reassignment_attestation.get("schema")
                == CLASS_ANALYSIS_CLASS_REASSIGNMENT_ATTESTATION_SCHEMA
            and stored_reassignment_attestation.get("committed") is True
            and str(
                stored_reassignment_attestation.get("analysis_job_id") or ""
            ) == stored_analysis_job_id
            and str(stored_reassignment_attestation.get("point_id") or "")
                == stored_point_id
            and str(
                stored_reassignment_attestation.get(
                    "source_review_object_key"
                )
                or ""
            ) == stored_source_review_object_key
            and reassignment_target is not None
            and reassignment_target == normalized_annotation_target
            and str(
                stored_reassignment_attestation.get("before_class") or ""
            ) == stored_source_class
            and str(
                stored_reassignment_attestation.get("committed_class") or ""
            ) == stored_target_class
            and re.fullmatch(
                r"alr1_[0-9a-f]{64}",
                str(
                    stored_reassignment_attestation.get("before_revision")
                    or ""
                ),
            ) is not None
            and re.fullmatch(
                r"alr1_[0-9a-f]{64}",
                str(
                    stored_reassignment_attestation.get(
                        "committed_revision"
                    )
                    or ""
                ),
            ) is not None
            and reassignment_revisions_match
                == reassignment_is_already_committed
            and re.fullmatch(
                r"asi1_[0-9a-f]{64}",
                str(
                    stored_reassignment_attestation.get("source_identity")
                    or ""
                ),
            ) is not None
            and re.fullmatch(
                r"[0-9a-f]{64}",
                str(
                    stored_reassignment_attestation.get("image_sha256")
                    or ""
                ),
            ) is not None
            and isinstance(reassignment_geometry, Mapping)
            and reassignment_geometry.get("schema")
                == CLASS_ANALYSIS_BBOX_GEOMETRY_EDIT_SCHEMA
            and isinstance(reassignment_geometry.get("changed"), bool)
            and all(
                isinstance(reassignment_geometry.get(key), list)
                and len(reassignment_geometry.get(key)) == 4
                and all(
                    isinstance(value, (int, float))
                    and not isinstance(value, bool)
                    and math.isfinite(float(value))
                    for value in reassignment_geometry.get(key)
                )
                for key in (
                    "analysis_bbox_xyxy",
                    "committed_bbox_xyxy",
                )
            )
            and reassignment_transition_contract_valid
            and math.isfinite(reassignment_verified_at)
            and reassignment_verified_at > 0.0
            and str(
                stored_reassignment_attestation.get("attestation_sha256")
                or ""
            ) == _class_analysis_class_reassignment_attestation_hash(
                stored_reassignment_attestation
            )
        )
    elif stored_disposition != "reassign_class" and (
        stored_reassignment_attestation is not None
    ):
        reassignment_attestation_valid = False
    if (
        stored_key != review_object_key
        or stored_disposition not in CLASS_ANALYSIS_REVIEW_DISPOSITIONS
        or not math.isfinite(stored_reviewed_at)
        or stored_reviewed_at <= 0.0
        or (
            stored_revision
            and CLASS_ANALYSIS_REVIEW_ENTRY_REVISION_PATTERN.fullmatch(
                stored_revision
            )
            is None
        )
        or (
            stored_client_action_id
            and CLASS_ANALYSIS_REVIEW_CLIENT_ACTION_PATTERN.fullmatch(
                stored_client_action_id
            )
            is None
        )
        or (stored_client_action_id and not stored_revision)
        or (
            "training_capture_requested" in stored
            and not isinstance(
                stored.get("training_capture_requested"),
                bool,
            )
        )
        or (
            stored_disposition == "reassign_class"
            and (
                not stored_source_class
                or len(stored_source_class) > 512
                or not stored_target_class
                or len(stored_target_class) > 512
                or stored_target_class == stored_source_class
            )
        )
        or (
            stored_disposition != "reassign_class"
            and "target_class" in stored
        )
        or (
            stored_disposition == "reassign_class"
            and (
                not review_object_key.startswith("crj_")
                or re.fullmatch(
                    r"cro_[0-9a-f]{64}",
                    stored_source_review_object_key,
                )
                is None
                or not stored_analysis_job_id
                or _class_analysis_review_reassignment_key(
                    stored_source_review_object_key,
                    stored_analysis_job_id,
                )
                != review_object_key
            )
        )
        or (
            stored_disposition != "reassign_class"
            and (
                review_object_key.startswith("crj_")
                or "source_review_object_key" in stored
                or "annotation_target" in stored
            )
        )
        or not annotation_target_valid
        or not single_bbox_attestation_valid
        or not reassignment_attestation_valid
    ):
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_invalid",
        )

    pair_resolution = (
        stored.get("dual_bbox_pair_resolution")
        if isinstance(stored.get("dual_bbox_pair_resolution"), Mapping)
        else {}
    )
    if review_object_key.startswith("crp_"):
        if stored_disposition not in CLASS_ANALYSIS_DUAL_BBOX_REVIEW_DISPOSITIONS:
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                detail="review_disposition_ledger_invalid",
            )
        stored_pair_key = str(
            pair_resolution.get("pair_review_key") or ""
        ).strip()
        stored_current_key = str(
            pair_resolution.get("current_review_object_key") or ""
        ).strip()
        stored_other_key = str(
            pair_resolution.get("other_review_object_key") or ""
        ).strip()
        if (
            pair_resolution.get("schema")
            != CLASS_ANALYSIS_DUAL_BBOX_PAIR_KEY_SCHEMA
            or str(pair_resolution.get("action") or "").strip().lower()
            != stored_disposition
            or stored_pair_key != review_object_key
            or re.fullmatch(r"cro_[0-9a-f]{64}", stored_current_key)
            is None
            or re.fullmatch(r"cro_[0-9a-f]{64}", stored_other_key)
            is None
            or stored_current_key == stored_other_key
            or _class_analysis_dual_bbox_pair_key_from_object_keys(
                stored_current_key,
                stored_other_key,
            )
            != review_object_key
        ):
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                detail="review_disposition_ledger_invalid",
            )
        if stored_disposition in {
            "delete_current_box",
            "delete_overlapping_box",
        }:
            commit_attestation = pair_resolution.get(
                "annotation_commit_attestation"
            )
            if (
                not isinstance(commit_attestation, Mapping)
                or commit_attestation.get("schema")
                != CLASS_ANALYSIS_DUAL_BBOX_ANNOTATION_COMMIT_SCHEMA
                or commit_attestation.get("committed") is not True
                or str(commit_attestation.get("pair_review_key") or "")
                != review_object_key
                or str(commit_attestation.get("action") or "").strip()
                != stored_disposition
                or str(commit_attestation.get("attestation_sha256") or "")
                != _class_analysis_dual_bbox_commit_attestation_hash(
                    commit_attestation
                )
            ):
                raise HTTPException(
                    status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                    detail="review_disposition_ledger_invalid",
                )
    return (
        stored_disposition,
        stored_reviewed_at,
        stored_revision,
        dict(pair_resolution),
    )


def _class_analysis_lookup_review_dispositions(
    review_object_keys: Iterable[str],
) -> Dict[str, Dict[str, Any]]:
    keys_by_shard: Dict[str, Set[str]] = defaultdict(set)
    for raw_key in review_object_keys:
        key = str(raw_key or "").strip()
        try:
            shard_id, _lock = _class_analysis_review_disposition_shard(key)
        except HTTPException:
            continue
        keys_by_shard[shard_id].add(key)
    if not keys_by_shard:
        return {}
    ledger_root = _class_analysis_review_disposition_root(
        create=False,
        strict=True,
    )
    if ledger_root is None:
        return {}
    matches: Dict[str, Dict[str, Any]] = {}
    for shard_id, keys in keys_by_shard.items():
        lock = CLASS_ANALYSIS_REVIEW_DISPOSITION_LOCKS[int(shard_id, 16)]
        with lock:
            payload = _class_analysis_load_review_disposition_shard(
                ledger_root,
                shard_id,
                strict=True,
            )
        entries = payload.get("entries") if isinstance(payload, dict) else {}
        for key in keys:
            entry = entries.get(key) if isinstance(entries, dict) else None
            if entry is None:
                continue
            _class_analysis_validated_review_disposition_entry(key, entry)
            matches[key] = dict(entry)
    return matches


def _class_analysis_review_origin(value: Any) -> str:
    return (
        re.sub(r"[^A-Za-z0-9_.-]+", "_", str(value or "").strip())[:48]
        or "desktop"
    )


def _class_analysis_review_action_tombstone_key(
    client_action_id: str,
    review_object_key: str,
) -> str:
    return "rat1_" + hashlib.sha256(
        (
            str(client_action_id or "").strip()
            + "\x00"
            + str(review_object_key or "").strip()
        ).encode("utf-8")
    ).hexdigest()


def _class_analysis_validated_review_action_tombstone(
    client_action_id: str,
    stored: Any,
    *,
    expected_shard_id: str = "",
) -> Dict[str, Any]:
    if not isinstance(stored, Mapping):
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_invalid",
        )
    review_object_key = str(stored.get("review_object_key") or "").strip()
    entry_revision = str(stored.get("entry_revision") or "").strip()
    deleted_by = str(
        stored.get("deleted_by_client_action_id") or ""
    ).strip()
    try:
        deleted_at = float(stored.get("deleted_at"))
    except (TypeError, ValueError, OverflowError):
        deleted_at = float("nan")
    try:
        tombstone_shard_id, _lock = (
            _class_analysis_review_disposition_shard(review_object_key)
        )
    except HTTPException as exc:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_invalid",
        ) from exc
    if (
        stored.get("schema")
        != CLASS_ANALYSIS_REVIEW_ACTION_TOMBSTONE_SCHEMA
        or str(stored.get("client_action_id") or "").strip()
        != client_action_id
        or CLASS_ANALYSIS_REVIEW_CLIENT_ACTION_PATTERN.fullmatch(
            client_action_id
        )
        is None
        or (
            CLASS_ANALYSIS_REVIEW_ENTRY_REVISION_PATTERN.fullmatch(
                entry_revision
            )
            is None
        )
        or str(stored.get("disposition") or "").strip().lower()
        not in CLASS_ANALYSIS_REVIEW_DISPOSITIONS
        or not math.isfinite(deleted_at)
        or deleted_at <= 0.0
        or (
            deleted_by
            and CLASS_ANALYSIS_REVIEW_CLIENT_ACTION_PATTERN.fullmatch(
                deleted_by
            )
            is None
        )
        or not str(stored.get("reason") or "").strip()
        or len(str(stored.get("reason") or "").strip()) > 64
        or (
            expected_shard_id
            and tombstone_shard_id != expected_shard_id
        )
    ):
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_invalid",
        )
    return dict(stored)


def _class_analysis_tombstone_review_action(
    payload: MutableMapping[str, Any],
    stored: Any,
    *,
    reason: str,
    deleted_by_client_action_id: str = "",
    deleted_at: Optional[float] = None,
) -> None:
    if not isinstance(stored, Mapping):
        return
    client_action_id = str(stored.get("client_action_id") or "").strip()
    if CLASS_ANALYSIS_REVIEW_CLIENT_ACTION_PATTERN.fullmatch(
        client_action_id
    ) is None:
        return
    tombstones = payload.setdefault("deleted_action_ids", {})
    if not isinstance(tombstones, dict):
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_invalid",
        )
    timestamp = float(deleted_at if deleted_at is not None else time.time())
    tombstone_key = _class_analysis_review_action_tombstone_key(
        client_action_id,
        str(stored.get("review_object_key") or "").strip(),
    )
    tombstones.setdefault(tombstone_key, {
        "schema": CLASS_ANALYSIS_REVIEW_ACTION_TOMBSTONE_SCHEMA,
        "client_action_id": client_action_id,
        "review_object_key": str(
            stored.get("review_object_key") or ""
        ).strip(),
        "entry_revision": str(stored.get("entry_revision") or "").strip(),
        "disposition": str(stored.get("disposition") or "")
        .strip()
        .lower(),
        "deleted_at": timestamp,
        "reason": str(reason or "review_history_deleted").strip()[:64],
        "deleted_by_client_action_id": str(
            deleted_by_client_action_id or ""
        ).strip(),
    })


def _class_analysis_raise_if_review_action_tombstoned(
    payload: Mapping[str, Any],
    *,
    shard_id: str,
    client_action_id: str,
    review_object_key: str,
) -> None:
    if not client_action_id:
        return
    tombstones = payload.get("deleted_action_ids")
    if tombstones is None:
        return
    if not isinstance(tombstones, Mapping):
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_invalid",
        )
    stored = tombstones.get(
        _class_analysis_review_action_tombstone_key(
            client_action_id,
            review_object_key,
        )
    )
    if stored is None:
        # Compatibility with the brief development format that keyed a
        # tombstone by client token alone. New writes always use a compound
        # digest so one token reused for another object cannot overwrite or
        # block the original object's audit identity.
        legacy = tombstones.get(client_action_id)
        if (
            isinstance(legacy, Mapping)
            and str(legacy.get("review_object_key") or "").strip()
            == review_object_key
        ):
            stored = legacy
    if stored is None:
        return
    tombstone = _class_analysis_validated_review_action_tombstone(
        client_action_id,
        stored,
        expected_shard_id=shard_id,
    )
    raise HTTPException(
        status_code=HTTP_409_CONFLICT,
        detail={
            "code": "review_disposition_action_deleted",
            "review_object_key": str(
                tombstone.get("review_object_key") or review_object_key
            ),
        },
    )


def _class_analysis_preflight_review_action_tombstone(
    review_object_key: str,
    client_action_id: str,
) -> None:
    """Reject a deleted action token before expensive live-source checks.

    The writer performs the same check again while holding the shard lock, so
    this read-side fast path is an optimization and deterministic error
    contract, not the race-safety boundary.
    """

    shard_id, lock = _class_analysis_review_disposition_shard(
        review_object_key
    )
    ledger_root = _class_analysis_review_disposition_root(
        create=False,
        strict=True,
    )
    if ledger_root is None:
        return
    with lock:
        with _class_analysis_review_disposition_file_lock(
            ledger_root,
            shard_id,
        ):
            payload = _class_analysis_load_review_disposition_shard(
                ledger_root,
                shard_id,
                strict=True,
            )
            _class_analysis_raise_if_review_action_tombstoned(
                payload,
                shard_id=shard_id,
                client_action_id=client_action_id,
                review_object_key=review_object_key,
            )


def _class_analysis_single_bbox_attestation_stable_payload(
    value: Any,
) -> Optional[Dict[str, Any]]:
    if not isinstance(value, Mapping):
        return None
    return {
        key: _class_analysis_json_safe(value.get(key))
        for key in (
            "schema",
            "committed",
            "analysis_job_id",
            "point_id",
            "review_object_key",
            "annotation_target",
            "source_identity",
            "before_revision",
            "committed_revision",
            "image_sha256",
            "committed_label_count",
            "deletion_state",
            "deleted_label_line_sha256",
            "deleted_label_line_index",
            "verification_method",
        )
    }


def _class_analysis_class_reassignment_attestation_stable_payload(
    value: Any,
) -> Optional[Dict[str, Any]]:
    """Return the immutable proof fields used for idempotent retries."""

    if not isinstance(value, Mapping):
        return None
    return {
        key: _class_analysis_json_safe(value.get(key))
        for key in (
            "schema",
            "committed",
            "analysis_job_id",
            "point_id",
            "source_review_object_key",
            "annotation_target",
            "source_identity",
            "before_revision",
            "committed_revision",
            "image_sha256",
            "before_class",
            "committed_class",
            "committed_label_count",
            "committed_label_line_sha256",
            "committed_label_line_index",
            "reconstructed_before_label_line_sha256",
            "reconstructed_before_label_line_index",
            "transition_mode",
            "geometry_edit",
            "verification_method",
        )
    }


def _class_analysis_record_review_disposition_entry(
    *,
    result: Mapping[str, Any],
    point: Mapping[str, Any],
    disposition: str,
    origin: str,
    client_action_id: str = "",
    training_capture_requested: bool = False,
) -> Dict[str, Any]:
    review_object_key = str(point.get("review_object_key") or "").strip()
    shard_id, lock = _class_analysis_review_disposition_shard(review_object_key)
    ledger_root = _class_analysis_review_disposition_root(create=True)
    if ledger_root is None:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="review_disposition_ledger_unavailable",
        )
    summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
    analysis_job_id = str(summary.get("analysis_job_id") or "").strip()
    review_target_class = str(
        point.get("review_target_class") or ""
    ).strip()
    source_review_object_key = str(
        point.get("source_review_object_key") or ""
    ).strip()
    review_annotation_target = point.get("review_annotation_target")
    single_bbox_deletion_attestation = point.get(
        "single_bbox_deletion_attestation"
    )
    class_reassignment_attestation = point.get(
        "class_reassignment_attestation"
    )
    review_annotation_attestation = point.get(
        "review_annotation_attestation"
    )
    dual_bbox_pair_resolution = point.get(
        "dual_bbox_pair_resolution"
    )
    sibling_review_object_key = ""
    if disposition == "reassign_class":
        sibling_review_object_key = source_review_object_key
    elif (
        re.fullmatch(r"cro_[0-9a-f]{64}", review_object_key)
        and analysis_job_id
    ):
        sibling_review_object_key = _class_analysis_review_reassignment_key(
            review_object_key,
            analysis_job_id,
        )
    if sibling_review_object_key:
        sibling_shard_id, _sibling_lock = (
            _class_analysis_review_disposition_shard(
                sibling_review_object_key
            )
        )
        if sibling_shard_id != shard_id:
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                detail="review_disposition_sibling_shard_invalid",
            )
    now = time.time()
    clean_origin = _class_analysis_review_origin(origin)
    with lock:
        with _class_analysis_review_disposition_file_lock(ledger_root, shard_id):
            payload = _class_analysis_load_review_disposition_shard(
                ledger_root,
                shard_id,
                strict=True,
            )
            _class_analysis_raise_if_review_action_tombstoned(
                payload,
                shard_id=shard_id,
                client_action_id=client_action_id,
                review_object_key=review_object_key,
            )
            entries = payload["entries"]
            previous = entries.get(review_object_key)
            sibling = (
                entries.get(sibling_review_object_key)
                if sibling_review_object_key
                else None
            )
            if previous is not None:
                _class_analysis_validated_review_disposition_entry(
                    review_object_key,
                    previous,
                )
            if sibling is not None:
                _class_analysis_validated_review_disposition_entry(
                    sibling_review_object_key,
                    sibling,
                )
            if disposition != "reassign_class" and sibling is not None:
                # A class correction is the stronger, annotation-backed
                # decision for this frozen analysis. A stale tab must not add
                # a global confirm/skip row that would outlive the correction
                # and suppress a future intentionally changed-back object.
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail={
                        "code": "review_disposition_changed",
                        "review_object_key": sibling_review_object_key,
                    },
                )
            if (
                client_action_id
                and isinstance(previous, dict)
                and str(previous.get("client_action_id") or "")
                == client_action_id
            ):
                expected_analysis_job_id = analysis_job_id
                expected_point_id = str(point.get("point_id") or "")
                if (
                    str(previous.get("disposition") or "").strip().lower()
                    != disposition
                    or str(previous.get("analysis_job_id") or "")
                    != expected_analysis_job_id
                    or str(previous.get("point_id") or "")
                    != expected_point_id
                    or str(previous.get("origin") or "") != clean_origin
                    or not isinstance(
                        previous.get("training_capture_requested"),
                        bool,
                    )
                    or bool(previous.get("training_capture_requested"))
                    != bool(training_capture_requested)
                    or str(previous.get("target_class") or "").strip()
                    != review_target_class
                    or str(
                        previous.get("source_review_object_key") or ""
                    ).strip()
                    != source_review_object_key
                    or previous.get("annotation_target")
                    != review_annotation_target
                    or _class_analysis_json_safe(
                        previous.get("dual_bbox_pair_resolution")
                    )
                    != _class_analysis_json_safe(
                        dual_bbox_pair_resolution
                    )
                    or (
                        disposition == "delete_bbox"
                        and _class_analysis_single_bbox_attestation_stable_payload(
                            previous.get(
                                "single_bbox_deletion_attestation"
                            )
                        )
                        != _class_analysis_single_bbox_attestation_stable_payload(
                            single_bbox_deletion_attestation
                        )
                    )
                    or (
                        disposition != "delete_bbox"
                        and previous.get(
                            "single_bbox_deletion_attestation"
                        )
                        != single_bbox_deletion_attestation
                    )
                    or (
                        disposition == "reassign_class"
                        and _class_analysis_class_reassignment_attestation_stable_payload(
                            previous.get("class_reassignment_attestation")
                        )
                        != _class_analysis_class_reassignment_attestation_stable_payload(
                            class_reassignment_attestation
                        )
                    )
                    or (
                        disposition != "reassign_class"
                        and previous.get("class_reassignment_attestation")
                        != class_reassignment_attestation
                    )
                ):
                    raise HTTPException(
                        status_code=HTTP_409_CONFLICT,
                        detail="review_disposition_client_action_conflict",
                    )
                if (
                    disposition == "reassign_class"
                    and sibling_review_object_key
                    and sibling is not None
                ):
                    _class_analysis_tombstone_review_action(
                        payload,
                        sibling,
                        reason="superseded_by_class_reassignment",
                    )
                    entries.pop(sibling_review_object_key, None)
                    payload["updated_at"] = now
                    _class_analysis_write_audit_json(
                        ledger_root / f"{shard_id}.json",
                        ledger_root,
                        payload,
                        detail="review_disposition_ledger_unavailable",
                    )
                return {
                    **dict(previous),
                    "_idempotent_replay": True,
                }
            if client_action_id and previous is not None:
                # Production writes are create-once per durable review row.
                # A delayed retry carrying an older client token must never
                # overwrite a newer choice merely because the ledger stores
                # only the most recent receipt.  The user can explicitly
                # clear the current revision before recording another choice.
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail={
                        "code": "review_disposition_changed",
                        "review_object_key": review_object_key,
                    },
                )
            try:
                created_at = (
                    float(previous.get("created_at"))
                    if isinstance(previous, dict)
                    and previous.get("created_at") is not None
                    else now
                )
            except (TypeError, ValueError):
                created_at = now
            if not math.isfinite(created_at) or created_at <= 0.0:
                created_at = now
            raw_review_evidence = {
                "embedding_wrong_class_suspicion": point.get(
                    "embedding_wrong_class_suspicion"
                ),
                "same_class_neighbor_ratio": point.get(
                    "same_class_neighbor_ratio"
                ),
                "top_other_neighbor_ratio": point.get(
                    "top_other_neighbor_ratio"
                ),
                "suggested_neighbor_class": point.get(
                    "suggested_neighbor_class"
                ),
                "neighbor_class_counts": point.get("neighbor_class_counts"),
                "review_signals": point.get("review_signals"),
                "is_close_overlap_candidate": point.get(
                    "is_close_overlap_candidate"
                ),
                "close_overlap_matches": point.get("close_overlap_matches"),
                "is_dual_bbox_conflict": point.get("is_dual_bbox_conflict"),
                "dual_bbox_conflict": point.get("dual_bbox_conflict"),
            }
            # Preserve the established ledger shape for Stage-1-only review
            # actions. Refinement evidence is optional provenance and should
            # appear only when the reviewed point actually carries it.
            for refinement_key in (
                "is_rough_outlier_candidate",
                "include_in_refined_vignettes",
                "refined_outlier",
            ):
                if refinement_key in point:
                    raw_review_evidence[refinement_key] = point.get(
                        refinement_key
                    )
            for quality_key in (
                "quality_recipe",
                "quality_score",
                "compact_logistic_disagreement",
                "compact_neighbor_disagreement",
                "cradio_logistic_disagreement",
                "cradio_neighbor_disagreement",
                "el2n_score",
                "proposed_class",
                "proposed_class_differs",
                "bbox_global_percentile",
                "bbox_class_percentile",
                "bbox_global_quintile",
                "low_source_detail",
                "tiny_object",
                "adaptive_review_score",
                "learned_error_probability",
                "review_sampling_source",
            ):
                if quality_key in point:
                    raw_review_evidence[quality_key] = point.get(quality_key)
            entry = {
                "review_object_key": review_object_key,
                "entry_revision": f"rdr1_{uuid.uuid4().hex}",
                "disposition": disposition,
                "analysis_job_id": str(summary.get("analysis_job_id") or ""),
                "point_id": str(point.get("point_id") or ""),
                "source_mode": str(
                    summary.get("source_mode") or point.get("source_mode") or ""
                ),
                "source_id": str(
                    summary.get("source_id") or point.get("source_id") or ""
                ),
                "source_key": str(
                    summary.get("source_key") or point.get("source_key") or ""
                ),
                "split": str(point.get("split") or ""),
                "image_relpath": str(point.get("image_relpath") or ""),
                "class_name": str(point.get("class_name") or ""),
                "bbox_xyxy": [
                    round(float(value), 6)
                    for value in list(point.get("bbox_xyxy") or [])[:4]
                ],
                "raw_wrong_class_suspicion": point.get("wrong_class_suspicion"),
                "raw_wrong_class_review_reason": point.get("wrong_class_review_reason"),
                "raw_review_evidence": raw_review_evidence,
                "origin": clean_origin,
                "client_action_id": client_action_id,
                "training_capture_requested": bool(
                    training_capture_requested
                ),
                "created_at": created_at,
                "updated_at": now,
            }
            if isinstance(dual_bbox_pair_resolution, Mapping):
                entry["dual_bbox_pair_resolution"] = (
                    _class_analysis_json_safe(dual_bbox_pair_resolution)
                )
            if disposition == "reassign_class":
                entry["target_class"] = review_target_class
                entry["source_review_object_key"] = (
                    source_review_object_key
                )
                entry["annotation_target"] = copy.deepcopy(
                    review_annotation_target
                )
                if isinstance(class_reassignment_attestation, Mapping):
                    entry["class_reassignment_attestation"] = (
                        copy.deepcopy(dict(class_reassignment_attestation))
                    )
                if isinstance(sibling, dict):
                    entry["superseded_source_disposition"] = str(
                        sibling.get("disposition") or ""
                    )
                    entry["superseded_source_revision"] = str(
                        sibling.get("entry_revision") or ""
                    )
                    _class_analysis_tombstone_review_action(
                        payload,
                        sibling,
                        reason="superseded_by_class_reassignment",
                    )
                    entries.pop(sibling_review_object_key, None)
            if (
                disposition == "delete_bbox"
                and isinstance(single_bbox_deletion_attestation, Mapping)
            ):
                entry["single_bbox_deletion_attestation"] = copy.deepcopy(
                    dict(single_bbox_deletion_attestation)
                )
            if (
                disposition == "confirm_current"
                and isinstance(review_annotation_attestation, Mapping)
            ):
                entry["review_annotation_attestation"] = copy.deepcopy(
                    dict(review_annotation_attestation)
                )
            entries[review_object_key] = entry
            payload["updated_at"] = now
            _class_analysis_write_audit_json(
                ledger_root / f"{shard_id}.json",
                ledger_root,
                payload,
                detail="review_disposition_ledger_unavailable",
            )
    return entry


def _class_analysis_clear_review_disposition_entry(
    review_object_key: str,
    *,
    expected_revision: str,
    expected_reviewed_at: Optional[float],
) -> Optional[Dict[str, Any]]:
    shard_id, lock = _class_analysis_review_disposition_shard(review_object_key)
    ledger_root = _class_analysis_review_disposition_root(
        create=False,
        strict=True,
    )
    if ledger_root is None:
        return None
    with lock:
        with _class_analysis_review_disposition_file_lock(ledger_root, shard_id):
            payload = _class_analysis_load_review_disposition_shard(
                ledger_root,
                shard_id,
                strict=True,
            )
            previous = payload["entries"].get(review_object_key)
            if previous is None:
                return None
            (
                _stored_disposition,
                stored_reviewed_at,
                stored_revision,
                _pair_resolution,
            ) = _class_analysis_validated_review_disposition_entry(
                review_object_key,
                previous,
            )
            stale = (
                stored_revision != expected_revision
                if expected_revision
                else bool(stored_revision)
                or stored_reviewed_at != expected_reviewed_at
            )
            if stale:
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail={
                        "code": "review_disposition_changed",
                        "review_object_key": review_object_key,
                    },
                )
            previous = payload["entries"].pop(review_object_key, None)
            if previous is not None:
                _class_analysis_tombstone_review_action(
                    payload,
                    previous,
                    reason="review_restored_to_queue",
                )
                payload["updated_at"] = time.time()
                _class_analysis_write_audit_json(
                    ledger_root / f"{shard_id}.json",
                    ledger_root,
                    payload,
                    detail="review_disposition_ledger_unavailable",
                )
    return dict(previous) if isinstance(previous, dict) else None


def _class_analysis_backfill_legacy_dual_bbox_pair_identities(
    result: Dict[str, Any],
    *,
    job: Optional["ClassAnalysisJob"] = None,
) -> None:
    """Hydrate legacy pair keys in the transient public-result graph.

    Early completed analyses persisted the two point ids and exact box
    geometry but not the direction-independent ``crp_`` key.  Durable review
    dispositions are indexed by that key, so those immutable analyses would
    otherwise show an already-reviewed conflict again after reload.

    All-class results derive the pair from the canonical object keys already
    present on the two result rows.  Selected-class results may omit the other
    class from ``points``; only that compatibility path consults the
    server-owned source image metadata.  Work is linear in the public result,
    retains only rows referenced by legacy conflicts, and caches source image
    identity per image.  Nothing is written to ``result.json`` or labels.
    """

    if not isinstance(result, dict):
        return
    candidate_fields = (
        "wrong_class_candidates",
        "refinement_candidates",
        "vignette_candidates",
        "within_class_outlier_candidates",
    )
    candidate_collections: List[List[Any]] = []
    for field in candidate_fields:
        stored_rows = result.get(field)
        if not isinstance(stored_rows, list):
            continue
        # ``_class_analysis_public_result`` intentionally shallow-copies the
        # large candidate collections. Copy only their pointer arrays here;
        # individual legacy rows are cloned below before hydration so an
        # in-memory completed job remains as immutable as result.json.
        public_rows = list(stored_rows)
        result[field] = public_rows
        candidate_collections.append(public_rows)
    point_rows = (
        result.get("points")
        if isinstance(result.get("points"), list)
        else []
    )
    rows_with_legacy_conflicts: List[Dict[str, Any]] = []
    needed_point_ids: Set[str] = set()

    def _register_legacy_row(row: Any) -> bool:
        if not isinstance(row, dict):
            return False
        conflict = row.get("dual_bbox_conflict")
        if not isinstance(conflict, Mapping):
            return False
        pair_key = str(conflict.get("pair_review_key") or "").strip()
        current_key = str(
            conflict.get("current_review_object_key") or ""
        ).strip()
        other_key = str(
            conflict.get("other_review_object_key") or ""
        ).strip()
        if (
            re.fullmatch(r"crp_[0-9a-f]{64}", pair_key)
            and re.fullmatch(r"cro_[0-9a-f]{64}", current_key)
            and re.fullmatch(r"cro_[0-9a-f]{64}", other_key)
            and current_key != other_key
        ):
            return False
        current_point_id = str(
            row.get("point_id") or conflict.get("point_id") or ""
        ).strip()
        other_point_id = str(conflict.get("other_point_id") or "").strip()
        if (
            not current_point_id
            or not other_point_id
            or current_point_id == other_point_id
        ):
            return False
        rows_with_legacy_conflicts.append(row)
        needed_point_ids.update((current_point_id, other_point_id))
        return True

    for rows in candidate_collections:
        for index, stored_row in enumerate(rows):
            if not isinstance(stored_row, dict):
                continue
            public_row = dict(stored_row)
            if _register_legacy_row(public_row):
                rows[index] = public_row
    for row in point_rows:
        _register_legacy_row(row)
    if not rows_with_legacy_conflicts:
        return

    # Keep only the records needed by legacy conflicts.  Candidate rows are
    # applied after public points because they retain review_object_key in old
    # result schemas even when the compact public point projection does not.
    records_by_id: Dict[str, Dict[str, Any]] = {}
    for rows in (point_rows, *candidate_collections):
        for row in rows:
            if not isinstance(row, dict):
                continue
            point_id = str(row.get("point_id") or "").strip()
            if point_id not in needed_point_ids:
                continue
            records_by_id[point_id] = {
                **records_by_id.get(point_id, {}),
                **row,
            }

    def _bbox_matches(left: Any, right: Any) -> bool:
        try:
            left_values = [float(value) for value in list(left or [])[:4]]
            right_values = [float(value) for value in list(right or [])[:4]]
        except (TypeError, ValueError):
            return False
        return bool(
            len(left_values) == 4
            and len(right_values) == 4
            and all(math.isfinite(value) for value in left_values)
            and all(math.isfinite(value) for value in right_values)
            and all(
                math.isclose(a, b, rel_tol=0.0, abs_tol=1e-6)
                for a, b in zip(left_values, right_values)
            )
        )

    def _current_matches_conflict(
        current: Mapping[str, Any],
        conflict: Mapping[str, Any],
    ) -> bool:
        conflict_current_class = str(
            conflict.get("current_class")
            or current.get("class_name")
            or ""
        ).strip()
        try:
            return bool(
                str(current.get("kind") or "bbox").strip().lower()
                == "bbox"
                and str(current.get("class_name") or "").strip()
                == conflict_current_class
                and _bbox_matches(
                    current.get("bbox_xyxy"),
                    conflict.get("target_bbox_xyxy"),
                )
                and _annotation_normalise_split(current.get("split"))
                == _annotation_normalise_split(conflict.get("split"))
                and _annotation_normalise_image_relpath(
                    current.get("image_relpath")
                )
                == _annotation_normalise_image_relpath(
                    conflict.get("image_relpath")
                    or current.get("image_relpath")
                )
            )
        except HTTPException:
            return False

    def _records_match_conflict(
        current: Mapping[str, Any],
        other: Mapping[str, Any],
        conflict: Mapping[str, Any],
    ) -> bool:
        other_class = str(
            conflict.get("other_class_name")
            or conflict.get("class_name")
            or ""
        ).strip()
        try:
            return bool(
                _current_matches_conflict(current, conflict)
                and str(other.get("kind") or "bbox").strip().lower()
                == "bbox"
                and str(other.get("class_name") or "").strip()
                == other_class
                and _bbox_matches(
                    other.get("bbox_xyxy"),
                    conflict.get("other_bbox_xyxy"),
                )
                and _annotation_normalise_split(current.get("split"))
                == _annotation_normalise_split(other.get("split"))
                and _annotation_normalise_image_relpath(
                    current.get("image_relpath")
                )
                == _annotation_normalise_image_relpath(
                    other.get("image_relpath")
                )
            )
        except HTTPException:
            return False

    identity_by_direction: Dict[
        Tuple[str, str], Optional[Tuple[str, str, str]]
    ] = {}
    image_identity_cache: Dict[Tuple[str, str], Tuple[int, int, str]] = {}
    source: Optional[Mapping[str, Any]] = None
    source_resolved = False
    for row in rows_with_legacy_conflicts:
        conflict = row.get("dual_bbox_conflict")
        if not isinstance(conflict, Mapping):
            continue
        current_point_id = str(
            row.get("point_id") or conflict.get("point_id") or ""
        ).strip()
        other_point_id = str(conflict.get("other_point_id") or "").strip()
        direction_key = (current_point_id, other_point_id)
        if direction_key not in identity_by_direction:
            current = {
                **records_by_id.get(current_point_id, {}),
                **row,
            }
            other = records_by_id.get(other_point_id)
            identity: Optional[Tuple[str, str, str]] = None
            if (
                isinstance(other, Mapping)
                and _records_match_conflict(current, other, conflict)
            ):
                current_key = str(
                    current.get("review_object_key") or ""
                ).strip()
                other_key = str(
                    other.get("review_object_key") or ""
                ).strip()
                try:
                    identity = (
                        _class_analysis_dual_bbox_pair_key_from_object_keys(
                            current_key,
                            other_key,
                        ),
                        current_key,
                        other_key,
                    )
                except HTTPException:
                    identity = None
            if (
                identity is None
                and job is not None
                and _current_matches_conflict(current, conflict)
            ):
                if not source_resolved:
                    source_resolved = True
                    try:
                        source = _class_analysis_source_locator(job.request)
                    except Exception:
                        source = None
                if isinstance(source, Mapping):
                    try:
                        identity = _class_analysis_dual_bbox_pair_review_key(
                            job,
                            current,
                            conflict,
                            source=source,
                            image_identity_cache=image_identity_cache,
                        )
                    except HTTPException:
                        identity = None
            identity_by_direction[direction_key] = identity
        identity = identity_by_direction.get(direction_key)
        if identity is None:
            continue
        pair_key, current_key, other_key = identity
        existing_values = {
            "pair_review_key": str(
                conflict.get("pair_review_key") or ""
            ).strip(),
            "current_review_object_key": str(
                conflict.get("current_review_object_key") or ""
            ).strip(),
            "other_review_object_key": str(
                conflict.get("other_review_object_key") or ""
            ).strip(),
        }
        expected_values = {
            "pair_review_key": pair_key,
            "current_review_object_key": current_key,
            "other_review_object_key": other_key,
        }
        # Missing legacy fields may be filled. A conflicting persisted value
        # is evidence of a stale/corrupt artifact and must never be repaired by
        # guessing during a read.
        if any(
            existing_values[key]
            and existing_values[key] != expected_values[key]
            for key in expected_values
        ):
            continue
        row["dual_bbox_conflict"] = {
            **dict(conflict),
            **expected_values,
        }


def _class_analysis_review_object_key_from_row(row: Mapping[str, Any]) -> str:
    direct = str(row.get("review_object_key") or "").strip()
    if direct:
        return direct
    conflict = row.get("dual_bbox_conflict")
    return (
        str(conflict.get("current_review_object_key") or "").strip()
        if isinstance(conflict, Mapping)
        else ""
    )


def _class_analysis_disposition_keys_for_row(
    row: Mapping[str, Any],
    analysis_job_id: str,
) -> List[str]:
    keys: List[str] = []
    object_key = _class_analysis_review_object_key_from_row(row)
    if object_key:
        if analysis_job_id and re.fullmatch(r"cro_[0-9a-f]{64}", object_key):
            keys.append(
                _class_analysis_review_reassignment_key(
                    object_key,
                    analysis_job_id,
                )
            )
        keys.append(object_key)
    conflict = row.get("dual_bbox_conflict")
    if isinstance(conflict, Mapping):
        pair_key = str(conflict.get("pair_review_key") or "").strip()
        if re.fullmatch(r"crp_[0-9a-f]{64}", pair_key):
            keys.append(pair_key)
    return list(dict.fromkeys(keys))


def _class_analysis_point_review_keys(
    points: Iterable[Mapping[str, Any]],
) -> Dict[str, str]:
    return {
        str(point.get("point_id") or "").strip(): str(
            point.get("review_object_key") or ""
        ).strip()
        for point in points
        if isinstance(point, Mapping)
        and str(point.get("point_id") or "").strip()
        and str(point.get("review_object_key") or "").strip()
    }


def _class_analysis_apply_review_dispositions(
    result: Dict[str, Any],
    *,
    job: Optional["ClassAnalysisJob"] = None,
    point_review_keys: Optional[Mapping[str, str]] = None,
) -> Dict[str, Any]:
    """Overlay durable human dispositions onto a fresh public result.

    ``_class_analysis_public_result`` has already allocated the UI point
    dictionaries. Mutating those dictionaries here avoids cloning a second
    258k-object graph just to hide a few reviewed vignettes.
    """

    if not isinstance(result, dict):
        return {}
    _class_analysis_backfill_legacy_dual_bbox_pair_identities(
        result,
        job=job,
    )
    points = [
        point
        for point in (result.get("points") or [])
        if isinstance(point, dict)
    ]
    raw_candidates = [
        candidate
        for candidate in (result.get("wrong_class_candidates") or [])
        if isinstance(candidate, dict)
    ]
    refinement_candidates = [
        candidate
        for candidate in (result.get("refinement_candidates") or [])
        if isinstance(candidate, dict)
    ]
    vignette_candidates = [
        candidate
        for candidate in (result.get("vignette_candidates") or [])
        if isinstance(candidate, dict)
    ]
    within_class_candidates = [
        candidate
        for candidate in (result.get("within_class_outlier_candidates") or [])
        if isinstance(candidate, dict)
    ]

    analysis_job_id = str(
        (result.get("summary") or {}).get("analysis_job_id")
        or (job.job_id if job is not None else "")
        or ""
    ).strip()

    safe_point_review_keys = {
        str(point_id or "").strip(): str(review_key or "").strip()
        for point_id, review_key in (point_review_keys or {}).items()
        if str(point_id or "").strip() and str(review_key or "").strip()
    }

    def candidate_review_object_key(candidate: Mapping[str, Any]) -> str:
        direct = _class_analysis_review_object_key_from_row(candidate)
        if direct:
            return direct
        return safe_point_review_keys.get(
            str(candidate.get("point_id") or "").strip(),
            "",
        )

    def disposition_keys_for_candidate(
        candidate: Mapping[str, Any],
    ) -> List[str]:
        review_key = candidate_review_object_key(candidate)
        if review_key and not _class_analysis_review_object_key_from_row(candidate):
            candidate = {
                **dict(candidate),
                "review_object_key": review_key,
            }
        return _class_analysis_disposition_keys_for_row(
            candidate,
            analysis_job_id,
        )

    candidate_keys: List[str] = []
    for candidate in (
        raw_candidates
        + refinement_candidates
        + vignette_candidates
        + within_class_candidates
    ):
        candidate_keys.extend(disposition_keys_for_candidate(candidate))
    # Graph selection permits reviewing any real point, not only a detector
    # candidate. Include point identities so those durable receipts survive a
    # result reload while candidate statistics remain candidate-only below.
    for point in points:
        candidate_keys.extend(disposition_keys_for_candidate(point))
    dispositions = _class_analysis_lookup_review_dispositions(candidate_keys)
    # Skip is a navigation decision for one frozen analysis generation. Unlike
    # confirm/resolve receipts, it must not hide the same entity in a later run.
    dispositions = {
        key: entry
        for key, entry in dispositions.items()
        if not (
            str(entry.get("disposition") or "").strip().lower() == "skip"
            and str(entry.get("analysis_job_id") or "").strip()
            != analysis_job_id
        )
    }
    unverified_single_bbox_deletion_history_count = sum(
        1
        for entry in dispositions.values()
        if str(entry.get("disposition") or "").strip().lower()
        == "delete_bbox"
        and not isinstance(
            entry.get("single_bbox_deletion_attestation"), Mapping
        )
    )
    if unverified_single_bbox_deletion_history_count:
        # Pre-attestation delete rows are retained for audit/delete-history
        # compatibility, but they must not hide candidates in a backend that
        # advertises verified single-bbox deletion.
        dispositions = {
            key: entry
            for key, entry in dispositions.items()
            if not (
                str(entry.get("disposition") or "").strip().lower()
                == "delete_bbox"
                and not isinstance(
                    entry.get("single_bbox_deletion_attestation"), Mapping
                )
            )
        }

    refinement_summary = result.get("refinement_summary")
    selector_summary = (
        refinement_summary.get("selector_priority")
        if isinstance(refinement_summary, Mapping)
        else None
    )
    selector_contract = str(
        refinement_summary.get("selector_priority_contract") or ""
        if isinstance(refinement_summary, Mapping)
        else ""
    ).strip()
    selector_candidate_count = (
        selector_summary.get("candidate_count")
        if isinstance(selector_summary, Mapping)
        else None
    )
    analysis_scope = str(
        (result.get("summary") or {}).get("analysis_scope") or ""
    ).strip()
    authoritative_stage_one_candidates = (
        within_class_candidates
        if analysis_scope == "selected_class"
        else raw_candidates
    )
    preserve_complete_selector_queue = bool(
        selector_contract
        in {
            CLASS_ANALYSIS_SELECTOR_PRIORITY_CONTRACT,
            CLASS_ANALYSIS_SELECTOR_LEGACY_V6_PRIORITY_CONTRACT,
        }
        and not isinstance(selector_candidate_count, bool)
        and isinstance(selector_candidate_count, int)
        and selector_candidate_count == len(authoritative_stage_one_candidates)
        and selector_candidate_count == len(refinement_candidates)
    )

    def visible_queue(
        candidates: Sequence[Dict[str, Any]],
    ) -> List[Dict[str, Any]]:
        return [
            candidate
            for candidate in candidates
            if not any(
                key in dispositions
                for key in disposition_keys_for_candidate(candidate)
            )
        ]

    visible_candidates = visible_queue(raw_candidates)
    disposition_counts: Counter = Counter()
    counted_review_keys: Set[str] = set()
    overlaid_point_ids: Set[str] = set()

    def overlay_review_entry(
        point: Dict[str, Any],
        entry: Mapping[str, Any],
        matched_key: str,
    ) -> None:
        disposition = str(entry.get("disposition") or "")
        pair_resolution = (
            entry.get("dual_bbox_pair_resolution")
            if isinstance(entry.get("dual_bbox_pair_resolution"), Mapping)
            else {}
        )
        candidate_object_key = candidate_review_object_key(point)
        original_other_key = str(
            pair_resolution.get("other_review_object_key") or ""
        ).strip()
        effective_disposition = disposition
        if matched_key.startswith("crp_") and candidate_object_key == original_other_key:
            effective_disposition = {
                "delete_current_box": "delete_overlapping_box",
                "delete_overlapping_box": "delete_current_box",
            }.get(disposition, disposition)
        point["human_review_disposition"] = effective_disposition
        point["human_reviewed_at"] = entry.get("updated_at")
        point["human_review_revision"] = entry.get("entry_revision")
        point["human_review_origin"] = entry.get("origin")
        if disposition == "reassign_class":
            point["human_review_before_class"] = entry.get("class_name")
            point["human_review_target_class"] = entry.get("target_class")
        if matched_key.startswith("crp_"):
            point["human_review_pair_key"] = matched_key
        if disposition == "confirm_current":
            point["is_wrong_class_candidate"] = False
        point_id = str(point.get("point_id") or "").strip()
        if point_id:
            overlaid_point_ids.add(point_id)

    if dispositions:
        all_review_candidates = (
            raw_candidates
            + refinement_candidates
            + vignette_candidates
            + within_class_candidates
        )
        points_by_id = {
            str(point.get("point_id") or ""): point
            for point in points
            if str(point.get("point_id") or "").strip()
        }
        canonical_pair_owner_keys: Set[str] = set()
        for review_rows in (all_review_candidates, points):
            for candidate in review_rows:
                candidate_object_key = candidate_review_object_key(candidate)
                for key in disposition_keys_for_candidate(candidate):
                    entry = dispositions.get(key)
                    pair_resolution = (
                        entry.get("dual_bbox_pair_resolution")
                        if isinstance(entry, Mapping)
                        and isinstance(
                            entry.get("dual_bbox_pair_resolution"), Mapping
                        )
                        else {}
                    )
                    original_current_key = str(
                        pair_resolution.get("current_review_object_key") or ""
                    ).strip()
                    if (
                        key.startswith("crp_")
                        and original_current_key
                        and candidate_object_key == original_current_key
                    ):
                        canonical_pair_owner_keys.add(key)

        for candidate in all_review_candidates:
            candidate_point_id = str(candidate.get("point_id") or "")
            matched_key = next(
                (
                    key
                    for key in disposition_keys_for_candidate(candidate)
                    if key in dispositions
                ),
                "",
            )
            entry = dispositions.get(matched_key)
            if entry is None:
                continue
            disposition = str(entry.get("disposition") or "")
            if matched_key not in counted_review_keys:
                counted_review_keys.add(matched_key)
                disposition_counts[disposition] += 1
            point = points_by_id.get(candidate_point_id)
            pair_resolution = (
                entry.get("dual_bbox_pair_resolution")
                if isinstance(entry.get("dual_bbox_pair_resolution"), Mapping)
                else {}
            )
            candidate_object_key = candidate_review_object_key(candidate)
            original_current_key = str(
                pair_resolution.get("current_review_object_key") or ""
            ).strip()
            original_other_key = str(
                pair_resolution.get("other_review_object_key") or ""
            ).strip()
            if (
                matched_key.startswith("crp_")
                and original_current_key
                and candidate_object_key != original_current_key
                and matched_key in canonical_pair_owner_keys
            ):
                # Both directions of an all-class conflict can appear in the
                # same result. Hide both through the pair key, but publish one
                # reviewed-history owner so the UI does not show duplicates.
                continue
            if point is not None:
                overlay_review_entry(point, entry, matched_key)

        for point in points:
            point_id = str(point.get("point_id") or "").strip()
            if point_id and point_id in overlaid_point_ids:
                continue
            matched_key = next(
                (
                    key
                    for key in disposition_keys_for_candidate(point)
                    if key in dispositions
                ),
                "",
            )
            entry = dispositions.get(matched_key)
            if entry is not None:
                pair_resolution = (
                    entry.get("dual_bbox_pair_resolution")
                    if isinstance(
                        entry.get("dual_bbox_pair_resolution"), Mapping
                    )
                    else {}
                )
                original_current_key = str(
                    pair_resolution.get("current_review_object_key") or ""
                ).strip()
                if (
                    matched_key.startswith("crp_")
                    and original_current_key
                    and candidate_review_object_key(point)
                    != original_current_key
                    and matched_key in canonical_pair_owner_keys
                ):
                    continue
                overlay_review_entry(point, entry, matched_key)

    summary = dict(result.get("summary") or {})
    summary["wrong_class_candidate_count_before_human_review"] = len(raw_candidates)
    summary["visible_wrong_class_candidate_count"] = len(visible_candidates)
    summary["wrong_class_candidate_count"] = (
        len(raw_candidates)
        if preserve_complete_selector_queue
        else len(visible_candidates)
    )
    summary["human_review_disposition_counts"] = dict(disposition_counts)
    summary["human_reviewed_wrong_class_candidate_count"] = sum(
        disposition_counts.values()
    )
    summary["human_reviewed_candidate_count"] = sum(
        disposition_counts.values()
    )
    summary["unverified_single_bbox_deletion_history_count"] = (
        unverified_single_bbox_deletion_history_count
    )
    visible_refinement = visible_queue(refinement_candidates)
    visible_vignettes = visible_queue(vignette_candidates)
    visible_within = visible_queue(within_class_candidates)
    summary["refinement_candidate_count_before_human_review"] = len(
        refinement_candidates
    )
    summary["visible_refinement_candidate_count"] = len(visible_refinement)
    summary["refinement_candidate_count"] = (
        len(refinement_candidates)
        if preserve_complete_selector_queue
        else len(visible_refinement)
    )
    summary["vignette_candidate_count_before_human_review"] = len(
        vignette_candidates
    )
    summary["visible_vignette_candidate_count"] = len(visible_vignettes)
    summary["vignette_candidate_count"] = (
        len(vignette_candidates)
        if preserve_complete_selector_queue
        else len(visible_vignettes)
    )
    summary["within_class_outlier_candidate_count_before_human_review"] = len(
        within_class_candidates
    )
    summary["visible_within_class_outlier_candidate_count"] = len(
        visible_within
    )
    summary["within_class_outlier_candidate_count"] = (
        len(within_class_candidates)
        if preserve_complete_selector_queue
        else len(visible_within)
    )
    summary["complete_selector_queue_preserved"] = (
        preserve_complete_selector_queue
    )
    result["summary"] = summary
    result["points"] = points
    result["wrong_class_candidates"] = (
        raw_candidates
        if preserve_complete_selector_queue
        else visible_candidates
    )
    result["refinement_candidates"] = (
        refinement_candidates
        if preserve_complete_selector_queue
        else visible_refinement
    )
    result["vignette_candidates"] = (
        vignette_candidates
        if preserve_complete_selector_queue
        else visible_vignettes
    )
    result["within_class_outlier_candidates"] = (
        within_class_candidates
        if preserve_complete_selector_queue
        else visible_within
    )
    return result


def _class_analysis_vignette_training_action_root(
    *,
    create: bool,
) -> Optional[Path]:
    """Return the opt-in, append-only human training-candidate store."""

    class_root = _class_analysis_storage_root(create=create)
    audit_root = class_root / "audit"
    action_root = audit_root / "vignette_training_actions"
    if create:
        _class_analysis_prepare_private_audit_dir(
            audit_root,
            class_root,
            detail="vignette_training_action_store_unavailable",
        )
        return _class_analysis_prepare_private_audit_dir(
            action_root,
            class_root,
            detail="vignette_training_action_store_unavailable",
        )
    if not action_root.exists():
        return None
    try:
        return _class_analysis_prepare_private_audit_dir(
            action_root,
            class_root,
            detail="vignette_training_action_store_unavailable",
        )
    except HTTPException:
        return None


def _class_analysis_training_request_host(request: Request) -> str:
    raw_host = str(request.headers.get("host") or "").strip()
    try:
        parsed = urlsplit(f"//{raw_host}")
        return str(parsed.hostname or "").strip().lower()
    except Exception:
        return ""


def _class_analysis_training_origin_host(request: Request) -> str:
    raw_origin = str(request.headers.get("origin") or "").strip()
    if not raw_origin:
        return ""
    try:
        parsed = urlsplit(raw_origin)
        if parsed.scheme not in {"http", "https"}:
            return ""
        return str(parsed.hostname or "").strip().lower()
    except Exception:
        return ""


def _class_analysis_training_is_loopback_host(value: str) -> bool:
    return str(value or "").strip().lower() in {
        "localhost",
        "127.0.0.1",
        "::1",
    }


def _class_analysis_authorize_training_capture_request(
    request: Request,
) -> Dict[str, str]:
    """Authorize access to the opt-in human-training corpus.

    The normal launcher is loopback-only. Remote browser access is supported
    through Tailscale Serve, whose identity/capability headers are trusted only
    when the immediate peer is loopback. Direct LAN/tailnet connections need
    the explicit bearer-style environment token and cannot spoof those proxy
    headers.
    """

    host = _class_analysis_training_request_host(request)
    peer = str(
        getattr(getattr(request, "client", None), "host", "") or ""
    ).strip().lower()
    origin = str(request.headers.get("origin") or "").strip()
    origin_host = _class_analysis_training_origin_host(request)
    fetch_site = str(
        request.headers.get("sec-fetch-site") or ""
    ).strip().lower()
    if fetch_site == "cross-site":
        raise HTTPException(
            status_code=HTTP_403_FORBIDDEN,
            detail="training_capture_forbidden",
        )
    if origin and not origin_host:
        raise HTTPException(
            status_code=HTTP_403_FORBIDDEN,
            detail="training_capture_forbidden",
        )
    configured_origins, _origin_regex = _configured_cors_origins()
    configured_origin_match = (
        origin.rstrip("/") in set(configured_origins)
        and "*" not in configured_origins
    )
    if origin_host and not (
        origin_host == host
        or (
            _class_analysis_training_is_loopback_host(origin_host)
            and _class_analysis_training_is_loopback_host(host)
        )
        or configured_origin_match
    ):
        raise HTTPException(
            status_code=HTTP_403_FORBIDDEN,
            detail="training_capture_forbidden",
        )

    peer_is_loopback = _class_analysis_training_is_loopback_host(peer)
    if (
        peer_is_loopback
        and _class_analysis_training_is_loopback_host(host)
        and (
            not origin_host
            or _class_analysis_training_is_loopback_host(origin_host)
        )
    ):
        return {"source": "local_loopback", "actor": "local_user"}

    configured_token = str(
        os.environ.get("TATOR_TRAINING_DATA_TOKEN") or ""
    ).strip()
    supplied_token = str(
        request.headers.get("x-tator-training-token") or ""
    ).strip()
    if (
        configured_token
        and supplied_token
        and hmac.compare_digest(configured_token, supplied_token)
    ):
        return {"source": "configured_token", "actor": "token_holder"}

    # Tailscale documents that Serve injects these headers and strips spoofed
    # inbound versions. They are safe to trust only because the normal Tator
    # launcher binds the destination backend to loopback.
    tailscale_login = str(
        request.headers.get("tailscale-user-login") or ""
    ).strip()
    allowed_logins = {
        item.strip().lower()
        for item in str(
            os.environ.get(
                "TATOR_TRAINING_CAPTURE_TAILSCALE_USERS"
            )
            or ""
        ).split(",")
        if item.strip()
    }
    capability_name = str(
        os.environ.get(
            "TATOR_TRAINING_CAPTURE_TAILSCALE_CAPABILITY"
        )
        or ""
    ).strip()
    has_capability = False
    raw_capabilities = str(
        request.headers.get("tailscale-app-capabilities") or ""
    ).strip()
    if peer_is_loopback and capability_name and raw_capabilities:
        try:
            capability_payload = json.loads(raw_capabilities)
            has_capability = (
                isinstance(capability_payload, dict)
                and capability_name in capability_payload
            )
        except Exception:
            has_capability = False
    if (
        peer_is_loopback
        and not _class_analysis_training_is_loopback_host(host)
        and (
            has_capability
            or (
                tailscale_login
                and tailscale_login.lower() in allowed_logins
            )
        )
    ):
        return {
            "source": (
                "tailscale_capability"
                if has_capability
                else "tailscale_identity"
            ),
            "actor": tailscale_login or "tailscale_capability",
        }

    raise HTTPException(
        status_code=HTTP_403_FORBIDDEN,
        detail="training_capture_forbidden",
    )


def _class_analysis_vignette_training_point(
    job: ClassAnalysisJob,
    point_id: str,
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """Resolve one immutable analysis point without cloning the full result."""

    safe_point_id = str(point_id or "").strip()
    if not safe_point_id:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="point_id_required",
        )
    job_dir = _class_analysis_job_dir(
        job.job_id,
        create=False,
        detail="result_not_found",
    )
    point = _class_analysis_thumbnail_point_metadata(job, job_dir, safe_point_id)
    summary = {
        **dict(getattr(job, "summary", None) or {}),
        "analysis_job_id": str(job.job_id or ""),
    }
    if point is None:
        raw_result: Dict[str, Any]
        if isinstance(job.result, dict):
            raw_result = job.result
        else:
            result_path = _safe_job_result_json_path(
                job.result_path,
                CLASS_ANALYSIS_ROOT,
            )
            if result_path is None:
                raise HTTPException(
                    status_code=HTTP_404_NOT_FOUND,
                    detail="result_not_found",
                )
            raw_result = _class_analysis_load_job_result_payload(
                job,
                result_path,
            )
        summary = {
            **dict(raw_result.get("summary") or {}),
            **summary,
        }
        point = next(
            (
                item
                for item in (raw_result.get("points") or [])
                if isinstance(item, dict)
                and str(item.get("point_id") or "") == safe_point_id
            ),
            None,
        )
        if point is not None and not point.get("review_object_key"):
            candidate = next(
                (
                    item
                    for item in (raw_result.get("wrong_class_candidates") or [])
                    if isinstance(item, dict)
                    and str(item.get("point_id") or "") == safe_point_id
                ),
                None,
            )
            if isinstance(candidate, dict):
                point = {
                    **point,
                    "review_object_key": candidate.get("review_object_key"),
                }
    if point is None:
        raise HTTPException(
            status_code=HTTP_404_NOT_FOUND,
            detail="point_not_found",
        )
    return _class_analysis_backfill_review_object_key(job, point), summary


def _class_analysis_vignette_training_model_review(
    *,
    job_id: str,
    point_id: str,
    review_id: str = "",
) -> Optional[Dict[str, Any]]:
    """Snapshot the exact terminal model result and durable artifact locators."""

    requested_review_id = str(review_id or "").strip()
    selected: Optional[ClassAnalysisQwenReviewJob] = None
    with CLASS_ANALYSIS_QWEN_REVIEW_JOBS_LOCK:
        if requested_review_id:
            candidate = CLASS_ANALYSIS_QWEN_REVIEW_JOBS.get(requested_review_id)
            if candidate is not None:
                if (
                    str(candidate.parent_job_id or "") != str(job_id or "")
                    or str(candidate.point_id or "") != str(point_id or "")
                ):
                    raise HTTPException(
                        status_code=HTTP_409_CONFLICT,
                        detail="training_action_review_mismatch",
                    )
                selected = candidate
        else:
            candidates = [
                candidate
                for candidate in CLASS_ANALYSIS_QWEN_REVIEW_JOBS.values()
                if str(candidate.parent_job_id or "") == str(job_id or "")
                and str(candidate.point_id or "") == str(point_id or "")
                and str(candidate.status or "").strip().lower() == "completed"
            ]
            if candidates:
                selected = max(
                    candidates,
                    key=lambda candidate: float(
                        candidate.updated_at or candidate.created_at or 0.0
                    ),
                )
    if selected is None:
        if requested_review_id:
            # Never attach an arbitrary caller-supplied directory to a human
            # label. Exact review linkage must be validated by the live review
            # registry before the disposable job is archived.
            raise HTTPException(
                status_code=HTTP_404_NOT_FOUND,
                detail="training_action_review_not_found",
            )
        return None

    safe_job_id = _class_analysis_safe_slug(selected.parent_job_id, "")
    safe_review_id = _class_analysis_safe_slug(selected.review_id, "")
    result = (
        copy.deepcopy(selected.result)
        if isinstance(selected.result, dict)
        else None
    )
    request_payload = (
        selected.request if isinstance(selected.request, dict) else {}
    )
    model_id = ""
    model_provenance: Dict[str, Any] = {}
    if isinstance(result, dict):
        model_provenance = (
            copy.deepcopy(result.get("model_provenance"))
            if isinstance(result.get("model_provenance"), dict)
            else {}
        )
        # Production final results record the actually loaded checkpoint under
        # `reviewed_by_model`; request/model_id may be an alias such as
        # "default". Preserve the resolved model in training provenance.
        model_id = str(
            model_provenance.get("resolved_model_id")
            or result.get("reviewed_by_model")
            or result.get("model_id")
            or ""
        ).strip()
    if not model_id:
        model_id = str(
            request_payload.get("model_id")
            or request_payload.get("reviewer_model")
            or ""
        ).strip()
    artifact_snapshot = _class_analysis_snapshot_vignette_review_artifacts(
        parent_job_id=safe_job_id,
        review_id=safe_review_id,
        use_cache=(
            str(selected.status or "").strip().lower()
            in {"completed", "failed", "cancelled"}
        ),
    )
    artifact_manifest_sha256 = hashlib.sha256(
        json.dumps(
            _class_analysis_json_safe(artifact_snapshot),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    artifact_roles = {
        str(artifact.get("role") or "")
        for artifact in (artifact_snapshot.get("files") or [])
        if isinstance(artifact, dict)
    }
    has_complete_model_io = any(
        isinstance(artifact, dict)
        and artifact.get("role") == "model_io_trace"
        and artifact.get("model_io_complete") is True
        for artifact in (artifact_snapshot.get("files") or [])
    )
    checkpoint_fingerprint = str(
        model_provenance.get("checkpoint_fingerprint") or ""
    ).strip().lower()
    checkpoint_fingerprint_verified = bool(
        model_provenance.get("checkpoint_fingerprint_verified") is True
        and re.fullmatch(r"[0-9a-f]{64}", checkpoint_fingerprint)
    )
    checkpoint_identity_verified = bool(
        model_provenance.get("checkpoint_identity_verified") is True
        and model_provenance.get("fingerprint_strength")
        == "revision_config_weight_manifest"
        and re.fullmatch(r"[0-9a-f]{64}", checkpoint_fingerprint)
    )
    model_invoked = bool(isinstance(result, dict) and result.get("model_invoked") is True)
    model_final_completed = bool(
        isinstance(result, dict) and result.get("model_final_completed") is True
    )
    model_final_validated = bool(
        isinstance(result, dict) and result.get("model_final_validated") is True
    )
    reviewed_by_model = str(
        (result.get("reviewed_by_model") or "") if isinstance(result, dict) else ""
    ).strip()
    explicit_link = bool(requested_review_id)
    vlm_trace = (
        copy.deepcopy(artifact_snapshot.get("vlm_trace"))
        if isinstance(artifact_snapshot.get("vlm_trace"), Mapping)
        else {
            "schema": "qwen-review-trace-capture-v1",
            "status": "unavailable",
        }
    )
    return json_sanitize(
        {
            "review_id": safe_review_id,
            "model_id": model_id,
            "requested_model_id": str(
                model_provenance.get("requested_model_id")
                or request_payload.get("model_id")
                or request_payload.get("reviewer_model")
                or ""
            ),
            "resolved_model_id": model_id,
            "model_provenance": model_provenance,
            "checkpoint_fingerprint": checkpoint_fingerprint,
            "checkpoint_fingerprint_verified": checkpoint_fingerprint_verified,
            "checkpoint_identity_verified": checkpoint_identity_verified,
            "fingerprint_strength": str(
                model_provenance.get("fingerprint_strength") or ""
            ),
            "model_invoked": model_invoked,
            "model_final_completed": model_final_completed,
            "model_final_validated": model_final_validated,
            "status": str(selected.status or ""),
            "result": result,
            # Both paths are recorded because startup cleanup atomically moves
            # completed review directories from the job tree into audit.
            "active_relpath": (
                f"{safe_job_id}/qwen_reviews/{safe_review_id}"
            ),
            "archive_relpath": f"audit/{safe_job_id}/{safe_review_id}",
            "registry_validated": True,
            "linkage_method": (
                "explicit_review_id"
                if explicit_link
                else "heuristic_latest_completed"
            ),
            # Heuristic linkage remains useful audit context, but preference
            # exporters must not treat it as an exact prompt/output pairing.
            "preference_train_eligible": explicit_link
            and str(selected.status or "").strip().lower() == "completed"
            and model_invoked
            and model_final_completed
            and model_final_validated
            and bool(reviewed_by_model)
            and checkpoint_identity_verified
            and artifact_snapshot.get("status") == "complete"
            and has_complete_model_io
            and {"model_io_trace", "structured_result"}.issubset(
                artifact_roles
            ),
            "model_io_complete": has_complete_model_io,
            # The complete raw audit stays in the immutable content-addressed
            # blob rather than inflating every JSONL action record.  This
            # explicit index makes the prompt/intermediate/final output trace
            # a first-class part of the opted-in capture instead of an
            # incidental file buried in the artifact manifest.
            "vlm_trace": vlm_trace,
            "artifact_snapshot": artifact_snapshot,
            "artifact_manifest_sha256": artifact_manifest_sha256,
            "created_at": selected.created_at,
            "updated_at": selected.updated_at,
        }
    )


def _class_analysis_snapshot_vignette_review_artifacts(
    *,
    parent_job_id: str,
    review_id: str,
    use_cache: bool = True,
) -> Dict[str, Any]:
    """Copy bounded review artifacts into content-addressed immutable blobs."""

    class_root = _class_analysis_storage_root(create=True)
    safe_job_id = _class_analysis_safe_slug(parent_job_id, "")
    safe_review_id = _class_analysis_safe_slug(review_id, "")
    if not safe_job_id or not safe_review_id:
        return {"status": "unavailable", "files": []}
    cache_key = f"{class_root}:{safe_job_id}:{safe_review_id}"
    if use_cache:
        with CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE_LOCK:
            cached = CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE.get(cache_key)
            if isinstance(cached, dict):
                CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE.move_to_end(cache_key)
                return copy.deepcopy(cached)
    candidates = [
        class_root / safe_job_id / "qwen_reviews" / safe_review_id,
        class_root / "audit" / safe_job_id / safe_review_id,
    ]
    audit_root = class_root / "audit"
    if audit_root.is_dir() and not audit_root.is_symlink():
        try:
            collision_roots = sorted(
                (
                    path
                    for path in audit_root.glob(f"{safe_job_id}_*")
                    if path.is_dir() and not path.is_symlink()
                ),
                key=lambda path: path.stat().st_mtime_ns,
                reverse=True,
            )
            candidates.extend(
                path / safe_review_id for path in collision_roots[:16]
            )
        except OSError:
            pass
    source_dir: Optional[Path] = None
    for candidate in candidates:
        try:
            if (
                candidate.is_dir()
                and not candidate.is_symlink()
                and _path_is_within_root_impl(
                    candidate.resolve(strict=True),
                    class_root,
                )
            ):
                source_dir = candidate.resolve(strict=True)
                break
        except OSError:
            continue
    if source_dir is None:
        return {"status": "unavailable", "files": []}

    action_root = _class_analysis_vignette_training_action_root(create=True)
    if action_root is None:
        return {"status": "unavailable", "files": []}
    blobs_root = _class_analysis_prepare_private_audit_dir(
        action_root / "blobs",
        action_root,
        detail="vignette_training_action_store_unavailable",
    )
    blob_root = _class_analysis_prepare_private_audit_dir(
        blobs_root / "sha256",
        blobs_root,
        detail="vignette_training_action_store_unavailable",
    )
    allowed_suffixes = {
        ".json",
        ".jsonl",
        ".txt",
        ".jpg",
        ".jpeg",
        ".png",
        ".webp",
    }
    max_files = 256
    max_file_bytes = 16 * 1024 * 1024
    max_total_bytes = 128 * 1024 * 1024
    total_bytes = 0
    manifest: List[Dict[str, Any]] = []
    truncated = False
    files: List[Path] = []
    try:
        for scanned_count, candidate in enumerate(
            source_dir.rglob("*"),
            start=1,
        ):
            if scanned_count > 4096:
                truncated = True
                break
            if (
                candidate.is_file()
                and not candidate.is_symlink()
                and candidate.suffix.lower() in allowed_suffixes
            ):
                files.append(candidate)
    except OSError:
        truncated = True
    # The append-only model I/O ledger is the irreplaceable training artifact.
    # Capture it before rendered evidence so a large evidence pack cannot
    # consume the bounded corpus budget and leave the decision without its
    # prompts, intermediate outputs, controller events, and raw final output.
    def _capture_priority(path: Path) -> Tuple[int, str]:
        relpath = path.relative_to(source_dir).as_posix()
        if path.name == "events.jsonl":
            return (0, relpath)
        if path.name in {"final.json", "result.json"}:
            return (1, relpath)
        return (2, relpath)

    for candidate in sorted(files, key=_capture_priority):
        if len(manifest) >= max_files:
            truncated = True
            break
        try:
            if (
                candidate.is_symlink()
                or not candidate.is_file()
                or candidate.suffix.lower() not in allowed_suffixes
            ):
                continue
            safe_candidate = _safe_existing_regular_file_within_root_impl(
                candidate,
                source_dir,
            )
            if safe_candidate is None:
                continue
            size = int(safe_candidate.stat().st_size)
            candidate_max_bytes = (
                max_total_bytes
                if safe_candidate.name == "events.jsonl"
                else max_file_bytes
            )
            if (
                size < 0
                or size > candidate_max_bytes
                or total_bytes + size > max_total_bytes
            ):
                truncated = True
                continue
            data = safe_candidate.read_bytes()
            digest = hashlib.sha256(data).hexdigest()
            model_io_complete = False
            trace_metadata: Dict[str, Any] = {}
            if safe_candidate.name == "events.jsonl":
                final_inputs: Set[str] = set()
                final_outputs: Set[str] = set()
                event_count = 0
                model_input_count = 0
                model_output_count = 0
                model_partial_output_count = 0
                final_model_output_count = 0
                try:
                    for raw_line in data.decode(
                        "utf-8",
                        errors="strict",
                    ).splitlines():
                        if not raw_line.strip():
                            continue
                        event = json.loads(raw_line)
                        if not isinstance(event, dict):
                            raise ValueError("trace_event_not_object")
                        event_count += 1
                        phase = str(event.get("phase") or "").strip()
                        event_type = str(event.get("type") or "").strip()
                        if event_type == "model_input":
                            model_input_count += 1
                        if event_type in {
                            "model_output",
                            "model_partial_output",
                        }:
                            model_output_count += 1
                        if event_type == "model_partial_output":
                            model_partial_output_count += 1
                        is_final_phase = bool(
                            phase == "final"
                            or phase == "schema_finalization"
                            or phase.startswith("final_attempt_")
                        )
                        if is_final_phase and event_type == "model_output":
                            final_model_output_count += 1
                        if not is_final_phase:
                            continue
                        if (
                            event_type == "model_input"
                            and isinstance(event.get("messages"), list)
                            and bool(event.get("messages"))
                        ):
                            final_inputs.add(phase)
                        if (
                            event_type == "model_output"
                            and bool(str(event.get("text") or "").strip())
                        ):
                            final_outputs.add(phase)
                    model_io_complete = bool(
                        final_inputs & final_outputs
                    )
                    trace_metadata = {
                        "trace_complete": True,
                        "event_count": event_count,
                        "model_input_count": model_input_count,
                        "model_output_count": model_output_count,
                        "model_partial_output_count": (
                            model_partial_output_count
                        ),
                        "final_model_output_count": (
                            final_model_output_count
                        ),
                    }
                except Exception:
                    model_io_complete = False
                    trace_metadata = {
                        "trace_complete": False,
                        "event_count": 0,
                        "model_input_count": 0,
                        "model_output_count": 0,
                        "model_partial_output_count": 0,
                        "final_model_output_count": 0,
                    }
            dimensions: Dict[str, int] = {}
            if safe_candidate.suffix.lower() in {
                ".jpg",
                ".jpeg",
                ".png",
                ".webp",
            }:
                try:
                    with Image.open(io.BytesIO(data)) as loaded:
                        dimensions = {
                            "width": int(loaded.width),
                            "height": int(loaded.height),
                        }
                except Exception:
                    dimensions = {}
            shard_root = _class_analysis_prepare_private_audit_dir(
                blob_root / digest[:2],
                blob_root,
                detail="vignette_training_action_store_unavailable",
            )
            blob_path = shard_root / f"{digest}.blob"
            existing = _safe_existing_regular_file_within_root_impl(
                blob_path,
                blob_root,
            )
            if existing is None:
                _class_analysis_write_audit_binary(
                    blob_path,
                    blob_root,
                    lambda handle, content=data: handle.write(content),
                    detail="vignette_training_action_store_unavailable",
                )
            elif (
                int(existing.stat().st_size) != len(data)
                or _class_analysis_file_sha256(existing) != digest
            ):
                raise OSError("existing training blob failed integrity check")
            manifest.append(
                {
                    "source_relpath": safe_candidate.relative_to(
                        source_dir
                    ).as_posix(),
                    "sha256": digest,
                    "bytes": len(data),
                    "media_type": {
                        ".json": "application/json",
                        ".jsonl": "application/x-ndjson",
                        ".txt": "text/plain",
                        ".jpg": "image/jpeg",
                        ".jpeg": "image/jpeg",
                        ".png": "image/png",
                        ".webp": "image/webp",
                    }.get(
                        safe_candidate.suffix.lower(),
                        "application/octet-stream",
                    ),
                    "role": (
                        "model_io_trace"
                        if safe_candidate.name == "events.jsonl"
                        else (
                            "structured_result"
                            if safe_candidate.name
                            in {"result.json", "final.json"}
                            else (
                                "evidence_ledger"
                                if "evidence" in safe_candidate.name.lower()
                                and safe_candidate.suffix.lower()
                                in {".json", ".jsonl"}
                                else (
                                    "rendered_evidence"
                                    if safe_candidate.suffix.lower()
                                    in {".jpg", ".jpeg", ".png", ".webp"}
                                    else "prompt_or_context"
                                )
                            )
                        )
                    ),
                    **(
                        {
                            "model_io_complete": model_io_complete,
                            **trace_metadata,
                        }
                        if safe_candidate.name == "events.jsonl"
                        else {}
                    ),
                    "dimensions": dimensions,
                    "blob_relpath": (
                        Path("audit")
                        / "vignette_training_actions"
                        / "blobs"
                        / "sha256"
                        / digest[:2]
                        / f"{digest}.blob"
                    ).as_posix(),
                }
            )
            total_bytes += len(data)
        except Exception as exc:
            logger.warning(
                "Could not snapshot VLM review artifact %s: %s",
                candidate,
                exc,
            )
            truncated = True
    trace_artifact = next(
        (
            artifact
            for artifact in manifest
            if artifact.get("role") == "model_io_trace"
        ),
        None,
    )
    trace_snapshot = {
        "schema": "qwen-review-trace-capture-v1",
        "status": (
            "complete"
            if isinstance(trace_artifact, Mapping)
            and trace_artifact.get("trace_complete") is True
            else "unavailable"
        ),
        "source_relpath": (
            str(trace_artifact.get("source_relpath") or "")
            if isinstance(trace_artifact, Mapping)
            else ""
        ),
        "sha256": (
            str(trace_artifact.get("sha256") or "")
            if isinstance(trace_artifact, Mapping)
            else ""
        ),
        "blob_relpath": (
            str(trace_artifact.get("blob_relpath") or "")
            if isinstance(trace_artifact, Mapping)
            else ""
        ),
        "bytes": (
            int(trace_artifact.get("bytes") or 0)
            if isinstance(trace_artifact, Mapping)
            else 0
        ),
        "event_count": (
            int(trace_artifact.get("event_count") or 0)
            if isinstance(trace_artifact, Mapping)
            else 0
        ),
        "model_input_count": (
            int(trace_artifact.get("model_input_count") or 0)
            if isinstance(trace_artifact, Mapping)
            else 0
        ),
        "model_output_count": (
            int(trace_artifact.get("model_output_count") or 0)
            if isinstance(trace_artifact, Mapping)
            else 0
        ),
        "model_partial_output_count": (
            int(
                trace_artifact.get("model_partial_output_count") or 0
            )
            if isinstance(trace_artifact, Mapping)
            else 0
        ),
        "final_model_output_count": (
            int(trace_artifact.get("final_model_output_count") or 0)
            if isinstance(trace_artifact, Mapping)
            else 0
        ),
    }
    snapshot = {
        "status": "partial" if truncated else "complete",
        "source_relpath": source_dir.relative_to(class_root).as_posix(),
        "file_count": len(manifest),
        "bytes": total_bytes,
        "vlm_trace": trace_snapshot,
        "files": manifest,
    }
    if use_cache:
        with CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE_LOCK:
            CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE[cache_key] = copy.deepcopy(
                snapshot
            )
            CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE.move_to_end(cache_key)
            while len(CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE) > 512:
                CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE.popitem(last=False)
    return snapshot


def _class_analysis_store_vignette_training_blob(
    data: bytes,
    *,
    source_relpath: str,
    media_type: str,
    role: str,
) -> Dict[str, Any]:
    action_root = _class_analysis_vignette_training_action_root(create=True)
    if action_root is None:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="vignette_training_action_store_unavailable",
        )
    blobs_root = _class_analysis_prepare_private_audit_dir(
        action_root / "blobs",
        action_root,
        detail="vignette_training_action_store_unavailable",
    )
    blob_root = _class_analysis_prepare_private_audit_dir(
        blobs_root / "sha256",
        blobs_root,
        detail="vignette_training_action_store_unavailable",
    )
    digest = hashlib.sha256(data).hexdigest()
    shard_root = _class_analysis_prepare_private_audit_dir(
        blob_root / digest[:2],
        blob_root,
        detail="vignette_training_action_store_unavailable",
    )
    blob_path = shard_root / f"{digest}.blob"
    existing = _safe_existing_regular_file_within_root_impl(
        blob_path,
        blob_root,
    )
    if existing is None:
        _class_analysis_write_audit_binary(
            blob_path,
            blob_root,
            lambda handle: handle.write(data),
            detail="vignette_training_action_store_unavailable",
        )
    elif (
        int(existing.stat().st_size) != len(data)
        or _class_analysis_file_sha256(existing) != digest
    ):
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="vignette_training_blob_integrity_failed",
        )
    dimensions: Dict[str, int] = {}
    if str(media_type or "").startswith("image/"):
        try:
            with Image.open(io.BytesIO(data)) as loaded:
                dimensions = {
                    "width": int(loaded.width),
                    "height": int(loaded.height),
                }
        except Exception:
            dimensions = {}
    return {
        "source_relpath": str(source_relpath or ""),
        "sha256": digest,
        "bytes": len(data),
        "media_type": str(media_type or "application/octet-stream"),
        "role": str(role or "artifact"),
        "dimensions": dimensions,
        "blob_relpath": (
            Path("audit")
            / "vignette_training_actions"
            / "blobs"
            / "sha256"
            / digest[:2]
            / f"{digest}.blob"
        ).as_posix(),
    }


def _class_analysis_snapshot_vignette_point_media(
    job: ClassAnalysisJob,
    point: Mapping[str, Any],
) -> List[Dict[str, Any]]:
    """Persist the object crop even when no VLM review was requested."""

    point_id = str(point.get("point_id") or "").strip()
    review_object_key = str(point.get("review_object_key") or "").strip()
    if not point_id or not review_object_key:
        return []
    cache_key = (
        f"point:{_class_analysis_storage_root(create=True)}:"
        f"{review_object_key}"
    )
    with CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE_LOCK:
        cached = CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE.get(cache_key)
        if isinstance(cached, dict):
            files = cached.get("files")
            if isinstance(files, list):
                CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE.move_to_end(
                    cache_key
                )
                return copy.deepcopy(files)
    try:
        response = get_class_analysis_thumbnail(job.job_id, point_id)
        body = bytes(getattr(response, "body", b"") or b"")
        if not body:
            return []
        artifact = _class_analysis_store_vignette_training_blob(
            body,
            source_relpath=f"point/{point_id}/thumbnail.jpg",
            media_type="image/jpeg",
            role="object_crop",
        )
        files = [artifact]
        with CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE_LOCK:
            CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE[cache_key] = {
                "files": copy.deepcopy(files)
            }
            CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE.move_to_end(cache_key)
            while len(CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE) > 512:
                CLASS_ANALYSIS_TRAINING_ARTIFACT_CACHE.popitem(last=False)
        return files
    except Exception as exc:
        # Some legacy/unit-test jobs no longer have their source image. Keep
        # the semantic event, but mark it ineligible for visual export.
        logger.warning(
            "Could not snapshot training crop for %s/%s: %s",
            job.job_id,
            point_id,
            exc,
        )
        return []


def _class_analysis_vignette_training_point_snapshot(
    point: Mapping[str, Any],
    summary: Mapping[str, Any],
) -> Dict[str, Any]:
    bbox: List[float] = []
    for value in list(point.get("bbox_xyxy") or [])[:4]:
        try:
            bbox.append(round(float(value), 6))
        except (TypeError, ValueError):
            pass
    visual_source_key = str(
        point.get("source_key") or summary.get("source_key") or ""
    )
    if visual_source_key.startswith("active:"):
        visual_source_key = "active_workspace"
    elif visual_source_key.startswith("transient:"):
        visual_source_key = "transient_workspace"
    visual_identity = {
        "source_key": visual_source_key,
        "image_sha256": str(point.get("image_sha256") or "").lower(),
        "split": str(point.get("split") or ""),
        "image_relpath": str(point.get("image_relpath") or ""),
        # Geometry only: YOLO label_line begins with the class id and would
        # make this supposedly class-independent key change after relabeling.
        "geometry": _class_analysis_canonical_review_geometry(
            point,
            image_width=_coerce_int(point.get("image_width"), 0)
            or None,
            image_height=_coerce_int(point.get("image_height"), 0)
            or None,
        ),
    }
    visual_key = "cvo_" + hashlib.sha256(
        json.dumps(
            _class_analysis_json_safe(visual_identity),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return json_sanitize(
        {
            "identity": {
                "id": str(point.get("point_id") or ""),
                "review_object_key": str(
                    point.get("review_object_key") or ""
                ),
                "visual_object_key": visual_key,
            },
            "source": {
                "mode": str(
                    point.get("source_mode")
                    or summary.get("source_mode")
                    or ""
                ),
                "id": str(
                    point.get("source_id")
                    or summary.get("source_id")
                    or ""
                ),
                "key": str(
                    point.get("source_key")
                    or summary.get("source_key")
                    or ""
                ),
                "dataset_label": str(summary.get("dataset_label") or ""),
            },
            "image": {
                "split": str(point.get("split") or ""),
                "relpath": str(point.get("image_relpath") or ""),
                "sha256": str(point.get("image_sha256") or ""),
                "width": point.get("image_width"),
                "height": point.get("image_height"),
            },
            "class": {"name": str(point.get("class_name") or "")},
            "bbox": {
                "kind": str(point.get("kind") or "bbox"),
                "xyxy": bbox,
                "label_line": str(point.get("label_line") or ""),
            },
            "review_rails": {
                "wrong_class_suspicion": point.get(
                    "wrong_class_suspicion"
                ),
                "wrong_class_review_reason": point.get(
                    "wrong_class_review_reason"
                ),
                "embedding_wrong_class_suspicion": point.get(
                    "embedding_wrong_class_suspicion"
                ),
                "same_class_neighbor_ratio": point.get(
                    "same_class_neighbor_ratio"
                ),
                "top_other_neighbor_ratio": point.get(
                    "top_other_neighbor_ratio"
                ),
                "suggested_neighbor_class": point.get(
                    "suggested_neighbor_class"
                ),
                "neighbor_class_counts": point.get("neighbor_class_counts"),
                "review_signals": point.get("review_signals"),
                "is_close_overlap_candidate": point.get(
                    "is_close_overlap_candidate"
                ),
                "close_overlap_matches": point.get("close_overlap_matches"),
                "is_dual_bbox_conflict": point.get(
                    "is_dual_bbox_conflict"
                ),
                "dual_bbox_conflict": point.get("dual_bbox_conflict"),
                # Stage-2 is captured as compact provenance only. Private
                # patch arrays remain in the checksum-bound job sidecar, and
                # this rail is never treated as the human label.
                "patch_refinement": (
                    _class_analysis_compact_refinement_rail(point)
                ),
            },
        }
    )


def _class_analysis_vignette_training_dual_pair_contract(
    *,
    job: ClassAnalysisJob,
    point: Mapping[str, Any],
    action_type: str,
    payload: Mapping[str, Any],
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """Rebuild training provenance from the persisted pair, never the client."""

    (
        conflict,
        pair_review_key,
        current_review_object_key,
        other_review_object_key,
    ) = _class_analysis_validated_dual_bbox_conflict(job, point, payload)
    commit_attestation = None
    if action_type in {"delete_current_box", "delete_overlapping_box"}:
        commit_attestation = (
            _class_analysis_validate_dual_bbox_annotation_commit_attestation(
                job=job,
                point=point,
                conflict=conflict,
                pair_review_key=pair_review_key,
                action=action_type,
                value=payload.get("annotation_commit_attestation"),
            )
        )
    resolution = _class_analysis_dual_bbox_pair_resolution_record(
        action=action_type,
        point=point,
        conflict=conflict,
        pair_review_key=pair_review_key,
        current_review_object_key=current_review_object_key,
        other_review_object_key=other_review_object_key,
        annotation_commit_attestation=commit_attestation,
    )
    supplied_resolution = payload.get("dual_bbox_pair_resolution")
    if isinstance(supplied_resolution, Mapping):
        # The disposition endpoint passes its already-bound record to make the
        # handoff explicit. Recomputing and comparing here prevents the public
        # training-capture route from smuggling caller-owned pair identity.
        supplied_safe = {
            key: _class_analysis_json_safe(supplied_resolution.get(key))
            for key in resolution
        }
        if supplied_safe != _class_analysis_json_safe(resolution):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="training_dual_bbox_pair_resolution_mismatch",
            )
    return resolution, conflict


def _class_analysis_vignette_training_dual_pair_review_artifacts(
    model_review: Optional[Mapping[str, Any]],
    *,
    pair_resolution: Mapping[str, Any],
) -> List[Dict[str, Any]]:
    """Link the exact paired VLM rail for an explicitly selected review.

    The review registry and its content-addressed snapshot are server-owned.
    Pair fields in the terminal review must still match the canonical
    disposition pair, which prevents a stale review of another overlap from
    being attached to this human geometry decision.
    """

    if (
        not isinstance(model_review, Mapping)
        or model_review.get("registry_validated") is not True
        or str(model_review.get("linkage_method") or "")
        != "explicit_review_id"
    ):
        return []
    result = model_review.get("result")
    if not isinstance(result, Mapping):
        return []
    if (
        str(result.get("review_mode") or "")
        != "dual_bbox_annotation_resolution"
    ):
        return []
    conflict = result.get("dual_bbox_conflict")
    if not isinstance(conflict, Mapping):
        return []
    exact_fields = {
        "point_id": str(conflict.get("point_id") or "").strip(),
        "other_point_id": str(conflict.get("other_point_id") or "").strip(),
        "current_class": str(conflict.get("current_class") or "").strip(),
        "other_class": str(
            conflict.get("other_class_name")
            or conflict.get("class_name")
            or ""
        ).strip(),
    }
    expected_fields = {
        key: str(pair_resolution.get(key) or "").strip()
        for key in exact_fields
    }
    if exact_fields != expected_fields:
        return []
    for conflict_key, resolution_key in (
        ("pair_review_key", "pair_review_key"),
        ("current_review_object_key", "current_review_object_key"),
        ("other_review_object_key", "other_review_object_key"),
    ):
        value = str(conflict.get(conflict_key) or "").strip()
        if value and value != str(pair_resolution.get(resolution_key) or ""):
            return []

    def _bbox_matches(left: Any, right: Any) -> bool:
        try:
            left_values = [float(value) for value in list(left or [])[:4]]
            right_values = [float(value) for value in list(right or [])[:4]]
        except (TypeError, ValueError):
            return False
        return bool(
            len(left_values) == 4
            and len(right_values) == 4
            and all(
                math.isclose(a, b, rel_tol=0.0, abs_tol=1e-6)
                for a, b in zip(left_values, right_values)
            )
        )

    if not _bbox_matches(
        conflict.get("target_bbox_xyxy"),
        pair_resolution.get("current_bbox_xyxy"),
    ) or not _bbox_matches(
        conflict.get("other_bbox_xyxy"),
        pair_resolution.get("other_bbox_xyxy"),
    ):
        return []
    snapshot = model_review.get("artifact_snapshot")
    files = snapshot.get("files") if isinstance(snapshot, Mapping) else []
    linked: List[Dict[str, Any]] = []
    for artifact in files or []:
        if not isinstance(artifact, Mapping):
            continue
        source_relpath = str(artifact.get("source_relpath") or "").replace(
            "\\", "/"
        )
        if (
            re.fullmatch(
                r"evidence/dual_bbox_pair_[A-Za-z0-9_.-]+\.(?:jpg|jpeg|png|webp)",
                source_relpath,
                flags=re.IGNORECASE,
            )
            is None
            or not str(artifact.get("media_type") or "").startswith("image/")
            or _class_analysis_vignette_training_blob(artifact) is None
        ):
            continue
        linked.append(
            {
                **copy.deepcopy(dict(artifact)),
                "source_role": str(artifact.get("role") or ""),
                "role": "dual_bbox_pair_evidence",
                "linked_review_id": str(
                    model_review.get("review_id") or ""
                ),
                "pair_review_key": str(
                    pair_resolution.get("pair_review_key") or ""
                ),
            }
        )
    return linked


def _class_analysis_training_action_refresh_id_index(
    path: Path,
) -> Dict[str, str]:
    cache_key = str(path.resolve(strict=False))
    with CLASS_ANALYSIS_TRAINING_ACTION_ID_INDEX_LOCK:
        state = CLASS_ANALYSIS_TRAINING_ACTION_ID_INDEX.get(cache_key)
        if state is None:
            state = {"offset": 0, "ids": {}}
            CLASS_ANALYSIS_TRAINING_ACTION_ID_INDEX[cache_key] = state
        CLASS_ANALYSIS_TRAINING_ACTION_ID_INDEX.move_to_end(cache_key)
        while len(CLASS_ANALYSIS_TRAINING_ACTION_ID_INDEX) > 512:
            CLASS_ANALYSIS_TRAINING_ACTION_ID_INDEX.popitem(last=False)
    offset = max(0, int(state.get("offset") or 0))
    ids = state.get("ids")
    if not isinstance(ids, dict):
        ids = {}
        state["ids"] = ids
    try:
        size = int(path.stat().st_size) if path.exists() else 0
        if size < offset:
            # A human-data shard must never be truncated. Fail closed instead
            # of silently rebuilding against potentially replaced history.
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                detail="vignette_training_action_store_truncated",
            )
        if size > offset:
            with path.open("rb") as handle:
                handle.seek(offset)
                while handle.tell() < size:
                    raw_line = handle.readline(
                        CLASS_ANALYSIS_TRAINING_ACTION_MAX_LINE_BYTES + 1
                    )
                    if (
                        not raw_line
                        or len(raw_line)
                        > CLASS_ANALYSIS_TRAINING_ACTION_MAX_LINE_BYTES
                        or not raw_line.endswith(b"\n")
                    ):
                        raise HTTPException(
                            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                            detail="vignette_training_action_store_corrupt",
                        )
                    if not raw_line.strip():
                        continue
                    try:
                        record = json.loads(raw_line)
                    except Exception as exc:
                        raise HTTPException(
                            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                            detail="vignette_training_action_store_corrupt",
                        ) from exc
                    if (
                        isinstance(record, dict)
                        and record.get("schema")
                        == "vignette-training-action-batch-v1"
                    ):
                        if not _class_analysis_vignette_training_batch_hash_valid(
                            record
                        ):
                            raise HTTPException(
                                status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                                detail="vignette_training_action_store_corrupt",
                            )
                    elif (
                        not isinstance(record, dict)
                        or not _class_analysis_vignette_training_event_hash_valid(
                            record
                        )
                    ):
                        raise HTTPException(
                            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                            detail="vignette_training_action_store_corrupt",
                        )
                    records = [record]
                    if (
                        isinstance(record, dict)
                        and isinstance(record.get("events"), list)
                    ):
                        records.extend(record["events"])
                    for item in records:
                        if not isinstance(item, dict):
                            continue
                        action_id = str(item.get("action_id") or "")
                        payload_hash = str(
                            item.get("idempotency_payload_sha256") or ""
                        )
                        if action_id:
                            ids[action_id] = payload_hash
            state["offset"] = size
    except HTTPException:
        raise
    except OSError as exc:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="vignette_training_action_store_unavailable",
        ) from exc
    return ids


def _class_analysis_vignette_training_action_files(
    action_root: Path,
) -> List[Path]:
    """List stable v1 shards plus legacy daily shards in deterministic order."""

    paths: List[Path] = []
    stable_root = action_root / "events"
    if stable_root.is_dir() and not stable_root.is_symlink():
        paths.extend(
            path
            for path in sorted(stable_root.glob("*.jsonl"))
            if (
                not path.is_symlink()
                and re.fullmatch(r"[0-9a-f]{2}\.jsonl", path.name)
            )
        )
    for day_root in sorted(action_root.iterdir()):
        if (
            not day_root.is_dir()
            or day_root.is_symlink()
            or re.fullmatch(r"\d{4}-\d{2}-\d{2}", day_root.name)
            is None
        ):
            continue
        paths.extend(
            path
            for path in sorted(day_root.glob("*.jsonl"))
            if (
                not path.is_symlink()
                and re.fullmatch(r"[0-9a-f]{2}\.jsonl", path.name)
            )
        )
    return paths


def _class_analysis_vignette_training_legacy_action_hash(
    action_root: Path,
    action_id: str,
) -> Optional[str]:
    """Find a pre-stable-shard action lazily for upgrade-safe retries."""

    for path in _class_analysis_vignette_training_action_files(action_root):
        try:
            if path.parent.name == "events":
                continue
            ids = _class_analysis_training_action_refresh_id_index(path)
        except HTTPException:
            raise
        if action_id in ids:
            return str(ids.get(action_id) or "")
    return None


def _class_analysis_vignette_training_annotation_target(
    value: Any,
) -> Optional[Dict[str, str]]:
    if not isinstance(value, Mapping):
        return None
    mode = str(value.get("source_mode") or "").strip().lower()
    if mode == "dataset":
        mode = "linked"
    elif mode == "open_path":
        mode = "transient"
    if mode not in {"linked", "transient"}:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="training_annotation_target_invalid",
        )
    source_id = str(value.get("source_id") or "").strip()
    if not source_id or len(source_id) > 256:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="training_annotation_target_invalid",
        )
    try:
        split = _annotation_normalise_split(value.get("split"))
        relpath = _annotation_normalise_image_relpath(
            value.get("image_relpath")
        ).as_posix()
    except Exception as exc:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="training_annotation_target_invalid",
        ) from exc
    return {
        "source_mode": mode,
        "source_id": source_id,
        "split": split,
        "image_relpath": relpath,
    }


def _class_analysis_vignette_training_derived_annotation_target(
    event: Mapping[str, Any],
) -> Optional[Dict[str, str]]:
    point = event.get("point")
    if not isinstance(point, Mapping):
        return None
    source = point.get("source")
    image = point.get("image")
    if (
        not isinstance(source, Mapping)
        or not isinstance(image, Mapping)
    ):
        return None
    mode = str(source.get("mode") or "").strip().lower()
    if mode not in {"linked", "transient"}:
        return None
    return _class_analysis_vignette_training_annotation_target(
        {
            "source_mode": mode,
            "source_id": source.get("id"),
            "split": image.get("split"),
            "image_relpath": image.get("relpath"),
        }
    )


def _class_analysis_vignette_training_derived_linked_target(
    event: Mapping[str, Any],
) -> Optional[Dict[str, str]]:
    target = _class_analysis_vignette_training_derived_annotation_target(
        event
    )
    return (
        target
        if target is not None and target.get("source_mode") == "linked"
        else None
    )


def _class_analysis_vignette_training_attestation_hash(
    attestation: Mapping[str, Any],
) -> str:
    payload = {
        key: value
        for key, value in dict(attestation).items()
        if key != "attestation_sha256"
    }
    return hashlib.sha256(
        json.dumps(
            _class_analysis_json_safe(payload),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _class_analysis_vignette_training_commit_attestation_valid(
    attestation: Any,
    *,
    commit_event: Mapping[str, Any],
    source_event: Mapping[str, Any],
) -> bool:
    if not isinstance(attestation, Mapping):
        return False
    expected_hash = str(
        attestation.get("attestation_sha256") or ""
    ).strip().lower()
    if (
        not re.fullmatch(r"[0-9a-f]{64}", expected_hash)
    ):
        return False
    schema = str(attestation.get("schema") or "")
    if schema == CLASS_ANALYSIS_CLASS_REASSIGNMENT_ATTESTATION_SCHEMA:
        if (
            _class_analysis_class_reassignment_attestation_hash(attestation)
            != expected_hash
        ):
            return False
    elif (
        _class_analysis_vignette_training_attestation_hash(attestation)
        != expected_hash
    ):
        return False
    try:
        target = _class_analysis_vignette_training_annotation_target(
            attestation.get("annotation_target")
        )
        commit_target = _class_analysis_vignette_training_annotation_target(
            commit_event.get("annotation_target")
        )
        source_target = _class_analysis_vignette_training_annotation_target(
            source_event.get("annotation_target")
        )
    except HTTPException:
        return False
    if target is None or commit_target != target:
        return False
    if source_target is not None and source_target != target:
        return False
    source_record_sha256 = str(
        source_event.get("record_sha256") or ""
    ).strip().lower()
    image_sha256 = str(
        ((source_event.get("point") or {}).get("image") or {}).get(
            "sha256"
        )
        if isinstance(source_event.get("point"), Mapping)
        else ""
    ).strip().lower()
    geometry = (
        (source_event.get("point") or {}).get("bbox")
        if isinstance(source_event.get("point"), Mapping)
        else None
    )
    try:
        verified_at = float(attestation.get("verified_at") or 0.0)
    except (TypeError, ValueError):
        return False
    if schema == CLASS_ANALYSIS_CLASS_REASSIGNMENT_ATTESTATION_SCHEMA:
        source_geometry_edit = _class_analysis_bbox_geometry_edit_request_payload(
            source_event.get("geometry_edit")
        )
        commit_geometry_edit = _class_analysis_bbox_geometry_edit_request_payload(
            commit_event.get("geometry_edit")
        )
        attested_geometry_edit = (
            _class_analysis_bbox_geometry_edit_request_payload(
                attestation.get("geometry_edit")
            )
        )
        source_point_identity = (
            source_event.get("point", {}).get("identity", {})
            if isinstance(source_event.get("point"), Mapping)
            else {}
        )
        source_request_geometry = (
            source_event.get("geometry_edit")
            if isinstance(source_event.get("geometry_edit"), Mapping)
            else {}
        )
        attested_geometry = (
            attestation.get("geometry_edit")
            if isinstance(attestation.get("geometry_edit"), Mapping)
            else {}
        )
        return bool(
            attestation.get("committed") is True
            and target is not None
            and source_target == target
            and str(attestation.get("analysis_job_id") or "")
                == str(source_event.get("analysis_job_id") or "")
                == str(commit_event.get("analysis_job_id") or "")
            and str(attestation.get("point_id") or "")
                == str(source_point_identity.get("id") or "")
            and str(attestation.get("source_review_object_key") or "")
                == str(source_event.get("review_object_key") or "")
            and str(attestation.get("before_class") or "")
                == str(source_event.get("before_class") or "")
                == str(commit_event.get("before_class") or "")
            and str(attestation.get("committed_class") or "")
                == str(source_event.get("after_class") or "")
                == str(commit_event.get("after_class") or "")
            and source_geometry_edit is not None
            and commit_geometry_edit == attested_geometry_edit
            and _class_analysis_json_safe(
                source_request_geometry.get("analysis_geometry")
            ) == _class_analysis_json_safe(
                attested_geometry.get("analysis_geometry")
            )
            and _class_analysis_json_safe(
                source_request_geometry.get("committed_geometry")
            ) == _class_analysis_json_safe(
                attested_geometry.get("committed_geometry")
            )
            and str(attestation.get("verification_method") or "")
                == CLASS_ANALYSIS_CLASS_REASSIGNMENT_VERIFICATION_METHOD
            and verified_at > 0.0
        )
    return bool(
        attestation.get("verified") is True
        and schema
        == "vignette-training-annotation-commit-attestation-v1"
        and re.fullmatch(r"[0-9a-f]{64}", image_sha256)
        and str(attestation.get("image_sha256") or "").strip().lower()
        == image_sha256
        and str(attestation.get("visual_object_key") or "")
        == str(source_event.get("visual_object_key") or "")
        == str(commit_event.get("visual_object_key") or "")
        and _class_analysis_json_safe(attestation.get("geometry"))
        == _class_analysis_json_safe(geometry)
        and str(attestation.get("committed_class") or "")
        == str(source_event.get("after_class") or "")
        == str(commit_event.get("after_class") or "")
        and str(attestation.get("source_action_id") or "")
        == str(source_event.get("action_id") or "")
        and re.fullmatch(r"[0-9a-f]{64}", source_record_sha256)
        and str(
            attestation.get("source_record_sha256") or ""
        ).strip().lower()
        == source_record_sha256
        and str(attestation.get("verification_method") or "")
        == "current_annotation_geometry_iou_v1"
        and verified_at > 0.0
    )


def _class_analysis_append_vignette_training_action(
    event: Mapping[str, Any],
) -> bool:
    action_root = _class_analysis_vignette_training_action_root(create=True)
    if action_root is None:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="vignette_training_action_store_unavailable",
        )
    review_object_key = str(event.get("review_object_key") or "")
    match = re.fullmatch(r"cro_([0-9a-f]{64})", review_object_key)
    if match is None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_object_key_missing",
        )
    action_id = str(event.get("action_id") or "").strip()
    if not action_id:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="training_action_id_missing",
        )
    # The physical shard is derived from the caller's deterministic action
    # token (falling back to the record id), not the event date or first point.
    # Batch children and an equivalent single-point retry therefore meet in
    # the same index as well as surviving UTC midnight and point reordering.
    shard_identity = str(
        event.get("client_action_id") or action_id
    ).strip()
    shard_id = hashlib.sha256(
        shard_identity.encode("utf-8")
    ).hexdigest()[:2]
    events_root = _class_analysis_prepare_private_audit_dir(
        action_root / "events",
        action_root,
        detail="vignette_training_action_store_unavailable",
    )
    path = _class_analysis_prepare_write_path(
        events_root / f"{shard_id}.jsonl",
        events_root,
    )
    if path is None:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="vignette_training_action_store_unavailable",
        )
    line = (
        json.dumps(
            _class_analysis_json_safe(dict(event)),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        + "\n"
    ).encode("utf-8")
    if len(line) > CLASS_ANALYSIS_TRAINING_ACTION_MAX_LINE_BYTES:
        raise HTTPException(
            status_code=HTTP_413_CONTENT_TOO_LARGE,
            detail="vignette_training_action_too_large",
        )
    with CLASS_ANALYSIS_TRAINING_ACTION_APPEND_LOCK:
        with _class_analysis_review_disposition_file_lock(
            action_root,
            "append",
        ):
            client_action_id = str(
                event.get("client_action_id") or ""
            ).strip()
            ids = _class_analysis_training_action_refresh_id_index(path)
            existing_hash: Optional[str] = (
                str(ids.get(action_id) or "")
                if action_id in ids
                else _class_analysis_vignette_training_legacy_action_hash(
                    action_root,
                    action_id,
                )
            )
            if client_action_id and existing_hash is not None:
                submitted_hash = str(
                    event.get("idempotency_payload_sha256") or ""
                )
                if (
                    str(existing_hash)
                    and submitted_hash
                    and str(existing_hash) != submitted_hash
                ):
                    raise HTTPException(
                        status_code=HTTP_409_CONFLICT,
                        detail="training_action_idempotency_conflict",
                    )
                return False
            flags = os.O_WRONLY | os.O_CREAT | os.O_APPEND
            if hasattr(os, "O_NOFOLLOW"):
                flags |= os.O_NOFOLLOW
            try:
                fd = os.open(path, flags, 0o600)
                try:
                    if hasattr(os, "fchmod"):
                        os.fchmod(fd, 0o600)
                    offset = 0
                    while offset < len(line):
                        written = os.write(fd, line[offset:])
                        if written <= 0:
                            raise OSError("short append")
                        offset += written
                    os.fsync(fd)
                finally:
                    os.close(fd)
                _fsync_directory(events_root)
            except HTTPException:
                raise
            except Exception as exc:
                raise HTTPException(
                    status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                    detail="vignette_training_action_append_failed",
                ) from exc
            cache_key = str(path.resolve(strict=False))
            with CLASS_ANALYSIS_TRAINING_ACTION_ID_INDEX_LOCK:
                state = CLASS_ANALYSIS_TRAINING_ACTION_ID_INDEX.get(cache_key)
                if state is not None:
                    state_ids = state.get("ids")
                    if isinstance(state_ids, dict) and action_id:
                        state_ids[action_id] = str(
                            event.get("idempotency_payload_sha256") or ""
                        )
                        for nested in (
                            event.get("events")
                            if isinstance(event.get("events"), list)
                            else []
                        ):
                            if not isinstance(nested, dict):
                                continue
                            nested_id = str(
                                nested.get("action_id") or ""
                            )
                            if nested_id:
                                state_ids[nested_id] = str(
                                    nested.get(
                                        "idempotency_payload_sha256"
                                    )
                                    or ""
                                )
                    try:
                        state["offset"] = int(path.stat().st_size)
                    except OSError:
                        # The append is already durable; a later refresh will
                        # recover the index from disk.
                        CLASS_ANALYSIS_TRAINING_ACTION_ID_INDEX.pop(
                            cache_key,
                            None,
                        )
    return True


def _class_analysis_record_vignette_training_commit(
    job_id: str,
    point_id: str,
    payload: Mapping[str, Any],
    *,
    clean_origin: str,
    clean_session_id: str,
    clean_group_id: str,
    authorization_source: str,
    authorization_actor: str,
    payload_annotation_target: Optional[Dict[str, str]],
) -> Dict[str, Any]:
    """Commit a captured correction without depending on a live analysis job."""

    commits_action_id = str(
        payload.get("commits_action_id") or ""
    ).strip()
    source_event = _class_analysis_vignette_training_action_by_id(
        commits_action_id
    )
    if (
        not isinstance(source_event, dict)
        or str(source_event.get("action_type") or "") != "change_class"
        or str(source_event.get("label_commit_status") or "")
        != "pending_desktop_sync"
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="training_commit_reference_invalid",
        )
    source_point = source_event.get("point")
    source_identity = (
        source_point.get("identity")
        if isinstance(source_point, Mapping)
        else {}
    )
    if (
        str(source_event.get("analysis_job_id") or "")
        != str(job_id or "")
        or str(
            (source_identity or {}).get("id")
            if isinstance(source_identity, Mapping)
            else ""
        )
        != str(point_id or "")
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="training_commit_reference_mismatch",
        )
    before_class = str(payload.get("before_class") or "").strip()
    after_class = str(payload.get("after_class") or "").strip()
    if not after_class:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="after_class_required",
        )
    if (
        before_class != str(source_event.get("before_class") or "")
        or after_class != str(source_event.get("after_class") or "")
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="training_commit_reference_mismatch",
        )
    raw_commit_status = str(
        payload.get("label_commit_status") or ""
    ).strip().lower()
    if raw_commit_status and raw_commit_status != "committed":
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="label_commit_status_invalid",
        )

    client_action_id = re.sub(
        r"[^A-Za-z0-9_.:-]+",
        "_",
        str(payload.get("client_action_id") or "").strip(),
    )[:160]
    action_id = (
        "client:"
        f"{client_action_id}:"
        f"{hashlib.sha256(point_id.encode('utf-8')).hexdigest()[:16]}"
        if client_action_id
        else f"vta_{uuid.uuid4().hex}"
    )
    existing_event = (
        _class_analysis_vignette_training_action_by_id(action_id)
        if client_action_id
        else None
    )
    source_target = (
        _class_analysis_vignette_training_annotation_target(
            source_event.get("annotation_target")
        )
        if source_event.get("annotation_target") is not None
        else _class_analysis_vignette_training_derived_annotation_target(
            source_event
        )
    )
    if source_target is None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="training_commit_annotation_target_required",
        )
    if (
        payload_annotation_target is not None
        and payload_annotation_target != source_target
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="training_commit_annotation_target_mismatch",
        )
    existing_target = (
        _class_analysis_vignette_training_annotation_target(
            existing_event.get("annotation_target")
        )
        if (
            isinstance(existing_event, Mapping)
            and existing_event.get("annotation_target") is not None
        )
        else None
    )
    if existing_target is not None and existing_target != source_target:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="training_action_idempotency_conflict",
        )

    source_image_sha256 = str(
        ((source_point or {}).get("image") or {}).get("sha256")
        if isinstance(source_point, Mapping)
        else ""
    ).strip().lower()
    visual_object_key = str(
        source_event.get("visual_object_key") or ""
    )
    existing_attestation = (
        existing_event.get("annotation_commit_attestation")
        if isinstance(existing_event, Mapping)
        else None
    )
    source_geometry_edit = (
        source_event.get("geometry_edit")
        if isinstance(source_event.get("geometry_edit"), Mapping)
        else None
    )
    reassignment_key = _class_analysis_review_reassignment_key(
        review_object_key=str(source_event.get("review_object_key") or ""),
        analysis_job_id=str(source_event.get("analysis_job_id") or ""),
    )
    stored_reassignment = _class_analysis_lookup_review_dispositions(
        [reassignment_key]
    ).get(reassignment_key)
    stored_reassignment_attestation = (
        stored_reassignment.get("class_reassignment_attestation")
        if isinstance(stored_reassignment, Mapping)
        and isinstance(
            stored_reassignment.get("class_reassignment_attestation"),
            Mapping,
        )
        else None
    )
    if (
        isinstance(existing_attestation, Mapping)
        and _class_analysis_vignette_training_commit_attestation_valid(
            existing_attestation,
            commit_event=existing_event,
            source_event=source_event,
        )
    ):
        attestation = dict(existing_attestation)
    elif source_geometry_edit is not None:
        payload_geometry = _class_analysis_bbox_geometry_edit_request_payload(
            payload.get("geometry_edit")
        )
        source_geometry = _class_analysis_bbox_geometry_edit_request_payload(
            source_geometry_edit
        )
        stored_geometry = (
            _class_analysis_bbox_geometry_edit_request_payload(
                stored_reassignment_attestation.get("geometry_edit")
            )
            if isinstance(stored_reassignment_attestation, Mapping)
            else None
        )
        if (
            not isinstance(stored_reassignment, Mapping)
            or str(stored_reassignment.get("disposition") or "")
                != "reassign_class"
            or str(stored_reassignment.get("analysis_job_id") or "")
                != str(source_event.get("analysis_job_id") or "")
            or str(stored_reassignment.get("point_id") or "")
                != str((source_identity or {}).get("id") or "")
            or str(stored_reassignment.get("target_class") or "")
                != after_class
            or not isinstance(stored_reassignment_attestation, Mapping)
            or payload_geometry is None
            or source_geometry is None
            or payload_geometry != source_geometry
            or _class_analysis_json_safe(
                source_geometry_edit.get("analysis_geometry")
            ) != _class_analysis_json_safe(
                (stored_reassignment_attestation.get("geometry_edit") or {}).get(
                    "analysis_geometry"
                )
            )
            or _class_analysis_json_safe(
                source_geometry_edit.get("committed_geometry")
            ) != _class_analysis_json_safe(
                (stored_reassignment_attestation.get("geometry_edit") or {}).get(
                    "committed_geometry"
                )
            )
            or str(payload.get("annotation_before_revision") or "").strip()
                != str(
                    stored_reassignment_attestation.get("before_revision")
                    or ""
                )
            or str(payload.get("annotation_commit_revision") or "").strip()
                != str(
                    stored_reassignment_attestation.get(
                        "committed_revision"
                    )
                    or ""
                )
            or str(payload.get("annotation_source_identity") or "").strip()
                != str(
                    stored_reassignment_attestation.get("source_identity")
                    or ""
                )
        ):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="training_commit_reassignment_attestation_invalid",
            )
        attestation = copy.deepcopy(
            dict(stored_reassignment_attestation)
        )
    else:
        verified_class = (
            _class_analysis_vignette_current_annotation_target_class(
                source_event,
                source_target,
                {},
            )
        )
        if (
            verified_class != after_class
            or not re.fullmatch(
                r"[0-9a-f]{64}", source_image_sha256
            )
        ):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="training_commit_annotation_unverified",
            )
        verified_at = time.time()
        attestation = {
            "schema": (
                "vignette-training-annotation-commit-attestation-v1"
            ),
            "verified": True,
            "annotation_target": source_target,
            "image_sha256": source_image_sha256,
            "visual_object_key": visual_object_key,
            "geometry": (
                (source_point or {}).get("bbox")
                if isinstance(source_point, Mapping)
                else None
            ),
            "committed_class": after_class,
            "source_action_id": str(
                source_event.get("action_id") or ""
            ),
            "source_record_sha256": str(
                source_event.get("record_sha256") or ""
            ),
            "verification_method": (
                "current_annotation_geometry_iou_v1"
            ),
            "verified_at": verified_at,
        }
        attestation["attestation_sha256"] = (
            _class_analysis_vignette_training_attestation_hash(
                attestation
            )
        )

    now = time.time()
    review_object_key = str(
        source_event.get("review_object_key") or ""
    )
    event: Dict[str, Any] = {
        "schema": CLASS_ANALYSIS_TRAINING_ACTION_SCHEMA,
        "action_id": action_id,
        "client_action_id": client_action_id,
        "recorded_at": now,
        "recorded_at_iso": time.strftime(
            "%Y-%m-%dT%H:%M:%SZ",
            time.gmtime(now),
        ),
        "consent": {
            "explicit_opt_in": True,
            "control": "class_split_training_capture",
            "policy_version": (
                CLASS_ANALYSIS_TRAINING_ACTION_POLICY_VERSION
            ),
        },
        "authorization": {
            "source": authorization_source,
            "actor": authorization_actor,
        },
        "action_type": "commit_class_change",
        "action_semantics": "commit_marker",
        "origin": clean_origin,
        "session_id": clean_session_id,
        "group_id": clean_group_id,
        "analysis_job_id": str(job_id or ""),
        "review_object_key": review_object_key,
        "visual_object_key": visual_object_key,
        "before_class": before_class,
        "after_class": after_class,
        "label_commit_status": "committed",
        "tombstone_of_action_id": "",
        "commits_action_id": commits_action_id,
        "annotation_target": source_target,
        "point": copy.deepcopy(source_point),
        "model_review": None,
        "artifacts": [],
        "validated_commit_reference": {
            "action_id": str(source_event.get("action_id") or ""),
            "record_sha256": str(
                source_event.get("record_sha256") or ""
            ),
            "visual_object_key": visual_object_key,
            "after_class": after_class,
        },
        "annotation_commit_attestation": attestation,
        "training_eligibility": {
            "classification": False,
            "preference": False,
            "rail_use": False,
            "visual_artifact": False,
        },
        "action": {
            "type": "commit_class_change",
            "semantics": "commit_marker",
            "annotation_commit_status": "committed",
            "reverts_event_id": None,
            "commits_event_id": commits_action_id,
        },
        "object": {
            "visual_object_key": visual_object_key,
            "review_object_key_before": review_object_key,
            "review_object_key_after": None,
            "before_class": before_class,
            "after_class": after_class,
        },
        "analysis": copy.deepcopy(
            source_event.get("analysis") or {
                "job_id": str(job_id or ""),
                "configuration_digest": "",
                "rails": {},
            }
        ),
    }
    if source_geometry_edit is not None:
        event["geometry_edit"] = copy.deepcopy(
            dict(attestation.get("geometry_edit") or {})
        )
    idempotency_payload = {
        key: value
        for key, value in event.items()
        if key not in {"recorded_at", "recorded_at_iso"}
    }
    event["idempotency_payload_sha256"] = hashlib.sha256(
        json.dumps(
            _class_analysis_json_safe(idempotency_payload),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    event["record_sha256"] = hashlib.sha256(
        json.dumps(
            _class_analysis_json_safe(event),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    appended = _class_analysis_append_vignette_training_action(event)
    return {
        "status": "recorded" if appended else "already_recorded",
        "recorded_count": 1 if appended else 0,
        "duplicate_count": 0 if appended else 1,
        "action_ids": [action_id] if appended else [],
        "duplicate_action_ids": [] if appended else [action_id],
        "batch_id": "",
        "schema": CLASS_ANALYSIS_TRAINING_ACTION_SCHEMA,
    }


def _class_analysis_vignette_training_request_contract(
    *,
    action_id: str,
    client_action_id: str,
    job_id: str,
    point_id: str,
    action_type: str,
    clean_origin: str,
    clean_session_id: str,
    clean_group_id: str,
    authorization_source: str,
    authorization_actor: str,
    before_class: str,
    after_class: str,
    label_commit_status: str,
    tombstone_of_action_id: str,
    commits_action_id: str,
    annotation_target: Optional[Mapping[str, Any]],
    point_snapshot: Mapping[str, Any],
    requested_review_id: str,
    dual_pair_resolution: Optional[Mapping[str, Any]],
    single_bbox_deletion_attestation: Optional[Mapping[str, Any]],
    geometry_edit: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Build the immutable caller/server contract for one captured action.

    Model output and copied artifacts deliberately do not belong here. They are
    a snapshot taken when the action first lands, not caller intent. Keeping
    that distinction lets a lost-response retry reuse the durable record even
    if a newer VLM review has since completed, while every authorization,
    object, annotation, and action binding still has to match exactly.
    """

    point_snapshot_sha256 = hashlib.sha256(
        json.dumps(
            _class_analysis_json_safe(dict(point_snapshot)),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return _class_analysis_json_safe(
        {
            "schema": (
                CLASS_ANALYSIS_TRAINING_ACTION_REQUEST_CONTRACT_SCHEMA
            ),
            "policy_version": CLASS_ANALYSIS_TRAINING_ACTION_POLICY_VERSION,
            "action_id": str(action_id or ""),
            "client_action_id": str(client_action_id or ""),
            "analysis_job_id": str(job_id or ""),
            "point_id": str(point_id or ""),
            "action_type": str(action_type or ""),
            "origin": str(clean_origin or ""),
            "session_id": str(clean_session_id or ""),
            "group_id": str(clean_group_id or ""),
            "authorization": {
                "source": str(authorization_source or ""),
                "actor": str(authorization_actor or ""),
            },
            "before_class": str(before_class or ""),
            "after_class": str(after_class or ""),
            "label_commit_status": str(label_commit_status or ""),
            "tombstone_of_action_id": str(
                tombstone_of_action_id or ""
            ),
            "commits_action_id": str(commits_action_id or ""),
            "annotation_target": (
                dict(annotation_target)
                if isinstance(annotation_target, Mapping)
                else None
            ),
            "review_object_key": str(
                ((point_snapshot.get("identity") or {}).get(
                    "review_object_key"
                ))
                if isinstance(point_snapshot.get("identity"), Mapping)
                else ""
            ),
            "visual_object_key": str(
                ((point_snapshot.get("identity") or {}).get(
                    "visual_object_key"
                ))
                if isinstance(point_snapshot.get("identity"), Mapping)
                else ""
            ),
            "point_snapshot_sha256": point_snapshot_sha256,
            # Empty means the endpoint was allowed to snapshot whichever
            # completed review was newest at first write. A later implicit
            # review must never rewrite that already-durable snapshot.
            "requested_review_id": str(requested_review_id or ""),
            "dual_bbox_pair_resolution": (
                dict(dual_pair_resolution)
                if isinstance(dual_pair_resolution, Mapping)
                else None
            ),
            "single_bbox_deletion_attestation": (
                dict(single_bbox_deletion_attestation)
                if isinstance(single_bbox_deletion_attestation, Mapping)
                else None
            ),
            "geometry_edit": (
                dict(geometry_edit)
                if isinstance(geometry_edit, Mapping)
                else None
            ),
        }
    )


def _class_analysis_vignette_training_legacy_request_contract(
    existing_event: Mapping[str, Any],
    expected_contract: Mapping[str, Any],
) -> Dict[str, Any]:
    """Reconstruct the request contract for records written before the field."""

    model_review = existing_event.get("model_review")
    requested_review_id = ""
    if (
        isinstance(model_review, Mapping)
        and str(model_review.get("linkage_method") or "")
        == "explicit_review_id"
    ):
        requested_review_id = str(model_review.get("review_id") or "")
    existing_pair = existing_event.get("dual_bbox_resolution")
    expected_pair = expected_contract.get("dual_bbox_pair_resolution")
    canonical_pair = None
    if isinstance(expected_pair, Mapping) and isinstance(existing_pair, Mapping):
        canonical_pair = {
            key: copy.deepcopy(existing_pair.get(key)) for key in expected_pair
        }
    point_snapshot = (
        existing_event.get("point")
        if isinstance(existing_event.get("point"), Mapping)
        else {}
    )
    return _class_analysis_vignette_training_request_contract(
        action_id=str(existing_event.get("action_id") or ""),
        client_action_id=str(existing_event.get("client_action_id") or ""),
        job_id=str(existing_event.get("analysis_job_id") or ""),
        point_id=str(
            ((point_snapshot.get("identity") or {}).get("id"))
            if isinstance(point_snapshot.get("identity"), Mapping)
            else ""
        ),
        action_type=str(existing_event.get("action_type") or ""),
        clean_origin=str(existing_event.get("origin") or ""),
        clean_session_id=str(existing_event.get("session_id") or ""),
        clean_group_id=str(existing_event.get("group_id") or ""),
        authorization_source=str(
            ((existing_event.get("authorization") or {}).get("source"))
            if isinstance(existing_event.get("authorization"), Mapping)
            else ""
        ),
        authorization_actor=str(
            ((existing_event.get("authorization") or {}).get("actor"))
            if isinstance(existing_event.get("authorization"), Mapping)
            else ""
        ),
        before_class=str(existing_event.get("before_class") or ""),
        after_class=str(existing_event.get("after_class") or ""),
        label_commit_status=str(
            existing_event.get("label_commit_status") or ""
        ),
        tombstone_of_action_id=str(
            existing_event.get("tombstone_of_action_id") or ""
        ),
        commits_action_id=str(existing_event.get("commits_action_id") or ""),
        annotation_target=(
            existing_event.get("annotation_target")
            if isinstance(existing_event.get("annotation_target"), Mapping)
            else None
        ),
        point_snapshot=point_snapshot,
        requested_review_id=requested_review_id,
        dual_pair_resolution=canonical_pair,
        single_bbox_deletion_attestation=(
            existing_event.get("single_bbox_deletion_attestation")
            if isinstance(
                existing_event.get("single_bbox_deletion_attestation"),
                Mapping,
            )
            else None
        ),
        geometry_edit=(
            existing_event.get("geometry_edit")
            if isinstance(existing_event.get("geometry_edit"), Mapping)
            else None
        ),
    )


def _class_analysis_vignette_training_validate_existing_replay(
    existing_event: Mapping[str, Any],
    expected_contract: Mapping[str, Any],
) -> None:
    stored_contract = existing_event.get("request_contract")
    if isinstance(stored_contract, Mapping):
        actual_contract = _class_analysis_json_safe(dict(stored_contract))
    else:
        actual_contract = _class_analysis_vignette_training_legacy_request_contract(
            existing_event,
            expected_contract,
        )
    if actual_contract != _class_analysis_json_safe(dict(expected_contract)):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="training_action_idempotency_conflict",
        )


def _class_analysis_vignette_training_actions_by_id(
    action_ids: Iterable[str],
    *,
    client_action_id: str,
) -> Dict[str, Dict[str, Any]]:
    wanted = {str(action_id or "").strip() for action_id in action_ids}
    wanted.discard("")
    clean_client_action_id = str(client_action_id or "").strip()
    if not wanted or not clean_client_action_id:
        return {}
    action_root = _class_analysis_vignette_training_action_root(create=False)
    if action_root is None:
        return {}
    shard_id = hashlib.sha256(
        clean_client_action_id.encode("utf-8")
    ).hexdigest()[:2]
    stable_path = action_root / "events" / f"{shard_id}.jsonl"
    indexed_ids: Set[str] = set()
    if stable_path.is_file() and not stable_path.is_symlink():
        with CLASS_ANALYSIS_TRAINING_ACTION_APPEND_LOCK:
            with _class_analysis_review_disposition_file_lock(
                action_root,
                "append",
            ):
                stable_index = _class_analysis_training_action_refresh_id_index(
                    stable_path
                )
        indexed_ids.update(wanted.intersection(stable_index))
    for action_id in wanted.difference(indexed_ids):
        if _class_analysis_vignette_training_legacy_action_hash(
            action_root,
            action_id,
        ) is not None:
            indexed_ids.add(action_id)
    # A first-time action stays on the cheap per-shard index path. Only a real
    # retry pays for reconstructing its integrity-validated durable event.
    if not indexed_ids:
        return {}
    found: Dict[str, Dict[str, Any]] = {}
    for event in _class_analysis_iter_vignette_training_actions():
        action_id = str(event.get("action_id") or "").strip()
        if action_id not in indexed_ids:
            continue
        previous = found.get(action_id)
        if (
            previous is not None
            and str(previous.get("record_sha256") or "")
            != str(event.get("record_sha256") or "")
        ):
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                detail="vignette_training_action_store_corrupt",
            )
        found[action_id] = event
        if len(found) == len(indexed_ids):
            break
    if set(found) != indexed_ids:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="vignette_training_action_store_corrupt",
        )
    return found


def record_class_analysis_vignette_training_action(
    job_id: str,
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    """Append explicitly opted-in semantic review actions.

    This endpoint does not modify labels, review queues, or the current-state
    disposition ledger. It only records a training candidate after the
    human-controlled action succeeds.
    """

    payload = payload if isinstance(payload, dict) else {}
    if payload.get("capture_training_data") is not True:
        return {
            "status": "not_recorded",
            "reason": "explicit_opt_in_required",
            "recorded_count": 0,
        }
    action_type = str(payload.get("action_type") or "").strip().lower()
    allowed_actions = {
        "confirm_current",
        "skip",
        "delete_bbox",
        "undo_review",
        "change_class",
        "commit_class_change",
        "delete_current_box",
        "delete_overlapping_box",
        "keep_both_boxes",
        "unresolved",
        "discard",
    }
    if action_type not in allowed_actions:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="training_action_type_invalid",
        )
    if (
        action_type == "commit_class_change"
        and not str(payload.get("commits_action_id") or "").strip()
    ):
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="commits_action_id_required",
        )
    raw_point_ids = payload.get("point_ids")
    if isinstance(raw_point_ids, list):
        point_ids = [
            str(point_id or "").strip()
            for point_id in raw_point_ids
            if str(point_id or "").strip()
        ]
    else:
        point_id = str(payload.get("point_id") or "").strip()
        point_ids = [point_id] if point_id else []
    point_ids = list(dict.fromkeys(point_ids))
    if not point_ids:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="point_id_required",
        )
    if len(point_ids) > 100:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="training_action_batch_too_large",
        )
    if action_type == "commit_class_change" and len(point_ids) != 1:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="commit_class_change_requires_one_point",
        )
    clean_origin = re.sub(
        r"[^A-Za-z0-9_.-]+",
        "_",
        str(payload.get("origin") or "desktop").strip(),
    )[:48] or "desktop"
    clean_session_id = re.sub(
        r"[^A-Za-z0-9_.:-]+",
        "_",
        str(payload.get("session_id") or "").strip(),
    )[:128]
    clean_group_id = re.sub(
        r"[^A-Za-z0-9_.:-]+",
        "_",
        str(payload.get("group_id") or "").strip(),
    )[:128]
    supplied_review_ids = (
        payload.get("review_ids")
        if isinstance(payload.get("review_ids"), dict)
        else {}
    )
    authorization_payload = (
        payload.get("_training_authorization")
        if isinstance(payload.get("_training_authorization"), dict)
        else {}
    )
    authorization_source = str(
        authorization_payload.get("source") or "internal"
    )[:64]
    authorization_actor = str(
        authorization_payload.get("actor") or "local_user"
    )
    if authorization_actor not in {"local_user", "token_holder"}:
        authorization_actor = (
            "actor_"
            + hashlib.sha256(
                authorization_actor.encode("utf-8")
            ).hexdigest()[:16]
        )
    payload_annotation_target = (
        _class_analysis_vignette_training_annotation_target(
            payload.get("annotation_target")
        )
        if payload.get("annotation_target") is not None
        else None
    )
    if action_type == "commit_class_change":
        return _class_analysis_record_vignette_training_commit(
            job_id,
            point_ids[0],
            payload,
            clean_origin=clean_origin,
            clean_session_id=clean_session_id,
            clean_group_id=clean_group_id,
            authorization_source=authorization_source,
            authorization_actor=authorization_actor,
            payload_annotation_target=payload_annotation_target,
        )
    client_action_id = re.sub(
        r"[^A-Za-z0-9_.:-]+",
        "_",
        str(payload.get("client_action_id") or "").strip(),
    )[:160]
    action_ids_by_point = {
        point_id: (
            "client:"
            f"{client_action_id}:"
            f"{hashlib.sha256(point_id.encode('utf-8')).hexdigest()[:16]}"
        )
        for point_id in point_ids
    } if client_action_id else {}
    existing_events = _class_analysis_vignette_training_actions_by_id(
        action_ids_by_point.values(),
        client_action_id=client_action_id,
    )
    job = _get_class_analysis_job(job_id)
    now = time.time()
    resolved: List[Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]] = []
    preexisting_action_ids: List[str] = []
    for point_id in point_ids:
        point, summary = _class_analysis_vignette_training_point(job, point_id)
        _class_analysis_require_dual_bbox_pair_action(
            point,
            action=action_type,
        )
        dual_pair_resolution: Optional[Dict[str, Any]] = None
        dual_pair_conflict: Optional[Dict[str, Any]] = None
        single_bbox_deletion_attestation: Optional[Dict[str, Any]] = None
        if action_type in CLASS_ANALYSIS_DUAL_BBOX_REVIEW_DISPOSITIONS:
            (
                dual_pair_resolution,
                dual_pair_conflict,
            ) = _class_analysis_vignette_training_dual_pair_contract(
                job=job,
                point=point,
                action_type=action_type,
                payload=payload,
            )
        elif action_type == "delete_bbox":
            review_object_key = str(
                point.get("review_object_key") or ""
            ).strip()
            supplied_attestation = payload.get(
                "single_bbox_deletion_attestation"
            )
            stored_disposition = (
                _class_analysis_lookup_review_dispositions(
                    [review_object_key]
                ).get(review_object_key)
            )
            stored_attestation = (
                stored_disposition.get(
                    "single_bbox_deletion_attestation"
                )
                if isinstance(stored_disposition, Mapping)
                else None
            )
            if (
                re.fullmatch(r"cro_[0-9a-f]{64}", review_object_key)
                is None
                or not isinstance(stored_disposition, Mapping)
                or str(stored_disposition.get("disposition") or "")
                != "delete_bbox"
                or str(
                    stored_disposition.get("analysis_job_id") or ""
                )
                != str(job.job_id or job_id or "")
                or str(stored_disposition.get("point_id") or "")
                != point_id
                or stored_disposition.get("training_capture_requested")
                is not True
                or str(
                    stored_disposition.get("client_action_id") or ""
                )
                != str(payload.get("client_action_id") or "").strip()
                or str(stored_disposition.get("origin") or "")
                != clean_origin
                or not isinstance(stored_attestation, Mapping)
                or not isinstance(supplied_attestation, Mapping)
                or _class_analysis_json_safe(supplied_attestation)
                != _class_analysis_json_safe(stored_attestation)
            ):
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=(
                        "single_bbox_deletion_training_attestation_invalid"
                    ),
                )
            single_bbox_deletion_attestation = copy.deepcopy(
                dict(stored_attestation)
            )
        frozen_class = str(point.get("class_name") or "").strip()
        supplied_before_class = str(
            payload.get("before_class") or ""
        ).strip()
        if (
            action_type == "change_class"
            and supplied_before_class
            and supplied_before_class != frozen_class
        ):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="before_class_mismatch",
            )
        before_class = supplied_before_class or frozen_class
        after_class = str(
            payload.get("after_class") or before_class
        ).strip()
        if action_type == "change_class":
            if not str(payload.get("after_class") or "").strip():
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="after_class_required",
                )
            labelmap = {
                str(name or "").strip()
                for name in (summary.get("labelmap") or [])
                if str(name or "").strip()
            }
            if labelmap and after_class not in labelmap:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="after_class_unknown",
                )
        review_id = str(
            supplied_review_ids.get(point_id)
            or payload.get("review_id")
            or ""
        ).strip()
        semantics = {
            "confirm_current": "label_decision",
            "change_class": "label_decision",
            "commit_class_change": "commit_marker",
            "skip": "human_abstention",
            "delete_bbox": "geometry_decision",
            "delete_current_box": "geometry_decision",
            "delete_overlapping_box": "geometry_decision",
            "keep_both_boxes": "geometry_decision",
            "unresolved": "human_abstention",
            "undo_review": "history_tombstone",
            "discard": "queue_navigation",
        }[action_type]
        action_id = (
            action_ids_by_point[point_id]
            if client_action_id
            else f"vta_{uuid.uuid4().hex}"
        )
        point_snapshot = _class_analysis_vignette_training_point_snapshot(
            point,
            summary,
        )
        geometry_edit: Optional[Dict[str, Any]] = None
        if action_type == "change_class" and payload.get(
            "geometry_edit"
        ) is not None:
            image_snapshot = point_snapshot.get("image")
            image_snapshot = (
                image_snapshot
                if isinstance(image_snapshot, Mapping)
                else {}
            )
            geometry_edit = _class_analysis_bbox_geometry_edit_contract(
                payload.get("geometry_edit"),
                point_snapshot=point_snapshot,
                image_width=_coerce_int(image_snapshot.get("width"), 0),
                image_height=_coerce_int(image_snapshot.get("height"), 0),
            )
        visual_object_key = str(
            (point_snapshot.get("identity") or {}).get(
                "visual_object_key"
            )
            or ""
        )
        raw_commit_status = str(
            payload.get("label_commit_status") or ""
        ).strip().lower()
        if action_type == "confirm_current":
            label_commit_status = raw_commit_status or "committed"
            if label_commit_status != "committed":
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="label_commit_status_invalid",
                )
        elif action_type == "change_class":
            label_commit_status = (
                raw_commit_status or "pending_desktop_sync"
            )
            if label_commit_status != "pending_desktop_sync":
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="label_commit_status_invalid",
                )
        elif action_type in {
            "delete_bbox",
            "delete_current_box",
            "delete_overlapping_box",
        }:
            if action_type != "delete_bbox" and (
                not isinstance(dual_pair_resolution, Mapping)
                or not isinstance(
                    dual_pair_resolution.get("annotation_commit_attestation"),
                    Mapping,
                )
            ):
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail="dual_bbox_deletion_attestation_required",
                )
            label_commit_status = raw_commit_status or "committed"
            allowed_commit_statuses = (
                {"committed", "already_absent"}
                if action_type == "delete_bbox"
                else {"committed"}
            )
            if label_commit_status not in allowed_commit_statuses:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="label_commit_status_invalid",
                )
        else:
            label_commit_status = "not_applicable"
        derived_annotation_target = (
            _class_analysis_vignette_training_derived_annotation_target(
                {"point": point_snapshot}
            )
        )
        attested_single_bbox_target = (
            _class_analysis_vignette_training_annotation_target(
                single_bbox_deletion_attestation.get(
                    "annotation_target"
                )
            )
            if isinstance(single_bbox_deletion_attestation, Mapping)
            else None
        )
        if (
            payload_annotation_target is not None
            and derived_annotation_target is not None
            and payload_annotation_target != derived_annotation_target
        ):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="training_annotation_target_mismatch",
            )
        if (
            action_type == "delete_bbox"
            and (
                attested_single_bbox_target is None
                or (
                    derived_annotation_target is not None
                    and attested_single_bbox_target
                    != derived_annotation_target
                )
                or (
                    payload_annotation_target is not None
                    and payload_annotation_target
                    != attested_single_bbox_target
                )
            )
        ):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail=(
                    "single_bbox_deletion_training_attestation_invalid"
                ),
            )
        annotation_target = (
            attested_single_bbox_target
            if action_type == "delete_bbox"
            else (derived_annotation_target or payload_annotation_target)
            if action_type in {"confirm_current", "change_class"}
            else payload_annotation_target
        )
        request_contract = _class_analysis_vignette_training_request_contract(
            action_id=action_id,
            client_action_id=client_action_id,
            job_id=str(job.job_id or job_id or ""),
            point_id=point_id,
            action_type=action_type,
            clean_origin=clean_origin,
            clean_session_id=clean_session_id,
            clean_group_id=clean_group_id,
            authorization_source=authorization_source,
            authorization_actor=authorization_actor,
            before_class=before_class,
            after_class=after_class,
            label_commit_status=label_commit_status,
            tombstone_of_action_id=str(
                payload.get("tombstone_of_action_id") or ""
            ).strip()[:192],
            commits_action_id=str(
                payload.get("commits_action_id") or ""
            ).strip()[:192],
            annotation_target=annotation_target,
            point_snapshot=point_snapshot,
            requested_review_id=review_id,
            dual_pair_resolution=dual_pair_resolution,
            single_bbox_deletion_attestation=(
                single_bbox_deletion_attestation
            ),
            geometry_edit=geometry_edit,
        )
        existing_event = existing_events.get(action_id)
        if existing_event is not None:
            _class_analysis_vignette_training_validate_existing_replay(
                existing_event,
                request_contract,
            )
            preexisting_action_ids.append(action_id)
            continue
        model_review = (
            None
            if action_type == "discard"
            else _class_analysis_vignette_training_model_review(
                job_id=str(job.job_id or job_id or ""),
                point_id=point_id,
                review_id=review_id,
            )
        )
        point_artifacts = (
            []
            if action_type == "discard"
            else _class_analysis_snapshot_vignette_point_media(job, point)
        )
        pair_review_artifacts = (
            _class_analysis_vignette_training_dual_pair_review_artifacts(
                model_review,
                pair_resolution=dual_pair_resolution,
            )
            if isinstance(dual_pair_resolution, Mapping)
            else []
        )
        event_artifacts = [
            *point_artifacts,
            *pair_review_artifacts,
        ]
        event = {
            "schema": CLASS_ANALYSIS_TRAINING_ACTION_SCHEMA,
            "action_id": action_id,
            "client_action_id": client_action_id,
            "recorded_at": now,
            "recorded_at_iso": time.strftime(
                "%Y-%m-%dT%H:%M:%SZ",
                time.gmtime(now),
            ),
            "consent": {
                "explicit_opt_in": True,
                "control": "class_split_training_capture",
                "policy_version": CLASS_ANALYSIS_TRAINING_ACTION_POLICY_VERSION,
            },
            "authorization": {
                "source": authorization_source,
                "actor": authorization_actor,
            },
            "action_type": action_type,
            "action_semantics": semantics,
            "origin": clean_origin,
            "session_id": clean_session_id,
            "group_id": clean_group_id,
            "analysis_job_id": str(job.job_id or job_id or ""),
            "review_object_key": str(
                point.get("review_object_key") or ""
            ),
            "visual_object_key": visual_object_key,
            "before_class": before_class,
            "after_class": after_class,
            "label_commit_status": label_commit_status,
            "tombstone_of_action_id": str(
                payload.get("tombstone_of_action_id") or ""
            ).strip()[:192],
            "commits_action_id": str(
                payload.get("commits_action_id") or ""
            ).strip()[:192],
            "annotation_target": annotation_target,
            "point": point_snapshot,
            "request_contract": request_contract,
            "model_review": model_review,
            "artifacts": event_artifacts,
        }
        if geometry_edit is not None:
            event["geometry_edit"] = copy.deepcopy(geometry_edit)
        if single_bbox_deletion_attestation is not None:
            event["single_bbox_deletion_attestation"] = (
                single_bbox_deletion_attestation
            )
        if (
            action_type in CLASS_ANALYSIS_DUAL_BBOX_REVIEW_DISPOSITIONS
            and isinstance(dual_pair_resolution, Mapping)
            and isinstance(dual_pair_conflict, Mapping)
        ):
            event["pair_review_key"] = str(
                dual_pair_resolution.get("pair_review_key") or ""
            )
            event["dual_bbox_resolution"] = {
                **copy.deepcopy(dict(dual_pair_resolution)),
                "conflict": _class_analysis_json_safe(dual_pair_conflict),
                "paired_vlm_artifact_sha256": [
                    str(artifact.get("sha256") or "")
                    for artifact in pair_review_artifacts
                    if str(artifact.get("sha256") or "")
                ],
            }
        preference_link_ok = bool(
            isinstance(model_review, dict)
            and model_review.get("preference_train_eligible") is True
        )
        event["training_eligibility"] = {
            "classification": (
                action_type in {"confirm_current", "change_class"}
                and label_commit_status == "committed"
                and bool(point_artifacts)
            ),
            "preference": (
                action_type in {"confirm_current", "change_class"}
                and label_commit_status == "committed"
                and preference_link_ok
            ),
            "rail_use": bool(model_review is not None),
            "visual_artifact": bool(event_artifacts),
            "dual_bbox_pair_visual": bool(pair_review_artifacts),
        }
        event["action"] = {
            "type": action_type,
            "semantics": semantics,
            "annotation_commit_status": label_commit_status,
            "reverts_event_id": event["tombstone_of_action_id"] or None,
            "commits_event_id": event["commits_action_id"] or None,
        }
        event["object"] = {
            "visual_object_key": visual_object_key,
            "review_object_key_before": event["review_object_key"],
            # The class is part of review_object_key. Without re-reading the
            # committed annotation/image dimensions we cannot safely invent
            # the canonical post-change key. visual_object_key is the stable
            # join across this correction.
            "review_object_key_after": (
                event["review_object_key"]
                if before_class == after_class
                else None
            ),
            "before_class": before_class,
            "after_class": after_class,
        }
        event["analysis"] = {
            "job_id": str(job.job_id or job_id or ""),
            "configuration_digest": hashlib.sha256(
                json.dumps(
                    _class_analysis_json_safe(
                        job.request if isinstance(job.request, dict) else {}
                    ),
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest(),
            "rails": point_snapshot.get("review_rails") or {},
        }
        idempotency_payload = {
            key: value
            for key, value in event.items()
            if key not in {"recorded_at", "recorded_at_iso"}
        }
        event["idempotency_payload_sha256"] = hashlib.sha256(
            json.dumps(
                _class_analysis_json_safe(idempotency_payload),
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        event["record_sha256"] = hashlib.sha256(
            json.dumps(
                _class_analysis_json_safe(event),
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        resolved.append((point, summary, event))
    if preexisting_action_ids:
        # One client action is atomic. Seeing only part of a deterministic
        # multi-point action indicates a conflicting/corrupt prior use; never
        # fill in the remainder under a potentially different dynamic snapshot.
        if len(preexisting_action_ids) != len(point_ids):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="training_action_idempotency_conflict",
            )
        replay_batch_id = (
            "batch:"
            + hashlib.sha256(client_action_id.encode("utf-8")).hexdigest()
            if len(point_ids) > 1
            else ""
        )
        return {
            "status": "already_recorded",
            "recorded_count": 0,
            "duplicate_count": len(preexisting_action_ids),
            "action_ids": [],
            "duplicate_action_ids": preexisting_action_ids,
            "batch_id": replay_batch_id,
            "schema": CLASS_ANALYSIS_TRAINING_ACTION_SCHEMA,
        }
    # Validate and construct the complete batch before the first append. A
    # malformed later point can therefore never leave a partial corpus batch.
    appended: List[str] = []
    duplicates: List[str] = []
    batch_id = ""
    if len(resolved) > 1:
        batch_client_action_id = str(
            resolved[0][2].get("client_action_id") or ""
        )
        batch_identity = (
            batch_client_action_id
            or f"{clean_session_id}:{clean_group_id}:{uuid.uuid4().hex}"
        )
        batch_id = (
            "batch:"
            + hashlib.sha256(batch_identity.encode("utf-8")).hexdigest()
        )
        batch_record = {
            "schema": "vignette-training-action-batch-v1",
            "action_id": batch_id,
            "client_action_id": batch_client_action_id,
            "idempotency_payload_sha256": hashlib.sha256(
                json.dumps(
                    sorted(
                        [
                            {
                                "action_id": str(
                                    event.get("action_id") or ""
                                ),
                                "payload_sha256": str(
                                    event.get(
                                        "idempotency_payload_sha256"
                                    )
                                    or ""
                                ),
                            }
                            for _, _, event in resolved
                        ],
                        key=lambda item: item["action_id"],
                    ),
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest(),
            "recorded_at": now,
            "recorded_at_iso": time.strftime(
                "%Y-%m-%dT%H:%M:%SZ",
                time.gmtime(now),
            ),
            "review_object_key": resolved[0][2][
                "review_object_key"
            ],
            "expected_count": len(resolved),
            "events": [event for _, _, event in resolved],
        }
        batch_record["record_sha256"] = hashlib.sha256(
            json.dumps(
                _class_analysis_json_safe(batch_record),
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        if _class_analysis_append_vignette_training_action(batch_record):
            appended.extend(
                str(event["action_id"]) for _, _, event in resolved
            )
        else:
            duplicates.extend(
                str(event["action_id"]) for _, _, event in resolved
            )
    else:
        for _point, _summary, event in resolved:
            if _class_analysis_append_vignette_training_action(event):
                appended.append(str(event["action_id"]))
            else:
                duplicates.append(str(event["action_id"]))
    return {
        "status": "recorded" if appended else "already_recorded",
        "recorded_count": len(appended),
        "duplicate_count": len(duplicates),
        "action_ids": appended,
        "duplicate_action_ids": duplicates,
        "batch_id": batch_id,
        "schema": CLASS_ANALYSIS_TRAINING_ACTION_SCHEMA,
    }


def _class_analysis_iter_vignette_training_actions() -> Iterator[Dict[str, Any]]:
    action_root = _class_analysis_vignette_training_action_root(create=False)
    if action_root is None:
        return
    # Take immutable prefix sizes while holding the same lock used by append.
    # Readers can then stream those prefixes without blocking later appends
    # and can never mistake an in-flight partial write for corpus corruption.
    snapshots: List[Tuple[Path, int]] = []
    with CLASS_ANALYSIS_TRAINING_ACTION_APPEND_LOCK:
        with _class_analysis_review_disposition_file_lock(
            action_root,
            "append",
        ):
            for path in _class_analysis_vignette_training_action_files(
                action_root
            ):
                safe_path = _safe_existing_regular_file_within_root_impl(
                    path,
                    action_root,
                )
                if safe_path is None:
                    raise HTTPException(
                        status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                        detail="vignette_training_action_store_corrupt",
                    )
                try:
                    snapshots.append(
                        (safe_path, int(safe_path.stat().st_size))
                    )
                except OSError as exc:
                    raise HTTPException(
                        status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                        detail="vignette_training_action_store_corrupt",
                    ) from exc
    for safe_path, snapshot_size in snapshots:
        with safe_path.open("rb") as handle:
            while handle.tell() < snapshot_size:
                remaining = snapshot_size - handle.tell()
                raw_line = handle.readline(
                    min(
                        CLASS_ANALYSIS_TRAINING_ACTION_MAX_LINE_BYTES + 1,
                        remaining,
                    )
                )
                if (
                    not raw_line
                    or len(raw_line)
                    > CLASS_ANALYSIS_TRAINING_ACTION_MAX_LINE_BYTES
                    or not raw_line.endswith(b"\n")
                ):
                    raise HTTPException(
                        status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                        detail="vignette_training_action_store_corrupt",
                    )
                try:
                    record = json.loads(raw_line)
                except Exception as exc:
                    raise HTTPException(
                        status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                        detail="vignette_training_action_store_corrupt",
                    ) from exc
                if (
                    isinstance(record, dict)
                    and record.get("schema")
                    == "vignette-training-action-batch-v1"
                ):
                    if not _class_analysis_vignette_training_batch_hash_valid(
                        record
                    ):
                        raise HTTPException(
                            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                            detail="vignette_training_action_store_corrupt",
                        )
                    events = record.get("events") or []
                else:
                    events = [record]
                for event in events:
                    if (
                        not isinstance(event, dict)
                        or event.get("schema")
                        != CLASS_ANALYSIS_TRAINING_ACTION_SCHEMA
                        or (event.get("consent") or {}).get(
                            "explicit_opt_in"
                        )
                        is not True
                        or not _class_analysis_vignette_training_event_hash_valid(
                            event
                        )
                    ):
                        raise HTTPException(
                            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                            detail="vignette_training_action_store_corrupt",
                        )
                    yield event


def _class_analysis_vignette_training_event_hash_valid(
    event: Mapping[str, Any],
) -> bool:
    expected_idempotency = str(
        event.get("idempotency_payload_sha256") or ""
    ).strip()
    expected_record = str(event.get("record_sha256") or "").strip()
    if (
        not re.fullmatch(r"[0-9a-f]{64}", expected_idempotency)
        or not re.fullmatch(r"[0-9a-f]{64}", expected_record)
    ):
        return False
    idempotency_payload = {
        key: value
        for key, value in event.items()
        if key
        not in {
            "idempotency_payload_sha256",
            "record_sha256",
            "recorded_at",
            "recorded_at_iso",
        }
    }
    actual_idempotency = hashlib.sha256(
        json.dumps(
            _class_analysis_json_safe(idempotency_payload),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    record_payload = {
        key: value
        for key, value in event.items()
        if key != "record_sha256"
    }
    actual_record = hashlib.sha256(
        json.dumps(
            _class_analysis_json_safe(record_payload),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return (
        actual_idempotency == expected_idempotency
        and actual_record == expected_record
    )


def _class_analysis_vignette_training_batch_hash_valid(
    record: Mapping[str, Any],
) -> bool:
    events = record.get("events")
    try:
        expected_count = int(record.get("expected_count") or -1)
    except (TypeError, ValueError):
        return False
    if (
        record.get("schema") != "vignette-training-action-batch-v1"
        or not isinstance(events, list)
        or expected_count != len(events)
        or not events
        or any(
            not isinstance(event, dict)
            or not _class_analysis_vignette_training_event_hash_valid(
                event
            )
            for event in events
        )
    ):
        return False
    expected_idempotency = str(
        record.get("idempotency_payload_sha256") or ""
    ).strip()
    expected_record = str(record.get("record_sha256") or "").strip()
    if (
        not re.fullmatch(r"[0-9a-f]{64}", expected_idempotency)
        or not re.fullmatch(r"[0-9a-f]{64}", expected_record)
    ):
        return False
    semantic_children = sorted(
        [
            {
                "action_id": str(event.get("action_id") or ""),
                "payload_sha256": str(
                    event.get("idempotency_payload_sha256") or ""
                ),
            }
            for event in events
        ],
        key=lambda item: item["action_id"],
    )
    actual_idempotency = hashlib.sha256(
        json.dumps(
            semantic_children,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    record_payload = {
        key: value
        for key, value in record.items()
        if key != "record_sha256"
    }
    actual_record = hashlib.sha256(
        json.dumps(
            _class_analysis_json_safe(record_payload),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return (
        actual_idempotency == expected_idempotency
        and actual_record == expected_record
    )


def _class_analysis_vignette_training_action_by_id(
    action_id: str,
) -> Optional[Dict[str, Any]]:
    safe_action_id = str(action_id or "").strip()
    if not safe_action_id:
        return None
    for event in _class_analysis_iter_vignette_training_actions():
        if str(event.get("action_id") or "") == safe_action_id:
            return event
    return None


def _class_analysis_latest_captured_review_action_id(
    review_object_key: str,
) -> str:
    candidates: List[Tuple[float, str]] = []
    tombstoned: Set[str] = set()
    for event in _class_analysis_iter_vignette_training_actions():
        action_type = str(event.get("action_type") or "")
        if action_type == "undo_review":
            target = str(
                event.get("tombstone_of_action_id") or ""
            )
            if target:
                tombstoned.add(target)
            continue
        if (
            action_type in {"confirm_current", "skip"}
            and str(event.get("review_object_key") or "")
            == str(review_object_key or "")
        ):
            action_id = str(event.get("action_id") or "")
            if action_id:
                candidates.append(
                    (
                        float(event.get("recorded_at") or 0.0),
                        action_id,
                    )
                )
    eligible = [
        candidate
        for candidate in candidates
        if candidate[1] not in tombstoned
    ]
    return (
        max(eligible, key=lambda candidate: candidate)[1]
        if eligible
        else ""
    )


def get_class_analysis_vignette_training_status() -> Dict[str, Any]:
    action_root = _class_analysis_vignette_training_action_root(create=False)
    if action_root is None:
        return {
            "schema": CLASS_ANALYSIS_TRAINING_ACTION_SCHEMA,
            "event_count": 0,
            "action_counts": {},
            "event_bytes": 0,
            "blob_count": 0,
            "blob_bytes": 0,
            "explicit_opt_in_required": True,
        }
    action_counts: Counter = Counter()
    event_count = 0
    valid_hash_count = 0
    for event in _class_analysis_iter_vignette_training_actions():
        event_count += 1
        action_counts[str(event.get("action_type") or "unknown")] += 1
        if _class_analysis_vignette_training_event_hash_valid(event):
            valid_hash_count += 1
    event_bytes = 0
    blob_count = 0
    blob_bytes = 0
    for path in action_root.rglob("*"):
        try:
            if path.is_symlink() or not path.is_file():
                continue
            size = int(path.stat().st_size)
            if path.suffix == ".jsonl":
                event_bytes += size
            elif path.suffix == ".blob":
                blob_count += 1
                blob_bytes += size
        except OSError:
            continue
    return {
        "schema": CLASS_ANALYSIS_TRAINING_ACTION_SCHEMA,
        "event_count": event_count,
        "valid_hash_count": valid_hash_count,
        "action_counts": dict(action_counts),
        "event_bytes": event_bytes,
        "blob_count": blob_count,
        "blob_bytes": blob_bytes,
        "total_bytes": event_bytes + blob_bytes,
        "explicit_opt_in_required": True,
    }


def _class_analysis_vignette_training_blob(
    artifact: Mapping[str, Any],
) -> Optional[Path]:
    relpath = str(artifact.get("blob_relpath") or "").strip()
    digest = str(artifact.get("sha256") or "").strip().lower()
    if not relpath or not re.fullmatch(r"[0-9a-f]{64}", digest):
        return None
    class_root = _class_analysis_storage_root(create=False)
    path = class_root / _class_analysis_safe_relpath(relpath, "")
    safe = _safe_existing_regular_file_within_root_impl(path, class_root)
    if safe is None:
        return None
    try:
        if int(safe.stat().st_size) != int(artifact.get("bytes") or -1):
            return None
        if _class_analysis_file_sha256(safe) != digest:
            return None
    except (OSError, TypeError, ValueError):
        return None
    return safe


@contextmanager
def _class_analysis_annotation_target_transaction_lock(
    annotation_target: Mapping[str, Any],
) -> Iterator[None]:
    """Serialize reassignment verification with its review-ledger write."""

    target = _class_analysis_vignette_training_annotation_target(
        annotation_target
    )
    if target is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="review_reassignment_annotation_target_required",
        )
    if target["source_mode"] == "linked":
        entry = _resolve_dataset_entry(target["source_id"])
        with _dataset_annotation_mutation_lock(entry):
            yield
        return
    if target["source_mode"] == "transient":
        with DATASET_TRANSIENT_LOCK:
            yield
        return
    raise HTTPException(
        status_code=HTTP_400_BAD_REQUEST,
        detail="review_reassignment_annotation_target_invalid",
    )


def _class_analysis_vignette_current_linked_class(
    event: Mapping[str, Any],
    cache: Dict[str, Optional[str]],
    *,
    require_unique: bool = False,
) -> Optional[str]:
    point = event.get("point")
    if not isinstance(point, dict):
        return None
    source = point.get("source")
    image = point.get("image")
    bbox_payload = point.get("bbox")
    if (
        not isinstance(source, dict)
        or str(source.get("mode") or "").strip().lower() != "linked"
        or not isinstance(image, dict)
        or not isinstance(bbox_payload, dict)
    ):
        return None
    source_id = str(source.get("id") or "").strip()
    split = _annotation_normalise_split(image.get("split"))
    rel = _annotation_normalise_image_relpath(
        image.get("relpath")
    )
    target_bbox = [
        float(value)
        for value in list(bbox_payload.get("xyxy") or [])[:4]
    ]
    expected_image_sha256 = str(
        image.get("sha256") or ""
    ).strip().lower()
    if (
        not source_id
        or len(target_bbox) != 4
        or not re.fullmatch(r"[0-9a-f]{64}", expected_image_sha256)
    ):
        return None
    cache_key = (
        f"{source_id}:{split}:{rel.as_posix()}:"
        f"{expected_image_sha256}:"
        f"unique={int(require_unique)}:"
        + ",".join(f"{value:.4f}" for value in target_bbox)
    )
    if cache_key in cache:
        return cache[cache_key]
    resolved_class: Optional[str] = None
    try:
        entry = _resolve_dataset_entry(source_id)
        dataset_root = _dataset_effective_root_from_entry(entry)
        layout = str(entry.get("yolo_layout") or "flat")
        labelmap = [
            str(name or "").strip()
            for name in (
                entry.get("classes")
                or _dataset_labelmap_from_root(dataset_root)
            )
        ]
        image_path = _resolve_annotation_image_path(
            dataset_root,
            layout,
            split,
            rel,
        )
        if (
            _class_analysis_file_sha256_cached(image_path)
            != expected_image_sha256
        ):
            cache[cache_key] = None
            return None
        with Image.open(image_path) as loaded:
            width, height = loaded.size
        resolved_class = _class_analysis_resolve_persisted_review_class(
            event=event,
            label_lines=_annotation_effective_label_lines(
                entry,
                split,
                rel,
            ),
            labelmap=labelmap,
            target_bbox=target_bbox,
            image_width=int(width),
            image_height=int(height),
            require_unique=require_unique,
        )
    except Exception:
        resolved_class = None
    cache[cache_key] = resolved_class
    return resolved_class


def _class_analysis_vignette_current_annotation_target_class(
    event: Mapping[str, Any],
    annotation_target: Mapping[str, Any],
    cache: Dict[str, Optional[str]],
    *,
    require_unique: bool = False,
) -> Optional[str]:
    """Re-read one persisted annotation and match the captured geometry."""

    try:
        target = _class_analysis_vignette_training_annotation_target(
            annotation_target
        )
    except HTTPException:
        return None
    if target is None:
        return None
    derived_linked = (
        _class_analysis_vignette_training_derived_linked_target(event)
    )
    if derived_linked == target:
        # Keep the linked-source path centralized. Tests can also substitute
        # this reader to model a committed linked annotation without creating
        # a complete dataset registry fixture.
        if require_unique:
            return _class_analysis_vignette_current_linked_class(
                event,
                cache,
                require_unique=True,
            )
        return _class_analysis_vignette_current_linked_class(event, cache)

    point = event.get("point")
    if not isinstance(point, Mapping):
        return None
    image = point.get("image")
    bbox_payload = point.get("bbox")
    if not isinstance(image, Mapping) or not isinstance(
        bbox_payload, Mapping
    ):
        return None
    expected_image_sha256 = str(
        image.get("sha256") or ""
    ).strip().lower()
    try:
        target_bbox = [
            float(value)
            for value in list(bbox_payload.get("xyxy") or [])[:4]
        ]
    except (TypeError, ValueError):
        return None
    if (
        len(target_bbox) != 4
        or not re.fullmatch(r"[0-9a-f]{64}", expected_image_sha256)
    ):
        return None
    cache_key = hashlib.sha256(
        json.dumps(
            {
                "annotation_target": target,
                "bbox_xyxy": target_bbox,
                "image_sha256": expected_image_sha256,
                "require_unique": bool(require_unique),
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    if cache_key in cache:
        return cache[cache_key]

    resolved_class: Optional[str] = None
    try:
        split = target["split"]
        rel = _annotation_normalise_image_relpath(
            target["image_relpath"]
        )
        if target["source_mode"] == "linked":
            entry = _resolve_dataset_entry(target["source_id"])
            dataset_root = _dataset_effective_root_from_entry(entry)
            layout = str(entry.get("yolo_layout") or "flat")
            labelmap = [
                str(name or "").strip()
                for name in (
                    entry.get("classes")
                    or _dataset_labelmap_from_root(dataset_root)
                )
            ]
            label_lines = _annotation_effective_label_lines(
                entry,
                split,
                rel,
            )
        else:
            session = _resolve_transient_session(target["source_id"])
            dataset_root = _validate_linked_dataset_path(
                str(session.get("dataset_root") or "")
            )
            layout = str(session.get("yolo_layout") or "flat")
            labelmap = [
                str(name or "").strip()
                for name in (session.get("classes") or [])
            ]
            overlay_labels = (
                session.get("overlay_labels")
                if isinstance(session.get("overlay_labels"), dict)
                else {}
            )
            overlay_key = f"{split}:{rel.as_posix()}"
            if overlay_key in overlay_labels:
                label_lines = [
                    str(line or "").strip()
                    for line in (overlay_labels.get(overlay_key) or [])
                    if str(line or "").strip()
                ]
            else:
                source_path = _annotation_source_label_path(
                    dataset_root,
                    layout,
                    split,
                    rel,
                )
                source_text = _annotation_read_text_within_root(
                    source_path,
                    dataset_root,
                )
                label_lines = (
                    [
                        line.strip()
                        for line in source_text.splitlines()
                        if line.strip()
                    ]
                    if source_text is not None
                    else []
                )
        image_path = _resolve_annotation_image_path(
            dataset_root,
            layout,
            split,
            rel,
        )
        if (
            _class_analysis_file_sha256_cached(image_path)
            != expected_image_sha256
        ):
            cache[cache_key] = None
            return None
        with Image.open(image_path) as loaded:
            width, height = loaded.size
        resolved_class = _class_analysis_resolve_persisted_review_class(
            event=event,
            label_lines=label_lines,
            labelmap=labelmap,
            target_bbox=target_bbox,
            image_width=int(width),
            image_height=int(height),
            require_unique=require_unique,
        )
    except Exception:
        resolved_class = None
    cache[cache_key] = resolved_class
    return resolved_class


def _class_analysis_vignette_transient_target_unavailable(
    annotation_target: Any,
) -> bool:
    try:
        target = _class_analysis_vignette_training_annotation_target(
            annotation_target
        )
    except HTTPException:
        return False
    if target is None or target.get("source_mode") != "transient":
        return False
    try:
        _resolve_transient_session(target["source_id"])
        return False
    except HTTPException as exc:
        return exc.status_code in {
            HTTP_404_NOT_FOUND,
            410,
        }
    except Exception:
        return False


def _class_analysis_vignette_current_reassignment_matches(
    attestation: Mapping[str, Any],
) -> Optional[bool]:
    """Verify the attested post-edit geometry/class against current labels."""

    try:
        target = _class_analysis_vignette_training_annotation_target(
            attestation.get("annotation_target")
        )
        geometry_edit = attestation.get("geometry_edit")
        if target is None or not isinstance(geometry_edit, Mapping):
            return False
        with _class_analysis_annotation_target_transaction_lock(target):
            state = _class_analysis_reassignment_annotation_state(target)
    except HTTPException:
        return None if _class_analysis_vignette_transient_target_unavailable(
            attestation.get("annotation_target")
        ) else False
    except Exception:
        return False
    if state.get("image_sha256") != attestation.get("image_sha256"):
        return False
    labelmap = list(state.get("labelmap") or [])
    committed_class = str(attestation.get("committed_class") or "")
    if labelmap.count(committed_class) != 1:
        return False
    expected_class_id = labelmap.index(committed_class)
    expected_geometry = geometry_edit.get("committed_geometry")
    matches = 0
    for line in state.get("current_lines") or []:
        parsed, class_id = _class_analysis_parse_yolo_geometry_for_identity(
            line,
            image_width=int(state.get("image_width") or 0),
            image_height=int(state.get("image_height") or 0),
        )
        if not isinstance(parsed, Mapping):
            continue
        if (
            _class_analysis_canonical_review_geometry(
                parsed,
                image_width=int(state.get("image_width") or 0),
                image_height=int(state.get("image_height") or 0),
            ) == expected_geometry
            and class_id == expected_class_id
        ):
            matches += 1
    return matches == 1


def _class_analysis_vignette_training_export_rows(
    events: Sequence[Dict[str, Any]],
) -> Dict[str, Any]:
    by_action_id: Dict[str, Dict[str, Any]] = {}
    duplicate_ids: Set[str] = set()
    hash_invalid_ids: Set[str] = set()
    for event in events:
        action_id = str(event.get("action_id") or "")
        if not action_id:
            continue
        if not _class_analysis_vignette_training_event_hash_valid(event):
            hash_invalid_ids.add(action_id)
        previous = by_action_id.get(action_id)
        if previous is not None:
            if previous != event:
                duplicate_ids.add(action_id)
            continue
        by_action_id[action_id] = event
    ordered = sorted(
        by_action_id.values(),
        key=lambda event: (
            float(event.get("recorded_at") or 0.0),
            str(event.get("action_id") or ""),
        ),
    )
    tombstoned = {
        str(event.get("tombstone_of_action_id") or "")
        for event in ordered
        if str(event.get("action_type") or "") == "undo_review"
        and str(event.get("tombstone_of_action_id") or "")
    }
    committed: Set[str] = set()
    committed_attestations: Dict[str, Dict[str, Any]] = {}
    invalid_commit_ids: Set[str] = set()
    invalid_attestation_commit_ids: Set[str] = set()
    current_class_cache: Dict[str, Optional[str]] = {}
    for commit_event in ordered:
        if (
            str(commit_event.get("action_type") or "")
            != "commit_class_change"
        ):
            continue
        commit_id = str(commit_event.get("action_id") or "")
        source_id = str(
            commit_event.get("commits_action_id") or ""
        )
        source_event = by_action_id.get(source_id)
        reference = commit_event.get("validated_commit_reference")
        reference = reference if isinstance(reference, dict) else {}
        attestation = commit_event.get(
            "annotation_commit_attestation"
        )
        valid_reference = (
            commit_id not in hash_invalid_ids
            and commit_id not in duplicate_ids
            and source_id
            and isinstance(source_event, dict)
            and source_id not in hash_invalid_ids
            and source_id not in duplicate_ids
            and str(source_event.get("action_type") or "")
            == "change_class"
            and str(source_event.get("label_commit_status") or "")
            == "pending_desktop_sync"
            and str(reference.get("action_id") or "") == source_id
            and str(reference.get("record_sha256") or "")
            == str(source_event.get("record_sha256") or "")
            and str(reference.get("visual_object_key") or "")
            == str(source_event.get("visual_object_key") or "")
            == str(commit_event.get("visual_object_key") or "")
            and str(reference.get("after_class") or "")
            == str(source_event.get("after_class") or "")
            == str(commit_event.get("after_class") or "")
            and str(source_event.get("before_class") or "")
            == str(commit_event.get("before_class") or "")
            and str(source_event.get("analysis_job_id") or "")
            == str(commit_event.get("analysis_job_id") or "")
        )
        valid_attestation = bool(
            valid_reference
            and _class_analysis_vignette_training_commit_attestation_valid(
                attestation,
                commit_event=commit_event,
                source_event=source_event,
            )
        )
        current_annotation_matches = False
        if valid_attestation:
            if not isinstance(source_event, dict) or not isinstance(
                attestation, Mapping
            ):
                # This should already be excluded by the attestation validator,
                # but keep export fail-closed if that contract ever regresses.
                valid_attestation = False
            else:
                if (
                    str(attestation.get("schema") or "")
                    == CLASS_ANALYSIS_CLASS_REASSIGNMENT_ATTESTATION_SCHEMA
                ):
                    current_reassignment = (
                        _class_analysis_vignette_current_reassignment_matches(
                            attestation
                        )
                    )
                    current_annotation_matches = bool(
                        current_reassignment is True
                        or (
                            current_reassignment is None
                            and _class_analysis_vignette_transient_target_unavailable(
                                attestation.get("annotation_target")
                            )
                        )
                    )
                else:
                    current_class = (
                        _class_analysis_vignette_current_annotation_target_class(
                            source_event,
                            attestation.get("annotation_target") or {},
                            current_class_cache,
                        )
                    )
                    current_annotation_matches = (
                        current_class
                        == str(source_event.get("after_class") or "")
                        or (
                            current_class is None
                            and _class_analysis_vignette_transient_target_unavailable(
                                attestation.get("annotation_target")
                            )
                        )
                    )
        if valid_reference and valid_attestation and current_annotation_matches:
            committed.add(source_id)
            committed_attestations[source_id] = copy.deepcopy(
                dict(attestation)
            )
        elif valid_reference and commit_id:
            invalid_attestation_commit_ids.add(commit_id)
        elif commit_id:
            invalid_commit_ids.add(commit_id)
    latest_label_action: Dict[str, str] = {}
    latest_abstention_action: Dict[str, str] = {}
    latest_geometry_action: Dict[str, str] = {}
    for event in ordered:
        if str(event.get("action_type") or "") not in {
            "confirm_current",
            "change_class",
        }:
            continue
        visual_key = str(event.get("visual_object_key") or "")
        if visual_key:
            latest_label_action[visual_key] = str(
                event.get("action_id") or ""
            )
    for event in ordered:
        if str(event.get("action_type") or "") != "skip":
            continue
        visual_key = str(event.get("visual_object_key") or "")
        if visual_key:
            latest_abstention_action[visual_key] = str(
                event.get("action_id") or ""
            )
    for event in ordered:
        action_type = str(event.get("action_type") or "")
        if action_type == "delete_bbox":
            geometry_key = str(
                event.get("review_object_key") or ""
            ).strip()
        elif action_type in CLASS_ANALYSIS_DUAL_BBOX_REVIEW_DISPOSITIONS:
            geometry_key = str(event.get("pair_review_key") or "").strip()
        else:
            continue
        if geometry_key:
            latest_geometry_action[geometry_key] = str(
                event.get("action_id") or ""
            )
    disposition_keys = [
        (
            str(event.get("pair_review_key") or "")
            if str(event.get("action_type") or "")
            in CLASS_ANALYSIS_DUAL_BBOX_REVIEW_DISPOSITIONS
            else str(event.get("review_object_key") or "")
        )
        for event in ordered
        if str(event.get("action_type") or "")
        in {
            "confirm_current",
            "skip",
            "delete_bbox",
            *CLASS_ANALYSIS_DUAL_BBOX_REVIEW_DISPOSITIONS,
        }
    ]
    current_dispositions = _class_analysis_lookup_review_dispositions(
        disposition_keys
    )
    classification: List[Dict[str, Any]] = []
    preferences: List[Dict[str, Any]] = []
    preference_excluded: List[Dict[str, Any]] = []
    abstentions: List[Dict[str, Any]] = []
    geometry_decisions: List[Dict[str, Any]] = []
    excluded: List[Dict[str, Any]] = []
    selected_blob_artifacts: Dict[str, Dict[str, Any]] = {}
    for event in ordered:
        action_id = str(event.get("action_id") or "")
        action_type = str(event.get("action_type") or "")
        reasons: List[str] = []
        if action_id in hash_invalid_ids:
            reasons.append("event_hash_invalid")
        if action_id in duplicate_ids:
            reasons.append("action_id_conflict")
        if action_id in tombstoned:
            reasons.append("explicitly_undone")
        if action_id in invalid_commit_ids:
            reasons.append("commit_reference_invalid")
        if action_id in invalid_attestation_commit_ids:
            reasons.append("commit_attestation_invalid")
        if action_type in {
            "undo_review",
            "discard",
            "commit_class_change",
        }:
            reasons.append(
                "history_marker"
                if action_type
                in {"undo_review", "commit_class_change"}
                else "navigation_only"
            )
        if action_type == "skip":
            if latest_abstention_action.get(
                str(event.get("visual_object_key") or "")
            ) != action_id:
                reasons.append("superseded_abstention")
            disposition = current_dispositions.get(
                str(event.get("review_object_key") or "")
            )
            if (
                not isinstance(disposition, dict)
                or disposition.get("disposition") != "skip"
            ):
                reasons.append("current_review_state_not_skipped")
            skip_artifacts = [
                artifact
                for artifact in (event.get("artifacts") or [])
                if isinstance(artifact, dict)
                and artifact.get("role") == "object_crop"
                and _class_analysis_vignette_training_blob(artifact)
                is not None
            ]
            if not skip_artifacts:
                reasons.append("object_crop_missing_or_corrupt")
            if reasons:
                excluded.append(
                    {"action_id": action_id, "reasons": reasons}
                )
            else:
                abstentions.append(event)
                for artifact in skip_artifacts:
                    selected_blob_artifacts[
                        str(artifact.get("sha256") or "")
                    ] = artifact
                model_review = event.get("model_review")
                snapshot = (
                    model_review.get("artifact_snapshot")
                    if isinstance(model_review, dict)
                    else None
                )
                if isinstance(snapshot, dict):
                    for artifact in snapshot.get("files") or []:
                        if (
                            isinstance(artifact, dict)
                            and _class_analysis_vignette_training_blob(
                                artifact
                            )
                            is not None
                        ):
                            selected_blob_artifacts[
                                str(artifact.get("sha256") or "")
                            ] = artifact
            continue
        if action_type == "delete_bbox":
            review_key = str(event.get("review_object_key") or "").strip()
            if re.fullmatch(r"cro_[0-9a-f]{64}", review_key) is None:
                reasons.append("review_object_key_missing")
            if latest_geometry_action.get(review_key) != action_id:
                reasons.append("superseded_geometry_decision")
            disposition = current_dispositions.get(review_key)
            if (
                not isinstance(disposition, Mapping)
                or str(disposition.get("disposition") or "")
                != "delete_bbox"
            ):
                reasons.append("current_review_state_changed")
            event_attestation = event.get(
                "single_bbox_deletion_attestation"
            )
            ledger_attestation = (
                disposition.get("single_bbox_deletion_attestation")
                if isinstance(disposition, Mapping)
                else None
            )
            event_point = event.get("point")
            event_identity = (
                event_point.get("identity")
                if isinstance(event_point, Mapping)
                and isinstance(event_point.get("identity"), Mapping)
                else {}
            )
            event_target_invalid = False
            try:
                event_annotation_target = (
                    _class_analysis_vignette_training_annotation_target(
                        event.get("annotation_target")
                    )
                    if event.get("annotation_target") is not None
                    else None
                )
                derived_event_annotation_target = (
                    _class_analysis_vignette_training_derived_annotation_target(
                        event
                    )
                )
            except HTTPException:
                event_target_invalid = True
                event_annotation_target = None
                derived_event_annotation_target = None
            if (
                not isinstance(event_attestation, Mapping)
                or not isinstance(ledger_attestation, Mapping)
                or _class_analysis_json_safe(event_attestation)
                != _class_analysis_json_safe(ledger_attestation)
                or event_attestation.get("schema")
                != CLASS_ANALYSIS_SINGLE_BBOX_DELETION_ATTESTATION_SCHEMA
                or event_attestation.get("committed") is not True
                or str(event.get("label_commit_status") or "")
                != "committed"
                or str(event_attestation.get("analysis_job_id") or "")
                != str(event.get("analysis_job_id") or "")
                or str(event_attestation.get("point_id") or "")
                != str(event_identity.get("id") or "")
                or str(event_attestation.get("review_object_key") or "")
                != review_key
                or str(event_identity.get("review_object_key") or "")
                != review_key
                or event_target_invalid
                or _class_analysis_json_safe(
                    event_attestation.get("annotation_target")
                )
                != _class_analysis_json_safe(event_annotation_target)
                or event_annotation_target
                != derived_event_annotation_target
                or event_attestation.get("verification_method")
                != CLASS_ANALYSIS_SINGLE_BBOX_DELETION_VERIFICATION_METHOD
                or re.fullmatch(
                    r"[0-9a-f]{64}",
                    str(
                        event_attestation.get("deleted_label_line_sha256")
                        or ""
                    ),
                )
                is None
                or not isinstance(
                    event_attestation.get("deleted_label_line_index"), int
                )
                or isinstance(
                    event_attestation.get("deleted_label_line_index"), bool
                )
                or event_attestation.get("deleted_label_line_index") < 0
                or str(event_attestation.get("attestation_sha256") or "")
                != _class_analysis_single_bbox_deletion_attestation_hash(
                    event_attestation
                )
            ):
                reasons.append(
                    "single_bbox_deletion_attestation_invalid"
                )
            valid_event_artifacts = [
                dict(artifact)
                for artifact in (event.get("artifacts") or [])
                if isinstance(artifact, Mapping)
                and _class_analysis_vignette_training_blob(artifact)
                is not None
            ]
            if not any(
                str(artifact.get("role") or "") == "object_crop"
                for artifact in valid_event_artifacts
            ):
                reasons.append("object_crop_missing_or_corrupt")
            if reasons:
                excluded.append({"action_id": action_id, "reasons": reasons})
            else:
                geometry_decisions.append(event)
                for artifact in valid_event_artifacts:
                    selected_blob_artifacts[
                        str(artifact.get("sha256") or "")
                    ] = artifact
            continue
        if action_type in CLASS_ANALYSIS_DUAL_BBOX_REVIEW_DISPOSITIONS:
            pair_key = str(event.get("pair_review_key") or "").strip()
            resolution = event.get("dual_bbox_resolution")
            resolution = (
                resolution if isinstance(resolution, Mapping) else {}
            )
            if re.fullmatch(r"crp_[0-9a-f]{64}", pair_key) is None:
                reasons.append("pair_review_key_missing")
            if latest_geometry_action.get(pair_key) != action_id:
                reasons.append("superseded_geometry_decision")
            disposition = current_dispositions.get(pair_key)
            if (
                not isinstance(disposition, Mapping)
                or str(disposition.get("disposition") or "")
                != action_type
            ):
                reasons.append("current_pair_review_state_changed")
            ledger_resolution = (
                disposition.get("dual_bbox_pair_resolution")
                if isinstance(disposition, Mapping)
                and isinstance(
                    disposition.get("dual_bbox_pair_resolution"),
                    Mapping,
                )
                else {}
            )
            pair_fields = (
                "schema",
                "action",
                "pair_review_key",
                "current_review_object_key",
                "other_review_object_key",
                "point_id",
                "other_point_id",
                "current_class",
                "other_class",
                "current_bbox_xyxy",
                "other_bbox_xyxy",
                "deleted_point_id",
                "annotation_mutation_committed",
                "annotation_commit_attestation",
            )
            if not ledger_resolution or any(
                _class_analysis_json_safe(ledger_resolution.get(key))
                != _class_analysis_json_safe(resolution.get(key))
                for key in pair_fields
            ):
                reasons.append("pair_resolution_mismatch")
            if action_type in {
                "delete_current_box",
                "delete_overlapping_box",
            }:
                attestation = resolution.get(
                    "annotation_commit_attestation"
                )
                attestation = (
                    attestation
                    if isinstance(attestation, Mapping)
                    else {}
                )
                if (
                    resolution.get("annotation_mutation_committed")
                    is not True
                    or attestation.get("schema")
                    != CLASS_ANALYSIS_DUAL_BBOX_ANNOTATION_COMMIT_SCHEMA
                    or attestation.get("committed") is not True
                    or str(attestation.get("action") or "")
                    != action_type
                    or str(attestation.get("pair_review_key") or "")
                    != pair_key
                    or str(attestation.get("point_id") or "")
                    != str(resolution.get("point_id") or "")
                    or str(attestation.get("deleted_point_id") or "")
                    != str(resolution.get("deleted_point_id") or "")
                    or str(attestation.get("attestation_sha256") or "")
                    != _class_analysis_dual_bbox_commit_attestation_hash(
                        attestation
                    )
                ):
                    reasons.append("geometry_commit_attestation_invalid")
            event_artifacts = [
                artifact
                for artifact in (event.get("artifacts") or [])
                if isinstance(artifact, Mapping)
            ]
            valid_event_artifacts = [
                dict(artifact)
                for artifact in event_artifacts
                if _class_analysis_vignette_training_blob(artifact)
                is not None
            ]
            if len(valid_event_artifacts) != len(event_artifacts):
                reasons.append("geometry_artifact_missing_or_corrupt")
            if not any(
                str(artifact.get("role") or "") == "object_crop"
                for artifact in valid_event_artifacts
            ):
                reasons.append("object_crop_missing_or_corrupt")
            if reasons:
                excluded.append(
                    {"action_id": action_id, "reasons": reasons}
                )
            else:
                geometry_decisions.append(event)
                for artifact in valid_event_artifacts:
                    selected_blob_artifacts[
                        str(artifact.get("sha256") or "")
                    ] = artifact
            continue
        if action_type not in {"confirm_current", "change_class"}:
            excluded.append({"action_id": action_id, "reasons": reasons})
            continue
        commit_status = str(
            event.get("label_commit_status") or ""
        )
        if (
            action_type == "confirm_current"
            and commit_status != "committed"
        ) or (
            action_type == "change_class"
            and action_id not in committed
        ):
            reasons.append("annotation_not_committed")
        visual_key = str(event.get("visual_object_key") or "")
        if latest_label_action.get(visual_key) != action_id:
            reasons.append("superseded_label_decision")
        if action_type == "confirm_current":
            disposition = current_dispositions.get(
                str(event.get("review_object_key") or "")
            )
            if (
                not isinstance(disposition, dict)
                or disposition.get("disposition") != "confirm_current"
            ):
                reasons.append("current_review_state_not_confirmed")
        if action_type == "confirm_current":
            point_source = (
                (event.get("point") or {}).get("source")
                if isinstance(event.get("point"), dict)
                else {}
            )
            annotation_target = event.get("annotation_target")
            if isinstance(annotation_target, Mapping):
                current_class = (
                    _class_analysis_vignette_current_annotation_target_class(
                        event,
                        annotation_target,
                        current_class_cache,
                    )
                )
            elif (
                isinstance(point_source, dict)
                and str(point_source.get("mode") or "").strip().lower()
                == "linked"
            ):
                current_class = (
                    _class_analysis_vignette_current_linked_class(
                        event,
                        current_class_cache,
                    )
                )
            else:
                current_class = None
            if current_class is None:
                reasons.append("current_annotation_unverifiable")
            elif current_class != str(
                event.get("after_class") or ""
            ):
                reasons.append("current_annotation_class_changed")
        point_artifacts = [
            artifact
            for artifact in (event.get("artifacts") or [])
            if isinstance(artifact, dict)
            and artifact.get("role") == "object_crop"
        ]
        valid_point_artifact = next(
            (
                artifact
                for artifact in point_artifacts
                if _class_analysis_vignette_training_blob(artifact)
                is not None
            ),
            None,
        )
        if valid_point_artifact is None:
            reasons.append("object_crop_missing_or_corrupt")
        if reasons:
            excluded.append({"action_id": action_id, "reasons": reasons})
            continue
        if not isinstance(valid_point_artifact, dict):
            # The branch above must exclude a missing/corrupt crop. Keep this
            # invariant explicit so ``python -O`` cannot turn a malformed
            # export row into an exception or an unbound training artifact.
            excluded.append(
                {
                    "action_id": action_id,
                    "reasons": ["object_crop_missing_or_corrupt"],
                }
            )
            continue
        selected_blob_artifacts[
            str(valid_point_artifact["sha256"])
        ] = valid_point_artifact
        classification_row = {
            "action_id": action_id,
            "visual_object_key": visual_key,
            "image_sha256": valid_point_artifact["sha256"],
            "image": f"media/{valid_point_artifact['sha256']}.jpg",
            "class_name": str(event.get("after_class") or ""),
            "before_class": str(event.get("before_class") or ""),
            "point": event.get("point"),
            "analysis": event.get("analysis"),
        }
        committed_attestation = committed_attestations.get(action_id)
        if isinstance(committed_attestation, Mapping):
            classification_row["annotation_commit_attestation"] = (
                copy.deepcopy(dict(committed_attestation))
            )
            if isinstance(
                committed_attestation.get("geometry_edit"), Mapping
            ):
                classification_row["geometry_edit"] = copy.deepcopy(
                    dict(committed_attestation["geometry_edit"])
                )
        classification.append(classification_row)
        model_review = event.get("model_review")
        if (
            isinstance(model_review, dict)
            and model_review.get("preference_train_eligible") is True
        ):
            snapshot = model_review.get("artifact_snapshot")
            expected_manifest_hash = str(
                model_review.get("artifact_manifest_sha256") or ""
            )
            actual_manifest_hash = (
                hashlib.sha256(
                    json.dumps(
                        _class_analysis_json_safe(snapshot),
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest()
                if isinstance(snapshot, dict)
                else ""
            )
            review_artifacts = (
                [
                    artifact
                    for artifact in (snapshot.get("files") or [])
                    if isinstance(artifact, dict)
                ]
                if isinstance(snapshot, dict)
                else []
            )
            valid_review_artifacts = [
                artifact
                for artifact in review_artifacts
                if _class_analysis_vignette_training_blob(artifact)
                is not None
            ]
            if (
                not expected_manifest_hash
                or expected_manifest_hash != actual_manifest_hash
                or len(valid_review_artifacts)
                != len(review_artifacts)
            ):
                preference_excluded.append(
                    {
                        "action_id": action_id,
                        "reasons": [
                            "model_artifact_manifest_missing_or_corrupt"
                        ],
                    }
                )
            else:
                for artifact in valid_review_artifacts:
                    selected_blob_artifacts[
                        str(artifact.get("sha256") or "")
                    ] = artifact
                preferences.append(
                    {
                        "action_id": action_id,
                        "human_choice": {
                            "action_type": action_type,
                            "class_name": str(
                                event.get("after_class") or ""
                            ),
                        },
                        "model_review": model_review,
                        "visual_object_key": visual_key,
                    }
                )
    return {
        "events": ordered,
        "classification": classification,
        "preferences": preferences,
        "preference_excluded": preference_excluded,
        "abstentions": abstentions,
        "geometry_decisions": geometry_decisions,
        "excluded": excluded,
        "artifacts": list(selected_blob_artifacts.values()),
    }


def export_class_analysis_vignette_training_actions() -> FileResponse:
    events = list(_class_analysis_iter_vignette_training_actions())
    rows = _class_analysis_vignette_training_export_rows(events)
    class_root = _class_analysis_storage_root(create=True)
    exports_root = _class_analysis_prepare_dir(
        class_root / "exports",
        class_root,
    )
    if exports_root is None:
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="class_analysis_export_unavailable",
        )
    output_path = exports_root / (
        "vignette_training_candidates_"
        + time.strftime("%Y%m%d_%H%M%S", time.gmtime())
        + f"_{uuid.uuid4().hex[:8]}.zip"
    )
    partial_path = output_path.with_suffix(".zip.partial")
    if (
        _class_analysis_prepare_write_path(partial_path, exports_root)
        is None
    ):
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="class_analysis_export_unavailable",
        )
    manifest = {
        "schema": "vignette-training-export-v1",
        "created_at": time.time(),
        "source_schema": CLASS_ANALYSIS_TRAINING_ACTION_SCHEMA,
        "raw_event_count": len(rows["events"]),
        "classification_count": len(rows["classification"]),
        "preference_candidate_count": len(rows["preferences"]),
        "preference_excluded_count": len(
            rows["preference_excluded"]
        ),
        "abstention_count": len(rows["abstentions"]),
        "geometry_decision_count": len(rows["geometry_decisions"]),
        "excluded_count": len(rows["excluded"]),
        "artifact_count": len(rows["artifacts"]),
        "rules": {
            "skip_is_label": False,
            "navigation_is_training_example": False,
            "pending_changes_excluded": True,
            "class_changes_require_current_annotation_attestation": True,
            "expired_transient_uses_durable_attestation": True,
            "undone_or_superseded_excluded": True,
            "exact_model_review_required_for_preferences": True,
            "dual_bbox_geometry_decisions_exported_with_linked_evidence": True,
        },
    }
    data_card = """# Vignette training-candidate export

This local export contains only actions taken while the explicit training
capture checkbox was enabled. Ordinary VLM audits and review dispositions are
not swept into it.

Classification rows require a committed, current human label and an
integrity-checked object crop. Class corrections additionally require a
hashed backend attestation that re-read the exact annotation target, matched
the source-image hash and object geometry, and observed the committed class;
export checks any still-addressable current annotation again. An expired
transient session uses that durable attestation as its portable annotation
snapshot. Skip is exported only as abstention data. Navigation, pending local
edits, undone/superseded decisions, stale live annotations, corrupt blobs, and
heuristic model links are excluded. Preference rows require an explicitly
linked completed model review; no human rationale is invented.

Exact dual-box delete/keep/unresolved choices are exported separately in
``geometry_decisions.jsonl`` only while the matching pair decision is still
current. Deletions require an integrity-checked backend commit receipt. Each
geometry decision includes its object crop and any linked pair-review evidence
in the content-addressed media bundle.

Before training, review dataset licences and provenance. Images may contain
people, licence plates, locations, sensitive filenames, or prompt-injection
text. Content hashes establish integrity, not anonymity.
"""
    try:
        with zipfile.ZipFile(
            partial_path,
            mode="w",
            compression=zipfile.ZIP_DEFLATED,
            compresslevel=6,
        ) as archive:
            archive.writestr(
                "manifest.json",
                json.dumps(manifest, indent=2, sort_keys=True),
            )
            archive.writestr("DATA_CARD.md", data_card)
            for name in (
                "events",
                "classification",
                "preferences",
                "preference_excluded",
                "abstentions",
                "geometry_decisions",
                "excluded",
            ):
                content = "".join(
                    json.dumps(
                        _class_analysis_json_safe(row),
                        ensure_ascii=False,
                        sort_keys=True,
                    )
                    + "\n"
                    for row in rows[name]
                )
                archive.writestr(f"{name}.jsonl", content)
            archive.writestr(
                "sft.jsonl",
                "",
            )
            artifact_index: List[Dict[str, Any]] = []
            for artifact in rows["artifacts"]:
                blob = _class_analysis_vignette_training_blob(artifact)
                if blob is None:
                    continue
                media_type = str(artifact.get("media_type") or "")
                suffix = {
                    "image/jpeg": ".jpg",
                    "image/png": ".png",
                    "image/webp": ".webp",
                    "application/json": ".json",
                    "application/x-ndjson": ".jsonl",
                    "text/plain": ".txt",
                }.get(media_type, ".bin")
                export_path = (
                    "media/"
                    + str(artifact.get("sha256") or "")
                    + suffix
                )
                archive.write(blob, arcname=export_path)
                artifact_index.append(
                    {**dict(artifact), "export_path": export_path}
                )
            archive.writestr(
                "artifact_index.jsonl",
                "".join(
                    json.dumps(
                        _class_analysis_json_safe(row),
                        ensure_ascii=False,
                        sort_keys=True,
                    )
                    + "\n"
                    for row in artifact_index
                ),
            )
        os.replace(partial_path, output_path)
    finally:
        partial_path.unlink(missing_ok=True)
    return FileResponse(
        output_path,
        media_type="application/zip",
        filename=output_path.name,
        background=BackgroundTask(
            lambda path=output_path: path.unlink(missing_ok=True)
        ),
    )


def _class_analysis_review_point_for_mutation(
    job_id: str,
    point_id: str,
) -> Tuple[ClassAnalysisJob, Dict[str, Any]]:
    """Resolve one persisted analysis point without publicizing the full graph."""

    job = _get_class_analysis_job(job_id)
    job_dir = _class_analysis_job_dir(
        job.job_id,
        create=False,
        detail="result_not_found",
    )
    point = _class_analysis_thumbnail_point_metadata(job, job_dir, point_id)
    if point is None:
        raw_result: Optional[Dict[str, Any]] = None
        if isinstance(job.result, dict):
            raw_result = job.result
        else:
            result_path = _safe_job_result_json_path(
                job.result_path,
                CLASS_ANALYSIS_ROOT,
            )
            if result_path is not None:
                raw_result = _class_analysis_load_job_result_payload(
                    job,
                    result_path,
                )
        point = next(
            (
                item
                for item in ((raw_result or {}).get("points") or [])
                if isinstance(item, dict)
                and str(item.get("point_id") or "") == str(point_id or "")
            ),
            None,
        )
        if point is not None and not point.get("review_object_key"):
            candidate = next(
                (
                    item
                    for item in (
                        (raw_result or {}).get("wrong_class_candidates") or []
                    )
                    if isinstance(item, dict)
                    and str(item.get("point_id") or "")
                    == str(point_id or "")
                ),
                None,
            )
            if isinstance(candidate, dict):
                point = {
                    **point,
                    "review_object_key": candidate.get("review_object_key"),
                }
    if point is None:
        raise HTTPException(
            status_code=HTTP_404_NOT_FOUND,
            detail="point_not_found",
        )
    return job, _class_analysis_backfill_review_object_key(job, point)


def _class_analysis_dual_bbox_semantic_label_key(line: Any) -> str:
    clean = " ".join(str(line or "").strip().split())
    parts = clean.split()
    if len(parts) < 5:
        return f"raw:{clean}"
    try:
        class_id = int(float(parts[0]))
        coordinates = [float(value) for value in parts[1:]]
    except (TypeError, ValueError, OverflowError):
        return f"raw:{clean}"
    if not all(math.isfinite(value) for value in coordinates):
        return f"raw:{clean}"
    return json.dumps(
        [class_id, [round(value, 10) for value in coordinates]],
        ensure_ascii=True,
        separators=(",", ":"),
    )


def _class_analysis_dual_bbox_exact_line_indexes(
    label_lines: Sequence[Any],
    *,
    class_name: str,
    bbox_xyxy: Sequence[Any],
    labelmap: Sequence[Any],
    image_width: int,
    image_height: int,
) -> List[int]:
    expected_bbox = [float(value) for value in list(bbox_xyxy or [])[:4]]
    if len(expected_bbox) != 4:
        return []
    tolerance = max(float(image_width), float(image_height), 1.0) * 1e-6
    matches: List[int] = []
    clean_labelmap = [str(value or "").strip() for value in labelmap]
    for index, line in enumerate(label_lines):
        parsed = _class_analysis_parse_yolo_geometry(
            str(line or ""),
            image_width=image_width,
            image_height=image_height,
        )
        if not isinstance(parsed, Mapping) or parsed.get("kind") != "bbox":
            continue
        class_id = int(parsed.get("class_id"))
        if not (0 <= class_id < len(clean_labelmap)):
            continue
        if clean_labelmap[class_id] != str(class_name or "").strip():
            continue
        candidate_bbox = [
            float(value)
            for value in list(parsed.get("bbox_xyxy") or [])[:4]
        ]
        if len(candidate_bbox) == 4 and all(
            math.isclose(left, right, rel_tol=0.0, abs_tol=tolerance)
            for left, right in zip(candidate_bbox, expected_bbox)
        ):
            matches.append(index)
    return matches


def _class_analysis_validate_dual_bbox_post_state(
    *,
    before_lines: Sequence[Any],
    after_lines: Sequence[Any],
    point: Mapping[str, Any],
    conflict: Mapping[str, Any],
    action: str,
    labelmap: Sequence[Any],
    image_width: int,
    image_height: int,
    idempotent_replay: bool = False,
) -> Tuple[str, str]:
    delete_current = action == "delete_current_box"
    deleted_class = str(
        point.get("class_name")
        if delete_current
        else conflict.get("other_class_name") or conflict.get("class_name")
        or ""
    ).strip()
    surviving_class = str(
        conflict.get("other_class_name") or conflict.get("class_name")
        if delete_current
        else point.get("class_name")
        or ""
    ).strip()
    deleted_bbox = (
        conflict.get("target_bbox_xyxy")
        if delete_current
        else conflict.get("other_bbox_xyxy")
    )
    surviving_bbox = (
        conflict.get("other_bbox_xyxy")
        if delete_current
        else conflict.get("target_bbox_xyxy")
    )
    after_deleted = _class_analysis_dual_bbox_exact_line_indexes(
        after_lines,
        class_name=deleted_class,
        bbox_xyxy=deleted_bbox,
        labelmap=labelmap,
        image_width=image_width,
        image_height=image_height,
    )
    after_survivor = _class_analysis_dual_bbox_exact_line_indexes(
        after_lines,
        class_name=surviving_class,
        bbox_xyxy=surviving_bbox,
        labelmap=labelmap,
        image_width=image_width,
        image_height=image_height,
    )
    if after_deleted or len(after_survivor) != 1:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_annotation_post_state_invalid",
        )
    if not idempotent_replay:
        before_deleted = _class_analysis_dual_bbox_exact_line_indexes(
            before_lines,
            class_name=deleted_class,
            bbox_xyxy=deleted_bbox,
            labelmap=labelmap,
            image_width=image_width,
            image_height=image_height,
        )
        before_survivor = _class_analysis_dual_bbox_exact_line_indexes(
            before_lines,
            class_name=surviving_class,
            bbox_xyxy=surviving_bbox,
            labelmap=labelmap,
            image_width=image_width,
            image_height=image_height,
        )
        if len(before_deleted) != 1 or len(before_survivor) != 1:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="dual_bbox_annotation_pair_stale",
            )
        before_counter = Counter(
            _class_analysis_dual_bbox_semantic_label_key(line)
            for line in before_lines
        )
        after_counter = Counter(
            _class_analysis_dual_bbox_semantic_label_key(line)
            for line in after_lines
        )
        removed = before_counter - after_counter
        added = after_counter - before_counter
        deleted_key = _class_analysis_dual_bbox_semantic_label_key(
            before_lines[before_deleted[0]]
        )
        if (
            sum(removed.values()) != 1
            or removed.get(deleted_key) != 1
            or sum(added.values()) != 0
            or len(after_lines) != len(before_lines) - 1
        ):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="dual_bbox_annotation_non_target_changes",
            )
    return deleted_class, surviving_class


def _class_analysis_dual_bbox_commit_attestation_hash(
    attestation: Mapping[str, Any],
) -> str:
    return hashlib.sha256(
        json.dumps(
            {
                key: value
                for key, value in dict(attestation).items()
                if key != "attestation_sha256"
            },
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _class_analysis_dual_bbox_annotation_source_contract(
    *,
    job: ClassAnalysisJob,
    point: Mapping[str, Any],
    conflict: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> Dict[str, str]:
    target = _class_analysis_vignette_training_annotation_target(
        payload.get("annotation_target")
    )
    if target is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="dual_bbox_annotation_target_required",
        )
    summary = job.summary if isinstance(job.summary, Mapping) else {}
    expected_mode = str(
        point.get("source_mode") or summary.get("source_mode") or ""
    ).strip().lower()
    if expected_mode == "dataset":
        expected_mode = "linked"
    elif expected_mode == "open_path":
        expected_mode = "transient"
    expected = {
        "source_mode": expected_mode,
        "source_id": str(
            point.get("source_id") or summary.get("source_id") or ""
        ).strip(),
        "split": _annotation_normalise_split(
            conflict.get("split") or point.get("split")
        ),
        "image_relpath": _annotation_normalise_image_relpath(
            conflict.get("image_relpath") or point.get("image_relpath")
        ).as_posix(),
    }
    if target != expected or expected_mode not in {"linked", "transient"}:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_annotation_source_mismatch",
        )
    return target


def _class_analysis_dual_bbox_rerun_required_detail(
    *,
    job: ClassAnalysisJob,
    point: Mapping[str, Any],
    conflict: Mapping[str, Any],
    reason: str,
) -> Dict[str, Any]:
    """Persist and return the terminal recovery envelope for a stale pair."""

    current_entity = (
        conflict.get("current_entity")
        if isinstance(conflict.get("current_entity"), Mapping)
        else {}
    )
    source_identity = str(
        current_entity.get("annotation_source_identity")
        or point.get("annotation_source_identity")
        or ""
    ).strip()
    source_record_key = str(
        current_entity.get("source_record_key")
        or point.get("source_record_key")
        or ""
    ).strip()
    diagnostic_persisted = False
    if source_identity and source_record_key:
        try:
            _class_analysis_annotation_entity_store().mark_conflict(
                source_identity,
                source_record_key,
                reason,
            )
            diagnostic_persisted = True
        except Exception:
            logger.exception(
                "Could not persist pair-identity conflict for %s/%s",
                job.job_id,
                point.get("point_id"),
            )
    return {
        "code": "annotation_entity_changed_rerun_required",
        "status": "rerun_required",
        "rerun_required": True,
        "job_id": str(job.job_id or ""),
        "point_id": str(point.get("point_id") or ""),
        "reason": str(reason or "annotation_entity_changed"),
        "diagnostic_persisted": diagnostic_persisted,
    }


def _class_analysis_dual_bbox_entity_descriptor(
    value: Any,
) -> Optional[Dict[str, Any]]:
    if not isinstance(value, Mapping):
        return None
    try:
        entity_revision = int(value.get("entity_revision") or 0)
    except (TypeError, ValueError, OverflowError):
        return None
    descriptor = {
        "annotation_entity_id": str(
            value.get("annotation_entity_id") or ""
        ).strip(),
        "entity_revision": entity_revision,
        "record_revision": str(value.get("record_revision") or "").strip(),
        "annotation_source_identity": str(
            value.get("annotation_source_identity") or ""
        ).strip(),
        "source_record_key": str(
            value.get("source_record_key") or ""
        ).strip(),
    }
    if (
        not descriptor["annotation_entity_id"]
        or descriptor["entity_revision"] <= 0
        or re.fullmatch(
            r"alr1_[0-9a-f]{64}",
            descriptor["record_revision"],
        )
        is None
        or re.fullmatch(
            r"asi1_[0-9a-f]{64}",
            descriptor["annotation_source_identity"],
        )
        is None
        or not descriptor["source_record_key"]
    ):
        return None
    return descriptor


def _class_analysis_dual_bbox_entity_preconditions(
    *,
    job: ClassAnalysisJob,
    point: Mapping[str, Any],
    conflict: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> Dict[str, Any]:
    """Bind one destructive pair request to both frozen entities."""

    current = _class_analysis_dual_bbox_entity_descriptor(
        conflict.get("current_entity")
    )
    other = _class_analysis_dual_bbox_entity_descriptor(
        conflict.get("other_entity")
    )

    def _rerun(reason: str) -> None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=_class_analysis_dual_bbox_rerun_required_detail(
                job=job,
                point=point,
                conflict=conflict,
                reason=reason,
            ),
        )

    try:
        point_entity_revision = int(
            point.get("annotation_entity_revision") or 0
        )
    except (TypeError, ValueError, OverflowError):
        point_entity_revision = 0
    if (
        current is None
        or other is None
        or current["annotation_entity_id"] == other["annotation_entity_id"]
        or current["record_revision"] != other["record_revision"]
        or current["annotation_source_identity"]
        != other["annotation_source_identity"]
        or current["source_record_key"] != other["source_record_key"]
        or str(point.get("annotation_entity_id") or "").strip()
        != current["annotation_entity_id"]
        or point_entity_revision != current["entity_revision"]
        or str(
            point.get("annotation_entity_record_revision") or ""
        ).strip()
        != current["record_revision"]
    ):
        _rerun("dual_bbox_frozen_entity_identity_missing_or_stale")

    expected_record_revision = str(
        payload.get("expected_entity_record_revision") or ""
    ).strip()
    requested = payload.get("entity_preconditions")
    requested = requested if isinstance(requested, Mapping) else {}

    def _requested_role(role: str) -> Dict[str, Any]:
        value = requested.get(role)
        value = value if isinstance(value, Mapping) else {}
        try:
            revision = int(value.get("entity_revision") or 0)
        except (TypeError, ValueError, OverflowError):
            revision = 0
        return {
            "annotation_entity_id": str(
                value.get("annotation_entity_id") or ""
            ).strip(),
            "entity_revision": revision,
        }

    canonical = {
        "record_revision": current["record_revision"],
        "annotation_source_identity": current["annotation_source_identity"],
        "source_record_key": current["source_record_key"],
        "current": {
            "annotation_entity_id": current["annotation_entity_id"],
            "entity_revision": current["entity_revision"],
        },
        "other": {
            "annotation_entity_id": other["annotation_entity_id"],
            "entity_revision": other["entity_revision"],
        },
    }
    if (
        expected_record_revision != canonical["record_revision"]
        or _requested_role("current") != canonical["current"]
        or _requested_role("other") != canonical["other"]
    ):
        _rerun("dual_bbox_entity_preconditions_stale")
    return canonical


def _class_analysis_prepare_dual_bbox_entity_commit(
    *,
    job: ClassAnalysisJob,
    point: Mapping[str, Any],
    conflict: Mapping[str, Any],
    action: str,
    preconditions: Mapping[str, Any],
    current_lines: Sequence[Any],
    post_lines: Sequence[Any],
) -> Dict[str, Any]:
    from services.annotation_entities import (
        AnnotationEntityError,
        AnnotationRevisionConflict,
        apply_annotation_entity_actions,
        canonical_label_line,
        live_label_lines,
    )

    source_identity = str(preconditions["annotation_source_identity"])
    source_record_key = str(preconditions["source_record_key"])

    def _rerun(reason: str) -> None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=_class_analysis_dual_bbox_rerun_required_detail(
                job=job,
                point=point,
                conflict=conflict,
                reason=reason,
            ),
        )

    record = _class_analysis_annotation_entity_store().get_record(
        source_identity,
        source_record_key,
    )
    if not isinstance(record, Mapping):
        _rerun("dual_bbox_entity_record_missing")
    if (
        str(record.get("annotation_source_identity") or "")
        != source_identity
        or str(record.get("record_revision") or "")
        != str(preconditions["record_revision"])
    ):
        _rerun("dual_bbox_entity_record_revision_changed")
    entities = {
        str(entity.get("annotation_entity_id") or ""): dict(entity)
        for entity in (record.get("entities") or [])
        if isinstance(entity, Mapping)
    }
    for role in ("current", "other"):
        expected = preconditions[role]
        entity = entities.get(str(expected["annotation_entity_id"]))
        if (
            entity is None
            or bool(entity.get("deleted"))
            or int(entity.get("entity_revision") or 0)
            != int(expected["entity_revision"])
        ):
            _rerun(f"dual_bbox_{role}_entity_changed")
    try:
        canonical_current = [
            canonical_label_line(line)
            for line in current_lines
            if str(line or "").strip()
        ]
        if live_label_lines(record) != canonical_current:
            _rerun("dual_bbox_entity_sidecar_out_of_sync")
        deleted_role = (
            "current" if action == "delete_current_box" else "other"
        )
        deleted = preconditions[deleted_role]
        updated, _results = apply_annotation_entity_actions(
            record,
            [
                {
                    "annotation_entity_id": deleted["annotation_entity_id"],
                    "expected_entity_revision": deleted["entity_revision"],
                    "action": "delete",
                }
            ],
            expected_record_revision=str(preconditions["record_revision"]),
        )
        canonical_post = [
            canonical_label_line(line)
            for line in post_lines
            if str(line or "").strip()
        ]
    except (AnnotationRevisionConflict, AnnotationEntityError) as exc:
        _rerun(f"dual_bbox_entity_compare_and_swap_failed:{exc}")
    if live_label_lines(updated) != canonical_post:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_annotation_entity_post_state_invalid",
        )
    updated_entities = {
        str(entity.get("annotation_entity_id") or ""): dict(entity)
        for entity in (updated.get("entities") or [])
        if isinstance(entity, Mapping)
    }
    entity_results: List[Dict[str, Any]] = []
    for role in ("current", "other"):
        before = preconditions[role]
        entity = updated_entities[str(before["annotation_entity_id"])]
        deleted = bool(entity.get("deleted"))
        entity_results.append(
            {
                "role": role,
                "annotation_entity_id": str(
                    entity["annotation_entity_id"]
                ),
                "entity_revision": int(entity["entity_revision"]),
                "outcome": "deleted" if deleted else "retained",
                "deleted": deleted,
            }
        )
    return {
        "updated_record": updated,
        "record_revision": str(updated["record_revision"]),
        "entity_results": entity_results,
    }


def _class_analysis_dual_bbox_commit_attestation(
    *,
    operation_id: str,
    job: ClassAnalysisJob,
    point: Mapping[str, Any],
    conflict: Mapping[str, Any],
    pair_review_key: str,
    action: str,
    target: Mapping[str, str],
    source_identity: str,
    before_revision: str,
    committed_revision: str,
    image_sha256: str,
    committed_label_count: int,
    entity_preconditions: Mapping[str, Any],
    entity_record_revision: str,
    entity_results: Sequence[Mapping[str, Any]],
    idempotent_replay: bool,
    session_revision: Optional[int] = None,
) -> Dict[str, Any]:
    deleted_point_id = str(
        point.get("point_id")
        if action == "delete_current_box"
        else conflict.get("other_point_id")
        or ""
    ).strip()
    surviving_point_id = str(
        conflict.get("other_point_id")
        if action == "delete_current_box"
        else point.get("point_id")
        or ""
    ).strip()
    attestation: Dict[str, Any] = {
        "schema": CLASS_ANALYSIS_DUAL_BBOX_ANNOTATION_COMMIT_SCHEMA,
        "committed": True,
        "status": "already_committed" if idempotent_replay else "committed",
        "operation_id": operation_id,
        "analysis_job_id": str(job.job_id or ""),
        "point_id": str(point.get("point_id") or ""),
        "pair_review_key": str(pair_review_key or ""),
        "action": action,
        "deleted_point_id": deleted_point_id,
        "surviving_point_id": surviving_point_id,
        "annotation_target": dict(target),
        "source_identity": source_identity,
        "before_revision": before_revision,
        "committed_revision": committed_revision,
        "image_sha256": image_sha256,
        "committed_label_count": int(committed_label_count),
        "entity_preconditions": copy.deepcopy(dict(entity_preconditions)),
        "entity_record_revision": str(entity_record_revision),
        "entity_results": [
            dict(value) for value in entity_results
        ],
        "verification_method": "stable_two_entity_compare_and_swap_v2",
        "committed_at": time.time(),
    }
    if session_revision is not None:
        attestation["session_revision"] = int(session_revision)
    attestation["attestation_sha256"] = (
        _class_analysis_dual_bbox_commit_attestation_hash(attestation)
    )
    return attestation


def _commit_class_analysis_dual_bbox_annotation_transaction_locked(
    job_id: str,
    point_id: str,
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    """Commit exactly one server-bound box deletion on one annotation image."""

    from services.annotation_entities import canonical_label_line

    raw_job_id = str(job_id or "")
    if (
        not raw_job_id
        or _class_analysis_safe_slug(raw_job_id, "") != raw_job_id
    ):
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="job_id_invalid",
        )
    payload = payload if isinstance(payload, dict) else {}
    operation_id = str(payload.get("operation_id") or "").strip()
    if re.fullmatch(r"[A-Za-z0-9_.:-]{8,160}", operation_id) is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="dual_bbox_annotation_operation_id_invalid",
        )
    review_client_action_id = str(
        payload.get("review_client_action_id") or operation_id
    ).strip()
    if CLASS_ANALYSIS_REVIEW_CLIENT_ACTION_PATTERN.fullmatch(
        review_client_action_id
    ) is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="review_disposition_client_action_id_invalid",
        )
    action = str(payload.get("action") or "").strip().lower()
    if action not in {"delete_current_box", "delete_overlapping_box"}:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="dual_bbox_annotation_action_invalid",
        )
    job, point = _class_analysis_review_point_for_mutation(
        raw_job_id,
        point_id,
    )
    conflict, pair_review_key, _current_key, _other_key = (
        _class_analysis_validated_dual_bbox_conflict(job, point, payload)
    )
    existing_pair_review: Optional[Mapping[str, Any]] = None
    stored_replay_attestation: Optional[Dict[str, Any]] = None
    entity_store = _class_analysis_annotation_entity_store()
    existing_pair_review = _class_analysis_lookup_review_dispositions(
        [pair_review_key]
    ).get(pair_review_key)
    if isinstance(existing_pair_review, Mapping):
        existing_resolution = (
            existing_pair_review.get("dual_bbox_pair_resolution")
            if isinstance(
                existing_pair_review.get("dual_bbox_pair_resolution"),
                Mapping,
            )
            else {}
        )
        existing_attestation = (
            existing_resolution.get("annotation_commit_attestation")
            if isinstance(
                existing_resolution.get("annotation_commit_attestation"),
                Mapping,
            )
            else {}
        )
        exact_committed_replay = bool(
            str(existing_pair_review.get("disposition") or "").strip()
            == action
            and str(existing_attestation.get("operation_id") or "").strip()
            == operation_id
        )
        if not exact_committed_replay:
            pending_operation = entity_store.get_operation(operation_id)
            pending_request = (
                pending_operation.get("request") or {}
                if pending_operation is not None
                else {}
            )
            pending_preconditions = (
                pending_request.get("entity_preconditions") or {}
            )
            if (
                pending_operation is not None
                and str(pending_operation.get("state") or "")
                not in {"complete", "conflict", "rejected"}
                and str(pending_request.get("transaction_kind") or "")
                == "dual_bbox_delete_v1"
                and str(pending_request.get("job_id") or "") == raw_job_id
                and str(pending_request.get("point_id") or "")
                == str(point.get("point_id") or point_id or "")
                and str(pending_request.get("pair_review_key") or "")
                == str(pair_review_key)
            ):
                source_identity = str(
                    pending_preconditions.get("annotation_source_identity")
                    or pending_request.get("expected_source_identity")
                    or ""
                )
                image_key = str(
                    pending_preconditions.get("source_record_key") or ""
                )
                if source_identity and image_key:
                    entity_store.mark_operation_conflict(
                        operation_id=operation_id,
                        source_identity=source_identity,
                        image_key=image_key,
                        detail="dual_bbox_review_disposition_exists",
                        response=pending_operation.get("response") or {},
                    )
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail={
                    "code": "dual_bbox_review_disposition_exists",
                    "pair_review_key": pair_review_key,
                },
            )
        stored_replay_attestation = copy.deepcopy(dict(existing_attestation))
    target = _class_analysis_dual_bbox_annotation_source_contract(
        job=job,
        point=point,
        conflict=conflict,
        payload=payload,
    )
    target_source_mode = str(
        target.get("source_mode") or target.get("mode") or target.get("source_kind") or ""
    ).strip()
    target_source_id = str(
        target.get("source_id")
        or target.get("dataset_id")
        or target.get("session_id")
        or ""
    ).strip()
    try:
        binding = entity_store.claim_source_job(
            target_source_mode,
            target_source_id,
            raw_job_id,
            source_descriptor=target,
        )
    except ValueError as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": str(exc),
                "source_mode": target_source_mode,
                "source_id": target_source_id,
            },
        ) from exc
    binding_generation = int(binding.get("binding_generation") or 0)
    expected_revision = str(
        payload.get("expected_annotation_record_revision") or ""
    ).strip()
    expected_source_identity = str(
        payload.get("expected_source_identity") or ""
    ).strip()
    if re.fullmatch(r"alr1_[0-9a-f]{64}", expected_revision) is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="dual_bbox_annotation_revision_required",
        )
    if re.fullmatch(r"asi1_[0-9a-f]{64}", expected_source_identity) is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="dual_bbox_annotation_source_identity_required",
        )
    entity_preconditions = _class_analysis_dual_bbox_entity_preconditions(
        job=job,
        point=point,
        conflict=conflict,
        payload=payload,
    )
    normalised = _normalise_annotation_snapshot_records(
        [payload.get("record")]
    )
    if len(normalised) != 1:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="dual_bbox_annotation_single_record_required",
        )
    split, rel, has_lines, post_lines, has_text, _text = normalised[0]
    if (
        not has_lines
        or has_text
        or split != target["split"]
        or rel.as_posix() != target["image_relpath"]
    ):
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="dual_bbox_annotation_single_record_invalid",
        )
    post_revision = _annotation_image_label_revision(post_lines)
    expected_image_sha256 = str(point.get("image_sha256") or "").strip().lower()
    if re.fullmatch(r"[0-9a-f]{64}", expected_image_sha256) is None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_annotation_image_identity_missing",
        )

    canonical_post_lines = [
        canonical_label_line(line)
        for line in post_lines
        if canonical_label_line(line)
    ]
    canonical_request: Dict[str, Any] = {
        "transaction_kind": "dual_bbox_delete_v1",
        "job_id": raw_job_id,
        "point_id": str(point.get("point_id") or point_id or ""),
        "operation_id": operation_id,
        "review_client_action_id": review_client_action_id,
        "action": action,
        "origin": _class_analysis_review_origin(
            payload.get("origin") or "desktop"
        ),
        "capture_training_data": payload.get("capture_training_data") is True,
        "annotation_source": {
            "kind": target_source_mode,
            "id": target_source_id,
        },
        "binding_generation": binding_generation,
        "annotation_target": dict(target),
        "dual_bbox_conflict": copy.deepcopy(dict(conflict)),
        "pair_review_key": str(pair_review_key),
        "expected_annotation_record_revision": expected_revision,
        "expected_entity_record_revision": str(
            payload.get("expected_entity_record_revision") or ""
        ).strip(),
        "entity_preconditions": copy.deepcopy(dict(entity_preconditions)),
        "expected_source_identity": expected_source_identity,
        "record": {
            "split": split,
            "image_relpath": rel.as_posix(),
            "label_lines": canonical_post_lines,
        },
    }
    for key in ("review_id",):
        if payload.get(key) is not None and str(payload.get(key) or "").strip():
            canonical_request[key] = payload.get(key)
    journal_request = dict(canonical_request)
    request_hash = entity_store.request_hash(canonical_request)
    try:
        entity_store.assert_source_generation(
            target_source_mode,
            target_source_id,
            raw_job_id,
            binding_generation,
        )
    except ValueError as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": str(exc),
                "binding_generation": binding_generation,
            },
        ) from exc
    try:
        operation = entity_store.get_operation(
            operation_id,
            request_hash=request_hash,
        )
    except ValueError as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=str(exc),
        ) from exc
    if operation is not None and str(operation.get("state") or "") == "complete":
        replay = _class_analysis_annotation_operation_public(operation)
        replay["commit_status"] = "already_committed"
        if isinstance(replay.get("review_disposition"), Mapping):
            replay["review_disposition"] = {
                **dict(replay["review_disposition"]),
                "idempotent_replay": True,
            }
        return replay
    if operation is not None and str(operation.get("state") or "") in {
        "conflict",
        "rejected",
    }:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=(operation.get("error") or {}).get("detail")
            or "dual_bbox_annotation_transaction_conflict",
        )

    existing_pair_review = _class_analysis_lookup_review_dispositions(
        [pair_review_key]
    ).get(pair_review_key)
    if isinstance(existing_pair_review, Mapping):
        existing_resolution = (
            existing_pair_review.get("dual_bbox_pair_resolution")
            if isinstance(
                existing_pair_review.get("dual_bbox_pair_resolution"),
                Mapping,
            )
            else {}
        )
        existing_attestation = (
            existing_resolution.get("annotation_commit_attestation")
            if isinstance(
                existing_resolution.get("annotation_commit_attestation"),
                Mapping,
            )
            else {}
        )
        exact_committed_replay = bool(
            str(existing_pair_review.get("disposition") or "").strip()
            == action
            and str(existing_attestation.get("operation_id") or "").strip()
            == operation_id
        )
        if not exact_committed_replay:
            if operation is not None:
                entity_store.mark_operation_conflict(
                    operation_id=operation_id,
                    source_identity=expected_source_identity,
                    image_key=str(entity_preconditions["source_record_key"]),
                    detail="dual_bbox_review_disposition_exists",
                    response=operation.get("response") or {},
                )
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail={
                    "code": "dual_bbox_review_disposition_exists",
                    "pair_review_key": pair_review_key,
                },
            )
        stored_replay_attestation = copy.deepcopy(dict(existing_attestation))

    if stored_replay_attestation is not None and operation is None:
        # A lost-response retry must reuse the exact proof that was committed
        # with the durable pair decision.  Regenerating an attestation here
        # changes committed_at (and therefore its hash), which can make the
        # optional training event disagree with both the review ledger and a
        # later export even though no second annotation mutation occurred.
        replay_contract_matches = bool(
            isinstance(existing_pair_review, Mapping)
            and str(existing_pair_review.get("client_action_id") or "")
            == review_client_action_id
            and str(existing_pair_review.get("analysis_job_id") or "")
            == raw_job_id
            and str(existing_pair_review.get("point_id") or "")
            == str(point.get("point_id") or point_id or "")
            and str(existing_pair_review.get("origin") or "")
            == _class_analysis_review_origin(
                payload.get("origin") or "desktop"
            )
            and bool(existing_pair_review.get("training_capture_requested"))
            == (payload.get("capture_training_data") is True)
            and stored_replay_attestation.get("annotation_target") == target
            and str(stored_replay_attestation.get("source_identity") or "")
            == expected_source_identity
            and str(stored_replay_attestation.get("before_revision") or "")
            == expected_revision
            and str(
                stored_replay_attestation.get("committed_revision") or ""
            )
            == post_revision
            and str(stored_replay_attestation.get("image_sha256") or "")
            == expected_image_sha256
            and stored_replay_attestation.get("entity_preconditions")
            == entity_preconditions
            and isinstance(
                stored_replay_attestation.get("committed_label_count"), int
            )
            and not isinstance(
                stored_replay_attestation.get("committed_label_count"), bool
            )
            and stored_replay_attestation.get("committed_label_count")
            == len(post_lines)
        )
        if not replay_contract_matches:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="dual_bbox_annotation_operation_replay_conflict",
            )
        attestation = (
            _class_analysis_validate_dual_bbox_annotation_commit_attestation(
                job=job,
                point=point,
                conflict=conflict,
                pair_review_key=pair_review_key,
                action=action,
                value=stored_replay_attestation,
            )
        )
        review_receipt = _record_class_analysis_review_disposition_locked(
            raw_job_id,
            str(point.get("point_id") or point_id or ""),
            {
                "disposition": action,
                "origin": str(payload.get("origin") or "desktop"),
                "client_action_id": review_client_action_id,
                "capture_training_data": (
                    payload.get("capture_training_data") is True
                ),
                "label_commit_status": "committed",
                "annotation_target": dict(target),
                "dual_bbox_conflict": dict(conflict),
                "annotation_commit_attestation": attestation,
                **(
                    {"review_id": str(payload.get("review_id") or "").strip()}
                    if str(payload.get("review_id") or "").strip()
                    else {}
                ),
            },
        )
        stored_session_revision = attestation.get("session_revision")
        return {
            "status": "already_committed",
            "committed": True,
            "annotation_commit_attestation": attestation,
            "review_disposition": review_receipt,
            "annotation_record_revision": post_revision,
            "annotation_source_identity": expected_source_identity,
            "annotation_entity_record_revision": str(
                attestation.get("entity_record_revision") or ""
            ),
            "annotation_entity_results": copy.deepcopy(
                list(attestation.get("entity_results") or [])
            ),
            **(
                {"session_revision": int(stored_session_revision)}
                if stored_session_revision is not None
                else {}
            ),
        }

    prepared_entity_commit: Optional[Dict[str, Any]] = None

    def _validate_state(
        current_lines: Sequence[Any],
        *,
        labelmap: Sequence[Any],
        image_path: Path,
        source_identity: str,
    ) -> bool:
        nonlocal operation, prepared_entity_commit
        try:
            entity_store.assert_source_generation(
                target_source_mode,
                target_source_id,
                raw_job_id,
                binding_generation,
            )
        except ValueError as exc:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail={
                    "code": str(exc),
                    "binding_generation": binding_generation,
                },
            ) from exc
        if source_identity != expected_source_identity:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="dual_bbox_annotation_source_identity_stale",
            )
        if _class_analysis_file_sha256_cached(image_path) != expected_image_sha256:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="dual_bbox_annotation_image_identity_stale",
            )
        canonical_current_lines = [
            canonical_label_line(line)
            for line in current_lines
            if canonical_label_line(line)
        ]
        current_revision = _annotation_image_label_revision(
            canonical_current_lines
        )
        idempotent_replay = current_revision == post_revision
        if operation is None and idempotent_replay:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail=_class_analysis_dual_bbox_rerun_required_detail(
                    job=job,
                    point=point,
                    conflict=conflict,
                    reason="dual_bbox_already_absent_without_exact_receipt",
                ),
            )
        if operation is None and current_revision != expected_revision:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="dual_bbox_annotation_revision_stale",
            )
        with Image.open(image_path) as loaded:
            width, height = loaded.size
        before_lines = canonical_current_lines
        stored_plan: Dict[str, Any] = {}
        if operation is not None:
            stored_plan = dict(
                (operation.get("response") or {}).get("plan") or {}
            )
            planned_before = list(
                stored_plan.get("before_label_lines") or []
            )
            planned_after = list(
                stored_plan.get("after_label_lines") or []
            )
            if (
                not planned_before
                or planned_after != canonical_post_lines
                or tuple(canonical_current_lines) not in {
                    tuple(planned_before),
                    tuple(planned_after),
                }
            ):
                detail = _class_analysis_dual_bbox_rerun_required_detail(
                    job=job,
                    point=point,
                    conflict=conflict,
                    reason="dual_bbox_annotation_journal_state_conflict",
                )
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=detail,
                )
            if (
                str(operation.get("state") or "prepared") != "prepared"
                and canonical_current_lines != planned_after
            ):
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=_class_analysis_dual_bbox_rerun_required_detail(
                        job=job,
                        point=point,
                        conflict=conflict,
                        reason="dual_bbox_committed_label_state_missing",
                    ),
                )
            before_lines = planned_before
        _class_analysis_validate_dual_bbox_post_state(
            before_lines=before_lines,
            after_lines=canonical_post_lines,
            point=point,
            conflict=conflict,
            action=action,
            labelmap=labelmap,
            image_width=int(width),
            image_height=int(height),
            idempotent_replay=idempotent_replay,
        )
        planned_entity_commit = stored_plan.get("prepared_entity_commit")
        operation_state = str(
            operation.get("state") if operation is not None else "prepared"
        )
        if operation is None or operation_state in {
            "prepared",
            "annotation_committed",
        }:
            current_entity_commit = (
                _class_analysis_prepare_dual_bbox_entity_commit(
                    job=job,
                    point=point,
                    conflict=conflict,
                    action=action,
                    preconditions=entity_preconditions,
                    current_lines=before_lines,
                    post_lines=canonical_post_lines,
                )
            )
            if (
                isinstance(planned_entity_commit, Mapping)
                and dict(planned_entity_commit) != current_entity_commit
            ):
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=_class_analysis_dual_bbox_rerun_required_detail(
                        job=job,
                        point=point,
                        conflict=conflict,
                        reason="dual_bbox_entity_plan_changed",
                    ),
                )
            prepared_entity_commit = current_entity_commit
        elif isinstance(planned_entity_commit, Mapping):
            prepared_entity_commit = copy.deepcopy(
                dict(planned_entity_commit)
            )
        else:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail=_class_analysis_dual_bbox_rerun_required_detail(
                    job=job,
                    point=point,
                    conflict=conflict,
                    reason="dual_bbox_entity_plan_missing",
                ),
            )
        if operation is None:
            deleted_point_id = str(
                point.get("point_id")
                if action == "delete_current_box"
                else conflict.get("other_point_id")
                or ""
            ).strip()
            resolved_point_ids = list(dict.fromkeys(filter(None, (
                str(point.get("point_id") or point_id or "").strip(),
                str(conflict.get("other_point_id") or "").strip(),
            ))))
            initial_response = {
                "transaction_kind": "dual_bbox_delete_v1",
                "job_id": raw_job_id,
                "point_id": str(point.get("point_id") or point_id or ""),
                "resolved_point_ids": resolved_point_ids,
                "deleted_point_id": deleted_point_id,
                "plan": {
                    "before_label_lines": before_lines,
                    "after_label_lines": canonical_post_lines,
                    "prepared_entity_commit": copy.deepcopy(
                        dict(prepared_entity_commit)
                    ),
                    "annotation_target": dict(target),
                    "source_identity": expected_source_identity,
                    "image_sha256": expected_image_sha256,
                    "image_key": str(
                        entity_preconditions["source_record_key"]
                    ),
                },
            }
            operation = entity_store.begin_operation(
                operation_id=operation_id,
                request_hash=request_hash,
                request=journal_request,
                job_id=raw_job_id,
                source_identity=expected_source_identity,
                source_mode=target_source_mode,
                source_id=target_source_id,
                binding_generation=binding_generation,
                transaction_kind="dual_bbox_delete_v1",
                response=initial_response,
            )
            entity_store.bind_job_sources(
                raw_job_id,
                [expected_source_identity],
            )
        return idempotent_replay

    source_mode = target["source_mode"]
    source_id = target["source_id"]
    idempotent_replay = False
    session_revision: Optional[int] = None
    if source_mode == "linked":
        entry = _resolve_dataset_entry(source_id)
        with _dataset_annotation_mutation_lock(entry):
            _meta_path, meta = _annotation_load_or_create_meta(entry)
            _require_annotation_lock_owner(meta, payload)
            dataset_root = _dataset_effective_root_from_entry(entry)
            layout = str(entry.get("yolo_layout") or "flat")
            image_path = _resolve_annotation_image_path(
                dataset_root,
                layout,
                split,
                rel,
            )
            source_identity = _annotation_image_source_identity(
                source_mode=source_mode,
                source_id=source_id,
                split=split,
                image_relpath=rel,
                image_path=image_path,
                yolo_layout=layout,
            )
            current_lines = _annotation_effective_label_lines(entry, split, rel)
            labelmap = list(entry.get("classes") or _dataset_labelmap_from_root(dataset_root))
            idempotent_replay = _validate_state(
                current_lines,
                labelmap=labelmap,
                image_path=image_path,
                source_identity=source_identity,
            )
            operation_state = str(operation.get("state") or "prepared")
            if operation_state == "prepared" and not idempotent_replay:
                saved_snapshot = save_dataset_annotation_snapshot(
                    source_id,
                    {
                        "session_id": payload.get("session_id"),
                        "records": [
                            {
                                "split": split,
                                "image_relpath": rel.as_posix(),
                                "label_lines": list(post_lines),
                            }
                        ],
                    },
                )
                if saved_snapshot.get("session_revision") is not None:
                    session_revision = int(
                        saved_snapshot["session_revision"]
                    )
            elif meta.get("annotation_revision") is not None:
                session_revision = int(meta.get("annotation_revision") or 0)
            committed_lines = _annotation_effective_label_lines(entry, split, rel)
            if _annotation_image_label_revision(committed_lines) != post_revision:
                raise HTTPException(
                    status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                    detail="dual_bbox_annotation_commit_unverified",
                )
    else:
        session = _resolve_transient_session(source_id)
        dataset_root = _validate_linked_dataset_path(
            str(session.get("dataset_root") or "")
        )
        layout = str(session.get("yolo_layout") or "flat")
        image_path = _resolve_annotation_image_path(
            dataset_root,
            layout,
            split,
            rel,
        )
        source_identity = _annotation_image_source_identity(
            source_mode=source_mode,
            source_id=source_id,
            split=split,
            image_relpath=rel,
            image_path=image_path,
            yolo_layout=layout,
        )
        labelmap = list(session.get("classes") or [])
        source_label_path = _annotation_source_label_path(
            dataset_root,
            layout,
            split,
            rel,
        )
        source_label_text = _annotation_read_text_within_root(
            source_label_path,
            dataset_root,
        )
        source_lines = (
            [line.strip() for line in source_label_text.splitlines() if line.strip()]
            if source_label_text is not None
            else []
        )

        def _apply_transient_commit(current: Dict[str, Any]) -> Dict[str, Any]:
            nonlocal idempotent_replay
            _require_annotation_lock_owner(current, payload)
            overlay = (
                dict(current.get("overlay_labels"))
                if isinstance(current.get("overlay_labels"), dict)
                else {}
            )
            key = f"{split}:{rel.as_posix()}"
            current_lines = list(overlay.get(key) if key in overlay else source_lines)
            idempotent_replay = _validate_state(
                current_lines,
                labelmap=labelmap,
                image_path=image_path,
                source_identity=source_identity,
            )
            if (
                str(operation.get("state") or "prepared") == "prepared"
                and not idempotent_replay
            ):
                overlay[key] = list(post_lines)
                current["overlay_labels"] = overlay
                progress = current.get("annotation_progress")
                if isinstance(progress, dict):
                    try:
                        total = int(progress.get("images_total"))
                        labeled = int(progress.get("images_with_bbox_or_seg"))
                    except Exception:
                        total = -1
                        labeled = -1
                    if total >= 0 and 0 <= labeled <= total:
                        labeled += int(bool(post_lines)) - int(bool(current_lines))
                        progress = dict(progress)
                        progress["images_with_bbox_or_seg"] = max(
                            0,
                            min(total, labeled),
                        )
                        progress["percent_labeled"] = (
                            100.0 * progress["images_with_bbox_or_seg"] / total
                            if total > 0
                            else 0.0
                        )
                        current["annotation_progress"] = progress
            return {"idempotent_replay": idempotent_replay}

        committed_session, _outcome, _committed = _mutate_transient_session(
            source_id,
            _apply_transient_commit,
        )
        session_revision = int(committed_session.get("_state_revision") or 0)
        overlay = (
            committed_session.get("overlay_labels")
            if isinstance(committed_session.get("overlay_labels"), dict)
            else {}
        )
        committed_lines = list(
            overlay.get(f"{split}:{rel.as_posix()}")
            if f"{split}:{rel.as_posix()}" in overlay
            else source_lines
        )
        if _annotation_image_label_revision(committed_lines) != post_revision:
            raise HTTPException(
                status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                detail="dual_bbox_annotation_commit_unverified",
            )

    if operation is None or not isinstance(prepared_entity_commit, Mapping):
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR,
            detail="dual_bbox_annotation_transaction_not_prepared",
        )
    response = dict(operation.get("response") or {})
    annotation_snapshot: Dict[str, Any] = {
        "status": "saved",
        "records": [
            {
                "split": split,
                "image_relpath": rel.as_posix(),
                "annotation_source_identity": expected_source_identity,
                "annotation_record_revision": post_revision,
            }
        ],
    }
    if session_revision is not None:
        annotation_snapshot["session_revision"] = int(session_revision)
    response["annotation_snapshot"] = annotation_snapshot
    state = str(operation.get("state") or "prepared")
    if state == "prepared":
        operation = entity_store.advance_operation(
            operation_id,
            "annotation_committed",
            response=response,
        )
        state = "annotation_committed"

    if state == "annotation_committed":
        try:
            operation = entity_store.put_record_and_advance_operation(
                operation_id=operation_id,
                source_identity=str(
                    entity_preconditions["annotation_source_identity"]
                ),
                image_key=str(entity_preconditions["source_record_key"]),
                record=dict(prepared_entity_commit["updated_record"]),
                state="entity_committed",
                response=response,
            )
        except Exception as exc:
            raise HTTPException(
                status_code=HTTP_503_SERVICE_UNAVAILABLE,
                detail={
                    "code": "annotation_transaction_recovery_required",
                    "status": "recovery_required",
                    "operation_id": operation_id,
                    "reason": f"dual_bbox_entity_commit_pending:{exc}",
                },
            ) from exc
        state = "entity_committed"

    persisted_entity_record = entity_store.get_record(
        str(entity_preconditions["annotation_source_identity"]),
        str(entity_preconditions["source_record_key"]),
    )
    if (
        not isinstance(persisted_entity_record, Mapping)
        or str(persisted_entity_record.get("record_revision") or "")
        != str(prepared_entity_commit["record_revision"])
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=_class_analysis_dual_bbox_rerun_required_detail(
                job=job,
                point=point,
                conflict=conflict,
                reason="dual_bbox_entity_commit_unverified",
            ),
        )

    if state in {"entity_committed", "recovery_required"}:
        attestation_value = response.get("annotation_commit_attestation")
        if isinstance(attestation_value, Mapping):
            attestation = (
                _class_analysis_validate_dual_bbox_annotation_commit_attestation(
                    job=job,
                    point=point,
                    conflict=conflict,
                    pair_review_key=pair_review_key,
                    action=action,
                    value=attestation_value,
                )
            )
        else:
            attestation = _class_analysis_dual_bbox_commit_attestation(
                operation_id=operation_id,
                job=job,
                point=point,
                conflict=conflict,
                pair_review_key=pair_review_key,
                action=action,
                target=target,
                source_identity=expected_source_identity,
                before_revision=expected_revision,
                committed_revision=post_revision,
                image_sha256=expected_image_sha256,
                committed_label_count=len(canonical_post_lines),
                entity_preconditions=entity_preconditions,
                entity_record_revision=str(
                    prepared_entity_commit["record_revision"]
                ),
                entity_results=prepared_entity_commit["entity_results"],
                idempotent_replay=idempotent_replay,
                session_revision=session_revision,
            )
            response["annotation_commit_attestation"] = attestation
            response["committed"] = True
            response["commit_status"] = attestation["status"]
            operation = entity_store.advance_operation(
                operation_id,
                state,
                response=response,
            )
        live_entities = [
            dict(entity)
            for entity in persisted_entity_record.get("entities", [])
            if isinstance(entity, Mapping) and not bool(entity.get("deleted"))
        ]
        deleted_entity = next(
            (
                dict(result)
                for result in prepared_entity_commit["entity_results"]
                if bool(result.get("deleted"))
            ),
            {},
        )
        response.update(
            {
                "committed": True,
                "annotation_commit_attestation": attestation,
                "annotation_record_revision": post_revision,
                "annotation_source_identity": expected_source_identity,
                "annotation_entity_record_revision": str(
                    prepared_entity_commit["record_revision"]
                ),
                "annotation_entity_results": copy.deepcopy(
                    list(prepared_entity_commit["entity_results"])
                ),
                "records": [
                    {
                        "annotation_source_identity": expected_source_identity,
                        "image_key": str(entity_preconditions["source_record_key"]),
                        "record_revision": str(prepared_entity_commit["record_revision"]),
                        "annotation_record_revision": post_revision,
                        "label_lines": canonical_post_lines,
                        "annotation_entities": live_entities,
                    }
                ],
                "actions": [
                    {
                        "point_id": str(response.get("deleted_point_id") or ""),
                        "action": "delete",
                        "annotation_entity_id": str(
                            deleted_entity.get("annotation_entity_id") or ""
                        ),
                    }
                ],
                **(
                    {"session_revision": int(session_revision)}
                    if session_revision is not None
                    else {}
                ),
            }
        )
        operation = entity_store.advance_operation(
            operation_id,
            state,
            response=response,
        )
        review_receipt: Optional[Dict[str, Any]] = None
        review_failures: List[Dict[str, Any]] = []
        try:
            review_receipt = _record_class_analysis_review_disposition_locked(
                raw_job_id,
                str(point.get("point_id") or point_id or ""),
                {
                    "disposition": action,
                    "origin": str(payload.get("origin") or "desktop"),
                    "client_action_id": review_client_action_id,
                    "capture_training_data": (
                        payload.get("capture_training_data") is True
                    ),
                    "label_commit_status": "committed",
                    "annotation_target": dict(target),
                    "dual_bbox_conflict": dict(conflict),
                    "annotation_commit_attestation": attestation,
                    **(
                        {
                            "review_id": str(
                                payload.get("review_id") or ""
                            ).strip()
                        }
                        if str(payload.get("review_id") or "").strip()
                        else {}
                    ),
                },
            )
        except HTTPException as exc:
            if int(exc.status_code) in {408, 425, 429} or int(
                exc.status_code
            ) >= HTTP_500_INTERNAL_SERVER_ERROR:
                operation = entity_store.advance_operation(
                    operation_id,
                    "recovery_required",
                    response=response,
                    error={"detail": "dual_bbox_review_commit_pending"},
                )
                raise HTTPException(
                    status_code=HTTP_503_SERVICE_UNAVAILABLE,
                    detail={
                        "code": "annotation_transaction_recovery_required",
                        "status": "recovery_required",
                        "operation_id": operation_id,
                        "mutation_committed": True,
                        "reason": f"dual_bbox_review_commit_pending:{exc.detail}",
                        "operation": _class_analysis_annotation_operation_public(operation),
                    },
                ) from exc
            review_failures.append(
                {
                    "point_id": str(point.get("point_id") or point_id or ""),
                    "status_code": int(exc.status_code),
                    "reason": str(exc.detail),
                }
            )
        except Exception as exc:
            operation = entity_store.advance_operation(
                operation_id,
                "recovery_required",
                response=response,
                error={"detail": "dual_bbox_review_commit_pending"},
            )
            raise HTTPException(
                status_code=HTTP_503_SERVICE_UNAVAILABLE,
                detail={
                    "code": "annotation_transaction_recovery_required",
                    "status": "recovery_required",
                    "operation_id": operation_id,
                    "mutation_committed": True,
                    "reason": f"dual_bbox_review_commit_pending:{exc}",
                    "operation": _class_analysis_annotation_operation_public(operation),
                },
            ) from exc
        live_entities = [
            dict(entity)
            for entity in persisted_entity_record.get("entities", [])
            if isinstance(entity, Mapping) and not bool(entity.get("deleted"))
        ]
        deleted_entity = next(
            (
                dict(result)
                for result in prepared_entity_commit["entity_results"]
                if bool(result.get("deleted"))
            ),
            {},
        )
        response.update(
            {
                "committed": True,
                "annotation_commit_attestation": attestation,
                "review_receipts": (
                    [review_receipt] if review_receipt is not None else []
                ),
                "review_failures": review_failures,
                "annotation_record_revision": post_revision,
                "annotation_source_identity": expected_source_identity,
                "annotation_entity_record_revision": str(
                    prepared_entity_commit["record_revision"]
                ),
                "annotation_entity_results": copy.deepcopy(
                    list(prepared_entity_commit["entity_results"])
                ),
                "records": [
                    {
                        "annotation_source_identity": expected_source_identity,
                        "image_key": str(
                            entity_preconditions["source_record_key"]
                        ),
                        "record_revision": str(
                            prepared_entity_commit["record_revision"]
                        ),
                        "annotation_record_revision": post_revision,
                        "label_lines": canonical_post_lines,
                        "annotation_entities": live_entities,
                    }
                ],
                "actions": [
                    {
                        "point_id": str(
                            response.get("deleted_point_id") or ""
                        ),
                        "action": "delete",
                        "annotation_entity_id": str(
                            deleted_entity.get("annotation_entity_id") or ""
                        ),
                    }
                ],
                **(
                    {"session_revision": int(session_revision)}
                    if session_revision is not None
                    else {}
                ),
            }
        )
        if review_receipt is not None:
            response["review_disposition"] = review_receipt
        operation = entity_store.advance_operation(
            operation_id,
            "review_committed",
            response=response,
        )
        state = "review_committed"

    if state == "review_committed":
        operation = entity_store.advance_operation(
            operation_id,
            "complete",
            response=response,
        )
    return _class_analysis_annotation_operation_public(operation)


def _class_analysis_validate_dual_bbox_annotation_commit_attestation(
    *,
    job: ClassAnalysisJob,
    point: Mapping[str, Any],
    conflict: Mapping[str, Any],
    pair_review_key: str,
    action: str,
    value: Any,
) -> Dict[str, Any]:
    """Re-read the one committed image before accepting a deletion disposition."""

    if not isinstance(value, Mapping):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_deletion_attestation_required",
        )
    attestation = copy.deepcopy(dict(value))
    expected_deleted_point_id = str(
        point.get("point_id")
        if action == "delete_current_box"
        else conflict.get("other_point_id")
        or ""
    ).strip()
    expected_surviving_point_id = str(
        conflict.get("other_point_id")
        if action == "delete_current_box"
        else point.get("point_id")
        or ""
    ).strip()
    frozen_current = _class_analysis_dual_bbox_entity_descriptor(
        conflict.get("current_entity")
    )
    frozen_other = _class_analysis_dual_bbox_entity_descriptor(
        conflict.get("other_entity")
    )
    expected_entity_preconditions = (
        {
            "record_revision": frozen_current["record_revision"],
            "annotation_source_identity": (
                frozen_current["annotation_source_identity"]
            ),
            "source_record_key": frozen_current["source_record_key"],
            "current": {
                "annotation_entity_id": (
                    frozen_current["annotation_entity_id"]
                ),
                "entity_revision": frozen_current["entity_revision"],
            },
            "other": {
                "annotation_entity_id": frozen_other["annotation_entity_id"],
                "entity_revision": frozen_other["entity_revision"],
            },
        }
        if frozen_current is not None
        and frozen_other is not None
        and frozen_current["record_revision"]
        == frozen_other["record_revision"]
        and frozen_current["annotation_source_identity"]
        == frozen_other["annotation_source_identity"]
        and frozen_current["source_record_key"]
        == frozen_other["source_record_key"]
        else None
    )
    entity_results = (
        attestation.get("entity_results")
        if isinstance(attestation.get("entity_results"), list)
        else []
    )
    entity_results_by_role = {
        str(result.get("role") or ""): result
        for result in entity_results
        if isinstance(result, Mapping)
    }
    expected_deleted_role = (
        "current" if action == "delete_current_box" else "other"
    )
    expected_retained_role = (
        "other" if expected_deleted_role == "current" else "current"
    )

    def _entity_result_revision(role: str) -> int:
        try:
            return int(
                entity_results_by_role.get(role, {}).get(
                    "entity_revision"
                )
                or 0
            )
        except (TypeError, ValueError, OverflowError):
            return 0

    entity_result_contract_valid = bool(
        expected_entity_preconditions is not None
        and set(entity_results_by_role) == {"current", "other"}
        and str(
            entity_results_by_role["current"].get(
                "annotation_entity_id"
            )
            or ""
        )
        == expected_entity_preconditions["current"]["annotation_entity_id"]
        and str(
            entity_results_by_role["other"].get(
                "annotation_entity_id"
            )
            or ""
        )
        == expected_entity_preconditions["other"]["annotation_entity_id"]
        and entity_results_by_role[expected_deleted_role].get("deleted")
        is True
        and str(
            entity_results_by_role[expected_deleted_role].get("outcome")
            or ""
        )
        == "deleted"
        and _entity_result_revision(expected_deleted_role)
        == int(
            expected_entity_preconditions[expected_deleted_role][
                "entity_revision"
            ]
        )
        + 1
        and entity_results_by_role[expected_retained_role].get("deleted")
        is False
        and str(
            entity_results_by_role[expected_retained_role].get("outcome")
            or ""
        )
        == "retained"
        and _entity_result_revision(expected_retained_role)
        == int(
            expected_entity_preconditions[expected_retained_role][
                "entity_revision"
            ]
        )
    )
    if (
        attestation.get("schema")
        != CLASS_ANALYSIS_DUAL_BBOX_ANNOTATION_COMMIT_SCHEMA
        or attestation.get("committed") is not True
        or str(attestation.get("analysis_job_id") or "")
        != str(job.job_id or "")
        or str(attestation.get("point_id") or "")
        != str(point.get("point_id") or "")
        or str(attestation.get("pair_review_key") or "")
        != str(pair_review_key or "")
        or str(attestation.get("action") or "") != action
        or str(attestation.get("deleted_point_id") or "")
        != expected_deleted_point_id
        or str(attestation.get("surviving_point_id") or "")
        != expected_surviving_point_id
        or str(attestation.get("attestation_sha256") or "")
        != _class_analysis_dual_bbox_commit_attestation_hash(attestation)
        or str(attestation.get("verification_method") or "")
        != "stable_two_entity_compare_and_swap_v2"
        or not isinstance(attestation.get("entity_preconditions"), Mapping)
        or attestation.get("entity_preconditions")
        != expected_entity_preconditions
        or not entity_result_contract_valid
        or re.fullmatch(
            r"alr1_[0-9a-f]{64}",
            str(attestation.get("entity_record_revision") or ""),
        )
        is None
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_deletion_attestation_invalid",
        )
    target = _class_analysis_dual_bbox_annotation_source_contract(
        job=job,
        point=point,
        conflict=conflict,
        payload={"annotation_target": attestation.get("annotation_target")},
    )
    source_mode = target["source_mode"]
    source_id = target["source_id"]
    split = target["split"]
    rel = _annotation_normalise_image_relpath(target["image_relpath"])
    if source_mode == "linked":
        entry = _resolve_dataset_entry(source_id)
        with _dataset_annotation_mutation_lock(entry):
            dataset_root = _dataset_effective_root_from_entry(entry)
            layout = str(entry.get("yolo_layout") or "flat")
            image_path = _resolve_annotation_image_path(
                dataset_root,
                layout,
                split,
                rel,
            )
            current_lines = _annotation_effective_label_lines(entry, split, rel)
            labelmap = list(
                entry.get("classes") or _dataset_labelmap_from_root(dataset_root)
            )
            source_identity = _annotation_image_source_identity(
                source_mode=source_mode,
                source_id=source_id,
                split=split,
                image_relpath=rel,
                image_path=image_path,
                yolo_layout=layout,
            )
    else:
        session = _resolve_transient_session(source_id)
        dataset_root = _validate_linked_dataset_path(
            str(session.get("dataset_root") or "")
        )
        layout = str(session.get("yolo_layout") or "flat")
        image_path = _resolve_annotation_image_path(
            dataset_root,
            layout,
            split,
            rel,
        )
        key = f"{split}:{rel.as_posix()}"
        overlay = (
            session.get("overlay_labels")
            if isinstance(session.get("overlay_labels"), dict)
            else {}
        )
        if key in overlay:
            current_lines = list(overlay.get(key) or [])
        else:
            source_path = _annotation_source_label_path(
                dataset_root,
                layout,
                split,
                rel,
            )
            source_text = _annotation_read_text_within_root(
                source_path,
                dataset_root,
            )
            current_lines = (
                [line.strip() for line in source_text.splitlines() if line.strip()]
                if source_text is not None
                else []
            )
        labelmap = list(session.get("classes") or [])
        source_identity = _annotation_image_source_identity(
            source_mode=source_mode,
            source_id=source_id,
            split=split,
            image_relpath=rel,
            image_path=image_path,
            yolo_layout=layout,
        )
    if (
        source_identity != str(attestation.get("source_identity") or "")
        or _annotation_image_label_revision(current_lines)
        != str(attestation.get("committed_revision") or "")
        or len(current_lines)
        != int(attestation.get("committed_label_count") or -1)
        or _class_analysis_file_sha256_cached(image_path)
        != str(attestation.get("image_sha256") or "")
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_deletion_attestation_stale",
        )
    with Image.open(image_path) as loaded:
        width, height = loaded.size
    _class_analysis_validate_dual_bbox_post_state(
        before_lines=current_lines,
        after_lines=current_lines,
        point=point,
        conflict=conflict,
        action=action,
        labelmap=labelmap,
        image_width=int(width),
        image_height=int(height),
        idempotent_replay=True,
    )
    entity_preconditions = attestation["entity_preconditions"]
    entity_record = _class_analysis_annotation_entity_store().get_record(
        str(entity_preconditions.get("annotation_source_identity") or ""),
        str(entity_preconditions.get("source_record_key") or ""),
    )
    entity_by_id = {
        str(entity.get("annotation_entity_id") or ""): entity
        for entity in ((entity_record or {}).get("entities") or [])
        if isinstance(entity, Mapping)
    }
    valid_entity_state = bool(
        isinstance(entity_record, Mapping)
        and str(entity_record.get("record_revision") or "")
        == str(attestation.get("entity_record_revision") or "")
    )
    for result in attestation.get("entity_results") or []:
        entity = entity_by_id.get(
            str(result.get("annotation_entity_id") or "")
        )
        valid_entity_state = bool(
            valid_entity_state
            and entity is not None
            and int(entity.get("entity_revision") or 0)
            == int(result.get("entity_revision") or 0)
            and bool(entity.get("deleted")) is bool(result.get("deleted"))
            and str(result.get("outcome") or "")
            == (
                "deleted"
                if bool(entity.get("deleted"))
                else "retained"
            )
        )
    if not valid_entity_state:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="dual_bbox_deletion_entity_attestation_stale",
        )
    return attestation


def _class_analysis_class_reassignment_attestation_hash(
    attestation: Mapping[str, Any],
) -> str:
    return hashlib.sha256(
        json.dumps(
            {
                key: value
                for key, value in dict(attestation).items()
                if key != "attestation_sha256"
            },
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _class_analysis_bbox_geometry_edit_contract(
    value: Any,
    *,
    point_snapshot: Mapping[str, Any],
    image_width: int,
    image_height: int,
) -> Dict[str, Any]:
    """Validate a browser locator, then bind it to frozen analysis geometry.

    The edited coordinates remain a locator until the caller re-reads the
    committed annotation file and proves that one exact row has those
    coordinates.  Browser UUIDs are deliberately absent from this durable
    contract because they are session-local implementation details.
    """

    if (
        not isinstance(value, Mapping)
        or str(value.get("schema") or "")
        != CLASS_ANALYSIS_BBOX_GEOMETRY_EDIT_SCHEMA
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_reassignment_geometry_edit_required",
        )

    def _bbox(field: str, *aliases: str) -> List[float]:
        raw: Any = value.get(field)
        for alias in aliases:
            if raw is None:
                raw = value.get(alias)
        try:
            bbox = [float(item) for item in list(raw or [])[:4]]
        except (TypeError, ValueError, OverflowError) as exc:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="review_reassignment_geometry_edit_invalid",
            ) from exc
        if (
            len(bbox) != 4
            or not all(math.isfinite(item) for item in bbox)
            or bbox[0] < 0.0
            or bbox[1] < 0.0
            or bbox[2] > float(image_width)
            or bbox[3] > float(image_height)
            or bbox[2] <= bbox[0]
            or bbox[3] <= bbox[1]
        ):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="review_reassignment_geometry_edit_invalid",
            )
        return [round(item, 6) for item in bbox]

    analysis_bbox = _bbox("analysis_bbox_xyxy")
    committed_bbox = _bbox(
        "committed_bbox_xyxy",
        "edited_bbox_xyxy",
    )
    frozen_geometry = _class_analysis_exact_frozen_review_geometry(
        {"point": point_snapshot},
        image_width=image_width,
        image_height=image_height,
    )
    analysis_geometry = _class_analysis_canonical_review_geometry(
        {"kind": "bbox", "bbox_xyxy": analysis_bbox},
        image_width=image_width,
        image_height=image_height,
    )
    committed_geometry = _class_analysis_canonical_review_geometry(
        {"kind": "bbox", "bbox_xyxy": committed_bbox},
        image_width=image_width,
        image_height=image_height,
    )
    if frozen_geometry is None or analysis_geometry != frozen_geometry:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_reassignment_analysis_geometry_mismatch",
        )
    return {
        "schema": CLASS_ANALYSIS_BBOX_GEOMETRY_EDIT_SCHEMA,
        "analysis_bbox_xyxy": analysis_bbox,
        "committed_bbox_xyxy": committed_bbox,
        "analysis_geometry": analysis_geometry,
        "committed_geometry": committed_geometry,
        "changed": analysis_geometry != committed_geometry,
    }


def _class_analysis_bbox_geometry_edit_request_payload(
    value: Any,
) -> Optional[Dict[str, Any]]:
    """Canonicalize only the immutable bbox fields for retry comparison."""

    if (
        not isinstance(value, Mapping)
        or str(value.get("schema") or "")
        != CLASS_ANALYSIS_BBOX_GEOMETRY_EDIT_SCHEMA
    ):
        return None

    def _bbox(field: str, alias: str = "") -> Optional[List[float]]:
        raw = value.get(field)
        if raw is None and alias:
            raw = value.get(alias)
        try:
            result = [round(float(item), 6) for item in list(raw or [])]
        except (TypeError, ValueError, OverflowError):
            return None
        if len(result) != 4 or not all(math.isfinite(item) for item in result):
            return None
        return result

    analysis_bbox = _bbox("analysis_bbox_xyxy")
    committed_bbox = _bbox("committed_bbox_xyxy", "edited_bbox_xyxy")
    if analysis_bbox is None or committed_bbox is None:
        return None
    return {
        "schema": CLASS_ANALYSIS_BBOX_GEOMETRY_EDIT_SCHEMA,
        "analysis_bbox_xyxy": analysis_bbox,
        "committed_bbox_xyxy": committed_bbox,
    }


def _class_analysis_browser_bbox_label_line(
    *,
    class_id: int,
    bbox_xyxy: Sequence[float],
    image_width: int,
    image_height: int,
) -> str:
    x1, y1, x2, y2 = [float(value) for value in list(bbox_xyxy)[:4]]

    def _number(value: float) -> str:
        clamped = max(0.0, min(1.0, float(value)))
        return f"{clamped:.6f}".rstrip("0").rstrip(".") or "0"

    return " ".join(
        [
            str(int(class_id)),
            _number(((x1 + x2) / 2.0) / float(image_width)),
            _number(((y1 + y2) / 2.0) / float(image_height)),
            _number((x2 - x1) / float(image_width)),
            _number((y2 - y1) / float(image_height)),
        ]
    )


def _class_analysis_reassignment_annotation_state(
    target: Mapping[str, Any],
) -> Dict[str, Any]:
    """Read one exact committed annotation record under its caller-held lock."""

    split = str(target["split"])
    rel = _annotation_normalise_image_relpath(target["image_relpath"])
    source_mode = str(target["source_mode"])
    source_id = str(target["source_id"])
    if source_mode == "linked":
        entry = _resolve_dataset_entry(source_id)
        dataset_root = _dataset_effective_root_from_entry(entry)
        layout = str(entry.get("yolo_layout") or "flat")
        image_path = _resolve_annotation_image_path(
            dataset_root,
            layout,
            split,
            rel,
        )
        current_lines = _annotation_effective_label_lines(entry, split, rel)
        labelmap = list(
            entry.get("classes") or _dataset_labelmap_from_root(dataset_root)
        )
    else:
        session = _resolve_transient_session(source_id)
        dataset_root = _validate_linked_dataset_path(
            str(session.get("dataset_root") or "")
        )
        layout = str(session.get("yolo_layout") or "flat")
        image_path = _resolve_annotation_image_path(
            dataset_root,
            layout,
            split,
            rel,
        )
        overlay = (
            session.get("overlay_labels")
            if isinstance(session.get("overlay_labels"), dict)
            else {}
        )
        overlay_key = f"{split}:{rel.as_posix()}"
        if overlay_key in overlay:
            current_lines = [
                str(line or "").strip()
                for line in (overlay.get(overlay_key) or [])
                if str(line or "").strip()
            ]
        else:
            source_path = _annotation_source_label_path(
                dataset_root,
                layout,
                split,
                rel,
            )
            source_text = _annotation_read_text_within_root(
                source_path,
                dataset_root,
            )
            current_lines = (
                [
                    line.strip()
                    for line in source_text.splitlines()
                    if line.strip()
                ]
                if source_text is not None
                else []
            )
        labelmap = list(session.get("classes") or [])
    with Image.open(image_path) as loaded:
        image_width, image_height = loaded.size
    return {
        "target": dict(target),
        "current_lines": list(current_lines),
        "labelmap": [str(name or "").strip() for name in labelmap],
        "image_path": image_path,
        "image_width": int(image_width),
        "image_height": int(image_height),
        "source_identity": _annotation_image_source_identity(
            source_mode=source_mode,
            source_id=source_id,
            split=split,
            image_relpath=rel,
            image_path=image_path,
            yolo_layout=layout,
        ),
        "current_revision": _annotation_image_label_revision(current_lines),
        "image_sha256": _class_analysis_file_sha256_cached(image_path),
    }


def _class_analysis_validate_class_reassignment_commit(
    *,
    job: ClassAnalysisJob,
    point: Mapping[str, Any],
    summary: Mapping[str, Any],
    annotation_target: Mapping[str, Any],
    before_revision: str,
    committed_revision: str,
    expected_source_identity: str,
    target_class: str,
    geometry_edit: Any,
    allow_already_committed: bool = False,
) -> Dict[str, Any]:
    """Prove a class transition or the exact already-committed target state.

    The proof supports both user sequences: resize first and save, then change
    class; or resize and change class in the same save.  It reconstructs the
    claimed pre-change revision from the committed server-owned label record,
    so merely supplying plausible browser coordinates cannot mint a receipt.
    """

    if (
        re.fullmatch(r"alr1_[0-9a-f]{64}", before_revision) is None
        or re.fullmatch(r"alr1_[0-9a-f]{64}", committed_revision) is None
        or (before_revision == committed_revision) != allow_already_committed
        or re.fullmatch(r"asi1_[0-9a-f]{64}", expected_source_identity)
        is None
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_reassignment_commit_invalid",
        )
    target = _class_analysis_vignette_training_annotation_target(
        annotation_target
    )
    if target is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="review_reassignment_annotation_target_required",
        )
    point_snapshot = _class_analysis_vignette_training_point_snapshot(
        point,
        summary,
    )
    if (
        _class_analysis_vignette_training_derived_annotation_target(
            {"point": point_snapshot}
        )
        != target
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_reassignment_annotation_target_mismatch",
        )
    state = _class_analysis_reassignment_annotation_state(target)
    if (
        state["source_identity"] != expected_source_identity
        or state["current_revision"] != committed_revision
        or state["image_sha256"]
        != str((point_snapshot.get("image") or {}).get("sha256") or "")
        .strip()
        .lower()
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_reassignment_commit_stale",
        )
    image_width = int(state["image_width"])
    image_height = int(state["image_height"])
    edit = _class_analysis_bbox_geometry_edit_contract(
        geometry_edit,
        point_snapshot=point_snapshot,
        image_width=image_width,
        image_height=image_height,
    )
    labelmap = list(state["labelmap"])
    before_class = str(point.get("class_name") or "").strip()
    if (
        labelmap.count(before_class) != 1
        or labelmap.count(target_class) != 1
        or before_class == target_class
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_reassignment_class_identity_invalid",
        )
    before_class_id = labelmap.index(before_class)
    target_class_id = labelmap.index(target_class)
    matching_rows: List[Tuple[int, str, Dict[str, Any], Optional[int]]] = []
    matching_geometry_count = 0
    for index, line in enumerate(state["current_lines"]):
        parsed, class_id = _class_analysis_parse_yolo_geometry_for_identity(
            line,
            image_width=image_width,
            image_height=image_height,
        )
        if not isinstance(parsed, Mapping):
            continue
        canonical = _class_analysis_canonical_review_geometry(
            parsed,
            image_width=image_width,
            image_height=image_height,
        )
        if canonical != edit["committed_geometry"]:
            continue
        matching_geometry_count += 1
        matching_rows.append((index, str(line), dict(parsed), class_id))
    if (
        matching_geometry_count != 1
        or len(matching_rows) != 1
        or matching_rows[0][3] != target_class_id
        or str(matching_rows[0][2].get("kind") or "bbox") != "bbox"
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "review_reassignment_annotation_unverified",
                "expected_target_class": target_class,
                "exact_committed_geometry_match_count": matching_geometry_count,
            },
        )
    committed_index, committed_line, committed_parsed, _class_id = (
        matching_rows[0]
    )
    committed_bbox = [
        round(float(value), 6)
        for value in list(committed_parsed.get("bbox_xyxy") or [])[:4]
    ]
    original_bbox = [
        round(float(value), 6)
        for value in list((point_snapshot.get("bbox") or {}).get("xyxy") or [])[:4]
    ]
    if len(original_bbox) != 4 or len(committed_bbox) != 4:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="review_reassignment_geometry_edit_invalid",
        )
    # The browser coordinates were only a locator.  Publish the immutable
    # analysis snapshot and the server-parsed committed annotation row as the
    # authoritative geometries in the receipt/corpus.
    edit["analysis_bbox_xyxy"] = original_bbox
    edit["committed_bbox_xyxy"] = committed_bbox
    edit["changed"] = (
        edit["analysis_geometry"] != edit["committed_geometry"]
    )
    if allow_already_committed:
        attestation: Dict[str, Any] = {
            "schema": CLASS_ANALYSIS_CLASS_REASSIGNMENT_ATTESTATION_SCHEMA,
            "committed": True,
            "analysis_job_id": str(job.job_id or ""),
            "point_id": str(point.get("point_id") or ""),
            "source_review_object_key": str(
                point.get("review_object_key") or ""
            ),
            "annotation_target": dict(target),
            "source_identity": state["source_identity"],
            "before_revision": before_revision,
            "committed_revision": committed_revision,
            "image_sha256": state["image_sha256"],
            "before_class": before_class,
            "committed_class": target_class,
            "committed_label_count": len(state["current_lines"]),
            "committed_label_line_sha256": hashlib.sha256(
                " ".join(committed_line.split()).encode("utf-8")
            ).hexdigest(),
            "committed_label_line_index": committed_index,
            "reconstructed_before_label_line_sha256": "",
            "reconstructed_before_label_line_index": None,
            "transition_mode": "already_committed",
            "geometry_edit": edit,
            "verification_method": (
                CLASS_ANALYSIS_CLASS_REASSIGNMENT_ALREADY_COMMITTED_VERIFICATION_METHOD
            ),
            "verified_at": time.time(),
        }
        attestation["attestation_sha256"] = (
            _class_analysis_class_reassignment_attestation_hash(attestation)
        )
        return attestation
    frozen_label_line = str(
        (point_snapshot.get("bbox") or {}).get("label_line") or ""
    ).strip()
    committed_tokens = committed_line.split()
    old_row_candidates: List[Tuple[str, str]] = [
        # Preserve the server-owned numeric spellings.  The annotation
        # revision normalizes whitespace, but intentionally does not round or
        # otherwise normalize coordinates.  Re-serializing here would reject
        # a valid resize-then-reclassify transition written with different
        # decimal precision.
        (
            "geometry_precommitted",
            " ".join([str(before_class_id), *committed_tokens[1:]]),
        ),
        (
            "geometry_precommitted",
            _class_analysis_browser_bbox_label_line(
                class_id=before_class_id,
                bbox_xyxy=committed_bbox,
                image_width=image_width,
                image_height=image_height,
            ),
        ),
        (
            "geometry_and_class_same_commit",
            _class_analysis_browser_bbox_label_line(
                class_id=before_class_id,
                bbox_xyxy=original_bbox,
                image_width=image_width,
                image_height=image_height,
            ),
        ),
    ]
    if frozen_label_line:
        # Prefer the exact frozen analysis row for a resize + reclassify saved
        # in one annotation commit; it carries the original numeric spellings.
        old_row_candidates.insert(
            2,
            ("geometry_and_class_same_commit", frozen_label_line),
        )
    old_row_candidates = list(
        dict.fromkeys(old_row_candidates)
    )
    remaining_lines = [
        *state["current_lines"][:committed_index],
        *state["current_lines"][committed_index + 1 :],
    ]
    insertion_positions = list(range(len(remaining_lines) + 1))
    preferred_position = min(committed_index, len(remaining_lines))
    insertion_positions.remove(preferred_position)
    insertion_positions.insert(0, preferred_position)
    matched_transition: Optional[Tuple[str, str, int]] = None
    for transition_mode, old_line in old_row_candidates:
        for insertion_position in insertion_positions:
            reconstructed = [
                *remaining_lines[:insertion_position],
                old_line,
                *remaining_lines[insertion_position:],
            ]
            if _annotation_image_label_revision(reconstructed) == before_revision:
                matched_transition = (
                    transition_mode,
                    old_line,
                    insertion_position,
                )
                break
        if matched_transition is not None:
            break
    if matched_transition is None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "review_reassignment_transition_unverified",
                "committed_label_count": len(state["current_lines"]),
            },
        )
    transition_mode, reconstructed_old_line, reconstructed_index = (
        matched_transition
    )
    attestation: Dict[str, Any] = {
        "schema": CLASS_ANALYSIS_CLASS_REASSIGNMENT_ATTESTATION_SCHEMA,
        "committed": True,
        "analysis_job_id": str(job.job_id or ""),
        "point_id": str(point.get("point_id") or ""),
        "source_review_object_key": str(
            point.get("review_object_key") or ""
        ),
        "annotation_target": dict(target),
        "source_identity": state["source_identity"],
        "before_revision": before_revision,
        "committed_revision": committed_revision,
        "image_sha256": state["image_sha256"],
        "before_class": before_class,
        "committed_class": target_class,
        "committed_label_count": len(state["current_lines"]),
        "committed_label_line_sha256": hashlib.sha256(
            " ".join(committed_line.split()).encode("utf-8")
        ).hexdigest(),
        "committed_label_line_index": committed_index,
        "reconstructed_before_label_line_sha256": hashlib.sha256(
            " ".join(reconstructed_old_line.split()).encode("utf-8")
        ).hexdigest(),
        "reconstructed_before_label_line_index": reconstructed_index,
        "transition_mode": transition_mode,
        "geometry_edit": edit,
        "verification_method": (
            CLASS_ANALYSIS_CLASS_REASSIGNMENT_VERIFICATION_METHOD
        ),
        "verified_at": time.time(),
    }
    attestation["attestation_sha256"] = (
        _class_analysis_class_reassignment_attestation_hash(attestation)
    )
    return attestation


def _class_analysis_single_bbox_deletion_attestation_hash(
    attestation: Mapping[str, Any],
) -> str:
    return hashlib.sha256(
        json.dumps(
            {
                key: value
                for key, value in dict(attestation).items()
                if key != "attestation_sha256"
            },
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _class_analysis_validate_single_bbox_deletion_commit(
    *,
    job: ClassAnalysisJob,
    point: Mapping[str, Any],
    summary: Mapping[str, Any],
    annotation_target: Mapping[str, Any],
    before_revision: str,
    committed_revision: str,
    expected_source_identity: str,
    allow_already_absent: bool = False,
) -> Dict[str, Any]:
    """Attest a causal deletion or reconcile a previously deleted bbox.

    A causal deletion requires distinct before/after revisions and proves the
    exact one-label transition.  Reconciliation deliberately makes the weaker
    claim that the frozen geometry was already absent at one exact current
    persisted revision; it never fabricates a deletion transition.
    """

    reconcile_already_absent = bool(allow_already_absent)
    if (
        re.fullmatch(r"alr1_[0-9a-f]{64}", before_revision) is None
        or re.fullmatch(r"alr1_[0-9a-f]{64}", committed_revision) is None
        or (
            (before_revision == committed_revision)
            != reconcile_already_absent
        )
        or re.fullmatch(
            r"asi1_[0-9a-f]{64}", expected_source_identity
        )
        is None
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="single_bbox_deletion_commit_invalid",
        )
    target = _class_analysis_vignette_training_annotation_target(
        annotation_target
    )
    if target is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="single_bbox_deletion_annotation_target_required",
        )
    point_snapshot = _class_analysis_vignette_training_point_snapshot(
        point,
        summary,
    )
    derived_target = _class_analysis_vignette_training_derived_annotation_target(
        {"point": point_snapshot}
    )
    if derived_target != target:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="single_bbox_deletion_annotation_target_mismatch",
        )
    split = target["split"]
    rel = _annotation_normalise_image_relpath(target["image_relpath"])
    if target["source_mode"] == "linked":
        entry = _resolve_dataset_entry(target["source_id"])
        dataset_root = _dataset_effective_root_from_entry(entry)
        layout = str(entry.get("yolo_layout") or "flat")
        image_path = _resolve_annotation_image_path(
            dataset_root,
            layout,
            split,
            rel,
        )
        current_lines = _annotation_effective_label_lines(entry, split, rel)
    else:
        session = _resolve_transient_session(target["source_id"])
        dataset_root = _validate_linked_dataset_path(
            str(session.get("dataset_root") or "")
        )
        layout = str(session.get("yolo_layout") or "flat")
        image_path = _resolve_annotation_image_path(
            dataset_root,
            layout,
            split,
            rel,
        )
        overlay = (
            session.get("overlay_labels")
            if isinstance(session.get("overlay_labels"), dict)
            else {}
        )
        overlay_key = f"{split}:{rel.as_posix()}"
        if overlay_key in overlay:
            current_lines = [
                str(line or "").strip()
                for line in (overlay.get(overlay_key) or [])
                if str(line or "").strip()
            ]
        else:
            source_path = _annotation_source_label_path(
                dataset_root,
                layout,
                split,
                rel,
            )
            source_text = _annotation_read_text_within_root(
                source_path,
                dataset_root,
            )
            current_lines = (
                [
                    line.strip()
                    for line in source_text.splitlines()
                    if line.strip()
                ]
                if source_text is not None
                else []
            )
    source_identity = _annotation_image_source_identity(
        source_mode=target["source_mode"],
        source_id=target["source_id"],
        split=split,
        image_relpath=rel,
        image_path=image_path,
        yolo_layout=layout,
    )
    current_revision = _annotation_image_label_revision(current_lines)
    expected_image_sha256 = str(
        (point_snapshot.get("image") or {}).get("sha256") or ""
    ).strip().lower()
    if (
        source_identity != expected_source_identity
        or current_revision != committed_revision
        or re.fullmatch(r"[0-9a-f]{64}", expected_image_sha256) is None
        or _class_analysis_file_sha256_cached(image_path)
        != expected_image_sha256
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="single_bbox_deletion_commit_stale",
        )
    with Image.open(image_path) as loaded:
        width, height = loaded.size
    frozen_geometry = _class_analysis_exact_frozen_review_geometry(
        {"point": point_snapshot},
        image_width=int(width),
        image_height=int(height),
    )
    if frozen_geometry is None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="single_bbox_deletion_geometry_unverifiable",
        )
    exact_match_count = 0
    for line in current_lines:
        parsed, _class_id = _class_analysis_parse_yolo_geometry_for_identity(
            line,
            image_width=int(width),
            image_height=int(height),
        )
        if not isinstance(parsed, Mapping):
            continue
        if _class_analysis_canonical_review_geometry(
            parsed,
            image_width=int(width),
            image_height=int(height),
        ) == frozen_geometry:
            exact_match_count += 1
    if exact_match_count:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "single_bbox_deletion_not_committed",
                "exact_geometry_match_count": exact_match_count,
            },
        )
    if reconcile_already_absent:
        attestation: Dict[str, Any] = {
            "schema": CLASS_ANALYSIS_SINGLE_BBOX_DELETION_ATTESTATION_SCHEMA,
            "committed": True,
            "deletion_state": "already_absent",
            "analysis_job_id": str(job.job_id or ""),
            "point_id": str(point.get("point_id") or ""),
            "review_object_key": str(point.get("review_object_key") or ""),
            "annotation_target": dict(target),
            "source_identity": source_identity,
            "before_revision": current_revision,
            "committed_revision": current_revision,
            "image_sha256": expected_image_sha256,
            "committed_label_count": len(current_lines),
            "verification_method": (
                CLASS_ANALYSIS_SINGLE_BBOX_ALREADY_ABSENT_VERIFICATION_METHOD
            ),
            "verified_at": time.time(),
        }
        attestation["attestation_sha256"] = (
            _class_analysis_single_bbox_deletion_attestation_hash(attestation)
        )
        return attestation
    bbox_snapshot = point_snapshot.get("bbox")
    deleted_label_line = str(
        bbox_snapshot.get("label_line")
        if isinstance(bbox_snapshot, Mapping)
        else ""
    ).strip()
    parsed_deleted_line, deleted_class_id = (
        _class_analysis_parse_yolo_geometry_for_identity(
            deleted_label_line,
            image_width=int(width),
            image_height=int(height),
        )
    )
    if (
        not deleted_label_line
        or not isinstance(parsed_deleted_line, Mapping)
        or deleted_class_id is None
        or _class_analysis_canonical_review_geometry(
            parsed_deleted_line,
            image_width=int(width),
            image_height=int(height),
        )
        != frozen_geometry
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="single_bbox_deletion_transition_unverifiable",
        )

    # Absence alone does not prove that this click caused the deletion: the
    # bbox may already have been missing while the caller supplied any other
    # syntactically valid revision. Reconstruct the exact pre-commit record by
    # adding only the frozen analysis label back to the committed record. The
    # caller's before revision must identify one such reconstruction, proving
    # a one-label transition with no unrelated annotation changes.
    raw_line_index = point.get("label_line_index")
    line_index: Optional[int] = None
    if not isinstance(raw_line_index, bool):
        try:
            parsed_line_index = int(raw_line_index)
        except (TypeError, ValueError, OverflowError):
            parsed_line_index = -1
        if 0 <= parsed_line_index <= len(current_lines):
            line_index = parsed_line_index
    insertion_positions = list(range(len(current_lines) + 1))
    if line_index is not None:
        insertion_positions.remove(line_index)
        insertion_positions.insert(0, line_index)

    def _browser_yolo_number(value: float) -> str:
        clamped = max(0.0, min(1.0, float(value)))
        return f"{clamped:.6f}".rstrip("0").rstrip(".") or "0"

    browser_parts = [str(deleted_class_id)]
    if str(parsed_deleted_line.get("kind") or "bbox") == "polygon":
        for raw_point in parsed_deleted_line.get("points") or []:
            if not isinstance(raw_point, Sequence) or len(raw_point) < 2:
                browser_parts = []
                break
            browser_parts.extend(
                [
                    _browser_yolo_number(
                        float(raw_point[0]) / float(width)
                    ),
                    _browser_yolo_number(
                        float(raw_point[1]) / float(height)
                    ),
                ]
            )
    else:
        deleted_xyxy = list(
            parsed_deleted_line.get("bbox_xyxy") or []
        )[:4]
        if len(deleted_xyxy) == 4:
            x1, y1, x2, y2 = [
                float(value) for value in deleted_xyxy
            ]
            browser_parts.extend(
                [
                    _browser_yolo_number(
                        ((x1 + x2) / 2.0) / float(width)
                    ),
                    _browser_yolo_number(
                        ((y1 + y2) / 2.0) / float(height)
                    ),
                    _browser_yolo_number((x2 - x1) / float(width)),
                    _browser_yolo_number((y2 - y1) / float(height)),
                ]
            )
        else:
            browser_parts = []
    deleted_label_candidates = list(
        dict.fromkeys(
            [
                deleted_label_line,
                *(
                    [" ".join(browser_parts)]
                    if len(browser_parts) >= 5
                    else []
                ),
            ]
        )
    )
    matched_transition: Optional[Tuple[str, int]] = None
    for candidate_line in deleted_label_candidates:
        for position in insertion_positions:
            if _annotation_image_label_revision(
                [
                    *current_lines[:position],
                    candidate_line,
                    *current_lines[position:],
                ]
            ) == before_revision:
                matched_transition = (candidate_line, int(position))
                break
        if matched_transition is not None:
            break
    if matched_transition is None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "single_bbox_deletion_transition_unverified",
                "committed_label_count": len(current_lines),
            },
        )
    matched_deleted_label_line, reconstructed_line_index = (
        matched_transition
    )
    attestation: Dict[str, Any] = {
        "schema": CLASS_ANALYSIS_SINGLE_BBOX_DELETION_ATTESTATION_SCHEMA,
        "committed": True,
        "analysis_job_id": str(job.job_id or ""),
        "point_id": str(point.get("point_id") or ""),
        "review_object_key": str(point.get("review_object_key") or ""),
        "annotation_target": dict(target),
        "source_identity": source_identity,
        "before_revision": before_revision,
        "committed_revision": committed_revision,
        "image_sha256": expected_image_sha256,
        "committed_label_count": len(current_lines),
        "deleted_label_line_sha256": hashlib.sha256(
            " ".join(matched_deleted_label_line.split()).encode("utf-8")
        ).hexdigest(),
        "deleted_label_line_index": reconstructed_line_index,
        "verification_method": (
            CLASS_ANALYSIS_SINGLE_BBOX_DELETION_VERIFICATION_METHOD
        ),
        "verified_at": time.time(),
    }
    attestation["attestation_sha256"] = (
        _class_analysis_single_bbox_deletion_attestation_hash(attestation)
    )
    return attestation


def _class_analysis_require_no_other_pending_dual_bbox_operation(
    *,
    job_id: str,
    pair_review_key: str,
    client_action_id: str,
) -> None:
    """Reserve a pair review key while its destructive journal is unfinished."""

    for operation in _class_analysis_annotation_entity_store().list_operations(
        job_id=str(job_id)
    ):
        request = operation.get("request") or {}
        owner_action_ids = {
            str(operation.get("operation_id") or ""),
            str(request.get("review_client_action_id") or ""),
        }
        if (
            str(request.get("transaction_kind") or "")
            != "dual_bbox_delete_v1"
            or str(request.get("pair_review_key") or "")
            != str(pair_review_key)
            or str(client_action_id) in owner_action_ids
        ):
            continue
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "dual_bbox_annotation_transaction_in_progress",
                "pair_review_key": str(pair_review_key),
                "operation_id": str(operation.get("operation_id") or ""),
            },
        )


def _record_class_analysis_review_disposition_locked(
    job_id: str,
    point_id: str,
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    raw_job_id = str(job_id or "")
    if (
        not raw_job_id
        or _class_analysis_safe_slug(raw_job_id, "") != raw_job_id
    ):
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="job_id_invalid",
        )
    payload = payload if isinstance(payload, dict) else {}
    disposition = str(payload.get("disposition") or "").strip().lower()
    if disposition not in {*CLASS_ANALYSIS_REVIEW_DISPOSITIONS, "clear"}:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="review_disposition_invalid",
        )
    client_action_id = str(
        payload.get("client_action_id") or ""
    ).strip()
    if CLASS_ANALYSIS_REVIEW_CLIENT_ACTION_PATTERN.fullmatch(
        client_action_id
    ) is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="review_disposition_client_action_id_invalid",
        )
    safe_point_id = str(point_id or "").strip()
    if not safe_point_id:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="point_id_required",
        )
    clear_expected_revision = ""
    clear_expected_reviewed_at: Optional[float] = None
    if disposition == "clear":
        clear_expected_revision = str(
            payload.get("expected_revision") or ""
        ).strip()
        if (
            clear_expected_revision
            and CLASS_ANALYSIS_REVIEW_ENTRY_REVISION_PATTERN.fullmatch(
                clear_expected_revision
            )
            is None
        ):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="review_disposition_clear_precondition_invalid",
            )
        if not clear_expected_revision:
            raw_expected_reviewed_at = payload.get("expected_reviewed_at")
            if isinstance(raw_expected_reviewed_at, bool):
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="review_disposition_clear_precondition_invalid",
                )
            try:
                clear_expected_reviewed_at = float(
                    raw_expected_reviewed_at
                )
            except (TypeError, ValueError, OverflowError) as exc:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="review_disposition_clear_precondition_invalid",
                ) from exc
            if (
                not math.isfinite(clear_expected_reviewed_at)
                or clear_expected_reviewed_at <= 0.0
            ):
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="review_disposition_clear_precondition_invalid",
                )
    # Use indexed metadata for the normal production path. Loading and
    # publicizing a 258k-point result.json for one button click would briefly
    # duplicate the full graph in memory and turn a constant-time review action
    # into a multi-second operation.
    job = _get_class_analysis_job(raw_job_id)
    job_dir = _class_analysis_job_dir(
        job.job_id,
        create=False,
        detail="result_not_found",
    )
    point = _class_analysis_thumbnail_point_metadata(
        job,
        job_dir,
        safe_point_id,
    )
    raw_result: Dict[str, Any] = {
        "summary": {
            **dict(getattr(job, "summary", None) or {}),
            "analysis_job_id": str(job.job_id or job_id or ""),
        },
    }
    if point is None:
        # Legacy jobs and focused unit fixtures may predate indexed metadata.
        # Keep the compatibility fallback, but new production analyses always
        # take the fast path above.
        if isinstance(job.result, dict):
            raw_result = job.result
        else:
            result_path = _safe_job_result_json_path(
                job.result_path,
                CLASS_ANALYSIS_ROOT,
            )
            if result_path is None:
                raise HTTPException(
                    status_code=HTTP_404_NOT_FOUND,
                    detail="result_not_found",
                )
            raw_result = _class_analysis_load_job_result_payload(
                job,
                result_path,
            )
        raw_result["summary"] = {
            **dict(raw_result.get("summary") or {}),
            "analysis_job_id": str(job.job_id or job_id or ""),
        }
        point = next(
            (
                item
                for item in (raw_result.get("points") or [])
                if isinstance(item, dict)
                and str(item.get("point_id") or "") == safe_point_id
            ),
            None,
        )
        if point is not None and not point.get("review_object_key"):
            candidate = next(
                (
                    item
                    for item in (raw_result.get("wrong_class_candidates") or [])
                    if isinstance(item, dict)
                    and str(item.get("point_id") or "") == safe_point_id
                ),
                None,
            )
            if isinstance(candidate, dict):
                point = {
                    **point,
                    "review_object_key": candidate.get("review_object_key"),
                }
    if point is None:
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="point_not_found")
    point = _class_analysis_backfill_review_object_key(job, point)
    _class_analysis_require_dual_bbox_pair_action(
        point,
        action=disposition,
        allow_pair_clear=(
            disposition == "clear"
            and isinstance(payload.get("dual_bbox_conflict"), Mapping)
        ),
    )
    pair_conflict: Optional[Dict[str, Any]] = None
    pair_review_key = ""
    pair_resolution: Optional[Dict[str, Any]] = None
    current_review_object_key = str(
        point.get("review_object_key") or ""
    ).strip()
    other_review_object_key = ""
    pair_request = (
        disposition in CLASS_ANALYSIS_DUAL_BBOX_REVIEW_DISPOSITIONS
        or (
            disposition == "clear"
            and isinstance(payload.get("dual_bbox_conflict"), Mapping)
        )
    )
    if pair_request:
        (
            pair_conflict,
            pair_review_key,
            current_review_object_key,
            other_review_object_key,
        ) = _class_analysis_validated_dual_bbox_conflict(
            job,
            point,
            payload,
        )
        _class_analysis_require_no_other_pending_dual_bbox_operation(
            job_id=raw_job_id,
            pair_review_key=pair_review_key,
            client_action_id=client_action_id,
        )
        if disposition != "clear":
            commit_attestation = None
            if disposition in {
                "delete_current_box",
                "delete_overlapping_box",
            }:
                commit_attestation = (
                    _class_analysis_validate_dual_bbox_annotation_commit_attestation(
                        job=job,
                        point=point,
                        conflict=pair_conflict,
                        pair_review_key=pair_review_key,
                        action=disposition,
                        value=payload.get("annotation_commit_attestation"),
                    )
                )
            pair_resolution = (
                _class_analysis_dual_bbox_pair_resolution_record(
                    action=disposition,
                    point=point,
                    conflict=pair_conflict,
                    pair_review_key=pair_review_key,
                    current_review_object_key=current_review_object_key,
                    other_review_object_key=other_review_object_key,
                    annotation_commit_attestation=commit_attestation,
                )
            )
        point = {
            **point,
            "review_object_key": pair_review_key,
            **(
                {"dual_bbox_pair_resolution": pair_resolution}
                if isinstance(pair_resolution, dict)
                else {}
            ),
        }
    if disposition != "clear":
        preflight_review_object_key = (
            _class_analysis_review_reassignment_key(
                current_review_object_key,
                str(job.job_id or raw_job_id),
            )
            if disposition == "reassign_class"
            else pair_review_key or current_review_object_key
        )
        _class_analysis_preflight_review_action_tombstone(
            preflight_review_object_key,
            client_action_id,
        )
    entry: Optional[Dict[str, Any]] = None
    if disposition == "delete_bbox":
        deletion_commit_status = str(
            payload.get("label_commit_status") or ""
        ).strip().lower()
        if deletion_commit_status not in {"committed", "already_absent"}:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="single_bbox_deletion_label_commit_required",
            )
        annotation_target = _class_analysis_vignette_training_annotation_target(
            payload.get("annotation_target")
        )
        if annotation_target is None:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="single_bbox_deletion_annotation_target_required",
            )
        before_revision = str(
            payload.get("annotation_before_revision") or ""
        ).strip()
        committed_revision = str(
            payload.get("annotation_commit_revision") or ""
        ).strip()
        expected_source_identity = str(
            payload.get("annotation_source_identity") or ""
        ).strip()
        existing = _class_analysis_lookup_review_dispositions(
            [current_review_object_key]
        ).get(current_review_object_key)
        stored_attestation = (
            existing.get("single_bbox_deletion_attestation")
            if isinstance(existing, Mapping)
            and isinstance(
                existing.get("single_bbox_deletion_attestation"), Mapping
            )
            else None
        )
        exact_idempotent_replay = bool(
            client_action_id
            and isinstance(existing, Mapping)
            and str(existing.get("client_action_id") or "")
                == client_action_id
            and str(existing.get("disposition") or "").strip().lower()
                == "delete_bbox"
            and str(existing.get("analysis_job_id") or "") == raw_job_id
            and str(existing.get("point_id") or "") == safe_point_id
            and str(existing.get("origin") or "")
                == _class_analysis_review_origin(
                    payload.get("origin") or "desktop"
                )
            and bool(existing.get("training_capture_requested"))
                == (payload.get("capture_training_data") is True)
            and isinstance(stored_attestation, Mapping)
            and stored_attestation.get("annotation_target")
                == annotation_target
            and str(stored_attestation.get("before_revision") or "")
                == before_revision
            and str(stored_attestation.get("committed_revision") or "")
                == committed_revision
            and str(stored_attestation.get("source_identity") or "")
                == expected_source_identity
            and str(
                stored_attestation.get("verification_method") or ""
            )
                == (
                    CLASS_ANALYSIS_SINGLE_BBOX_ALREADY_ABSENT_VERIFICATION_METHOD
                    if deletion_commit_status == "already_absent"
                    else CLASS_ANALYSIS_SINGLE_BBOX_DELETION_VERIFICATION_METHOD
                )
        )
        if isinstance(existing, Mapping):
            if not exact_idempotent_replay:
                same_action_token = (
                    str(existing.get("client_action_id") or "")
                    == client_action_id
                )
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=(
                        "review_disposition_client_action_conflict"
                        if same_action_token
                        else {
                            "code": "review_disposition_changed",
                            "review_object_key": (
                                current_review_object_key
                            ),
                        }
                    ),
                )
            point = {
                **point,
                "single_bbox_deletion_attestation": copy.deepcopy(
                    dict(stored_attestation)
                ),
            }
            entry = _class_analysis_record_review_disposition_entry(
                result=raw_result,
                point=point,
                disposition=disposition,
                origin=str(payload.get("origin") or "desktop"),
                client_action_id=client_action_id,
                training_capture_requested=(
                    payload.get("capture_training_data") is True
                ),
            )
        else:
            with _class_analysis_annotation_target_transaction_lock(
                annotation_target
            ):
                deletion_attestation = (
                    _class_analysis_validate_single_bbox_deletion_commit(
                        job=job,
                        point=point,
                        summary=raw_result.get("summary") or {},
                        annotation_target=annotation_target,
                        before_revision=before_revision,
                        committed_revision=committed_revision,
                        expected_source_identity=expected_source_identity,
                        allow_already_absent=(
                            deletion_commit_status == "already_absent"
                        ),
                    )
                )
                point = {
                    **point,
                    "single_bbox_deletion_attestation": (
                        deletion_attestation
                    ),
                }
                entry = _class_analysis_record_review_disposition_entry(
                    result=raw_result,
                    point=point,
                    disposition=disposition,
                    origin=str(payload.get("origin") or "desktop"),
                    client_action_id=client_action_id,
                    training_capture_requested=(
                        payload.get("capture_training_data") is True
                    ),
                )
    elif disposition == "reassign_class":
        target_class = str(payload.get("target_class") or "").strip()
        frozen_class = str(point.get("class_name") or "").strip()
        source_review_object_key = str(
            point.get("review_object_key") or ""
        ).strip()
        labelmap = {
            str(name or "").strip()
            for name in (raw_result.get("summary") or {}).get(
                "labelmap", []
            )
            if str(name or "").strip()
        }
        if (
            not target_class
            or len(target_class) > 512
            or target_class == frozen_class
        ):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="review_reassignment_target_invalid",
            )
        if labelmap and target_class not in labelmap:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="review_reassignment_target_unknown",
            )
        reassignment_commit_status = str(
            payload.get("label_commit_status") or ""
        ).strip().lower()
        if reassignment_commit_status not in {
            "committed",
            "already_committed",
        }:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="review_reassignment_label_commit_required",
            )
        annotation_target = _class_analysis_vignette_training_annotation_target(
            payload.get("annotation_target")
        )
        if annotation_target is None:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="review_reassignment_annotation_target_required",
            )
        point_snapshot = _class_analysis_vignette_training_point_snapshot(
            point,
            raw_result.get("summary") or {},
        )
        derived_annotation_target = (
            _class_analysis_vignette_training_derived_annotation_target(
                {"point": point_snapshot}
            )
        )
        if derived_annotation_target != annotation_target:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail="review_reassignment_annotation_target_mismatch",
            )
        reassignment_key = _class_analysis_review_reassignment_key(
            source_review_object_key,
            raw_job_id,
        )
        point = {
            **point,
            "review_object_key": reassignment_key,
            "source_review_object_key": source_review_object_key,
            "review_target_class": target_class,
            "review_annotation_target": dict(annotation_target),
        }
        existing = _class_analysis_lookup_review_dispositions(
            [reassignment_key]
        ).get(reassignment_key)
        supplied_geometry_edit = payload.get("geometry_edit")
        supplied_before_revision = str(
            payload.get("annotation_before_revision") or ""
        ).strip()
        supplied_committed_revision = str(
            payload.get("annotation_commit_revision") or ""
        ).strip()
        supplied_source_identity = str(
            payload.get("annotation_source_identity") or ""
        ).strip()
        stored_reassignment_attestation = (
            existing.get("class_reassignment_attestation")
            if isinstance(existing, Mapping)
            and isinstance(
                existing.get("class_reassignment_attestation"), Mapping
            )
            else None
        )
        supplied_geometry_retry_payload = (
            _class_analysis_bbox_geometry_edit_request_payload(
                supplied_geometry_edit
            )
        )
        supplied_geometry_contract: Optional[Dict[str, Any]] = None
        if supplied_geometry_retry_payload is not None:
            image_snapshot = point_snapshot.get("image")
            image_snapshot = (
                image_snapshot
                if isinstance(image_snapshot, Mapping)
                else {}
            )
            try:
                supplied_geometry_contract = (
                    _class_analysis_bbox_geometry_edit_contract(
                        supplied_geometry_edit,
                        point_snapshot=point_snapshot,
                        image_width=_coerce_int(
                            image_snapshot.get("width"), 0
                        ),
                        image_height=_coerce_int(
                            image_snapshot.get("height"), 0
                        ),
                    )
                )
            except HTTPException:
                supplied_geometry_contract = None
        stored_geometry_contract = (
            stored_reassignment_attestation.get("geometry_edit")
            if isinstance(stored_reassignment_attestation, Mapping)
            and isinstance(
                stored_reassignment_attestation.get("geometry_edit"),
                Mapping,
            )
            else None
        )
        supplied_geometry_retry_matches = bool(
            isinstance(supplied_geometry_contract, Mapping)
            and isinstance(stored_geometry_contract, Mapping)
            and _class_analysis_json_safe(
                supplied_geometry_contract.get("analysis_geometry")
            )
            == _class_analysis_json_safe(
                stored_geometry_contract.get("analysis_geometry")
            )
            and _class_analysis_json_safe(
                supplied_geometry_contract.get("committed_geometry")
            )
            == _class_analysis_json_safe(
                stored_geometry_contract.get("committed_geometry")
            )
        )
        exact_idempotent_replay = bool(
            client_action_id
            and isinstance(existing, Mapping)
            and str(existing.get("client_action_id") or "")
                == client_action_id
            and str(existing.get("disposition") or "").strip().lower()
                == "reassign_class"
            and str(existing.get("analysis_job_id") or "") == raw_job_id
            and str(existing.get("point_id") or "") == safe_point_id
            and str(existing.get("origin") or "")
                == _class_analysis_review_origin(
                    payload.get("origin") or "desktop"
                )
            and bool(existing.get("training_capture_requested"))
                == (payload.get("capture_training_data") is True)
            and str(existing.get("target_class") or "").strip()
                == target_class
            and str(existing.get("source_review_object_key") or "").strip()
                == source_review_object_key
            and existing.get("annotation_target") == annotation_target
            and isinstance(stored_reassignment_attestation, Mapping)
            and supplied_geometry_retry_payload is not None
            and supplied_geometry_retry_matches
            and str(
                stored_reassignment_attestation.get("before_revision")
                or ""
            ) == supplied_before_revision
            and str(
                stored_reassignment_attestation.get(
                    "committed_revision"
                )
                or ""
            ) == supplied_committed_revision
            and str(
                stored_reassignment_attestation.get("source_identity")
                or ""
            ) == supplied_source_identity
            and str(
                stored_reassignment_attestation.get("verification_method")
                or ""
            )
                == (
                    CLASS_ANALYSIS_CLASS_REASSIGNMENT_ALREADY_COMMITTED_VERIFICATION_METHOD
                    if reassignment_commit_status == "already_committed"
                    else CLASS_ANALYSIS_CLASS_REASSIGNMENT_VERIFICATION_METHOD
                )
        )
        if exact_idempotent_replay:
            if isinstance(stored_reassignment_attestation, Mapping):
                point = {
                    **point,
                    "class_reassignment_attestation": copy.deepcopy(
                        dict(stored_reassignment_attestation)
                    ),
                }
            entry = _class_analysis_record_review_disposition_entry(
                result=raw_result,
                point=point,
                disposition=disposition,
                origin=str(payload.get("origin") or "desktop"),
                client_action_id=client_action_id,
                training_capture_requested=(
                    payload.get("capture_training_data") is True
                ),
            )
        else:
            with _class_analysis_annotation_target_transaction_lock(
                annotation_target
            ):
                reassignment_attestation = (
                    _class_analysis_validate_class_reassignment_commit(
                        job=job,
                        point={
                            **point,
                            "review_object_key": source_review_object_key,
                        },
                        summary=raw_result.get("summary") or {},
                        annotation_target=annotation_target,
                        before_revision=supplied_before_revision,
                        committed_revision=supplied_committed_revision,
                        expected_source_identity=supplied_source_identity,
                        target_class=target_class,
                        geometry_edit=supplied_geometry_edit,
                        allow_already_committed=(
                            reassignment_commit_status
                            == "already_committed"
                        ),
                    )
                )
                point = {
                    **point,
                    "class_reassignment_attestation": (
                        reassignment_attestation
                    ),
                }
                entry = _class_analysis_record_review_disposition_entry(
                    result=raw_result,
                    point=point,
                    disposition=disposition,
                    origin=str(payload.get("origin") or "desktop"),
                    client_action_id=client_action_id,
                    training_capture_requested=(
                        payload.get("capture_training_data") is True
                    ),
                )
    if disposition == "clear":
        review_object_key = str(point.get("review_object_key") or "").strip()
        previous = _class_analysis_clear_review_disposition_entry(
            review_object_key,
            expected_revision=clear_expected_revision,
            expected_reviewed_at=clear_expected_reviewed_at,
        )
        response = {
            "schema": CLASS_ANALYSIS_REVIEW_DISPOSITION_RECEIPT_SCHEMA,
            "status": "cleared" if previous is not None else "already_clear",
            "job_id": raw_job_id,
            "point_id": safe_point_id,
            "review_object_key": review_object_key,
            "disposition": "clear",
            "client_action_id": client_action_id,
            "training_capture_requested": (
                payload.get("capture_training_data") is True
            ),
            "previous_disposition": (
                str(previous.get("disposition") or "")
                if isinstance(previous, dict)
                else ""
            ),
        }
        if pair_review_key:
            response["pair_review_key"] = pair_review_key
            response["current_review_object_key"] = (
                current_review_object_key
            )
            response["other_review_object_key"] = other_review_object_key
        if (
            payload.get("capture_training_data") is True
            and previous is not None
        ):
            # The review-ledger clear above is the primary transaction. Keep a
            # frozen capture request on the private in-process response so the
            # public wrapper can release the global mutation lock before doing
            # any media snapshotting or append-only corpus I/O.
            response["_training_capture_context"] = {
                "kind": "clear",
                "job_id": str(job_id or ""),
                "point_id": safe_point_id,
                "review_object_key": review_object_key,
                "previous": copy.deepcopy(dict(previous)),
                "payload": {
                    **copy.deepcopy(payload),
                    "action_type": "undo_review",
                    "point_id": safe_point_id,
                    "before_class": str(point.get("class_name") or ""),
                    "after_class": str(point.get("class_name") or ""),
                },
            }
        elif payload.get("capture_training_data") is True:
            response["training_capture"] = {
                "status": "not_required",
                "reason": "review_already_clear",
            }
        return response
    if entry is None:
        if disposition == "confirm_current":
            entry = _class_analysis_record_confirm_current_disposition(
                job=job,
                result=raw_result,
                point=point,
                payload=payload,
                origin=str(payload.get("origin") or "desktop"),
                client_action_id=client_action_id,
                training_capture_requested=(
                    payload.get("capture_training_data") is True
                ),
            )
        else:
            entry = _class_analysis_record_review_disposition_entry(
                result=raw_result,
                point=point,
                disposition=disposition,
                origin=str(payload.get("origin") or "desktop"),
                client_action_id=client_action_id,
                training_capture_requested=(
                    payload.get("capture_training_data") is True
                ),
            )
    response = {
        "schema": CLASS_ANALYSIS_REVIEW_DISPOSITION_RECEIPT_SCHEMA,
        "status": "recorded",
        "job_id": raw_job_id,
        "point_id": safe_point_id,
        "review_object_key": entry["review_object_key"],
        "disposition": disposition,
        "human_reviewed_at": entry["updated_at"],
        "human_review_revision": entry["entry_revision"],
        "origin": entry["origin"],
        "client_action_id": client_action_id,
        "training_capture_requested": (
            payload.get("capture_training_data") is True
        ),
        "idempotent_replay": bool(entry.get("_idempotent_replay")),
    }
    if disposition == "reassign_class":
        response["target_class"] = str(entry.get("target_class") or "")
        if isinstance(
            entry.get("class_reassignment_attestation"), Mapping
        ):
            response["annotation_commit_attestation"] = copy.deepcopy(
                dict(entry["class_reassignment_attestation"])
            )
            response["geometry_edit"] = copy.deepcopy(
                dict(
                    entry["class_reassignment_attestation"].get(
                        "geometry_edit"
                    )
                    or {}
                )
            )
    if disposition == "delete_bbox" and isinstance(
        entry.get("single_bbox_deletion_attestation"), Mapping
    ):
        single_bbox_attestation = copy.deepcopy(
            dict(entry["single_bbox_deletion_attestation"])
        )
        response["annotation_commit_attestation"] = single_bbox_attestation
        if (
            str(single_bbox_attestation.get("verification_method") or "")
            == CLASS_ANALYSIS_SINGLE_BBOX_ALREADY_ABSENT_VERIFICATION_METHOD
        ):
            response["status"] = "already_absent"
            response["annotation_state"] = "already_absent"
    if disposition == "confirm_current" and isinstance(
        entry.get("review_annotation_attestation"), Mapping
    ):
        response["annotation_entity_attestation"] = copy.deepcopy(
            dict(entry["review_annotation_attestation"])
        )
    if pair_review_key:
        response["pair_review_key"] = pair_review_key
        response["current_review_object_key"] = current_review_object_key
        response["other_review_object_key"] = other_review_object_key
        response["dual_bbox_conflict"] = pair_conflict
    if payload.get("capture_training_data") is True:
        capture_payload = {
            key: copy.deepcopy(payload.get(key))
            for key in (
                "capture_training_data",
                "origin",
                "client_action_id",
                "session_id",
                "group_id",
                "review_id",
                "review_ids",
                "annotation_target",
                "label_commit_status",
                "annotation_commit_attestation",
                "_training_authorization",
            )
            if key in payload
        }
        if isinstance(pair_conflict, dict):
            # Never forward caller-owned pair identity into the training
            # corpus. These values were rebound above from the persisted
            # analysis and canonical annotation-object hashes.
            capture_payload["dual_bbox_conflict"] = copy.deepcopy(
                pair_conflict
            )
        if isinstance(pair_resolution, dict):
            capture_payload["dual_bbox_pair_resolution"] = copy.deepcopy(
                pair_resolution
            )
        if disposition == "delete_bbox" and isinstance(
            entry.get("single_bbox_deletion_attestation"), Mapping
        ):
            # Training capture must receive the server-generated proof, never
            # a caller-authored mutation claim.
            capture_payload["single_bbox_deletion_attestation"] = (
                copy.deepcopy(
                    dict(entry["single_bbox_deletion_attestation"])
                )
            )
        if disposition == "reassign_class" and isinstance(
            entry.get("class_reassignment_attestation"), Mapping
        ):
            reassignment_attestation = copy.deepcopy(
                dict(entry["class_reassignment_attestation"])
            )
            capture_payload["geometry_edit"] = copy.deepcopy(
                dict(reassignment_attestation.get("geometry_edit") or {})
            )
            capture_payload["annotation_before_revision"] = str(
                reassignment_attestation.get("before_revision") or ""
            )
            capture_payload["annotation_commit_revision"] = str(
                reassignment_attestation.get("committed_revision") or ""
            )
            capture_payload["annotation_source_identity"] = str(
                reassignment_attestation.get("source_identity") or ""
            )
        response["_training_capture_context"] = {
            "kind": "review",
            "job_id": str(job_id or ""),
            "point_id": safe_point_id,
            "payload": {
                **capture_payload,
                "action_type": (
                    "change_class"
                    if disposition == "reassign_class"
                    else disposition
                ),
                "point_id": safe_point_id,
                "before_class": str(point.get("class_name") or ""),
                "after_class": (
                    str(entry.get("target_class") or "")
                    if disposition == "reassign_class"
                    else str(point.get("class_name") or "")
                ),
                **(
                    {"label_commit_status": "pending_desktop_sync"}
                    if disposition == "reassign_class"
                    else {}
                ),
            },
        }
    return response


def _class_analysis_finalize_review_training_capture(
    response: Dict[str, Any],
) -> Dict[str, Any]:
    """Run optional corpus capture after the primary review lock is released."""

    context = response.pop("_training_capture_context", None)
    if not isinstance(context, Mapping):
        return response
    job_id = str(context.get("job_id") or "")
    point_id = str(context.get("point_id") or "")
    capture_payload = copy.deepcopy(
        dict(context.get("payload") or {})
    )
    kind = str(context.get("kind") or "review")
    try:
        if kind == "clear" and not str(
            capture_payload.get("tombstone_of_action_id") or ""
        ).strip():
            # Every contemporary review row has a mandatory deterministic
            # client action id. Deriving its corpus id avoids a whole-corpus
            # scan and remains correct even if the original append is still in
            # flight when the human immediately restores the review choice.
            previous = (
                context.get("previous")
                if isinstance(context.get("previous"), Mapping)
                else {}
            )
            previous_client_action_id = re.sub(
                r"[^A-Za-z0-9_.:-]+",
                "_",
                str(previous.get("client_action_id") or "").strip(),
            )[:160]
            if previous_client_action_id:
                capture_payload["tombstone_of_action_id"] = (
                    "client:"
                    f"{previous_client_action_id}:"
                    f"{hashlib.sha256(point_id.encode('utf-8')).hexdigest()[:16]}"
                )
            else:
                # Compatibility only for pre-client-action history rows.
                capture_payload["tombstone_of_action_id"] = (
                    _class_analysis_latest_captured_review_action_id(
                        str(context.get("review_object_key") or "")
                    )
                )
        response["training_capture"] = (
            record_class_analysis_vignette_training_action(
                job_id,
                capture_payload,
            )
        )
    except Exception as exc:
        # The durable human choice is already committed. Corpus capture is
        # explicitly optional and must report failure without rolling back or
        # monopolizing the review transaction lock.
        logger.exception(
            "%s, but opt-in training capture failed for %s/%s",
            (
                "Review disposition was cleared"
                if kind == "clear"
                else "Review disposition was saved"
            ),
            job_id,
            point_id,
        )
        response["training_capture"] = {
            "status": "failed",
            "detail": (
                str(exc.detail)
                if isinstance(exc, HTTPException)
                else "vignette_training_action_append_failed"
            ),
        }
    return response


def record_class_analysis_review_disposition(
    job_id: str,
    point_id: str,
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    """Commit review state atomically, then perform optional capture unlocked."""

    with CLASS_ANALYSIS_REVIEW_MUTATION_TRANSACTION_LOCK:
        response = _record_class_analysis_review_disposition_locked(
            job_id,
            point_id,
            payload,
        )
    _class_analysis_sync_review_receipt_to_session(job_id, point_id, response)
    return _class_analysis_finalize_review_training_capture(response)


def commit_class_analysis_dual_bbox_annotation_transaction(
    job_id: str,
    point_id: str,
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    """Atomically commit one pair deletion and its review row."""

    with _CLASS_ANALYSIS_ANNOTATION_ENTITY_LOCK:
        with CLASS_ANALYSIS_REVIEW_MUTATION_TRANSACTION_LOCK:
            try:
                response = (
                    _commit_class_analysis_dual_bbox_annotation_transaction_locked(
                        job_id,
                        point_id,
                        payload,
                    )
                )
            except HTTPException as exc:
                detail = exc.detail if isinstance(exc.detail, Mapping) else {}
                if (
                    detail.get("rerun_required") is True
                    or str(detail.get("status") or "") == "rerun_required"
                ):
                    operation_id = str(
                        (payload or {}).get("operation_id") or ""
                    ).strip()
                    store = _class_analysis_annotation_entity_store()
                    operation = store.get_operation(operation_id)
                    if operation is not None and str(
                        operation.get("state") or ""
                    ) not in {"complete", "conflict", "rejected"}:
                        request = operation.get("request") or {}
                        preconditions = request.get("entity_preconditions") or {}
                        source_identity = str(
                            preconditions.get("annotation_source_identity")
                            or request.get("expected_source_identity")
                            or ""
                        )
                        image_key = str(
                            preconditions.get("source_record_key") or ""
                        )
                        if source_identity and image_key:
                            store.mark_operation_conflict(
                                operation_id=operation_id,
                                source_identity=source_identity,
                                image_key=image_key,
                                detail=dict(detail),
                                response=operation.get("response") or {},
                            )
                raise
    review_receipt = response.get("review_disposition")
    if isinstance(review_receipt, dict):
        _class_analysis_sync_review_receipt_to_session(
            job_id,
            point_id,
            review_receipt,
        )
        _class_analysis_finalize_review_training_capture(review_receipt)
    return response


def delete_class_analysis_review_history(
    job_id: str,
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    """Delete the requested durable review choices without touching annotations.

    The browser identifies rows by point id and supplies compare-and-delete
    preconditions. Canonical object and pair keys always come from the frozen
    analysis metadata. All touched shards are locked and validated before the
    first rewrite, so a stale row cannot leave a partially cleared request.
    """

    raw_job_id = str(job_id or "")
    if (
        not raw_job_id
        or _class_analysis_safe_slug(raw_job_id, "") != raw_job_id
    ):
        # Mutation routes must never inherit the read-path compatibility that
        # turns an arbitrary identifier into a different on-disk job slug.
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="job_id_invalid",
        )

    payload = payload if isinstance(payload, dict) else {}
    if payload.get("schema") != CLASS_ANALYSIS_REVIEW_HISTORY_DELETE_SCHEMA:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="review_history_delete_schema_invalid",
        )
    raw_entries = payload.get("entries")
    if not isinstance(raw_entries, list):
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="review_history_delete_entries_required",
        )
    if len(raw_entries) > CLASS_ANALYSIS_REVIEW_HISTORY_DELETE_MAX_ENTRIES:
        raise HTTPException(
            status_code=HTTP_413_CONTENT_TOO_LARGE,
            detail="review_history_delete_too_many_entries",
        )
    client_action_id = str(payload.get("client_action_id") or "").strip()
    if CLASS_ANALYSIS_REVIEW_CLIENT_ACTION_PATTERN.fullmatch(
        client_action_id
    ) is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="review_history_delete_client_action_id_invalid",
        )

    job = _get_class_analysis_job(raw_job_id)
    job_dir = _class_analysis_job_dir(
        job.job_id,
        create=False,
        detail="result_not_found",
    )
    legacy_points_by_id: Optional[Dict[str, Dict[str, Any]]] = None

    def point_for_id(point_id: str) -> Optional[Dict[str, Any]]:
        nonlocal legacy_points_by_id
        indexed = _class_analysis_thumbnail_point_metadata(job, job_dir, point_id)
        if indexed is not None:
            return indexed
        if legacy_points_by_id is None:
            if isinstance(job.result, dict):
                result = job.result
            else:
                result_path = _safe_job_result_json_path(
                    job.result_path,
                    CLASS_ANALYSIS_ROOT,
                )
                if result_path is None:
                    raise HTTPException(
                        status_code=HTTP_404_NOT_FOUND,
                        detail="result_not_found",
                    )
                result = _class_analysis_load_job_result_payload(job, result_path)
            legacy_points_by_id = {
                str(point.get("point_id") or ""): dict(point)
                for point in (result.get("points") or [])
                if isinstance(point, dict)
                and str(point.get("point_id") or "").strip()
            }
            candidate_keys = {
                str(candidate.get("point_id") or ""): str(
                    candidate.get("review_object_key") or ""
                ).strip()
                for field in (
                    "wrong_class_candidates",
                    "refinement_candidates",
                    "vignette_candidates",
                    "within_class_outlier_candidates",
                )
                for candidate in (result.get(field) or [])
                if isinstance(candidate, dict)
                and str(candidate.get("point_id") or "").strip()
                and str(candidate.get("review_object_key") or "").strip()
            }
            for candidate_point_id, review_object_key in candidate_keys.items():
                if candidate_point_id in legacy_points_by_id:
                    legacy_points_by_id[candidate_point_id].setdefault(
                        "review_object_key",
                        review_object_key,
                    )
        return legacy_points_by_id.get(point_id)

    resolved_by_key: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
    seen_point_ids: Set[str] = set()
    for raw_entry in raw_entries:
        if not isinstance(raw_entry, Mapping):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="review_history_delete_entry_invalid",
            )
        point_id = str(raw_entry.get("point_id") or "").strip()
        expected_disposition = str(
            raw_entry.get("expected_disposition") or ""
        ).strip().lower()
        expected_revision = str(
            raw_entry.get("expected_revision") or ""
        ).strip()
        if expected_revision and CLASS_ANALYSIS_REVIEW_ENTRY_REVISION_PATTERN.fullmatch(
            expected_revision
        ) is None:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="review_history_delete_precondition_invalid",
            )
        expected_reviewed_at: Optional[float] = None
        if not expected_revision and "expected_reviewed_at" in raw_entry:
            if isinstance(raw_entry.get("expected_reviewed_at"), bool):
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="review_history_delete_precondition_invalid",
                )
            try:
                expected_reviewed_at = float(
                    raw_entry.get("expected_reviewed_at")
                )
            except (TypeError, ValueError, OverflowError) as exc:
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST,
                    detail="review_history_delete_precondition_invalid",
                ) from exc
        if (
            not point_id
            or expected_disposition not in CLASS_ANALYSIS_REVIEW_DISPOSITIONS
            or (
                not expected_revision
                and (
                    expected_reviewed_at is None
                    or not math.isfinite(expected_reviewed_at)
                    or expected_reviewed_at <= 0.0
                )
            )
        ):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="review_history_delete_precondition_invalid",
            )
        if point_id in seen_point_ids:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail="review_history_delete_point_duplicate",
            )
        seen_point_ids.add(point_id)
        point = point_for_id(point_id)
        if point is None:
            raise HTTPException(
                status_code=HTTP_404_NOT_FOUND,
                detail="point_not_found",
            )
        current_review_object_key = str(
            point.get("review_object_key") or ""
        ).strip()
        pair_review_key = ""
        if _class_analysis_point_is_dual_bbox_resolution_task(point):
            conflict = point.get("dual_bbox_conflict")
            conflict = conflict if isinstance(conflict, Mapping) else {}
            frozen_pair_key = str(
                conflict.get("pair_review_key") or ""
            ).strip()
            frozen_current_key = str(
                conflict.get("current_review_object_key") or ""
            ).strip()
            frozen_other_key = str(
                conflict.get("other_review_object_key") or ""
            ).strip()
            if any(
                (frozen_pair_key, frozen_current_key, frozen_other_key)
            ):
                if (
                    re.fullmatch(r"crp_[0-9a-f]{64}", frozen_pair_key)
                    is None
                    or re.fullmatch(
                        r"cro_[0-9a-f]{64}", frozen_current_key
                    )
                    is None
                    or re.fullmatch(
                        r"cro_[0-9a-f]{64}", frozen_other_key
                    )
                    is None
                    or current_review_object_key != frozen_current_key
                    or frozen_current_key == frozen_other_key
                    or _class_analysis_dual_bbox_pair_key_from_object_keys(
                        frozen_current_key,
                        frozen_other_key,
                    )
                    != frozen_pair_key
                ):
                    raise HTTPException(
                        status_code=HTTP_409_CONFLICT,
                        detail="dual_bbox_pair_identity_missing",
                    )
                # These identities were frozen into the server-owned analysis
                # artifact when the conflict was discovered. Deleting review
                # history must not reopen or hash a mutable source image merely
                # to rediscover the same pair.
                pair_review_key = frozen_pair_key
                current_review_object_key = frozen_current_key
            else:
                point = _class_analysis_backfill_review_object_key(job, point)
                (
                    _trusted_conflict,
                    pair_review_key,
                    current_review_object_key,
                    _other_review_object_key,
                ) = _class_analysis_validated_dual_bbox_conflict(
                    job,
                    point,
                    {
                        "dual_bbox_conflict": raw_entry.get(
                            "dual_bbox_conflict"
                        )
                    },
                )
        elif re.fullmatch(
            r"cro_[0-9a-f]{64}", current_review_object_key
        ) is None:
            point = _class_analysis_backfill_review_object_key(job, point)
            current_review_object_key = str(
                point.get("review_object_key") or ""
            ).strip()
        review_object_key = pair_review_key or current_review_object_key
        if expected_disposition == "reassign_class":
            review_object_key = _class_analysis_review_reassignment_key(
                current_review_object_key,
                str(job.job_id or job_id or ""),
            )
        _class_analysis_review_disposition_shard(review_object_key)
        resolved_by_key[review_object_key].append(
            {
                "point_id": point_id,
                "current_review_object_key": current_review_object_key,
                "expected_disposition": expected_disposition,
                "expected_revision": expected_revision,
                "expected_reviewed_at": expected_reviewed_at,
            }
        )

    response_base = {
        "schema": CLASS_ANALYSIS_REVIEW_HISTORY_DELETE_SCHEMA,
        "job_id": str(job.job_id or job_id or ""),
        "client_action_id": client_action_id,
        "requested_point_count": len(raw_entries),
        "resolved_review_key_count": len(resolved_by_key),
        "labels_changed": False,
        "annotations_changed": False,
        "training_actions_deleted": 0,
        "qwen_audits_deleted": 0,
    }
    if not resolved_by_key:
        return {
            **response_base,
            "status": "nothing_to_delete",
            "deleted_count": 0,
            "absent_count": 0,
            "deleted_disposition_counts": {},
        }
    ledger_root = _class_analysis_review_disposition_root(
        create=False,
        strict=True,
    )
    if ledger_root is None:
        return {
            **response_base,
            "status": "nothing_to_delete",
            "deleted_count": 0,
            "absent_count": len(resolved_by_key),
            "deleted_disposition_counts": {},
        }

    keys_by_shard: Dict[str, List[str]] = defaultdict(list)
    for review_object_key in resolved_by_key:
        shard_id, _lock = _class_analysis_review_disposition_shard(
            review_object_key
        )
        keys_by_shard[shard_id].append(review_object_key)
    shard_ids = sorted(keys_by_shard)
    shard_payloads: Dict[str, Dict[str, Any]] = {}
    entries_to_delete: Dict[str, Dict[str, Any]] = {}
    absent_count = 0
    stale_point_ids: Set[str] = set()

    with ExitStack() as locks:
        for shard_id in shard_ids:
            locks.enter_context(
                CLASS_ANALYSIS_REVIEW_DISPOSITION_LOCKS[int(shard_id, 16)]
            )
        for shard_id in shard_ids:
            locks.enter_context(
                _class_analysis_review_disposition_file_lock(
                    ledger_root,
                    shard_id,
                )
            )
        for shard_id in shard_ids:
            shard_payloads[shard_id] = (
                _class_analysis_load_review_disposition_shard(
                    ledger_root,
                    shard_id,
                    strict=True,
                )
            )
        for shard_id, review_object_keys in keys_by_shard.items():
            stored_entries = shard_payloads[shard_id]["entries"]
            for review_object_key in review_object_keys:
                if review_object_key not in stored_entries:
                    absent_count += 1
                    continue
                stored = stored_entries.get(review_object_key)
                (
                    stored_disposition,
                    stored_reviewed_at,
                    stored_revision,
                    pair_resolution,
                ) = _class_analysis_validated_review_disposition_entry(
                    review_object_key,
                    stored,
                )
                original_other_key = str(
                    pair_resolution.get("other_review_object_key") or ""
                ).strip()
                for requested in resolved_by_key[review_object_key]:
                    effective_disposition = stored_disposition
                    if (
                        review_object_key.startswith("crp_")
                        and requested["current_review_object_key"]
                        == original_other_key
                    ):
                        effective_disposition = {
                            "delete_current_box": "delete_overlapping_box",
                            "delete_overlapping_box": "delete_current_box",
                        }.get(stored_disposition, stored_disposition)
                    if (
                        effective_disposition
                        != requested["expected_disposition"]
                        or (
                            requested["expected_revision"]
                            and stored_revision
                            != requested["expected_revision"]
                        )
                        or (
                            not requested["expected_revision"]
                            and (
                                bool(stored_revision)
                                or stored_reviewed_at
                                != requested["expected_reviewed_at"]
                            )
                        )
                    ):
                        stale_point_ids.add(requested["point_id"])
                entries_to_delete[review_object_key] = stored
        if stale_point_ids:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail={
                    "code": "review_history_changed",
                    "point_ids": sorted(stale_point_ids),
                },
            )
        deleted_counts: Counter = Counter()
        changed_shards: Set[str] = {
            _class_analysis_review_disposition_shard(review_object_key)[0]
            for review_object_key in entries_to_delete
        }
        original_shard_bytes = {
            shard_id: _class_analysis_read_review_disposition_shard_bytes(
                ledger_root,
                shard_id,
            )
            for shard_id in sorted(changed_shards)
        }
        updated_at = time.time()
        for review_object_key, stored in entries_to_delete.items():
            shard_id, _lock = _class_analysis_review_disposition_shard(
                review_object_key
            )
            removed = shard_payloads[shard_id]["entries"].pop(
                review_object_key,
                None,
            )
            if isinstance(removed, dict):
                _class_analysis_tombstone_review_action(
                    shard_payloads[shard_id],
                    removed,
                    reason="review_history_deleted",
                    deleted_by_client_action_id=client_action_id,
                    deleted_at=updated_at,
                )
                deleted_counts[str(removed.get("disposition") or "")] += 1
        try:
            for shard_id in sorted(changed_shards):
                shard_payloads[shard_id]["updated_at"] = updated_at
                _class_analysis_write_audit_json(
                    ledger_root / f"{shard_id}.json",
                    ledger_root,
                    shard_payloads[shard_id],
                    detail="review_disposition_ledger_unavailable",
                )
        except Exception as write_error:
            rollback_errors: List[str] = []
            for shard_id in sorted(changed_shards, reverse=True):
                original = original_shard_bytes[shard_id]
                try:
                    current = _class_analysis_read_review_disposition_shard_bytes(
                        ledger_root,
                        shard_id,
                    )
                except Exception:
                    current = b""
                if current == original:
                    continue
                try:
                    _class_analysis_restore_review_disposition_shard_bytes(
                        ledger_root,
                        shard_id,
                        original,
                    )
                    restored = _class_analysis_read_review_disposition_shard_bytes(
                        ledger_root,
                        shard_id,
                    )
                    if restored != original:
                        raise RuntimeError("review history rollback verification failed")
                except Exception as rollback_error:
                    rollback_errors.append(
                        f"{shard_id}:{type(rollback_error).__name__}"
                    )
            if rollback_errors:
                logger.critical(
                    "Class-analysis review-history rollback failed after a "
                    "shard write error: %s",
                    ",".join(rollback_errors),
                )
                raise HTTPException(
                    status_code=HTTP_500_INTERNAL_SERVER_ERROR,
                    detail={
                        "code": "review_history_delete_rollback_failed",
                        "shards": rollback_errors,
                    },
                ) from write_error
            raise

    deleted_count = sum(deleted_counts.values())
    if deleted_count:
        for review_object_key in entries_to_delete:
            for resolved in resolved_by_key.get(review_object_key) or []:
                _class_analysis_sync_review_receipt_to_session(
                    str(job.job_id or job_id or ""),
                    str(resolved.get("point_id") or ""),
                    {
                        "disposition": "clear",
                        "review_object_key": review_object_key,
                    },
                )
    return {
        **response_base,
        "status": "deleted" if deleted_count else "nothing_to_delete",
        "deleted_count": deleted_count,
        "absent_count": absent_count,
        "deleted_disposition_counts": dict(sorted(deleted_counts.items())),
    }


def _class_analysis_write_binary(
    path: Path,
    root: Path,
    writer: Callable[[Any], None],
    *,
    detail: str = "class_analysis_write_path_forbidden",
) -> Path:
    _write_binary_within_root_atomic(
        path,
        root,
        writer,
        detail=detail,
        context="class analysis",
    )
    return path


def _class_analysis_write_npy(path: Path, root: Path, value: np.ndarray) -> Path:
    return _class_analysis_write_binary(
        path,
        root,
        lambda handle: np.save(handle, value),
    )


def _class_analysis_write_npz(path: Path, root: Path, **arrays: Any) -> Path:
    return _class_analysis_write_binary(
        path,
        root,
        lambda handle: np.savez_compressed(handle, **arrays),
    )


@contextmanager
def _class_analysis_open_regular_binary_nofollow(
    path: Path,
) -> Iterator[Tuple[Any, os.stat_result]]:
    """Open one already root-checked artifact without following a leaf link."""

    flags = os.O_RDONLY
    if hasattr(os, "O_CLOEXEC"):
        flags |= os.O_CLOEXEC
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = os.open(Path(path), flags)
    try:
        opened_stat = os.fstat(fd)
        if not stat.S_ISREG(opened_stat.st_mode):
            raise ValueError("class_analysis_artifact_not_regular")
        with os.fdopen(fd, "rb") as handle:
            fd = -1
            yield handle, opened_stat
    finally:
        if fd >= 0:
            os.close(fd)


def _class_analysis_binary_handle_sha256(handle: Any) -> str:
    """Hash a seekable handle and restore it to the start."""

    handle.seek(0)
    digest = hashlib.sha256()
    while True:
        chunk = handle.read(1024 * 1024)
        if not chunk:
            break
        digest.update(chunk)
    handle.seek(0)
    return digest.hexdigest()


def _class_analysis_artifact_stat_identity(
    stat_result: os.stat_result,
) -> Dict[str, int]:
    """Return the leaf identity needed to detect an atomic path replacement."""

    return {
        "device": int(stat_result.st_dev),
        "inode": int(stat_result.st_ino),
        "size": int(stat_result.st_size),
        "mtime_ns": int(stat_result.st_mtime_ns),
        "ctime_ns": int(stat_result.st_ctime_ns),
    }


def _class_analysis_require_snapshot_path_unchanged(
    path: Path,
    snapshot: Mapping[str, Any],
    *,
    detail: str,
) -> None:
    """Require ``path`` to still name the inode captured by a file snapshot.

    Parsing and hashing one open descriptor protects the bytes being validated,
    but an atomic replacement can make that descriptor stale before the caller
    publishes or restores the job.  Re-open the current leaf without following
    links and compare its identity to close that validation/publication window.
    Bound result reads still verify their digest from one descriptor, so a
    replacement after this check cannot be served as validated content.
    """

    expected = snapshot.get("file_identity")
    if not isinstance(expected, Mapping):
        # Streaming writer snapshots carry an exact payload digest but no open
        # descriptor identity.  Restart snapshots always include this field.
        return
    try:
        expected_identity = {
            field: int(expected.get(field))
            for field in ("device", "inode", "size", "mtime_ns", "ctime_ns")
        }
    except (TypeError, ValueError):
        raise ValueError(f"{detail}_snapshot_identity_invalid") from None
    with _class_analysis_open_regular_binary_nofollow(path) as (
        _handle,
        current_stat,
    ):
        current_identity = _class_analysis_artifact_stat_identity(current_stat)
    if current_identity != expected_identity:
        raise ValueError(f"{detail}_artifact_changed")


def _class_analysis_binary_artifact_snapshot(
    path: Path,
    *,
    count_jsonl_rows: bool = False,
) -> Dict[str, Any]:
    """Return one no-follow, single-inode digest/size snapshot."""

    with _class_analysis_open_regular_binary_nofollow(path) as (
        handle,
        opened_stat,
    ):
        digest = hashlib.sha256()
        byte_count = 0
        row_count = 0
        final_byte = b""
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
            byte_count += len(chunk)
            if count_jsonl_rows:
                row_count += chunk.count(b"\n")
                final_byte = chunk[-1:]
        if byte_count != int(opened_stat.st_size):
            raise ValueError("class_analysis_artifact_size_changed")
        if count_jsonl_rows and byte_count and final_byte != b"\n":
            raise ValueError("class_analysis_metadata_framing_invalid")
        final_stat = os.fstat(handle.fileno())
        if _class_analysis_artifact_stat_identity(
            final_stat
        ) != _class_analysis_artifact_stat_identity(opened_stat):
            raise ValueError("class_analysis_artifact_changed")
        snapshot = {
            "sha256": digest.hexdigest(),
            "bytes": byte_count,
            "file_identity": _class_analysis_artifact_stat_identity(
                opened_stat
            ),
        }
        if count_jsonl_rows:
            snapshot["row_count"] = row_count
        return snapshot


def _class_analysis_json_artifact_snapshot(path: Path) -> Dict[str, Any]:
    """Parse JSON and hash the same no-follow file descriptor."""

    with _class_analysis_open_regular_binary_nofollow(path) as (
        handle,
        opened_stat,
    ):
        sha256 = _class_analysis_binary_handle_sha256(handle)
        text_handle = io.TextIOWrapper(handle, encoding="utf-8")
        try:
            payload = json.load(text_handle)
        finally:
            # The outer context owns the binary handle.
            text_handle.detach()
        final_stat = os.fstat(handle.fileno())
        if (
            int(final_stat.st_dev),
            int(final_stat.st_ino),
            int(final_stat.st_size),
            int(final_stat.st_mtime_ns),
            int(final_stat.st_ctime_ns),
        ) != (
            int(opened_stat.st_dev),
            int(opened_stat.st_ino),
            int(opened_stat.st_size),
            int(opened_stat.st_mtime_ns),
            int(opened_stat.st_ctime_ns),
        ):
            raise ValueError("class_analysis_json_artifact_changed")
        if not isinstance(payload, dict):
            raise ValueError("class_analysis_json_artifact_invalid")
        return {
            "payload": payload,
            "sha256": sha256,
            "bytes": int(opened_stat.st_size),
            "file_identity": _class_analysis_artifact_stat_identity(
                opened_stat
            ),
        }


def _class_analysis_bound_artifact_identity(
    job: "ClassAnalysisJob",
    path: Path,
    artifact_name: str,
) -> Optional[Dict[str, int]]:
    """Return the private identity for one modern terminal-bound artifact.

    File hashes and byte counts stay in the portable terminal marker. Device,
    inode and timestamp identity is captured again while that marker is
    validated and kept only in the in-process job object. This makes repeated
    point reads O(1) without treating an atomic pathname replacement as the
    artifact that was validated at startup.
    """

    binding = (
        job._artifact_binding
        if isinstance(job._artifact_binding, Mapping)
        else {}
    )
    terminal_bound = bool(str(binding.get("result_file") or "").strip())
    expected_file = str(
        binding.get(f"{artifact_name}_file") or ""
    ).strip()
    if not expected_file:
        if terminal_bound:
            raise ValueError(
                f"class_analysis_{artifact_name}_binding_missing"
            )
        return None
    if Path(path).name != expected_file:
        raise ValueError(
            f"class_analysis_{artifact_name}_binding_path_mismatch"
        )
    raw_identities = binding.get("_file_identities")
    raw_identity = (
        raw_identities.get(artifact_name)
        if isinstance(raw_identities, Mapping)
        else None
    )
    if not isinstance(raw_identity, Mapping):
        raise ValueError(
            f"class_analysis_{artifact_name}_binding_identity_missing"
        )
    try:
        identity = {
            field: int(raw_identity[field])
            for field in (
                "device",
                "inode",
                "size",
                "mtime_ns",
                "ctime_ns",
            )
        }
        expected_bytes = binding.get(f"{artifact_name}_bytes")
        if (
            isinstance(expected_bytes, bool)
            or not isinstance(expected_bytes, int)
            or int(expected_bytes) < 0
            or identity["size"] != int(expected_bytes)
        ):
            raise ValueError
    except (KeyError, TypeError, ValueError):
        raise ValueError(
            f"class_analysis_{artifact_name}_binding_identity_invalid"
        ) from None
    return identity


@contextmanager
def _class_analysis_open_job_bound_artifact(
    job: "ClassAnalysisJob",
    path: Path,
    artifact_name: str,
) -> Iterator[Tuple[Any, os.stat_result]]:
    """Open a terminal artifact and bind the read to its validated inode."""

    expected_identity = _class_analysis_bound_artifact_identity(
        job,
        path,
        artifact_name,
    )
    with _class_analysis_open_regular_binary_nofollow(path) as (
        handle,
        opened_stat,
    ):
        opened_identity = _class_analysis_artifact_stat_identity(opened_stat)
        if (
            expected_identity is not None
            and opened_identity != expected_identity
        ):
            raise ValueError(
                f"class_analysis_{artifact_name}_artifact_changed"
            )
        yield handle, opened_stat
        final_identity = _class_analysis_artifact_stat_identity(
            os.fstat(handle.fileno())
        )
        if final_identity != opened_identity or (
            expected_identity is not None
            and final_identity != expected_identity
        ):
            raise ValueError(
                f"class_analysis_{artifact_name}_artifact_changed"
            )


def _class_analysis_require_bound_artifact_snapshot(
    job: "ClassAnalysisJob",
    path: Path,
    artifact_name: str,
    snapshot: Mapping[str, Any],
) -> None:
    """Match one same-descriptor snapshot to the terminal and private binds."""

    expected_identity = _class_analysis_bound_artifact_identity(
        job,
        path,
        artifact_name,
    )
    if expected_identity is None:
        return
    snapshot_identity = snapshot.get("file_identity")
    if not isinstance(snapshot_identity, Mapping):
        raise ValueError(
            f"class_analysis_{artifact_name}_snapshot_identity_missing"
        )
    try:
        observed_identity = {
            field: int(snapshot_identity[field])
            for field in expected_identity
        }
    except (KeyError, TypeError, ValueError):
        raise ValueError(
            f"class_analysis_{artifact_name}_snapshot_identity_invalid"
        ) from None
    expected_sha256 = str(
        job._artifact_binding.get(f"{artifact_name}_sha256") or ""
    ).strip().lower()
    if (
        observed_identity != expected_identity
        or str(snapshot.get("sha256") or "").strip().lower()
        != expected_sha256
        or int(snapshot.get("bytes") or 0) != expected_identity["size"]
    ):
        raise ValueError(
            f"class_analysis_{artifact_name}_artifact_changed"
        )
    _class_analysis_require_snapshot_path_unchanged(
        path,
        snapshot,
        detail=f"class_analysis_{artifact_name}",
    )


def _class_analysis_preflight_npy_header(
    handle: Any,
    *,
    max_array_bytes: int,
) -> Dict[str, Any]:
    """Validate one standalone NPY header without allocating its array."""

    if max_array_bytes <= 0:
        raise ValueError("class_analysis_npy_limit_invalid")
    handle.seek(0)
    try:
        version = np.lib.format.read_magic(handle)
        if version == (1, 0):
            shape, fortran_order, dtype = np.lib.format.read_array_header_1_0(
                handle,
                max_header_size=CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES,
            )
        elif version == (2, 0):
            shape, fortran_order, dtype = np.lib.format.read_array_header_2_0(
                handle,
                max_header_size=CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES,
            )
        elif version == (3, 0):
            shape, fortran_order, dtype = (
                np.lib.format._read_array_header(  # type: ignore[attr-defined]
                    handle,
                    version,
                    max_header_size=CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES,
                )
            )
        else:
            raise ValueError("class_analysis_npy_version_invalid")
        dtype = np.dtype(dtype)
        normalized_shape = tuple(int(size) for size in shape)
        if (
            any(size < 0 for size in normalized_shape)
            or bool(fortran_order)
            or dtype.hasobject
            or dtype.fields is not None
            or int(dtype.itemsize) <= 0
        ):
            raise ValueError("class_analysis_npy_header_unsafe")
        element_count = 1
        for dimension in normalized_shape:
            if dimension > max_array_bytes:
                raise ValueError("class_analysis_npy_dimension_too_large")
            if dimension and element_count > (
                max_array_bytes // int(dtype.itemsize) // dimension
            ):
                raise ValueError("class_analysis_npy_declared_array_too_large")
            element_count *= dimension
        declared_bytes = element_count * int(dtype.itemsize)
        if declared_bytes > max_array_bytes:
            raise ValueError("class_analysis_npy_declared_array_too_large")
        data_offset = int(handle.tell())
        opened_stat = os.fstat(handle.fileno())
        if data_offset + declared_bytes != int(opened_stat.st_size):
            raise ValueError("class_analysis_npy_file_size_mismatch")
        return {
            "shape": normalized_shape,
            "dtype": dtype,
            "declared_bytes": declared_bytes,
            "data_offset": data_offset,
        }
    finally:
        handle.seek(0)


def _class_analysis_remove_disposable_if_same_inode(
    path: Path,
    opened_identity: Optional[Tuple[int, int]],
) -> None:
    """Remove only the invalid cache inode that this process inspected."""

    if opened_identity is None:
        return
    try:
        current_stat = os.stat(path, follow_symlinks=False)
        if (
            stat.S_ISREG(current_stat.st_mode)
            and (int(current_stat.st_dev), int(current_stat.st_ino))
            == opened_identity
        ):
            path.unlink(missing_ok=True)
    except OSError:
        return


def _class_analysis_array_all_finite_chunked(
    value: np.ndarray,
    *,
    chunk_bytes: int = 4 * 1024 * 1024,
) -> bool:
    """Check finiteness with bounded temporary boolean allocations."""

    array = np.asarray(value)
    if array.size == 0:
        return True
    if array.ndim == 0:
        return bool(np.isfinite(array).item())
    trailing_elements = 1
    for dimension in array.shape[1:]:
        trailing_elements *= max(1, int(dimension))
    bytes_per_row = max(1, trailing_elements * int(array.dtype.itemsize))
    rows_per_chunk = max(1, int(chunk_bytes) // bytes_per_row)
    for start in range(0, int(array.shape[0]), rows_per_chunk):
        if not bool(np.isfinite(array[start : start + rows_per_chunk]).all()):
            return False
    return True


def _class_analysis_preflight_npz_headers(
    handle: Any,
    *,
    expected_arrays: Mapping[str, Mapping[str, Any]],
    max_array_bytes: int,
    max_total_bytes: int,
) -> Dict[str, Dict[str, Any]]:
    """Validate every embedded NPY header before ``np.load`` may allocate.

    The caller keeps ``handle`` open and passes that same handle to
    ``np.load`` after this check.  Besides closing the small-archive/huge-shape
    allocation path, this avoids a path-swap window between preflight and
    materialization.
    """

    if max_array_bytes <= 0 or max_total_bytes <= 0:
        raise ValueError("class_analysis_npz_limit_invalid")
    expected_names = {str(name) for name in expected_arrays}
    if not expected_names or any(not name for name in expected_names):
        raise ValueError("class_analysis_npz_contract_invalid")
    expected_members = {f"{name}.npy" for name in expected_names}
    headers: Dict[str, Dict[str, Any]] = {}
    total_data_bytes = 0
    handle.seek(0)
    try:
        with zipfile.ZipFile(handle, "r") as archive:
            infos = archive.infolist()
            member_names = [info.filename for info in infos]
            if (
                len(member_names) != len(set(member_names))
                or set(member_names) != expected_members
            ):
                raise ValueError("class_analysis_npz_member_set_invalid")
            if any(
                info.is_dir()
                or bool(info.flag_bits & 0x1)
                or int(info.file_size) < 0
                for info in infos
            ):
                raise ValueError("class_analysis_npz_member_invalid")
            maximum_archive_bytes = max_total_bytes + (
                len(infos) * CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES
            )
            if sum(int(info.file_size) for info in infos) > maximum_archive_bytes:
                raise ValueError("class_analysis_npz_archive_too_large")

            for array_name in sorted(expected_names):
                member_name = f"{array_name}.npy"
                info = archive.getinfo(member_name)
                if int(info.file_size) > (
                    max_array_bytes + CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES
                ):
                    raise ValueError(
                        f"class_analysis_npz_member_too_large:{array_name}"
                    )
                with archive.open(info, "r") as member:
                    version = np.lib.format.read_magic(member)
                    if version == (1, 0):
                        shape, fortran_order, dtype = (
                            np.lib.format.read_array_header_1_0(
                                member,
                                max_header_size=(
                                    CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES
                                ),
                            )
                        )
                    elif version == (2, 0):
                        shape, fortran_order, dtype = (
                            np.lib.format.read_array_header_2_0(
                                member,
                                max_header_size=(
                                    CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES
                                ),
                            )
                        )
                    elif version == (3, 0):
                        shape, fortran_order, dtype = (
                            np.lib.format._read_array_header(  # type: ignore[attr-defined]
                                member,
                                version,
                                max_header_size=(
                                    CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES
                                ),
                            )
                        )
                    else:
                        raise ValueError(
                            f"class_analysis_npz_version_invalid:{array_name}"
                        )
                    dtype = np.dtype(dtype)
                    normalized_shape = tuple(int(size) for size in shape)
                    if (
                        any(size < 0 for size in normalized_shape)
                        or bool(fortran_order)
                        or dtype.hasobject
                        or dtype.fields is not None
                        or int(dtype.itemsize) <= 0
                    ):
                        raise ValueError(
                            f"class_analysis_npz_header_unsafe:{array_name}"
                        )
                    element_count = 1
                    for dimension in normalized_shape:
                        if dimension > max_array_bytes:
                            raise ValueError(
                                "class_analysis_npz_dimension_too_large:"
                                f"{array_name}"
                            )
                        if dimension and element_count > (
                            max_array_bytes // int(dtype.itemsize) // dimension
                        ):
                            raise ValueError(
                                "class_analysis_npz_declared_array_too_large:"
                                f"{array_name}"
                            )
                        element_count *= dimension
                    declared_bytes = element_count * int(dtype.itemsize)
                    if declared_bytes > max_array_bytes:
                        raise ValueError(
                            "class_analysis_npz_declared_array_too_large:"
                            f"{array_name}"
                        )
                    total_data_bytes += declared_bytes
                    if total_data_bytes > max_total_bytes:
                        raise ValueError(
                            "class_analysis_npz_declared_total_too_large"
                        )
                    if int(member.tell()) + declared_bytes != int(info.file_size):
                        raise ValueError(
                            f"class_analysis_npz_member_size_mismatch:{array_name}"
                        )

                    expected = expected_arrays.get(array_name)
                    if not isinstance(expected, Mapping):
                        raise ValueError(
                            f"class_analysis_npz_contract_invalid:{array_name}"
                        )
                    if "shape" in expected:
                        try:
                            expected_shape = tuple(
                                int(size) for size in expected.get("shape")
                            )
                        except (TypeError, ValueError):
                            raise ValueError(
                                "class_analysis_npz_contract_shape_invalid:"
                                f"{array_name}"
                            )
                        if normalized_shape != expected_shape:
                            raise ValueError(
                                "class_analysis_npz_header_shape_mismatch:"
                                f"{array_name}"
                            )
                    if "dtype" in expected:
                        try:
                            expected_dtype = np.dtype(expected.get("dtype"))
                        except (TypeError, ValueError):
                            raise ValueError(
                                "class_analysis_npz_contract_dtype_invalid:"
                                f"{array_name}"
                            )
                        if dtype != expected_dtype:
                            raise ValueError(
                                "class_analysis_npz_header_dtype_mismatch:"
                                f"{array_name}"
                            )
                    headers[array_name] = {
                        "shape": normalized_shape,
                        "dtype": dtype,
                        "declared_bytes": declared_bytes,
                    }
    except (zipfile.BadZipFile, zipfile.LargeZipFile) as exc:
        raise ValueError("class_analysis_npz_archive_invalid") from exc
    finally:
        handle.seek(0)
    return headers


def _class_analysis_projection_contract(
    result: Mapping[str, Any],
) -> Tuple[List[str], int, bool]:
    """Return the exact public projection member/row contract.

    The boolean distinguishes a modern result that explicitly advertises its
    available coordinate arrays from the narrow legacy format whose only
    coordinates live on each point record.
    """

    projection_options = (
        result.get("projection_options")
        if isinstance(result.get("projection_options"), Mapping)
        else {}
    )
    coordinates_advertised = "coordinates_available" in projection_options
    raw_projection_modes = projection_options.get("coordinates_available")
    if raw_projection_modes in (None, ""):
        projection_modes: List[str] = []
    elif isinstance(raw_projection_modes, list):
        projection_modes = [
            str(value or "").strip() for value in raw_projection_modes
        ]
    else:
        raise ValueError("class_analysis_projection_contract_invalid")
    if (
        any(
            mode not in CLASS_ANALYSIS_PCA_PROJECTION_MODES
            for mode in projection_modes
        )
        or len(set(projection_modes)) != len(projection_modes)
    ):
        raise ValueError("class_analysis_projection_contract_invalid")
    points = result.get("points")
    points_storage = result.get("points_storage")
    if isinstance(points, list):
        row_count = len(points)
    elif (
        isinstance(points_storage, Mapping)
        and str(points_storage.get("schema") or "")
        == "class-analysis-points-sqlite-v1"
        and not isinstance(points_storage.get("row_count"), bool)
        and isinstance(points_storage.get("row_count"), int)
        and int(points_storage.get("row_count") or 0) >= 0
    ):
        row_count = int(points_storage.get("row_count") or 0)
    else:
        raise ValueError("class_analysis_projection_points_invalid")
    array_bytes = row_count * 2 * int(np.dtype(np.float32).itemsize)
    total_bytes = array_bytes * len(projection_modes)
    if (
        array_bytes > CLASS_ANALYSIS_PROJECTION_MAX_ARRAY_BYTES
        or total_bytes > CLASS_ANALYSIS_PROJECTION_MAX_TOTAL_BYTES
    ):
        raise ValueError("class_analysis_projection_contract_too_large")
    return projection_modes, row_count, coordinates_advertised


def _class_analysis_validated_projection_artifact(
    path: Path,
    *,
    result: Mapping[str, Any],
    load_mode: Optional[str] = None,
    expected_sha256: Optional[str] = None,
    expected_bytes: Optional[int] = None,
) -> Dict[str, Any]:
    """Hash, preflight, and validate a projection NPZ on one open inode.

    Each advertised member is exactly ``float32[len(points), 2]``.  The bounded
    NPY-header preflight runs before NumPy may allocate, members are finite, and
    the same no-follow descriptor is checked again after materialization.
    """

    projection_modes, row_count, _advertised = (
        _class_analysis_projection_contract(result)
    )
    if not projection_modes:
        raise ValueError("class_analysis_projection_artifact_unreferenced")
    if load_mode is not None and load_mode not in projection_modes:
        raise ValueError("class_analysis_projection_mode_unadvertised")

    array_bytes = row_count * 2 * int(np.dtype(np.float32).itemsize)
    total_bytes = array_bytes * len(projection_modes)
    expected_arrays = {
        mode: {
            "shape": (row_count, 2),
            "dtype": np.dtype(np.float32),
        }
        for mode in projection_modes
    }
    expected_sha = str(expected_sha256 or "").strip().lower()
    if expected_sha256 is not None and not re.fullmatch(
        r"[0-9a-f]{64}", expected_sha
    ):
        raise ValueError("class_analysis_projection_expected_hash_invalid")
    if expected_bytes is not None and (
        isinstance(expected_bytes, bool)
        or not isinstance(expected_bytes, int)
        or expected_bytes < 0
    ):
        raise ValueError("class_analysis_projection_expected_size_invalid")

    loaded_coordinates: Optional[np.ndarray] = None
    with _class_analysis_open_regular_binary_nofollow(path) as (
        handle,
        opened_stat,
    ):
        # A valid compressed archive cannot need materially more bytes than the
        # exact uncompressed arrays plus bounded NPY/ZIP framing.  Reject an
        # oversized leaf before spending unbounded time hashing it.
        maximum_file_bytes = (
            total_bytes
            + len(projection_modes) * CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES
            + 1024 * 1024
        )
        if int(opened_stat.st_size) > maximum_file_bytes:
            raise ValueError("class_analysis_projection_artifact_too_large")
        if expected_bytes is not None and int(opened_stat.st_size) != int(
            expected_bytes
        ):
            raise ValueError("class_analysis_projection_size_mismatch")

        sha256 = _class_analysis_binary_handle_sha256(handle)
        if expected_sha256 is not None and sha256 != expected_sha:
            raise ValueError("class_analysis_projection_hash_mismatch")
        _class_analysis_preflight_npz_headers(
            handle,
            expected_arrays=expected_arrays,
            max_array_bytes=CLASS_ANALYSIS_PROJECTION_MAX_ARRAY_BYTES,
            max_total_bytes=CLASS_ANALYSIS_PROJECTION_MAX_TOTAL_BYTES,
        )
        modes_to_load = [load_mode] if load_mode is not None else projection_modes
        with np.load(
            handle,
            allow_pickle=False,
            max_header_size=CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES,
        ) as payload:
            for mode in modes_to_load:
                array = np.asarray(payload[mode])
                if (
                    array.dtype != np.dtype(np.float32)
                    or array.shape != (row_count, 2)
                ):
                    raise ValueError(
                        "class_analysis_projection_array_contract_invalid:"
                        f"{mode}"
                    )
                for start in range(0, row_count, 65_536):
                    if not bool(
                        np.isfinite(array[start : start + 65_536]).all()
                    ):
                        raise ValueError(
                            "class_analysis_projection_nonfinite:"
                            f"{mode}"
                        )
                if load_mode is not None:
                    loaded_coordinates = np.array(array, copy=True)
                del array

        final_stat = os.fstat(handle.fileno())
        if (
            int(final_stat.st_dev),
            int(final_stat.st_ino),
            int(final_stat.st_size),
            int(final_stat.st_mtime_ns),
            int(final_stat.st_ctime_ns),
        ) != (
            int(opened_stat.st_dev),
            int(opened_stat.st_ino),
            int(opened_stat.st_size),
            int(opened_stat.st_mtime_ns),
            int(opened_stat.st_ctime_ns),
        ):
            raise ValueError("class_analysis_projection_artifact_changed")

    return {
        "sha256": sha256,
        "bytes": int(opened_stat.st_size),
        "file_identity": _class_analysis_artifact_stat_identity(
            opened_stat
        ),
        "coordinates": loaded_coordinates,
    }


def _class_analysis_write_jsonl(
    path: Path,
    root: Path,
    rows: Iterable[Mapping[str, Any]],
) -> Path:
    def writer(handle: Any) -> None:
        for row in rows:
            line = json.dumps(
                _class_analysis_json_safe(dict(row)),
                ensure_ascii=False,
                separators=(",", ":"),
            )
            handle.write((line + "\n").encode("utf-8"))

    return _class_analysis_write_binary(path, root, writer)


def _class_analysis_thumbnail_index_payload(
    metadata_path: Path,
    offsets: Mapping[str, int],
    *,
    metadata_stat: Optional[os.stat_result] = None,
) -> Dict[str, Any]:
    stat_result = metadata_stat or metadata_path.stat()
    return {
        "schema": CLASS_ANALYSIS_THUMBNAIL_INDEX_SCHEMA,
        "metadata_file": CLASS_ANALYSIS_METADATA_FILENAME,
        "metadata_size": int(stat_result.st_size),
        "metadata_mtime_ns": int(stat_result.st_mtime_ns),
        "point_count": len(offsets),
        "offsets": dict(offsets),
    }


def _class_analysis_write_indexed_metadata_jsonl(
    path: Path,
    root: Path,
    rows: Iterable[Mapping[str, Any]],
) -> Path:
    """Persist metadata plus a portable point-id-to-byte-offset sidecar."""

    offsets: Dict[str, int] = {}

    def writer(handle: Any) -> None:
        for row in rows:
            line_offset = int(handle.tell())
            row_payload = _class_analysis_json_safe(dict(row))
            raw_point_id = str(row_payload.get("point_id") or "")
            point_id = _class_analysis_safe_slug(raw_point_id, "")
            line = json.dumps(
                row_payload,
                ensure_ascii=False,
                separators=(",", ":"),
            )
            handle.write((line + "\n").encode("utf-8"))
            if point_id and point_id == raw_point_id:
                offsets.setdefault(point_id, line_offset)

    metadata_path = _class_analysis_write_binary(path, root, writer)
    index_payload = _class_analysis_thumbnail_index_payload(metadata_path, offsets)
    _class_analysis_write_text(
        metadata_path.parent / CLASS_ANALYSIS_THUMBNAIL_INDEX_FILENAME,
        root,
        json.dumps(index_payload, ensure_ascii=False, separators=(",", ":")),
    )
    return metadata_path


def _class_analysis_build_thumbnail_metadata_index(
    job_dir: Path,
) -> Optional[Dict[str, int]]:
    """Build an offset index from metadata.jsonl without materializing its rows."""

    metadata_path = _safe_existing_regular_file_within_root_impl(
        job_dir / CLASS_ANALYSIS_METADATA_FILENAME,
        job_dir,
    )
    if metadata_path is None:
        return None
    try:
        offsets: Dict[str, int] = {}
        with _class_analysis_open_regular_binary_nofollow(
            metadata_path
        ) as (handle, before):
            while True:
                line_offset = int(handle.tell())
                line = handle.readline(CLASS_ANALYSIS_THUMBNAIL_METADATA_MAX_LINE_BYTES + 1)
                if not line:
                    break
                if len(line) > CLASS_ANALYSIS_THUMBNAIL_METADATA_MAX_LINE_BYTES:
                    raise ValueError("class analysis metadata row is too large")
                try:
                    row = json.loads(line)
                except Exception:
                    continue
                if not isinstance(row, dict):
                    continue
                raw_point_id = str(row.get("point_id") or "")
                point_id = _class_analysis_safe_slug(raw_point_id, "")
                if point_id and point_id == raw_point_id:
                    offsets.setdefault(point_id, line_offset)
            after = os.fstat(handle.fileno())
            if _class_analysis_artifact_stat_identity(
                before
            ) != _class_analysis_artifact_stat_identity(after):
                return None
        _class_analysis_require_snapshot_path_unchanged(
            metadata_path,
            {
                "file_identity": _class_analysis_artifact_stat_identity(
                    after
                )
            },
            detail="class_analysis_metadata_index",
        )
        index_payload = _class_analysis_thumbnail_index_payload(
            metadata_path,
            offsets,
            metadata_stat=after,
        )
        _class_analysis_write_text(
            job_dir / CLASS_ANALYSIS_THUMBNAIL_INDEX_FILENAME,
            job_dir,
            json.dumps(index_payload, ensure_ascii=False, separators=(",", ":")),
        )
        return offsets
    except Exception as exc:
        logger.warning(
            "Failed to build class analysis thumbnail index for %s: %s",
            job_dir.name,
            exc,
        )
        return None


def _class_analysis_load_thumbnail_metadata_index(
    job_dir: Path,
) -> Optional[Dict[str, int]]:
    metadata_path = _safe_existing_regular_file_within_root_impl(
        job_dir / CLASS_ANALYSIS_METADATA_FILENAME,
        job_dir,
    )
    index_path = _safe_existing_regular_file_within_root_impl(
        job_dir / CLASS_ANALYSIS_THUMBNAIL_INDEX_FILENAME,
        job_dir,
    )
    if metadata_path is None or index_path is None:
        return None
    try:
        with _class_analysis_open_regular_binary_nofollow(
            index_path
        ) as (index_handle, index_stat):
            index_size = int(index_stat.st_size)
            if (
                index_size <= 0
                or index_size > CLASS_ANALYSIS_THUMBNAIL_INDEX_MAX_BYTES
            ):
                return None
            text_handle = io.TextIOWrapper(index_handle, encoding="utf-8")
            try:
                payload = json.load(text_handle)
            finally:
                text_handle.detach()
            if _class_analysis_artifact_stat_identity(
                os.fstat(index_handle.fileno())
            ) != _class_analysis_artifact_stat_identity(index_stat):
                return None
        if not isinstance(payload, dict):
            return None
        if str(payload.get("schema") or "") != CLASS_ANALYSIS_THUMBNAIL_INDEX_SCHEMA:
            return None
        if str(payload.get("metadata_file") or "") != CLASS_ANALYSIS_METADATA_FILENAME:
            return None
        with _class_analysis_open_regular_binary_nofollow(
            metadata_path
        ) as (_handle, stat_result):
            pass
        if (
            int(payload.get("metadata_size") or -1) != int(stat_result.st_size)
            or int(payload.get("metadata_mtime_ns") or -1) != int(stat_result.st_mtime_ns)
        ):
            return None
        raw_offsets = payload.get("offsets")
        if not isinstance(raw_offsets, dict):
            return None
        point_count = payload.get("point_count")
        if (
            isinstance(point_count, bool)
            or not isinstance(point_count, int)
            or point_count < 0
            or point_count > CLASS_ANALYSIS_THUMBNAIL_INDEX_MAX_ENTRIES
            or len(raw_offsets) != point_count
        ):
            return None
        metadata_size = int(stat_result.st_size)
        offsets: Dict[str, int] = {}
        for raw_point_id, raw_offset in raw_offsets.items():
            point_id = _class_analysis_safe_slug(str(raw_point_id or ""), "")
            if (
                not point_id
                or point_id != str(raw_point_id)
                or isinstance(raw_offset, bool)
                or not isinstance(raw_offset, int)
                or raw_offset < 0
                or raw_offset >= metadata_size
            ):
                return None
            offsets[point_id] = int(raw_offset)
        if point_count != len(offsets):
            return None
        return offsets
    except Exception:
        return None


def _class_analysis_thumbnail_metadata_offsets(
    job: ClassAnalysisJob,
    job_dir: Path,
) -> Dict[str, int]:
    metadata_path = _safe_existing_regular_file_within_root_impl(
        job_dir / CLASS_ANALYSIS_METADATA_FILENAME,
        job_dir,
    )
    if metadata_path is None:
        return {}
    try:
        with _class_analysis_open_job_bound_artifact(
            job,
            metadata_path,
            "metadata",
        ) as (_handle, stat_result):
            identity = (
                int(stat_result.st_dev),
                int(stat_result.st_ino),
                int(stat_result.st_size),
                int(stat_result.st_mtime_ns),
                int(stat_result.st_ctime_ns),
            )
        cache_key = str(job_dir.resolve(strict=True))
    except Exception:
        return {}
    with CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE_LOCK:
        cached = CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE.get(cache_key)
        if cached is not None and cached[0] == identity:
            CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE.move_to_end(cache_key)
            return cached[1]
        if cached is not None:
            CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE.pop(cache_key, None)
    with job.thumbnail_metadata_lock:
        with CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE_LOCK:
            cached = CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE.get(cache_key)
            if cached is not None and cached[0] == identity:
                CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE.move_to_end(cache_key)
                return cached[1]
            if cached is not None:
                CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE.pop(cache_key, None)
        loaded = _class_analysis_load_thumbnail_metadata_index(job_dir)
        if loaded is None:
            loaded = _class_analysis_build_thumbnail_metadata_index(job_dir)
        if not isinstance(loaded, dict):
            # Do not make a transient read/build error permanent; a later
            # request may succeed after a concurrent atomic write completes.
            return {}
        with CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE_LOCK:
            CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE[cache_key] = (identity, loaded)
            CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE.move_to_end(cache_key)
            while (
                len(CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE)
                > CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE_JOBS
            ):
                CLASS_ANALYSIS_THUMBNAIL_INDEX_CACHE.popitem(last=False)
        return loaded


def _class_analysis_thumbnail_point_metadata(
    job: ClassAnalysisJob,
    job_dir: Path,
    point_id: str,
) -> Optional[Dict[str, Any]]:
    offsets = _class_analysis_thumbnail_metadata_offsets(job, job_dir)
    offset = offsets.get(point_id)
    if offset is None:
        return None
    metadata_path = _safe_existing_regular_file_within_root_impl(
        job_dir / CLASS_ANALYSIS_METADATA_FILENAME,
        job_dir,
    )
    if metadata_path is None:
        return None
    try:
        with _class_analysis_open_job_bound_artifact(
            job,
            metadata_path,
            "metadata",
        ) as (handle, opened_stat):
            if offset < 0 or offset >= int(opened_stat.st_size):
                return None
            handle.seek(offset)
            line = handle.readline(
                CLASS_ANALYSIS_THUMBNAIL_METADATA_MAX_LINE_BYTES + 1
            )
        if not line or len(line) > CLASS_ANALYSIS_THUMBNAIL_METADATA_MAX_LINE_BYTES:
            return None
        point = json.loads(line)
        if not isinstance(point, dict):
            return None
        if str(point.get("point_id") or "") != point_id:
            return None
        return point
    except Exception:
        return None


def _class_analysis_load_saved_embeddings(
    job_dir: Path,
    *,
    copy_on_write: bool = False,
) -> Tuple[Optional[np.ndarray], Optional[Path]]:
    npy_path = _safe_existing_regular_file_within_root_impl(
        job_dir / "embeddings.npy",
        job_dir,
    )
    if npy_path is not None:
        try:
            with _class_analysis_open_regular_binary_nofollow(npy_path) as (
                handle,
                opened_stat,
            ):
                if int(opened_stat.st_size) > (
                    CLASS_ANALYSIS_SAVED_NPY_MAX_BYTES
                    + CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES
                ):
                    raise ValueError("class_analysis_saved_embeddings_too_large")
                header = _class_analysis_preflight_npy_header(
                    handle,
                    max_array_bytes=CLASS_ANALYSIS_SAVED_NPY_MAX_BYTES,
                )
                if (
                    len(header["shape"]) != 2
                    or header["shape"][0] <= 0
                    or header["shape"][1] <= 0
                    or header["dtype"] != np.dtype(np.float32)
                ):
                    raise ValueError(
                        "class_analysis_saved_embeddings_contract_invalid"
                    )
                matrix = np.memmap(
                    handle,
                    dtype=header["dtype"],
                    # PyNNDescent's Numba kernels require an array with a
                    # writable type signature even though graph construction
                    # does not need to persist mutations. ``c`` is an
                    # OS-backed private mapping: writable to the process,
                    # immutable on disk, and it avoids a 1.5+ GiB eager copy.
                    mode="c" if copy_on_write else "r",
                    offset=int(header["data_offset"]),
                    shape=header["shape"],
                    order="C",
                )
                if not _class_analysis_array_all_finite_chunked(matrix):
                    raise ValueError(
                        "class_analysis_saved_embeddings_nonfinite"
                    )
                if _class_analysis_artifact_stat_identity(
                    os.fstat(handle.fileno())
                ) != _class_analysis_artifact_stat_identity(opened_stat):
                    raise ValueError("class_analysis_saved_embeddings_changed")
            return matrix, npy_path
        except Exception:
            return None, npy_path
    npz_path = _safe_existing_regular_file_within_root_impl(
        job_dir / "embeddings.npz",
        job_dir,
    )
    if npz_path is None:
        return None, None
    try:
        with _class_analysis_open_regular_binary_nofollow(npz_path) as (
            handle,
            opened_stat,
        ):
            if int(opened_stat.st_size) > (
                CLASS_ANALYSIS_SAVED_LEGACY_NPZ_MAX_BYTES
                + CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES
                + 1024 * 1024
            ):
                raise ValueError(
                    "class_analysis_saved_legacy_embeddings_too_large"
                )
            headers = _class_analysis_preflight_npz_headers(
                handle,
                expected_arrays={"embeddings": {}},
                max_array_bytes=(
                    CLASS_ANALYSIS_SAVED_LEGACY_NPZ_MAX_BYTES
                ),
                max_total_bytes=(
                    CLASS_ANALYSIS_SAVED_LEGACY_NPZ_MAX_BYTES
                ),
            )
            header = headers["embeddings"]
            if (
                len(header["shape"]) != 2
                or header["shape"][0] <= 0
                or header["shape"][1] <= 0
                or header["dtype"] != np.dtype(np.float32)
            ):
                raise ValueError(
                    "class_analysis_saved_legacy_embeddings_contract_invalid"
                )
            with np.load(
                handle,
                allow_pickle=False,
                max_header_size=CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES,
            ) as payload:
                matrix = np.asarray(payload["embeddings"])
            if (
                matrix.shape != header["shape"]
                or matrix.dtype != np.dtype(np.float32)
                or not _class_analysis_array_all_finite_chunked(matrix)
            ):
                raise ValueError(
                    "class_analysis_saved_legacy_embeddings_payload_invalid"
                )
            if _class_analysis_artifact_stat_identity(
                os.fstat(handle.fileno())
            ) != _class_analysis_artifact_stat_identity(opened_stat):
                raise ValueError(
                    "class_analysis_saved_legacy_embeddings_changed"
                )
        return matrix, npz_path
    except Exception:
        return None, npz_path


def _class_analysis_embedding_record_digest(
    records: Sequence[Mapping[str, Any]],
) -> str:
    """Bind a resumable matrix to the exact ordered object rows it encodes."""

    digest = hashlib.sha256()
    for row_index, record in enumerate(records):
        bbox = []
        for value in list(record.get("bbox_xyxy") or [])[:4]:
            try:
                bbox.append(float(value).hex())
            except (TypeError, ValueError):
                bbox.append("invalid")
        digest.update(
            json.dumps(
                {
                    "row": int(row_index),
                    "source_key": str(record.get("source_key") or ""),
                    "source_id": str(record.get("source_id") or ""),
                    "split": str(record.get("split") or ""),
                    "image_relpath": str(
                        record.get("image_relpath") or ""
                    ),
                    "image_sha256": str(
                        record.get("_image_sha256")
                        or record.get("image_sha256")
                        or ""
                    ).lower(),
                    "bbox_float64_hex": bbox,
                    "crop_cache_key": str(
                        record.get("crop_cache_key") or ""
                    ),
                },
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        )
        digest.update(b"\n")
    return digest.hexdigest()


def _class_analysis_embedding_recipe_digest(
    request: Mapping[str, Any],
    head: Mapping[str, Any],
) -> str:
    """Bind a resumable matrix to the effective encoder and crop recipe."""

    return _class_analysis_cache_digest(
        {
            "cache_version": CLASS_ANALYSIS_CACHE_VERSION,
            "encoder_identity": _class_analysis_embedding_head_cache_identity(
                head
            ),
            "crop_mode": str(request.get("crop_mode") or ""),
            "padding_ratio": float(request.get("padding_ratio") or 0.0),
            "preprocess_mode": str(request.get("preprocess_mode") or ""),
            "canonical_size": int(request.get("canonical_size") or 0),
            "background_mode": str(request.get("background_mode") or ""),
            "embedding_view_mode": str(
                request.get("embedding_view_mode") or ""
            ),
            "embedding_adjustment": str(
                request.get("embedding_adjustment") or ""
            ),
            "salad_settings": {
                key: head.get(key)
                for key in (
                    "salad_preset",
                    "salad_num_clusters",
                    "salad_cluster_dim",
                    "salad_token_dim",
                    "salad_hidden_dim",
                    "salad_dropout",
                    "salad_sinkhorn_iters",
                    "salad_sinkhorn_reg",
                    "salad_epochs",
                    "salad_batch_size",
                    "salad_max_train_objects",
                    "salad_token_budget_mb",
                    "salad_weight",
                    "salad_learning_rate",
                    "salad_weight_decay",
                    "salad_temperature",
                    "embedding_salad_training_fingerprint",
                )
                if head.get(key) is not None
            },
        }
    )


def _class_analysis_stage1_embedding_fingerprint(
    records: Sequence[Mapping[str, Any]],
    request: Mapping[str, Any],
    head: Mapping[str, Any],
) -> str:
    """Return the refinement-independent identity of the Stage-1 matrix.

    The ordered record digest and effective encoder/crop recipe are the full
    inputs to this adjusted embedding matrix.  Graph projection, neighbor
    settings, and V2/V3 refinement contracts operate downstream and must not
    force an expensive re-encode.
    """

    return _class_analysis_cache_digest(
        {
            "schema": CLASS_ANALYSIS_STAGE1_EMBEDDING_FINGERPRINT_SCHEMA,
            "record_digest": _class_analysis_embedding_record_digest(records),
            "recipe_digest": _class_analysis_embedding_recipe_digest(
                request,
                head,
            ),
        }
    )


def _class_analysis_resume_checkpoint_dir(
    checkpoint_fingerprint: str,
    *,
    create: bool,
) -> Optional[Path]:
    clean_fingerprint = str(checkpoint_fingerprint or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", clean_fingerprint):
        return None
    cache_root = _class_analysis_cache_storage_root(create=create)
    if cache_root is None:
        return None
    checkpoint_root = cache_root / CLASS_ANALYSIS_RESUME_CHECKPOINT_DIRNAME
    shard_root = checkpoint_root / clean_fingerprint[:2]
    checkpoint_dir = shard_root / clean_fingerprint
    if create:
        for directory in (checkpoint_root, shard_root, checkpoint_dir):
            if _class_analysis_prepare_dir(directory, cache_root) is None:
                return None
    elif (
        not checkpoint_dir.is_dir()
        or checkpoint_dir.is_symlink()
        or not _path_is_within_root_impl(
            checkpoint_dir.resolve(strict=False), cache_root
        )
    ):
        return None
    return checkpoint_dir.resolve(strict=False)


def _class_analysis_link_checkpoint_artifact(
    source_path: Path,
    target_path: Path,
    *,
    root: Path,
) -> Path:
    """Atomically materialize one immutable NPY, preferring a hard link."""

    safe_source = _safe_existing_regular_file_within_root_impl(
        source_path,
        source_path.parent,
    )
    safe_target = _class_analysis_prepare_write_path(target_path, root)
    if safe_source is None or safe_target is None:
        raise ValueError("class_analysis_embedding_checkpoint_path_invalid")
    temporary = _class_analysis_prepare_write_path(
        safe_target.with_name(
            f".{safe_target.name}.{uuid.uuid4().hex}.tmp"
        ),
        root,
    )
    if temporary is None:
        raise ValueError("class_analysis_embedding_checkpoint_path_invalid")
    try:
        try:
            os.link(
                safe_source,
                temporary,
                follow_symlinks=False,
            )
        except OSError:
            shutil.copyfile(safe_source, temporary, follow_symlinks=False)
        os.replace(temporary, safe_target)
        # Cache eviction is mtime-based. A new hard-linked checkpoint must be
        # treated as newly used rather than inheriting the job artifact's age.
        os.utime(safe_target, None, follow_symlinks=False)
        return safe_target
    finally:
        try:
            temporary.unlink(missing_ok=True)
        except OSError:
            pass


def _class_analysis_publish_embedding_checkpoint(
    *,
    embeddings_path: Path,
    embeddings: np.ndarray,
    records: Sequence[Mapping[str, Any]],
    request: Mapping[str, Any],
    head: Mapping[str, Any],
    adjustment_info: Mapping[str, Any],
) -> Optional[Dict[str, Any]]:
    """Publish a restart-safe, fingerprint-bound Stage-1 checkpoint."""

    run_fingerprint = str(request.get("run_fingerprint") or "").lower()
    embedding_fingerprint = _class_analysis_stage1_embedding_fingerprint(
        records,
        request,
        head,
    )
    checkpoint_dir = _class_analysis_resume_checkpoint_dir(
        embedding_fingerprint,
        create=True,
    )
    if checkpoint_dir is None:
        return None
    array = np.asarray(embeddings)
    if (
        array.ndim != 2
        or array.shape[0] != len(records)
        or array.shape[0] <= 0
        or array.shape[1] <= 0
        or array.dtype != np.dtype(np.float32)
    ):
        raise ValueError("class_analysis_embedding_checkpoint_shape_invalid")
    source_snapshot = _class_analysis_binary_artifact_snapshot(
        embeddings_path
    )
    checkpoint_path = _class_analysis_link_checkpoint_artifact(
        embeddings_path,
        checkpoint_dir / "embeddings.npy",
        root=checkpoint_dir,
    )
    checkpoint_snapshot = _class_analysis_binary_artifact_snapshot(
        checkpoint_path
    )
    if (
        checkpoint_snapshot.get("sha256") != source_snapshot.get("sha256")
        or int(checkpoint_snapshot.get("bytes") or 0)
        != int(source_snapshot.get("bytes") or 0)
    ):
        raise ValueError("class_analysis_embedding_checkpoint_copy_changed")
    manifest = {
        "schema": CLASS_ANALYSIS_RESUME_CHECKPOINT_SCHEMA,
        "cache_version": CLASS_ANALYSIS_CACHE_VERSION,
        "run_fingerprint": run_fingerprint,
        "embedding_fingerprint_schema": (
            CLASS_ANALYSIS_STAGE1_EMBEDDING_FINGERPRINT_SCHEMA
        ),
        "embedding_fingerprint": embedding_fingerprint,
        "record_digest": _class_analysis_embedding_record_digest(records),
        "recipe_digest": _class_analysis_embedding_recipe_digest(
            request,
            head,
        ),
        "record_count": int(array.shape[0]),
        "shape": [int(value) for value in array.shape],
        "dtype": str(array.dtype),
        "embedding_file": "embeddings.npy",
        "embedding_sha256": str(checkpoint_snapshot["sha256"]),
        "embedding_bytes": int(checkpoint_snapshot["bytes"]),
        "adjustment_info": json_sanitize(dict(adjustment_info or {})),
        "created_at": time.time(),
    }
    # The manifest is the commit marker and is deliberately written last.
    _class_analysis_write_json(
        checkpoint_dir / CLASS_ANALYSIS_RESUME_CHECKPOINT_MANIFEST,
        checkpoint_dir,
        manifest,
    )
    return manifest


def _class_analysis_find_legacy_embedding_checkpoint(
    *,
    record_digest: str,
    recipe_digest: str,
    preferred_run_fingerprint: str,
) -> Optional[Path]:
    """Find an older run-keyed checkpoint with the exact Stage-1 binding.

    This bounded compatibility scan is solely for the immutable adjusted
    embedding matrix.  Patch-reference banks have independent V3 fingerprints
    and are never considered here.
    """

    cache_root = _class_analysis_cache_storage_root(create=False)
    if cache_root is None:
        return None
    checkpoint_root = cache_root / CLASS_ANALYSIS_RESUME_CHECKPOINT_DIRNAME
    if not checkpoint_root.is_dir() or checkpoint_root.is_symlink():
        return None
    candidates: List[Tuple[float, Path]] = []
    preferred = str(preferred_run_fingerprint or "").strip().lower()
    if re.fullmatch(r"[0-9a-f]{64}", preferred):
        preferred_dir = _class_analysis_resume_checkpoint_dir(
            preferred,
            create=False,
        )
        if preferred_dir is not None:
            candidates.append((float("inf"), preferred_dir))
    scanned = 0
    maximum_scanned = 4_096
    try:
        shard_dirs = sorted(checkpoint_root.iterdir(), key=lambda path: path.name)
    except OSError:
        return None
    for shard_dir in shard_dirs:
        if scanned >= maximum_scanned:
            break
        if (
            not re.fullmatch(r"[0-9a-f]{2}", shard_dir.name)
            or not shard_dir.is_dir()
            or shard_dir.is_symlink()
        ):
            continue
        try:
            checkpoint_dirs = list(shard_dir.iterdir())
        except OSError:
            continue
        for checkpoint_dir in checkpoint_dirs:
            if scanned >= maximum_scanned:
                break
            scanned += 1
            if (
                not re.fullmatch(r"[0-9a-f]{64}", checkpoint_dir.name)
                or not checkpoint_dir.is_dir()
                or checkpoint_dir.is_symlink()
            ):
                continue
            try:
                mtime = float(checkpoint_dir.stat().st_mtime)
            except OSError:
                mtime = 0.0
            candidates.append((mtime, checkpoint_dir.resolve(strict=False)))
    seen: Set[Path] = set()
    for _mtime, checkpoint_dir in sorted(
        candidates,
        key=lambda item: (item[0], item[1].as_posix()),
        reverse=True,
    ):
        if checkpoint_dir in seen:
            continue
        seen.add(checkpoint_dir)
        manifest_path = _safe_existing_regular_file_within_root_impl(
            checkpoint_dir / CLASS_ANALYSIS_RESUME_CHECKPOINT_MANIFEST,
            checkpoint_dir,
        )
        if manifest_path is None:
            continue
        try:
            manifest = _class_analysis_json_artifact_snapshot(
                manifest_path
            ).get("payload")
        except Exception:
            continue
        if not isinstance(manifest, Mapping):
            continue
        if (
            str(manifest.get("schema") or "")
            == CLASS_ANALYSIS_RESUME_CHECKPOINT_SCHEMA
            and str(manifest.get("cache_version") or "")
            == CLASS_ANALYSIS_CACHE_VERSION
            and str(manifest.get("record_digest") or "").lower()
            == record_digest
            and str(manifest.get("recipe_digest") or "").lower()
            == recipe_digest
        ):
            return checkpoint_dir
    return None


def _class_analysis_load_embedding_checkpoint(
    *,
    records: Sequence[Mapping[str, Any]],
    request: Mapping[str, Any],
    head: Mapping[str, Any],
    out_dir: Path,
    copy_on_write: bool = False,
) -> Tuple[Optional[np.ndarray], Dict[str, Any]]:
    """Validate and attach an exact cached matrix to a new analysis job."""

    run_fingerprint = str(request.get("run_fingerprint") or "").lower()
    record_digest = _class_analysis_embedding_record_digest(records)
    recipe_digest = _class_analysis_embedding_recipe_digest(request, head)
    embedding_fingerprint = _class_analysis_cache_digest(
        {
            "schema": CLASS_ANALYSIS_STAGE1_EMBEDDING_FINGERPRINT_SCHEMA,
            "record_digest": record_digest,
            "recipe_digest": recipe_digest,
        }
    )
    checkpoint_dir = _class_analysis_resume_checkpoint_dir(
        embedding_fingerprint,
        create=False,
    )
    if checkpoint_dir is None:
        checkpoint_dir = _class_analysis_find_legacy_embedding_checkpoint(
            record_digest=record_digest,
            recipe_digest=recipe_digest,
            preferred_run_fingerprint=run_fingerprint,
        )
    if checkpoint_dir is None:
        return None, {
            "used": False,
            "reason": "checkpoint_missing",
            "embedding_fingerprint": embedding_fingerprint,
        }
    manifest_path = _safe_existing_regular_file_within_root_impl(
        checkpoint_dir / CLASS_ANALYSIS_RESUME_CHECKPOINT_MANIFEST,
        checkpoint_dir,
    )
    if manifest_path is None:
        return None, {"used": False, "reason": "checkpoint_manifest_missing"}
    try:
        manifest_snapshot = _class_analysis_json_artifact_snapshot(
            manifest_path
        )
        manifest = manifest_snapshot.get("payload")
        if not isinstance(manifest, dict):
            raise ValueError(
                "class_analysis_embedding_checkpoint_manifest_invalid"
            )
        expected_shape = list(manifest.get("shape") or [])
        if (
            str(manifest.get("schema") or "")
            != CLASS_ANALYSIS_RESUME_CHECKPOINT_SCHEMA
            or str(manifest.get("cache_version") or "")
            != CLASS_ANALYSIS_CACHE_VERSION
            or str(manifest.get("record_digest") or "").lower()
            != record_digest
            or str(manifest.get("recipe_digest") or "").lower()
            != recipe_digest
            or (
                str(manifest.get("embedding_fingerprint") or "").strip()
                and str(manifest.get("embedding_fingerprint") or "").lower()
                != embedding_fingerprint
            )
            or int(manifest.get("record_count") or 0) != len(records)
            or len(expected_shape) != 2
            or int(expected_shape[0]) != len(records)
            or int(expected_shape[1]) <= 0
            or str(manifest.get("dtype") or "") != "float32"
            or str(manifest.get("embedding_file") or "")
            != "embeddings.npy"
            or not re.fullmatch(
                r"[0-9a-f]{64}",
                str(manifest.get("embedding_sha256") or "").lower(),
            )
            or int(manifest.get("embedding_bytes") or 0) <= 0
        ):
            raise ValueError("class_analysis_embedding_checkpoint_binding_invalid")
        checkpoint_path = _safe_existing_regular_file_within_root_impl(
            checkpoint_dir / "embeddings.npy",
            checkpoint_dir,
        )
        if checkpoint_path is None:
            raise ValueError("class_analysis_embedding_checkpoint_missing")
        checkpoint_snapshot = _class_analysis_binary_artifact_snapshot(
            checkpoint_path
        )
        if (
            str(checkpoint_snapshot.get("sha256") or "").lower()
            != str(manifest.get("embedding_sha256") or "").lower()
            or int(checkpoint_snapshot.get("bytes") or 0)
            != int(manifest.get("embedding_bytes") or 0)
        ):
            raise ValueError("class_analysis_embedding_checkpoint_hash_mismatch")
        target_path = _class_analysis_link_checkpoint_artifact(
            checkpoint_path,
            out_dir / "embeddings.npy",
            root=out_dir,
        )
        # Hash the exact attached inode as well. The cache leaf can be
        # atomically replaced after its descriptor was validated but before
        # the hard-link/copy call resolves the source path; shape and finiteness
        # checks alone cannot prove that the job received the hashed matrix.
        target_snapshot = _class_analysis_binary_artifact_snapshot(
            target_path
        )
        if (
            str(target_snapshot.get("sha256") or "").lower()
            != str(manifest.get("embedding_sha256") or "").lower()
            or int(target_snapshot.get("bytes") or 0)
            != int(manifest.get("embedding_bytes") or 0)
        ):
            raise ValueError(
                "class_analysis_embedding_checkpoint_attach_mismatch"
            )
        matrix, loaded_path = _class_analysis_load_saved_embeddings(
            out_dir,
            copy_on_write=copy_on_write,
        )
        if (
            matrix is None
            or loaded_path != target_path
            or list(matrix.shape) != [int(value) for value in expected_shape]
        ):
            raise ValueError("class_analysis_embedding_checkpoint_payload_invalid")
        _class_analysis_require_snapshot_path_unchanged(
            target_path,
            target_snapshot,
            detail="class_analysis_embedding_checkpoint_attached",
        )
        _class_analysis_require_snapshot_path_unchanged(
            manifest_path,
            manifest_snapshot,
            detail="class_analysis_embedding_checkpoint_manifest",
        )
        migrated_to_stage1_fingerprint = False
        if checkpoint_dir.name != embedding_fingerprint:
            try:
                migrated = _class_analysis_publish_embedding_checkpoint(
                    embeddings_path=target_path,
                    embeddings=matrix,
                    records=records,
                    request=request,
                    head=head,
                    adjustment_info=dict(
                        manifest.get("adjustment_info") or {}
                    ),
                )
                migrated_to_stage1_fingerprint = bool(migrated)
            except Exception as exc:  # noqa: BLE001
                # The already validated job-owned attachment remains usable.
                # Migration is only an optimization for later V3 reruns.
                logger.warning(
                    "Could not migrate legacy Stage-1 embedding checkpoint: %s",
                    exc,
                )
        _class_analysis_write_json(
            out_dir / "embeddings_manifest.json",
            out_dir,
            {
                "schema": "class-analysis-embeddings-v5-resumed-memmap",
                "dtype": "float32",
                "shape": [int(value) for value in matrix.shape],
                "embeddings": "embeddings.npy",
                "raw_embeddings": "",
                "run_fingerprint": run_fingerprint,
                "embedding_fingerprint": embedding_fingerprint,
                "checkpoint_source_run_fingerprint": str(
                    manifest.get("run_fingerprint") or ""
                ),
                "checkpoint_sha256": str(
                    checkpoint_snapshot.get("sha256") or ""
                ),
            },
        )
        return matrix, {
            "used": True,
            "checkpoint_schema": CLASS_ANALYSIS_RESUME_CHECKPOINT_SCHEMA,
            "embedding_fingerprint": embedding_fingerprint,
            "checkpoint_source": (
                "stage1_fingerprint"
                if checkpoint_dir.name == embedding_fingerprint
                else "validated_legacy_run_fingerprint"
            ),
            "checkpoint_source_run_fingerprint": str(
                manifest.get("run_fingerprint") or ""
            ),
            "migrated_to_stage1_fingerprint": (
                migrated_to_stage1_fingerprint
            ),
            "checkpoint_sha256": str(
                checkpoint_snapshot.get("sha256") or ""
            ),
            "record_count": len(records),
            "adjustment_info": dict(
                manifest.get("adjustment_info") or {}
            ),
        }
    except Exception as exc:
        return None, {
            "used": False,
            "reason": str(exc) or "checkpoint_invalid",
        }


def _class_analysis_extract_projection_coordinates(result: Dict[str, Any]) -> Dict[str, np.ndarray]:
    projection_options = result.get("projection_options") if isinstance(result, dict) else None
    coordinates = projection_options.get("coordinates") if isinstance(projection_options, dict) else None
    if not isinstance(coordinates, dict):
        return {}
    extracted: Dict[str, np.ndarray] = {}
    for mode in CLASS_ANALYSIS_PCA_PROJECTION_MODES:
        if mode not in coordinates:
            continue
        arr = np.asarray(coordinates.get(mode), dtype=np.float32)
        if arr.ndim == 2 and arr.shape[1] >= 2:
            extracted[mode] = arr[:, :2].astype(np.float32, copy=False)
    return extracted


def _class_analysis_public_result(
    result: Dict[str, Any],
    *,
    in_place: bool = False,
) -> Dict[str, Any]:
    if not isinstance(result, dict):
        return {}
    # Large all-class analyses can contain hundreds of thousands of points.
    # The terminal publisher owns ``result`` and may compact it in place so it
    # never holds both the private and public point graphs at once.  Read paths
    # retain the historical copy-on-convert default.
    public = result if in_place else dict(result)
    projection_options = dict(public.get("projection_options") or {})
    coordinates = projection_options.pop("coordinates", None)
    if isinstance(coordinates, dict):
        projection_options.setdefault(
            "coordinates_available",
            [mode for mode in CLASS_ANALYSIS_PCA_PROJECTION_MODES if mode in coordinates],
        )
    public["projection_options"] = projection_options
    points = public.get("points")
    if isinstance(points, list):
        if in_place:
            write_index = 0
            for point in points:
                if not isinstance(point, dict):
                    continue
                points[write_index] = _class_analysis_public_point(point)
                write_index += 1
            if write_index < len(points):
                del points[write_index:]
            public["points"] = points
        else:
            public["points"] = [
                _class_analysis_public_point(point)
                for point in points
                if isinstance(point, dict)
            ]
    for queue_name in (
        "wrong_class_candidates",
        "within_class_outlier_candidates",
        "refinement_candidates",
        "vignette_candidates",
    ):
        candidates = public.get(queue_name)
        if not isinstance(candidates, list):
            continue
        if not in_place:
            candidates = [
                dict(candidate) if isinstance(candidate, Mapping) else candidate
                for candidate in candidates
            ]
            public[queue_name] = candidates
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            for private_key in (
                "_image_path",
                "_image_sha256",
                "_image_width",
                "_image_height",
                "image_pack_write_enabled",
            ):
                candidate.pop(private_key, None)
    return public


