def _class_analysis_public_point(point: Dict[str, Any]) -> Dict[str, Any]:
    public = {}
    for key, value in point.items():
        if key not in _CLASS_ANALYSIS_PUBLIC_POINT_FIELDS:
            continue
        if key in _CLASS_ANALYSIS_PUBLIC_EMPTY_DEFAULT_POINT_FIELDS and _class_analysis_public_point_empty_default(value):
            continue
        public[key] = _class_analysis_public_point_value(key, value)
    review_signals = public.get("review_signals")
    is_review_point = bool(public.get("is_wrong_class_candidate")) or (
        isinstance(review_signals, list) and bool(review_signals)
    )
    if is_review_point:
        for key in _CLASS_ANALYSIS_PUBLIC_REVIEW_POINT_FIELDS:
            if key in point:
                public[key] = point[key]
    return public


def _class_analysis_public_point_empty_default(value: Any) -> bool:
    if value is None:
        return True
    if isinstance(value, str):
        return not value
    if isinstance(value, bool):
        return not value
    if isinstance(value, (int, float, np.integer, np.floating)):
        return float(value) == 0.0
    if isinstance(value, (list, tuple, dict, set)):
        return len(value) == 0
    return False


def _class_analysis_public_point_number(value: Any, *, ndigits: int = 6) -> Any:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return value
    if not math.isfinite(number):
        return value
    rounded = round(number, ndigits)
    return int(rounded) if float(rounded).is_integer() else rounded


def _class_analysis_public_point_value(key: str, value: Any) -> Any:
    if key == "projection" and isinstance(value, (list, tuple)):
        return [_class_analysis_public_point_number(item, ndigits=6) for item in value[:2]]
    if key == "bbox_xyxy" and isinstance(value, (list, tuple)):
        return [_class_analysis_public_point_number(item, ndigits=3) for item in value[:4]]
    if isinstance(value, (float, np.floating)):
        return _class_analysis_public_point_number(value, ndigits=6)
    return value


def _class_analysis_write_jpeg(
    path: Path,
    root: Path,
    image: Image.Image,
    *,
    quality: int = 86,
) -> Path:
    return _class_analysis_write_binary(
        path,
        root,
        lambda handle: image.save(handle, format="JPEG", quality=quality),
    )


def _class_analysis_copy_file_within_roots(
    src: Path,
    dest: Path,
    *,
    source_root: Path,
    dest_root: Path,
) -> bool:
    src_path = _safe_existing_regular_file_within_root_impl(src, source_root)
    if src_path is None:
        return False
    try:
        dest_path = _class_analysis_prepare_write_path(dest, dest_root)
        if dest_path is not None:
            try:
                src_resolved = src_path.resolve(strict=True)
                if dest_path.exists() and dest_path.resolve(strict=True) == src_resolved:
                    return True
                tmp_leaf = dest_path.with_suffix(f"{dest_path.suffix}.{uuid.uuid4().hex}.tmp")
                if tmp_leaf.is_symlink() or tmp_leaf.exists():
                    if tmp_leaf.is_dir() and not tmp_leaf.is_symlink():
                        return False
                    tmp_leaf.unlink(missing_ok=True)
                if dest_path.exists() or dest_path.is_symlink():
                    dest_path.unlink(missing_ok=True)
                os.link(src_resolved, dest_path)
                return True
            except OSError:
                pass
    except Exception:
        pass

    def copy_source(handle: Any) -> None:
        with src_path.open("rb") as source_handle:
            shutil.copyfileobj(source_handle, handle)

    try:
        _class_analysis_write_binary(
            dest,
            dest_root,
            copy_source,
        )
    except Exception:
        return False
    return True


def _class_analysis_embedding_cache_key(crop_cache_key: str, head: Dict[str, Any]) -> str:
    return _class_analysis_cache_digest(
        {
            "version": CLASS_ANALYSIS_CACHE_VERSION,
            "crop_key": str(crop_cache_key or ""),
            "head": _class_analysis_embedding_head_cache_identity(head),
        }
    )


def _class_analysis_load_cached_embedding(cache_path: Path) -> Optional[np.ndarray]:
    cache_root = _class_analysis_cache_storage_root(create=False)
    if cache_root is None:
        return None
    safe_cache_path = _safe_existing_regular_file_within_root_impl(
        cache_path, cache_root
    )
    if safe_cache_path is None:
        return None
    opened_identity: Optional[Tuple[int, int]] = None
    try:
        with _class_analysis_open_regular_binary_nofollow(safe_cache_path) as (
            handle,
            opened_stat,
        ):
            opened_identity = (
                int(opened_stat.st_dev),
                int(opened_stat.st_ino),
            )
            if int(opened_stat.st_size) > (
                CLASS_ANALYSIS_EMBEDDING_CACHE_MAX_BYTES
                + CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES
            ):
                raise ValueError("class_analysis_embedding_cache_too_large")
            header = _class_analysis_preflight_npy_header(
                handle,
                max_array_bytes=CLASS_ANALYSIS_EMBEDDING_CACHE_MAX_BYTES,
            )
            if (
                len(header["shape"]) != 1
                or header["shape"][0] <= 0
                or header["dtype"] != np.dtype(np.float32)
            ):
                raise ValueError("class_analysis_embedding_cache_contract_invalid")
            cached = np.load(
                handle,
                allow_pickle=False,
                max_header_size=CLASS_ANALYSIS_NPY_MAX_HEADER_BYTES,
            )
            arr = np.asarray(cached)
            if (
                arr.shape != header["shape"]
                or arr.dtype != np.dtype(np.float32)
                or not _class_analysis_array_all_finite_chunked(arr)
            ):
                raise ValueError("class_analysis_embedding_cache_payload_invalid")
            if _class_analysis_artifact_stat_identity(
                os.fstat(handle.fileno())
            ) != _class_analysis_artifact_stat_identity(opened_stat):
                raise ValueError("class_analysis_embedding_cache_changed")
            try:
                os.utime(handle.fileno(), None)
            except OSError:
                pass
    except Exception:
        _class_analysis_remove_disposable_if_same_inode(
            safe_cache_path,
            opened_identity,
        )
        return None
    return arr.astype(np.float32, copy=False)


def _class_analysis_cached_embedding_valid(crop_cache_key: str, head: Dict[str, Any]) -> bool:
    crop_key = str(crop_cache_key or "").strip()
    if not crop_key:
        return False
    cache_key = _class_analysis_embedding_cache_key(crop_key, head)
    cache_path = _class_analysis_embedding_cache_path(cache_key)
    return _class_analysis_load_cached_embedding(cache_path) is not None


