def _materialize_yolo_training_annotation_view(
    entry: Dict[str, Any],
    target_root: Path,
) -> Dict[str, Any]:
    dataset_root = _dataset_effective_root_from_entry(entry)
    target_root = _reset_materialized_dataset_root(
        target_root,
        YOLO_DATASET_CACHE_ROOT,
        detail="yolo_cache_path_invalid",
    )
    for split in ("train", "val"):
        (target_root / split / "images").mkdir(parents=True, exist_ok=True)
        (target_root / split / "labels").mkdir(parents=True, exist_ok=True)

    labelmap = [str(item).strip() for item in (entry.get("classes") or []) if str(item).strip()]
    if not labelmap:
        labelmap = _dataset_labelmap_from_root(dataset_root)
    if not labelmap:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="labelmap_missing")
    labelmap_path = target_root / "labelmap.txt"
    _materialized_dataset_write_text_within_root(
        labelmap_path,
        target_root,
        "\n".join(labelmap) + "\n",
        detail="yolo_cache_path_invalid",
    )

    yolo_layout = str(entry.get("yolo_layout") or "flat")
    counts = {"train": 0, "val": 0}
    dataset_root_resolved = dataset_root.resolve()
    for row in _annotation_collect_images(entry):
        try:
            split = _annotation_normalise_split(row.get("split"))
            image_relpath = _annotation_normalise_image_relpath(row.get("image_relpath"))
        except HTTPException:
            continue
        image_path_raw = row.get("image_path")
        if image_path_raw is None:
            continue
        try:
            image_source = Path(str(image_path_raw)).resolve()
        except Exception:
            continue
        if not _path_is_within_root_impl(image_source, dataset_root_resolved):
            continue
        lines = _annotation_effective_label_lines(entry, split, image_relpath)
        overlay_label_path = _annotation_overlay_label_path(entry, split, image_relpath)
        source_label_path = _annotation_source_label_path(
            dataset_root, yolo_layout, split, image_relpath
        )
        if not lines and not overlay_label_path.exists() and not source_label_path.exists():
            continue
        target_image = target_root / split / "images" / image_relpath
        target_label = target_root / split / "labels" / image_relpath.with_suffix(".txt")
        _copy2_if_different(image_source, target_image)
        _materialized_dataset_write_text_within_root(
            target_label,
            target_root,
            "\n".join(lines) + ("\n" if lines else ""),
            detail="yolo_cache_path_invalid",
        )
        counts[split] += 1

    train_labels = target_root / "train" / "labels"
    val_labels = target_root / "val" / "labels"
    yolo_seg_ready = _yolo_labels_have_polygons_impl(train_labels) or _yolo_labels_have_polygons_impl(
        val_labels
    )
    return {
        "prepared_root": str(target_root),
        "yolo_ready": True,
        "yolo_seg_ready": yolo_seg_ready,
        "yolo_images_dir": str(target_root / "train" / "images"),
        "yolo_labels_dir": str(train_labels),
        "yolo_labelmap_path": str(labelmap_path),
        "yolo_layout": "split",
        "source": "annotation_overlay_cache",
        "train_count": counts["train"],
        "val_count": counts["val"],
        "image_count": counts["train"] + counts["val"],
    }


def _resolve_yolo_training_dataset(payload) -> Dict[str, Any]:
    dataset_info = _yolo_training_dataset_base_resolver(payload)
    dataset_id = str(getattr(payload, "dataset_id", None) or "").strip()
    if not dataset_id:
        return dataset_info
    entry = _resolve_dataset_entry_impl(dataset_id, list_all_datasets_fn=_list_all_datasets)
    if not entry or not entry.get("yolo_ready"):
        return dataset_info
    if not _sam3_entry_needs_annotation_materialized_view(entry):
        return dataset_info
    cache_root = Path(str(dataset_info.get("cache_root") or ""))
    materialized = _materialize_yolo_training_annotation_view(entry, cache_root)
    dataset_info.update(materialized)
    return dataset_info


_rfdetr_training_dataset_base_resolver = functools.partial(
    _resolve_rfdetr_training_dataset_impl,
    resolve_dataset_entry_fn=lambda dataset_id: _resolve_dataset_entry_impl(
        dataset_id,
        list_all_datasets_fn=_list_all_datasets,
    ),
    resolve_sam3_or_qwen_dataset_fn=_resolve_sam3_or_qwen_dataset,
    load_sam3_meta_fn=lambda dataset_dir: _load_sam3_dataset_metadata_impl(
        dataset_dir,
        meta_name=SAM3_DATASET_META_NAME,
        load_json_metadata_fn=_load_json_metadata,
        persist_metadata_fn=lambda dataset_dir_inner, metadata: _persist_sam3_dataset_metadata_impl(
            dataset_dir_inner,
            metadata,
            meta_name=SAM3_DATASET_META_NAME,
            logger=logger,
            suppress_errors=True,
        ),
    ),
    detect_yolo_layout_fn=_detect_yolo_layout_impl,
    yolo_labels_have_polygons_fn=_yolo_labels_have_polygons_impl,
    convert_yolo_dataset_to_coco_fn=_convert_yolo_dataset_to_coco_impl,
    convert_qwen_dataset_to_coco_fn=_convert_qwen_dataset_to_coco_impl,
    load_qwen_dataset_metadata_fn=lambda dataset_dir: _load_qwen_dataset_metadata_impl(
        dataset_dir,
        meta_name=QWEN_METADATA_FILENAME,
        load_json_metadata_fn=_load_json_metadata,
    ),
    ensure_coco_supercategory_fn=_ensure_coco_supercategory_impl,
    http_exception_cls=HTTPException,
)


def _resolve_rfdetr_training_dataset(payload) -> Dict[str, Any]:
    dataset_id = str(getattr(payload, "dataset_id", None) or "").strip()
    task = str(getattr(payload, "task", None) or "detect").strip().lower() or "detect"
    if dataset_id:
        entry = _resolve_dataset_entry_impl(dataset_id, list_all_datasets_fn=_list_all_datasets)
        if entry and entry.get("yolo_ready") and _sam3_entry_needs_annotation_materialized_view(entry):
            meta = _materialize_sam3_annotation_view(entry)
            dataset_type = str(meta.get("type") or entry.get("type") or "bbox")
            if task == "segment" and dataset_type != "seg":
                raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="rfdetr_seg_requires_polygons")
            coco_train = meta.get("coco_train_json")
            coco_val = meta.get("coco_val_json")
            if not coco_train or not coco_val:
                raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="dataset_not_ready")
            _ensure_coco_supercategory_impl(Path(coco_train))
            _ensure_coco_supercategory_impl(Path(coco_val))
            return {
                "dataset_id": entry.get("id") or dataset_id,
                "dataset_root": meta.get("dataset_root"),
                "dataset_label": entry.get("label") or meta.get("label") or dataset_id,
                "task": task,
                "coco_train_json": coco_train,
                "coco_val_json": coco_val,
                "type": dataset_type,
                "source": "annotation_overlay",
            }
    return _rfdetr_training_dataset_base_resolver(payload)


def _resolve_coco_index_dataset_root(dataset_id: str) -> Path:
    dataset_id_clean = str(dataset_id or "").strip()
    if not dataset_id_clean:
        return _resolve_sam3_or_qwen_dataset(dataset_id_clean)
    entry = _resolve_dataset_entry_impl(
        dataset_id_clean,
        list_all_datasets_fn=_list_all_datasets,
    )
    if entry and entry.get("yolo_ready"):
        if _sam3_entry_needs_annotation_materialized_view(entry):
            meta = _materialize_sam3_annotation_view(entry)
        else:
            dataset_root = _dataset_effective_root_from_entry(entry)
            meta = _convert_yolo_dataset_to_coco_impl(dataset_root)
        root_raw = meta.get("dataset_root")
        if root_raw:
            return Path(str(root_raw)).resolve()
    if entry and entry.get("qwen_ready"):
        dataset_root = _dataset_effective_root_from_entry(entry)
        meta = _convert_qwen_dataset_to_coco_impl(dataset_root)
        root_raw = meta.get("dataset_root")
        if root_raw:
            return Path(str(root_raw)).resolve()
    return _resolve_sam3_or_qwen_dataset(dataset_id_clean)


