def _update_best_clip_head_sweep_summary(
    *,
    best_summary: Optional[Dict[str, Any]],
    best_key: Optional[Tuple[float, float]],
    total_gt: int,
    total_images: int,
    matched: int,
    fps: int,
    duplicates: int,
    preds: int,
    det_images: int,
    min_prob: float,
    margin: float,
    target_precision: float,
) -> Tuple[Dict[str, Any], Tuple[float, float]]:
    precision = matched / preds if preds else 0.0
    meets = precision >= float(target_precision)
    key = (float(min_prob), float(margin))
    summary = {
        "clip_head_min_prob": float(min_prob),
        "clip_head_margin": float(margin),
        "clip_head_meets_target_precision": bool(meets),
        "matched": int(matched),
        "fps": int(fps),
        "duplicates": int(duplicates),
        "preds": int(preds),
        "det_images": int(det_images),
        "precision": float(precision),
        "total_gt": int(total_gt),
        "total_images": int(total_images),
    }
    if best_summary is None:
        return summary, key
    best_meets = bool(best_summary.get("clip_head_meets_target_precision"))
    if meets and not best_meets:
        return summary, key
    if meets == best_meets:
        if meets:
            # prefer higher matched, then higher precision
            if (int(matched), float(precision)) > (
                int(best_summary.get("matched", 0)),
                float(best_summary.get("precision", 0.0)),
            ):
                return summary, key
        else:
            if float(precision) > float(best_summary.get("precision", 0.0)):
                return summary, key
    return best_summary, best_key or key


def _run_prompt_recipe_job(job: PromptHelperJob, payload: PromptRecipeRequest) -> None:
    with PROMPT_HELPER_JOBS_LOCK:
        PROMPT_HELPER_JOBS[job.job_id] = job
    job.status = "running"
    job.message = "Loading dataset…"
    job.request = {"mode": "recipe", **model_dump_compat(payload)}
    job.updated_at = time.time()
    try:
        if not payload.prompts:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="recipe_prompts_required")
        dataset_root = _resolve_coco_index_dataset_root(payload.dataset_id)
        coco, gt_by_image_cat, images = _load_coco_index_impl(dataset_root)
        categories = coco.get("categories") or []
        cat_entry = next(
            (c for c in categories if int(c.get("id", categories.index(c))) == payload.class_id),
            None,
        )
        if not cat_entry:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="recipe_class_not_found")
        class_name = str(cat_entry.get("name", f"class_{payload.class_id}"))
        cat_to_images: Dict[int, set[int]] = {}
        for ann in coco.get("annotations", []):
            try:
                cat_id = int(ann["category_id"])
                img_id = int(ann["image_id"])
            except Exception:
                continue
            cat_to_images.setdefault(cat_id, set()).add(img_id)
        pos_ids = _sample_images_for_category(
            payload.class_id,
            list(cat_to_images.get(payload.class_id, set())),
            payload.sample_size,
            payload.seed,
        )
        all_img_ids = list(images.keys())
        neg_ids = _sample_negative_images(
            payload.class_id,
            all_img_ids,
            cat_to_images,
            payload.negatives,
            payload.seed,
        )
        eval_ids = list(dict.fromkeys([*pos_ids, *neg_ids]))
        image_cache: Dict[int, Image.Image] = {}
        gt_index_all, all_gt_keys_all, per_image_gt_all = _build_gt_index_for_class_impl(
            gt_by_image_cat,
            payload.class_id,
            xywh_to_xyxy_fn=_xywh_to_xyxy,
        )
        gt_index = {
            img_id: entries for img_id, entries in gt_index_all.items() if img_id in eval_ids
        }
        per_image_gt = {img_id: per_image_gt_all.get(img_id, 0) for img_id in eval_ids}
        all_gt_keys = set()
        for entries in gt_index.values():
            for key, _ in entries:
                all_gt_keys.add(key)
        if not eval_ids:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="recipe_no_images_sampled")
        if not all_gt_keys:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="recipe_no_gt_for_class")
        thresholds_cache: Dict[str, List[float]] = {}
        total_steps = 0
        for prompt_entry in payload.prompts:
            key = prompt_entry.prompt
            thresholds_cache[key] = _normalize_recipe_thresholds(
                prompt_entry.thresholds or payload.threshold_candidates,
                payload.score_threshold,
            )
            total_steps += len(thresholds_cache[key]) * max(1, len(eval_ids))
        job.total_steps = total_steps
        job.completed_steps = 0
        candidates: List[Dict[str, Any]] = []
        for idx, prompt_entry in enumerate(payload.prompts):
            thresholds = thresholds_cache.get(prompt_entry.prompt) or [payload.score_threshold]
            min_threshold = min(thresholds) if thresholds else payload.score_threshold
            detections = _collect_prompt_detections_impl(
                prompt_entry.prompt,
                min_threshold,
                image_ids=eval_ids,
                images=images,
                image_cache=image_cache,
                max_dets=payload.max_dets,
                run_sam3_text_inference_fn=_run_sam3_text_inference,
                yolo_to_xyxy_fn=_yolo_to_xyxy,
            )
            for thr in thresholds:
                try:
                    job.logs.append(
                        {
                            "ts": time.time(),
                            "msg": f"Eval prompt {idx + 1}/{len(payload.prompts)} @ {thr:.2f} on {len(eval_ids)} images",
                        }
                    )
                    if len(job.logs) > MAX_JOB_LOGS:
                        job.logs[:] = job.logs[-MAX_JOB_LOGS:]
                except Exception:
                    pass
                metrics = _evaluate_prompt_candidate_impl(
                    prompt_entry.prompt,
                    thr,
                    cat_id=payload.class_id,
                    image_ids=eval_ids,
                    gt_index=gt_index,
                    images=images,
                    iou_threshold=payload.iou_threshold,
                    max_dets=payload.max_dets,
                    image_cache=image_cache,
                    cached_detections=detections,
                    run_sam3_text_inference_fn=_run_sam3_text_inference,
                    yolo_to_xyxy_fn=_yolo_to_xyxy,
                    iou_fn=_iou,
                )
                metrics["class_name"] = class_name
                metrics["class_id"] = payload.class_id
                metrics["image_count"] = len(eval_ids)
                candidates.append(metrics)
                job.completed_steps += len(eval_ids)
                if job.total_steps:
                    job.progress = min(1.0, job.completed_steps / job.total_steps)
                job.message = f"Evaluated {prompt_entry.prompt} ({job.completed_steps}/{job.total_steps} images)"
                job.updated_at = time.time()
        recipe, coverage_by_image = _build_prompt_recipe_impl(
            candidates,
            all_gt_keys,
            per_image_gt,
            images,
            eval_ids,
            gt_index,
        )
        job.status = "completed"
        job.message = "Done"
        job.result = {
            "mode": "recipe",
            "dataset_id": payload.dataset_id,
            "class_id": payload.class_id,
            "class_name": class_name,
            "positive_images": len(pos_ids),
            "negative_images": len(neg_ids),
            "positive_image_ids": pos_ids,
            "negative_image_ids": neg_ids,
            "evaluated_image_ids": eval_ids,
            "gt_count": len(all_gt_keys),
            "config": model_dump_compat(payload),
            "candidates": [
                {
                    **{
                        k: v
                        for k, v in cand.items()
                        if k not in {"matched_gt_keys", "matches_by_image"}
                    },
                    "matched_gt": len(cand.get("matched_gt_keys") or []),
                }
                for cand in candidates
            ],
            "recipe": recipe,
            "coverage_by_image": coverage_by_image,
        }
    except Exception as exc:  # noqa: BLE001
        logger.exception("Prompt recipe job %s failed", job.job_id)
        job.status = "failed"
        job.error = str(exc)
        job.message = "Failed"
    finally:
        job.updated_at = time.time()


def _run_agent_mining_job(job: AgentMiningJob, payload: AgentMiningRequest) -> None:
    """
    SAM3 Recipe Mining (steps mode).

    Builds schema-v2 multi-step recipes using:
    - prompt bank (text prompts)
    - pretrained CLIP head (required) for filtering + cleanliness tuning

    Then evaluates the full steps pipeline on a deterministic sample of images.
    """
    with AGENT_MINING_JOBS_LOCK:
        AGENT_MINING_JOBS[job.job_id] = job
    job.status = "running"
    job.message = "Preparing image sample…"
    job.request = model_dump_compat(payload)
    job.updated_at = time.time()
    start_ts = time.time()
    compute_estimate_info: Optional[Dict[str, Any]] = None

    def _log(msg: str) -> None:
        try:
            job.logs.append({"ts": time.time(), "msg": msg})
            if len(job.logs) > MAX_JOB_LOGS:
                job.logs[:] = job.logs[-MAX_JOB_LOGS:]
        except Exception:
            pass
        job.updated_at = time.time()

    def _cancelled() -> bool:
        return bool(job.cancel_event.is_set())

    try:
        _enforce_agent_mining_cache_limits(AGENT_MINING_DET_CACHE_ROOT, allow_when_running=False)

        dataset_root = _resolve_coco_index_dataset_root(payload.dataset_id)
        _log(f"Dataset resolved at {dataset_root}")
        _log(
            "Request: "
            f"eval_images={payload.eval_image_count} "
            f"sample_seed={payload.split_seed}"
        )

        sample = _ensure_agent_mining_sample(
            payload.dataset_id,
            dataset_root,
            sample_size=payload.eval_image_count,
            seed=payload.split_seed,
        )
        eval_ids = [int(i) for i in (sample.get("sample_ids") or [])]
        if not eval_ids:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST, detail="agent_mining_empty_sample"
            )
        _log(f"Prepared sample with {len(eval_ids)} images (cached={sample.get('_cached', False)})")
        sample_hash = "unknown"
        try:
            sample_hash = hashlib.sha256(
                ",".join(str(i) for i in eval_ids).encode("utf-8")
            ).hexdigest()[:12]
        except Exception:
            sample_hash = "unknown"
        job.progress = 0.05

        coco, gt_by_image_cat, images = _load_coco_index_impl(dataset_root)
        categories = coco.get("categories") or []
        _log(f"Loaded COCO with {len(categories)} categories")

        cat_filter: Optional[set[int]] = None
        if payload.classes:
            cat_filter = set()
            for cid in payload.classes:
                try:
                    cat_filter.add(int(cid))
                except Exception:
                    continue

        selected_categories: List[Tuple[int, str]] = []
        for idx, cat in enumerate(categories):
            try:
                cid = int(cat.get("id", idx))
            except Exception:
                cid = idx
            if cat_filter and cid not in cat_filter:
                continue
            selected_categories.append((cid, str(cat.get("name", f"class_{cid}"))))
        if not selected_categories:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST, detail="agent_mining_no_classes_selected"
            )

        _log(
            "Config: "
            + f"text_thr={payload.seed_threshold} visual_thr={payload.expand_threshold} "
            + f"cand_iou={payload.seed_dedupe_iou} out_iou={payload.dedupe_iou} "
            + f"mask_thr={payload.mask_threshold} max_results={payload.max_results} iou_eval={payload.iou_threshold} "
            + f"llm_prompts={payload.prompt_llm_max_prompts} workers_per_gpu={getattr(payload, 'max_workers_per_device', 1)} "
            + f"steps(max_steps={int(payload.steps_max_steps_per_recipe)}, candidates/step={int(payload.steps_max_visual_seeds_per_step)}) "
            + f"bg_guard={bool(payload.clip_head_background_guard)} "
            + f"bg_apply={getattr(payload, 'clip_head_background_apply', 'final')} "
            + f"bg_margin={getattr(payload, 'clip_head_background_margin', 0.0)} "
            + f"bg_penalty={getattr(payload, 'clip_head_background_penalty', 0.0)}"
        )

        # Pretrained CLIP head (LogReg) is required for Agent Mining (recipe mining).
        clip_head_path = _resolve_agent_clip_classifier_path_impl(
            payload.clip_head_classifier_path,
            allowed_root=UPLOAD_ROOT / "classifiers",
            allowed_exts=CLASSIFIER_ALLOWED_EXTS,
            path_is_within_root_fn=_path_is_within_root_impl,
            http_exception_cls=HTTPException,
        )
        if clip_head_path is None:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST, detail="agent_mining_clip_head_required"
            )
        clip_head = _load_clip_head_from_classifier_impl(
            clip_head_path,
            joblib_load_fn=_joblib_load,
            http_exception_cls=HTTPException,
            clip_head_background_indices_fn=_clip_head_background_indices,
            resolve_head_normalize_embeddings_fn=_resolve_head_normalize_embeddings_impl,
            infer_clip_model_fn=_infer_clip_model_from_embedding_dim_impl,
            active_clip_model_name=clip_model_name,
            default_clip_model=DEFAULT_CLIP_MODEL,
            logger=logger,
        )
        if not isinstance(clip_head, dict):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST, detail="agent_mining_clip_head_required"
            )
        head_encoder_type = str(clip_head.get("encoder_type") or "clip").lower().strip()
        if not head_encoder_type:
            head_encoder_type = "clip"
        prefilter_allowed = head_encoder_type == "clip"
        head_mode_bits = ""
        try:
            if bool(getattr(payload, "clip_head_auto_tune", True)):
                head_mode_bits = (
                    f"(auto-tune: target_precision={float(getattr(payload, 'clip_head_target_precision', 0.9)):.2f}; "
                    f"seed min_prob={payload.clip_head_min_prob} margin={payload.clip_head_margin})"
                )
            else:
                head_mode_bits = f"(fixed thresholds: min_prob={payload.clip_head_min_prob} margin={payload.clip_head_margin})"
        except Exception:
            head_mode_bits = ""
        clip_name = clip_head.get("clip_model") if isinstance(clip_head, dict) else None
        clip_name_str = (
            str(clip_name).strip()
            if isinstance(clip_name, str) and clip_name.strip()
            else "unknown"
        )
        classes_list = _clip_head_classes(clip_head)
        _log(
            "Pretrained CLIP head enabled: "
            f"{clip_head_path.name} "
            f"(clip={clip_name_str}, classes={len(classes_list)}, mode={clip_head.get('proba_mode')}) "
            f"{head_mode_bits}"
        )
        if classes_list:
            preview_limit = 60
            preview_items = []
            for idx, label in enumerate(classes_list):
                preview_items.append(f"{idx}:{label}")
                if len(preview_items) >= preview_limit:
                    break
            preview = ", ".join(preview_items)
            suffix = (
                f", … (+{len(classes_list) - preview_limit} more)"
                if len(classes_list) > preview_limit
                else ""
            )
            _log(f"CLIP head classes (index:name): {preview}{suffix}")

        sample_images = int(len(eval_ids))
        class_count = int(len(selected_categories))
        per_image_units = int(payload.steps_max_steps_per_recipe) * (
            1 + int(payload.steps_max_visual_seeds_per_step)
        )
        speed_factor = _estimate_steps_speed_factor(payload, allow_prefilter=prefilter_allowed)
        base_units_per_class = float(sample_images * per_image_units) * float(speed_factor)
        global_enabled = bool(getattr(payload, "steps_optimize_global", False)) and bool(clip_head)
        global_units_per_class = 0.0
        budgets: List[int] = []
        invalid_budgets = False
        if global_enabled:
            global_images, budgets, invalid_budgets = _estimate_agent_global_optimizer_image_evals(
                val_images=sample_images,
                eval_caps=list(getattr(payload, "steps_optimize_global_eval_caps", []) or []),
                keep_ratio=float(getattr(payload, "steps_optimize_global_keep_ratio", 0.5) or 0.5),
                rounds=int(getattr(payload, "steps_optimize_global_rounds", 1) or 1),
                max_trials=int(getattr(payload, "steps_optimize_global_max_trials", 1) or 1),
                mutations_per_round=int(
                    getattr(payload, "steps_optimize_global_mutations_per_round", 1) or 1
                ),
            )
            if not invalid_budgets:
                global_units_per_class = float(global_images * per_image_units) * float(
                    speed_factor
                )
        total_units_per_class = float(base_units_per_class + global_units_per_class)
        total_units_all = float(total_units_per_class * class_count) if class_count > 0 else None
        compute_estimate_info = {
            "sample_images": sample_images,
            "class_count": class_count,
            "steps": int(payload.steps_max_steps_per_recipe),
            "seeds_per_step": int(payload.steps_max_visual_seeds_per_step),
            "per_image_units": int(per_image_units),
            "speed_factor": float(speed_factor),
            "base_units_per_class": float(base_units_per_class),
            "global_units_per_class": float(global_units_per_class),
            "total_units_per_class": float(total_units_per_class),
            "total_units_all_classes": (
                float(total_units_all) if total_units_all is not None else None
            ),
            "global_optimizer": {
                "enabled": bool(global_enabled),
                "eval_caps": budgets,
                "invalid_budgets": bool(invalid_budgets),
            },
        }
        _log(
            "Compute estimate: "
            f"sample_images={sample_images} steps={int(payload.steps_max_steps_per_recipe)} candidates/step={int(payload.steps_max_visual_seeds_per_step)} "
            f"speed_factor={float(speed_factor):.2f} base_units/class={base_units_per_class:.0f} "
            f"global_units/class={global_units_per_class:.0f} total_units/class={total_units_per_class:.0f}"
            + (
                f" total_units/all_classes={total_units_all:.0f}"
                if total_units_all is not None
                else ""
            )
        )

        # Prompt mining (Qwen) per class.
        base_prompts_all: List[str] = []
        if payload.extra_prompts_by_class and isinstance(payload.extra_prompts_by_class, dict):
            raw_base = payload.extra_prompts_by_class.get("__base__")
            if isinstance(raw_base, list):
                base_prompts_all = [p for p in raw_base if isinstance(p, str) and p.strip()]
            elif isinstance(raw_base, str) and raw_base.strip():
                base_prompts_all = [raw_base.strip()]
        base_prompts_all = _sanitize_prompts_impl(base_prompts_all)
        if base_prompts_all:
            _log(f"Base prompts (all classes): {', '.join(base_prompts_all)}")

        prefilter_cfg = _resolve_steps_prompt_prefilter_config(
            payload, allow_prefilter=prefilter_allowed
        )
        clip_model_for_prefilter: Optional[str] = None
        if isinstance(clip_head, dict):
            raw_model = clip_head.get("clip_model")
            if isinstance(raw_model, str) and raw_model.strip():
                clip_model_for_prefilter = raw_model.strip()
        if prefilter_cfg.get("enabled"):
            _log(
                "CLIP prompt prefilter enabled: "
                f"mode={prefilter_cfg.get('mode')} sample_size={prefilter_cfg.get('sample_size')} "
                f"keep_ratio={float(prefilter_cfg.get('keep_ratio') or 0.0):.2f}"
            )
        elif prefilter_cfg.get("requested") and not prefilter_allowed:
            _log(f"CLIP prompt prefilter disabled: head encoder_type={head_encoder_type}")

        bg_indices = _clip_head_background_indices(classes_list) if clip_head else []
        prompt_bg_drop_cfg = _resolve_steps_prompt_bg_drop_config(
            payload, allow_drop=bool(bg_indices)
        )
        if prompt_bg_drop_cfg.get("enabled"):
            _log(
                "Prompt background drop enabled: "
                f"mode={prompt_bg_drop_cfg.get('mode')} min_checked={prompt_bg_drop_cfg.get('min_checked')} "
                f"drop_rate={float(prompt_bg_drop_cfg.get('drop_rate') or 0.0):.2f}"
            )
        elif (
            prompt_bg_drop_cfg.get("requested")
            and prompt_bg_drop_cfg.get("disabled_reason") == "no_background_classes"
        ):
            _log("Prompt background drop disabled: no __bg_* classes in CLIP head.")

        prepared_prompts: Dict[int, List[str]] = {}
        prompt_prefilter_stats: Dict[int, Dict[str, Any]] = {}
        for cid, name in selected_categories:
            if _cancelled():
                break
            base = []
            if payload.text_prompts_by_class and cid in payload.text_prompts_by_class:
                base = [
                    p
                    for p in payload.text_prompts_by_class.get(cid) or []
                    if isinstance(p, str) and p.strip()
                ]
            if not base:
                base = [name]
            user_extras: List[str] = []
            if payload.extra_prompts_by_class and isinstance(payload.extra_prompts_by_class, dict):
                raw_extra = payload.extra_prompts_by_class.get(name)
                if isinstance(raw_extra, list):
                    user_extras = [p for p in raw_extra if isinstance(p, str) and p.strip()]
                elif isinstance(raw_extra, str) and raw_extra.strip():
                    user_extras = [raw_extra.strip()]
            if user_extras:
                _log(f"User extra prompts for {name}: {', '.join(user_extras)}")
            base = _sanitize_prompts_impl([*base, *user_extras]) or [name]
            extras: List[str] = []
            if payload.prompt_llm_max_prompts > 0:
                extras = _expand_prompts_with_prompt_llm(
                    name,
                    base,
                    payload.prompt_llm_max_prompts,
                    log_fn=_log,
                    max_new_tokens=payload.prompt_max_new_tokens,
                )
            merged: List[str] = []
            seen = set()
            for p in [*base, *extras, *base_prompts_all]:
                key = str(p).lower().strip()
                if not key or key in seen:
                    continue
                seen.add(key)
                merged.append(str(p))
            base_keep = _sanitize_prompts_impl([*base, *base_prompts_all])
            prefilter_total = len(merged)
            if prefilter_cfg.get("enabled"):
                merged = _prefilter_prompts_with_clip(
                    merged,
                    keep_prompts=base_keep,
                    cat_id=int(cid),
                    class_name=str(name),
                    eval_ids=eval_ids,
                    images=images,
                    gt_by_image_cat=gt_by_image_cat,
                    clip_model_name=clip_model_for_prefilter,
                    sample_size=int(prefilter_cfg.get("sample_size") or 0),
                    keep_ratio=float(prefilter_cfg.get("keep_ratio") or 0.0),
                    seed=int(payload.split_seed) + int(cid),
                    log_fn=_log,
                )
            prompt_prefilter_stats[int(cid)] = {
                "enabled": bool(prefilter_cfg.get("enabled")),
                "mode": str(prefilter_cfg.get("mode") or "balanced"),
                "total": int(prefilter_total),
                "kept": int(len(merged)),
                "requested": bool(prefilter_cfg.get("requested")),
                "disabled_reason": prefilter_cfg.get("disabled_reason"),
            }
            if prefilter_cfg.get("enabled"):
                _log(
                    f"[steps] Prompt prefilter summary for {name}: kept {len(merged)}/{prefilter_total} "
                    f"(mode={prefilter_cfg.get('mode')})"
                )
            prepared_prompts[cid] = merged or base
            _log(f"Prompt list for {name}: {', '.join(prepared_prompts[cid])}")

        try:
            _unload_qwen_runtime()
            _log("Qwen prompt expansion runtime unloaded to free memory before SAM3 mining")
        except Exception:
            pass
        job.progress = max(job.progress, 0.07)

        eval_set = set(eval_ids)
        class_entries: List[Dict[str, Any]] = []
        total_classes = len(selected_categories)
        _log(f"Preparing {total_classes} class(es)…")

        for class_idx, (cid, name) in enumerate(selected_categories, start=1):
            if _cancelled():
                break
            job.message = f"Preparing {name} ({class_idx}/{total_classes})"
            job.updated_at = time.time()

            eval_gt = 0
            for img_id, cat_map in gt_by_image_cat.items():
                bboxes = cat_map.get(cid)
                if not bboxes:
                    continue
                if img_id in eval_set:
                    eval_gt += len(bboxes)

            prompts_for_class = prepared_prompts.get(cid) or [name]
            head_target_index: Optional[int] = None
            if clip_head:
                head_target_index = _find_clip_head_target_index(classes_list, name)
                if head_target_index is None:
                    _log(
                        f"CLIP head mapping: class '{name}' not found; skipping head filter for this class."
                    )
                else:
                    mapped_label = (
                        str(classes_list[head_target_index])
                        if 0 <= head_target_index < len(classes_list)
                        else "unknown"
                    )
                    _log(
                        f"CLIP head mapping: class '{name}' -> idx {head_target_index} (head='{mapped_label}')"
                    )
            class_entries.append(
                {
                    "id": int(cid),
                    "name": name,
                    "eval_gt": eval_gt,
                    "text_prompts": prompts_for_class,
                    "clip_head_target_index": head_target_index,
                }
            )

            job.progress = max(job.progress, 0.07 + 0.03 * (class_idx / max(1, total_classes)))
            job.updated_at = time.time()

        eval_payload = payload
        summaries: Dict[int, Dict[str, Any]] = {}
        recipes_by_class: Dict[int, Dict[str, Any]] = {}
        if _cancelled():
            summaries = {}
        else:
            job.message = "Evaluating recipes on sample…"
            job.updated_at = time.time()
            job.progress = max(job.progress, 0.1)
            eval_log_every = 5 if len(eval_ids) <= 50 else 50

            def _on_eval_progress(done: int, total: int) -> None:
                if total <= 0:
                    return
                if done != total and (eval_log_every <= 0 or done % eval_log_every != 0):
                    return
                frac = max(0.0, min(1.0, float(done) / float(total)))
                job.progress = max(job.progress, 0.1 + 0.9 * frac)
                job.message = f"Evaluating recipes: {done}/{total} sample images"
                job.updated_at = time.time()

            eval_workers: Optional[List[_Sam3GreedyEvalWorker]] = None
            try:
                eval_workers = _build_sam3_greedy_eval_workers(eval_payload, log_fn=_log)
                total_classes = len(class_entries)
                for class_idx, entry in enumerate(class_entries, start=1):
                    if _cancelled():
                        break
                    cid = int(entry.get("id"))
                    name = str(entry.get("name") or f"class_{cid}")
                    prompts_for_class = entry.get("text_prompts") or [name]
                    head_target_index = entry.get("clip_head_target_index")

                    class_base = 0.1 + 0.9 * ((class_idx - 1) / max(1, total_classes))
                    class_span = 0.9 * (1.0 / max(1, total_classes))
                    seed_span = class_span * 0.45
                    tune_span = class_span * 0.55

                    def _mk_phase_cb(
                        base: float, span: float, label: str, class_name: str
                    ) -> Callable[[int, int], None]:
                        def _cb(done: int, total: int) -> None:
                            if total <= 0:
                                return
                            frac = max(0.0, min(1.0, float(done) / float(total)))
                            job.progress = max(job.progress, base + span * frac)
                            job.message = f"{label} {done}/{total} ({class_name})"
                            job.updated_at = time.time()

                        return _cb

                    job.message = f"[steps] Evaluating text candidates for {name} ({class_idx}/{total_classes})…"
                    job.updated_at = time.time()
                    seed_stats = _mine_seed_prompt_stats_image_first(
                        cat_id=cid,
                        prompts=prompts_for_class,
                        val_ids=eval_ids,
                        images=images,
                        gt_by_image_cat=gt_by_image_cat,
                        payload=eval_payload,
                        clip_head=clip_head,
                        clip_head_target_index=head_target_index,
                        clip_head_bg_indices=bg_indices,
                        prompt_bg_drop_cfg=prompt_bg_drop_cfg,
                        workers=eval_workers,
                        log_every=eval_log_every,
                        log_fn=_log,
                        cancel_event=job.cancel_event,
                        progress_callback=_mk_phase_cb(
                            class_base, seed_span, "[steps] Candidate eval", name
                        ),
                    )
                    prompt_bg_drop_summary: Optional[Dict[str, Any]] = None
                    if isinstance(prompt_bg_drop_cfg, dict) and (
                        prompt_bg_drop_cfg.get("enabled") or prompt_bg_drop_cfg.get("requested")
                    ):
                        dropped = sum(
                            1
                            for s in (seed_stats or [])
                            if isinstance(s, dict) and s.get("bg_drop")
                        )
                        prompt_bg_drop_summary = {
                            "enabled": bool(prompt_bg_drop_cfg.get("enabled")),
                            "mode": str(prompt_bg_drop_cfg.get("mode") or "balanced"),
                            "min_checked": int(prompt_bg_drop_cfg.get("min_checked") or 0),
                            "drop_rate": float(prompt_bg_drop_cfg.get("drop_rate") or 0.0),
                            "total": int(len(seed_stats or [])),
                            "dropped": int(dropped),
                            "requested": bool(prompt_bg_drop_cfg.get("requested")),
                            "disabled_reason": prompt_bg_drop_cfg.get("disabled_reason"),
                        }
                    target_prec = (
                        float(getattr(eval_payload, "clip_head_target_precision", 0.0) or 0.0)
                        if (clip_head is not None and head_target_index is not None)
                        else None
                    )
                    early_stop_cfg = _resolve_steps_early_stop_config(
                        eval_payload, target_precision=target_prec
                    )
                    if early_stop_cfg.get("enabled"):
                        _log(
                            "Early-stop enabled: "
                            f"mode={early_stop_cfg.get('mode')} min_steps={early_stop_cfg.get('min_steps')} "
                            f"window={early_stop_cfg.get('window')} min_increment={float(early_stop_cfg.get('min_increment') or 0.0):.3f} "
                            f"precision_margin={float(early_stop_cfg.get('precision_margin') or 0.0):.2f}"
                        )
                    selected, early_stop_info = _select_steps_from_seed_prompt_stats(
                        seed_stats,
                        max_steps=int(getattr(eval_payload, "steps_max_steps_per_recipe", 6) or 6),
                        target_precision=target_prec,
                        early_stop=early_stop_cfg,
                        log_fn=_log,
                    )
                    if early_stop_info.get("enabled"):
                        _log(
                            f"[steps] Early-stop summary for {name}: "
                            f"selected_steps={early_stop_info.get('selected_steps')}/{early_stop_info.get('max_steps')} "
                            f"mode={early_stop_info.get('mode')} reason={early_stop_info.get('reason')}"
                        )
                    refine_info: Optional[Dict[str, Any]] = None
                    if bool(getattr(eval_payload, "steps_refine_prompt_subset", False)):
                        selected, refine_info = _refine_steps_prompt_subset_seed_stage(
                            seed_stats,
                            selected,
                            max_steps=int(
                                getattr(eval_payload, "steps_max_steps_per_recipe", 6) or 6
                            ),
                            target_precision=target_prec,
                            max_iters=int(
                                getattr(eval_payload, "steps_refine_prompt_subset_max_iters", 6)
                                or 6
                            ),
                            top_k=int(
                                getattr(eval_payload, "steps_refine_prompt_subset_top_k", 6) or 6
                            ),
                            base_seed_threshold=float(eval_payload.seed_threshold),
                            log_fn=_log,
                        )
                    if isinstance(early_stop_info, dict):
                        early_stop_info["selected_steps_final"] = int(len(selected))
                    selected_prompts, step_list = _build_steps_recipe_step_list_from_selected_stats(
                        selected,
                        prompts_fallback=prompts_for_class,
                        payload=eval_payload,
                    )

                    tier1_info: Optional[Dict[str, Any]] = None
                    tier2_info: Optional[Dict[str, Any]] = None
                    global_info: Optional[Dict[str, Any]] = None
                    summary: Dict[str, Any]
                    if clip_head is not None and head_target_index is not None:
                        global_enabled = bool(getattr(eval_payload, "steps_optimize_global", False))
                        if global_enabled:
                            job.message = f"[steps] Global optimization for {name} ({class_idx}/{total_classes})…"
                            job.updated_at = time.time()
                            step_list, global_info = _tune_steps_global_optimizer_image_first(
                                cat_id=cid,
                                steps=step_list,
                                seed_stats=seed_stats,
                                val_ids=eval_ids,
                                images=images,
                                gt_by_image_cat=gt_by_image_cat,
                                payload=eval_payload,
                                clip_head=clip_head,
                                clip_head_target_index=int(head_target_index),
                                workers=eval_workers,
                                log_fn=_log,
                                cancel_event=job.cancel_event,
                            )
                        else:
                            if bool(getattr(eval_payload, "steps_optimize_tier1", False)):
                                job.message = f"[steps] Tier-1 grid search for {name} ({class_idx}/{total_classes})…"
                                job.updated_at = time.time()
                                step_list, tier1_info = _tune_steps_tier1_knobs_image_first(
                                    cat_id=cid,
                                    steps=step_list,
                                    val_ids=eval_ids,
                                    images=images,
                                    gt_by_image_cat=gt_by_image_cat,
                                    payload=eval_payload,
                                    clip_head=clip_head,
                                    clip_head_target_index=int(head_target_index),
                                    workers=eval_workers,
                                    log_fn=_log,
                                    cancel_event=job.cancel_event,
                                )
                            if bool(getattr(eval_payload, "steps_optimize_tier2", False)):
                                job.message = f"[steps] Tier-2 tuning for {name} ({class_idx}/{total_classes})…"
                                job.updated_at = time.time()
                                step_list, tier2_info = _tune_steps_tier2_knobs_image_first(
                                    cat_id=cid,
                                    steps=step_list,
                                    val_ids=eval_ids,
                                    images=images,
                                    gt_by_image_cat=gt_by_image_cat,
                                    payload=eval_payload,
                                    clip_head=clip_head,
                                    clip_head_target_index=int(head_target_index),
                                    workers=eval_workers,
                                    log_fn=_log,
                                    cancel_event=job.cancel_event,
                                )
                        job.message = (
                            f"[steps] Tuning CLIP head for {name} ({class_idx}/{total_classes})…"
                        )
                        job.updated_at = time.time()
                        summary = _tune_clip_head_for_selected_steps_image_first(
                            cat_id=cid,
                            class_name=name,
                            steps=step_list,
                            val_ids=eval_ids,
                            images=images,
                            gt_by_image_cat=gt_by_image_cat,
                            payload=eval_payload,
                            clip_head=clip_head,
                            clip_head_target_index=int(head_target_index),
                            workers=eval_workers,
                            log_every=eval_log_every,
                            log_fn=_log,
                            cancel_event=job.cancel_event,
                            progress_callback=_mk_phase_cb(
                                class_base + seed_span,
                                tune_span,
                                "[steps] Final tune",
                                name,
                            ),
                            export_hard_negatives=True,
                        )
                        if tier1_info and isinstance(summary, dict):
                            summary["tier1_tuning"] = tier1_info
                        if tier2_info and isinstance(summary, dict):
                            summary["tier2_tuning"] = tier2_info
                        if global_info and isinstance(summary, dict):
                            summary["global_optimizer"] = global_info
                        if refine_info and isinstance(summary, dict):
                            summary["prompt_subset_refinement"] = refine_info
                        if isinstance(summary, dict):
                            prefilter_summary = prompt_prefilter_stats.get(int(cid))
                            if isinstance(prefilter_summary, dict):
                                summary["prompt_prefilter"] = prefilter_summary
                            if isinstance(prompt_bg_drop_summary, dict):
                                summary["prompt_bg_drop"] = prompt_bg_drop_summary
                            if isinstance(early_stop_info, dict):
                                summary["early_stop"] = early_stop_info
                    else:
                        total_gt = int(entry.get("eval_gt") or 0)
                        summary = {
                            "gts": total_gt,
                            "matches": 0,
                            "fps": 0,
                            "duplicates": 0,
                            "preds": 0,
                            "precision": 0.0,
                            "recall": 0.0,
                            "coverage_rate": 0.0,
                            "det_rate": 0.0,
                        }
                        if refine_info:
                            summary["prompt_subset_refinement"] = refine_info
                        prefilter_summary = prompt_prefilter_stats.get(int(cid))
                        if isinstance(prefilter_summary, dict):
                            summary["prompt_prefilter"] = prefilter_summary
                        if isinstance(prompt_bg_drop_summary, dict):
                            summary["prompt_bg_drop"] = prompt_bg_drop_summary
                        if isinstance(early_stop_info, dict):
                            summary["early_stop"] = early_stop_info

                    summaries[cid] = summary
                    tuned_min_prob = None
                    tuned_margin = None
                    tuned_bg_margin = None
                    if isinstance(summary, dict):
                        tuned_min_prob = summary.get("clip_head_min_prob")
                        tuned_margin = summary.get("clip_head_margin")
                        tuned_bg_margin = summary.get("clip_head_background_margin")
                    try:
                        final_min_prob = (
                            float(tuned_min_prob)
                            if tuned_min_prob is not None
                            else float(payload.clip_head_min_prob)
                        )
                    except Exception:
                        final_min_prob = float(payload.clip_head_min_prob)
                    try:
                        final_margin = (
                            float(tuned_margin)
                            if tuned_margin is not None
                            else float(payload.clip_head_margin)
                        )
                    except Exception:
                        final_margin = float(payload.clip_head_margin)
                    try:
                        final_bg_margin = (
                            float(tuned_bg_margin)
                            if tuned_bg_margin is not None
                            else float(payload.clip_head_background_margin)
                        )
                    except Exception:
                        final_bg_margin = float(payload.clip_head_background_margin)
                    if step_list:
                        for step in step_list:
                            if not isinstance(step, dict):
                                continue
                            if "clip_seed" not in step:
                                step["clip_seed"] = {"min_prob": 0.0, "margin": 0.0}
                            if "clip_final" not in step:
                                step["clip_final"] = {
                                    "min_prob": float(final_min_prob),
                                    "margin": float(final_margin),
                                }
                    tuned_expand = float(eval_payload.expand_threshold)
                    tuned_max_seeds = int(
                        getattr(eval_payload, "steps_max_visual_seeds_per_step", 5) or 0
                    )
                    tuned_seed_iou = float(eval_payload.seed_dedupe_iou)
                    tuned_out_iou = float(eval_payload.dedupe_iou)
                    tuned_max_results = int(eval_payload.max_results)
                    if step_list and isinstance(step_list[0], dict):
                        try:
                            if step_list[0].get("expand_threshold") is not None:
                                tuned_expand = float(step_list[0].get("expand_threshold"))
                        except Exception:
                            tuned_expand = float(eval_payload.expand_threshold)
                        try:
                            if step_list[0].get("max_visual_seeds") is not None:
                                tuned_max_seeds = int(step_list[0].get("max_visual_seeds"))
                        except Exception:
                            tuned_max_seeds = int(
                                getattr(eval_payload, "steps_max_visual_seeds_per_step", 5) or 0
                            )
                        try:
                            if step_list[0].get("seed_dedupe_iou") is not None:
                                tuned_seed_iou = float(step_list[0].get("seed_dedupe_iou"))
                        except Exception:
                            tuned_seed_iou = float(eval_payload.seed_dedupe_iou)
                        try:
                            if step_list[0].get("dedupe_iou") is not None:
                                tuned_out_iou = float(step_list[0].get("dedupe_iou"))
                        except Exception:
                            tuned_out_iou = float(eval_payload.dedupe_iou)
                        try:
                            if step_list[0].get("max_results") is not None:
                                tuned_max_results = int(step_list[0].get("max_results"))
                        except Exception:
                            tuned_max_results = int(eval_payload.max_results)
                    optimizer = {
                        "algorithm": "sam3_steps_v2",
                        "version": 1,
                        "created_at": float(time.time()),
                        "sample_seed": int(eval_payload.split_seed),
                        "sample_size": int(eval_payload.eval_image_count),
                        "sample_hash": str(sample_hash),
                        "sample_images": int(len(eval_ids)),
                        "target_precision": float(
                            getattr(eval_payload, "clip_head_target_precision", 0.0) or 0.0
                        ),
                        "max_steps_per_recipe": int(
                            getattr(eval_payload, "steps_max_steps_per_recipe", 6) or 6
                        ),
                        "seed_threshold": {
                            "base": float(eval_payload.seed_threshold),
                            "seed_eval_threshold": float(
                                _compute_steps_seed_eval_threshold(eval_payload)
                            ),
                            "seed_eval_max_results": int(
                                _compute_steps_seed_eval_max_results(eval_payload)
                            ),
                            "strategy": "curve_candidates",
                            "max_candidates_per_prompt": 6,
                        },
                        "global_optimizer": (
                            global_info
                            if isinstance(global_info, dict)
                            else {
                                "enabled": False,
                                "requested": bool(
                                    getattr(eval_payload, "steps_optimize_global", False)
                                ),
                                "eval_caps": list(
                                    getattr(eval_payload, "steps_optimize_global_eval_caps", [])
                                    or []
                                ),
                                "max_trials": int(
                                    getattr(eval_payload, "steps_optimize_global_max_trials", 0)
                                    or 0
                                ),
                                "keep_ratio": float(
                                    getattr(eval_payload, "steps_optimize_global_keep_ratio", 0.0)
                                    or 0.0
                                ),
                                "rounds": int(
                                    getattr(eval_payload, "steps_optimize_global_rounds", 0) or 0
                                ),
                                "mutations_per_round": int(
                                    getattr(
                                        eval_payload, "steps_optimize_global_mutations_per_round", 0
                                    )
                                    or 0
                                ),
                                "enable_ordering": bool(
                                    getattr(
                                        eval_payload, "steps_optimize_global_enable_ordering", False
                                    )
                                ),
                                "enable_max_results": bool(
                                    getattr(
                                        eval_payload,
                                        "steps_optimize_global_enable_max_results",
                                        False,
                                    )
                                ),
                            }
                        ),
                        "tier1": (
                            tier1_info
                            if isinstance(tier1_info, dict)
                            else {
                                "enabled": False,
                                "requested": bool(
                                    getattr(eval_payload, "steps_optimize_tier1", False)
                                ),
                                "eval_cap": int(
                                    getattr(eval_payload, "steps_optimize_tier1_eval_cap", 0) or 0
                                ),
                                "max_trials": int(
                                    getattr(eval_payload, "steps_optimize_tier1_max_trials", 0) or 0
                                ),
                            }
                        ),
                        "tier2": (
                            tier2_info
                            if isinstance(tier2_info, dict)
                            else {
                                "enabled": False,
                                "requested": bool(
                                    getattr(eval_payload, "steps_optimize_tier2", False)
                                ),
                                "eval_cap": int(
                                    getattr(eval_payload, "steps_optimize_tier2_eval_cap", 0) or 0
                                ),
                                "max_trials": int(
                                    getattr(eval_payload, "steps_optimize_tier2_max_trials", 0) or 0
                                ),
                            }
                        ),
                        "prompt_subset_refinement": (
                            refine_info
                            if isinstance(refine_info, dict)
                            else {
                                "enabled": False,
                                "requested": bool(
                                    getattr(eval_payload, "steps_refine_prompt_subset", False)
                                ),
                                "max_iters": int(
                                    getattr(eval_payload, "steps_refine_prompt_subset_max_iters", 0)
                                    or 0
                                ),
                                "top_k": int(
                                    getattr(eval_payload, "steps_refine_prompt_subset_top_k", 0)
                                    or 0
                                ),
                            }
                        ),
                        "early_stop": {
                            **(early_stop_cfg or {}),
                            "requested": bool(getattr(eval_payload, "steps_early_stop", False)),
                        },
                        "prompt_prefilter": {
                            **(prefilter_cfg or {}),
                            "requested": bool(
                                prefilter_cfg.get("requested")
                                if isinstance(prefilter_cfg, dict)
                                else getattr(eval_payload, "steps_prompt_prefilter", False)
                            ),
                            "keep_base_prompts": True,
                        },
                    }
                    recipes_by_class[cid] = {
                        "schema_version": 2,
                        "mode": "sam3_steps",
                        "optimizer": optimizer,
                        "text_prompts": list(prompts_for_class),
                        "steps": step_list,
                        "params": {
                            "use_clip_fp_guard": False,
                            "use_negative_exemplars": False,
                            "negative_strength": 0.0,
                            "similarity_score": 0.0,
                            "seed_threshold": float(eval_payload.seed_threshold),
                            "expand_threshold": float(tuned_expand),
                            "max_visual_seeds": int(tuned_max_seeds),
                            "seed_dedupe_iou": float(tuned_seed_iou),
                            "dedupe_iou": float(tuned_out_iou),
                            "mask_threshold": float(eval_payload.mask_threshold),
                            "min_size": int(eval_payload.min_size),
                            "simplify_epsilon": float(eval_payload.simplify_epsilon),
                            "max_results": int(tuned_max_results),
                            "clip_head_background_guard": bool(
                                getattr(eval_payload, "clip_head_background_guard", False)
                            ),
                            "clip_head_background_margin": float(final_bg_margin),
                            "clip_head_background_apply": str(
                                getattr(eval_payload, "clip_head_background_apply", "final")
                                or "final"
                            ),
                            "clip_head_background_penalty": float(
                                getattr(eval_payload, "clip_head_background_penalty", 0.0) or 0.0
                            ),
                        },
                        "summary": {
                            **(summary or {}),
                            "seed_prompt_stats": [
                                {
                                    "prompt": s.get("prompt"),
                                    "matches": int(s.get("matches") or 0),
                                    "fps": int(s.get("fps") or 0),
                                    "precision": float(s.get("precision") or 0.0),
                                    "selected_seed_threshold": float(
                                        s.get("selected_seed_threshold")
                                        if s.get("selected_seed_threshold") is not None
                                        else (
                                            s.get("seed_threshold_recommended")
                                            if s.get("seed_threshold_recommended") is not None
                                            else eval_payload.seed_threshold
                                        )
                                    ),
                                    "selected_seed_threshold_point": s.get(
                                        "selected_seed_threshold_point"
                                    ),
                                    "seed_threshold_base": float(
                                        s.get("seed_threshold_base") or eval_payload.seed_threshold
                                    ),
                                    "seed_threshold_recommended": float(
                                        s.get("seed_threshold_recommended")
                                        if s.get("seed_threshold_recommended") is not None
                                        else eval_payload.seed_threshold
                                    ),
                                    "seed_threshold_base_point": s.get("seed_threshold_base_point"),
                                    "seed_threshold_recommended_point": s.get(
                                        "seed_threshold_recommended_point"
                                    ),
                                    "seed_threshold_curve": s.get("seed_threshold_curve") or [],
                                }
                                for s in selected
                            ],
                        },
                    }
                job.progress = max(job.progress, 0.98)
            finally:
                if eval_workers:
                    for w in eval_workers:
                        try:
                            w.close()
                        except Exception:
                            continue

        results: List[Dict[str, Any]] = []
        for entry in class_entries:
            cid = int(entry.get("id"))
            name = str(entry.get("name") or f"class_{cid}")
            summary = summaries.get(cid)
            if summary is None:
                summary = {
                    "gts": int(entry.get("eval_gt") or 0),
                    "matches": 0,
                    "fps": 0,
                    "duplicates": 0,
                    "preds": 0,
                    "precision": 0.0,
                    "recall": 0.0,
                    "coverage_rate": 0.0,
                    "det_rate": 0.0,
                }
            recipe = recipes_by_class.get(cid) or {}
            if clip_head is not None and isinstance(recipe, dict):
                try:
                    tuned_min_prob = summary.get("clip_head_min_prob")
                    tuned_margin = summary.get("clip_head_margin")
                    if tuned_min_prob is not None or tuned_margin is not None:
                        recipe["_clip_head_classifier_path"] = str(clip_head_path)
                    recipe["clip_head"] = {
                        "artifact": "clip_head/head.npz",
                        "clip_model": clip_head.get("clip_model"),
                        "proba_mode": clip_head.get("proba_mode"),
                        "classes": _clip_head_classes(clip_head),
                        "min_prob": (
                            float(tuned_min_prob)
                            if tuned_min_prob is not None
                            else float(payload.clip_head_min_prob)
                        ),
                        "margin": (
                            float(tuned_margin)
                            if tuned_margin is not None
                            else float(payload.clip_head_margin)
                        ),
                        "background_margin": (
                            float(tuned_bg_margin)
                            if tuned_bg_margin is not None
                            else float(getattr(payload, "clip_head_background_margin", 0.0) or 0.0)
                        ),
                        "auto_tuned": bool(getattr(payload, "clip_head_auto_tune", True)),
                        "target_precision": float(
                            getattr(payload, "clip_head_target_precision", 0.9)
                        ),
                    }
                except Exception:
                    pass

            results.append(
                {
                    "id": cid,
                    "name": name,
                    "eval_gt": int(entry.get("eval_gt") or 0),
                    "recipe": recipe,
                }
            )

        job.result = {
            "dataset_id": payload.dataset_id,
            "sample": {
                "count": len(eval_ids),
                "seed": payload.split_seed,
            },
            "compute_estimate": compute_estimate_info,
            "classes": results,
            "config": model_dump_compat(eval_payload),
            "note": "Agent mining completed (steps mode).",
        }
        if compute_estimate_info and total_units_per_class:
            runtime_sec = max(0.0, float(time.time() - start_ts))
            total_units = compute_estimate_info.get(
                "total_units_all_classes"
            ) or compute_estimate_info.get("total_units_per_class")
            try:
                total_units_val = float(total_units) if total_units is not None else 0.0
            except Exception:
                total_units_val = 0.0
            sec_per_unit = runtime_sec / total_units_val if total_units_val > 0 else None
            compute_estimate_info["runtime_sec"] = runtime_sec
            compute_estimate_info["sec_per_unit"] = sec_per_unit
            _log(
                "Compute estimate calibration: "
                f"runtime_sec={runtime_sec:.1f} units={total_units_val:.0f} "
                + (
                    f"sec_per_unit={sec_per_unit:.6f}"
                    if sec_per_unit is not None
                    else "sec_per_unit=n/a"
                )
            )
        if _cancelled():
            job.status = "cancelled"
            job.message = "Cancelled"
        else:
            job.status = "completed"
            job.message = "Done"
            job.progress = 1.0
    except Exception as exc:  # noqa: BLE001
        logger.exception("Agent mining job %s failed", job.job_id)
        job.status = "failed"
        job.error = str(exc)
        job.message = "Failed"
    finally:
        job.updated_at = time.time()


def _validate_prompt_helper_dataset_id(dataset_id: str) -> None:
    _resolve_sam3_or_qwen_dataset(str(dataset_id or ""))


def _register_job_and_start_thread(
    *,
    job: Any,
    registry: Dict[str, Any],
    lock: threading.Lock,
    target: Callable[..., Any],
    args: Tuple[Any, ...],
    name: Optional[str] = None,
) -> None:
    with lock:
        registry[job.job_id] = job
    try:
        thread = threading.Thread(target=target, args=args, daemon=True, name=name)
        thread.start()
    except Exception:
        with lock:
            if registry.get(job.job_id) is job:
                registry.pop(job.job_id, None)
        raise


def _start_prompt_helper_job(payload: PromptHelperRequest) -> PromptHelperJob:
    job_id = f"ph_{uuid.uuid4().hex[:8]}"
    job = PromptHelperJob(job_id=job_id)
    _register_job_and_start_thread(
        job=job,
        registry=PROMPT_HELPER_JOBS,
        lock=PROMPT_HELPER_JOBS_LOCK,
        target=_run_prompt_helper_job,
        args=(job, payload),
    )
    return job


def _start_agent_mining_job(payload: AgentMiningRequest) -> AgentMiningJob:
    clip_head_path = _resolve_agent_clip_classifier_path_impl(
        payload.clip_head_classifier_path,
        allowed_root=UPLOAD_ROOT / "classifiers",
        allowed_exts=CLASSIFIER_ALLOWED_EXTS,
        path_is_within_root_fn=_path_is_within_root_impl,
        http_exception_cls=HTTPException,
    )
    if clip_head_path is None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST, detail="agent_mining_clip_head_required"
        )
    # Validate early so we fail fast (no background job created).
    _load_clip_head_from_classifier_impl(
        clip_head_path,
        joblib_load_fn=_joblib_load,
        http_exception_cls=HTTPException,
        clip_head_background_indices_fn=_clip_head_background_indices,
        resolve_head_normalize_embeddings_fn=_resolve_head_normalize_embeddings_impl,
        infer_clip_model_fn=_infer_clip_model_from_embedding_dim_impl,
        active_clip_model_name=clip_model_name,
        default_clip_model=DEFAULT_CLIP_MODEL,
        logger=logger,
    )
    _resolve_sam3_or_qwen_dataset(payload.dataset_id)
    job_id = f"am_{uuid.uuid4().hex[:8]}"
    job = AgentMiningJob(job_id=job_id)
    _register_job_and_start_thread(
        job=job,
        registry=AGENT_MINING_JOBS,
        lock=AGENT_MINING_JOBS_LOCK,
        target=_run_agent_mining_job,
        args=(job, payload),
    )
    return job


def _cancel_agent_mining_job(job_id: str) -> AgentMiningJob:
    with AGENT_MINING_JOBS_LOCK:
        job = AGENT_MINING_JOBS.get(job_id)
    if not job:
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="agent_mining_job_not_found")
    if job.status in {"completed", "failed", "cancelled"}:
        return job
    job.cancel_event.set()
    job.status = "cancelled"
    job.message = "Cancelled"
    job.updated_at = time.time()
    return job


def _run_auto_label_job(job: AutoLabelJob, payload: AutoLabelRequest) -> None:
    with AUTO_LABEL_JOBS_LOCK:
        AUTO_LABEL_JOBS[job.job_id] = job
    job.status = "running"
    job.message = "Preparing dataset…"
    job.request = model_dump_compat(payload)
    job.updated_at = time.time()
    session_id = str(payload.annotation_session_id or "").strip() or uuid.uuid4().hex
    lock_started = False
    lock_holder = f"auto_label:{job.job_id}"
    try:
        if bool(payload.enable_falcon):
            falcon_err = _falcon_runtime_error_detail(torch)
            if falcon_err:
                raise HTTPException(status_code=HTTP_503_SERVICE_UNAVAILABLE, detail=falcon_err)

        entry = _resolve_dataset_entry(payload.dataset_id)
        if payload.annotation_session_id:
            _meta_path, meta = _annotation_load_or_create_meta(entry)
            owned_lock = _require_annotation_lock_owner(meta, {"session_id": session_id})
            lock_holder = str(owned_lock.get("holder") or "").strip() or lock_holder
        manifest = _annotation_manifest_for_entry(entry)
        rows = list(manifest.get("images") or [])
        labelmap = [str(label).strip() for label in (manifest.get("labelmap") or []) if str(label).strip()]
        if not labelmap:
            labelmap, glossary = _agent_load_labelmap_meta(payload.dataset_id)
        else:
            glossary = get_dataset_glossary(payload.dataset_id).get("glossary") or ""
        if not rows:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="auto_label_no_images")
        target_mode, inferred_mode = _auto_label_effective_target_mode(payload.target_mode, rows)
        class_names = _auto_label_class_selection(labelmap, payload.class_names)
        class_id_map = {str(label).strip(): idx for idx, label in enumerate(labelmap)}
        edr_package_id = str(payload.edr_package_id or "").strip() or _auto_label_pick_default_edr_package(payload.dataset_id)
        baseline_mode = "edr_package" if edr_package_id else "detector_classifier"

        selected_rows = []
        split_filter = str(payload.split or "all").strip().lower()
        requested_relpaths = {
            _annotation_normalise_image_relpath(item).as_posix()
            for item in (payload.image_relpaths or [])
            if str(item or "").strip()
        }
        for row in rows:
            row_split = str(row.get("split") or "train").strip().lower()
            if split_filter in {"train", "val"} and row_split != split_filter:
                continue
            row_relpath = _annotation_normalise_image_relpath(
                row.get("image_relpath") or row.get("image_name")
            ).as_posix()
            if requested_relpaths and row_relpath not in requested_relpaths:
                continue
            lines = row.get("label_lines") or []
            if payload.unlabeled_only and isinstance(lines, list) and any(str(line).strip() for line in lines):
                continue
            selected_rows.append(row)
        max_images = int(payload.max_images or len(selected_rows))
        selected_rows = selected_rows[: max(0, max_images)]
        if not selected_rows:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="auto_label_no_target_images")

        if not payload.annotation_session_id:
            lock_payload = {
                "session_id": session_id,
                "editor_name": lock_holder,
                "force": bool(payload.force_annotation_lock),
            }
            lock_response = start_dataset_annotation_session(payload.dataset_id, lock_payload)
            if str(lock_response.get("status") or "").strip().lower() != "ok":
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=str(lock_response.get("warning") or "annotation_lock_active"),
                )
            lock_started = True

        result_summary: Dict[str, Any] = {
            "dataset_id": payload.dataset_id,
            "annotation_session_id": session_id if payload.annotation_session_id else None,
            "target_mode": target_mode,
            "mode_inferred": inferred_mode,
            "baseline_mode": baseline_mode,
            "edr_package_id": edr_package_id,
            "images_total": len(selected_rows),
            "images_processed": 0,
            "images_with_changes": 0,
            "labels_added": 0,
            "duplicates_dropped": 0,
            "zero_write_images": 0,
            "falcon_query_count": 0,
            "falcon_window_count": 0,
            "baseline_candidate_count": 0,
            "falcon_candidate_count": 0,
            "kept_candidate_count": 0,
            "writes_attempted": 0,
            "writes_applied": 0,
            "planner_retry_count": 0,
            "planner_decisions": [],
            "falcon_diagnostics": [],
            "per_class_added": {},
            "errors": [],
            "timings_sec": {
                "baseline": 0.0,
                "planner": 0.0,
                "falcon": 0.0,
                "save": 0.0,
                "total": 0.0,
            },
            "image_times_sec": [],
        }
        job.result = dict(result_summary)
        last_heartbeat = 0.0

        def _maybe_lock_heartbeat() -> None:
            nonlocal last_heartbeat
            now_local = time.time()
            if now_local - last_heartbeat <= 20.0:
                return
            try:
                heartbeat_dataset_annotation_session(
                    payload.dataset_id,
                    {"session_id": session_id, "editor_name": lock_holder},
                )
                last_heartbeat = now_local
            except Exception:
                pass

        for idx, row in enumerate(selected_rows, start=1):
            if job.cancel_event.is_set():
                break
            image_started = time.perf_counter()
            _maybe_lock_heartbeat()
            split = _annotation_normalise_split(row.get("split"))
            image_relpath = _annotation_normalise_image_relpath(row.get("image_relpath") or row.get("image_name"))
            image_path = _resolve_annotation_image_path(
                _dataset_effective_root_from_entry(entry),
                str(entry.get("yolo_layout") or "flat"),
                split,
                image_relpath,
            )
            job.message = f"Auto-labeling {image_relpath.name} ({idx}/{len(selected_rows)})"
            job.progress = max(0.0, min(1.0, float(idx - 1) / float(max(1, len(selected_rows)))))
            job.updated_at = time.time()
            current_lines = _annotation_effective_label_lines(entry, split, image_relpath)
            try:
                pil_img = Image.open(image_path).convert("RGB")
            except Exception as exc:
                result_summary["errors"].append(
                    {"image_relpath": str(image_relpath.as_posix()), "error": f"image_open_failed:{exc}"}
                )
                continue
            img_w, img_h = pil_img.size
            existing_annotations = _auto_label_build_existing_annotations(
                current_lines,
                width=img_w,
                height=img_h,
                labelmap=labelmap,
                target_mode=target_mode,
            )
            existing_classes = {
                str(item.get("class_name") or "").strip()
                for item in existing_annotations
                if str(item.get("class_name") or "").strip()
            }
            image_base64 = _auto_label_image_base64(image_path)
            baseline_candidates: List[Dict[str, Any]] = []
            baseline_counts: Dict[str, int] = {}
            if edr_package_id or payload.enable_yolo or payload.enable_rfdetr:
                baseline_started = time.perf_counter()
                baseline_request = QwenPrepassRequest(
                    dataset_id=payload.dataset_id,
                    edr_package_id=edr_package_id or None,
                    edr_package_apply_ensemble=False,
                    image_base64=image_base64,
                    image_name=image_relpath.name,
                    labelmap=labelmap,
                    labelmap_glossary=glossary or None,
                    enable_yolo=bool(payload.enable_yolo),
                    enable_rfdetr=bool(payload.enable_rfdetr),
                    yolo_id=payload.yolo_id,
                    rfdetr_id=payload.rfdetr_id,
                    classifier_id=payload.classifier_id,
                    enable_sam3_text=bool(edr_package_id),
                    enable_sam3_similarity=bool(edr_package_id),
                    prepass_caption=False,
                    ensemble_enabled=False,
                    prepass_only=True,
                    prepass_keep_all=True,
                    prepass_finalize=False,
                )
                baseline_response = _run_prepass_annotation_qwen(
                    baseline_request,
                    cancel_event=job.cancel_event,
                )
                result_summary["timings_sec"]["baseline"] += time.perf_counter() - baseline_started
                _maybe_lock_heartbeat()
                for det in baseline_response.detections or []:
                    class_name = str(det.get("label") or "").strip()
                    if class_name and class_names and class_name not in class_names:
                        continue
                    bbox = det.get("bbox_yolo")
                    if not isinstance(bbox, (list, tuple)) or len(bbox) < 4:
                        continue
                    x1, y1, x2, y2 = _yolo_to_xyxy(img_w, img_h, bbox[:4])
                    baseline_candidates.append(
                        {
                            "class_id": int(class_id_map.get(class_name, -1)),
                            "class_name": class_name,
                            "bbox_xyxy": (float(x1), float(y1), float(x2), float(y2)),
                            "mask": None,
                            "score": float(det.get("score") or 0.5),
                            "source": "baseline",
                        }
                    )
                    if class_name:
                        baseline_counts[class_name] = baseline_counts.get(class_name, 0) + 1
            result_summary["baseline_candidate_count"] += len(baseline_candidates)

            manual_window_mode = bool(payload.enable_falcon) and payload.falcon_window_mode in {
                AUTO_LABEL_WINDOW_MODE_FULL,
                AUTO_LABEL_WINDOW_MODE_QUADRANTS,
            }
            explicit_class_subset = bool(payload.class_names)
            if not bool(payload.enable_falcon):
                target_classes = []
            elif manual_window_mode and explicit_class_subset:
                # In explicit manual window modes, the user's requested class subset is the
                # contract. Baseline detections should not suppress Falcon entirely for a class.
                target_classes = [name for name in class_names if name not in existing_classes]
            else:
                covered_classes = set(existing_classes)
                for class_name in baseline_counts:
                    covered_classes.add(class_name)
                target_classes = [name for name in class_names if name not in covered_classes]
            falcon_candidates: List[Dict[str, Any]] = []
            planner_summary = None
            if target_classes:
                if payload.falcon_window_mode == AUTO_LABEL_WINDOW_MODE_FULL:
                    windows = [{"id": "FULL", "xyxy": (0.0, 0.0, float(img_w), float(img_h)), "classes": target_classes}]
                elif payload.falcon_window_mode == AUTO_LABEL_WINDOW_MODE_QUADRANTS:
                    windows = [
                        {**window, "classes": list(target_classes)}
                        for window in _auto_label_build_quadrant_windows(
                            img_w,
                            img_h,
                            overlap_ratio=float(payload.falcon_overlap_ratio),
                        )
                    ]
                else:
                    planner_started = time.perf_counter()
                    planner_summary = _auto_label_run_planner(
                        pil_img,
                        model_id_override=payload.planner_model_id,
                        labelmap=labelmap,
                        target_classes=target_classes,
                        baseline_counts=baseline_counts,
                        window_overlap_ratio=float(payload.falcon_overlap_ratio),
                        use_caption=bool(payload.use_planner_caption),
                        grid_cols=int(payload.planner_grid_cols),
                        grid_rows=int(payload.planner_grid_rows),
                    )
                    result_summary["timings_sec"]["planner"] += time.perf_counter() - planner_started
                    planner_payload = planner_summary.get("parsed") if isinstance(planner_summary, dict) else None
                    decision = str((planner_payload or {}).get("decision") or "").strip().lower()
                    grid_windows = {
                        str(row.get("id") or ""): row
                        for row in (planner_summary.get("grid_windows") or [])
                        if isinstance(row, dict)
                    }
                    windows = []
                    if decision == "skip":
                        windows = []
                    elif decision == AUTO_LABEL_WINDOW_MODE_FULL:
                        classes_for_full = list((planner_payload or {}).get("global_classes") or target_classes) or list(target_classes)
                        windows = [{"id": "FULL", "xyxy": (0.0, 0.0, float(img_w), float(img_h)), "classes": classes_for_full}]
                    elif decision == AUTO_LABEL_WINDOW_MODE_QUADRANTS:
                        windows = [
                            {**window, "classes": list(target_classes)}
                            for window in _auto_label_build_quadrant_windows(
                                img_w,
                                img_h,
                                overlap_ratio=float(payload.falcon_overlap_ratio),
                            )
                        ]
                    elif decision == "grid_cells":
                        seen_cells = set()
                        for row in (planner_payload or {}).get("cell_classes") or []:
                            if not isinstance(row, dict):
                                continue
                            cell_id = str(row.get("cell") or "").strip().upper()
                            if cell_id in seen_cells:
                                continue
                            window = grid_windows.get(cell_id)
                            if not window:
                                continue
                            seen_cells.add(cell_id)
                            window_classes = [
                                cls_name
                                for cls_name in (row.get("classes") or [])
                                if cls_name in target_classes
                            ] or list(target_classes)
                            windows.append({**window, "classes": window_classes})
                        for cell_id in (planner_payload or {}).get("cells") or []:
                            cell_norm = str(cell_id or "").strip().upper()
                            if cell_norm in seen_cells:
                                continue
                            window = grid_windows.get(cell_norm)
                            if not window:
                                continue
                            seen_cells.add(cell_norm)
                            windows.append({**window, "classes": list(target_classes)})
                    else:
                        windows = [
                            {**window, "classes": list(target_classes)}
                            for window in _auto_label_build_quadrant_windows(
                                img_w,
                                img_h,
                                overlap_ratio=float(payload.falcon_overlap_ratio),
                            )
                        ]
                result_summary["falcon_window_count"] += len(windows)
                if planner_summary is not None:
                    result_summary["planner_retry_count"] += int(
                        planner_summary.get("retry_count") or 0
                    )
                    result_summary["planner_decisions"].append(
                        {
                            "image_relpath": str(image_relpath.as_posix()),
                            "planner": planner_summary,
                        }
                    )
                for window in windows:
                    window_classes = [
                        cls_name for cls_name in (window.get("classes") or []) if cls_name in target_classes
                    ]
                    if not window_classes:
                        continue
                    falcon_started = time.perf_counter()
                    falcon_window_result = _auto_label_falcon_candidates_for_window(
                        pil_img=pil_img,
                        crop_window=window,
                        class_names=window_classes,
                        class_id_map=class_id_map,
                        labelmap=labelmap,
                        glossary=glossary or "",
                        payload=payload,
                        target_mode=target_mode,
                    )
                    if isinstance(falcon_window_result, dict):
                        falcon_candidates.extend(list(falcon_window_result.get("candidates") or []))
                        result_summary["falcon_query_count"] += int(
                            falcon_window_result.get("query_count") or 0
                        )
                        result_summary["falcon_diagnostics"].extend(
                            list(falcon_window_result.get("diagnostics") or [])
                        )
                    else:
                        falcon_candidates.extend(list(falcon_window_result or []))
                        result_summary["falcon_query_count"] += len(window_classes)
                    result_summary["timings_sec"]["falcon"] += time.perf_counter() - falcon_started
                    _maybe_lock_heartbeat()
            result_summary["falcon_candidate_count"] += len(falcon_candidates)

            merge_candidates = [*baseline_candidates, *falcon_candidates]
            kept, dropped = _auto_label_dedupe_candidates(
                merge_candidates,
                existing=existing_annotations,
                target_mode=target_mode,
                iou_threshold=float(payload.dedupe_existing_same_class_iou),
            )
            result_summary["duplicates_dropped"] += int(dropped)
            result_summary["kept_candidate_count"] += len(kept)
            if not kept:
                image_elapsed = time.perf_counter() - image_started
                result_summary["zero_write_images"] += 1
                result_summary["timings_sec"]["total"] += image_elapsed
                result_summary["image_times_sec"].append(image_elapsed)
                result_summary["images_processed"] += 1
                job.result = dict(result_summary)
                job.progress = max(0.0, min(1.0, float(idx) / float(max(1, len(selected_rows)))))
                continue

            new_lines: List[str] = []
            per_class_new_lines: Dict[str, int] = {}
            for candidate in kept:
                class_id = int(candidate.get("class_id", -1))
                if class_id < 0:
                    class_name = str(candidate.get("class_name") or "").strip()
                    if class_name not in class_id_map:
                        continue
                    class_id = int(class_id_map[class_name])
                if target_mode == AUTO_LABEL_TARGET_MODE_SEGMENTATION and candidate.get("mask") is not None:
                    try:
                        line = _auto_label_serialize_mask_label_line(
                            class_id,
                            candidate.get("mask"),
                            width=img_w,
                            height=img_h,
                            simplify_epsilon=float(payload.simplify_epsilon),
                        )
                    except Exception:
                        continue
                elif target_mode == AUTO_LABEL_TARGET_MODE_SEGMENTATION:
                    line = _auto_label_serialize_bbox_polygon_label_line(
                        class_id,
                        candidate.get("bbox_xyxy") or (),
                        width=img_w,
                        height=img_h,
                    )
                else:
                    line = _auto_label_serialize_bbox_label_line(
                        class_id,
                        candidate.get("bbox_xyxy") or (),
                        width=img_w,
                        height=img_h,
                    )
                new_lines.append(line)
                class_name = (
                    str(labelmap[class_id]).strip()
                    if 0 <= class_id < len(labelmap)
                    else str(candidate.get("class_name") or class_id)
                )
                per_class_new_lines[class_name] = int(per_class_new_lines.get(class_name) or 0) + 1
            if not new_lines:
                image_elapsed = time.perf_counter() - image_started
                result_summary["zero_write_images"] += 1
                result_summary["timings_sec"]["total"] += image_elapsed
                result_summary["image_times_sec"].append(image_elapsed)
                result_summary["images_processed"] += 1
                job.result = dict(result_summary)
                job.progress = max(0.0, min(1.0, float(idx) / float(max(1, len(selected_rows)))))
                continue
            if job.cancel_event.is_set():
                _auto_label_log(job, f"cancelled before saving {image_relpath.as_posix()}")
                break
            final_lines = list(current_lines) + new_lines
            _maybe_lock_heartbeat()
            if job.cancel_event.is_set():
                _auto_label_log(job, f"cancelled before saving {image_relpath.as_posix()}")
                break
            result_summary["writes_attempted"] += len(new_lines)
            save_started = time.perf_counter()
            save_dataset_annotation_snapshot(
                payload.dataset_id,
                {
                    "session_id": session_id,
                    "records": [
                        {
                            "split": split,
                            "image_relpath": str(image_relpath.as_posix()),
                            "label_lines": final_lines,
                        }
                    ],
                    "cursor": {"image_relpath": str(image_relpath.as_posix())},
                },
            )
            result_summary["timings_sec"]["save"] += time.perf_counter() - save_started
            result_summary["images_with_changes"] += 1
            result_summary["labels_added"] += len(new_lines)
            result_summary["writes_applied"] += len(new_lines)
            for class_name, count in per_class_new_lines.items():
                result_summary["per_class_added"][class_name] = (
                    int(result_summary["per_class_added"].get(class_name) or 0) + int(count)
                )
            result_summary["images_processed"] += 1
            image_elapsed = time.perf_counter() - image_started
            result_summary["timings_sec"]["total"] += image_elapsed
            result_summary["image_times_sec"].append(image_elapsed)
            job.result = dict(result_summary)
            _auto_label_log(
                job,
                f"saved {image_relpath.as_posix()} added={len(new_lines)} dropped={dropped} mode={target_mode}",
            )
            job.progress = max(0.0, min(1.0, float(idx) / float(max(1, len(selected_rows)))))

        if job.cancel_event.is_set():
            job.status = "cancelled"
            job.message = "Cancelled"
        else:
            job.status = "completed"
            job.message = "Done"
            job.progress = 1.0
        job.result = result_summary
        try:
            _write_auto_label_result_json(job.job_id, result_summary)
        except Exception:
            pass
    except HTTPException as exc:
        logger.exception("Auto-label job %s failed", job.job_id)
        job.status = "failed"
        job.error = str(exc.detail or exc)
        job.message = "Failed"
    except Exception as exc:  # noqa: BLE001
        logger.exception("Auto-label job %s failed", job.job_id)
        job.status = "failed"
        job.error = str(exc)
        job.message = "Failed"
    finally:
        if lock_started:
            try:
                stop_dataset_annotation_session(
                    payload.dataset_id,
                    {
                        "session_id": session_id,
                        "editor_name": lock_holder,
                        "force": bool(payload.force_annotation_lock),
                    },
                )
            except Exception:
                pass
        job.updated_at = time.time()


def _start_auto_label_job(payload: AutoLabelRequest) -> AutoLabelJob:
    job_id = f"al_{uuid.uuid4().hex[:8]}"
    job = AutoLabelJob(job_id=job_id)
    _register_job_and_start_thread(
        job=job,
        registry=AUTO_LABEL_JOBS,
        lock=AUTO_LABEL_JOBS_LOCK,
        target=_run_auto_label_job,
        args=(job, payload),
    )
    return job


def _cancel_auto_label_job(job_id: str) -> AutoLabelJob:
    with AUTO_LABEL_JOBS_LOCK:
        job = AUTO_LABEL_JOBS.get(job_id)
    if not job:
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="auto_label_job_not_found")
    if job.status in {"completed", "failed", "cancelled"}:
        return job
    job.cancel_event.set()
    job.status = "cancelled"
    job.message = "Cancelled"
    job.updated_at = time.time()
    return job


def _start_prompt_helper_search_job(payload: PromptHelperSearchRequest) -> PromptHelperJob:
    job_id = f"phs_{uuid.uuid4().hex[:8]}"
