def _safe_regular_file_within_root(path: Path, root: Path) -> bool:
    try:
        resolved_path = path.resolve(strict=True)
        resolved_root = root.resolve(strict=False)
    except Exception:
        return False
    if not _path_is_within_root_impl(resolved_path, resolved_root):
        return False
    return resolved_path.is_file()


def _zip_write_safe_file(zf: zipfile.ZipFile, path: Path, root: Path, arcname: str) -> bool:
    if not _safe_regular_file_within_root(path, root):
        return False
    zf.write(path.resolve(strict=True), arcname=arcname)
    return True


def _zip_write_required_safe_file(
    zf: zipfile.ZipFile,
    path: Path,
    root: Path,
    arcname: str,
    *,
    error: str,
    missing_name: Optional[str] = None,
) -> None:
    if _zip_write_safe_file(zf, path, root, arcname):
        return
    raise HTTPException(
        status_code=HTTP_412_PRECONDITION_FAILED,
        detail={"error": error, "missing": [missing_name or arcname]},
    )


def delete_rfdetr_run(run_id: str):
    run_dir = _rfdetr_run_dir_impl(
        run_id,
        create=False,
        job_root=RFDETR_JOB_ROOT,
        sanitize_fn=_sanitize_rfdetr_run_id_impl,
        http_exception_cls=HTTPException,
    )
    if not run_dir.exists() or not run_dir.is_dir():
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="rfdetr_run_not_found")
    blocking_registry = _active_job_registry_blocking_run_delete(
        run_id,
        run_dir,
        [("rfdetr_training", RFDETR_TRAINING_JOBS, RFDETR_TRAINING_JOBS_LOCK)],
    )
    if blocking_registry:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=f"rfdetr_run_delete_blocked_active_jobs:{blocking_registry}",
        )
    active = _load_detector_active_payload_raw(RFDETR_ACTIVE_PATH)
    active_best = str(active.get("best_path") or "")
    active_matches = str(active.get("run_id") or "") == str(run_id)
    if not active_matches and active_best:
        try:
            active_matches = _path_is_within_root_impl(
                Path(active_best).resolve(strict=False),
                run_dir.resolve(strict=False),
            )
        except Exception:
            active_matches = False
    try:
        shutil.rmtree(run_dir)
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(status_code=HTTP_500_INTERNAL_SERVER_ERROR, detail=str(exc)) from exc
    if active_matches:
        try:
            RFDETR_ACTIVE_PATH.unlink(missing_ok=True)
        except Exception:
            pass
        _clear_rfdetr_infer_state()
    return {"status": "deleted", "run_id": run_id}


