def get_active_model():
    return _current_active_payload()


def set_active_model(payload: ActiveModelRequest):
    global clf, clip_model, clip_preprocess, clip_model_name, clip_initialized
    global active_classifier_path, active_labelmap_path, active_label_list, clip_last_error
    global active_encoder_type, active_encoder_model
    global dinov3_model, dinov3_processor, dinov3_model_name, dinov3_initialized, dinov3_model_device
    global cradio_model, cradio_processor, cradio_model_name, cradio_model_device, cradio_initialized
    global active_classifier_meta, active_head_normalize_embeddings, active_classifier_head

    classifier_path = _normalise_optional_path(payload.classifier_path) or active_classifier_path
    labelmap_path = _normalise_optional_path(payload.labelmap_path)
    payload_fields_set = getattr(payload, "model_fields_set", None)
    if payload_fields_set is None:
        payload_fields_set = getattr(payload, "__fields_set__", set())
    labelmap_provided = "labelmap_path" in payload_fields_set
    requested_clip_model = _normalise_optional_path(payload.clip_model)

    if not classifier_path:
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="classifier_required")
    classifier_path_abs = os.path.abspath(classifier_path)
    if not os.path.isfile(classifier_path_abs):
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="classifier_not_found")
    allowed_root = _safe_upload_subdir("classifiers", detail="classifiers_root_invalid")
    classifier_path_raw = Path(classifier_path_abs)
    try:
        classifier_path_resolved = classifier_path_raw.resolve()
    except Exception:
        classifier_path_resolved = classifier_path_raw
    if (
        not _path_is_within_root_impl(classifier_path_resolved, allowed_root)
        or _classifier_path_has_symlink_component(classifier_path_raw, allowed_root)
    ):
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="classifier_path_not_allowed")
    _validate_upload_extension(
        classifier_path_abs, CLASSIFIER_ALLOWED_EXTS, "classifier_extension_not_allowed"
    )

    try:
        new_clf = _joblib_load(classifier_path_abs)
    except Exception as exc:  # noqa: BLE001
        clip_last_error = str(exc)
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST, detail=f"classifier_load_failed:{exc}"
        ) from exc

    meta_clip_model = None
    meta_encoder_type = "clip"
    meta_encoder_model = None
    meta_found = False
    meta_obj: Optional[Dict[str, Any]] = None
    meta_path = _safe_classifier_meta_path_impl(Path(classifier_path_abs))
    if meta_path is not None:
        try:
            meta_candidate = _joblib_load(str(meta_path))
            if isinstance(meta_candidate, dict):
                meta_obj = meta_candidate
                meta_found = True
                meta_clip_model = meta_obj.get("clip_model")
                meta_encoder_type = meta_obj.get("encoder_type") or "clip"
                meta_encoder_model = meta_obj.get("encoder_model") or meta_clip_model
        except Exception:
            meta_clip_model = None
            meta_encoder_type = "clip"
            meta_encoder_model = None
            meta_found = False
    encoder_type_norm = str(meta_encoder_type or "clip").strip().lower()
    encoder_model_norm = str(meta_encoder_model or "").strip() or (
        str(meta_clip_model).strip() if meta_clip_model else ""
    )

    embed_dim = None
    try:
        if isinstance(new_clf, dict):
            embed_dim = new_clf.get("embedding_dim")
            if embed_dim is None:
                layers = new_clf.get("layers")
                if isinstance(layers, list) and layers:
                    weight = layers[0].get("weight")
                    if weight is not None and hasattr(weight, "shape"):
                        embed_dim = weight.shape[1]
        else:
            coef = getattr(new_clf, "coef_", None)
            if coef is not None:
                embed_dim = coef.shape[1]
    except Exception:
        embed_dim = None
    new_clip_model = None
    new_preprocess = None
    new_dinov3_model = None
    new_dinov3_processor = None
    new_cradio_model = None
    new_cradio_processor = None
    new_cradio_device = None
    encoder_model_for_active = None

    if not meta_found:
        if (
            isinstance(new_clf, dict)
            and str(new_clf.get("classifier_type") or new_clf.get("head_type") or "") == "mlp"
        ):
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="classifier_meta_required")
        if embed_dim is not None and int(embed_dim) not in {512, 768}:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="classifier_meta_required")
        if encoder_type_norm != "clip":
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="classifier_meta_required")

    if encoder_type_norm == "clip":
        clip_name = (
            requested_clip_model
            or str(meta_clip_model or "").strip()
            or clip_model_name
            or DEFAULT_CLIP_MODEL
        )
        base_embed_dim = _classifier_base_dim_from_head_dim(
            embed_dim,
            encoder_type=encoder_type_norm,
            meta=meta_obj,
        )
        inferred = _infer_clip_model_from_embedding_dim_impl(
            base_embed_dim, active_name=clip_model_name or DEFAULT_CLIP_MODEL
        )
        if inferred and inferred != clip_name and not requested_clip_model:
            clip_name = inferred
        if clip_name not in SUPPORTED_CLIP_MODELS:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="clip_model_not_allowed")
        need_new_clip = clip_model is None or clip_model_name != clip_name
        if need_new_clip:
            try:
                new_clip_model, new_preprocess = clip.load(clip_name, device=device)
            except Exception as exc:  # noqa: BLE001
                raise HTTPException(
                    status_code=HTTP_400_BAD_REQUEST, detail=f"clip_load_failed:{exc}"
                ) from exc
        else:
            new_clip_model = clip_model
            new_preprocess = clip_preprocess
        clip_dim = getattr(getattr(new_clip_model, "visual", None), "output_dim", None)
        expected_clip_dim = _classifier_expected_head_dim(
            clip_dim,
            encoder_type=encoder_type_norm,
            meta=meta_obj,
        )
        if embed_dim is not None and expected_clip_dim is not None and embed_dim != expected_clip_dim:
            inferred = _infer_clip_model_from_embedding_dim_impl(
                base_embed_dim,
                active_name=clip_name,
            )
            if inferred and inferred != clip_name:
                try:
                    new_clip_model, new_preprocess = clip.load(inferred, device=device)
                except Exception as exc:  # noqa: BLE001
                    raise HTTPException(
                        status_code=HTTP_400_BAD_REQUEST, detail=f"clip_load_failed:{exc}"
                    ) from exc
                clip_name = inferred
                clip_dim = getattr(getattr(new_clip_model, "visual", None), "output_dim", None)
                expected_clip_dim = _classifier_expected_head_dim(
                    clip_dim,
                    encoder_type=encoder_type_norm,
                    meta=meta_obj,
                )
                logger.warning(
                    "CLIP classifier embedding dim %s mismatched requested backbone; falling back to %s.",
                    embed_dim,
                    inferred,
                )
        if embed_dim is not None and expected_clip_dim is not None and embed_dim != expected_clip_dim:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"dimension_mismatch:{embed_dim}!={expected_clip_dim}",
            )
        encoder_model_for_active = clip_name
    elif encoder_type_norm == "dinov3":
        if not encoder_model_norm:
            raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="encoder_model_required")
        try:
            target_device = _resolve_dinov3_runtime_device(encoder_model_norm, device)
            (
                new_dinov3_model,
                new_dinov3_processor,
                _resolved_dinov3_model,
                target_device,
            ) = _data_ingestion_get_dinov3(
                encoder_model_norm,
                target_device,
            )
        except HTTPException as exc:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST, detail=f"dinov3_load_failed:{exc.detail}"
            ) from exc
        except RuntimeError as exc:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST, detail=f"dinov3_load_failed:{exc}"
            ) from exc
        dino_dim = None
        if is_mlx_dinov3_encoder(new_dinov3_model):
            dino_dim = int(getattr(new_dinov3_model, "hidden_size", 0) or 0)
        else:
            try:
                cfg = getattr(new_dinov3_model, "config", None)
                dino_dim = getattr(cfg, "hidden_size", None) or getattr(cfg, "embed_dim", None)
            except Exception:
                dino_dim = None
        expected_dino_dim = _classifier_expected_head_dim(
            dino_dim,
            encoder_type=encoder_type_norm,
            meta=meta_obj,
        )
        if embed_dim is not None and expected_dino_dim is not None and int(embed_dim) != int(expected_dino_dim):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"dimension_mismatch:{embed_dim}!={expected_dino_dim}",
            )
        encoder_model_for_active = encoder_model_norm
    elif encoder_type_norm == "cradio":
        encoder_model_norm = normalize_cradio_model(encoder_model_norm)
        try:
            target_device = resolve_cradio_torch_device(model_name=encoder_model_norm)
            new_cradio_model, new_cradio_processor, encoder_model_for_active, new_cradio_device = _load_cradio_backbone_cached(
                encoder_model_norm,
                target_device,
                raise_on_error=True,
            )
        except RuntimeError as exc:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST, detail=f"cradio_load_failed:{exc}"
            ) from exc
        base_cradio_dim = _classifier_cradio_base_dim(new_cradio_model)
        expected_cradio_dim = _classifier_expected_head_dim(
            base_cradio_dim,
            encoder_type=encoder_type_norm,
            meta=meta_obj,
        )
        if embed_dim is not None and expected_cradio_dim is not None and int(embed_dim) != int(expected_cradio_dim):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"dimension_mismatch:{embed_dim}!={expected_cradio_dim}",
            )
    else:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST, detail="clip_encoder_type_unsupported"
        )

    labelmap_path_abs = None
    labelmap_entries: List[str] = []
    if labelmap_path is not None:
        labelmap_path_abs = os.path.abspath(labelmap_path)
        allowed_label_roots = [
            _safe_upload_subdir("labelmaps", detail="labelmaps_root_invalid"),
            _safe_upload_subdir("classifiers", detail="classifiers_root_invalid"),
        ]
        labelmap_path_raw = Path(labelmap_path_abs)
        try:
            labelmap_path_resolved = labelmap_path_raw.resolve()
        except Exception:
            labelmap_path_resolved = labelmap_path_raw
        matching_label_root = next(
            (
                root
                for root in allowed_label_roots
                if _path_is_within_root_impl(labelmap_path_resolved, root)
            ),
            None,
        )
        if matching_label_root is None or _classifier_path_has_symlink_component(
            labelmap_path_raw, matching_label_root
        ):
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST, detail="labelmap_path_not_allowed"
            )
        _validate_upload_extension(
            labelmap_path_abs, LABELMAP_ALLOWED_EXTS, "labelmap_extension_not_allowed"
        )
        labelmap_entries = _load_labelmap_file(labelmap_path_abs, strict=True)
    elif not labelmap_provided and active_labelmap_path:
        labelmap_path_abs = active_labelmap_path
        labelmap_entries = list(active_label_list)
    classes_raw = getattr(new_clf, "classes_", None)
    if classes_raw is None and isinstance(new_clf, dict):
        classes_list = _classifier_classes_list(new_clf.get("classes"))
    else:
        classes_list = _classifier_classes_list(classes_raw)
    clf_classes = len(classes_list) if classes_list else None
    if clf_classes is not None:
        if not labelmap_entries:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST, detail="labelmap_required_for_classifier"
            )
        bg_indices = _clip_head_background_indices(classes_list)
        non_bg_classes = [c for idx, c in enumerate(classes_list) if idx not in bg_indices]
        label_norm = {_normalize_class_name_for_match(n) for n in labelmap_entries if n}
        clf_norm = {_normalize_class_name_for_match(n) for n in non_bg_classes if n}
        if label_norm != clf_norm:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST, detail="labelmap_classifier_class_mismatch"
            )

    try:
        new_classifier_head = _load_clip_head_from_classifier_impl(
            Path(classifier_path_abs),
            joblib_load_fn=_joblib_load,
            http_exception_cls=HTTPException,
            clip_head_background_indices_fn=_clip_head_background_indices,
            resolve_head_normalize_embeddings_fn=_resolve_head_normalize_embeddings_impl,
            infer_clip_model_fn=_infer_clip_model_from_embedding_dim_impl,
            active_clip_model_name=encoder_model_for_active or clip_model_name,
            default_clip_model=DEFAULT_CLIP_MODEL,
            logger=logger,
        )
    except HTTPException:
        raise
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST, detail=f"classifier_head_load_failed:{exc}"
        ) from exc

    with clip_lock:
        clf = new_clf
        if encoder_type_norm == "clip":
            clip_model = new_clip_model
            clip_preprocess = new_preprocess
            clip_model_name = encoder_model_for_active
            clip_initialized = True
        else:
            clip_initialized = bool(clip_model is not None and clip_preprocess is not None)
        active_classifier_path = classifier_path_abs
        active_labelmap_path = labelmap_path_abs
        active_label_list = labelmap_entries
        active_encoder_type = encoder_type_norm
        active_encoder_model = encoder_model_for_active
        active_classifier_meta = dict(meta_obj) if isinstance(meta_obj, dict) else {}
        active_head_normalize_embeddings = _resolve_active_head_normalize_embeddings_impl(
            meta_obj,
            new_clf,
            default=True,
            resolve_head_normalize_embeddings_fn=_resolve_head_normalize_embeddings_impl,
        )
        active_classifier_head = new_classifier_head
        if payload.logit_adjustment_inference is not None and isinstance(
            active_classifier_head, dict
        ):
            active_classifier_head["logit_adjustment_inference"] = bool(
                payload.logit_adjustment_inference
            )
        clip_last_error = None
    if encoder_type_norm == "dinov3":
        with dinov3_lock:
            dinov3_model = new_dinov3_model
            dinov3_processor = new_dinov3_processor
            dinov3_model_name = encoder_model_for_active
            dinov3_model_device = target_device
            dinov3_initialized = bool(dinov3_model is not None and dinov3_processor is not None)
    elif encoder_type_norm == "cradio":
        with cradio_lock:
            cradio_model = new_cradio_model
            cradio_processor = new_cradio_processor
            cradio_model_name = encoder_model_for_active
            cradio_model_device = new_cradio_device
            cradio_initialized = _cradio_runtime_ready(
                cradio_model,
                cradio_processor,
                cradio_model_device,
            )

    return _current_active_payload()


