_CLASS_ANALYSIS_ANNOTATION_ENTITY_STORE = None
_CLASS_ANALYSIS_ANNOTATION_ENTITY_LOCK = threading.RLock()


def _class_analysis_annotation_entity_store():
    global _CLASS_ANALYSIS_ANNOTATION_ENTITY_STORE
    if _CLASS_ANALYSIS_ANNOTATION_ENTITY_STORE is None:
        from services.annotation_entity_store import AnnotationEntityStore

        _CLASS_ANALYSIS_ANNOTATION_ENTITY_STORE = AnnotationEntityStore()
    return _CLASS_ANALYSIS_ANNOTATION_ENTITY_STORE


def _class_analysis_annotation_image_key(record: Dict[str, Any]) -> str:
    split = _annotation_normalise_split(record.get("split"))
    relpath = _annotation_normalise_image_relpath(
        record.get("image_relpath") or record.get("image_name")
    )
    return f"{split}:{relpath.as_posix()}"


def _class_analysis_enrich_annotation_manifest(
    manifest: Any,
    *,
    initialize: bool = False,
) -> Any:
    """Attach non-exported stable IDs to each manifest row.

    Legacy records are migrated only when the mapping is deterministic.  A
    conflict is reported on that image and preserved in the sidecar store; no
    label row is changed by this read path.
    """

    if not isinstance(manifest, dict):
        return manifest
    rows = manifest.get("images")
    if not isinstance(rows, list):
        rows = manifest.get("records")
    if not isinstance(rows, list):
        return manifest
    from services.annotation_entities import (
        AnnotationIdentityConflict,
        bind_label_rows_to_entities,
        live_annotation_entities,
        migrate_legacy_annotation_record,
    )

    store = _class_analysis_annotation_entity_store()
    for raw in rows:
        if not isinstance(raw, dict):
            continue
        source_identity = str(raw.get("annotation_source_identity") or "").strip()
        label_lines = raw.get("label_lines")
        if not source_identity or not isinstance(label_lines, list):
            continue
        current_lines = [str(line).strip() for line in label_lines if str(line).strip()]
        try:
            image_key = _class_analysis_annotation_image_key(raw)
        except HTTPException:
            continue
        existing = store.get_record(source_identity, image_key)
        if existing is None and not initialize:
            raw["annotation_identity_status"] = "uninitialized"
            continue
        try:
            record = (
                migrate_legacy_annotation_record(
                    source_identity=source_identity,
                    source_lines=current_lines,
                    current_lines=current_lines,
                    existing_record=existing,
                )
                if initialize
                else existing
            )
            if record is None:
                raise AnnotationIdentityConflict("annotation identity is not initialized")
            bound_entities = bind_label_rows_to_entities(record, current_lines)
        except AnnotationIdentityConflict as exc:
            detail = str(exc)
            if initialize:
                store.mark_conflict(source_identity, image_key, detail)
            raw["annotation_identity_status"] = "identity_conflict"
            raw["annotation_identity_detail"] = detail
            continue
        if initialize:
            store.put_record(source_identity, image_key, record)
        raw["annotation_identity_status"] = "ready"
        raw["annotation_entity_record_revision"] = record["record_revision"]
        raw["annotation_entities"] = live_annotation_entities(record)
        raw["annotation_entities_by_label_row"] = bound_entities
    return manifest


def _class_analysis_initialize_annotation_manifest_entities(manifest: Any) -> Any:
    """Initialize/reconcile entity metadata once at analysis start under one lock."""
    with _CLASS_ANALYSIS_ANNOTATION_ENTITY_LOCK:
        return _class_analysis_enrich_annotation_manifest(manifest, initialize=True)


_get_transient_annotation_manifest_without_entities = get_transient_annotation_manifest
_get_dataset_annotation_manifest_without_entities = get_dataset_annotation_manifest


def get_transient_annotation_manifest(session_id: str):
    return _class_analysis_enrich_annotation_manifest(
        _get_transient_annotation_manifest_without_entities(session_id)
    )


def get_dataset_annotation_manifest(dataset_id: str):
    return _class_analysis_enrich_annotation_manifest(
        _get_dataset_annotation_manifest_without_entities(dataset_id)
    )


def _class_analysis_annotation_transaction_manifest(
    source_kind: str,
    source_id: str,
) -> Dict[str, Any]:
    if source_kind == "transient":
        return get_transient_annotation_manifest(source_id)
    if source_kind == "dataset":
        return get_dataset_annotation_manifest(source_id)
    raise HTTPException(
        status_code=HTTP_400_BAD_REQUEST,
        detail="annotation_transaction_source_kind_invalid",
    )


def _class_analysis_annotation_transaction_record(
    source_kind: str,
    source_id: str,
    split: str,
    image_relpath: str,
) -> Dict[str, Any]:
    """Read and identity-enrich one annotation row without scanning a dataset."""

    split_norm = _annotation_normalise_split(split)
    rel = _annotation_normalise_image_relpath(image_relpath)
    if source_kind == "dataset":
        entry = _resolve_dataset_entry(source_id)
        dataset_root = _dataset_effective_root_from_entry(entry)
        yolo_layout = str(entry.get("yolo_layout") or "flat")
        image_path = _resolve_annotation_image_path(
            dataset_root,
            yolo_layout,
            split_norm,
            rel,
        )
        label_lines = [
            str(line).strip()
            for line in _annotation_effective_label_lines(entry, split_norm, rel)
            if str(line).strip()
        ]
        source_mode = "linked"
    elif source_kind == "transient":
        session = _resolve_transient_session(source_id)
        dataset_root = _transient_session_dataset_root(session)
        yolo_layout = str(session.get("yolo_layout") or "flat")
        image_path = _resolve_annotation_image_path(
            dataset_root,
            yolo_layout,
            split_norm,
            rel,
        )
        key = f"{split_norm}:{rel.as_posix()}"
        overlay_labels = (
            session.get("overlay_labels")
            if isinstance(session.get("overlay_labels"), dict)
            else {}
        )
        if key in overlay_labels:
            label_lines = [
                str(line).strip()
                for line in (overlay_labels.get(key) or [])
                if str(line).strip()
            ]
        else:
            annotation_source_root = _transient_session_annotation_source_root(
                session,
                dataset_root,
            )
            source_path = _annotation_source_label_path(
                annotation_source_root,
                yolo_layout,
                split_norm,
                rel,
            )
            source_text = _annotation_read_text_within_root(
                source_path,
                annotation_source_root,
            )
            label_lines = (
                [line.strip() for line in source_text.splitlines() if line.strip()]
                if source_text is not None
                else []
            )
        source_mode = "transient"
    else:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_transaction_source_kind_invalid",
        )
    row = {
        "split": split_norm,
        "image_relpath": rel.as_posix(),
        "image_name": rel.name,
        "label_lines": label_lines,
        "annotation_record_revision": _annotation_image_label_revision(label_lines),
        "annotation_source_identity": _annotation_image_source_identity(
            source_mode=source_mode,
            source_id=source_id,
            split=split_norm,
            image_relpath=rel,
            image_path=image_path,
            yolo_layout=yolo_layout,
        ),
    }
    enriched = _class_analysis_enrich_annotation_manifest({"images": [row]})
    rows = enriched.get("images") if isinstance(enriched, dict) else None
    if not isinstance(rows, list) or len(rows) != 1:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail="annotation_review_source_row_unavailable",
        )
    return rows[0]


def _class_analysis_annotation_transaction_source_state(
    source_kind: str,
    source_id: str,
) -> Dict[str, Any]:
    """Read transaction metadata without scanning every source image."""

    if source_kind == "transient":
        session = _resolve_transient_session(source_id)
        return {
            "labelmap": list(session.get("classes") or []),
            "session_revision": int(session.get("_state_revision") or 0),
        }
    if source_kind == "dataset":
        entry = _resolve_dataset_entry(source_id)
        with _dataset_annotation_mutation_lock(entry):
            _meta_path, meta = _annotation_load_or_create_meta(entry)
        return {
            "labelmap": list(entry.get("classes") or []),
            "session_revision": int(meta.get("annotation_revision") or 0),
        }
    raise HTTPException(
        status_code=HTTP_400_BAD_REQUEST,
        detail="annotation_transaction_source_kind_invalid",
    )


def _class_analysis_annotation_transaction_snapshot(
    source_kind: str,
    source_id: str,
    requested_records: list[Any],
) -> Dict[str, Any]:
    """Capture transaction metadata and touched rows under one source lock."""

    def _rows() -> Dict[str, Dict[str, Any]]:
        rows_by_key: Dict[str, Dict[str, Any]] = {}
        for requested in requested_records:
            if not isinstance(requested, Mapping):
                continue
            image_key = _class_analysis_annotation_image_key(dict(requested))
            if image_key in rows_by_key:
                continue
            rows_by_key[image_key] = _class_analysis_annotation_transaction_record(
                source_kind,
                source_id,
                str(requested.get("split") or ""),
                str(
                    requested.get("image_relpath")
                    or requested.get("image_name")
                    or ""
                ),
            )
        return rows_by_key

    if source_kind == "transient":
        with DATASET_TRANSIENT_LOCK:
            session = _resolve_transient_session(source_id)
            return {
                "labelmap": list(session.get("classes") or []),
                "session_revision": int(session.get("_state_revision") or 0),
                "rows_by_key": _rows(),
            }
    if source_kind == "dataset":
        entry = _resolve_dataset_entry(source_id)
        with _dataset_annotation_mutation_lock(entry):
            _meta_path, meta = _annotation_load_or_create_meta(entry)
            return {
                "labelmap": list(entry.get("classes") or []),
                "session_revision": int(meta.get("annotation_revision") or 0),
                "rows_by_key": _rows(),
            }
    raise HTTPException(
        status_code=HTTP_400_BAD_REQUEST,
        detail="annotation_transaction_source_kind_invalid",
    )


def _class_analysis_annotation_transaction_conflict_detail(
    planned_records: Sequence[Mapping[str, Any]],
    current_states: Sequence[str],
    action_results: Sequence[Mapping[str, Any]],
) -> Dict[str, Any]:
    """Return exact identities for prepared rows that changed before commit."""

    conflict_image_keys = {
        str(planned.get("image_key") or "")
        for planned, current_state in zip(planned_records, current_states)
        if current_state == "conflict" and str(planned.get("image_key") or "")
    }
    conflict_point_ids = sorted(
        {
            str(result.get("point_id") or "")
            for result in action_results
            if str(result.get("point_id") or "")
            and _class_analysis_annotation_image_key(
                {
                    "split": result.get("split"),
                    "image_relpath": result.get("image_relpath"),
                }
            )
            in conflict_image_keys
        }
    )
    return {
        "code": "annotation_transaction_snapshot_state_conflict",
        "message": "A prepared annotation row changed before the transaction committed.",
        "image_keys": sorted(conflict_image_keys),
        "point_ids": conflict_point_ids,
    }


def _class_analysis_annotation_transaction_save(
    source_kind: str,
    source_id: str,
    payload: Dict[str, Any],
):
    if source_kind == "transient":
        return save_transient_annotation_snapshot(source_id, payload)
    if source_kind == "dataset":
        return save_dataset_annotation_snapshot(source_id, payload)
    raise HTTPException(
        status_code=HTTP_400_BAD_REQUEST,
        detail="annotation_transaction_source_kind_invalid",
    )


def _class_analysis_resolve_transaction_entity(
    *,
    job_id: str,
    point: Mapping[str, Any],
    current_row: Mapping[str, Any],
    image_key: str,
    source_identity: str,
    record: Mapping[str, Any],
    requested_action: Mapping[str, Any],
    store: Any,
) -> Dict[str, Any]:
    """Resolve one action to an immutable point identity; never sort duplicates."""

    from services.annotation_entities import canonical_label_line, live_annotation_entities

    point_id = str(point.get("point_id") or requested_action.get("point_id") or "").strip()
    entity_id = str(point.get("annotation_entity_id") or "").strip()
    point_has_entity_identity = bool(entity_id)
    entity_revision = int(point.get("annotation_entity_revision") or 0)
    record_revision = str(point.get("annotation_entity_record_revision") or "").strip()
    identity_status = str(point.get("identity_status") or "").strip()
    attestation = str(point.get("annotation_attestation") or "").strip()

    point_source_identity = str(point.get("annotation_source_identity") or "").strip()
    if point_source_identity and point_source_identity != source_identity:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=f"annotation_entity_point_source_changed:{point_id}",
        )
    point_record_key = str(point.get("source_record_key") or "").strip()
    if point_record_key and point_record_key != image_key:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=f"annotation_entity_point_record_changed:{point_id}",
        )

    if not entity_id:
        binding = store.get_point_binding(job_id, point_id)
        if binding is not None:
            if (
                str(binding.get("source_identity") or "") != source_identity
                or str(binding.get("image_key") or "") != image_key
            ):
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=f"annotation_entity_legacy_binding_changed:{point_id}",
                )
            entity_id = str(binding.get("annotation_entity_id") or "")
            entity_revision = int(binding.get("entity_revision") or 0)
            record_revision = str(binding.get("record_revision") or "")
            identity_status = str(binding.get("status") or "legacy_exact")
            attestation = str(binding.get("attestation") or "")
        else:
            try:
                source_ordinal = int(point.get("label_line_index"))
            except (TypeError, ValueError) as exc:
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=f"annotation_entity_rerun_required:{point_id}",
                ) from exc
            point_line = canonical_label_line(point.get("label_line"))
            candidates = [
                entity
                for entity in live_annotation_entities(record)
                if entity.get("source_row_ordinal") is not None
                and int(entity["source_row_ordinal"]) == source_ordinal
                and canonical_label_line(entity.get("label_line")) == point_line
            ]
            if len(candidates) != 1:
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=f"annotation_entity_ambiguous_rerun_required:{point_id}",
                )
            entity = candidates[0]
            entity_id = str(entity["annotation_entity_id"])
            entity_revision = int(entity["entity_revision"])
            record_revision = str(record.get("record_revision") or "")
            identity_status = "legacy_exact"
            attestation = hashlib.sha256(
                "\0".join(
                    [
                        source_identity,
                        image_key,
                        entity_id,
                        str(entity_revision),
                        record_revision,
                        point_line,
                    ]
                ).encode("utf-8")
            ).hexdigest()
            store.put_point_binding(
                job_id=job_id,
                point_id=point_id,
                source_identity=source_identity,
                image_key=image_key,
                annotation_entity_id=entity_id,
                entity_revision=entity_revision,
                record_revision=record_revision,
                status=identity_status,
                attestation=attestation,
            )

    if identity_status in {"identity_conflict", "ambiguous", "uninitialized"}:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=f"annotation_entity_rerun_required:{point_id}",
        )
    requested_entity_id = str(requested_action.get("annotation_entity_id") or "").strip()
    if point_has_entity_identity and not requested_entity_id:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=f"annotation_entity_id_required:{point_id}",
        )
    if requested_entity_id and requested_entity_id != entity_id:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=f"annotation_entity_point_identity_changed:{point_id}",
        )
    expected_entity_revision = requested_action.get("expected_entity_revision")
    if point_has_entity_identity and expected_entity_revision is None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=f"annotation_entity_revision_required:{point_id}",
        )
    if expected_entity_revision is not None:
        try:
            requested_entity_revision = int(expected_entity_revision)
        except (TypeError, ValueError) as exc:
            raise HTTPException(
                status_code=HTTP_400_BAD_REQUEST,
                detail=f"annotation_entity_revision_invalid:{point_id}",
            ) from exc
        if requested_entity_revision != entity_revision:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail=f"annotation_entity_point_revision_changed:{point_id}",
            )
    if point_has_entity_identity and not attestation:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail=f"annotation_entity_attestation_required:{point_id}",
        )
    if point_has_entity_identity:
        expected_attestation = hashlib.sha256(
            "\0".join(
                [
                    source_identity,
                    image_key,
                    entity_id,
                    str(entity_revision),
                    record_revision,
                ]
            ).encode("utf-8")
        ).hexdigest()
        if not hmac.compare_digest(attestation, expected_attestation):
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail=f"annotation_entity_attestation_invalid:{point_id}",
            )
    return {
        **dict(requested_action),
        "point_id": point_id,
        "annotation_entity_id": entity_id,
        "expected_entity_revision": entity_revision,
        "expected_record_revision": str(record.get("record_revision") or ""),
        "attested_record_revision": record_revision,
        "identity_status": identity_status or "ready",
        "annotation_attestation": attestation,
    }


def _class_analysis_validate_confirm_current_annotation(
    *,
    job: Any,
    point: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> Dict[str, Any]:
    """Prove that Confirm Current still names the same live entity and class."""

    from services.annotation_entities import canonical_label_line, live_annotation_entities

    point_id = str(point.get("point_id") or "").strip()
    precondition = payload.get("annotation_precondition")
    if not isinstance(precondition, Mapping):
        raise HTTPException(
            status_code=422,
            detail={
                "code": "annotation_precondition_required",
                "point_id": point_id,
            },
        )
    source = precondition.get("annotation_source")
    if not isinstance(source, Mapping):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_review_source_required",
                "point_id": point_id,
            },
        )
    source_kind = str(source.get("kind") or "").strip().lower()
    source_id = str(source.get("id") or "").strip()
    split = _annotation_normalise_split(precondition.get("split"))
    rel = _annotation_normalise_image_relpath(precondition.get("image_relpath"))
    if source_kind not in {"dataset", "transient"} or not source_id:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_review_source_required",
                "point_id": point_id,
            },
        )
    point_split = str(point.get("split") or "").strip()
    point_relpath = str(
        point.get("image_relpath")
        or point.get("image_name")
        or point.get("frontend_image_key")
        or ""
    ).replace("\\", "/").strip()
    if (
        (point_split and point_split != split)
        or (point_relpath and not point_relpath.endswith(rel.as_posix()))
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_review_point_image_changed",
                "point_id": point_id,
            },
        )

    current_row = _class_analysis_annotation_transaction_record(
        source_kind,
        source_id,
        split,
        rel.as_posix(),
    )
    image_key = _class_analysis_annotation_image_key(current_row)
    source_identity = str(
        current_row.get("annotation_source_identity") or ""
    ).strip()
    expected_source_identity = str(
        precondition.get("annotation_source_identity") or ""
    ).strip()
    if not source_identity or expected_source_identity != source_identity:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_review_source_changed",
                "point_id": point_id,
            },
        )
    current_label_revision = str(
        current_row.get("annotation_record_revision") or ""
    ).strip()
    if str(
        precondition.get("expected_annotation_record_revision") or ""
    ).strip() != current_label_revision:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_review_label_revision_changed",
                "point_id": point_id,
            },
        )

    store = _class_analysis_annotation_entity_store()
    record = store.get_record(source_identity, image_key)
    if record is None:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_entity_rerun_required",
                "point_id": point_id,
            },
        )
    current_record_revision = str(record.get("record_revision") or "").strip()
    if (
        not current_record_revision
        or str(current_row.get("annotation_entity_record_revision") or "").strip()
        != current_record_revision
        or str(precondition.get("expected_record_revision") or "").strip()
        != current_record_revision
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_entity_sidecar_out_of_sync",
                "point_id": point_id,
            },
        )

    authoritative = _class_analysis_resolve_transaction_entity(
        job_id=str(getattr(job, "job_id", "") or ""),
        point=point,
        current_row=current_row,
        image_key=image_key,
        source_identity=source_identity,
        record=record,
        requested_action={
            "point_id": point_id,
            "annotation_entity_id": precondition.get("annotation_entity_id"),
            "expected_entity_revision": precondition.get(
                "expected_entity_revision"
            ),
        },
        store=store,
    )
    entity_id = str(authoritative.get("annotation_entity_id") or "").strip()
    live_matches = [
        entity
        for entity in live_annotation_entities(record)
        if str(entity.get("annotation_entity_id") or "").strip() == entity_id
    ]
    expected_entity_revision = int(
        authoritative.get("expected_entity_revision") or 0
    )
    if (
        len(live_matches) != 1
        or int(live_matches[0].get("entity_revision") or 0)
        != expected_entity_revision
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_review_entity_changed",
                "point_id": point_id,
            },
        )

    summary = dict(getattr(job, "summary", None) or {})
    labelmap = [str(name or "").strip() for name in (summary.get("labelmap") or [])]
    frozen_class_name = str(point.get("class_name") or "").strip()
    frozen_line = canonical_label_line(point.get("label_line"))
    try:
        frozen_class_value = float(frozen_line.split()[0])
        if not math.isfinite(frozen_class_value) or not frozen_class_value.is_integer():
            raise ValueError("invalid frozen class")
        frozen_class_id = int(frozen_class_value)
    except (IndexError, TypeError, ValueError):
        frozen_class_id = (
            labelmap.index(frozen_class_name)
            if frozen_class_name in labelmap
            else -1
        )
    try:
        current_class_value = float(
            canonical_label_line(live_matches[0].get("label_line")).split()[0]
        )
        if not math.isfinite(current_class_value) or not current_class_value.is_integer():
            raise ValueError("invalid current class")
        current_class_id = int(current_class_value)
    except (IndexError, TypeError, ValueError) as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_review_live_class_invalid",
                "point_id": point_id,
            },
        ) from exc
    expected_class_name = str(precondition.get("expected_class_name") or "").strip()
    try:
        expected_class_id = int(precondition.get("expected_class_id"))
    except (TypeError, ValueError) as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_review_expected_class_invalid",
                "point_id": point_id,
            },
        ) from exc
    current_class_name = (
        labelmap[current_class_id]
        if 0 <= current_class_id < len(labelmap)
        else ""
    )
    if (
        frozen_class_id < 0
        or expected_class_id != frozen_class_id
        or expected_class_name != frozen_class_name
        or current_class_id != frozen_class_id
        or (
            frozen_class_name
            and current_class_name
            and current_class_name != frozen_class_name
        )
    ):
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_review_class_changed",
                "point_id": point_id,
            },
        )

    attestation = {
        "schema": "class-analysis-review-annotation-attestation-v1",
        "analysis_job_id": str(getattr(job, "job_id", "") or ""),
        "point_id": point_id,
        "annotation_entity_id": entity_id,
        "entity_revision": expected_entity_revision,
        "record_revision": current_record_revision,
        "annotation_record_revision": current_label_revision,
        "annotation_source_identity": source_identity,
        "image_key": image_key,
        "class_id": current_class_id,
        "class_name": current_class_name or frozen_class_name,
        "verification_method": "stable_entity_live_class_cas_v1",
    }
    attestation["attestation_sha256"] = hashlib.sha256(
        json.dumps(
            attestation,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return attestation


def _class_analysis_record_confirm_current_disposition(
    *,
    job: Any,
    result: Mapping[str, Any],
    point: Mapping[str, Any],
    payload: Mapping[str, Any],
    origin: str,
    client_action_id: str,
    training_capture_requested: bool,
) -> Dict[str, Any]:
    """Validate and record Confirm Current atomically with source mutations."""

    review_object_key = str(point.get("review_object_key") or "").strip()
    existing = _class_analysis_lookup_review_dispositions(
        [review_object_key]
    ).get(review_object_key)
    if (
        isinstance(existing, Mapping)
        and str(existing.get("client_action_id") or "") == client_action_id
        and str(existing.get("disposition") or "").strip().lower()
        == "confirm_current"
        and str(
            existing.get("analysis_job_id") or existing.get("job_id") or ""
        ).strip()
        == str(getattr(job, "job_id", "") or "").strip()
        and str(existing.get("point_id") or "").strip()
        == str(point.get("point_id") or "").strip()
    ):
        replay_point = dict(point)
        stored_attestation = existing.get("review_annotation_attestation")
        if isinstance(stored_attestation, Mapping):
            replay_point["review_annotation_attestation"] = copy.deepcopy(
                dict(stored_attestation)
            )
        return _class_analysis_record_review_disposition_entry(
            result=result,
            point=replay_point,
            disposition="confirm_current",
            origin=origin,
            client_action_id=client_action_id,
            training_capture_requested=training_capture_requested,
        )

    precondition = payload.get("annotation_precondition")
    if not isinstance(precondition, Mapping):
        raise HTTPException(
            status_code=422,
            detail={
                "code": "annotation_precondition_required",
                "point_id": str(point.get("point_id") or ""),
            },
        )
    source = (
        precondition.get("annotation_source")
        if isinstance(precondition, Mapping)
        else None
    )
    source_kind = (
        str(source.get("kind") or "").strip().lower()
        if isinstance(source, Mapping)
        else ""
    )
    source_id = (
        str(source.get("id") or "").strip()
        if isinstance(source, Mapping)
        else ""
    )
    if source_kind == "dataset" and source_id:
        source_lock = _dataset_annotation_mutation_lock(
            _resolve_dataset_entry(source_id)
        )
    elif source_kind == "transient" and source_id:
        source_lock = DATASET_TRANSIENT_LOCK
    else:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={
                "code": "annotation_review_source_required",
                "point_id": str(point.get("point_id") or ""),
            },
        )
    with source_lock:
        attestation = _class_analysis_validate_confirm_current_annotation(
            job=job,
            point=point,
            payload=payload,
        )
        return _class_analysis_record_review_disposition_entry(
            result=result,
            point={
                **dict(point),
                "review_annotation_attestation": attestation,
            },
            disposition="confirm_current",
            origin=origin,
            client_action_id=client_action_id,
            training_capture_requested=training_capture_requested,
        )


def _class_analysis_annotation_operation_public(operation: Mapping[str, Any]) -> Dict[str, Any]:
    response = dict(operation.get("response") or {})
    response.pop("plan", None)
    state = str(operation.get("state") or "prepared")
    phase = str(operation.get("phase") or state)
    status = str(operation.get("status") or state)
    request = operation.get("request") or {}
    response["status"] = status
    response["phase"] = phase
    response["transaction_status"] = state
    response["transaction_kind"] = str(
        request.get("transaction_kind")
        or response.get("transaction_kind")
        or "annotation_entity_actions_v1"
    )
    response["client_action_id"] = str(operation.get("operation_id") or "")
    response["job_id"] = str(operation.get("job_id") or response.get("job_id") or "")
    response["binding_generation"] = int(operation.get("binding_generation") or 0)
    response["mutation_committed"] = bool(
        response.get("committed")
        or state
        in {
            "annotation_committed",
            "entity_committed",
            "review_committed",
            "complete",
            "conflict",
        }
        and isinstance(response.get("annotation_snapshot"), Mapping)
    )
    response["checkpoint_blocking"] = status not in {
        "complete",
        "rejected",
        "conflict",
        "superseded",
        "legacy_unrecoverable",
    }
    response["recovery_required"] = bool(operation.get("retryable")) or state in {
        "prepared",
        "annotation_committed",
        "entity_committed",
        "review_committed",
        "recovery_required",
    }
    response["rerun_required"] = bool(
        response.get("rerun_required")
        or status == "binding_conflict"
        or isinstance(response.get("terminal_recovery"), Mapping)
        and response["terminal_recovery"].get("rerun_required") is True
    )
    if operation.get("error"):
        response["error"] = dict(operation.get("error") or {})
    return response


def _class_analysis_record_entity_transaction_review(
    *,
    job_id: str,
    point_id: str,
    action: str,
    target_class_id: Any,
    target_class_name: str,
    client_action_id: str,
    capture_training_data: bool = False,
    training_authorization: Any = None,
) -> Dict[str, Any]:
    """Write a canonical review row from a verified server-side entity commit."""

    disposition = "delete_bbox" if action == "delete" else "reassign_class"
    with CLASS_ANALYSIS_REVIEW_MUTATION_TRANSACTION_LOCK:
        job, point = _class_analysis_review_point_for_mutation(job_id, point_id)
        result = {
            "summary": {
                **dict(getattr(job, "summary", None) or {}),
                "analysis_job_id": str(job.job_id or job_id or ""),
            }
        }
        current_review_object_key = str(point.get("review_object_key") or "").strip()
        if str(point.get("pair_review_key") or "").strip():
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail=f"overlap_pair_requires_pair_action:{point_id}",
            )
        stored_point = dict(point)
        if disposition == "reassign_class":
            target_class = str(target_class_name or "").strip()
            if not target_class:
                labelmap = [
                    str(value)
                    for value in ((result.get("summary") or {}).get("labelmap") or [])
                ]
                try:
                    target_class = labelmap[int(target_class_id)]
                except (IndexError, TypeError, ValueError) as exc:
                    raise HTTPException(
                        status_code=HTTP_409_CONFLICT,
                        detail=f"review_reassignment_target_unknown:{point_id}",
                    ) from exc
            stored_point.update(
                {
                    "review_object_key": _class_analysis_review_reassignment_key(
                        current_review_object_key,
                        str(job_id),
                    ),
                    "source_review_object_key": current_review_object_key,
                    "review_target_class": target_class,
                }
            )
        _class_analysis_preflight_review_action_tombstone(
            str(stored_point.get("review_object_key") or ""),
            client_action_id,
        )
        entry = _class_analysis_record_review_disposition_entry(
            result=result,
            point=stored_point,
            disposition=disposition,
            origin="desktop",
            client_action_id=client_action_id,
            training_capture_requested=False,
        )
        response = {
            "schema": CLASS_ANALYSIS_REVIEW_DISPOSITION_RECEIPT_SCHEMA,
            "status": "recorded",
            "job_id": str(job_id),
            "point_id": str(point_id),
            "review_object_key": str(entry["review_object_key"]),
            "disposition": disposition,
            "human_reviewed_at": entry["updated_at"],
            "human_review_revision": entry["entry_revision"],
            "origin": entry["origin"],
            "client_action_id": client_action_id,
            "training_capture_requested": False,
            "idempotent_replay": bool(entry.get("_idempotent_replay")),
        }
        if disposition == "reassign_class":
            response["target_class"] = str(entry.get("target_class") or "")
        if capture_training_data:
            response["_training_capture_context"] = {
                "kind": "review",
                "job_id": str(job_id),
                "point_id": str(point_id),
                "payload": {
                    "capture_training_data": True,
                    "origin": "desktop",
                    "client_action_id": client_action_id,
                    "_training_authorization": training_authorization,
                    "action_type": (
                        "change_class" if disposition == "reassign_class" else "delete_bbox"
                    ),
                    "point_id": str(point_id),
                    "before_class": str(point.get("class_name") or ""),
                    "after_class": (
                        str(response.get("target_class") or "")
                        if disposition == "reassign_class"
                        else str(point.get("class_name") or "")
                    ),
                    "label_commit_status": "committed",
                },
            }
    _class_analysis_sync_review_receipt_to_session(job_id, point_id, response)
    return _class_analysis_finalize_review_training_capture(response)


def commit_class_analysis_annotation_transaction(
    job_id: str,
    payload: Dict[str, Any],
):
    """Run one revision-safe annotation transaction through durable stages."""

    from services.annotation_entities import (
        AnnotationEntityError,
        AnnotationRevisionConflict,
        apply_annotation_entity_actions,
        canonical_label_line,
        live_label_lines,
    )

    client_action_id = str(payload.get("client_action_id") or "").strip()
    if not client_action_id:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_transaction_client_action_id_required",
        )
    source = payload.get("annotation_source")
    records = payload.get("records")
    if not isinstance(source, dict):
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_transaction_source_required",
        )
    if not isinstance(records, list) or not records:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_transaction_records_required",
        )
    source_kind = str(source.get("kind") or "").strip().lower()
    source_id = str(source.get("id") or "").strip()
    if not source_id:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_transaction_source_required",
        )

    job = _get_class_analysis_job(job_id)
    store = _class_analysis_annotation_entity_store()
    with _CLASS_ANALYSIS_ANNOTATION_ENTITY_LOCK:
        try:
            binding = store.claim_source_job(
                source_kind,
                source_id,
                str(job_id),
                source_descriptor=source,
            )
        except ValueError as exc:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail={
                    "code": str(exc),
                    "source_mode": source_kind,
                    "source_id": source_id,
                },
            ) from exc
    binding_generation = int(binding.get("binding_generation") or 0)
    canonical_request = {
        "job_id": str(job_id),
        "client_action_id": client_action_id,
        "annotation_source": {"kind": source_kind, "id": source_id},
        "binding_generation": binding_generation,
        "records": records,
    }
    journal_request = {
        **canonical_request,
        "transaction_kind": "annotation_entity_actions_v1",
    }
    request_hash = store.request_hash(canonical_request)

    with _CLASS_ANALYSIS_ANNOTATION_ENTITY_LOCK:
        try:
            store.assert_source_generation(
                source_kind,
                source_id,
                str(job_id),
                binding_generation,
            )
        except ValueError as exc:
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail={"code": str(exc), "binding_generation": binding_generation},
            ) from exc
        try:
            operation = store.get_operation(client_action_id, request_hash=request_hash)
        except ValueError as exc:
            raise HTTPException(status_code=HTTP_409_CONFLICT, detail=str(exc)) from exc
        if operation is not None and str(operation.get("state")) == "complete":
            return _class_analysis_annotation_operation_public(operation)
        if operation is not None and str(operation.get("state")) in {"conflict", "rejected"}:
            public_operation = _class_analysis_annotation_operation_public(operation)
            raise HTTPException(
                status_code=HTTP_409_CONFLICT,
                detail={
                    "code": "annotation_transaction_conflict",
                    "operation": public_operation,
                    "mutation_committed": bool(
                        public_operation.get("mutation_committed")
                    ),
                    "rerun_required": bool(public_operation.get("rerun_required")),
                },
            )

        source_snapshot = _class_analysis_annotation_transaction_snapshot(
            source_kind,
            source_id,
            records,
        )
        rows_by_key = dict(source_snapshot.get("rows_by_key") or {})
        manifest_labelmap = [
            str(value) for value in (source_snapshot.get("labelmap") or [])
        ]
        analysis_labelmap = [
            str(value)
            for value in (dict(getattr(job, "summary", None) or {}).get("labelmap") or [])
        ]
        source_session_revision = source_snapshot.get("session_revision")

        if operation is None:
            planned_records: list[Dict[str, Any]] = []
            action_results: list[Dict[str, Any]] = []
            source_identities: set[str] = set()
            seen_image_keys: set[str] = set()
            seen_point_ids: set[str] = set()
            review_shard_cache: Dict[str, Any] = {}
            try:
                for requested in records:
                    if not isinstance(requested, dict):
                        raise HTTPException(
                            status_code=HTTP_400_BAD_REQUEST,
                            detail="annotation_transaction_record_invalid",
                        )
                    image_key = _class_analysis_annotation_image_key(requested)
                    if image_key in seen_image_keys:
                        raise HTTPException(
                            status_code=HTTP_400_BAD_REQUEST,
                            detail=f"annotation_transaction_duplicate_record:{image_key}",
                        )
                    seen_image_keys.add(image_key)
                    current_row = rows_by_key.get(image_key)
                    if current_row is None:
                        raise HTTPException(
                            status_code=HTTP_409_CONFLICT,
                            detail=f"annotation_transaction_image_missing:{image_key}",
                        )
                    source_identity = str(
                        requested.get("annotation_source_identity")
                        or current_row.get("annotation_source_identity")
                        or ""
                    ).strip()
                    if not source_identity or source_identity != str(
                        current_row.get("annotation_source_identity") or ""
                    ):
                        raise HTTPException(
                            status_code=HTTP_409_CONFLICT,
                            detail=f"annotation_transaction_source_changed:{image_key}",
                        )
                    source_identities.add(source_identity)
                    current_label_revision = str(
                        current_row.get("annotation_record_revision") or ""
                    )
                    expected_label_revision = requested.get(
                        "expected_annotation_record_revision"
                    )
                    if expected_label_revision is None:
                        raise HTTPException(
                            status_code=HTTP_409_CONFLICT,
                            detail=f"annotation_transaction_label_revision_required:{image_key}",
                        )
                    if str(expected_label_revision) != current_label_revision:
                        raise HTTPException(
                            status_code=HTTP_409_CONFLICT,
                            detail=f"annotation_transaction_label_revision_changed:{image_key}",
                        )
                    record = store.get_record(source_identity, image_key)
                    if record is None:
                        raise HTTPException(
                            status_code=HTTP_409_CONFLICT,
                            detail=f"annotation_entity_rerun_required:{image_key}",
                        )
                    stored_record_revision = str(
                        record.get("record_revision") or ""
                    ).strip()
                    manifest_entity_record_revision = str(
                        current_row.get("annotation_entity_record_revision") or ""
                    ).strip()
                    if (
                        not stored_record_revision
                        or not manifest_entity_record_revision
                        or manifest_entity_record_revision != stored_record_revision
                    ):
                        raise HTTPException(
                            status_code=HTTP_409_CONFLICT,
                            detail=f"annotation_entity_sidecar_out_of_sync:{image_key}",
                        )
                    requested_record_revision = requested.get("expected_record_revision")
                    actions = requested.get("actions")
                    if not isinstance(actions, list) or not actions:
                        raise HTTPException(
                            status_code=HTTP_400_BAD_REQUEST,
                            detail=f"annotation_transaction_actions_required:{image_key}",
                        )
                    authoritative_actions: list[Dict[str, Any]] = []
                    for raw_action in actions:
                        if not isinstance(raw_action, dict):
                            raise HTTPException(
                                status_code=HTTP_400_BAD_REQUEST,
                                detail="annotation_transaction_action_invalid",
                            )
                        point_id = str(raw_action.get("point_id") or "").strip()
                        if not point_id:
                            raise HTTPException(
                                status_code=HTTP_400_BAD_REQUEST,
                                detail="annotation_transaction_point_id_required",
                            )
                        if point_id in seen_point_ids:
                            raise HTTPException(
                                status_code=HTTP_400_BAD_REQUEST,
                                detail=f"annotation_transaction_duplicate_point:{point_id}",
                            )
                        seen_point_ids.add(point_id)
                        _, point = _class_analysis_review_point_for_mutation(job_id, point_id)
                        if (
                            bool(point.get("reviewed"))
                            or bool(
                                str(
                                    point.get("human_review_disposition")
                                    or point.get("review_disposition")
                                    or ""
                                ).strip()
                            )
                            or _class_analysis_row_has_review_disposition(
                                point,
                                job_id,
                                review_shard_cache,
                            )
                        ):
                            raise HTTPException(
                                status_code=HTTP_409_CONFLICT,
                                detail={
                                    "code": "review_disposition_changed",
                                    "point_id": point_id,
                                    "review_object_key": str(
                                        point.get("review_object_key") or ""
                                    ),
                                    "message": (
                                        "Restore the saved review decision before "
                                        "editing this annotation."
                                    ),
                                },
                            )
                        if str(point.get("pair_review_key") or "").strip():
                            raise HTTPException(
                                status_code=HTTP_409_CONFLICT,
                                detail=f"overlap_pair_requires_pair_action:{point_id}",
                            )
                        point_image = str(
                            point.get("image_relpath")
                            or point.get("image_name")
                            or point.get("frontend_image_key")
                            or ""
                        ).replace("\\", "/")
                        requested_image = str(
                            requested.get("image_relpath")
                            or requested.get("image_name")
                            or ""
                        ).replace("\\", "/")
                        point_split = str(point.get("split") or "").strip()
                        requested_split = str(requested.get("split") or "").strip()
                        if point_split and requested_split and point_split != requested_split:
                            raise HTTPException(
                                status_code=HTTP_409_CONFLICT,
                                detail=f"annotation_transaction_point_split_changed:{point_id}",
                            )
                        if requested_image and point_image and not point_image.endswith(requested_image):
                            raise HTTPException(
                                status_code=HTTP_409_CONFLICT,
                                detail=f"annotation_transaction_point_image_changed:{point_id}",
                            )
                        authoritative_action = _class_analysis_resolve_transaction_entity(
                                job_id=job_id,
                                point=point,
                                current_row=current_row,
                                image_key=image_key,
                                source_identity=source_identity,
                                record=record,
                                requested_action=raw_action,
                                store=store,
                            )
                        if str(authoritative_action.get("action") or "") == "relabel":
                            try:
                                target_value = float(
                                    str(authoritative_action.get("target_class_id"))
                                )
                            except (TypeError, ValueError) as exc:
                                raise HTTPException(
                                    status_code=HTTP_400_BAD_REQUEST,
                                    detail=f"annotation_transaction_target_class_invalid:{point_id}",
                                ) from exc
                            if not manifest_labelmap:
                                raise HTTPException(
                                    status_code=HTTP_409_CONFLICT,
                                    detail={
                                        "code": "annotation_source_labelmap_unavailable",
                                        "message": "The current annotation source has no authoritative label map.",
                                        "point_ids": [point_id],
                                        "image_keys": [image_key],
                                    },
                                )
                            if (
                                not math.isfinite(target_value)
                                or not target_value.is_integer()
                                or not 0 <= int(target_value) < len(manifest_labelmap)
                            ):
                                raise HTTPException(
                                    status_code=HTTP_400_BAD_REQUEST,
                                    detail=f"annotation_transaction_target_class_invalid:{point_id}",
                                )
                            target_index = int(target_value)
                            if (
                                analysis_labelmap
                                and (
                                    target_index >= len(analysis_labelmap)
                                    or analysis_labelmap[target_index]
                                    != manifest_labelmap[target_index]
                                )
                            ):
                                raise HTTPException(
                                    status_code=HTTP_409_CONFLICT,
                                    detail={
                                        "code": "annotation_source_labelmap_changed",
                                        "message": "The current dataset class map no longer matches this analysis.",
                                        "point_ids": [point_id],
                                        "image_keys": [image_key],
                                    },
                                )
                            authoritative_action["target_class_id"] = target_index
                        authoritative_actions.append(authoritative_action)
                    effective_record_revision = str(
                        authoritative_actions[0].get("expected_record_revision") or ""
                    )
                    if (
                        any(
                            str(action.get("identity_status") or "") != "legacy_exact"
                            for action in authoritative_actions
                        )
                        and requested_record_revision is None
                    ):
                        raise HTTPException(
                            status_code=HTTP_409_CONFLICT,
                            detail=f"annotation_entity_record_revision_required:{image_key}",
                        )
                    if requested_record_revision is not None and str(
                        requested_record_revision
                    ) != effective_record_revision:
                        raise HTTPException(
                            status_code=HTTP_409_CONFLICT,
                            detail=f"annotation_entity_record_revision_changed:{image_key}",
                        )
                    try:
                        updated, results = apply_annotation_entity_actions(
                            record,
                            authoritative_actions,
                            expected_record_revision=effective_record_revision,
                        )
                    except AnnotationRevisionConflict as exc:
                        raise HTTPException(
                            status_code=HTTP_409_CONFLICT, detail=str(exc)
                        ) from exc
                    except AnnotationEntityError as exc:
                        raise HTTPException(
                            status_code=HTTP_400_BAD_REQUEST, detail=str(exc)
                        ) from exc
                    split, relpath = image_key.split(":", 1)
                    before_lines = [
                        canonical_label_line(line)
                        for line in (current_row.get("label_lines") or [])
                        if canonical_label_line(line)
                    ]
                    after_lines = live_label_lines(updated)
                    planned_records.append(
                        {
                            "annotation_source_identity": source_identity,
                            "image_key": image_key,
                            "split": split,
                            "image_relpath": relpath,
                            "before_label_lines": before_lines,
                            "after_label_lines": after_lines,
                            "updated_record": updated,
                        }
                    )
                    action_results.extend(
                        {
                            **dict(result),
                            "point_id": str(authoritative_actions[index]["point_id"]),
                            "split": split,
                            "image_relpath": relpath,
                            "target_class_id": authoritative_actions[index].get(
                                "target_class_id"
                            ),
                            "target_class_name": (
                                manifest_labelmap[
                                    int(float(str(authoritative_actions[index]["target_class_id"])))
                                ]
                                if str(authoritative_actions[index].get("action") or "")
                                == "relabel"
                                and 0
                                <= int(float(str(authoritative_actions[index]["target_class_id"])))
                                < len(manifest_labelmap)
                                else ""
                            ),
                            "capture_training_data": bool(
                                authoritative_actions[index].get(
                                    "capture_training_data"
                                )
                            ),
                        }
                        for index, result in enumerate(results)
                    )
            except HTTPException:
                raise
            plan = {
                "records": planned_records,
                "actions": action_results,
                "annotation_source": {"kind": source_kind, "id": source_id},
            }
            initial_response = {
                "job_id": str(job_id),
                "client_action_id": client_action_id,
                "annotation_source": {"kind": source_kind, "id": source_id},
                "plan": plan,
                "actions": action_results,
                "review_receipts": [],
                "review_pending": [],
            }
            try:
                operation = store.begin_operation(
                    operation_id=client_action_id,
                    request_hash=request_hash,
                    request=journal_request,
                    job_id=str(job_id),
                    source_identity="|".join(sorted(source_identities)),
                    response=initial_response,
                    source_mode=source_kind,
                    source_id=source_id,
                    binding_generation=binding_generation,
                    transaction_kind="annotation_entity_actions_v1",
                )
            except ValueError as exc:
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT, detail=str(exc)
                ) from exc

        response = dict(operation.get("response") or {})
        plan = dict(response.get("plan") or {})
        planned_records = [
            dict(item) for item in (plan.get("records") or []) if isinstance(item, dict)
        ]
        action_results = [
            dict(item) for item in (plan.get("actions") or []) if isinstance(item, dict)
        ]
        state = str(operation.get("state") or "prepared")
        if state == "prepared":
            current_states: list[str] = []
            for planned in planned_records:
                row = rows_by_key.get(str(planned.get("image_key") or ""))
                current_lines = [
                    canonical_label_line(line)
                    for line in ((row or {}).get("label_lines") or [])
                    if canonical_label_line(line)
                ]
                if current_lines == list(planned.get("before_label_lines") or []):
                    current_states.append("before")
                elif current_lines == list(planned.get("after_label_lines") or []):
                    current_states.append("after")
                else:
                    current_states.append("conflict")
            if "conflict" in current_states:
                conflict_detail = _class_analysis_annotation_transaction_conflict_detail(
                    planned_records,
                    current_states,
                    action_results,
                )
                operation = store.advance_operation(
                    client_action_id,
                    "conflict",
                    response=response,
                    error=conflict_detail,
                )
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=conflict_detail,
                )
            records_to_save = [
                planned
                for planned, current_state in zip(planned_records, current_states)
                if current_state == "before"
            ]
            annotation_snapshot = dict(response.get("annotation_snapshot") or {})
            annotation_snapshot_records = {
                _class_analysis_annotation_image_key(item): dict(item)
                for item in (annotation_snapshot.get("records") or [])
                if isinstance(item, dict)
            }
            for planned, current_state in zip(planned_records, current_states):
                if current_state != "after":
                    continue
                image_key = str(planned.get("image_key") or "")
                row = rows_by_key.get(image_key) or {}
                annotation_snapshot_records[image_key] = {
                    "split": planned["split"],
                    "image_relpath": planned["image_relpath"],
                    "annotation_source_identity": str(
                        row.get("annotation_source_identity")
                        or planned.get("annotation_source_identity")
                        or ""
                    ),
                    "annotation_record_revision": str(
                        row.get("annotation_record_revision") or ""
                    ),
                }
            if records_to_save:
                save_payload = dict(payload.get("annotation_save") or {})
                current_session_revision = source_session_revision
                if current_session_revision is not None:
                    save_payload["expected_session_revision"] = int(
                        current_session_revision
                    )
                save_payload["records"] = [
                    {
                        "split": planned["split"],
                        "image_relpath": planned["image_relpath"],
                        "label_lines": list(planned.get("after_label_lines") or []),
                    }
                    for planned in records_to_save
                ]
                saved_snapshot = dict(
                    _class_analysis_annotation_transaction_save(
                        source_kind, source_id, save_payload
                    )
                )
                annotation_snapshot.update(saved_snapshot)
                for item in saved_snapshot.get("records") or []:
                    if isinstance(item, dict):
                        annotation_snapshot_records[
                            _class_analysis_annotation_image_key(item)
                        ] = dict(item)
            elif source_session_revision is not None:
                annotation_snapshot["session_revision"] = int(
                    source_session_revision
                )
            annotation_snapshot["records"] = [
                annotation_snapshot_records[str(planned.get("image_key") or "")]
                for planned in planned_records
                if str(planned.get("image_key") or "")
                in annotation_snapshot_records
            ]
            response["annotation_snapshot"] = annotation_snapshot
            operation = store.advance_operation(
                client_action_id,
                "annotation_committed",
                response=response,
            )
            state = "annotation_committed"

        if state == "annotation_committed":
            with store.transaction() as connection:
                for planned in planned_records:
                    store.put_record(
                        str(planned["annotation_source_identity"]),
                        str(planned["image_key"]),
                        dict(planned["updated_record"]),
                        connection=connection,
                    )
            operation = store.advance_operation(
                client_action_id,
                "entity_committed",
                response=response,
            )
            state = "entity_committed"

        if state in {"entity_committed", "recovery_required"}:
            review_receipts: list[Dict[str, Any]] = []
            review_pending: list[Dict[str, Any]] = []
            review_failures: list[Dict[str, Any]] = []
            for index, result in enumerate(action_results):
                point_id = str(result.get("point_id") or "")
                disposition = (
                    "delete_bbox"
                    if str(result.get("action") or "") == "delete"
                    else "reassign_class"
                )
                review_action_id = "aer:" + hashlib.sha256(
                    f"{client_action_id}\0{index}\0{point_id}".encode("utf-8")
                ).hexdigest()[:32]
                try:
                    review_receipts.append(
                        _class_analysis_record_entity_transaction_review(
                            job_id=job_id,
                            point_id=point_id,
                            action=str(result.get("action") or ""),
                            target_class_id=result.get("target_class_id"),
                            target_class_name=str(
                                result.get("target_class_name") or ""
                            ),
                            client_action_id=review_action_id,
                            capture_training_data=bool(
                                result.get("capture_training_data")
                            ),
                            training_authorization=payload.get(
                                "_training_authorization"
                            ),
                        )
                    )
                except HTTPException as exc:
                    conflict_code = (
                        str(exc.detail.get("code") or "")
                        if isinstance(exc.detail, Mapping)
                        else str(exc.detail or "")
                    )
                    if (
                        exc.status_code == HTTP_409_CONFLICT
                        and conflict_code
                        in {
                            "review_disposition_changed",
                            "review_disposition_client_action_conflict",
                        }
                    ):
                        review_receipts.append(
                            {
                                "status": "superseded_by_newer_review",
                                "point_id": point_id,
                                "detail": exc.detail,
                            }
                        )
                        continue
                    if int(exc.status_code) in {408, 425, 429} or int(exc.status_code) >= 500:
                        review_pending.append(
                            {"point_id": point_id, "reason": str(exc.detail)}
                        )
                    else:
                        review_failures.append(
                            {
                                "point_id": point_id,
                                "status_code": int(exc.status_code),
                                "reason": str(exc.detail),
                            }
                        )
                except Exception as exc:
                    review_pending.append(
                        {"point_id": point_id, "reason": str(exc)}
                    )
            response["review_receipts"] = review_receipts
            response["review_pending"] = review_pending
            response["review_failures"] = review_failures
            response["records"] = [
                {
                    "annotation_source_identity": planned["annotation_source_identity"],
                    "image_key": planned["image_key"],
                    "record_revision": planned["updated_record"]["record_revision"],
                    "annotation_record_revision": str(
                        next(
                            (
                                item.get("annotation_record_revision")
                                for item in (
                                    response.get("annotation_snapshot", {}).get("records")
                                    or []
                                )
                                if isinstance(item, Mapping)
                                and _class_analysis_annotation_image_key(item)
                                == planned["image_key"]
                            ),
                            "",
                        )
                        or ""
                    ),
                    "label_lines": list(planned.get("after_label_lines") or []),
                    "annotation_entities": [
                        dict(entity)
                        for entity in planned["updated_record"].get("entities", [])
                        if isinstance(entity, dict) and not bool(entity.get("deleted"))
                    ],
                }
                for planned in planned_records
            ]
            if review_pending:
                operation = store.advance_operation(
                    client_action_id,
                    "recovery_required",
                    response=response,
                    error={"detail": "annotation_review_receipts_pending"},
                )
                return _class_analysis_annotation_operation_public(operation)
            operation = store.advance_operation(
                client_action_id,
                "review_committed",
                response=response,
            )
            state = "review_committed"

        if state == "review_committed":
            operation = store.advance_operation(
                client_action_id,
                "complete",
                response=response,
            )
        return _class_analysis_annotation_operation_public(operation)


_CLASS_ANALYSIS_ANNOTATION_BATCH_UPLOAD_LIMIT = 500
_CLASS_ANALYSIS_ANNOTATION_BATCH_RECORD_LIMIT = 100
_CLASS_ANALYSIS_ANNOTATION_BATCH_ACTION_LIMIT = 500


def _class_analysis_annotation_batch_for_job(
    job_id: str, batch_id: str
) -> tuple[Any, Dict[str, Any]]:
    store = _class_analysis_annotation_entity_store()
    batch = store.get_batch(str(batch_id))
    if batch is None or str(batch.get("job_id") or "") != str(job_id):
        raise HTTPException(
            status_code=HTTP_404_NOT_FOUND,
            detail="annotation_batch_not_found",
        )
    try:
        store.assert_source_generation(
            str(batch.get("source_mode") or ""),
            str(batch.get("source_id") or ""),
            str(job_id),
            int(batch.get("binding_generation") or 0),
        )
    except ValueError as exc:
        raise HTTPException(
            status_code=HTTP_409_CONFLICT,
            detail={"code": str(exc), "batch_id": str(batch_id)},
        ) from exc
    return store, dict(batch)


def _class_analysis_annotation_batch_public(batch: Mapping[str, Any]) -> Dict[str, Any]:
    counts = {
        str(key): int(value)
        for key, value in dict(batch.get("counts") or {}).items()
    }
    succeeded = counts.get("complete", 0)
    failed = counts.get("failed", 0)
    conflicted = counts.get("conflict", 0)
    cancelled = counts.get("cancelled", 0)
    settled = succeeded + failed + conflicted + cancelled
    declared = int(batch.get("declared_count") or 0)
    return {
        "batch_id": str(batch.get("batch_id") or ""),
        "job_id": str(batch.get("job_id") or ""),
        "source_mode": str(batch.get("source_mode") or ""),
        "source_id": str(batch.get("source_id") or ""),
        "binding_generation": int(batch.get("binding_generation") or 0),
        "action": str(batch.get("action") or ""),
        "target_class_name": str(batch.get("target_class_name") or ""),
        "declared_count": declared,
        "state": str(batch.get("state") or "draft"),
        "counts": counts,
        "completed_count": settled,
        "settled_count": settled,
        "succeeded_count": succeeded,
        "failed_count": failed,
        "conflict_count": conflicted,
        "cancelled_count": cancelled,
        "progress": (settled / declared) if declared else 0.0,
        "active_operation_id": str(batch.get("active_operation_id") or ""),
        "error": dict(batch.get("error") or {}),
    }


def create_class_analysis_annotation_batch(job_id: str, payload: Dict[str, Any]):
    _get_class_analysis_job(job_id)
    batch_id = str(payload.get("batch_id") or "").strip()
    source = payload.get("annotation_source")
    action = str(payload.get("action") or "").strip().lower()
    target_class_name = str(payload.get("target_class_name") or "").strip()
    declared_count = int(payload.get("declared_count") or 0)
    manifest_hash = str(payload.get("manifest_hash") or "").strip().lower()
    if not batch_id or not isinstance(source, Mapping):
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_batch_identity_required",
        )
    source_mode = str(source.get("kind") or "").strip().lower()
    source_id = str(source.get("id") or "").strip()
    if action not in {"delete", "relabel"} or not source_mode or not source_id:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_batch_request_invalid",
        )
    if action == "relabel" and not target_class_name:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_batch_target_class_required",
        )
    if declared_count < 1 or declared_count > 1_000_000 or len(manifest_hash) != 64:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_batch_manifest_invalid",
        )
    store = _class_analysis_annotation_entity_store()
    try:
        binding = store.claim_source_job(
            source_mode,
            source_id,
            str(job_id),
            source_descriptor=source,
        )
        batch = store.create_batch(
            batch_id=batch_id,
            job_id=str(job_id),
            source_mode=source_mode,
            source_id=source_id,
            binding_generation=int(binding.get("binding_generation") or 0),
            action=action,
            target_class_name=target_class_name,
            declared_count=declared_count,
            manifest_hash=manifest_hash,
        )
    except ValueError as exc:
        raise HTTPException(status_code=HTTP_409_CONFLICT, detail=str(exc)) from exc
    return _class_analysis_annotation_batch_public(batch)


def append_class_analysis_annotation_batch_items(
    job_id: str, batch_id: str, payload: Dict[str, Any]
):
    store, _ = _class_analysis_annotation_batch_for_job(job_id, batch_id)
    items = payload.get("items")
    if not isinstance(items, list) or not items or len(items) > _CLASS_ANALYSIS_ANNOTATION_BATCH_UPLOAD_LIMIT:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_batch_page_invalid",
        )
    try:
        batch = store.append_batch_items(str(batch_id), items)
    except (KeyError, ValueError) as exc:
        raise HTTPException(status_code=HTTP_409_CONFLICT, detail=str(exc)) from exc
    return _class_analysis_annotation_batch_public(batch)


def start_class_analysis_annotation_batch(job_id: str, batch_id: str):
    store, _ = _class_analysis_annotation_batch_for_job(job_id, batch_id)
    try:
        batch = store.start_batch(str(batch_id))
    except (KeyError, ValueError) as exc:
        raise HTTPException(status_code=HTTP_409_CONFLICT, detail=str(exc)) from exc
    return _class_analysis_annotation_batch_public(batch)


def _class_analysis_annotation_batch_conflict_items(
    selected: list[Dict[str, Any]],
    detail: Any,
) -> list[Dict[str, Any]]:
    """Locate exact batch rows from structured or exact-suffix conflict data."""

    image_items: Dict[str, Dict[str, Any]] = {}
    point_items: Dict[str, Dict[str, Any]] = {}
    for item in selected:
        record = item.get("payload")
        if not isinstance(record, Mapping):
            continue
        try:
            image_items[_class_analysis_annotation_image_key(dict(record))] = item
        except HTTPException:
            pass
        for action in (record.get("actions") or []):
            if not isinstance(action, Mapping):
                continue
            point_id = str(action.get("point_id") or "").strip()
            if point_id:
                point_items[point_id] = item

    image_keys: set[str] = set()
    point_ids: set[str] = set()
    if isinstance(detail, Mapping):
        image_keys.update(
            str(value or "").strip()
            for value in (detail.get("image_keys") or [])
            if str(value or "").strip()
        )
        point_ids.update(
            str(value or "").strip()
            for value in (detail.get("point_ids") or [])
            if str(value or "").strip()
        )
        if str(detail.get("image_key") or "").strip():
            image_keys.add(str(detail.get("image_key") or "").strip())
        if str(detail.get("point_id") or "").strip():
            point_ids.add(str(detail.get("point_id") or "").strip())
    else:
        _code, separator, identifier = str(detail or "").partition(":")
        if separator:
            if identifier in image_items:
                image_keys.add(identifier)
            if identifier in point_items:
                point_ids.add(identifier)

    matched_by_sequence: Dict[int, Dict[str, Any]] = {}
    for image_key in image_keys:
        item = image_items.get(image_key)
        if item is not None:
            matched_by_sequence[int(item.get("sequence") or 0)] = item
    for point_id in point_ids:
        item = point_items.get(point_id)
        if item is not None:
            matched_by_sequence[int(item.get("sequence") or 0)] = item
    return [matched_by_sequence[key] for key in sorted(matched_by_sequence)]


def _class_analysis_annotation_batch_error_detail(
    selected: list[Dict[str, Any]],
    detail: Any,
) -> Dict[str, Any]:
    """Normalize transaction errors without fuzzy identifier matching."""

    if isinstance(detail, Mapping):
        normalized = dict(detail)
        code = str(normalized.get("code") or "annotation_transaction_conflict")
        message = str(
            normalized.get("message")
            or normalized.get("detail")
            or code
        )
    else:
        message = str(detail or "annotation_transaction_conflict")
        code = message.partition(":")[0] or "annotation_transaction_conflict"
        normalized = {"code": code, "message": message}
    matched = _class_analysis_annotation_batch_conflict_items(selected, detail)
    image_keys: list[str] = []
    point_ids: list[str] = []
    for item in matched:
        record = item.get("payload")
        if not isinstance(record, Mapping):
            continue
        try:
            image_keys.append(_class_analysis_annotation_image_key(dict(record)))
        except HTTPException:
            pass
        point_ids.extend(
            str(action.get("point_id") or "").strip()
            for action in (record.get("actions") or [])
            if isinstance(action, Mapping)
            and str(action.get("point_id") or "").strip()
        )
    return {
        **normalized,
        "code": code,
        "message": message,
        "detail": message,
        "image_keys": sorted(set(image_keys)),
        "point_ids": sorted(set(point_ids)),
    }


def process_class_analysis_annotation_batch(
    job_id: str, batch_id: str, payload: Dict[str, Any]
):
    store, batch = _class_analysis_annotation_batch_for_job(job_id, batch_id)
    if str(batch.get("state") or "") in {"complete", "cancelled"}:
        return _class_analysis_annotation_batch_public(batch)
    candidates = store.get_batch_items(
        str(batch_id),
        states=("pending", "recovery_required"),
        limit=_CLASS_ANALYSIS_ANNOTATION_BATCH_RECORD_LIMIT,
    )
    selected: list[Dict[str, Any]] = []
    action_count = 0
    for item in candidates:
        record = item.get("payload")
        actions = record.get("actions") if isinstance(record, Mapping) else None
        if not isinstance(record, Mapping) or not isinstance(actions, list) or not actions:
            store.settle_batch_items(
                str(batch_id),
                [{
                    "sequence": int(item.get("sequence") or 0),
                    "state": "failed",
                    "error": {"detail": "annotation_batch_record_invalid"},
                }],
            )
            continue
        if len(actions) > _CLASS_ANALYSIS_ANNOTATION_BATCH_ACTION_LIMIT:
            store.settle_batch_items(
                str(batch_id),
                [{
                    "sequence": int(item.get("sequence") or 0),
                    "state": "failed",
                    "error": {"detail": "annotation_batch_record_too_large"},
                }],
            )
            continue
        if selected and action_count + len(actions) > _CLASS_ANALYSIS_ANNOTATION_BATCH_ACTION_LIMIT:
            break
        selected.append(dict(item))
        action_count += len(actions)
    if not selected:
        refreshed = store.get_batch(str(batch_id)) or batch
        return _class_analysis_annotation_batch_public(refreshed)
    sequences = [int(item.get("sequence") or 0) for item in selected]
    operation_id = "annotation-batch-chunk:" + hashlib.sha256(
        (str(batch_id) + ":" + ",".join(str(value) for value in sequences)).encode("utf-8")
    ).hexdigest()[:32]
    request = {
        "client_action_id": operation_id,
        "annotation_source": {
            "kind": str(batch.get("source_mode") or ""),
            "id": str(batch.get("source_id") or ""),
        },
        "records": [dict(item.get("payload") or {}) for item in selected],
        "annotation_save": dict(payload.get("annotation_save") or {}),
        **(
            {"_training_authorization": payload.get("_training_authorization")}
            if payload.get("_training_authorization") is not None
            else {}
        ),
    }
    try:
        receipt = commit_class_analysis_annotation_transaction(job_id, request)
    except HTTPException as exc:
        retryable = int(exc.status_code) in {408, 425, 429} or int(exc.status_code) >= 500
        error_detail = _class_analysis_annotation_batch_error_detail(
            selected,
            exc.detail,
        )
        rejected_items = selected
        if not retryable and len(selected) > 1:
            matched_items = _class_analysis_annotation_batch_conflict_items(
                selected,
                error_detail,
            )
            if matched_items:
                # Transaction validation is atomic. Settle only the row named by
                # the conflict and leave unrelated rows pending for the next pass.
                rejected_items = matched_items
        batch = store.settle_batch_items(
            str(batch_id),
            [
                {
                    "sequence": int(item.get("sequence") or 0),
                    "state": "recovery_required" if retryable else "conflict",
                    "operation_id": operation_id,
                    "error": {"status_code": int(exc.status_code), **error_detail},
                }
                for item in rejected_items
            ],
            active_operation_id=operation_id,
        )
        return {
            **_class_analysis_annotation_batch_public(batch),
            "chunk_error": {"status_code": int(exc.status_code), **error_detail},
            "chunk_conflict_sequences": [
                int(item.get("sequence") or 0) for item in rejected_items
            ],
        }
    complete = str(receipt.get("status") or "") == "complete"
    receipt_actions = [
        dict(item) for item in (receipt.get("actions") or []) if isinstance(item, Mapping)
    ]
    receipt_records = [
        dict(item) for item in (receipt.get("records") or []) if isinstance(item, Mapping)
    ]
    snapshot_records = [
        dict(item)
        for item in ((receipt.get("annotation_snapshot") or {}).get("records") or [])
        if isinstance(item, Mapping)
    ]
    updates = []
    for item in selected:
        record = dict(item.get("payload") or {})
        point_ids = {
            str(action.get("point_id") or "")
            for action in (record.get("actions") or [])
            if isinstance(action, Mapping)
        }
        image_key = _class_analysis_annotation_image_key(record)
        result = {
            "status": str(receipt.get("status") or ""),
            "client_action_id": operation_id,
            "actions": [action for action in receipt_actions if str(action.get("point_id") or "") in point_ids],
            "records": [row for row in receipt_records if str(row.get("image_key") or "") == image_key],
            "annotation_snapshot": {
                "session_revision": (receipt.get("annotation_snapshot") or {}).get("session_revision"),
                "records": [row for row in snapshot_records if _class_analysis_annotation_image_key(row) == image_key],
            },
            "review_receipts": [
                row for row in (receipt.get("review_receipts") or [])
                if isinstance(row, Mapping) and str(row.get("point_id") or "") in point_ids
            ],
            "review_failures": [
                row for row in (receipt.get("review_failures") or [])
                if isinstance(row, Mapping) and str(row.get("point_id") or "") in point_ids
            ],
        }
        updates.append(
            {
                "sequence": int(item.get("sequence") or 0),
                "state": "complete" if complete else "recovery_required",
                "operation_id": operation_id,
                "result": result,
            }
        )
    batch = store.settle_batch_items(
        str(batch_id), updates, active_operation_id=operation_id
    )
    return {
        **_class_analysis_annotation_batch_public(batch),
        "chunk_receipt": receipt,
        "chunk_sequences": sequences,
    }


def get_class_analysis_annotation_batch(job_id: str, batch_id: str):
    _, batch = _class_analysis_annotation_batch_for_job(job_id, batch_id)
    return _class_analysis_annotation_batch_public(batch)


def get_class_analysis_annotation_batch_results(
    job_id: str, batch_id: str, after_sequence: int, limit: int
):
    store, batch = _class_analysis_annotation_batch_for_job(job_id, batch_id)
    items = store.get_batch_items(
        str(batch_id),
        limit=max(1, min(int(limit), _CLASS_ANALYSIS_ANNOTATION_BATCH_UPLOAD_LIMIT)),
        after_sequence=int(after_sequence),
    )
    return {
        **_class_analysis_annotation_batch_public(batch),
        "items": items,
        "next_after_sequence": int(items[-1]["sequence"]) if items else None,
    }


def retry_class_analysis_annotation_batch(
    job_id: str, batch_id: str, payload: Dict[str, Any]
):
    store, _ = _class_analysis_annotation_batch_for_job(job_id, batch_id)
    sequences = payload.get("sequences")
    if sequences is not None and not isinstance(sequences, list):
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="annotation_batch_retry_invalid")
    try:
        batch = store.retry_batch_items(str(batch_id), sequences)
    except (KeyError, ValueError) as exc:
        raise HTTPException(status_code=HTTP_409_CONFLICT, detail=str(exc)) from exc
    return _class_analysis_annotation_batch_public(batch)


def cancel_class_analysis_annotation_batch(job_id: str, batch_id: str):
    store, _ = _class_analysis_annotation_batch_for_job(job_id, batch_id)
    try:
        batch = store.cancel_batch(str(batch_id))
    except KeyError as exc:
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="annotation_batch_not_found") from exc
    return _class_analysis_annotation_batch_public(batch)


def get_class_analysis_annotation_transaction(job_id: str, operation_id: str):
    operation = _class_analysis_annotation_entity_store().get_operation(operation_id)
    if operation is None or str(operation.get("job_id") or "") != str(job_id):
        raise HTTPException(status_code=HTTP_404_NOT_FOUND, detail="annotation_transaction_not_found")
    return _class_analysis_annotation_operation_public(operation)


def _class_analysis_annotation_recovery_snapshot(job_id: str) -> Dict[str, Any]:
    """Report each persistence mechanism independently.

    A stale entity is a local terminal result. Only source-generation or frozen
    source-identity conflicts invalidate the whole analysis.
    """

    store = _class_analysis_annotation_entity_store()
    checkpoint_loader = getattr(store, "list_checkpoint_operations", None)
    if callable(checkpoint_loader):
        all_operations = checkpoint_loader(job_id=str(job_id))
    else:
        try:
            all_operations = store.list_operations(
                job_id=str(job_id), include_terminal=True
            )
        except TypeError:
            all_operations = store.list_operations(job_id=str(job_id))
    public_operations = [
        _class_analysis_annotation_operation_public(operation)
        for operation in all_operations
    ]
    annotation_pending = []
    review_retry = []
    local_terminal = []
    legacy_unrecoverable = []
    for operation, public in zip(all_operations, public_operations):
        state = str(operation.get("state") or "")
        status = str(operation.get("status") or state)
        phase = str(operation.get("phase") or state)
        terminal = status in {
            "complete",
            "rejected",
            "conflict",
            "superseded",
            "legacy_unrecoverable",
        } or state in {"complete", "rejected", "conflict"}
        if status == "legacy_unrecoverable":
            legacy_unrecoverable.append(public)
        elif terminal and status != "complete":
            local_terminal.append(public)
        elif bool(operation.get("retryable")) and public.get("mutation_committed"):
            review_retry.append(public)
        elif not terminal and phase in {"prepared", "annotation_commit"}:
            annotation_pending.append(public)
        elif not terminal:
            review_retry.append(public)

    active_batches = [
        _class_analysis_annotation_batch_public(batch)
        for batch in store.list_active_batches(str(job_id))
    ]
    source_identities = set(store.list_job_sources(str(job_id)))
    source_identities.update(
        identity
        for operation in all_operations
        for identity in str(operation.get("source_identity") or "").split("|")
        if identity
    )
    identity_errors: list[str] = []
    identity_summary: Dict[str, Any] = {
        "identity_conflict_count": 0,
        "invalid_identity_count": 0,
        "source_identities": [],
    }
    try:
        identity_summary = get_class_analysis_session_identity_summary(
            _class_analysis_session_store_path(str(job_id))
        )
        session_sources = list(identity_summary.get("source_identities") or [])
        source_identities.update(session_sources)
        store.bind_job_sources(str(job_id), session_sources)
    except HTTPException as exc:
        if exc.detail != "class_analysis_job_id_invalid":
            raise
    except (OSError, SessionStoreError) as exc:
        identity_errors.append(str(exc))

    conflicts = [
        conflict
        for identity in sorted(source_identities)
        for conflict in store.list_conflicts(identity)
    ]
    frozen_identity_conflict_count = int(
        identity_summary.get("identity_conflict_count") or 0
    )
    frozen_identity_invalid_count = int(
        identity_summary.get("invalid_identity_count") or 0
    )
    source_invalid = bool(
        conflicts
        or identity_errors
        or frozen_identity_conflict_count
        or frozen_identity_invalid_count
    )
    annotation_blocked = bool(annotation_pending or active_batches)
    review_blocked = bool(review_retry)
    if source_invalid:
        status = "rerun_required"
    elif annotation_blocked or review_blocked:
        status = "recovery_required"
    elif local_terminal or legacy_unrecoverable:
        status = "ready_with_warnings"
    else:
        status = "ready"

    reason_codes = []
    if conflicts:
        reason_codes.append("annotation_identity_conflict")
    if frozen_identity_conflict_count:
        reason_codes.append("frozen_annotation_identity_conflict")
    if frozen_identity_invalid_count:
        reason_codes.append("frozen_annotation_identity_invalid")
    if identity_errors:
        reason_codes.append("session_store_identity_invalid")
    if annotation_pending:
        reason_codes.append("annotation_commit_pending")
    if review_retry:
        reason_codes.append("review_receipt_retry_pending")
    if active_batches:
        reason_codes.append("annotation_batch_pending")
    if local_terminal:
        reason_codes.append("entity_local_terminal_failures")
    if legacy_unrecoverable:
        reason_codes.append("legacy_transaction_unrecoverable")

    checkpoint_ready = not source_invalid and not annotation_blocked and not review_blocked
    export_ready = not source_invalid and not annotation_blocked
    return {
        "job_id": str(job_id),
        "status": status,
        "operations": annotation_pending + review_retry,
        "annotation_pending_operations": annotation_pending,
        "review_retry_operations": review_retry,
        "terminal_operations": local_terminal,
        "legacy_unrecoverable_operations": legacy_unrecoverable,
        "active_batches": active_batches,
        "conflicts": conflicts,
        "operation_count": len(annotation_pending) + len(review_retry),
        "annotation_pending_count": len(annotation_pending),
        "review_retry_count": len(review_retry),
        "terminal_operation_count": len(local_terminal),
        "legacy_unrecoverable_count": len(legacy_unrecoverable),
        "active_batch_count": len(active_batches),
        "identity_conflict_count": (
            len(conflicts)
            + len(identity_errors)
            + frozen_identity_conflict_count
            + frozen_identity_invalid_count
        ),
        "frozen_identity_conflict_count": frozen_identity_conflict_count,
        "frozen_identity_invalid_count": frozen_identity_invalid_count,
        "validated_session_store_schema": identity_summary.get("schema"),
        "affected_source_identities": sorted(source_identities),
        "reason_codes": reason_codes,
        "identity_errors": identity_errors,
        "rerun_required": source_invalid,
        "checkpoint_ready": checkpoint_ready,
        "can_save_session": checkpoint_ready,
        "can_export_dataset": export_ready,
        "recovery_modes": (
            ["retry_transactions"] if annotation_pending or review_retry else []
        ),
        "persistence_profiles": {
            "confirm_current": "entity_revision",
            "mark_resolved": "entity_revision",
            "skip": "analysis_generation",
        },
        "note": (
            "The bound annotation source changed; rerun this analysis before editing."
            if source_invalid
            else "Pending annotation writes, review receipts, and batches are reported separately. Local stale-object failures do not invalidate unrelated objects."
        ),
    }


def get_class_analysis_annotation_recovery(job_id: str):
    return _class_analysis_annotation_recovery_snapshot(job_id)


def recover_class_analysis_annotation_session(job_id: str, payload: Dict[str, Any]):
    _get_class_analysis_job(job_id)
    if str(payload.get("mode") or "") != "retry_transactions":
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail="annotation_recovery_mode_invalid",
        )
    requested_ids = {
        str(value)
        for value in (payload.get("operation_ids") or [])
        if str(value).strip()
    }
    store = _class_analysis_annotation_entity_store()
    operations = store.list_operations(job_id=str(job_id))
    annotation_save = payload.get("annotation_save")
    if operations and (
        not isinstance(annotation_save, Mapping)
        or not str(
            annotation_save.get("lock_session_id")
            or annotation_save.get("session_id")
            or ""
        ).strip()
        or not str(annotation_save.get("lock_token") or "").strip()
    ):
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail={
                "code": "annotation_recovery_fresh_lease_required",
                "message": "Recovery requires a fresh annotation-save lease.",
            },
        )
    results = []
    failures = []
    for operation in operations:
        operation_id = str(operation.get("operation_id") or "")
        if requested_ids and operation_id not in requested_ids:
            continue
        request = dict(operation.get("request") or {})
        request["annotation_save"] = dict(annotation_save or {})
        try:
            transaction_kind = str(
                request.get("transaction_kind")
                or "annotation_entity_actions_v1"
            )
            if transaction_kind == "dual_bbox_delete_v1":
                annotation_save = request.pop("annotation_save", {})
                if isinstance(annotation_save, Mapping):
                    for key in ("session_id", "lock_session_id", "lock_token"):
                        if annotation_save.get(key) is not None:
                            request[key] = annotation_save.get(key)
                results.append(
                    commit_class_analysis_dual_bbox_annotation_transaction(
                        job_id,
                        str(request.get("point_id") or ""),
                        request,
                    )
                )
            elif transaction_kind == "annotation_entity_actions_v1":
                results.append(
                    commit_class_analysis_annotation_transaction(
                        job_id,
                        request,
                    )
                )
            else:
                raise HTTPException(
                    status_code=HTTP_409_CONFLICT,
                    detail=f"annotation_transaction_kind_unknown:{transaction_kind}",
                )
        except HTTPException as exc:
            failures.append(
                {
                    "client_action_id": operation_id,
                    "status_code": int(exc.status_code),
                    "detail": exc.detail,
                }
            )
        except Exception as exc:
            failures.append(
                {
                    "client_action_id": operation_id,
                    "status_code": HTTP_500_INTERNAL_SERVER_ERROR,
                    "detail": str(exc),
                }
            )
    snapshot = _class_analysis_annotation_recovery_snapshot(job_id)
    if failures and snapshot["status"] == "ready":
        snapshot.update({"status": "recovery_required", "checkpoint_ready": False})
    return {
        **snapshot,
        "results": results,
        "remaining": list(snapshot.get("operations") or []),
        "failures": failures,
        "labels_changed": bool(results),
    }


