def sam3_text_prompt(payload: Sam3TextPrompt):
    variant = _default_variant(payload.sam_variant or "sam3")
    if variant != "sam3":
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="sam3_text_requires_sam3")
    pil_img, np_img, token = resolve_image_payload(
        payload.image_base64, payload.image_token, variant
    )
    effective_limit = payload.max_results
    warnings: List[str] = []
    if payload.windowed:
        detections, masks_arr, window_warnings = _run_sam3_text_windowed_inference(
            pil_img,
            payload.text_prompt,
            payload.threshold,
            payload.mask_threshold,
            effective_limit,
            window_size=payload.window_size,
            window_overlap=payload.window_overlap,
            merge_iou=payload.merge_iou,
            min_size=payload.min_size,
            simplify_epsilon=payload.simplify_epsilon,
        )
        warnings.extend(window_warnings)
    else:
        detections, masks_arr = _run_sam3_text_inference(
            pil_img,
            payload.text_prompt,
            payload.threshold,
            payload.mask_threshold,
            effective_limit,
            return_masks=True,
            min_size=payload.min_size,
            simplify_epsilon=payload.simplify_epsilon,
        )
    if not detections:
        warnings.append("no_results")
    encoded_masks = None
    if detections:
        encoded_masks = []
        for idx, det in enumerate(detections):
            mask_payload = det.mask if isinstance(det, QwenDetection) else None
            if (
                mask_payload is None
                and masks_arr is not None
                and idx < len(masks_arr)
                and masks_arr[idx] is not None
            ):
                try:
                    mask_payload = _encode_binary_mask_impl(
                        masks_arr[idx], max_bytes=MASK_ENCODE_MAX_BYTES
                    )
                except Exception:
                    mask_payload = None
            encoded_masks.append(mask_payload)
        if all(m is None for m in encoded_masks):
            encoded_masks = None
    return Sam3TextPromptResponse(
        detections=detections,
        warnings=warnings,
        image_token=token,
        masks=encoded_masks,
    )


def sam3_text_prompt_auto(payload: Sam3TextPrompt):
    variant = _default_variant(payload.sam_variant or "sam3")
    if variant != "sam3":
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="sam3_text_requires_sam3")
    if not _active_encoder_ready():
        return Sam3TextPromptAutoResponse(
            detections=[],
            warnings=["clip_unavailable"],
            image_token=None,
        )
    pil_img, np_img, token = resolve_image_payload(
        payload.image_base64, payload.image_token, variant
    )
    effective_limit = payload.max_results
    responses: List[SamPointAutoResponse] = []
    warnings: List[str] = []
    if payload.windowed:
        detections, masks_arr, window_warnings = _run_sam3_text_windowed_inference(
            pil_img,
            payload.text_prompt,
            payload.threshold,
            payload.mask_threshold,
            effective_limit,
            window_size=payload.window_size,
            window_overlap=payload.window_overlap,
            merge_iou=payload.merge_iou,
            min_size=payload.min_size,
            simplify_epsilon=payload.simplify_epsilon,
        )
        warnings.extend(window_warnings)
    else:
        detections, masks_arr = _run_sam3_text_inference(
            pil_img,
            payload.text_prompt,
            payload.threshold,
            payload.mask_threshold,
            effective_limit,
            return_masks=True,
            min_size=payload.min_size,
            simplify_epsilon=payload.simplify_epsilon,
        )
    if not detections:
        warnings.append("no_results")
    for idx, det in enumerate(detections):
        mask = masks_arr[idx] if masks_arr is not None and idx < len(masks_arr) else None
        mask_payload = det.mask if hasattr(det, "mask") else None
        if mask_payload is None and mask is not None:
            mask_payload = _encode_binary_mask_impl(mask, max_bytes=MASK_ENCODE_MAX_BYTES)
        if mask is not None:
            try:
                x_min, y_min, x_max, y_max = _mask_to_bounding_box(mask)
            except Exception:
                x_min, y_min, x_max, y_max = _yolo_to_xyxy_int(
                    pil_img.width, pil_img.height, det.bbox
                )
        else:
            x_min, y_min, x_max, y_max = _yolo_to_xyxy_int(pil_img.width, pil_img.height, det.bbox)
        li = max(0, int(x_min))
        ti = max(0, int(y_min))
        ri = min(pil_img.width, int(x_max))
        bi = min(pil_img.height, int(y_max))
        if ri <= li or bi <= ti:
            responses.append(
                SamPointAutoResponse(
                    prediction="unknown",
                    bbox=det.bbox,
                    uuid=str(uuid.uuid4()),
                    error="empty_mask",
                    image_token=token,
                    score=det.score,
                    mask=mask_payload,
                    simplify_epsilon=getattr(det, "simplify_epsilon", None),
                )
            )
            continue
        feats_np = _encode_classifier_xyxy_for_active(pil_img, [x_min, y_min, x_max, y_max])
        if feats_np is None or not isinstance(feats_np, np.ndarray) or feats_np.size == 0:
            responses.append(
                SamPointAutoResponse(
                    prediction="unknown",
                    bbox=det.bbox,
                    uuid=str(uuid.uuid4()),
                    error="clip_unavailable",
                    image_token=token,
                    score=det.score,
                    mask=mask_payload,
                    simplify_epsilon=getattr(det, "simplify_epsilon", None),
                )
            )
            continue
        details = _clip_auto_predict_details(feats_np)
        err = details.get("error")
        if isinstance(err, str) and err.startswith("classifier_error") and err not in warnings:
            warnings.append(err)
        responses.append(
            SamPointAutoResponse(
                prediction=str(details.get("label") or "unknown"),
                proba=details.get("proba"),
                second_label=details.get("second_label"),
                second_proba=details.get("second_proba"),
                margin=details.get("margin"),
                bbox=det.bbox,
                uuid=str(uuid.uuid4()),
                image_token=token,
                score=det.score,
                mask=mask_payload,
                simplify_epsilon=getattr(det, "simplify_epsilon", None),
                error=err,
            )
        )
    return Sam3TextPromptAutoResponse(detections=responses, warnings=warnings, image_token=token)


def sam3_visual_prompt(payload: Sam3VisualPrompt):
    variant = _default_variant(payload.sam_variant or "sam3")
    if variant != "sam3":
        raise HTTPException(status_code=HTTP_400_BAD_REQUEST, detail="sam3_visual_requires_sam3")
    pil_img, np_img, token = resolve_image_payload(
        payload.image_base64, payload.image_token, variant
    )
    effective_limit = payload.max_results
    try:
        if payload.bboxes:
            detections, masks_arr = _run_sam3_visual_inference_multi(
                pil_img,
                [tuple(bx) for bx in payload.bboxes],
                payload.bbox_labels,
                payload.threshold,
                payload.mask_threshold,
                effective_limit,
                return_masks=True,
                min_size=payload.min_size,
                simplify_epsilon=payload.simplify_epsilon,
                text_prompt=payload.text_prompt,
            )
        else:
            detections, masks_arr = _run_sam3_visual_inference(
                pil_img,
                (
                    float(payload.bbox_left),
                    float(payload.bbox_top),
                    float(payload.bbox_width),
                    float(payload.bbox_height),
                ),
                payload.threshold,
                payload.mask_threshold,
                effective_limit,
                return_masks=True,
                min_size=payload.min_size,
                simplify_epsilon=payload.simplify_epsilon,
                text_prompt=payload.text_prompt,
            )
    except HTTPException:
        raise
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(
            status_code=HTTP_500_INTERNAL_SERVER_ERROR, detail=f"sam3_visual_failed:{exc}"
        ) from exc
    warnings: List[str] = []
    if not detections:
        warnings.append("no_results")
    encoded_masks = None
    if detections:
        encoded_masks = []
        for idx, det in enumerate(detections):
            payload_mask = det.mask if isinstance(det, QwenDetection) else None
            if (
                payload_mask is None
                and masks_arr is not None
                and idx < len(masks_arr)
                and masks_arr[idx] is not None
            ):
                try:
                    payload_mask = _encode_binary_mask_impl(
                        masks_arr[idx], max_bytes=MASK_ENCODE_MAX_BYTES
                    )
                except Exception:
                    payload_mask = None
            encoded_masks.append(payload_mask)
        if all(m is None for m in encoded_masks):
            encoded_masks = None
    return Sam3TextPromptResponse(
        detections=detections,
        warnings=warnings,
        image_token=token,
        masks=encoded_masks,
    )


