def _stabilize_local_sam_bbox_mask(
    mask: np.ndarray,
    *,
    left: float,
    top: float,
    right: float,
    bottom: float,
) -> np.ndarray:
    """Keep a Magic Tweak mask local and anchored to its source bbox.

    Interactive SAM masks can contain a remote positive island (or one large
    connected region) whose global extent would corrupt an otherwise local
    bbox refinement. Limit refinement to a half-box margin and retain the
    connected component with the strongest support inside the original box.
    """
    import cv2

    binary = (np.asarray(mask) > 0).astype(np.uint8, copy=False)
    if binary.ndim != 2:
        raise ValueError(f"sam_local_refine_mask_shape_invalid:{binary.shape}")
    height, width = binary.shape
    box_width = max(1.0, float(right) - float(left))
    box_height = max(1.0, float(bottom) - float(top))
    margin_x = max(16.0, box_width * 0.5)
    margin_y = max(16.0, box_height * 0.5)
    window_left = max(0, int(math.floor(float(left) - margin_x)))
    window_top = max(0, int(math.floor(float(top) - margin_y)))
    window_right = min(width, int(math.ceil(float(right) + margin_x)))
    window_bottom = min(height, int(math.ceil(float(bottom) + margin_y)))
    stabilized = np.zeros_like(binary)
    if window_right <= window_left or window_bottom <= window_top:
        return stabilized

    window = np.ascontiguousarray(
        binary[window_top:window_bottom, window_left:window_right]
    )
    component_count, component_labels, _, _ = cv2.connectedComponentsWithStats(
        window,
        connectivity=8,
    )
    if component_count <= 1:
        return stabilized

    support_left = max(window_left, int(math.floor(float(left)))) - window_left
    support_top = max(window_top, int(math.floor(float(top)))) - window_top
    support_right = min(window_right, int(math.ceil(float(right)))) - window_left
    support_bottom = min(window_bottom, int(math.ceil(float(bottom)))) - window_top
    if support_right <= support_left or support_bottom <= support_top:
        return stabilized
    support_labels = component_labels[
        support_top:support_bottom,
        support_left:support_right,
    ]
    support_counts = np.bincount(
        support_labels.reshape(-1),
        minlength=component_count,
    )
    support_counts[0] = 0
    selected_label = int(np.argmax(support_counts))
    if support_counts[selected_label] <= 0:
        return stabilized

    stabilized[window_top:window_bottom, window_left:window_right] = (
        component_labels == selected_label
    ).astype(np.uint8)
    return stabilized


def sam_bbox_auto(prompt: BboxPrompt):
    if not _active_encoder_ready():
        return SamPointAutoResponse(prediction=str(ERROR_MESSAGE), bbox=[], uuid=prompt.uuid)

    pil_img, np_img, token = resolve_image_payload(
        prompt.image_base64,
        getattr(prompt, "image_token", None),
        getattr(prompt, "sam_variant", None),
    )
    full_h, full_w = pil_img.height, pil_img.width
    raw_left = float(prompt.bbox_left)
    raw_top = float(prompt.bbox_top)
    left = max(0.0, min(float(full_w), raw_left))
    top = max(0.0, min(float(full_h), raw_top))
    right = max(0.0, min(float(full_w), raw_left + float(prompt.bbox_width)))
    bottom = max(0.0, min(float(full_h), raw_top + float(prompt.bbox_height)))
    if right <= left or bottom <= top:
        return SamPointAutoResponse(
            prediction="unknown",
            bbox=[0, 0, 0, 0],
            uuid=prompt.uuid,
            error="invalid_bbox",
            image_token=token,
        )
    sub_box = np.array([left, top, right, bottom], dtype=np.float32)
    variant = _default_variant(getattr(prompt, "sam_variant", None))
    masks, _, _ = _predict_with_cache(
        np_img,
        token,
        variant,
        image_name=getattr(prompt, "image_name", None),
        box=sub_box,
        multimask_output=False,
    )
    mask_arr = np.asarray(masks[0])
    if mask_arr.dtype != np.uint8:
        mask_arr = (mask_arr > 0).astype(np.uint8)
    if prompt.local_refine:
        mask_arr = _stabilize_local_sam_bbox_mask(
            mask_arr,
            left=left,
            top=top,
            right=right,
            bottom=bottom,
        )
        if not np.any(mask_arr):
            raise HTTPException(status_code=422, detail="sam_local_refine_missed_prompt")
    x_min, y_min, x_max, y_max = _mask_to_bounding_box(mask_arr)
    yolo_box = _xyxy_to_yolo_norm_list(full_w, full_h, x_min, y_min, x_max, y_max)
    gx_min_i = max(0, int(x_min))
    gy_min_i = max(0, int(y_min))
    gx_max_i = min(full_w, int(x_max))
    gy_max_i = min(full_h, int(y_max))
    if gx_max_i <= gx_min_i or gy_max_i <= gy_min_i:
        return SamPointAutoResponse(
            prediction="unknown",
            bbox=yolo_box,
            uuid=prompt.uuid,
            error="empty_mask",
            image_token=token,
        )
    feats_np = _encode_classifier_xyxy_for_active(pil_img, [x_min, y_min, x_max, y_max])
    if feats_np is None or not isinstance(feats_np, np.ndarray) or feats_np.size == 0:
        return SamPointAutoResponse(
            prediction="unknown",
            bbox=yolo_box,
            uuid=prompt.uuid,
            error="clip_unavailable",
            image_token=token,
        )
    details = _clip_auto_predict_details(feats_np)
    return SamPointAutoResponse(
        prediction=str(details.get("label") or "unknown"),
        proba=details.get("proba"),
        second_label=details.get("second_label"),
        second_proba=details.get("second_proba"),
        margin=details.get("margin"),
        bbox=yolo_box,
        uuid=prompt.uuid,
        image_token=token,
        mask=_encode_binary_mask_impl(mask_arr, max_bytes=MASK_ENCODE_MAX_BYTES),
        simplify_epsilon=None,
        error=details.get("error"),
    )


