def crop_zip_init():
    jobId = str(uuid.uuid4())
    job_store[jobId] = []
    return {"jobId": jobId}


def crop_zip_chunk(request: CropZipRequest, jobId: str = Query(...)):
    if jobId not in job_store:
        raise HTTPException(status_code=400, detail="Invalid jobId")
    job_store[jobId].extend(request.images)
    return {"status": "ok", "count": len(request.images)}


def _safe_crop_zip_component(value: Optional[str], fallback: str) -> str:
    raw = Path(str(value or fallback)).name
    cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", raw).strip("._-")
    return cleaned or fallback


def _unique_crop_zip_member_name(base_name: str, used_names: Set[str]) -> str:
    candidate = str(base_name or "crop.jpg")
    if candidate not in used_names:
        used_names.add(candidate)
        return candidate
    stem = Path(candidate).stem or "crop"
    suffix = Path(candidate).suffix or ".jpg"
    counter = 2
    while True:
        candidate_next = f"{stem}-dup{counter}{suffix}"
        if candidate_next not in used_names:
            used_names.add(candidate_next)
            return candidate_next
        counter += 1


def crop_zip_finalize(jobId: str):
    if jobId not in job_store:
        raise HTTPException(status_code=400, detail="Invalid jobId")
    all_images = job_store[jobId]
    try:
        if len(all_images) == 0:
            empty_buffer = io.BytesIO()
            with zipfile.ZipFile(empty_buffer, mode="w") as zf:
                pass
            empty_buffer.seek(0)
            return StreamingResponse(
                empty_buffer,
                media_type="application/x-zip-compressed",
                headers={"Content-Disposition": "attachment; filename=crops.zip"},
            )
        zip_buffer = io.BytesIO()
        used_names: Set[str] = set()
        with zipfile.ZipFile(zip_buffer, mode="w", compression=zipfile.ZIP_DEFLATED) as zf:
            for img_index, cropImage in enumerate(all_images):
                pil_img, _ = _decode_image_base64_impl(
                    cropImage.image_base64,
                    max_bytes=BASE64_IMAGE_MAX_BYTES,
                    max_dim=BASE64_IMAGE_MAX_DIM,
                    allow_downscale=True,
                )
                stem = _safe_crop_zip_component(
                    Path(cropImage.originalName or "").stem, f"image_{img_index}"
                )
                for bindex, bbox in enumerate(cropImage.bboxes):
                    left = bbox.x
                    top = bbox.y
                    right = left + bbox.width
                    bottom = top + bbox.height
                    left = max(0, min(left, pil_img.width))
                    right = max(0, min(right, pil_img.width))
                    top = max(0, min(top, pil_img.height))
                    bottom = max(0, min(bottom, pil_img.height))
                    if right <= left or bottom <= top:
                        continue
                    sub_img = pil_img.crop((left, top, right, bottom))
                    class_name = _safe_crop_zip_component(bbox.className, "class")
                    out_name = f"{stem}-{class_name}-{bindex}.jpg"
                    out_name = _unique_crop_zip_member_name(out_name, used_names)
                    crop_buffer = io.BytesIO()
                    sub_img.save(crop_buffer, format="JPEG")
                    crop_buffer.seek(0)
                    zf.writestr(out_name, crop_buffer.read())
        zip_buffer.seek(0)
        return StreamingResponse(
            zip_buffer,
            media_type="application/x-zip-compressed",
            headers={"Content-Disposition": "attachment; filename=crops.zip"},
        )
    finally:
        job_store.pop(jobId, None)


app.include_router(
    build_crop_zip_router(
        init_fn=crop_zip_init,
        chunk_fn=crop_zip_chunk,
        finalize_fn=crop_zip_finalize,
        request_cls=CropZipRequest,
    )
)


def _serve_tator_ui() -> FileResponse:
    if not TATOR_UI_INDEX.exists() or not TATOR_UI_INDEX.is_file():
        raise HTTPException(status_code=404, detail="tator_ui_not_found")
    return FileResponse(str(TATOR_UI_INDEX), media_type="text/html")


@app.head("/", include_in_schema=False)
@app.get("/", include_in_schema=False)
def serve_tator_root() -> FileResponse:
    return _serve_tator_ui()


@app.head("/tator.html", include_in_schema=False)
@app.get("/tator.html", include_in_schema=False)
def serve_tator_html() -> FileResponse:
    return _serve_tator_ui()


@app.head("/ybat.html", include_in_schema=False)
@app.get("/ybat.html", include_in_schema=False)
def serve_legacy_ybat_html() -> RedirectResponse:
    return RedirectResponse(url="/tator.html", status_code=307)


@app.head("/{asset_name}", include_in_schema=False)
@app.get("/{asset_name}", include_in_schema=False)
def serve_tator_ui_asset(asset_name: str) -> FileResponse:
    safe_name = Path(str(asset_name or "")).name
    if safe_name != asset_name or safe_name not in TATOR_UI_ASSETS:
        raise HTTPException(status_code=404, detail="ui_asset_not_found")
    asset_path = TATOR_UI_DIR / safe_name
    if not asset_path.exists() or not asset_path.is_file():
        raise HTTPException(status_code=404, detail="ui_asset_not_found")
    return FileResponse(str(asset_path))


